/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2012_SEED = {"dse/writing/part-b/2012/Q2":[{"front":"virtual sports","meaning":"虛擬運動","examples":[{"en":"Virtual sports can help beginners start moving.","zh":"虛擬運動可以幫助初學者開始活動身體。"},{"en":"Virtual sports are games or activities that use screens, controllers, sensors, or digital systems to copy sports movements.","zh":"虛擬運動，是使用螢幕、控制器、感應器或數碼系統來模仿運動動作的遊戲或活動。"},{"en":"A student may play virtual tennis at home before feeling ready to try real tennis.","zh":"學生可能先在家玩虛擬網球，才覺得準備好嘗試真正網球。"},{"en":"Virtual sports can make exercise feel less frightening because players can practise privately.","zh":"虛擬運動可以令運動感覺沒那麼可怕，因為玩家可以私下練習。"},{"en":"Virtual sports are useful as a starting point, but they should not replace all real movement.","zh":"虛擬運動作為起點很有用，但不應取代所有真實活動。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"open the door","meaning":"打開大門；帶來開始","examples":[{"en":"Virtual sports can open the door to fitness.","zh":"虛擬運動可以為健身打開大門。"},{"en":"To open the door to something means to create the first chance to begin it.","zh":"為某事打開大門，意思是創造開始它的第一個機會。"},{"en":"A friendly school club can open the door to music for nervous beginners.","zh":"友善的學校學會可以為緊張的初學者打開音樂的大門。"},{"en":"A small first step can open the door to a healthier habit.","zh":"一個小小的第一步可以為更健康的習慣帶來開始。"},{"en":"Virtual sports open the door to fitness by making movement easier to start.","zh":"虛擬運動透過令活動身體更容易開始，為健身打開大門。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"real sports keep us moving","meaning":"真實運動令我們持續活動","examples":[{"en":"Virtual sports can open the door, but real sports keep us moving.","zh":"虛擬運動可以打開大門，但真實運動令我們持續活動。"},{"en":"Real sports keep us moving means physical sports help people continue active exercise over time.","zh":"真實運動令我們持續活動，意思是實體運動幫助人們長時間保持活躍鍛煉。"},{"en":"A fitness app may start a habit, but football practice can keep students moving every week.","zh":"健身應用程式可能開始一個習慣，但足球練習可以令學生每星期持續活動。"},{"en":"Real sports keep people moving because they involve teammates, spaces, goals, and routines.","zh":"真實運動令人在持續活動，因為它涉及隊友、場地、目標和規律。"},{"en":"The sentence shows that virtual sports can begin fitness, while real sports deepen it.","zh":"這句話顯示，虛擬運動可以開始健身，而真實運動則令它更深入。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"follow this debate with interest","meaning":"饒有興趣地關注這場辯論","examples":[{"en":"Chris has been following this debate with interest.","zh":"Chris 一直饒有興趣地關注這場辯論。"},{"en":"To follow a debate with interest means to pay attention to an argument because it seems important or engaging.","zh":"饒有興趣地關注一場辯論，意思是因為論題重要或吸引而留意相關爭論。"},{"en":"A student may follow a debate about school uniforms with interest.","zh":"學生可能饒有興趣地關注關於校服的辯論。"},{"en":"People follow debates with interest when the issue affects their daily lives.","zh":"當議題影響日常生活，人們會饒有興趣地關注辯論。"},{"en":"Chris follows the virtual sports debate because it connects technology, health, and young people.","zh":"Chris 關注虛擬運動的辯論，因為它連繫科技、健康和年輕人。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"ask the wrong question","meaning":"問錯問題","examples":[{"en":"He thinks people are asking the wrong question.","zh":"他認為人們問錯問題。"},{"en":"To ask the wrong question means to focus on an issue that is not the most important one.","zh":"問錯問題，意思是集中於不是最重要的議題。"},{"en":"If students only ask whether homework is easy, they may be asking the wrong question.","zh":"如果學生只問功課是否容易，他們可能問錯問題。"},{"en":"Sometimes the better question is not what is popular, but what is useful.","zh":"有時更好的問題不是甚麼受歡迎，而是甚麼有用。"},{"en":"The writer thinks the debate should focus on health, not only whether virtual sports are “real.”","zh":"作者認為這場辯論應集中於健康，而不只是虛擬運動是否「真實」。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"the issue is not whether...it is whether...","meaning":"問題不在於……而在於……","examples":[{"en":"The issue is not whether virtual sports are real, but whether they improve health.","zh":"問題不在於虛擬運動是否真實，而在於它們是否改善健康。"},{"en":"The issue is not whether A, but whether B shifts attention from a less important question to the real one.","zh":"問題不在於 A，而在於 B，會把注意力由較不重要的問題轉向真正問題。"},{"en":"The issue is not whether students like revision, but whether revision helps them learn.","zh":"問題不在於學生是否喜歡溫習，而在於溫習是否幫助他們學習。"},{"en":"This structure helps writers correct the focus of a debate.","zh":"這個結構幫助作者修正辯論焦點。"},{"en":"Here, the real issue is not realism itself, but lasting health benefits.","zh":"在這裏，真正問題不是真實感本身，而是持久的健康好處。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"Wii tennis","meaning":"Wii 網球","examples":[{"en":"Wii tennis is used as an example of virtual sports.","zh":"Wii 網球被用作虛擬運動的例子。"},{"en":"Wii tennis is a video game that lets players imitate tennis movements with a controller.","zh":"Wii 網球是一款讓玩家用控制器模仿網球動作的電子遊戲。"},{"en":"A beginner may enjoy Wii tennis before trying a real racket and court.","zh":"初學者可能先享受 Wii 網球，然後才嘗試真正球拍和球場。"},{"en":"Wii tennis can encourage movement, but it does not require the same full-body effort as real tennis.","zh":"Wii 網球可以鼓勵活動身體，但它不需要與真正網球相同的全身努力。"},{"en":"The writer uses Wii tennis to show both the value and limits of virtual sport.","zh":"作者使用 Wii 網球來顯示虛擬運動的價值和限制。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"real enough to deserve respect","meaning":"真實到值得尊重","examples":[{"en":"Some people ask whether virtual sports are real enough to deserve respect.","zh":"有些人問虛擬運動是否真實到值得尊重。"},{"en":"Real enough to deserve respect means sufficiently genuine or serious to be valued.","zh":"真實到值得尊重，意思是足夠真實或認真，值得被重視。"},{"en":"Online learning may be real enough to deserve respect if students work hard and improve.","zh":"如果學生努力學習並有進步，網上學習也可以真實到值得尊重。"},{"en":"People often ask this when a new activity does not look like the traditional version.","zh":"當一項新活動看起來不像傳統版本，人們常會問這個問題。"},{"en":"The writer says the better question is not respect, but whether virtual sports improve health.","zh":"作者說更好的問題不是尊重，而是虛擬運動是否改善健康。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"improve our health","meaning":"改善我們的健康","examples":[{"en":"The real question is whether virtual sports can improve our health.","zh":"真正問題是虛擬運動能否改善我們的健康。"},{"en":"To improve our health means to make our bodies or minds stronger, safer, or more active.","zh":"改善我們的健康，意思是令身體或心理更強壯、更安全或更活躍。"},{"en":"Walking to school can improve our health if it becomes a regular habit.","zh":"如果步行上學成為恆常習慣，它可以改善我們的健康。"},{"en":"Exercise improves health best when people continue doing it over time.","zh":"當人們長期持續運動，運動最能改善健康。"},{"en":"Virtual sports may improve health if they help inactive people move more often.","zh":"如果虛擬運動幫助不活躍的人更常活動，它們可能改善健康。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"in a way that lasts","meaning":"以持久的方式","examples":[{"en":"Exercise should improve our health in a way that lasts.","zh":"運動應以持久的方式改善我們的健康。"},{"en":"In a way that lasts means with effects that continue over time, not only for one short moment.","zh":"以持久的方式，意思是效果會長時間延續，而不只是短暫一刻。"},{"en":"A study habit works best when it helps students improve in a way that lasts.","zh":"當學習習慣以持久方式幫助學生進步，它最有效。"},{"en":"Fitness gains disappear if exercise does not become a lasting routine.","zh":"如果運動沒有變成持久習慣，健身成果會消失。"},{"en":"The writer asks whether virtual sports can create health habits that last.","zh":"作者問虛擬運動能否創造持久的健康習慣。"}],"source":"2012 Q2.pdf","sourcePage":1},{"front":"spend long hours","meaning":"花長時間","examples":[{"en":"Many teenagers spend long hours revising, commuting and scrolling.","zh":"許多青少年花長時間溫習、通勤和滑手機。"},{"en":"To spend long hours doing something means to use a lot of time on it.","zh":"花長時間做某事，意思是把大量時間用在那件事上。"},{"en":"Students may spend long hours preparing for public exams.","zh":"學生可能花長時間準備公開考試。"},{"en":"Spending long hours sitting can reduce the time available for exercise.","zh":"長時間坐着會減少可用於運動的時間。"},{"en":"Virtual sports may help teenagers who spend long hours indoors begin to move.","zh":"虛擬運動可能幫助長時間留在室內的青少年開始活動。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"revising, commuting and scrolling","meaning":"溫習、通勤和滑手機","examples":[{"en":"Teenagers often spend long hours revising, commuting and scrolling.","zh":"青少年常花長時間溫習、通勤和滑手機。"},{"en":"Revising, commuting and scrolling means studying, travelling to and from places, and looking through phone content.","zh":"溫習、通勤和滑手機，意思是學習、往返不同地方，以及瀏覽手機內容。"},{"en":"A student may spend the morning revising, the afternoon commuting, and the evening scrolling.","zh":"學生可能早上溫習，下午通勤，晚上滑手機。"},{"en":"These habits can leave little time or energy for outdoor sport.","zh":"這些習慣可能令戶外運動的時間和精力變少。"},{"en":"The phrase describes a modern routine that makes easy exercise options attractive.","zh":"這個短語描述現代生活規律，令容易開始的運動選擇變得吸引。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"consider something as","meaning":"把……視為","examples":[{"en":"Some people consider virtual sports as a less intimidating form of exercise.","zh":"有些人把虛擬運動視為沒那麼令人卻步的運動形式。"},{"en":"To consider something as something else means to think of it in that way.","zh":"把某事視為另一事，意思是以那種方式看待它。"},{"en":"A shy student may consider drama as a way to build confidence.","zh":"害羞的學生可能把戲劇視為建立信心的方法。"},{"en":"How people consider an activity affects whether they are willing to try it.","zh":"人們如何看待一項活動，會影響他們是否願意嘗試。"},{"en":"Virtual sports can be considered as a gentle first step into fitness.","zh":"虛擬運動可以被視為進入健身的溫和第一步。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"less intimidating exercise","meaning":"沒那麼令人卻步的運動","examples":[{"en":"Virtual sports may be a less intimidating form of exercise.","zh":"虛擬運動可能是一種沒那麼令人卻步的運動形式。"},{"en":"Less intimidating exercise means exercise that feels less frightening, embarrassing, or difficult to begin.","zh":"沒那麼令人卻步的運動，意思是開始時感覺較不害怕、不尷尬或不困難的運動。"},{"en":"Walking with a friend can be less intimidating exercise than joining a competitive team.","zh":"與朋友散步可能比加入競爭性隊伍更不令人卻步。"},{"en":"Beginners often need less intimidating exercise before trying harder activities.","zh":"初學者常需要沒那麼令人卻步的運動，然後才嘗試更難活動。"},{"en":"Virtual sports feel less intimidating because players can practise at home.","zh":"虛擬運動感覺沒那麼令人卻步，因為玩家可以在家練習。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"would otherwise stay on the sofa","meaning":"否則只會留在梳化上","examples":[{"en":"Virtual sports can help people who would otherwise stay on the sofa.","zh":"虛擬運動可以幫助那些否則只會留在梳化上的人。"},{"en":"Would otherwise stay on the sofa means would probably remain inactive if this option did not exist.","zh":"否則只會留在梳化上，意思是如果沒有這個選擇，就很可能保持不活動。"},{"en":"A rainy-day dance game may help children who would otherwise stay on the sofa.","zh":"雨天跳舞遊戲可能幫助那些否則只會留在梳化上的孩子。"},{"en":"A small active game is better than doing nothing at all.","zh":"小小的活動遊戲比完全不動好。"},{"en":"Virtual sports matter because they reach people who might not choose real sport first.","zh":"虛擬運動重要，因為它接觸到未必首先選擇真實運動的人。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"start moving","meaning":"開始活動身體","examples":[{"en":"Virtual sports can encourage inactive people to start moving.","zh":"虛擬運動可以鼓勵不活躍的人開始活動身體。"},{"en":"To start moving means to begin using the body in an active way.","zh":"開始活動身體，意思是開始以活躍方式使用身體。"},{"en":"A student can start moving by stretching for ten minutes after homework.","zh":"學生可以在做完功課後伸展十分鐘，開始活動身體。"},{"en":"Starting to move is often the hardest step for inactive people.","zh":"對不活躍的人來說，開始活動通常是最難的一步。"},{"en":"Virtual sports help people start moving by making exercise feel like play.","zh":"虛擬運動透過令運動感覺像玩樂，幫助人開始活動身體。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, virtual sports are useful but limited.","zh":"就我而言，虛擬運動有用但有限。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"就我而言，意思是以我的看法或從我的角度來說。"},{"en":"As far as I am concerned, students should try both indoor and outdoor exercise.","zh":"就我而言，學生應嘗試室內和戶外運動。"},{"en":"Writers use this phrase to introduce a personal but serious judgement.","zh":"作者使用這個短語來引入個人但認真的判斷。"},{"en":"The writer uses it before giving a balanced view of virtual sports.","zh":"作者在提出對虛擬運動的平衡看法前使用它。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"a doorway into fitness","meaning":"進入健身的門口","examples":[{"en":"Virtual sports can act as a doorway into fitness.","zh":"虛擬運動可以作為進入健身的門口。"},{"en":"A doorway into fitness means an easy first entrance into exercise and healthy habits.","zh":"進入健身的門口，意思是開始運動和健康習慣的容易入口。"},{"en":"A short walking club can be a doorway into fitness for beginners.","zh":"短途步行小組可以成為初學者進入健身的門口。"},{"en":"Doorways matter because people are more likely to begin when the first step feels possible.","zh":"入口很重要，因為當第一步感覺可行，人們更可能開始。"},{"en":"Virtual sports act as a doorway into fitness by reducing fear and embarrassment.","zh":"虛擬運動透過減少恐懼和尷尬，作為進入健身的門口。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"be treated as a replacement for","meaning":"被視為……的替代品","examples":[{"en":"Virtual sports should not be treated as a replacement for real sports.","zh":"虛擬運動不應被視為真實運動的替代品。"},{"en":"Be treated as a replacement for something means be used as if it could fully take that thing’s place.","zh":"被視為某事的替代品，意思是被當作能完全取代那事物來使用。"},{"en":"Online notes should not always be treated as a replacement for careful reading.","zh":"網上筆記不應總是被視為仔細閱讀的替代品。"},{"en":"A tool can be useful without replacing the deeper original activity.","zh":"一個工具可以有用，但不必取代更深入的原本活動。"},{"en":"The writer says virtual sports can support exercise but should not replace real sports completely.","zh":"作者說虛擬運動可以支援運動，但不應完全取代真實運動。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"widen access and motivation","meaning":"擴闊參與機會並提升動力","examples":[{"en":"Virtual sports widen access and motivation for exercise.","zh":"虛擬運動擴闊做運動的參與機會並提升動力。"},{"en":"To widen access and motivation means to make it easier for more people to join and want to continue.","zh":"擴闊參與機會並提升動力，意思是令更多人更容易參加，並更想繼續。"},{"en":"A free school club can widen access to music for students who cannot afford lessons.","zh":"免費學校學會可以為負擔不起課程的學生擴闊接觸音樂的機會。"},{"en":"Games widen motivation by making effort feel rewarding.","zh":"遊戲透過令努力感覺有回報來提升動力。"},{"en":"Virtual sports widen access because people can begin at home with less pressure.","zh":"虛擬運動擴闊參與機會，因為人們可以在家以較少壓力開始。"}],"source":"2012 Q2.pdf","sourcePage":2},{"front":"develop the body, mind and character","meaning":"培養身體、心智和品格","examples":[{"en":"Real sports develop the body, mind and character more deeply.","zh":"真實運動更深入地培養身體、心智和品格。"},{"en":"To develop the body, mind and character means to train physical ability, thinking, emotions, and values.","zh":"培養身體、心智和品格，意思是訓練體能、思考、情緒和價值觀。"},{"en":"Team sports develop the body through movement and the character through cooperation.","zh":"團隊運動透過活動身體培養體能，並透過合作培養品格。"},{"en":"Real sports develop the mind because players must make decisions under pressure.","zh":"真實運動培養心智，因為球員必須在壓力下作決定。"},{"en":"The writer believes outdoor and team sports shape people more fully than virtual games alone.","zh":"作者相信戶外和團隊運動比單靠虛擬遊戲更全面地塑造人。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"more deeply","meaning":"更深入地","examples":[{"en":"Real sports develop young people more deeply than virtual sports.","zh":"真實運動比虛擬運動更深入地培養年輕人。"},{"en":"More deeply means in a fuller, stronger, or more meaningful way.","zh":"更深入地，意思是以更完整、更強或更有意義的方式。"},{"en":"Students understand friendship more deeply when they solve problems together.","zh":"當學生一起解決問題，他們會更深入地理解友誼。"},{"en":"Physical practice can teach lessons more deeply because the body and mind both remember them.","zh":"身體練習能更深入地教導課題，因為身體和心智都會記住。"},{"en":"Real sports affect young people more deeply through challenge, teamwork, and failure.","zh":"真實運動透過挑戰、團隊合作和失敗，更深入地影響年輕人。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"deserve credit","meaning":"值得肯定","examples":[{"en":"Virtual sports deserve credit for lowering the barrier to exercise.","zh":"虛擬運動因降低做運動門檻而值得肯定。"},{"en":"Deserve credit means should be recognised or praised for doing something useful.","zh":"值得肯定，意思是因做了有用的事而應被承認或讚賞。"},{"en":"A quiet student deserves credit for helping the group prepare carefully.","zh":"安靜的學生幫助小組仔細準備，值得肯定。"},{"en":"New tools deserve credit when they help people begin good habits.","zh":"當新工具幫助人們開始好習慣，它們值得肯定。"},{"en":"Virtual sports deserve credit because they make movement less frightening for beginners.","zh":"虛擬運動值得肯定，因為它們令初學者較不害怕活動身體。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"lower the barrier to exercise","meaning":"降低做運動的門檻","examples":[{"en":"Virtual sports lower the barrier to exercise.","zh":"虛擬運動降低做運動的門檻。"},{"en":"To lower the barrier to exercise means to make exercise easier to begin.","zh":"降低做運動的門檻，意思是令開始運動變得更容易。"},{"en":"Free sports equipment can lower the barrier to exercise for students from low-income families.","zh":"免費運動器材可以為低收入家庭學生降低做運動的門檻。"},{"en":"Lowering barriers matters because many people stop before they even start.","zh":"降低門檻很重要，因為很多人甚至在開始前已放棄。"},{"en":"Virtual sports lower the barrier by allowing people to move at home and at their own pace.","zh":"虛擬運動讓人們在家按自己的速度活動，從而降低門檻。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"basketball court downstairs","meaning":"樓下的籃球場","examples":[{"en":"Not everyone has a basketball court downstairs.","zh":"不是每個人樓下都有籃球場。"},{"en":"A basketball court downstairs means an easily available sports space near one’s home.","zh":"樓下的籃球場，意思是住處附近容易使用的運動空間。"},{"en":"Some students live far from sports facilities and do not have a basketball court downstairs.","zh":"有些學生住得離運動設施很遠，樓下沒有籃球場。"},{"en":"Without nearby facilities, starting regular exercise can be harder.","zh":"沒有附近設施時，開始恆常運動會更困難。"},{"en":"Virtual sports help people who lack a basketball court downstairs or other easy sports spaces.","zh":"虛擬運動幫助那些樓下沒有籃球場或其他方便運動空間的人。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"a free afternoon","meaning":"空閒的下午","examples":[{"en":"Not everyone has a free afternoon to play sport.","zh":"不是每個人都有空閒的下午去做運動。"},{"en":"A free afternoon is an afternoon without duties, lessons, work, or other plans.","zh":"空閒的下午，是沒有職責、課堂、工作或其他安排的下午。"},{"en":"A student with tutoring and club meetings may not have a free afternoon.","zh":"有補習和學會會議的學生可能沒有空閒的下午。"},{"en":"Lack of free time can stop people from joining real sports regularly.","zh":"缺少空閒時間會阻止人們恆常參與真實運動。"},{"en":"Virtual sports can fit into short breaks when a full free afternoon is impossible.","zh":"當完整空閒下午不可能時，虛擬運動可以安排在短暫休息中。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"the confidence to join a team","meaning":"加入隊伍的信心","examples":[{"en":"Some students lack the confidence to join a team.","zh":"有些學生缺乏加入隊伍的信心。"},{"en":"The confidence to join a team means feeling brave enough to practise or compete with others.","zh":"加入隊伍的信心，意思是有足夠勇氣與別人一起練習或比賽。"},{"en":"A beginner may lack the confidence to join a basketball team if they fear making mistakes.","zh":"如果初學者害怕犯錯，可能缺乏加入籃球隊的信心。"},{"en":"Confidence grows when students can practise safely before joining others.","zh":"當學生可以先安全練習，信心就會增長。"},{"en":"Virtual sports may help shy students build the confidence to join a real team later.","zh":"虛擬運動可能幫助害羞學生建立日後加入真正隊伍的信心。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"stronger players may judge them","meaning":"較強的球員可能會評價他們","examples":[{"en":"Beginners may fear that stronger players will judge them.","zh":"初學者可能害怕較強的球員會評價他們。"},{"en":"Stronger players may judge them means more skilled players might criticise or look down on beginners.","zh":"較強的球員可能會評價他們，意思是技術較好的球員可能批評或看不起初學者。"},{"en":"A new student may avoid football if they think stronger players will laugh at mistakes.","zh":"如果新學生以為較強球員會嘲笑錯誤，他可能逃避足球。"},{"en":"Fear of judgement can stop people from trying healthy activities.","zh":"害怕被評價會阻止人們嘗試健康活動。"},{"en":"Virtual sports reduce this fear because beginners can practise away from stronger players.","zh":"虛擬運動減少這種恐懼，因為初學者可以遠離較強球員練習。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, a Wii game can be played at home.","zh":"相比之下，Wii 遊戲可以在家玩。"},{"en":"By contrast is used to show a clear difference from the previous idea.","zh":"相比之下，用來顯示與前一個想法的清楚差異。"},{"en":"Team sports may feel public and competitive; by contrast, home games feel private and safe.","zh":"團隊運動可能感覺公開而有競爭性；相比之下，家中遊戲感覺私人而安全。"},{"en":"Writers use by contrast to compare two different situations.","zh":"作者使用「相比之下」來比較兩種不同情況。"},{"en":"By contrast with outdoor sport, virtual sport can begin in a small room.","zh":"與戶外運動相比，虛擬運動可以在小房間中開始。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"turn a small living room into","meaning":"把小客廳變成","examples":[{"en":"A Wii game can turn a small living room into a tennis court.","zh":"Wii 遊戲可以把小客廳變成網球場。"},{"en":"To turn a small living room into something means to make a limited home space feel like another place or activity area.","zh":"把小客廳變成某物，意思是令有限的家中空間感覺像另一個地方或活動區域。"},{"en":"A dance video can turn a small living room into a practice studio.","zh":"跳舞影片可以把小客廳變成練習室。"},{"en":"Digital games can change how people use space at home.","zh":"數碼遊戲可以改變人們在家使用空間的方式。"},{"en":"Virtual sports turn small rooms into places where beginners can start exercising.","zh":"虛擬運動把小房間變成人們可以開始運動的地方。"}],"source":"2012 Q2.pdf","sourcePage":3},{"front":"tennis court","meaning":"網球場","examples":[{"en":"A virtual game can turn a living room into a tennis court.","zh":"虛擬遊戲可以把客廳變成網球場。"},{"en":"A tennis court is a marked area where people play tennis with rackets and a ball.","zh":"網球場，是人們用球拍和球打網球的標記場地。"},{"en":"A real tennis court gives players space to run, stop, and turn.","zh":"真正網球場給球員空間去跑、停下和轉身。"},{"en":"A living-room game may imitate a tennis court, but it cannot fully copy its physical demands.","zh":"客廳遊戲可以模仿網球場，但不能完全複製其身體要求。"},{"en":"The tennis court example shows how virtual sports can make sport feel accessible.","zh":"網球場的例子顯示虛擬運動如何令運動感覺容易參與。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"bowling alley","meaning":"保齡球場","examples":[{"en":"A Wii game can turn a room into a bowling alley.","zh":"Wii 遊戲可以把房間變成保齡球場。"},{"en":"A bowling alley is a place where people roll heavy balls down lanes to hit pins.","zh":"保齡球場，是人們把重球沿球道滾出去擊倒球瓶的地方。"},{"en":"Families may visit a bowling alley for relaxed weekend exercise.","zh":"家庭可能週末到保齡球場進行輕鬆運動。"},{"en":"Virtual bowling imitates a bowling alley without needing the full space or equipment.","zh":"虛擬保齡球模仿保齡球場，而不需要完整空間或設備。"},{"en":"For beginners, a living-room bowling alley can make movement feel playful.","zh":"對初學者來說，客廳裏的保齡球場可以令活動身體感覺像玩樂。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"boxing ring","meaning":"拳擊台","examples":[{"en":"A Wii game can turn a room into a boxing ring.","zh":"Wii 遊戲可以把房間變成拳擊台。"},{"en":"A boxing ring is the square area where boxers fight under rules.","zh":"拳擊台，是拳擊手按規則比賽的方形區域。"},{"en":"A real boxing ring requires training, safety equipment, and supervision.","zh":"真正拳擊台需要訓練、安全設備和監督。"},{"en":"Virtual boxing can imitate punches without the same danger of being hit.","zh":"虛擬拳擊可以模仿出拳，而沒有同樣被擊中的危險。"},{"en":"The boxing ring example shows why virtual sports may feel safer for beginners.","zh":"拳擊台的例子顯示為何虛擬運動對初學者來說可能較安全。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"shy student","meaning":"害羞的學生","examples":[{"en":"A shy student may avoid PE lessons.","zh":"害羞的學生可能逃避體育課。"},{"en":"A shy student is someone who feels nervous or uncomfortable in front of others.","zh":"害羞的學生，是在人前感到緊張或不自在的人。"},{"en":"A shy student may dislike team games because everyone can see their mistakes.","zh":"害羞的學生可能不喜歡團隊遊戲，因為每個人都看得到他的錯誤。"},{"en":"Private practice can help a shy student gain confidence slowly.","zh":"私下練習可以幫助害羞的學生慢慢建立信心。"},{"en":"Virtual sports may help a shy student move without feeling watched.","zh":"虛擬運動可能幫助害羞的學生在不覺得被觀看的情況下活動。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"avoid PE","meaning":"逃避體育課","examples":[{"en":"A shy student who avoids PE may still enjoy virtual sports.","zh":"逃避體育課的害羞學生仍可能享受虛擬運動。"},{"en":"To avoid PE means to try not to take part in physical education lessons.","zh":"逃避體育課，意思是嘗試不參加體育課。"},{"en":"A student may avoid PE if they feel embarrassed about running slowly.","zh":"如果學生因跑得慢而尷尬，可能逃避體育課。"},{"en":"Avoiding PE can reduce fitness and confidence over time.","zh":"長期逃避體育課會減低體能和信心。"},{"en":"Virtual sports may help students who avoid PE take a first step back into movement.","zh":"虛擬運動可能幫助逃避體育課的學生踏出重回活動身體的第一步。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"be willing to","meaning":"願意去","examples":[{"en":"A shy student may be willing to swing a controller at home.","zh":"害羞的學生可能願意在家揮動控制器。"},{"en":"Be willing to do something means be ready or prepared to do it.","zh":"願意去做某事，意思是準備好或願意做它。"},{"en":"A student may be willing to practise speaking when only a friend is listening.","zh":"當只有朋友聆聽，學生可能願意練習說話。"},{"en":"People are more willing to try when the situation feels safe.","zh":"當情況感覺安全，人們更願意嘗試。"},{"en":"Virtual sports can make beginners willing to move because the pressure is lower.","zh":"虛擬運動可以令初學者願意活動身體，因為壓力較低。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"swing a controller","meaning":"揮動控制器","examples":[{"en":"The student can swing a controller at home.","zh":"學生可以在家揮動控制器。"},{"en":"To swing a controller means to move a game controller through the air like a sports tool.","zh":"揮動控制器，意思是把遊戲控制器像運動工具一樣在空中移動。"},{"en":"In virtual tennis, players swing a controller as if it were a racket.","zh":"在虛擬網球中，玩家揮動控制器，好像它是球拍。"},{"en":"Swinging a controller uses movement, but it may not train the whole body fully.","zh":"揮動控制器會用到動作，但未必能完全訓練全身。"},{"en":"For beginners, swinging a controller can be an easy way to start exercising.","zh":"對初學者來說，揮動控制器可以是開始運動的容易方法。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"safely outdoors","meaning":"在戶外安全地","examples":[{"en":"A grandparent may not be able to run safely outdoors.","zh":"祖父母可能不能在戶外安全地跑步。"},{"en":"Safely outdoors means outside without serious risk from weather, traffic, uneven ground, or injury.","zh":"在戶外安全地，意思是在外面不受天氣、交通、不平地面或受傷風險嚴重影響。"},{"en":"Elderly people may not walk safely outdoors during heavy rain.","zh":"大雨期間，長者可能不能在戶外安全地步行。"},{"en":"If someone cannot exercise safely outdoors, indoor movement may be a useful option.","zh":"如果某人不能在戶外安全地運動，室內活動可能是有用選擇。"},{"en":"Virtual sports can help grandparents move when outdoor exercise is unsafe.","zh":"當戶外運動不安全，虛擬運動可以幫助祖父母活動身體。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"virtual bowling","meaning":"虛擬保齡球","examples":[{"en":"A grandparent may enjoy virtual bowling with grandchildren.","zh":"祖父母可能喜歡和孫兒一起玩虛擬保齡球。"},{"en":"Virtual bowling is a digital game that imitates bowling movements and scoring.","zh":"虛擬保齡球，是模仿保齡球動作和計分的數碼遊戲。"},{"en":"Families may play virtual bowling at home on rainy days.","zh":"家庭可能在雨天在家玩虛擬保齡球。"},{"en":"Virtual bowling can allow different generations to move and laugh together.","zh":"虛擬保齡球可以讓不同世代一起活動和大笑。"},{"en":"It may not replace a real bowling alley, but it can still encourage gentle exercise.","zh":"它未必取代真正保齡球場，但仍可以鼓勵溫和運動。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"what something lacks in...it makes up for in...","meaning":"在……方面有所不足，卻以……彌補","examples":[{"en":"What virtual sports lack in authenticity, they make up for in accessibility.","zh":"虛擬運動在真實感方面有所不足，卻以易參與程度彌補。"},{"en":"What something lacks in A, it makes up for in B means its weakness in one area is balanced by strength in another.","zh":"某物在 A 方面有所不足，卻以 B 彌補，意思是它在一方面的弱點由另一方面的強項平衡。"},{"en":"What a small school lacks in facilities, it may make up for in close teacher support.","zh":"小學校在設施方面有所不足，卻可能以緊密的教師支援彌補。"},{"en":"This structure helps writers give a balanced judgement.","zh":"這個結構幫助作者作出平衡判斷。"},{"en":"Virtual sports may not feel fully real, but they are easy for many people to try.","zh":"虛擬運動可能不完全真實，但很多人很容易嘗試。"}],"source":"2012 Q2.pdf","sourcePage":4},{"front":"authenticity","meaning":"真實感","examples":[{"en":"Virtual sports may lack authenticity.","zh":"虛擬運動可能缺乏真實感。"},{"en":"Authenticity means the quality of feeling real, genuine, or true to the original experience.","zh":"真實感，意思是感覺真實、真正或貼近原本經驗的特質。"},{"en":"A real concert has an authenticity that a recording may not fully capture.","zh":"真正音樂會有錄音未必能完全捕捉的真實感。"},{"en":"Virtual tennis may lack authenticity because players do not run across a real court.","zh":"虛擬網球可能缺乏真實感，因為玩家不是在真正球場上奔跑。"},{"en":"The writer accepts that virtual sports have less authenticity than real sports.","zh":"作者承認虛擬運動比真實運動少一點真實感。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"accessibility","meaning":"易參與程度","examples":[{"en":"Virtual sports make up for limited authenticity with accessibility.","zh":"虛擬運動以易參與程度彌補有限的真實感。"},{"en":"Accessibility means how easy it is for different people to take part or use something.","zh":"易參與程度，意思是不同人參加或使用某事物有多容易。"},{"en":"A sports club improves accessibility when it offers beginner sessions and low fees.","zh":"運動學會提供初學者課堂和低收費時，就改善了易參與程度。"},{"en":"High accessibility matters because many people stop exercising when the first step is too hard.","zh":"高易參與程度很重要，因為當第一步太難，很多人會停止運動。"},{"en":"Virtual sports have strong accessibility because they can be played at home.","zh":"虛擬運動有很強的易參與程度，因為它們可以在家玩。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"instant feedback","meaning":"即時回饋","examples":[{"en":"Points, levels and instant feedback can make movement enjoyable.","zh":"分數、等級和即時回饋可以令活動身體變得有趣。"},{"en":"Instant feedback is information given immediately after an action, showing how well someone did.","zh":"即時回饋，是在行動後立即給出的資訊，顯示某人做得如何。"},{"en":"A game gives instant feedback when it shows a score after each move.","zh":"遊戲在每個動作後顯示分數，就是給出即時回饋。"},{"en":"Instant feedback motivates beginners because they can see progress quickly.","zh":"即時回饋激勵初學者，因為他們可以快速看見進步。"},{"en":"Virtual sports use instant feedback to make exercise feel rewarding.","zh":"虛擬運動使用即時回饋，令運動感覺有回報。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"make movement addictive","meaning":"令活動身體變得令人上癮","examples":[{"en":"Games can make movement addictive through scores and levels.","zh":"遊戲可以透過分數和等級令活動身體變得令人上癮。"},{"en":"To make movement addictive means to make physical activity so rewarding that people want to keep doing it.","zh":"令活動身體變得令人上癮，意思是令身體活動很有回報，使人想持續做下去。"},{"en":"A step-counting app can make walking addictive by celebrating daily goals.","zh":"計步應用程式透過慶祝每日目標，可以令步行變得令人上癮。"},{"en":"Scores and levels can turn effort into a challenge people want to repeat.","zh":"分數和等級可以把努力變成令人想重複的挑戰。"},{"en":"Virtual sports make movement addictive by mixing exercise with play.","zh":"虛擬運動透過把運動和玩樂結合，令活動身體變得令人上癮。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"record your best score","meaning":"記錄你的最佳分數","examples":[{"en":"The game records your best score and asks you to try again.","zh":"遊戲記錄你的最佳分數，並要求你再試一次。"},{"en":"To record your best score means to save the highest result you have achieved.","zh":"記錄你的最佳分數，意思是保存你取得過的最高成績。"},{"en":"A running app may record your best time for one kilometre.","zh":"跑步應用程式可能記錄你一公里的最佳時間。"},{"en":"Recording a best score encourages people to improve by giving them a target.","zh":"記錄最佳分數會給人目標，鼓勵他們進步。"},{"en":"Virtual sports use best scores to make players repeat movement.","zh":"虛擬運動使用最佳分數，令玩家重複活動身體。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"try again","meaning":"再試一次","examples":[{"en":"The game encourages players to try again.","zh":"遊戲鼓勵玩家再試一次。"},{"en":"To try again means to make another attempt after the first one.","zh":"再試一次，意思是在第一次之後再作另一次嘗試。"},{"en":"A student may try again after missing a basketball shot.","zh":"學生投失籃後可能再試一次。"},{"en":"Trying again builds persistence because mistakes become part of practice.","zh":"再試一次建立堅持，因為錯誤變成練習的一部分。"},{"en":"Virtual sports encourage players to try again through scores, levels, and rewards.","zh":"虛擬運動透過分數、等級和獎勵鼓勵玩家再試一次。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"no longer feels like punishment","meaning":"不再感覺像懲罰","examples":[{"en":"Exercise no longer feels like punishment when it becomes play.","zh":"當運動變成玩樂，它就不再感覺像懲罰。"},{"en":"No longer feels like punishment means it stops feeling unpleasant, forced, or painful.","zh":"不再感覺像懲罰，意思是不再感覺不愉快、被迫或痛苦。"},{"en":"Running may no longer feel like punishment when students do it with music and friends.","zh":"當學生配合音樂和朋友跑步，跑步可能不再感覺像懲罰。"},{"en":"Exercise becomes easier to continue when it feels enjoyable instead of miserable.","zh":"當運動感覺有趣而不是痛苦，它會更容易持續。"},{"en":"Virtual sports help some beginners because movement no longer feels like punishment.","zh":"虛擬運動幫助某些初學者，因為活動身體不再感覺像懲罰。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"become play","meaning":"變成玩樂","examples":[{"en":"Movement becomes play through virtual sports.","zh":"活動身體透過虛擬運動變成玩樂。"},{"en":"Become play means change into an enjoyable game or activity rather than a duty.","zh":"變成玩樂，意思是變成有趣的遊戲或活動，而不是責任。"},{"en":"Cleaning a classroom can become play if students turn it into a friendly challenge.","zh":"如果學生把清潔課室變成友善挑戰，它可以變成玩樂。"},{"en":"When exercise becomes play, people may move longer without noticing effort.","zh":"當運動變成玩樂，人們可能活動更久而沒有注意到努力。"},{"en":"Virtual sports make movement become play by adding goals, points, and fun.","zh":"虛擬運動透過加入目標、分數和樂趣，令活動身體變成玩樂。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"fitness plan","meaning":"健身計劃","examples":[{"en":"A fitness plan is useless if nobody follows it.","zh":"如果沒有人跟隨，健身計劃是沒有用的。"},{"en":"A fitness plan is a set of steps or activities designed to improve health and exercise habits.","zh":"健身計劃，是為改善健康和運動習慣而設計的一套步驟或活動。"},{"en":"A student’s fitness plan may include walking, stretching, and weekly football practice.","zh":"學生的健身計劃可能包括步行、伸展和每週足球練習。"},{"en":"A plan only works when people actually follow it regularly.","zh":"只有當人們真正定期跟隨，計劃才有效。"},{"en":"Virtual sports can support a fitness plan by making the first steps enjoyable.","zh":"虛擬運動可以透過令第一步有趣來支持健身計劃。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"no better than","meaning":"不比……好","examples":[{"en":"A perfect plan that nobody follows is no better than a dusty treadmill.","zh":"一個沒有人跟隨的完美計劃不比滿佈灰塵的跑步機好。"},{"en":"No better than means not more useful or valuable than something else.","zh":"不比某事好，意思是並不比另一事物更有用或更有價值。"},{"en":"A study timetable that no student uses is no better than a blank page.","zh":"沒有學生使用的溫習時間表不比白紙好。"},{"en":"This phrase shows that something impressive in theory may fail in practice.","zh":"這個短語顯示某事理論上令人印象深刻，但實際上可能失敗。"},{"en":"A fitness plan is no better than unused equipment if it does not lead to action.","zh":"如果健身計劃沒有帶來行動，它不比閒置器材好。"}],"source":"2012 Q2.pdf","sourcePage":5},{"front":"treadmill covered in dust","meaning":"滿佈灰塵的跑步機","examples":[{"en":"A fitness plan that nobody follows is like a treadmill covered in dust.","zh":"沒有人跟隨的健身計劃就像滿佈灰塵的跑步機。"},{"en":"A treadmill covered in dust is exercise equipment that has been unused for a long time.","zh":"滿佈灰塵的跑步機，是長時間沒有使用的運動器材。"},{"en":"A family may buy a treadmill, but it becomes covered in dust if no one uses it.","zh":"家庭可能買了跑步機，但如果沒有人使用，它就會滿佈灰塵。"},{"en":"The image shows the difference between owning equipment and building habits.","zh":"這個畫面顯示擁有器材和建立習慣之間的分別。"},{"en":"The writer uses a dusty treadmill to show that unused fitness tools do not improve health.","zh":"作者用滿佈灰塵的跑步機來顯示，沒有使用的健身工具不會改善健康。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"a practical starting point","meaning":"實際可行的起點","examples":[{"en":"Virtual sports are a practical starting point for beginners.","zh":"虛擬運動是初學者實際可行的起點。"},{"en":"A practical starting point is a realistic and useful first step.","zh":"實際可行的起點，是現實和有用的第一步。"},{"en":"Walking ten minutes a day can be a practical starting point for someone who rarely exercises.","zh":"對很少運動的人來說，每天步行十分鐘可以是實際可行的起點。"},{"en":"Starting points should feel possible, or people may give up early.","zh":"起點應感覺可行，否則人們可能很早放棄。"},{"en":"Virtual sports are practical because beginners can start without a team, court, or public pressure.","zh":"虛擬運動很實際，因為初學者不用隊伍、球場或公開壓力也能開始。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, real sports offer a deeper physical challenge.","zh":"話雖如此，真實運動提供更深層的身體挑戰。"},{"en":"That said is used to add a balancing or contrasting point after the previous idea.","zh":"話雖如此，用來在前一個想法後加入平衡或相反的一點。"},{"en":"Virtual games are useful; that said, outdoor play trains the body more fully.","zh":"虛擬遊戲有用；話雖如此，戶外活動更全面地訓練身體。"},{"en":"Writers use that said when both sides of an argument have value.","zh":"當論點雙方都有價值時，作者會使用「話雖如此」。"},{"en":"The writer praises virtual sports, but then uses that said to explain their limits.","zh":"作者讚賞虛擬運動，然後用「話雖如此」來解釋其限制。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"offer a physical challenge","meaning":"提供身體挑戰","examples":[{"en":"Real sports offer a physical challenge that a screen can only imitate.","zh":"真實運動提供屏幕只能模仿的身體挑戰。"},{"en":"To offer a physical challenge means to require real bodily effort, strength, speed, and control.","zh":"提供身體挑戰，意思是需要真正的身體努力、力量、速度和控制。"},{"en":"Swimming offers a physical challenge because the whole body must move against water.","zh":"游泳提供身體挑戰，因為全身必須對抗水來移動。"},{"en":"Physical challenges help people build fitness through effort and recovery.","zh":"身體挑戰透過努力和恢復幫助人們建立體能。"},{"en":"Real sports offer a challenge that virtual movements cannot fully copy.","zh":"真實運動提供虛擬動作不能完全複製的挑戰。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"a screen can only imitate","meaning":"屏幕只能模仿","examples":[{"en":"A screen can only imitate the challenge of real sport.","zh":"屏幕只能模仿真實運動的挑戰。"},{"en":"A screen can only imitate means digital images can copy the appearance but not the full experience.","zh":"屏幕只能模仿，意思是數碼畫面可以複製外表，但不能完整複製經驗。"},{"en":"A cooking video can imitate a kitchen lesson, but it cannot let you smell or taste the food.","zh":"煮食影片可以模仿廚房課，但不能讓你聞到或嚐到食物。"},{"en":"Screens can show sport, but they cannot fully reproduce space, weather, and physical pressure.","zh":"屏幕可以展示運動，但不能完全重現空間、天氣和身體壓力。"},{"en":"The writer says virtual sports imitate sport but do not equal real training.","zh":"作者說虛擬運動模仿運動，但不等於真正訓練。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"on the face of it","meaning":"表面看來","examples":[{"en":"On the face of it, swinging a Wii remote looks like playing tennis.","zh":"表面看來，揮動 Wii 遙控器像是在打網球。"},{"en":"On the face of it means at first sight, before looking more carefully.","zh":"表面看來，意思是乍看之下，在更仔細觀察之前。"},{"en":"On the face of it, the short exercise game looks easy.","zh":"表面看來，短小運動遊戲看起來容易。"},{"en":"This phrase warns that first impressions may be incomplete.","zh":"這個短語提醒我們，第一印象可能不完整。"},{"en":"On the face of it, virtual tennis seems similar to tennis, but deeper comparison shows differences.","zh":"表面看來，虛擬網球似乎與網球相似，但深入比較會顯示差異。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"Wii remote","meaning":"Wii 遙控器","examples":[{"en":"Swinging a Wii remote is not the same as playing real tennis.","zh":"揮動 Wii 遙控器並不等於打真正網球。"},{"en":"A Wii remote is a handheld controller used to play games on the Wii system.","zh":"Wii 遙控器，是用來玩 Wii 系統遊戲的手持控制器。"},{"en":"A player may swing a Wii remote to imitate a tennis racket.","zh":"玩家可能揮動 Wii 遙控器來模仿網球拍。"},{"en":"A Wii remote can detect movement, but it cannot recreate a whole tennis court.","zh":"Wii 遙控器可以偵測動作，但不能重現整個網球場。"},{"en":"The writer uses the Wii remote to show the difference between gesture and full sport.","zh":"作者用 Wii 遙控器來顯示手勢和完整運動之間的差異。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, virtual tennis is very different from real tennis.","zh":"仔細看來，虛擬網球與真正網球非常不同。"},{"en":"On closer inspection means after looking carefully at the details.","zh":"仔細看來，意思是在仔細觀察細節之後。"},{"en":"On closer inspection, a simple game may involve more strategy than expected.","zh":"仔細看來，一個簡單遊戲可能比預期涉及更多策略。"},{"en":"Careful inspection can reveal differences that first impressions miss.","zh":"仔細檢視可以揭示第一印象錯過的差異。"},{"en":"On closer inspection, virtual tennis lacks running, footwork, weather, and real opponents.","zh":"仔細看來，虛擬網球缺少奔跑、步法、天氣和真正對手。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"a far cry from","meaning":"與……相差甚遠","examples":[{"en":"Swinging a controller is a far cry from chasing a ball across a court.","zh":"揮動控制器與在球場上追球相差甚遠。"},{"en":"A far cry from means very different from something else.","zh":"與某事相差甚遠，意思是與另一事物非常不同。"},{"en":"Watching a cooking show is a far cry from preparing a full meal yourself.","zh":"看煮食節目與親自準備一頓完整飯餐相差甚遠。"},{"en":"This phrase shows that two things may look similar but are not equal.","zh":"這個短語顯示兩件事可能看似相似，但並不相等。"},{"en":"The writer says virtual gestures are a far cry from real sport’s full-body demands.","zh":"作者說虛擬手勢與真實運動的全身要求相差甚遠。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"chase a ball across a court","meaning":"在球場上追球","examples":[{"en":"Real tennis requires players to chase a ball across a court.","zh":"真正網球要求球員在球場上追球。"},{"en":"To chase a ball across a court means to run after a moving ball over a sports area.","zh":"在球場上追球，意思是在運動場地上跑去追趕移動中的球。"},{"en":"In tennis, players chase the ball across the court to return each shot.","zh":"在網球中，球員在球場上追球，以回擊每一球。"},{"en":"Chasing a ball trains speed, balance, and reaction.","zh":"追球訓練速度、平衡和反應。"},{"en":"Virtual tennis does not fully copy the effort needed to chase a ball across a court.","zh":"虛擬網球不能完全複製在球場上追球所需的努力。"}],"source":"2012 Q2.pdf","sourcePage":6},{"front":"adjust your footwork","meaning":"調整步法","examples":[{"en":"Players must adjust their footwork during real tennis.","zh":"球員在真正網球中必須調整步法。"},{"en":"To adjust your footwork means to change how your feet move or stand in response to the game.","zh":"調整步法，意思是按比賽情況改變腳步移動或站位方式。"},{"en":"A badminton player adjusts footwork to reach a shuttle quickly.","zh":"羽毛球員會調整步法，以快速接到羽毛球。"},{"en":"Good footwork helps players stay balanced and hit with control.","zh":"良好步法幫助球員保持平衡並有控制地擊球。"},{"en":"Real tennis trains footwork because players must move before every shot.","zh":"真正網球訓練步法，因為球員每次擊球前都必須移動。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"read your opponent","meaning":"判斷對手意圖","examples":[{"en":"Real tennis requires players to read their opponent.","zh":"真正網球要求球員判斷對手意圖。"},{"en":"To read your opponent means to watch and predict what the other player may do next.","zh":"判斷對手意圖，意思是觀察並預測對方下一步可能做甚麼。"},{"en":"A goalkeeper reads an opponent before deciding where to dive.","zh":"守門員在決定撲向哪裏前會判斷對手意圖。"},{"en":"Reading opponents helps players react faster and choose smarter moves.","zh":"判斷對手意圖幫助球員更快反應並選擇更聰明動作。"},{"en":"Virtual sports may teach timing, but real sports train people to read human behaviour.","zh":"虛擬運動可能教時機，但真實運動訓練人判斷人類行為。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"cope with wind, heat and pressure","meaning":"應付風、熱和壓力","examples":[{"en":"Players must cope with wind, heat and pressure outdoors.","zh":"球員必須在戶外應付風、熱和壓力。"},{"en":"To cope with wind, heat and pressure means to manage difficult weather and stressful competition.","zh":"應付風、熱和壓力，意思是處理困難天氣和比賽壓力。"},{"en":"A runner must cope with heat and pressure during a school race.","zh":"跑手在學校賽跑中必須應付炎熱和壓力。"},{"en":"Outdoor conditions make sport harder because the body and mind must adapt.","zh":"戶外情況令運動更困難，因為身體和心智都必須適應。"},{"en":"Real sports train players to cope with changing conditions that screens cannot fully create.","zh":"真實運動訓練球員應付屏幕不能完全創造的變化情況。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"quick wrist movement","meaning":"快速手腕動作","examples":[{"en":"In virtual tennis, a quick wrist movement may produce a powerful shot.","zh":"在虛擬網球中，快速手腕動作可能打出有力一擊。"},{"en":"A quick wrist movement is a fast movement made mainly with the wrist.","zh":"快速手腕動作，是主要用手腕做出的快速動作。"},{"en":"A player may flick the wrist quickly to control a game controller.","zh":"玩家可能快速扭動手腕來控制遊戲控制器。"},{"en":"Quick wrist movement is not the same as using the legs, core, and shoulders together.","zh":"快速手腕動作並不等於同時使用雙腿、核心肌群和肩膀。"},{"en":"The writer uses this example to show why virtual tennis can be physically limited.","zh":"作者用這個例子來顯示虛擬網球在身體訓練上可能有限。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"produce a powerful shot","meaning":"打出有力一擊","examples":[{"en":"A quick wrist movement may produce a powerful shot in the game.","zh":"快速手腕動作可能在遊戲中打出有力一擊。"},{"en":"To produce a powerful shot means to create a strong hit or strike.","zh":"打出有力一擊，意思是產生強力擊球或攻擊。"},{"en":"A tennis player produces a powerful shot by using timing, strength, and body position.","zh":"網球員透過時機、力量和身體位置打出有力一擊。"},{"en":"In a game, a small movement may produce a powerful shot more easily than in real sport.","zh":"在遊戲中，小動作可能比真實運動中更容易打出有力一擊。"},{"en":"The difference shows why virtual games cannot fully copy physical training.","zh":"這種差異顯示虛擬遊戲不能完全複製身體訓練。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"legs, core and shoulders","meaning":"雙腿、核心肌群和肩膀","examples":[{"en":"Real tennis uses the legs, core and shoulders.","zh":"真正網球會使用雙腿、核心肌群和肩膀。"},{"en":"Legs, core and shoulders refers to major body parts needed for balance, power, and movement.","zh":"雙腿、核心肌群和肩膀，是指平衡、力量和動作所需的主要身體部位。"},{"en":"Swimmers use legs, core and shoulders to move through water.","zh":"游泳者使用雙腿、核心肌群和肩膀在水中前進。"},{"en":"Full-body sport trains more muscles than a game controlled mainly by the wrist.","zh":"全身運動比主要用手腕控制的遊戲訓練更多肌肉。"},{"en":"Real tennis is demanding because legs, core and shoulders must work together.","zh":"真正網球要求很高，因為雙腿、核心肌群和肩膀必須一起配合。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"timing and stamina","meaning":"時機掌握和耐力","examples":[{"en":"Real sport requires timing and stamina.","zh":"真實運動需要時機掌握和耐力。"},{"en":"Timing and stamina mean knowing when to act and having the energy to continue.","zh":"時機掌握和耐力，意思是知道何時行動，並有精力持續下去。"},{"en":"Basketball players need timing to pass and stamina to keep running.","zh":"籃球員需要時機掌握來傳球，也需要耐力繼續跑動。"},{"en":"Without stamina, a player may start well but become tired quickly.","zh":"沒有耐力，球員可能開始時表現好，但很快疲倦。"},{"en":"Real sports train timing and stamina through repeated movement and changing situations.","zh":"真實運動透過反覆動作和變化情況訓練時機掌握和耐力。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"work together","meaning":"一起配合","examples":[{"en":"The whole body has to work together in real tennis.","zh":"在真正網球中，全身必須一起配合。"},{"en":"Work together means different parts cooperate to achieve one result.","zh":"一起配合，意思是不同部分合作以達成同一結果。"},{"en":"In swimming, arms, legs, breathing, and core muscles work together.","zh":"在游泳中，雙臂、雙腿、呼吸和核心肌群一起配合。"},{"en":"The body moves better when its parts work together instead of separately.","zh":"當身體各部分一起配合而不是分開行動，動作會更好。"},{"en":"Real tennis requires the whole body to work together, not only the wrist.","zh":"真正網球需要全身一起配合，而不只是手腕。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"the same applies to","meaning":"同樣適用於","examples":[{"en":"The same applies to basketball, football, swimming and badminton.","zh":"這同樣適用於籃球、足球、游泳和羽毛球。"},{"en":"The same applies to means the same idea is true for another case too.","zh":"同樣適用於，意思是同一想法對另一情況也成立。"},{"en":"Sleep helps exam performance, and the same applies to sports training.","zh":"睡眠有助考試表現，這同樣適用於運動訓練。"},{"en":"Writers use this phrase to extend a point to more examples.","zh":"作者使用這個短語，把一個觀點延伸到更多例子。"},{"en":"The writer says the full-body demands of tennis also apply to other real sports.","zh":"作者說網球的全身要求也同樣適用於其他真實運動。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"force the whole body to respond","meaning":"迫使全身作出反應","examples":[{"en":"Real sports force the whole body to respond to changing situations.","zh":"真實運動迫使全身對變化情況作出反應。"},{"en":"To force the whole body to respond means to require all parts of the body to react quickly and actively.","zh":"迫使全身作出反應，意思是要求身體各部分快速而積極地反應。"},{"en":"Football forces the whole body to respond when the ball suddenly changes direction.","zh":"當皮球突然改變方向，足球會迫使全身作出反應。"},{"en":"Changing situations train balance, speed, strength, and awareness.","zh":"變化情況訓練平衡、速度、力量和意識。"},{"en":"Virtual sports may move the body, but real sports make the whole body respond.","zh":"虛擬運動可能令身體活動，但真實運動令全身作出反應。"}],"source":"2012 Q2.pdf","sourcePage":7},{"front":"space, speed and uncertainty","meaning":"空間、速度和不確定性","examples":[{"en":"Real sports involve space, speed and uncertainty.","zh":"真實運動涉及空間、速度和不確定性。"},{"en":"Space, speed and uncertainty means players must move through real areas, act quickly, and face unpredictable events.","zh":"空間、速度和不確定性，意思是球員必須在真實場地中移動、快速行動，並面對不可預測事件。"},{"en":"In badminton, space, speed and uncertainty appear when the shuttle changes direction.","zh":"在羽毛球中，當羽毛球改變方向，空間、速度和不確定性就會出現。"},{"en":"These elements make sport physically and mentally demanding.","zh":"這些元素令運動在身體和心理上都有要求。"},{"en":"Real sports train players because space, speed and uncertainty constantly change.","zh":"真實運動能訓練球員，因為空間、速度和不確定性不斷變化。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"build endurance","meaning":"建立耐力","examples":[{"en":"Real sports build endurance through repeated movement.","zh":"真實運動透過反覆動作建立耐力。"},{"en":"To build endurance means to increase the ability to keep going without getting tired quickly.","zh":"建立耐力，意思是提升持續活動而不快速疲倦的能力。"},{"en":"Running regularly can build endurance over several weeks.","zh":"定期跑步可以在數星期內建立耐力。"},{"en":"Endurance grows when the body repeats effort and learns to recover.","zh":"當身體反覆努力並學會恢復，耐力就會增長。"},{"en":"Real sports build endurance because players must move again and again during play.","zh":"真實運動建立耐力，因為球員在比賽中必須一次又一次移動。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"sprint, stop, turn, jump and recover","meaning":"衝刺、停下、轉身、跳躍和恢復","examples":[{"en":"Players must sprint, stop, turn, jump and recover.","zh":"球員必須衝刺、停下、轉身、跳躍和恢復。"},{"en":"Sprint, stop, turn, jump and recover describes the repeated physical actions needed in many sports.","zh":"衝刺、停下、轉身、跳躍和恢復，描述許多運動中需要反覆做的身體動作。"},{"en":"Basketball players sprint, stop, turn, jump and recover during one attack.","zh":"籃球員在一次進攻中會衝刺、停下、轉身、跳躍和恢復。"},{"en":"These actions train the body more fully than one repeated hand movement.","zh":"這些動作比單一重複手部動作更全面地訓練身體。"},{"en":"Real sports are demanding because players must perform these actions under pressure.","zh":"真實運動要求很高，因為球員必須在壓力下完成這些動作。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"sharpen coordination","meaning":"提升協調能力","examples":[{"en":"Real sports sharpen coordination.","zh":"真實運動提升協調能力。"},{"en":"To sharpen coordination means to improve how well different body parts work together.","zh":"提升協調能力，意思是改善身體不同部分一起配合的能力。"},{"en":"Badminton sharpens coordination because eyes, feet, arms, and timing must match.","zh":"羽毛球提升協調能力，因為眼睛、腳步、手臂和時機必須配合。"},{"en":"Coordination improves when players react to moving objects and changing space.","zh":"當球員對移動物件和變化空間作反應，協調能力就會改善。"},{"en":"Real sports sharpen coordination more deeply than simple controller movements.","zh":"真實運動比簡單控制器動作更深入地提升協調能力。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"programmed gesture","meaning":"預設動作","examples":[{"en":"The body is not merely copying a programmed gesture.","zh":"身體不只是複製一個預設動作。"},{"en":"A programmed gesture is a fixed movement designed by a game or system.","zh":"預設動作，是由遊戲或系統設計好的固定動作。"},{"en":"A game may reward the same programmed gesture every time.","zh":"遊戲可能每次都獎勵同一個預設動作。"},{"en":"Real sport is harder because the body must adjust instead of repeat one fixed movement.","zh":"真實運動更難，因為身體必須調整，而不是重複一個固定動作。"},{"en":"The writer contrasts programmed gestures with the changing problems of real sport.","zh":"作者把預設動作與真實運動中的變化問題作對比。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"solve a moving problem","meaning":"解決一個移動中的問題","examples":[{"en":"In real sport, the body is solving a moving problem.","zh":"在真實運動中，身體正在解決一個移動中的問題。"},{"en":"To solve a moving problem means to respond to a changing situation with body and mind together.","zh":"解決一個移動中的問題，意思是用身體和心智一起回應變化中的情況。"},{"en":"A goalkeeper solves a moving problem when the ball changes direction suddenly.","zh":"當皮球突然改變方向，守門員就在解決一個移動中的問題。"},{"en":"Real sport asks players to think through movement, not only repeat gestures.","zh":"真實運動要求球員透過動作思考，而不只是重複手勢。"},{"en":"The body solves moving problems when it reacts to opponents, space, and speed.","zh":"當身體對對手、空間和速度作反應，它就在解決移動中的問題。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"if fitness is the goal","meaning":"如果目標是健身","examples":[{"en":"If fitness is the goal, real sports offer deeper training.","zh":"如果目標是健身，真實運動提供更深入的訓練。"},{"en":"If fitness is the goal means if the purpose is to improve physical health and ability.","zh":"如果目標是健身，意思是如果目的在於改善身體健康和能力。"},{"en":"If fitness is the goal, walking daily is better than only reading about exercise.","zh":"如果目標是健身，每天步行比只閱讀運動知識更好。"},{"en":"Goals matter because they help us judge which activity works best.","zh":"目標重要，因為它幫助我們判斷哪種活動最有效。"},{"en":"The writer says real sports are stronger if lasting fitness is the main aim.","zh":"作者說如果主要目標是持久健身，真實運動更有力量。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"it would be wrong to pretend that","meaning":"假裝……是錯誤的","examples":[{"en":"It would be wrong to pretend that pressing buttons and playing matches are equal.","zh":"假裝按掣和進行比賽是相等的，是錯誤的。"},{"en":"It would be wrong to pretend that means it would be dishonest or inaccurate to act as if something were true.","zh":"假裝某事是錯誤的，意思是把不真實的事情當作真實，是不誠實或不準確的。"},{"en":"It would be wrong to pretend that watching a lesson is the same as practising the skill.","zh":"假裝觀看課堂等於練習技能，是錯誤的。"},{"en":"This phrase helps writers reject an unfair comparison.","zh":"這個短語幫助作者拒絕不公平比較。"},{"en":"The writer says virtual play and real matches should not be treated as equal training.","zh":"作者說虛擬遊玩和真實比賽不應被視為相等訓練。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"pressing buttons","meaning":"按掣","examples":[{"en":"Pressing buttons is not the same as playing a real match.","zh":"按掣並不等於進行真正比賽。"},{"en":"Pressing buttons means using fingers to control a device or game.","zh":"按掣，意思是用手指控制設備或遊戲。"},{"en":"Pressing buttons can choose actions on a screen, but it may not train the whole body.","zh":"按掣可以在屏幕上選擇行動，但未必訓練全身。"},{"en":"Some games require quick button pressing, but real sports require movement through space.","zh":"有些遊戲需要快速按掣，但真實運動需要在空間中移動。"},{"en":"The writer uses pressing buttons to show the limits of virtual activity.","zh":"作者用按掣來顯示虛擬活動的限制。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"playing matches","meaning":"進行比賽","examples":[{"en":"Playing matches requires the whole body and mind.","zh":"進行比賽需要整個身體和心智。"},{"en":"Playing matches means taking part in real competitive games against others.","zh":"進行比賽，意思是參與真正與他人競爭的遊戲或賽事。"},{"en":"Playing matches teaches players how to react to opponents and changing scores.","zh":"進行比賽教球員如何回應對手和變化比分。"},{"en":"Matches involve pressure, mistakes, teamwork, and physical effort.","zh":"比賽涉及壓力、錯誤、團隊合作和身體努力。"},{"en":"The writer believes playing matches gives lessons virtual sports cannot fully provide.","zh":"作者相信進行比賽會帶來虛擬運動不能完全提供的課題。"}],"source":"2012 Q2.pdf","sourcePage":8},{"front":"make us train","meaning":"令我們真正訓練","examples":[{"en":"Virtual sports may make us move, but real sports make us train.","zh":"虛擬運動可能令我們活動，但真實運動令我們真正訓練。"},{"en":"Make us train means push us to practise seriously and improve strength, skill, and discipline.","zh":"令我們真正訓練，意思是推動我們認真練習並改善力量、技巧和紀律。"},{"en":"A dance game may make students move, but team practice makes them train regularly.","zh":"跳舞遊戲可能令學生活動，但團隊練習令他們定期真正訓練。"},{"en":"Training requires repeated effort, correction, and progress over time.","zh":"訓練需要反覆努力、修正和隨時間進步。"},{"en":"Real sports make us train because they demand endurance, technique, and teamwork.","zh":"真實運動令我們真正訓練，因為它要求耐力、技巧和團隊合作。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"supporters of virtual sports","meaning":"虛擬運動的支持者","examples":[{"en":"Supporters of virtual sports may argue that they are safer.","zh":"虛擬運動的支持者可能認為它們更安全。"},{"en":"Supporters of virtual sports are people who defend or favour digital sports activities.","zh":"虛擬運動的支持者，是維護或偏好數碼運動活動的人。"},{"en":"Supporters may say virtual sports help shy beginners exercise at home.","zh":"支持者可能說虛擬運動幫助害羞初學者在家運動。"},{"en":"Supporters often focus on access, safety, and motivation.","zh":"支持者常集中於參與機會、安全和動力。"},{"en":"The writer listens to supporters of virtual sports before explaining their limits.","zh":"作者先聆聽虛擬運動支持者的意見，然後解釋其限制。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"safer, cleaner and more inclusive","meaning":"更安全、更乾淨、更共融","examples":[{"en":"Some people argue that virtual sports are safer, cleaner and more inclusive.","zh":"有些人認為虛擬運動更安全、更乾淨、更共融。"},{"en":"Safer, cleaner and more inclusive means involving less danger, less mess, and more chances for different people to join.","zh":"更安全、更乾淨、更共融，意思是危險較少、混亂較少，並給不同人更多參與機會。"},{"en":"Indoor games may feel safer and cleaner than outdoor sport on a rainy day.","zh":"在雨天，室內遊戲可能比戶外運動感覺更安全和更乾淨。"},{"en":"Inclusive activities allow beginners, shy students, and older people to participate more easily.","zh":"共融活動讓初學者、害羞學生和年長人士更容易參與。"},{"en":"Virtual sports can be safer, cleaner and more inclusive, but they still miss some real-sport lessons.","zh":"虛擬運動可以更安全、更乾淨、更共融，但仍缺少某些真實運動課題。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"I hear that","meaning":"我明白這一點","examples":[{"en":"The writer says, “I hear that,” before responding to the argument.","zh":"作者在回應論點前說：「我明白這一點。」"},{"en":"I hear that means I understand that point and accept that it deserves attention.","zh":"我明白這一點，意思是我理解這個觀點，並承認它值得注意。"},{"en":"A teacher may say “I hear that” when students explain why a task feels difficult.","zh":"當學生解釋任務為何困難，老師可能說「我明白這一點」。"},{"en":"This phrase helps a disagreement sound fair and respectful.","zh":"這個短語令異議聽起來公平和尊重。"},{"en":"The writer says “I hear that” before explaining why safety is not the whole story.","zh":"作者說「我明白這一點」，然後解釋安全不是全部。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"granted","meaning":"無可否認","examples":[{"en":"Granted, virtual sports can protect players from some difficulties.","zh":"無可否認，虛擬運動可以保護玩家免受某些困難。"},{"en":"Granted is used to admit that an opposing point has some truth before answering it.","zh":"無可否認，用來承認相反觀點有一定道理，然後再回應它。"},{"en":"Granted, online practice is convenient, but face-to-face practice teaches different skills.","zh":"無可否認，網上練習很方便，但面對面練習教會不同技巧。"},{"en":"This word helps writers sound fair instead of ignoring the other side.","zh":"這個詞幫助作者顯得公平，而不是忽視另一方。"},{"en":"The writer grants that virtual sports are safer in some ways, but says real sports teach more.","zh":"作者承認虛擬運動在某些方面較安全，但認為真實運動教得更多。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"protect players from","meaning":"保護玩家免受……","examples":[{"en":"Virtual sports can protect players from harsh weather.","zh":"虛擬運動可以保護玩家免受惡劣天氣影響。"},{"en":"To protect players from something means to keep them safe from that difficulty or danger.","zh":"保護玩家免受某事，意思是讓他們免於那種困難或危險。"},{"en":"Indoor training can protect players from lightning during a storm.","zh":"室內訓練可以在暴風雨期間保護球員免受雷電危險。"},{"en":"Protection is useful, but avoiding all difficulty may reduce learning.","zh":"保護很有用，但避開所有困難可能減少學習。"},{"en":"Virtual sports protect players from some risks by keeping exercise indoors.","zh":"虛擬運動透過把運動留在室內，保護玩家免受某些風險。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"harsh weather","meaning":"惡劣天氣","examples":[{"en":"Virtual sports avoid harsh weather.","zh":"虛擬運動避開惡劣天氣。"},{"en":"Harsh weather means difficult or unpleasant weather such as heavy rain, strong heat, or cold wind.","zh":"惡劣天氣，意思是困難或不舒服的天氣，例如大雨、酷熱或寒風。"},{"en":"Football practice may be cancelled because of harsh weather.","zh":"足球練習可能因惡劣天氣取消。"},{"en":"Harsh weather can make outdoor exercise unsafe for elderly people or beginners.","zh":"惡劣天氣會令戶外運動對長者或初學者不安全。"},{"en":"Virtual sports are useful on days when harsh weather makes real sports difficult.","zh":"當惡劣天氣令真實運動困難，虛擬運動就很有用。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"rough opponents","meaning":"粗魯的對手","examples":[{"en":"Players may avoid rough opponents by playing virtual sports.","zh":"玩家可以透過玩虛擬運動避開粗魯的對手。"},{"en":"Rough opponents are players who act physically, aggressively, or carelessly during sport.","zh":"粗魯的對手，是在運動中身體碰撞強烈、具攻擊性或粗心的球員。"},{"en":"A beginner may fear rough opponents in a competitive football match.","zh":"初學者可能害怕競爭性足球賽中的粗魯對手。"},{"en":"Rough opponents can make sport feel unsafe or embarrassing for new players.","zh":"粗魯的對手會令新玩家覺得運動不安全或尷尬。"},{"en":"Virtual sports reduce this fear because no one can push or tackle the player physically.","zh":"虛擬運動減少這種恐懼，因為沒有人能實際推撞或攔截玩家。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"public embarrassment","meaning":"當眾尷尬","examples":[{"en":"Virtual sports can protect shy players from public embarrassment.","zh":"虛擬運動可以保護害羞玩家免受當眾尷尬。"},{"en":"Public embarrassment is the uncomfortable feeling of making a mistake in front of others.","zh":"當眾尷尬，是在別人面前犯錯時感到不舒服的感覺。"},{"en":"A student may fear public embarrassment when trying a new sport in PE.","zh":"學生在體育課嘗試新運動時，可能害怕當眾尷尬。"},{"en":"Fear of embarrassment can stop beginners from joining healthy activities.","zh":"害怕尷尬會阻止初學者參與健康活動。"},{"en":"Virtual sports help by letting people practise without a watching crowd.","zh":"虛擬運動讓人不用在觀眾面前也能練習，因此有幫助。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"avoiding discomfort altogether","meaning":"完全避開不適","examples":[{"en":"Avoiding discomfort altogether comes at a cost.","zh":"完全避開不適是有代價的。"},{"en":"Avoiding discomfort altogether means staying away from all situations that feel difficult, awkward, or unpleasant.","zh":"完全避開不適，意思是遠離所有感覺困難、尷尬或不愉快的情況。"},{"en":"A student who avoids every hard question may feel safe but learn less.","zh":"避開每條難題的學生可能感到安全，但學得較少。"},{"en":"Some discomfort helps people grow because it teaches patience and courage.","zh":"某些不適幫助人成長，因為它教導耐性和勇氣。"},{"en":"The writer says avoiding all discomfort may also mean missing real-sport lessons.","zh":"作者說完全避開不適，也可能意味錯過真實運動的課題。"}],"source":"2012 Q2.pdf","sourcePage":9},{"front":"come at a cost","meaning":"有代價","examples":[{"en":"Avoiding discomfort comes at a cost.","zh":"避開不適是有代價的。"},{"en":"To come at a cost means to bring a disadvantage or loss while gaining something.","zh":"有代價，意思是在得到某事的同時帶來缺點或損失。"},{"en":"Studying all night may improve revision time, but it comes at the cost of sleep.","zh":"通宵溫習可能增加溫習時間，但代價是睡眠。"},{"en":"Safety is valuable, but avoiding every challenge can come at a cost.","zh":"安全很有價值，但避開每個挑戰可能有代價。"},{"en":"Virtual sports protect players from discomfort, but this protection may reduce real-life learning.","zh":"虛擬運動保護玩家免受不適，但這種保護可能減少現實學習。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"lessons that cannot be downloaded","meaning":"下載不到的人生課","examples":[{"en":"Real sports teach lessons that cannot be downloaded.","zh":"真實運動教會下載不到的人生課。"},{"en":"Lessons that cannot be downloaded are life skills learned through real experience, not by clicking or installing something.","zh":"下載不到的人生課，是透過真實經驗學到，而不是靠點擊或安裝得到的生活技能。"},{"en":"Teamwork, patience, and courage cannot simply be downloaded from an app.","zh":"團隊合作、耐性和勇氣不能簡單從應用程式下載。"},{"en":"Some lessons need bodies, people, mistakes, and time.","zh":"有些課題需要身體、他人、錯誤和時間。"},{"en":"Real sports teach lessons that virtual systems can explain but not fully provide.","zh":"真實運動教會虛擬系統可以解釋但不能完全提供的人生課。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"lose without sulking","meaning":"輸了也不鬧彆扭","examples":[{"en":"Real sports teach players how to lose without sulking.","zh":"真實運動教球員輸了也不鬧彆扭。"},{"en":"To lose without sulking means to accept defeat without becoming childish, silent, or resentful.","zh":"輸了也不鬧彆扭，意思是接受失敗，而不變得孩子氣、沉默或怨恨。"},{"en":"A student loses without sulking when they shake hands after a close match.","zh":"學生在接近的比賽後握手，就是輸了也不鬧彆扭。"},{"en":"Learning to lose well teaches emotional control and respect.","zh":"學會好好面對失敗，能教導情緒控制和尊重。"},{"en":"Real sports teach this because players must face opponents after defeat.","zh":"真實運動教會這一點，因為球員失敗後仍必須面對對手。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"pass instead of showing off","meaning":"傳球而不是炫耀","examples":[{"en":"Team sports teach players to pass instead of showing off.","zh":"團隊運動教球員傳球而不是炫耀。"},{"en":"To pass instead of showing off means to help the team rather than try to look impressive alone.","zh":"傳球而不是炫耀，意思是幫助團隊，而不是只想自己看起來厲害。"},{"en":"A basketball player passes instead of showing off when a teammate has a better chance to score.","zh":"當隊友有更好入球機會，籃球員選擇傳球而不是炫耀。"},{"en":"Teamwork improves when players choose the team result over personal display.","zh":"當球員選擇團隊結果而不是個人表現，團隊合作就會改善。"},{"en":"Real sports teach humility because success often depends on passing at the right moment.","zh":"真實運動教導謙遜，因為成功常取決於在正確時刻傳球。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"trust a teammate","meaning":"信任隊友","examples":[{"en":"Players learn how to trust a teammate.","zh":"球員學會如何信任隊友。"},{"en":"To trust a teammate means to believe another team member will try, help, and do their role.","zh":"信任隊友，意思是相信另一位隊員會努力、幫忙並做好自己的角色。"},{"en":"A football player trusts a teammate when passing the ball instead of keeping it alone.","zh":"足球員傳球而不是獨自控球時，就是信任隊友。"},{"en":"Trust grows through shared practice, mistakes, and support.","zh":"信任透過共同練習、錯誤和支持而增長。"},{"en":"Real sports teach trust because no one can win every team game alone.","zh":"真實運動教導信任，因為沒有人能獨自贏得每場團隊比賽。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"shake hands after a bad call","meaning":"在一次錯判後仍握手","examples":[{"en":"Players learn to shake hands after a bad call.","zh":"球員學會在一次錯判後仍握手。"},{"en":"To shake hands after a bad call means to show respect even after an unfair or mistaken referee decision.","zh":"在一次錯判後仍握手，意思是在不公平或錯誤裁判決定後仍表示尊重。"},{"en":"A player may feel angry after a bad call but still shake hands at the end.","zh":"球員在一次錯判後可能很生氣，但結束時仍握手。"},{"en":"This teaches self-control because sport does not always feel fair.","zh":"這教導自我控制，因為運動不一定總是感覺公平。"},{"en":"Real sports teach players to respect others even when decisions hurt.","zh":"真實運動教球員即使決定令人受傷，也要尊重他人。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"stand tall after","meaning":"在……之後仍昂然面對","examples":[{"en":"Players learn to stand tall after missing the final shot.","zh":"球員學會在錯失最後一球後仍昂然面對。"},{"en":"To stand tall after something means to keep dignity and courage after a difficult moment.","zh":"在某事之後仍昂然面對，意思是在困難時刻後仍保持尊嚴和勇氣。"},{"en":"A student can stand tall after failing a test by learning from mistakes.","zh":"學生測驗失敗後透過從錯誤中學習，仍可以昂然面對。"},{"en":"Standing tall does not mean pretending nothing hurts; it means not giving up.","zh":"昂然面對不代表假裝不痛，而是不放棄。"},{"en":"Real sports teach players to stand tall after public mistakes.","zh":"真實運動教球員在公開錯誤後仍昂然面對。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"miss the final shot","meaning":"錯失最後一球","examples":[{"en":"A player may miss the final shot but still learn from it.","zh":"球員可能錯失最後一球，但仍能從中學習。"},{"en":"To miss the final shot means to fail to score at the last important chance.","zh":"錯失最後一球，意思是在最後的重要機會中未能得分。"},{"en":"A basketball player who misses the final shot may feel responsible for the loss.","zh":"錯失最後一球的籃球員可能覺得自己要為落敗負責。"},{"en":"Missing the final shot can teach pressure, humility, and recovery.","zh":"錯失最後一球可以教導壓力、謙遜和恢復。"},{"en":"Real sports create moments where failure feels real but also teaches growth.","zh":"真實運動創造失敗感覺真實但也能教人成長的時刻。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"shooting technique","meaning":"射門技巧","examples":[{"en":"A teenager learns more than shooting technique from football.","zh":"青少年從足球學到的不只是射門技巧。"},{"en":"Shooting technique means the skill of kicking or hitting a ball towards the goal accurately and powerfully.","zh":"射門技巧，意思是準確而有力地把球踢向或擊向球門的技能。"},{"en":"A football coach may teach shooting technique by correcting foot position.","zh":"足球教練可能透過糾正腳的位置來教授射門技巧。"},{"en":"Sport teaches technique, but also patience, teamwork, and courage.","zh":"運動教技巧，也教耐性、團隊合作和勇氣。"},{"en":"The writer says real sport gives lessons beyond shooting technique.","zh":"作者說真實運動帶來超越射門技巧的課題。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"patience when the team is losing","meaning":"球隊落後時的耐性","examples":[{"en":"Real sport teaches patience when the team is losing.","zh":"真實運動教導球隊落後時的耐性。"},{"en":"Patience when the team is losing means staying calm and continuing to play even when behind.","zh":"球隊落後時的耐性，意思是在比分落後時仍保持冷靜並繼續比賽。"},{"en":"A player shows patience when the team is losing by following the plan instead of panicking.","zh":"球隊落後時，球員仍跟隨計劃而不是恐慌，就是表現耐性。"},{"en":"Losing situations test character because frustration can easily take over.","zh":"落後情況考驗品格，因為挫敗感很容易接管。"},{"en":"Real sports teach patience by making players continue under pressure.","zh":"真實運動透過要求球員在壓力下繼續，教導耐性。"}],"source":"2012 Q2.pdf","sourcePage":10},{"front":"courage when stronger players challenge him","meaning":"面對較強球員挑戰時的勇氣","examples":[{"en":"Sport teaches courage when stronger players challenge him.","zh":"運動教導他面對較強球員挑戰時的勇氣。"},{"en":"Courage when stronger players challenge him means bravery in facing people who seem more skilled or powerful.","zh":"面對較強球員挑戰時的勇氣，意思是面對看似更有技巧或更有力量的人時仍勇敢。"},{"en":"A beginner shows courage when stronger players challenge him but he keeps trying.","zh":"當較強球員挑戰初學者，而他仍繼續嘗試，就是表現勇氣。"},{"en":"Real opponents help young players learn not to fear difficulty.","zh":"真正對手幫助年輕球員學會不害怕困難。"},{"en":"Sport teaches courage because challenge cannot simply be paused or switched off.","zh":"運動教導勇氣，因為挑戰不能簡單暫停或關掉。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"humility when someone else scores","meaning":"別人入球時的謙遜","examples":[{"en":"Sport teaches humility when someone else scores.","zh":"運動教導別人入球時的謙遜。"},{"en":"Humility when someone else scores means accepting another person’s success without jealousy or showing off.","zh":"別人入球時的謙遜，意思是接受他人的成功，而不嫉妒或炫耀。"},{"en":"A player shows humility by celebrating a teammate’s goal.","zh":"球員慶祝隊友入球，就是表現謙遜。"},{"en":"Team sports teach that not every good moment belongs to one person.","zh":"團隊運動教人不是每個精彩時刻都屬於一個人。"},{"en":"Real sport teaches humility because players must share credit with others.","zh":"真實運動教導謙遜，因為球員必須與別人分享功勞。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"virtual match","meaning":"虛擬賽事","examples":[{"en":"A virtual match may connect players online.","zh":"虛擬賽事可能在網上連繫玩家。"},{"en":"A virtual match is a digital competition played through a screen or online system.","zh":"虛擬賽事，是透過螢幕或網上系統進行的數碼比賽。"},{"en":"Friends in different homes can join the same virtual match.","zh":"身處不同家中的朋友可以參加同一場虛擬賽事。"},{"en":"Virtual matches are convenient because players do not need to meet in one place.","zh":"虛擬賽事很方便，因為玩家不需要在同一地方見面。"},{"en":"A virtual match can connect people, but it may not create the same human contact as an in-person match.","zh":"虛擬賽事可以連繫人，但未必創造與實體比賽相同的人際接觸。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"connect players online","meaning":"在網上連繫玩家","examples":[{"en":"A virtual match may connect players online.","zh":"虛擬賽事可能在網上連繫玩家。"},{"en":"To connect players online means to let people play or communicate through the internet.","zh":"在網上連繫玩家，意思是讓人們透過互聯網一起玩或溝通。"},{"en":"An online game can connect players from different districts.","zh":"網上遊戲可以連繫來自不同地區的玩家。"},{"en":"Online connection is useful when friends cannot meet in person.","zh":"當朋友不能親身見面時，網上連繫很有用。"},{"en":"Virtual sports connect players online, but real sports add eye contact and shared space.","zh":"虛擬運動在網上連繫玩家，但真實運動加入眼神接觸和共享空間。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"in-person match","meaning":"實體比賽","examples":[{"en":"An in-person match creates stronger human connection.","zh":"實體比賽創造更強的人際連繫。"},{"en":"An in-person match is a real game where players meet face to face.","zh":"實體比賽，是球員面對面相遇的真實比賽。"},{"en":"A school football match is an in-person match because players share the same field.","zh":"學校足球賽是實體比賽，因為球員共享同一球場。"},{"en":"In-person matches create stronger memories because people experience pressure together.","zh":"實體比賽創造更強回憶，因為人們一起經歷壓力。"},{"en":"The writer values in-person matches for their teamwork, arguments, apologies, and laughter.","zh":"作者重視實體比賽，因為它有團隊合作、爭執、道歉和笑聲。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"eye contact","meaning":"眼神接觸","examples":[{"en":"An in-person match creates eye contact.","zh":"實體比賽創造眼神接觸。"},{"en":"Eye contact means looking directly at another person’s eyes.","zh":"眼神接觸，意思是直接看着另一個人的眼睛。"},{"en":"Players use eye contact to signal a pass or show understanding.","zh":"球員用眼神接觸來示意傳球或表示明白。"},{"en":"Eye contact builds connection because people feel seen and noticed.","zh":"眼神接觸建立連繫，因為人們感到被看見和注意。"},{"en":"Real sports create eye contact that virtual matches may not fully provide.","zh":"真實運動創造虛擬賽事未必能完全提供的眼神接觸。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"shared laughter","meaning":"共同笑聲","examples":[{"en":"Real sports create shared laughter and memories.","zh":"真實運動創造共同笑聲和回憶。"},{"en":"Shared laughter is laughter experienced together by a group of people.","zh":"共同笑聲，是一群人一起經歷的笑聲。"},{"en":"Teammates may share laughter after a funny mistake during practice.","zh":"隊友可能在練習中因有趣錯誤而共享笑聲。"},{"en":"Shared laughter helps teams feel closer and less afraid of failure.","zh":"共同笑聲幫助隊伍感覺更親近，並較不害怕失敗。"},{"en":"Real sports create shared laughter because players meet, struggle, and recover together.","zh":"真實運動創造共同笑聲，因為球員一起相遇、掙扎和恢復。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"arguments, apologies and memories","meaning":"爭執、道歉和回憶","examples":[{"en":"An in-person match creates arguments, apologies and memories.","zh":"實體比賽創造爭執、道歉和回憶。"},{"en":"Arguments, apologies and memories are disagreements, moments of making peace, and experiences people remember later.","zh":"爭執、道歉和回憶，是意見不合、和解時刻，以及人們日後記住的經驗。"},{"en":"Teammates may argue about a mistake, apologise afterwards, and remember the lesson.","zh":"隊友可能因一次錯誤爭執，之後道歉，並記住這個課題。"},{"en":"These moments teach communication because people must repair relationships.","zh":"這些時刻教導溝通，因為人們必須修補關係。"},{"en":"Real sport creates human stories that are messier and richer than online play.","zh":"真實運動創造比網上遊戲更複雜、更豐富的人類故事。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"there is more to sport than","meaning":"運動不止是……","examples":[{"en":"There is more to sport than movement.","zh":"運動不止是活動身體。"},{"en":"There is more to sport than something means sport includes other important parts beyond that one thing.","zh":"運動不止是某事，意思是運動除了那件事外，還包括其他重要部分。"},{"en":"There is more to school than exams because friendship and character also matter.","zh":"學校不止是考試，因為友誼和品格也重要。"},{"en":"This phrase helps writers show deeper value beyond the obvious feature.","zh":"這個短語幫助作者顯示表面特徵以外的更深價值。"},{"en":"The writer says sport is about movement, but also community, courage, and respect.","zh":"作者說運動關乎活動身體，也關乎社群、勇氣和尊重。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"community","meaning":"社群；群體連結","examples":[{"en":"Real sport creates community.","zh":"真實運動創造社群。"},{"en":"Community means a sense of belonging and connection among people.","zh":"社群或群體連結，意思是人與人之間的歸屬感和連繫。"},{"en":"A school team creates community when players support each other after losses.","zh":"當學校隊伍在落敗後互相支持，它就創造社群。"},{"en":"Community grows through shared practice, shared goals, and shared memories.","zh":"社群透過共同練習、共同目標和共同回憶而成長。"},{"en":"Real sports create community because players and supporters meet in the same space.","zh":"真實運動創造社群，因為球員和支持者在同一空間相遇。"}],"source":"2012 Q2.pdf","sourcePage":11},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, virtual sports should be welcomed but not worshipped.","zh":"總括而言，虛擬運動應被歡迎，但不應被崇拜。"},{"en":"All things considered means after thinking about all important points together.","zh":"總括而言，意思是在一起考慮所有重要因素之後。"},{"en":"All things considered, online lessons are useful but cannot replace every classroom experience.","zh":"總括而言，網上課堂有用，但不能取代每一種課室經驗。"},{"en":"Writers use this phrase before giving a balanced final judgement.","zh":"作者在作出平衡的最終判斷前會使用這個短語。"},{"en":"All things considered, virtual sports are helpful tools but not the whole answer to fitness.","zh":"總括而言，虛擬運動是有幫助的工具，但不是健身的完整答案。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"be welcomed, but not worshipped","meaning":"應被歡迎，但不應被崇拜","examples":[{"en":"Virtual sports should be welcomed, but not worshipped.","zh":"虛擬運動應被歡迎，但不應被崇拜。"},{"en":"Be welcomed, but not worshipped means something should be accepted positively without being treated as perfect.","zh":"應被歡迎但不應被崇拜，意思是某事應被正面接受，但不應被視為完美。"},{"en":"New technology should be welcomed, but not worshipped, because it still has limits.","zh":"新科技應被歡迎，但不應被崇拜，因為它仍有限制。"},{"en":"This phrase gives a balanced attitude: useful, but not magical.","zh":"這個短語給出平衡態度：有用，但不是神奇。"},{"en":"The writer welcomes virtual sports while refusing to treat them as better than real sport.","zh":"作者歡迎虛擬運動，但拒絕把它們視為比真實運動更好。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"a bridge, not the destination","meaning":"是橋樑，不是終點","examples":[{"en":"Virtual sports are a bridge, not the destination.","zh":"虛擬運動是橋樑，不是終點。"},{"en":"A bridge, not the destination means something helps people move towards a goal but is not the final goal itself.","zh":"是橋樑，不是終點，意思是某事幫助人走向目標，但本身不是最終目標。"},{"en":"A beginner class is a bridge, not the destination, for learning a language.","zh":"初級課程是學習語言的橋樑，不是終點。"},{"en":"Bridges are useful because they help people cross from fear to action.","zh":"橋樑有用，因為它幫助人從恐懼走向行動。"},{"en":"Virtual sports should lead people towards real participation, not stop them there.","zh":"虛擬運動應引導人走向真正參與，而不是停在那裏。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"get children off the sofa","meaning":"令孩子離開梳化","examples":[{"en":"Parents can use virtual sports to get children off the sofa.","zh":"家長可以使用虛擬運動令孩子離開梳化。"},{"en":"To get children off the sofa means to encourage them to stop sitting passively and become active.","zh":"令孩子離開梳化，意思是鼓勵他們停止被動坐着並變得活躍。"},{"en":"A family dance game can get children off the sofa on a rainy afternoon.","zh":"家庭跳舞遊戲可以在雨天下午令孩子離開梳化。"},{"en":"Getting children off the sofa is a first step towards healthier habits.","zh":"令孩子離開梳化是走向更健康習慣的第一步。"},{"en":"Virtual sports can help children begin moving before they join outdoor games.","zh":"虛擬運動可以在孩子加入戶外遊戲前幫助他們開始活動。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"on rainy days","meaning":"在雨天","examples":[{"en":"Schools can use virtual sports on rainy days.","zh":"學校可以在雨天使用虛擬運動。"},{"en":"On rainy days means during days when rain makes outdoor activities difficult.","zh":"在雨天，意思是在下雨令戶外活動困難的日子。"},{"en":"On rainy days, PE teachers may move lessons indoors.","zh":"在雨天，體育老師可能把課堂移到室內。"},{"en":"Virtual sports are useful on rainy days because students can still move safely.","zh":"虛擬運動在雨天很有用，因為學生仍可以安全活動。"},{"en":"Rainy-day use shows that virtual sports can support, not replace, real physical education.","zh":"雨天使用顯示虛擬運動可以支援，而不是取代，真正體育教育。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"build confidence","meaning":"建立信心","examples":[{"en":"Beginners can use virtual sports to build confidence.","zh":"初學者可以使用虛擬運動來建立信心。"},{"en":"To build confidence means to gradually become more sure and less afraid.","zh":"建立信心，意思是逐漸變得更肯定和較不害怕。"},{"en":"A student can build confidence by practising basketball skills before joining a team.","zh":"學生可以在加入隊伍前練習籃球技巧來建立信心。"},{"en":"Confidence grows when people experience small successes.","zh":"當人們經歷小成功，信心就會增長。"},{"en":"Virtual sports build confidence by letting beginners practise without public pressure.","zh":"虛擬運動讓初學者在沒有公開壓力下練習，從而建立信心。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"the next step","meaning":"下一步","examples":[{"en":"The next step should be towards real participation.","zh":"下一步應該走向真正參與。"},{"en":"The next step means the action that should follow after the first stage.","zh":"下一步，意思是第一階段之後應跟着做的行動。"},{"en":"After learning basic swimming movements, the next step may be joining a beginner class.","zh":"學會基本游泳動作後，下一步可能是參加初學者課程。"},{"en":"Good starting points should lead to another useful step.","zh":"好的起點應引向另一個有用步驟。"},{"en":"After virtual sports, the writer believes the next step is trying real activities.","zh":"作者認為在虛擬運動之後，下一步是嘗試真實活動。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"real participation","meaning":"真正參與","examples":[{"en":"Students should move from virtual sports to real participation.","zh":"學生應從虛擬運動走向真正參與。"},{"en":"Real participation means taking part in actual physical activities with real spaces, people, and effort.","zh":"真正參與，意思是參加有真實空間、人群和努力的實際身體活動。"},{"en":"Joining a school badminton game is real participation.","zh":"參加學校羽毛球比賽就是真正參與。"},{"en":"Real participation helps students experience teamwork, pressure, and physical challenge.","zh":"真正參與幫助學生經歷團隊合作、壓力和身體挑戰。"},{"en":"Virtual sports are most useful when they lead beginners towards real participation.","zh":"當虛擬運動引導初學者走向真正參與，它們最有用。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"joining a school team","meaning":"加入校隊","examples":[{"en":"Real participation may mean joining a school team.","zh":"真正參與可能意味着加入校隊。"},{"en":"Joining a school team means becoming part of a group that trains or competes for the school.","zh":"加入校隊，意思是成為代表學校訓練或比賽的團隊一員。"},{"en":"A student may join a school team after gaining confidence in basic skills.","zh":"學生在基本技巧上建立信心後，可能加入校隊。"},{"en":"School teams teach discipline because members must practise regularly.","zh":"校隊教導紀律，因為成員必須定期練習。"},{"en":"Virtual sports may help beginners prepare for joining a school team later.","zh":"虛擬運動可能幫助初學者為日後加入校隊作準備。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"playing badminton with friends","meaning":"跟朋友打羽毛球","examples":[{"en":"Students can start by playing badminton with friends.","zh":"學生可以由跟朋友打羽毛球開始。"},{"en":"Playing badminton with friends means enjoying a real racket sport together in a relaxed way.","zh":"跟朋友打羽毛球，意思是以輕鬆方式一起享受真正球拍運動。"},{"en":"A beginner may feel less nervous playing badminton with friends than joining a competition.","zh":"初學者跟朋友打羽毛球，可能比參加比賽較不緊張。"},{"en":"Friendly games help students practise without too much pressure.","zh":"友善比賽幫助學生在壓力不太大的情況下練習。"},{"en":"Playing badminton with friends is a simple step from virtual movement to real sport.","zh":"跟朋友打羽毛球是由虛擬活動走向真實運動的簡單一步。"}],"source":"2012 Q2.pdf","sourcePage":12},{"front":"trying a new sport","meaning":"嘗試一項新運動","examples":[{"en":"Beginners should try a new sport without fear.","zh":"初學者應不害怕地嘗試一項新運動。"},{"en":"Trying a new sport means taking part in a sport one has not practised before.","zh":"嘗試一項新運動，意思是參與自己以前未練習過的運動。"},{"en":"A student may try a new sport such as volleyball, fencing, or swimming.","zh":"學生可能嘗試一項新運動，例如排球、劍擊或游泳。"},{"en":"Trying new sports helps people discover abilities they did not know they had.","zh":"嘗試新運動幫助人們發現自己不知道擁有的能力。"},{"en":"Virtual sports can give beginners enough confidence to try a new sport in real life.","zh":"虛擬運動可以給初學者足夠信心，在現實中嘗試一項新運動。"}],"source":"2012 Q2.pdf","sourcePage":13},{"front":"without fear of looking foolish","meaning":"不怕看起來笨拙","examples":[{"en":"Students should try new sports without fear of looking foolish.","zh":"學生應不怕看起來笨拙地嘗試新運動。"},{"en":"Without fear of looking foolish means not worrying too much about appearing awkward or making mistakes.","zh":"不怕看起來笨拙，意思是不過分擔心自己顯得尷尬或犯錯。"},{"en":"Beginners learn faster when they can practise without fear of looking foolish.","zh":"當初學者可以不怕看起來笨拙地練習，他們學得更快。"},{"en":"Everyone looks awkward at first when learning a new physical skill.","zh":"每個人在學習新身體技能時，一開始都會顯得笨拙。"},{"en":"A supportive sports culture lets students try, fail, laugh, and improve.","zh":"支持性的運動文化讓學生嘗試、失敗、大笑和進步。"}],"source":"2012 Q2.pdf","sourcePage":13},{"front":"a resounding no","meaning":"一個響亮的「不」","examples":[{"en":"The writer does not give a resounding no to virtual sports.","zh":"作者並沒有對虛擬運動給出一個響亮的「不」。"},{"en":"A resounding no is a very strong and clear rejection.","zh":"一個響亮的「不」，是非常強烈和清晰的否定。"},{"en":"Should students stop all real exercise? The answer should be a resounding no.","zh":"學生應停止所有真實運動嗎？答案應是一個響亮的「不」。"},{"en":"This phrase makes disagreement firm and unmistakable.","zh":"這個短語令反對立場堅定而明確。"},{"en":"The writer does not reject virtual sports completely because they can help beginners.","zh":"作者沒有完全否定虛擬運動，因為它們可以幫助初學者。"}],"source":"2012 Q2.pdf","sourcePage":13},{"front":"a qualified yes","meaning":"有保留的「是」","examples":[{"en":"The writer gives virtual sports a qualified yes.","zh":"作者對虛擬運動給出有保留的「是」。"},{"en":"A qualified yes means agreement with conditions or limits.","zh":"有保留的「是」，意思是帶有條件或限制的同意。"},{"en":"A teacher may give a qualified yes to using phones if students use them only for research.","zh":"如果學生只用手機做資料搜集，老師可能給出有保留的「是」。"},{"en":"This phrase shows support that is careful, not blind.","zh":"這個短語顯示支持是謹慎的，而不是盲目的。"},{"en":"The writer gives virtual sports a qualified yes because they are useful as a bridge, not a final destination.","zh":"作者對虛擬運動給出有保留的「是」，因為它們作為橋樑有用，但不是終點。"}],"source":"2012 Q2.pdf","sourcePage":13},{"front":"step outside","meaning":"走到戶外；踏出去","examples":[{"en":"Virtual sports may open the door, but players should then step outside.","zh":"虛擬運動可能打開大門，但玩家之後應走到戶外。"},{"en":"To step outside means to leave the indoor or digital space and enter the real world.","zh":"走到戶外或踏出去，意思是離開室內或數碼空間，進入真實世界。"},{"en":"After practising with a fitness video, a student may step outside for a walk.","zh":"跟着健身影片練習後，學生可能走到戶外散步。"},{"en":"Stepping outside helps people experience real space, weather, and movement.","zh":"走到戶外幫助人們經歷真實空間、天氣和活動。"},{"en":"The writer says virtual sports should encourage players to step outside and try real activities.","zh":"作者說虛擬運動應鼓勵玩家踏出去並嘗試真實活動。"}],"source":"2012 Q2.pdf","sourcePage":13},{"front":"where sport truly begins","meaning":"運動真正開始的地方","examples":[{"en":"Outside the screen is where sport truly begins.","zh":"屏幕之外才是運動真正開始的地方。"},{"en":"Where sport truly begins means the place or moment where real physical challenge, teamwork, and experience start.","zh":"運動真正開始的地方，意思是真正身體挑戰、團隊合作和經驗開始的地方或時刻。"},{"en":"A game may teach rules, but the playground is where sport truly begins.","zh":"遊戲可能教規則，但操場才是運動真正開始的地方。"},{"en":"Sport truly begins when the body faces real space, real people, and real pressure.","zh":"當身體面對真實空間、真人和真實壓力，運動才真正開始。"},{"en":"The writer ends by suggesting that virtual sports should lead us beyond the screen.","zh":"作者在結尾暗示，虛擬運動應帶領我們走出屏幕。"}],"source":"2012 Q2.pdf","sourcePage":13}],"dse/writing/part-b/2012/Q3":[{"front":"a break from learning","meaning":"學習的休息；脫離學習","examples":[{"en":"Drama is not a break from learning.","zh":"戲劇並不是脫離學習的休息。"},{"en":"“A break from learning” means a period when students stop learning and simply relax or do something unrelated to study.","zh":"「a break from learning」表示學生暫停學習，只是休息或進行與學習無關的活動。"},{"en":"A game can become a break from learning if it has no connection with the lesson objectives.","zh":"如果一個遊戲與課堂目標完全無關，它便可能變成脫離學習的休息。"},{"en":"Drama may look playful, but students can still be analysing ideas and practising important skills.","zh":"戲劇看起來可能像玩樂，但學生仍可以分析概念和練習重要技能。"},{"en":"An activity is not a break from learning simply because students are moving, speaking or enjoying themselves.","zh":"一項活動不會只因學生在走動、說話或享受其中，就代表它脫離了學習。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"learning in action","meaning":"實踐中的學習","examples":[{"en":"Drama is learning in action.","zh":"戲劇是實踐中的學習。"},{"en":"“Learning in action” means understanding and practising ideas by actively doing something rather than only reading or listening.","zh":"「learning in action」表示透過實際行動理解和練習概念，而不只是閱讀或聆聽。"},{"en":"A science experiment is learning in action because students test ideas themselves.","zh":"科學實驗是實踐中的學習，因為學生親自測試想法。"},{"en":"Role-play becomes learning in action when students apply concepts to realistic situations.","zh":"當學生把概念應用到真實情境，角色扮演便成為實踐中的學習。"},{"en":"Learning in action can make abstract ideas easier to remember because students experience them directly.","zh":"實踐中的學習讓學生直接經歷概念，因此抽象想法可能更容易記住。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"understand why","meaning":"理解為甚麼","examples":[{"en":"I understand why some parents worry about drama lessons.","zh":"我理解為甚麼有些家長擔心戲劇課。"},{"en":"To understand why something happens means to recognise the reason behind another person’s feeling, action or concern.","zh":"「understand why」表示明白某人的感受、行動或憂慮背後的原因。"},{"en":"I understand why students feel nervous before an important examination.","zh":"我理解為甚麼學生在重要考試前會緊張。"},{"en":"Teachers can disagree with parents while still understanding why they have concerns.","zh":"老師可以不同意家長，但仍理解他們為甚麼有憂慮。"},{"en":"Understanding why someone thinks differently is often the first step towards a balanced discussion.","zh":"理解別人為甚麼有不同想法，往往是平衡討論的第一步。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"doing drama","meaning":"上戲劇活動課","examples":[{"en":"Some parents worry when they hear that a class is doing drama.","zh":"有些家長聽到班上正在上戲劇活動課時會擔心。"},{"en":"“Doing drama” means taking part in acting, role-play or other drama-based classroom activities.","zh":"「doing drama」表示參與演戲、角色扮演或其他以戲劇為本的課堂活動。"},{"en":"Students may be doing drama when they act out a conflict from a story.","zh":"學生把故事中的衝突演出來時，就是在進行戲劇活動。"},{"en":"Doing drama can involve careful reading, discussion and rehearsal as well as performance.","zh":"戲劇活動除了表演，也可以包括仔細閱讀、討論和排練。"},{"en":"A class doing drama may be learning seriously even if the room is noisier than usual.","zh":"即使課室比平時嘈吵，進行戲劇活動的班級仍可能在認真學習。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"in their eyes","meaning":"在他們眼中","examples":[{"en":"In their eyes, a lesson should look quiet and traditional.","zh":"在他們眼中，課堂應該看起來安靜而傳統。"},{"en":"“In their eyes” means according to how those people see, judge or understand the situation.","zh":"「in their eyes」表示按照那些人看待、判斷或理解事情的方式。"},{"en":"In her parents’ eyes, getting enough sleep is more important than staying up to revise.","zh":"在她父母眼中，睡眠充足比熬夜溫習更重要。"},{"en":"An active classroom may look disorderly in some parents’ eyes even when learning is taking place.","zh":"在一些家長眼中，活躍課堂可能看起來很混亂，即使學習其實正在進行。"},{"en":"The phrase helps explain another person’s viewpoint without saying that viewpoint is necessarily correct.","zh":"這個片語可以解釋別人的觀點，而不代表該觀點一定正確。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"sitting upright","meaning":"坐得筆直","examples":[{"en":"Some parents expect students to be sitting upright.","zh":"有些家長期望學生坐得筆直。"},{"en":"Sitting upright means sitting with the back straight rather than bending, lying back or moving around.","zh":"坐得筆直表示背部挺直地坐着，而不是彎腰、後靠或四處走動。"},{"en":"The teacher asked everyone to sit upright during the formal photograph.","zh":"拍正式照片時，老師叫大家坐得筆直。"},{"en":"Sitting upright may look attentive, but physical posture alone does not prove that a student is learning.","zh":"坐得筆直可能看起來很專心，但姿勢本身不能證明學生正在學習。"},{"en":"Active lessons may require students to stand or move instead of sitting upright for the whole period.","zh":"活動式課堂可能要求學生站立或走動，而不是整堂坐得筆直。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"copying notes","meaning":"抄筆記","examples":[{"en":"Some parents think lessons should involve copying notes.","zh":"有些家長認為課堂應包括抄筆記。"},{"en":"Copying notes means writing down information that a teacher, textbook or board has already provided.","zh":"抄筆記是把老師、課本或黑板已提供的資料寫下來。"},{"en":"Students copied notes from the board before discussing the topic.","zh":"學生先從黑板抄筆記，然後討論題目。"},{"en":"Copying notes can help record information, but it does not always show deep understanding.","zh":"抄筆記可以幫助記錄資料，但不一定代表深入理解。"},{"en":"Good learning may combine note-taking with discussion, practice and application.","zh":"良好學習可以把筆記、討論、練習和應用結合起來。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"preparing for tests","meaning":"準備測驗","examples":[{"en":"Students are often expected to be preparing for tests.","zh":"學生常被期望正在準備測驗。"},{"en":"Preparing for tests means studying, practising and reviewing material before an assessment.","zh":"準備測驗表示在評核前溫習、練習和重溫學習內容。"},{"en":"She spent the weekend preparing for tests in English and mathematics.","zh":"她整個週末都在準備英文和數學測驗。"},{"en":"Drama can contribute to test preparation if it helps students understand ideas they later need to explain in writing.","zh":"如果戲劇幫助學生理解之後要用文字解釋的概念，它也可以有助準備測驗。"},{"en":"Preparing for tests is useful, but education also involves communication, judgement and application.","zh":"準備測驗很有用，但教育也包括溝通、判斷和應用能力。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"incorporating","meaning":"加入；融入","examples":[{"en":"More teachers are incorporating drama into lessons.","zh":"更多老師正在把戲劇融入課堂。"},{"en":"Incorporating something means adding it as an integrated part of a larger activity or system.","zh":"「incorporating」表示把某事加入較大的活動或系統，成為其中一個整合部分。"},{"en":"The teacher incorporated short videos into the history lesson.","zh":"老師把短片融入歷史課。"},{"en":"Drama is most useful when teachers incorporate it into clear learning objectives.","zh":"當老師把戲劇融入清楚的學習目標，它會最有用。"},{"en":"Incorporating a new method does not mean replacing every traditional method.","zh":"加入新方法並不代表要取代所有傳統方法。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"role-play","meaning":"角色扮演","examples":[{"en":"Teachers are incorporating role-play into lessons.","zh":"老師正在把角色扮演融入課堂。"},{"en":"Role-play is an activity in which people act as particular characters or take on different positions in a situation.","zh":"角色扮演是參與者扮演特定人物或在某情況中擔任不同角色的活動。"},{"en":"Students used role-play to practise a conversation between a customer and a shop assistant.","zh":"學生用角色扮演練習顧客與店員之間的對話。"},{"en":"Role-play helps learners explore how different people may think and respond.","zh":"角色扮演幫助學習者探索不同人物可能如何思考和回應。"},{"en":"A well-designed role-play can turn an abstract issue into a situation students have to deal with.","zh":"設計良好的角色扮演可以把抽象問題變成學生必須面對的情境。"}],"source":"2012 Q3.pdf","sourcePage":1},{"front":"hot-seating","meaning":"熱座提問","examples":[{"en":"Hot-seating can help students understand characters more deeply.","zh":"熱座提問可以幫助學生更深入理解角色。"},{"en":"Hot-seating is a drama activity in which one person stays in character while others ask them questions.","zh":"熱座提問是一種戲劇活動，一名學生保持角色身分，其他人向他提問。"},{"en":"A student playing Macbeth sat in the hot seat and answered questions about his fears.","zh":"扮演Macbeth的學生坐上熱座，回答關於角色恐懼的問題。"},{"en":"Hot-seating forces students to think about a character’s motives rather than only repeat the text.","zh":"熱座提問迫使學生思考角色動機，而不只是重複原文。"},{"en":"Answering unexpected questions in character can deepen interpretation and empathy.","zh":"以角色身分回答意料之外的問題，可以加深理解和同理心。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"short performances","meaning":"簡短表演","examples":[{"en":"Teachers use short performances to support learning.","zh":"老師使用簡短表演支援學習。"},{"en":"Short performances are brief acted scenes used to present, practise or explore an idea.","zh":"簡短表演是用來呈現、練習或探索某個概念的短場景。"},{"en":"Each group gave a two-minute performance showing a conflict between friends.","zh":"每組進行兩分鐘表演，展示朋友之間的衝突。"},{"en":"Short performances can fit into an ordinary lesson without taking the whole period.","zh":"簡短表演可以融入普通課堂，而不用佔用整節時間。"},{"en":"A brief scene can reveal whether students truly understand a concept well enough to apply it.","zh":"一個短場景可以顯示學生是否真正理解概念，並能把它應用出來。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"considering drama not to entertain students, but to help them","meaning":"考慮使用戲劇不是為了娛樂學生，而是為了幫助他們","examples":[{"en":"Schools are considering drama not to entertain students, but to help them learn.","zh":"學校考慮使用戲劇，不是為了娛樂學生，而是為了幫助他們學習。"},{"en":"This structure means the main purpose of drama is educational rather than simply providing enjoyment.","zh":"這個句式表示戲劇的主要目的在教育，而不只是提供娛樂。"},{"en":"Teachers may use games not merely to make students happy, but to practise vocabulary.","zh":"老師使用遊戲可能不是單純令學生開心，而是練習詞彙。"},{"en":"Drama can be enjoyable while still being designed mainly to develop understanding and communication.","zh":"戲劇可以令人享受，同時主要仍是為了發展理解和溝通能力。"},{"en":"Enjoyment and learning are not opposites when an activity has a clear educational purpose.","zh":"當活動有清楚教育目的，享受與學習並不互相排斥。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"understand ideas more deeply","meaning":"更深入理解概念","examples":[{"en":"Drama helps students understand ideas more deeply.","zh":"戲劇幫助學生更深入理解概念。"},{"en":"To understand ideas more deeply means to move beyond knowing definitions and see how the ideas work in real situations.","zh":"更深入理解概念表示不只知道定義，也明白概念在真實情況如何運作。"},{"en":"Debating a moral problem can help students understand fairness more deeply.","zh":"辯論道德問題可以幫助學生更深入理解公平。"},{"en":"Acting out a conflict helps learners see consequences that may not be obvious on the page.","zh":"演出衝突可以讓學習者看見書本上未必明顯的後果。"},{"en":"Deeper understanding often comes when students explain, apply and test an idea themselves.","zh":"當學生自己解釋、應用和測試概念，通常會得到更深入理解。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"remember them more vividly","meaning":"更生動地記住它們","examples":[{"en":"Drama helps students remember ideas more vividly.","zh":"戲劇幫助學生更生動地記住概念。"},{"en":"To remember something more vividly means to recall it in a clearer, stronger and more detailed way.","zh":"更生動地記住某事，表示日後能更清楚、更強烈和更具細節地回想。"},{"en":"I remembered the history topic more vividly after visiting the museum.","zh":"參觀博物館後，我更生動地記住那個歷史主題。"},{"en":"Acting out an idea can create sights, words and emotions that make it easier to recall later.","zh":"把概念演出來可以創造畫面、說話和情緒，令日後更容易回想。"},{"en":"Vivid memories often form when learning involves several senses and active participation.","zh":"當學習涉及多種感官和主動參與，記憶通常會更鮮明。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"speak with greater confidence","meaning":"更有信心地說話","examples":[{"en":"Drama helps students speak with greater confidence.","zh":"戲劇幫助學生更有信心地說話。"},{"en":"To speak with greater confidence means to express yourself more clearly and with less fear or hesitation.","zh":"更有信心地說話表示表達得更清楚，而且較少恐懼或猶豫。"},{"en":"Repeated presentations helped her speak with greater confidence in class.","zh":"反覆進行簡報令她在課堂上更有信心地說話。"},{"en":"Drama gives students many low-risk opportunities to practise speaking in front of others.","zh":"戲劇給學生很多低風險機會，在其他人面前練習說話。"},{"en":"Confidence grows when learners discover that imperfect speaking does not lead to disaster.","zh":"當學習者發現說得不完美也不會造成災難，自信便會增加。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"my stance is clear","meaning":"我的立場很清楚","examples":[{"en":"My stance is clear: drama can be an effective way to learn.","zh":"我的立場很清楚：戲劇可以是一種有效的學習方法。"},{"en":"“My stance is clear” means my opinion or position on the issue is definite and easy to understand.","zh":"「my stance is clear」表示我對問題的意見或立場明確而容易理解。"},{"en":"My stance is clear: schools should not ignore student mental health.","zh":"我的立場很清楚：學校不應忽視學生心理健康。"},{"en":"Stating a clear stance helps readers understand the argument the writer will defend.","zh":"清楚表明立場，幫助讀者明白作者之後會支持甚麼論點。"},{"en":"A strong stance should still be supported by reasons and evidence.","zh":"清楚的立場仍應由理由和證據支持。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"when carefully planned","meaning":"在經過仔細規劃時","examples":[{"en":"Drama is effective when carefully planned.","zh":"戲劇在經過仔細規劃時會很有效。"},{"en":"“When carefully planned” means if the activity has been designed thoughtfully with clear goals and structure.","zh":"「when carefully planned」表示活動經過周詳設計，並有清楚目標和結構。"},{"en":"Group work can be very useful when carefully planned.","zh":"小組活動在經過仔細規劃時可以非常有用。"},{"en":"Drama is less likely to become noisy or unfocused when carefully planned.","zh":"戲劇經仔細規劃後，較不容易變得嘈吵或失去焦點。"},{"en":"Planning turns an enjoyable activity into purposeful learning.","zh":"規劃可以把有趣活動轉化成有目的的學習。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"one of the most effective ways to","meaning":"最有效的……方法之一","examples":[{"en":"Drama is one of the most effective ways to learn.","zh":"戲劇是最有效的學習方法之一。"},{"en":"“One of the most effective ways to” means one method among a small group of methods that work particularly well.","zh":"「one of the most effective ways to」表示在幾種特別有效的方法之中，其中一種。"},{"en":"Regular reading is one of the most effective ways to expand vocabulary.","zh":"定期閱讀是擴闊詞彙最有效的方法之一。"},{"en":"Practising realistic conversations is one of the most effective ways to build speaking confidence.","zh":"練習真實對話是建立說話自信最有效的方法之一。"},{"en":"This phrase makes a strong claim but does not say there is only one good method.","zh":"這個片語提出強烈主張，但沒有說只有一種好方法。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"the opposite of","meaning":"……的相反","examples":[{"en":"Drama is not the opposite of serious study.","zh":"戲劇並不是認真學習的相反。"},{"en":"“The opposite of” means completely different from or directly contrary to something else.","zh":"「the opposite of」表示與另一件事完全不同或直接相反。"},{"en":"Asking for help is not the opposite of independence.","zh":"尋求幫助並不是獨立的相反。"},{"en":"Enjoyment is not necessarily the opposite of serious learning.","zh":"享受不一定是認真學習的相反。"},{"en":"This phrase is useful for challenging a false either-or choice.","zh":"這個片語有助挑戰錯誤的二選一想法。"}],"source":"2012 Q3.pdf","sourcePage":2},{"front":"serious study","meaning":"認真學習","examples":[{"en":"Drama is not the opposite of serious study.","zh":"戲劇並不是認真學習的相反。"},{"en":"Serious study is focused learning that requires thought, effort and attention.","zh":"認真學習是需要思考、努力和專注的學習。"},{"en":"Preparing a research report involves serious study.","zh":"準備研究報告涉及認真學習。"},{"en":"Serious study can happen through discussion and performance as well as reading and writing.","zh":"認真學習既可以透過閱讀和寫作，也可以透過討論和表演進行。"},{"en":"What makes study serious is the quality of thinking, not whether the classroom is silent.","zh":"學習是否認真取決於思考質素，而不是課室是否安靜。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"a bridge between","meaning":"……之間的橋樑","examples":[{"en":"Drama is a bridge between knowledge and experience.","zh":"戲劇是知識與經驗之間的橋樑。"},{"en":"“A bridge between A and B” is a metaphor for something that connects two different areas or ideas.","zh":"「a bridge between A and B」是一個比喻，表示連接兩個不同領域或概念的東西。"},{"en":"Work experience can be a bridge between school and employment.","zh":"工作經驗可以成為學校與就業之間的橋樑。"},{"en":"Drama connects what students know intellectually with what they feel and do in a situation.","zh":"戲劇把學生理性知道的東西與他們在情境中的感受和行動連接起來。"},{"en":"A useful learning method often acts as a bridge between theory and practice.","zh":"有用的學習方法常成為理論與實踐之間的橋樑。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"knowledge and experience","meaning":"知識與經驗","examples":[{"en":"Drama connects knowledge and experience.","zh":"戲劇把知識與經驗連接起來。"},{"en":"Knowledge is what people know and understand, while experience is what they learn through doing or living through something.","zh":"知識是人知道和理解的內容，而經驗則是透過親身做或經歷而學到的東西。"},{"en":"Medical training combines classroom knowledge and practical experience.","zh":"醫療訓練結合課堂知識和實際經驗。"},{"en":"Students may know the definition of empathy but understand it better through experience.","zh":"學生可以知道同理心的定義，但透過經驗會理解得更好。"},{"en":"Learning becomes stronger when knowledge and experience support one another.","zh":"當知識與經驗互相支持，學習會更穩固。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"turns abstract knowledge into","meaning":"把抽象知識轉化為","examples":[{"en":"Drama turns abstract knowledge into lived understanding.","zh":"戲劇把抽象知識轉化為親身體會得來的理解。"},{"en":"To turn abstract knowledge into something means to transform ideas that exist mainly in words or theory into a more concrete form.","zh":"把抽象知識轉化為某物，表示把主要存在於文字或理論中的概念變成更具體的形式。"},{"en":"A science experiment turns abstract knowledge into visible results.","zh":"科學實驗把抽象知識轉化成看得見的結果。"},{"en":"Role-play can turn a definition of peer pressure into a situation students actually have to respond to.","zh":"角色扮演可以把同輩壓力的定義轉化成學生真的要回應的情境。"},{"en":"Transformation from theory to experience can make meaning clearer.","zh":"由理論轉化為經驗，可以令意思更清楚。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"abstract knowledge","meaning":"抽象知識","examples":[{"en":"Drama helps students understand abstract knowledge.","zh":"戲劇幫助學生理解抽象知識。"},{"en":"Abstract knowledge is information about ideas or concepts that cannot always be directly seen or touched.","zh":"抽象知識是關於不能總是直接看見或觸摸的概念和想法的知識。"},{"en":"Justice, empathy and responsibility are forms of abstract knowledge.","zh":"公義、同理心和責任都是抽象知識。"},{"en":"Students may understand abstract knowledge better when teachers connect it with real examples.","zh":"老師把抽象知識與真實例子連接時，學生可能理解得更好。"},{"en":"Drama gives abstract concepts concrete people, actions and consequences.","zh":"戲劇為抽象概念加入具體人物、行動和後果。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"lived understanding","meaning":"親身體會得來的理解","examples":[{"en":"Drama turns ideas into lived understanding.","zh":"戲劇把概念轉化成親身體會得來的理解。"},{"en":"Lived understanding is understanding developed through personal or simulated experience rather than explanation alone.","zh":"親身體會得來的理解，是透過親身或模擬經歷建立，而不只是靠解釋得到的理解。"},{"en":"Caring for a younger child can give someone lived understanding of responsibility.","zh":"照顧年幼孩子可以令人親身體會責任是甚麼。"},{"en":"Role-play gives students a form of lived understanding by making them act through difficult choices.","zh":"角色扮演迫使學生實際作出困難選擇，因此帶來一種親身體會。"},{"en":"Lived understanding often carries emotion and memory as well as facts.","zh":"親身體會得來的理解通常同時包含情緒、記憶和事實。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"it is one thing to…, it is another to…","meaning":"……是一回事，……又是另一回事","examples":[{"en":"It is one thing to read about empathy; it is another to act it out.","zh":"閱讀同理心是一回事，把它演出來又是另一回事。"},{"en":"“It is one thing to A; it is another to B” shows that two related actions differ greatly in difficulty or depth.","zh":"「it is one thing to A; it is another to B」表示兩件相關事情在難度或深度上有很大差別。"},{"en":"It is one thing to know a rule; it is another to follow it under pressure.","zh":"知道規則是一回事，在壓力下仍遵守它又是另一回事。"},{"en":"Reading about courage is easier than making a brave choice in a realistic scenario.","zh":"閱讀勇氣比在真實情境中作勇敢選擇容易。"},{"en":"This structure highlights the gap between theoretical knowledge and actual application.","zh":"這個句式突出理論知識與真正應用之間的差距。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"peer pressure","meaning":"同輩壓力","examples":[{"en":"Students can explore peer pressure through drama.","zh":"學生可以透過戲劇探索同輩壓力。"},{"en":"Peer pressure is influence from people of a similar age or social group that encourages someone to behave in a certain way.","zh":"同輩壓力是來自年齡相近或同一社交群體的人，令某人傾向以某種方式行事的影響。"},{"en":"A teenager may feel peer pressure to laugh at a joke they actually dislike.","zh":"青少年可能受到同輩壓力，即使不喜歡某個笑話也跟着笑。"},{"en":"Role-play can show how peer pressure makes speaking up more difficult.","zh":"角色扮演可以展示同輩壓力如何令發聲變得更困難。"},{"en":"Understanding peer pressure helps students recognise when a group is influencing their choices.","zh":"理解同輩壓力有助學生察覺群體何時正在影響自己的選擇。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"empathy","meaning":"同理心","examples":[{"en":"Drama can help students understand empathy.","zh":"戲劇可以幫助學生理解同理心。"},{"en":"Empathy is the ability to understand and imagine another person’s feelings or point of view.","zh":"同理心是理解和想像另一個人的感受或觀點的能力。"},{"en":"Listening carefully to a friend’s worries can show empathy.","zh":"仔細聆聽朋友的煩惱可以表現同理心。"},{"en":"Playing another character may help students understand why that person feels hurt or afraid.","zh":"扮演另一個角色可以幫助學生理解對方為甚麼受傷或害怕。"},{"en":"Empathy does not require agreeing with someone; it requires trying to understand their experience.","zh":"同理心不要求你同意對方，而是嘗試理解對方的經歷。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"moral courage","meaning":"道德勇氣","examples":[{"en":"Drama lets students practise moral courage.","zh":"戲劇讓學生練習道德勇氣。"},{"en":"Moral courage is the willingness to do what you believe is right even when it may be difficult, unpopular or risky.","zh":"道德勇氣是即使行動困難、不受歡迎或有風險，仍願意做自己認為正確的事。"},{"en":"Reporting bullying can require moral courage if friends want you to stay silent.","zh":"如果朋友希望你保持沉默，舉報欺凌可能需要道德勇氣。"},{"en":"Drama scenarios allow students to practise moral courage without facing the full consequences of a real event.","zh":"戲劇情境讓學生練習道德勇氣，而不用承受真實事件的全部後果。"},{"en":"Moral courage becomes meaningful when values must guide an uncomfortable choice.","zh":"當價值觀必須引導一個令人不舒服的選擇，道德勇氣便真正重要。"}],"source":"2012 Q3.pdf","sourcePage":3},{"front":"step into a situation","meaning":"進入某個情境","examples":[{"en":"Students step into a situation where ideas must be tested.","zh":"學生進入一個概念必須接受考驗的情境。"},{"en":"To step into a situation means to enter and take an active role in a particular set of circumstances.","zh":"「step into a situation」表示進入某一組具體情況並主動參與其中。"},{"en":"A manager may need to step into a difficult situation when two workers are arguing.","zh":"兩名員工爭吵時，經理可能需要介入那個困難情境。"},{"en":"In drama, students step into imagined situations rather than only discussing them from outside.","zh":"在戲劇中，學生進入想像情境，而不只是站在外面討論。"},{"en":"Entering a situation makes learners respond to pressures that may be invisible in theory.","zh":"進入情境令學習者必須回應理論上未必看得見的壓力。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"have to be tested through","meaning":"必須透過……接受考驗","examples":[{"en":"Ideas have to be tested through words, silence and action.","zh":"概念必須透過語言、沉默和行動接受考驗。"},{"en":"“Have to be tested through” means ideas must be examined by using particular forms of behaviour or evidence.","zh":"「have to be tested through」表示概念必須透過某些行為或證據加以檢驗。"},{"en":"A plan has to be tested through practical use before we know whether it works.","zh":"計劃必須透過實際使用接受測試，才能知道是否有效。"},{"en":"In drama, values are tested through what characters say, avoid saying and actually do.","zh":"在戲劇中，價值觀會透過角色說甚麼、不說甚麼和實際做甚麼接受考驗。"},{"en":"Testing an idea shows whether it still holds when situations become difficult.","zh":"測試一個概念可以顯示它在困難情況下是否仍然成立。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"through words, silence and action","meaning":"透過語言、沉默和行動","examples":[{"en":"The ideas are tested through words, silence and action.","zh":"這些概念透過語言、沉默和行動接受考驗。"},{"en":"“Through words, silence and action” means meaning is shown by what people say, what they leave unsaid and what they do.","zh":"「through words, silence and action」表示意思由人說甚麼、不說甚麼和做甚麼共同表達。"},{"en":"A character’s attitude may be revealed through words, silence and action.","zh":"角色的態度可以透過語言、沉默和行動表現。"},{"en":"Saying nothing during bullying can communicate something just as clearly as speaking.","zh":"面對欺凌時甚麼也不說，也可以像說話一樣清楚傳達意思。"},{"en":"Drama teaches students that communication includes behaviour and silence, not only spoken language.","zh":"戲劇教學生溝通不只包括口語，也包括行為和沉默。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"a simple scenario","meaning":"一個簡單情境","examples":[{"en":"The teacher gave each group a simple scenario.","zh":"老師給每組一個簡單情境。"},{"en":"A simple scenario is a short, clearly described situation used as the starting point for discussion or acting.","zh":"簡單情境是一個簡短而清楚描述的情況，用作討論或演戲的起點。"},{"en":"The teacher gave us a simple scenario about two friends arguing over a borrowed book.","zh":"老師給我們一個朋友為借書而爭吵的簡單情境。"},{"en":"A simple scenario can lead to complex thinking if the choices inside it are difficult.","zh":"如果當中的選擇很困難，一個簡單情境也可以帶來複雜思考。"},{"en":"Drama tasks often begin with a clear scenario so students know what problem they must explore.","zh":"戲劇任務常由清楚情境開始，讓學生知道要探索甚麼問題。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"left out of","meaning":"被排除在……之外","examples":[{"en":"A new student had been left out of a class chat.","zh":"一名新生被排除在班群組聊天之外。"},{"en":"To be left out of something means to be excluded and not allowed or invited to take part.","zh":"「be left out of」表示被排斥，沒有被允許或邀請參與某件事。"},{"en":"She felt hurt when she was left out of the birthday gathering.","zh":"她沒有被邀請參加生日聚會，感到很受傷。"},{"en":"Being left out of a class chat can make a new student feel isolated from classmates.","zh":"被排除在班群組之外，可以令新生感到與同學隔離。"},{"en":"Exclusion may be harmful even when nobody uses openly insulting words.","zh":"即使沒有人公開侮辱，排斥仍可以造成傷害。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"class chat","meaning":"班群組聊天","examples":[{"en":"The scenario involved a new student being left out of a class chat.","zh":"情境涉及一名新生被排除在班群組聊天之外。"},{"en":"A class chat is an online group conversation used by classmates to communicate with one another.","zh":"班群組聊天是同班同學用來互相溝通的網上群組對話。"},{"en":"Students shared homework reminders in the class chat.","zh":"學生在班群組聊天中分享功課提醒。"},{"en":"Being excluded from the class chat may mean missing both social contact and practical information.","zh":"被排除在班群組聊天之外，可能同時錯過社交聯繫和實用資訊。"},{"en":"Online groups can strongly affect whether students feel included in their class.","zh":"網上群組可以強烈影響學生是否覺得自己被班級接納。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"laugh along","meaning":"跟着一起笑","examples":[{"en":"Classmates had to decide whether to laugh along.","zh":"同學要決定是否跟着一起笑。"},{"en":"To laugh along means to join other people in laughing, even if you did not start the joke yourself.","zh":"「laugh along」表示跟其他人一起笑，即使笑話並不是自己開始的。"},{"en":"He laughed along because everyone else was laughing, although he felt uncomfortable.","zh":"雖然他感到不舒服，但因為所有人都在笑，他也跟着一起笑。"},{"en":"Laughing along with a cruel joke can make the victim feel that the whole group supports it.","zh":"跟着一起笑一個殘忍笑話，可以令受害者覺得整個群體都支持它。"},{"en":"Peer pressure often appears in small choices such as whether to laugh along or stay silent.","zh":"同輩壓力常出現在是否跟着笑或保持沉默等細小選擇中。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"remain silent","meaning":"保持沉默","examples":[{"en":"Some classmates had to decide whether to remain silent.","zh":"一些同學要決定是否保持沉默。"},{"en":"To remain silent means to continue saying nothing even when there is an opportunity or reason to speak.","zh":"「remain silent」表示即使有機會或理由發言，仍繼續甚麼也不說。"},{"en":"She remained silent during the argument because she was afraid of making it worse.","zh":"她在爭吵中保持沉默，因為害怕令情況更差。"},{"en":"Remaining silent can sometimes protect someone, but in other situations it can allow harm to continue.","zh":"保持沉默有時可以保護人，但在另一些情況卻會讓傷害繼續。"},{"en":"Drama helps students examine when silence is neutral and when it becomes a choice with consequences.","zh":"戲劇幫助學生分析沉默何時是中立，何時會成為有後果的選擇。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"speak up","meaning":"出聲；發聲","examples":[{"en":"Some classmates had to decide whether to speak up.","zh":"一些同學要決定是否出聲。"},{"en":"To speak up means to express your opinion or object to something, especially when doing so may be difficult.","zh":"「speak up」表示表達意見或反對某件事，尤其當這樣做並不容易。"},{"en":"She spoke up when she saw another student being treated unfairly.","zh":"她看見另一名學生受到不公平對待時便出聲。"},{"en":"Speaking up against bullying may require courage because friends may disagree.","zh":"反對欺凌時發聲可能需要勇氣，因為朋友未必同意。"},{"en":"Knowing what is right is different from actually speaking up when pressure is present.","zh":"知道甚麼是對的，與在有壓力時真正發聲是兩回事。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, the task looked like a harmless skit.","zh":"乍看之下，這項任務像一齣無傷大雅的小短劇。"},{"en":"“At first glance” means according to the first quick impression before looking more carefully.","zh":"「at first glance」表示未仔細了解前，第一眼快速形成的印象。"},{"en":"At first glance, the problem looked simple, but several issues were hidden inside it.","zh":"乍看之下，問題很簡單，但其中隱藏了幾個議題。"},{"en":"Drama may look like play at first glance even when the thinking required is serious.","zh":"戲劇乍看可能像玩樂，即使實際需要認真思考。"},{"en":"First impressions can change after closer examination.","zh":"仔細檢視後，第一印象可以改變。"}],"source":"2012 Q3.pdf","sourcePage":4},{"front":"harmless skit","meaning":"無傷大雅的小短劇","examples":[{"en":"The task looked like a harmless skit.","zh":"這項任務看起來像一齣無傷大雅的小短劇。"},{"en":"A harmless skit is a short acted scene that appears light, funny and unlikely to cause serious concern.","zh":"無傷大雅的小短劇是看起來輕鬆、有趣，而且似乎不涉及嚴重問題的短場景。"},{"en":"The students performed a harmless skit about forgetting homework.","zh":"學生演出了一齣關於忘記做功課的無傷大雅小短劇。"},{"en":"A scene may look harmless while still containing difficult questions about behaviour and responsibility.","zh":"一個場景可以看似無害，同時包含關於行為和責任的困難問題。"},{"en":"Drama can use simple-looking scenes to explore serious issues safely.","zh":"戲劇可以用看似簡單的場景安全地探索嚴肅議題。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"on closer inspection","meaning":"仔細看時","examples":[{"en":"On closer inspection, the task required serious judgment.","zh":"仔細看時，這項任務其實需要認真判斷。"},{"en":"“On closer inspection” means after examining something more carefully and in greater detail.","zh":"「on closer inspection」表示更仔細、更詳細檢視之後。"},{"en":"The bag looked ordinary, but on closer inspection the material was very high quality.","zh":"那個袋看起來普通，但仔細看時會發現物料質素很高。"},{"en":"On closer inspection, the role-play involved difficult questions about bullying and responsibility.","zh":"仔細看時，角色扮演其實涉及欺凌和責任等困難問題。"},{"en":"This phrase contrasts a quick first impression with a more thoughtful conclusion.","zh":"這個片語把快速第一印象與更深入的結論作對比。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"emotional awareness","meaning":"情感覺察","examples":[{"en":"The drama task required emotional awareness.","zh":"這項戲劇任務需要情感覺察。"},{"en":"Emotional awareness is the ability to notice, understand and respond appropriately to your own and other people’s feelings.","zh":"情感覺察是察覺、理解並適當回應自己和別人感受的能力。"},{"en":"A good team leader needs emotional awareness when a member feels excluded.","zh":"當一名組員感到被排斥，好組長需要有情感覺察。"},{"en":"Drama develops emotional awareness because students must notice how words and actions affect characters.","zh":"戲劇要求學生留意言語和行動如何影響角色，因此可以培養情感覺察。"},{"en":"Emotional awareness can help people communicate more thoughtfully in real conflicts.","zh":"情感覺察可以幫助人在真實衝突中更體貼地溝通。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"serious judgment","meaning":"認真判斷","examples":[{"en":"The task required careful reading and serious judgment.","zh":"這項任務需要仔細閱讀和認真判斷。"},{"en":"Serious judgment means thoughtful decision-making about an important or morally difficult situation.","zh":"認真判斷是對重要或道德上困難的情況作出周詳決定。"},{"en":"Choosing how to respond to bullying requires serious judgment.","zh":"決定如何回應欺凌需要認真判斷。"},{"en":"Students had to consider consequences before deciding what their characters should do.","zh":"學生決定角色應怎樣做之前，要先考慮後果。"},{"en":"Serious judgment develops when learners compare different choices rather than search for an easy answer.","zh":"當學習者比較不同選擇，而不是只找簡單答案，認真判斷便會發展。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"playing the victim","meaning":"扮演受害者","examples":[{"en":"The student playing the victim had to explain the harm.","zh":"扮演受害者的學生要解釋所造成的傷害。"},{"en":"“Playing the victim” here means acting the role of the person who has been hurt or targeted in the scenario.","zh":"這裏的「playing the victim」表示在情境中扮演受到傷害或針對的人。"},{"en":"The student playing the victim described how exclusion made the character feel.","zh":"扮演受害者的學生描述被排斥令角色有甚麼感受。"},{"en":"Taking the victim’s role can help learners see the situation from a different perspective.","zh":"擔任受害者角色，可以幫助學習者從不同角度看事情。"},{"en":"In drama, “playing the victim” refers to acting a role, not falsely claiming to be harmed.","zh":"在戲劇中，「playing the victim」是扮演角色，不是虛假聲稱自己受害。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"direct insults","meaning":"直接侮辱","examples":[{"en":"Silence could hurt as much as direct insults.","zh":"沉默造成的傷害可能和直接侮辱一樣大。"},{"en":"Direct insults are openly rude or hurtful words aimed at a particular person.","zh":"直接侮辱是公開針對某人的粗魯或傷人說話。"},{"en":"Calling a classmate stupid is a direct insult.","zh":"叫同學「蠢」是一種直接侮辱。"},{"en":"Exclusion and silence can sometimes hurt even when nobody uses direct insults.","zh":"即使沒有人直接侮辱，排斥和沉默有時仍然會傷害人。"},{"en":"Harmful behaviour includes more than obvious verbal attacks.","zh":"有害行為不只包括明顯的言語攻擊。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"bystanders","meaning":"旁觀者","examples":[{"en":"The bystanders had to justify their choices.","zh":"旁觀者要為自己的選擇辯解。"},{"en":"Bystanders are people who are present when something happens but are not the main person causing or receiving the action.","zh":"旁觀者是在事情發生時在場，但不是主要行動者或受害者的人。"},{"en":"Bystanders may witness bullying without knowing whether to intervene.","zh":"旁觀者可能目睹欺凌，卻不知道是否應介入。"},{"en":"Inaction by bystanders can still affect how safe a victim feels.","zh":"旁觀者沒有行動，仍然可以影響受害者是否感到安全。"},{"en":"Drama can help students examine the responsibility of people who watch rather than act.","zh":"戲劇可以幫助學生分析只觀看而不行動的人有甚麼責任。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"justify their choices","meaning":"為自己的選擇辯解","examples":[{"en":"The bystanders had to justify their choices.","zh":"旁觀者要為自己的選擇辯解。"},{"en":"To justify your choices means to explain why you believe your decisions were reasonable or right.","zh":"為自己的選擇辯解表示解釋為甚麼自己認為某個決定合理或正確。"},{"en":"Students had to justify their choice of evidence in the essay.","zh":"學生要解釋為甚麼在文章中選擇某些證據。"},{"en":"A bystander who stays silent should be able to explain why they made that decision.","zh":"保持沉默的旁觀者應能解釋為何作出該決定。"},{"en":"Asking people to justify choices reveals the thinking and values behind their actions.","zh":"要求人為選擇提出理由，可以揭示行動背後的思考和價值觀。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"instead of simply","meaning":"而不是單純","examples":[{"en":"The class teacher had to ask questions instead of simply giving punishment.","zh":"班主任要提問，而不是單純作出懲罰。"},{"en":"“Instead of simply” means choosing a more thoughtful or complex action rather than doing only the obvious thing.","zh":"「instead of simply」表示不只做最直接的事情，而選擇較深入或周詳的行動。"},{"en":"Teachers should investigate the cause instead of simply blaming one student.","zh":"老師應調查原因，而不是單純責怪一名學生。"},{"en":"The role-play required the teacher character to understand the situation before reacting.","zh":"角色扮演要求老師角色在回應前先了解情況。"},{"en":"This phrase contrasts a quick response with a more considered alternative.","zh":"這個片語把快速反應與較有思考的替代方法作對比。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"giving punishment","meaning":"作出懲罰","examples":[{"en":"The class teacher did not simply give punishment.","zh":"班主任並沒有單純作出懲罰。"},{"en":"Giving punishment means imposing a negative consequence because someone has broken a rule or behaved wrongly.","zh":"作出懲罰表示因某人違反規則或行為不當而給予負面後果。"},{"en":"Giving punishment without understanding the cause may not solve the problem.","zh":"如果不了解原因便作出懲罰，未必能解決問題。"},{"en":"Teachers may need to protect victims and educate offenders as well as give punishment.","zh":"老師除了懲罰，也可能需要保護受害者和教育犯錯者。"},{"en":"Discipline is most useful when it helps prevent the same harmful behaviour from happening again.","zh":"當紀律措施能防止同樣傷害再次發生，它才最有用。"}],"source":"2012 Q3.pdf","sourcePage":5},{"front":"the more…, the more…","meaning":"越……就越……","examples":[{"en":"The more we rehearsed, the more we understood the ideas.","zh":"我們越多排練，就越理解那些概念。"},{"en":"“The more A, the more B” shows that as one thing increases, another thing also increases.","zh":"「the more A, the more B」表示一件事增加時，另一件事也隨之增加。"},{"en":"The more students practise speaking, the more confident they become.","zh":"學生越多練習說話，就越有信心。"},{"en":"Repeated rehearsal gave students more chances to notice motives, tone and consequences.","zh":"反覆排練給學生更多機會留意動機、語氣和後果。"},{"en":"This pattern is useful for describing a direct relationship between two changing conditions.","zh":"這個句式適合描述兩個變化條件之間的直接關係。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"rehearsed","meaning":"排練","examples":[{"en":"The more we rehearsed, the more we understood respect.","zh":"我們越多排練，就越理解尊重。"},{"en":"To rehearse means to practise a performance or scene before presenting it.","zh":"「rehearse」表示在正式表演前練習場景或演出。"},{"en":"The actors rehearsed the scene several times before the school show.","zh":"演員在學校表演前把那一幕排練了幾次。"},{"en":"Rehearsing allows students to change their words and actions after noticing problems.","zh":"排練讓學生在發現問題後改變說話和行動。"},{"en":"Rehearsal in educational drama is also a chance to rethink decisions, not only memorise lines.","zh":"教育戲劇中的排練不只是背台詞，也是重新思考決定的機會。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"empty slogans","meaning":"空洞口號","examples":[{"en":"Words such as “respect” were not empty slogans.","zh":"「尊重」這類詞不再只是空洞口號。"},{"en":"Empty slogans are impressive-sounding words or phrases that have little real meaning because they are not connected with action.","zh":"空洞口號是聽起來很漂亮，但因沒有與實際行動連結而缺乏真正意義的說法。"},{"en":"“Everyone matters” becomes an empty slogan if bullying is ignored.","zh":"如果欺凌被忽視，「每個人都重要」便會變成空洞口號。"},{"en":"Drama makes values less like empty slogans by forcing students to make choices based on them.","zh":"戲劇迫使學生根據價值觀作選擇，令它們不再只是空洞口號。"},{"en":"A principle becomes meaningful when people know how it should affect behaviour.","zh":"當人知道一項原則應如何影響行為，它才真正有意義。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"choices people make","meaning":"人們作出的選擇","examples":[{"en":"Respect and empathy are choices people make in real situations.","zh":"尊重和同理心是人們在真實情況中作出的選擇。"},{"en":"“Choices people make” means decisions shown through what individuals actually do rather than what they merely say they believe.","zh":"「choices people make」表示透過人實際做甚麼而表現的決定，而不只是口頭相信甚麼。"},{"en":"Kindness appears in the choices people make when someone needs help.","zh":"當有人需要幫助，人們作出的選擇可以顯示善意。"},{"en":"Respect becomes visible when a person chooses whether to listen, mock or speak up.","zh":"當一個人選擇聆聽、嘲笑還是發聲，尊重便會變得看得見。"},{"en":"Values are most clearly understood through behaviour in difficult situations.","zh":"價值觀在困難情況中的行為選擇最容易被理解。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"real situations","meaning":"真實情境","examples":[{"en":"Drama shows how people make choices in real situations.","zh":"戲劇展示人們如何在真實情境作出選擇。"},{"en":"Real situations are actual or realistic circumstances in which people face practical pressures and consequences.","zh":"真實情境是人要面對實際壓力和後果的真正或貼近現實情況。"},{"en":"Communication skills matter most in real situations such as disagreements at work.","zh":"溝通技巧在工作爭執等真實情境最重要。"},{"en":"Drama can simulate real situations safely inside a classroom.","zh":"戲劇可以在課室安全地模擬真實情境。"},{"en":"Practising realistic choices helps students prepare for situations beyond school.","zh":"練習現實選擇可以幫助學生準備面對校園以外的情況。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time we wrote our reflection, everyone understood the conflict.","zh":"到我們寫反思的時候，每個人都明白那場衝突。"},{"en":"“By the time” means that something had already happened before or when another point was reached.","zh":"「by the time」表示到了另一個時間點時，某件事已經發生。"},{"en":"By the time the lesson ended, most students had changed their first opinion.","zh":"到課堂結束的時候，大部分學生已改變最初看法。"},{"en":"Rehearsal and discussion happened first, so understanding had developed by the time students wrote.","zh":"排練和討論先發生，所以到學生寫作時理解已經形成。"},{"en":"This structure is useful for showing how learning develops over a period of time.","zh":"這個句式適合展示學習如何在一段時間中逐步發展。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"wrote our reflection","meaning":"寫反思","examples":[{"en":"Students wrote their reflection after the drama activity.","zh":"學生在戲劇活動後寫反思。"},{"en":"To write a reflection means to explain what you thought, learned, noticed or would do differently after an experience.","zh":"寫反思表示在經歷後解釋自己想到、學到、留意到甚麼，或下次會怎樣改變。"},{"en":"After the group project, each student wrote a reflection on teamwork.","zh":"小組專題後，每名學生都寫了一篇關於合作的反思。"},{"en":"Writing a reflection helps students turn an active experience into clear ideas.","zh":"寫反思幫助學生把活躍經歷轉化成清楚概念。"},{"en":"Reflection is important because students may understand an activity more deeply after thinking back on it.","zh":"反思很重要，因為學生回望活動後可能理解得更深入。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"seldom spoke in class","meaning":"很少在課堂上發言","examples":[{"en":"Even students who seldom spoke in class could explain the conflict.","zh":"即使很少在課堂上發言的學生，也能解釋那場衝突。"},{"en":"“Seldom spoke in class” means rarely contributed verbally during normal lessons.","zh":"「seldom spoke in class」表示在一般課堂很少口頭參與。"},{"en":"She seldom spoke in class because she worried about making mistakes.","zh":"她因擔心犯錯，很少在課堂上發言。"},{"en":"Role-play may give quieter students a different way to participate.","zh":"角色扮演可以給較安靜學生另一種參與方式。"},{"en":"A student who seldom speaks may still understand deeply and benefit from structured opportunities to contribute.","zh":"很少發言的學生仍可能理解很深入，並從有結構的參與機會中受益。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"identify the conflict","meaning":"識別衝突","examples":[{"en":"Students could identify the conflict in the scene.","zh":"學生能識別場景中的衝突。"},{"en":"To identify the conflict means to recognise and clearly explain the central disagreement, tension or problem.","zh":"識別衝突表示找出並清楚解釋主要分歧、張力或問題。"},{"en":"Readers should identify the conflict before analysing how the characters respond.","zh":"讀者分析角色如何回應前，應先識別衝突。"},{"en":"In the bullying scene, the conflict involved loyalty to friends versus responsibility to protect someone.","zh":"在欺凌場景中，衝突涉及對朋友忠誠與保護他人的責任。"},{"en":"Identifying a conflict helps students understand why characters make difficult choices.","zh":"識別衝突有助學生理解角色為何作出困難選擇。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"characters’ motives","meaning":"角色動機","examples":[{"en":"Students described the characters’ motives.","zh":"學生描述角色動機。"},{"en":"Characters’ motives are the reasons, needs or desires that explain why characters act as they do.","zh":"角色動機是解釋角色為甚麼會這樣行動的原因、需要或願望。"},{"en":"Fear may be one character’s motive for staying silent.","zh":"恐懼可能是一個角色保持沉默的動機。"},{"en":"Understanding motives prevents students from judging behaviour only from the surface.","zh":"理解動機可以避免學生只從表面判斷行為。"},{"en":"The same action can come from very different motives.","zh":"同一個行動可以來自非常不同的動機。"}],"source":"2012 Q3.pdf","sourcePage":6},{"front":"tone, gesture and hesitation","meaning":"語氣、手勢和遲疑","examples":[{"en":"Students studied how tone, gesture and hesitation changed meaning.","zh":"學生研究語氣、手勢和遲疑如何改變意思。"},{"en":"Tone, gesture and hesitation are features of communication involving voice, body movement and pauses or uncertainty.","zh":"語氣、手勢和遲疑分別涉及聲音、身體動作和停頓或不確定，是溝通的重要部分。"},{"en":"The same words can sound kind or angry depending on tone.","zh":"同一句話因語氣不同，可以聽起來友善或生氣。"},{"en":"A hesitant pause or defensive gesture can reveal feelings that words do not state directly.","zh":"猶豫停頓或防衛手勢可以透露文字沒有直接說出的感受。"},{"en":"Drama helps students notice communication beyond vocabulary and grammar.","zh":"戲劇幫助學生留意詞彙和文法以外的溝通。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"changed the meaning of","meaning":"改變……的意思","examples":[{"en":"Tone and gesture changed the meaning of a sentence.","zh":"語氣和手勢改變了一句話的意思。"},{"en":"To change the meaning of something means to make it communicate a different message or feeling.","zh":"改變某事的意思，表示令它傳達不同訊息或感受。"},{"en":"Saying “fine” angrily changes the meaning of the word from simple agreement.","zh":"生氣地說「fine」會令這個字不再只是普通同意。"},{"en":"A smile, pause or sharp tone can change the meaning of otherwise neutral words.","zh":"微笑、停頓或尖銳語氣都可以改變原本中性說話的意思。"},{"en":"Communication depends partly on how something is said, not only the dictionary meaning.","zh":"溝通部分取決於怎樣說，而不只是字典意思。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"distract someone from learning","meaning":"使某人分心而不能學習","examples":[{"en":"Drama did not distract us from learning.","zh":"戲劇沒有令我們分心而不能學習。"},{"en":"To distract someone from learning means to pull their attention away from the educational task or objective.","zh":"「distract someone from learning」表示把注意力由學習任務或目標拉走。"},{"en":"Constant phone notifications can distract students from learning.","zh":"不斷出現的手機通知可以令學生分心，無法學習。"},{"en":"Drama only distracts from learning if students focus on performance fun and ignore the lesson purpose.","zh":"只有當學生只顧表演的樂趣而忽略課堂目的，戲劇才會妨礙學習。"},{"en":"An active classroom is not necessarily distracted if students remain focused on the learning goal.","zh":"活躍課室不一定代表分心，只要學生仍集中在學習目標。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"made the learning visible","meaning":"令學習變得看得見","examples":[{"en":"Drama made the learning visible.","zh":"戲劇令學習變得看得見。"},{"en":"To make learning visible means to make students’ understanding, thinking and skills observable through what they say or do.","zh":"令學習看得見表示透過學生說甚麼和做甚麼，把理解、思考和技能呈現出來。"},{"en":"A presentation can make learning visible because students must explain ideas aloud.","zh":"簡報可以令學習看得見，因為學生必須口頭解釋概念。"},{"en":"Drama shows teachers whether students understand motives, conflict and consequences.","zh":"戲劇可以讓老師看見學生是否理解動機、衝突和後果。"},{"en":"Visible learning gives teachers evidence beyond completed worksheets.","zh":"看得見的學習為老師提供工作紙以外的證據。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, drama develops skills that worksheets cannot train.","zh":"更重要的是，戲劇能培養工作紙無法訓練的技能。"},{"en":"“More importantly” introduces a point that the speaker considers more significant than the previous one.","zh":"「more importantly」用來帶出說話者認為比前一點更重要的重點。"},{"en":"The new timetable is shorter and, more importantly, gives students more rest.","zh":"新時間表較短；更重要的是，它給學生更多休息。"},{"en":"Drama can improve memory; more importantly, it also trains communication and judgement.","zh":"戲劇可以改善記憶；更重要的是，也訓練溝通和判斷。"},{"en":"This phrase helps writers rank arguments according to importance.","zh":"這個片語幫助作者按重要程度排列論點。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"develop skills","meaning":"培養技能","examples":[{"en":"Drama helps students develop important skills.","zh":"戲劇幫助學生培養重要技能。"},{"en":"To develop skills means to improve abilities through practice, experience and feedback.","zh":"培養技能表示透過練習、經驗和回饋改善能力。"},{"en":"Group projects help students develop communication and planning skills.","zh":"小組專題幫助學生培養溝通和規劃技能。"},{"en":"Drama develops speaking, listening, negotiation and quick decision-making.","zh":"戲劇培養說話、聆聽、協商和快速決策能力。"},{"en":"Skills become stronger when learners repeatedly use them in meaningful situations.","zh":"當學習者在有意義的情況反覆使用技能，它們會變得更強。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"ordinary worksheets","meaning":"普通工作紙","examples":[{"en":"Ordinary worksheets can hardly train these skills.","zh":"普通工作紙很難訓練這些技能。"},{"en":"Ordinary worksheets are standard paper or digital exercises involving written questions and answers.","zh":"普通工作紙是包含書面問題和答案的標準紙本或數碼練習。"},{"en":"Ordinary worksheets are useful for practising grammar or checking factual knowledge.","zh":"普通工作紙很適合練習文法或檢查事實知識。"},{"en":"Worksheets may not train spontaneous speaking because students can work silently and individually.","zh":"工作紙未必能訓練即時說話，因為學生可以安靜地獨立完成。"},{"en":"Different learning goals require different tools; worksheets are useful but limited.","zh":"不同學習目標需要不同工具；工作紙有用但有其限制。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"can hardly train","meaning":"很難訓練","examples":[{"en":"Worksheets can hardly train negotiation and quick response.","zh":"工作紙很難訓練協商和快速回應。"},{"en":"“Can hardly train” means are very limited in their ability to develop a particular skill.","zh":"「can hardly train」表示在培養某項技能方面能力非常有限。"},{"en":"Reading alone can hardly train someone to react calmly in a live argument.","zh":"單靠閱讀很難訓練人在即時爭論中冷靜反應。"},{"en":"Negotiation requires interaction, so a static worksheet can hardly train it fully.","zh":"協商需要互動，所以靜態工作紙很難完整訓練。"},{"en":"A method may be useful for one skill while hardly training another.","zh":"一種方法可以很適合某項技能，但很難訓練另一項技能。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"storing information","meaning":"儲存資料","examples":[{"en":"Learning is not just about storing information.","zh":"學習不只是儲存資料。"},{"en":"Storing information means keeping facts or knowledge in memory for later use.","zh":"儲存資料表示把事實或知識記在腦中，日後再使用。"},{"en":"Memorising vocabulary is one form of storing information.","zh":"背詞彙是一種儲存資料。"},{"en":"Education also requires students to use information, solve problems and communicate.","zh":"教育也要求學生運用資料、解決問題和溝通。"},{"en":"Remembering facts matters, but learning becomes deeper when information can be applied.","zh":"記住事實很重要，但能夠應用資料時，學習才更深入。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"negotiating","meaning":"協商；磋商","examples":[{"en":"Students practise negotiating through drama.","zh":"學生透過戲劇練習協商。"},{"en":"Negotiating means discussing different needs or opinions in order to reach an agreement or workable solution.","zh":"協商是討論不同需要或意見，以達成共識或可行方案。"},{"en":"Two classmates negotiated over how to divide the project work.","zh":"兩名同學就如何分配專題工作進行協商。"},{"en":"Role-play can require students to negotiate without knowing exactly what the other person will say.","zh":"角色扮演可以要求學生在不知道對方會怎樣說的情況下即場協商。"},{"en":"Negotiation involves listening, explaining priorities and sometimes compromising.","zh":"協商包括聆聽、解釋重點，有時也需要妥協。"}],"source":"2012 Q3.pdf","sourcePage":7},{"front":"responding under pressure","meaning":"在壓力下回應","examples":[{"en":"Drama trains students to respond under pressure.","zh":"戲劇訓練學生在壓力下回應。"},{"en":"Responding under pressure means making decisions or communicating when time, stress or social tension makes the situation difficult.","zh":"在壓力下回應表示在時間、壓力或社交張力令情況困難時作決定或溝通。"},{"en":"Nurses often need to respond under pressure during emergencies.","zh":"護士在緊急情況中常需要在壓力下回應。"},{"en":"Drama gives students safe practice in answering unexpected comments or difficult choices quickly.","zh":"戲劇讓學生安全練習快速回應意外說話或困難選擇。"},{"en":"Rehearsing pressure can improve confidence when similar challenges arise in real life.","zh":"練習面對壓力，可以在真實生活遇到類似挑戰時提升自信。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"created a short scene","meaning":"創作一個短場景","examples":[{"en":"My group created a short scene about cyberbullying.","zh":"我的小組創作了一個關於網絡欺凌的短場景。"},{"en":"To create a short scene means to plan and perform a brief dramatic situation.","zh":"創作一個短場景表示設計並演出一個簡短戲劇情境。"},{"en":"Each group created a short scene showing a misunderstanding between friends.","zh":"每組創作一個展示朋友誤會的短場景。"},{"en":"Creating a scene requires students to decide what happens, who says what and why.","zh":"創作場景要求學生決定發生甚麼、誰說甚麼以及原因。"},{"en":"Making a short scene can reveal understanding more actively than answering one written question.","zh":"創作短場景可以比回答一條書面問題更主動地展示理解。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"cyberbullying","meaning":"網絡欺凌","examples":[{"en":"The group created a short scene about cyberbullying.","zh":"小組創作了一個關於網絡欺凌的短場景。"},{"en":"Cyberbullying is bullying carried out through digital communication such as messages, social media or online groups.","zh":"網絡欺凌是透過訊息、社交媒體或網上群組等數碼溝通進行的欺凌。"},{"en":"Repeatedly posting cruel comments about a classmate can be cyberbullying.","zh":"反覆在網上發布針對同學的殘忍留言，可以是網絡欺凌。"},{"en":"Cyberbullying can follow a victim home because online messages are not limited to school hours.","zh":"網絡欺凌可以跟受害者回到家，因為網上訊息不受上課時間限制。"},{"en":"Students need to understand that digital actions can cause real emotional harm.","zh":"學生需要明白數碼行為可以造成真正情感傷害。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"played the victim","meaning":"扮演受害者","examples":[{"en":"One student played the victim in the scene.","zh":"一名學生在場景中扮演受害者。"},{"en":"To play the victim here means to act as the person who is targeted or harmed in the drama scenario.","zh":"這裏的「played the victim」表示在戲劇情境中扮演受到針對或傷害的人。"},{"en":"She played the victim and explained how the online comments affected her character.","zh":"她扮演受害者，解釋網上留言如何影響角色。"},{"en":"Playing the victim can help students consider the emotional impact of actions from the receiving side.","zh":"扮演受害者可以幫助學生從承受傷害的一方思考行動的情感影響。"},{"en":"Role-play allows learners to explore perspectives different from their own.","zh":"角色扮演讓學習者探索與自己不同的觀點。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"bystander","meaning":"旁觀者","examples":[{"en":"Another student played the bystander.","zh":"另一名學生扮演旁觀者。"},{"en":"A bystander is someone who sees an event happen but is not the main person causing or receiving the action.","zh":"旁觀者是看見事件發生，但不是主要行動者或受害者的人。"},{"en":"The bystander saw the argument but did not know whether to intervene.","zh":"旁觀者看見爭吵，卻不知道是否應介入。"},{"en":"Bystanders can influence bullying by joining in, staying silent or speaking up.","zh":"旁觀者可以透過加入、沉默或發聲影響欺凌情況。"},{"en":"Drama makes the bystander’s role visible instead of treating them as unimportant.","zh":"戲劇令旁觀者角色變得清楚，而不是把他們視為不重要。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"played the class teacher","meaning":"扮演班主任","examples":[{"en":"I played the class teacher in the scene.","zh":"我在場景中扮演班主任。"},{"en":"To play the class teacher means to act the role of the teacher responsible for a particular class.","zh":"扮演班主任表示在戲劇中擔任負責某個班級的老師角色。"},{"en":"I played the class teacher and had to decide how to question the students fairly.","zh":"我扮演班主任，需要決定如何公平地向學生提問。"},{"en":"Taking the teacher’s role required me to think about both discipline and support.","zh":"擔任老師角色要求我同時思考紀律和支援。"},{"en":"Role-play can help students understand the responsibilities adults face in school conflicts.","zh":"角色扮演可以幫助學生理解成年人處理校園衝突時的責任。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"forced us to consider","meaning":"迫使我們思考","examples":[{"en":"The task forced us to consider tone and body language.","zh":"這項任務迫使我們思考語氣和身體語言。"},{"en":"To force someone to consider something means to make it impossible to ignore and require serious thought about it.","zh":"「force someone to consider」表示令某件事無法被忽略，必須認真思考。"},{"en":"The accident forced the school to consider stronger safety rules.","zh":"那次意外迫使學校考慮更嚴格安全規則。"},{"en":"Drama forced us to consider details of communication that we might have ignored in a worksheet.","zh":"戲劇迫使我們思考在工作紙中可能忽略的溝通細節。"},{"en":"Difficult tasks can improve thinking by forcing learners to examine uncomfortable questions.","zh":"困難任務可以透過迫使學習者檢視令人不舒服的問題來提升思考。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"body language","meaning":"身體語言","examples":[{"en":"The task made us consider body language and responsibility.","zh":"這項任務令我們思考身體語言和責任。"},{"en":"Body language is communication through posture, facial expression, movement and gesture rather than words.","zh":"身體語言是透過姿勢、面部表情、動作和手勢，而不是文字進行的溝通。"},{"en":"Crossed arms can sometimes communicate discomfort through body language.","zh":"雙手交叉有時可以透過身體語言傳達不自在。"},{"en":"An actor’s body language can show fear even when the character says nothing.","zh":"即使角色沒有說話，演員的身體語言也可以顯示恐懼。"},{"en":"Understanding body language helps students interpret communication more accurately.","zh":"理解身體語言有助學生更準確解讀溝通。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"report the incident","meaning":"報告事件","examples":[{"en":"The bystander had to decide whether to report the incident.","zh":"旁觀者要決定是否報告事件。"},{"en":"To report the incident means to tell a responsible person or authority what happened.","zh":"報告事件表示把發生的事情告訴有責任處理的人或機構。"},{"en":"The student reported the bullying incident to a teacher.","zh":"學生把欺凌事件報告給老師。"},{"en":"Reporting an incident can be difficult when someone fears being called disloyal.","zh":"如果一個人害怕被說成不忠於朋友，報告事件可能很困難。"},{"en":"Students should know whom to contact when an incident involves safety or serious harm.","zh":"當事件涉及安全或嚴重傷害，學生應知道可以向誰報告。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"stay silent","meaning":"保持沉默","examples":[{"en":"The bystander had to decide whether to stay silent.","zh":"旁觀者要決定是否保持沉默。"},{"en":"To stay silent means to choose not to speak or report what you know.","zh":"「stay silent」表示選擇不說話或不報告自己知道的事情。"},{"en":"He stayed silent because he was afraid his friends would become angry.","zh":"他因害怕朋友生氣而保持沉默。"},{"en":"Staying silent can feel safe for the bystander while leaving the victim unsupported.","zh":"保持沉默對旁觀者可能感覺安全，卻令受害者得不到支持。"},{"en":"Drama allows students to examine the consequences of silence before facing a real situation.","zh":"戲劇讓學生在面對真實情況前先分析沉默的後果。"}],"source":"2012 Q3.pdf","sourcePage":8},{"front":"react without making someone feel ashamed","meaning":"回應時不令某人感到羞愧","examples":[{"en":"The parent had to react without making the child feel ashamed.","zh":"家長要回應問題，同時不令孩子感到羞愧。"},{"en":"This means responding to a problem firmly but without humiliating the person or making them feel worthless.","zh":"這表示要堅定處理問題，但不要羞辱對方或令他覺得自己一文不值。"},{"en":"A teacher can correct cheating without making a student feel that they are a terrible person.","zh":"老師可以糾正作弊，而不用令學生覺得自己是一個很差的人。"},{"en":"Effective discipline separates criticism of harmful behaviour from rejection of the individual.","zh":"有效紀律會把對有害行為的批評與對個人的否定分開。"},{"en":"People are more likely to learn from mistakes when correction does not destroy their dignity.","zh":"當糾正不會摧毀尊嚴，人更容易從錯誤中學習。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"feel ashamed","meaning":"感到羞愧","examples":[{"en":"The parent should not make the child feel ashamed.","zh":"家長不應令孩子感到羞愧。"},{"en":"To feel ashamed means to feel painful embarrassment or guilt about yourself or something you have done.","zh":"感到羞愧表示對自己或自己做過的事情感到強烈尷尬或內疚。"},{"en":"He felt ashamed after realising that his joke had hurt someone.","zh":"他發現自己的笑話傷害別人後感到羞愧。"},{"en":"Feeling ashamed can sometimes encourage reflection, but extreme shame may make people hide mistakes instead.","zh":"羞愧有時可以促進反思，但過度羞恥也可能令人隱瞞錯誤。"},{"en":"Good correction should help people take responsibility without making them believe they are beyond improvement.","zh":"良好糾正應幫助人承擔責任，而不是令他覺得自己無法改善。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"protect the victim","meaning":"保護受害者","examples":[{"en":"The teacher had to protect the victim.","zh":"老師必須保護受害者。"},{"en":"To protect the victim means to take action to keep the harmed person safe from further harm.","zh":"保護受害者表示採取行動，防止受到傷害的人再受進一步傷害。"},{"en":"The school separated the students involved in order to protect the victim.","zh":"學校把涉事學生分開，以保護受害者。"},{"en":"Protecting the victim may include listening, stopping the behaviour and providing support.","zh":"保護受害者可以包括聆聽、制止行為和提供支援。"},{"en":"Discipline is incomplete if it punishes wrongdoing but does not make the victim safer.","zh":"如果只懲罰錯誤行為，卻沒有令受害者更安全，紀律處理仍不完整。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"turn the classroom into a court","meaning":"把課室變成法庭","examples":[{"en":"The teacher should not turn the classroom into a court.","zh":"老師不應把課室變成法庭。"},{"en":"“Turn the classroom into a court” is a metaphor meaning to make the lesson feel like a harsh trial focused only on judging guilt and punishment.","zh":"「turn the classroom into a court」是一個比喻，表示把課堂變成只集中判罪和懲罰的嚴厲審訊。"},{"en":"A teacher should investigate conflict without turning every discussion into a courtroom.","zh":"老師應調查衝突，而不是把每次討論都變成審判。"},{"en":"Students need accountability, but they also need space to explain, learn and repair harm.","zh":"學生需要問責，也需要空間解釋、學習和修補傷害。"},{"en":"The metaphor warns against treating education as punishment alone.","zh":"這個比喻提醒人教育不應只等於懲罰。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"one neat answer","meaning":"一個簡單俐落的答案","examples":[{"en":"These were not questions with one neat answer.","zh":"這些問題並沒有一個簡單俐落的答案。"},{"en":"“One neat answer” means one simple, clear solution that completely solves a complicated problem.","zh":"「one neat answer」表示一個簡單清楚、能完全解決複雜問題的答案。"},{"en":"Family conflicts rarely have one neat answer.","zh":"家庭衝突很少只有一個簡單俐落的答案。"},{"en":"Bullying situations may involve competing responsibilities and uncertain consequences.","zh":"欺凌情境可能涉及互相衝突的責任和不確定後果。"},{"en":"Complex moral problems require judgement because several answers may contain strengths and weaknesses.","zh":"複雜道德問題需要判斷，因為不同答案都可能有優點和缺點。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"role reversal","meaning":"角色互換","examples":[{"en":"Through role reversal, students saw the issue differently.","zh":"透過角色互換，學生用不同角度看問題。"},{"en":"Role reversal is an activity in which people exchange roles so each experiences the situation from another position.","zh":"角色互換是參與者交換角色，從另一個位置經歷同一情況的活動。"},{"en":"The parent and child used role reversal to understand each other’s frustration.","zh":"家長和孩子透過角色互換理解彼此的挫折。"},{"en":"A student who first played the bystander may later play the victim.","zh":"最初扮演旁觀者的學生之後可以改扮受害者。"},{"en":"Role reversal can challenge quick judgments by making learners experience another perspective.","zh":"角色互換令學習者經歷另一種觀點，可以挑戰過快的判斷。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"one person’s joke","meaning":"某人的玩笑","examples":[{"en":"One person’s joke might be another person’s wound.","zh":"某人的玩笑可能是另一個人的傷口。"},{"en":"“One person’s joke” means something one person finds funny, even though another person may experience it differently.","zh":"「one person’s joke」表示某人覺得有趣的事情，即使另一個人可能有完全不同感受。"},{"en":"A nickname may be one person’s joke but feel humiliating to the person receiving it.","zh":"一個花名對某人來說可能只是玩笑，對被叫的人卻很羞辱。"},{"en":"Humour does not erase harm simply because the speaker intended to be funny.","zh":"說話者本來想搞笑，並不代表傷害便不存在。"},{"en":"People need to consider the listener’s experience, not only the speaker’s intention.","zh":"人需要考慮聽者的經歷，而不只是說話者的意圖。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"another person’s wound","meaning":"另一個人的傷口","examples":[{"en":"One person’s joke might be another person’s wound.","zh":"某人的玩笑可能是另一個人的傷口。"},{"en":"“Another person’s wound” is a metaphor for emotional pain caused by something others may treat lightly.","zh":"「another person’s wound」是一個比喻，表示別人可能輕視，但對某人造成的情感傷害。"},{"en":"A casual comment can become another person’s wound if it touches a deep insecurity.","zh":"一句隨口說的話如果觸及深層不安，可以成為另一個人的傷口。"},{"en":"Words that seem harmless to one student may remain painful for another.","zh":"對一名學生看似無害的話，對另一個人可能長期很痛。"},{"en":"The metaphor reminds people that emotional harm is not always visible.","zh":"這個比喻提醒人情感傷害不一定看得見。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"no less important than","meaning":"不比……較不重要","examples":[{"en":"Empathy is no less important than vocabulary or grammar.","zh":"同理心不比詞彙或文法較不重要。"},{"en":"“No less important than” means equally important and not of lower value than something else.","zh":"「no less important than」表示同樣重要，價值並不比另一樣東西低。"},{"en":"Sleep is no less important than revision before an examination.","zh":"考試前，睡眠不比溫習較不重要。"},{"en":"Communication skills are no less important than factual knowledge in many real situations.","zh":"在很多真實情況中，溝通技巧不比事實知識較不重要。"},{"en":"This structure challenges the idea that one kind of learning deserves less attention.","zh":"這個句式挑戰某一類學習應較少受到重視的想法。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"communicate quickly but not always wisely","meaning":"溝通很快但不一定明智","examples":[{"en":"Young people communicate quickly but not always wisely.","zh":"年輕人溝通很快，但不一定總是明智。"},{"en":"This means people can send messages rapidly without always thinking carefully about tone, consequences or other people’s feelings.","zh":"這表示人可以很快傳送訊息，卻未必總會仔細思考語氣、後果或別人感受。"},{"en":"Group chats allow students to communicate quickly, but an angry reply can spread before anyone calms down.","zh":"群組聊天令學生快速溝通，但憤怒回覆可以在人冷靜前已傳開。"},{"en":"Speed in communication can increase misunderstanding when reflection is missing.","zh":"如果缺乏反思，溝通速度越快可能越容易產生誤會。"},{"en":"Digital skills should include not only fast communication but responsible judgment.","zh":"數碼能力不應只包括快速溝通，也應包括負責任判斷。"}],"source":"2012 Q3.pdf","sourcePage":9},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, some parents have a point.","zh":"誠然，一些家長說得有道理。"},{"en":"“Granted” introduces a point the speaker accepts before giving a qualification or opposing argument.","zh":"「granted」用來先承認一個觀點，再提出限制或相反論點。"},{"en":"Granted, online learning is convenient, but some students still need face-to-face support.","zh":"誠然，網上學習很方便，但有些學生仍需要面對面支援。"},{"en":"Granted, drama can become noisy if badly organised.","zh":"誠然，如果組織不善，戲劇可以變得很嘈吵。"},{"en":"Using “granted” makes an argument more balanced because it acknowledges the other side.","zh":"使用「granted」承認另一方觀點，可以令論證更平衡。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"have a point","meaning":"說得有道理","examples":[{"en":"Some parents have a point about drama being noisy.","zh":"有些家長說戲劇課太嘈吵，這一點說得有道理。"},{"en":"To have a point means to make an argument or observation that is reasonable and deserves consideration.","zh":"「have a point」表示提出了一個合理而值得考慮的論點或觀察。"},{"en":"Students have a point when they say the deadline is too short for such a large project.","zh":"如果專題很大型，學生說截止日期太短是有道理的。"},{"en":"Parents have a point if drama activities lack clear structure.","zh":"如果戲劇活動缺乏清楚結構，家長的憂慮便有道理。"},{"en":"Someone can have a point without being completely correct about the whole issue.","zh":"一個人的某一點可以有道理，但不代表他對整個問題完全正確。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"poorly planned","meaning":"規劃不善的","examples":[{"en":"If drama is poorly planned, it may become noisy.","zh":"如果戲劇規劃不善，可能會變得嘈吵。"},{"en":"Poorly planned means organised without enough thought, structure or preparation.","zh":"「poorly planned」表示沒有足夠思考、結構或準備地安排。"},{"en":"A poorly planned trip may waste time because transport and timings have not been checked.","zh":"規劃不善的旅程可能因交通和時間沒有查清楚而浪費時間。"},{"en":"Drama becomes unfocused when roles, objectives and time limits are poorly planned.","zh":"如果角色、目標和時限規劃不善，戲劇活動就會失去焦點。"},{"en":"Weak results may come from poor planning rather than from the teaching method itself.","zh":"差劣結果可能來自規劃不善，而不是教學方法本身。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"little more than","meaning":"只不過是","examples":[{"en":"Poor drama lessons may become little more than laughter and movement.","zh":"差劣的戲劇課可能只不過是笑聲和走動。"},{"en":"“Little more than” means almost nothing beyond the thing mentioned.","zh":"「little more than」表示除了所提到的東西外，幾乎沒有其他內容。"},{"en":"Without evidence, the argument was little more than a personal opinion.","zh":"沒有證據，那個論點只不過是個人意見。"},{"en":"Drama without reflection may become little more than entertainment.","zh":"沒有反思的戲劇可能只不過是娛樂。"},{"en":"A learning activity needs purpose if it is to become more than simple activity.","zh":"學習活動需要目的，才不會只剩表面活動。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"take that concern seriously","meaning":"認真看待那個憂慮","examples":[{"en":"I take that concern seriously.","zh":"我認真看待那個憂慮。"},{"en":"To take a concern seriously means to recognise that it deserves careful thought rather than dismissing it.","zh":"認真看待一個憂慮表示承認它值得仔細思考，而不是直接否定。"},{"en":"The school took parents’ safety concerns seriously and reviewed the rules.","zh":"學校認真看待家長的安全憂慮，並重新檢討規則。"},{"en":"Supporting drama does not require ignoring genuine concerns about poor planning.","zh":"支持戲劇並不代表要忽視關於規劃不善的真正憂慮。"},{"en":"Taking criticism seriously can strengthen an argument by showing willingness to address weaknesses.","zh":"認真處理批評，可以顯示願意面對弱點，從而加強論證。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"to say that… is not to say that…","meaning":"說……並不等於說……","examples":[{"en":"To say that drama can be misused is not to say that drama is useless.","zh":"說戲劇可能被誤用，並不等於說戲劇毫無用處。"},{"en":"“To say that A is not to say that B” means accepting one point does not logically require accepting a stronger conclusion.","zh":"「to say that A is not to say that B」表示承認A並不代表必須接受更強的B結論。"},{"en":"To say that exams are stressful is not to say that all exams should disappear.","zh":"說考試有壓力，並不等於說所有考試都應取消。"},{"en":"A teaching method can have weaknesses without being worthless.","zh":"一種教學方法可以有弱點，而不代表完全沒有價值。"},{"en":"This structure helps writers make careful distinctions and avoid extreme conclusions.","zh":"這個句式幫助作者作仔細區分，避免極端結論。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"be misused","meaning":"被誤用","examples":[{"en":"Drama can be misused if it is poorly planned.","zh":"如果規劃不善，戲劇可能被誤用。"},{"en":"To be misused means to be used in the wrong way or for a purpose that reduces its value.","zh":"「be misused」表示以錯誤方式使用，或用於令其價值下降的目的。"},{"en":"Technology can be misused when students copy answers instead of learning.","zh":"如果學生只抄答案而不學習，科技便可能被誤用。"},{"en":"Drama is misused if teachers add performance without clear educational purpose.","zh":"如果老師加入表演卻沒有清楚教育目的，戲劇就是被誤用。"},{"en":"The possibility of misuse does not mean a tool has no proper use.","zh":"某項工具可能被誤用，並不代表它沒有正確用途。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"the same applies to","meaning":"同樣適用於","examples":[{"en":"The same applies to group discussion and presentations.","zh":"同樣的道理也適用於小組討論和匯報。"},{"en":"“The same applies to” means the same rule, argument or condition is also true for another situation.","zh":"「the same applies to」表示同一規則、論點或條件對另一種情況也成立。"},{"en":"Exercise needs balance, and the same applies to diet.","zh":"運動需要平衡，而同樣的道理也適用於飲食。"},{"en":"Drama can fail without clear goals; the same applies to other teaching methods.","zh":"戲劇沒有清楚目標可以失敗；同樣情況也適用於其他教學方法。"},{"en":"This phrase helps extend one point to comparable examples.","zh":"這個片語幫助把一個觀點延伸到可比較的例子。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"group discussion","meaning":"小組討論","examples":[{"en":"Group discussion can also fail without clear objectives.","zh":"如果沒有清楚目標，小組討論也可能失敗。"},{"en":"Group discussion is an activity in which several people exchange ideas and opinions about a topic.","zh":"小組討論是幾個人就某個主題交換想法和意見的活動。"},{"en":"Students used group discussion to compare different solutions.","zh":"學生透過小組討論比較不同解決方法。"},{"en":"Group discussion works best when everyone knows the question and has a chance to contribute.","zh":"當所有人都知道問題，而且有機會參與，小組討論效果最好。"},{"en":"Without structure, discussion can become casual conversation rather than focused learning.","zh":"缺乏結構時，討論可能變成普通閒聊，而不是有焦點的學習。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"presentations","meaning":"匯報；演講","examples":[{"en":"Presentations need clear objectives to be useful.","zh":"匯報需要清楚目標才有用。"},{"en":"Presentations are organised spoken explanations delivered to an audience, often with visual support.","zh":"匯報是有組織地向觀眾口頭解釋內容，常配合視覺材料。"},{"en":"Each group gave a presentation on its research findings.","zh":"每組就研究結果進行匯報。"},{"en":"Presentations can train speaking and organisation when students know what they are expected to demonstrate.","zh":"當學生知道要展示甚麼，匯報可以訓練說話和組織能力。"},{"en":"A presentation without a clear purpose can become a performance of slides rather than learning.","zh":"沒有清楚目的的匯報，可能只變成展示投影片，而不是學習。"}],"source":"2012 Q3.pdf","sourcePage":10},{"front":"clear objectives","meaning":"清晰目標","examples":[{"en":"Without clear objectives, any method can fail.","zh":"沒有清晰目標，任何方法都可能失敗。"},{"en":"Clear objectives are specific statements of what learners should understand, practise or achieve.","zh":"清晰目標是具體說明學習者應理解、練習或達成甚麼的陳述。"},{"en":"The teacher explained the clear objectives before the group project began.","zh":"小組專題開始前，老師解釋了清晰目標。"},{"en":"Clear objectives help students understand why they are doing an activity.","zh":"清晰目標幫助學生明白為甚麼要做某項活動。"},{"en":"A teaching method becomes easier to evaluate when its objectives are clear.","zh":"當目標清楚，教學方法的成效也更容易評估。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"any method can fail","meaning":"任何方法都可能失敗","examples":[{"en":"Without clear objectives, any method can fail.","zh":"沒有清楚目標，任何方法都可能失敗。"},{"en":"“Any method can fail” means no teaching approach is automatically successful in every situation.","zh":"「any method can fail」表示沒有任何教學方法會在所有情況自動成功。"},{"en":"Even technology can fail if teachers use it without a purpose.","zh":"如果老師沒有目的地使用科技，科技也可能失敗。"},{"en":"Weak planning can make both traditional and creative methods ineffective.","zh":"規劃不足可以令傳統和創新方法都失效。"},{"en":"Success depends on how a method is designed and used, not only what the method is called.","zh":"成功取決於方法如何設計和使用，而不只是它叫甚麼名稱。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"clear instructions","meaning":"清晰指示","examples":[{"en":"Drama needs clear instructions.","zh":"戲劇需要清晰指示。"},{"en":"Clear instructions are easy-to-understand directions explaining exactly what people should do.","zh":"清晰指示是容易理解、準確說明參與者應做甚麼的指引。"},{"en":"Clear instructions helped every group begin the activity quickly.","zh":"清晰指示令每組都能迅速開始活動。"},{"en":"Drama can become confusing if students do not know the task, roles or expected outcome.","zh":"如果學生不知道任務、角色或預期結果，戲劇可能變得混亂。"},{"en":"Good instructions reduce wasted time and allow creativity within clear boundaries.","zh":"良好指示減少浪費時間，同時讓創意在清楚界線內發揮。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"time limit","meaning":"時限","examples":[{"en":"A time limit helps make drama structured.","zh":"時限有助令戲劇活動更有結構。"},{"en":"A time limit is a fixed amount of time within which an activity must be completed.","zh":"時限是在某項活動必須完成前所規定的固定時間。"},{"en":"Each group had a ten-minute time limit to prepare its scene.","zh":"每組有十分鐘時限準備場景。"},{"en":"A time limit stops rehearsal from continuing endlessly and keeps the lesson moving.","zh":"時限可以防止排練無限延長，令課堂繼續推進。"},{"en":"Clear limits can make creative tasks more focused rather than less creative.","zh":"清楚限制可以令創意任務更集中，而不一定削弱創意。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"assigned roles","meaning":"指定角色","examples":[{"en":"Assigned roles help students understand the task.","zh":"指定角色幫助學生理解任務。"},{"en":"Assigned roles are particular responsibilities or characters given to specific participants.","zh":"指定角色是分配給特定參與者的責任或人物身分。"},{"en":"Each student received an assigned role in the group discussion.","zh":"小組討論中，每名學生都有一個指定角色。"},{"en":"Assigned roles prevent everyone from trying to do the same thing.","zh":"指定角色可以防止所有人都嘗試做同一件事。"},{"en":"Clear roles can help quieter students participate because they know exactly what contribution is expected.","zh":"清楚角色可以幫助較安靜學生參與，因為他們知道自己應作出甚麼貢獻。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"reflection questions","meaning":"反思問題","examples":[{"en":"Reflection questions make drama more meaningful.","zh":"反思問題令戲劇更有意義。"},{"en":"Reflection questions are prompts that ask learners to think about what they noticed, learned or would change after an activity.","zh":"反思問題是要求學習者思考活動後留意到、學到甚麼或會如何改變的提示問題。"},{"en":"“Why did your character stay silent?” is a useful reflection question.","zh":"「你的角色為甚麼保持沉默？」就是一條有用反思問題。"},{"en":"Reflection questions connect performance with deeper analysis.","zh":"反思問題把表演與更深入分析連接起來。"},{"en":"Without reflection, students may enjoy an activity without clearly understanding what they learned.","zh":"沒有反思，學生可能享受活動，卻不清楚自己學到了甚麼。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"assessment criteria","meaning":"評核準則","examples":[{"en":"Assessment criteria make drama a structured activity.","zh":"評核準則令戲劇成為有結構的活動。"},{"en":"Assessment criteria are clear standards used to judge the quality of work or performance.","zh":"評核準則是用來判斷作品或表現質素的清楚標準。"},{"en":"The teacher shared assessment criteria for clarity, teamwork and understanding.","zh":"老師分享了關於清晰度、合作和理解的評核準則。"},{"en":"Criteria show students that drama is being evaluated for learning rather than entertainment alone.","zh":"準則讓學生知道戲劇會按學習成果評估，而不只是娛樂。"},{"en":"Fair assessment requires students to know what quality looks like before they begin.","zh":"公平評核需要學生在開始前知道甚麼才算高質素。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"structured learning activity","meaning":"有結構的學習活動","examples":[{"en":"Drama can become a structured learning activity.","zh":"戲劇可以成為有結構的學習活動。"},{"en":"A structured learning activity is an organised task with clear aims, steps, roles and expected outcomes.","zh":"有結構的學習活動是具有清楚目標、步驟、角色和預期成果的有組織任務。"},{"en":"A debate becomes a structured learning activity when speakers have rules and preparation time.","zh":"當辯論有規則和準備時間，它便成為有結構的學習活動。"},{"en":"Drama needs more than free acting if it is to become structured learning.","zh":"如果戲劇要成為有結構學習，就不能只讓學生自由演戲。"},{"en":"Structure gives students enough direction to learn while still allowing creativity.","zh":"結構給學生足夠方向去學習，同時仍保留創意空間。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"diary entry","meaning":"日記","examples":[{"en":"Students can write a diary entry after a role-play.","zh":"學生可以在角色扮演後寫一篇日記。"},{"en":"A diary entry is a personal piece of writing describing thoughts, feelings or events, often from one person’s point of view.","zh":"日記是以個人角度描述思想、感受或事件的文字。"},{"en":"Students wrote a diary entry as if they were the character after the argument.","zh":"學生假裝自己是爭執後的角色，寫了一篇日記。"},{"en":"Writing in character helps learners explore feelings that may not appear directly in dialogue.","zh":"以角色身分寫作，可以幫助學習者探索對白沒有直接表達的感受。"},{"en":"A diary entry can turn a performance into written reflection and language practice.","zh":"日記可以把表演轉化成書面反思和語言練習。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"compare their performance with","meaning":"把自己的表現與……比較","examples":[{"en":"Students can compare their performance with the original text.","zh":"學生可以把自己的表現與原文比較。"},{"en":"To compare their performance with something means to examine similarities and differences between what they acted and another version.","zh":"「compare their performance with」表示檢視自己的演出與另一個版本之間的相同和不同。"},{"en":"Students compared their spoken interpretation with the written dialogue.","zh":"學生把口頭演繹與書面對白比較。"},{"en":"Comparison can reveal what was added through tone, gesture or movement.","zh":"比較可以揭示語氣、手勢或動作額外加入了甚麼。"},{"en":"Comparing versions helps learners justify creative choices rather than perform without reflection.","zh":"比較不同版本幫助學習者解釋創作選擇，而不是沒有反思地表演。"}],"source":"2012 Q3.pdf","sourcePage":11},{"front":"original text","meaning":"原文","examples":[{"en":"Students may compare their performance with the original text.","zh":"學生可以把自己的表現與原文比較。"},{"en":"The original text is the source material before it is adapted, performed or changed.","zh":"原文是在被改編、表演或改動前的原始材料。"},{"en":"The class compared the film adaptation with the original text of the novel.","zh":"全班把改編電影與小說原文比較。"},{"en":"Returning to the original text helps students check whether their interpretation is supported.","zh":"回到原文可以幫助學生檢查自己的演繹是否有根據。"},{"en":"Drama can deepen reading when students repeatedly move between performance and the text.","zh":"當學生在表演和原文之間反覆比較，戲劇可以加深閱讀理解。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"character’s choices","meaning":"角色的選擇","examples":[{"en":"Students can explain what their character’s choices reveal.","zh":"學生可以解釋角色的選擇反映了甚麼。"},{"en":"A character’s choices are the decisions a person in a story makes when facing particular situations.","zh":"角色的選擇是故事人物在面對特定情況時作出的決定。"},{"en":"The character’s choice to stay silent revealed his fear of losing friends.","zh":"角色選擇保持沉默，反映他害怕失去朋友。"},{"en":"Choices can reveal values and motives more clearly than descriptions alone.","zh":"選擇可以比單純描述更清楚揭示價值觀和動機。"},{"en":"Analysing character choices helps students understand how personality and pressure shape behaviour.","zh":"分析角色選擇幫助學生理解性格和壓力如何塑造行為。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"that way","meaning":"這樣","examples":[{"en":"That way, parents can see the purpose of drama.","zh":"這樣，家長就能看見戲劇的目的。"},{"en":"“That way” means by using the method or action just described.","zh":"「that way」表示透過剛才描述的方法或行動。"},{"en":"Explain the rules clearly; that way, everyone will know what to do.","zh":"清楚解釋規則；這樣所有人都知道要做甚麼。"},{"en":"If schools show the objectives and assessment, that way parents can understand the educational purpose.","zh":"如果學校展示目標和評核，這樣家長就能理解教育目的。"},{"en":"This phrase links an action directly to its expected result.","zh":"這個片語把一項行動直接連接到預期結果。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"the final goal","meaning":"最終目標","examples":[{"en":"Acting is not the final goal.","zh":"演戲不是最終目標。"},{"en":"The final goal is the most important result that an activity is ultimately intended to achieve.","zh":"最終目標是某項活動最終真正希望達成的最重要結果。"},{"en":"Winning a practice game is not the final goal; improving skills is.","zh":"贏一場練習賽不是最終目標；提升技能才是。"},{"en":"In educational drama, acting is a method while deeper understanding is the final goal.","zh":"在教育戲劇中，演戲是方法，更深入理解才是最終目標。"},{"en":"Knowing the final goal helps teachers avoid focusing too much on performance quality alone.","zh":"知道最終目標，可以避免老師只集中在演出質素。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"the route towards","meaning":"通往……的途徑","examples":[{"en":"Acting is the route towards deeper thinking.","zh":"演戲是通往更深入思考的途徑。"},{"en":"“The route towards” means a method or path that leads to a particular result.","zh":"「the route towards」表示通往某個結果的方法或路徑。"},{"en":"Regular practice is the route towards greater confidence.","zh":"定期練習是通往更大自信的途徑。"},{"en":"Acting gives students experiences that can lead towards analysis and reflection.","zh":"演戲給學生經歷，這些經歷可以通往分析和反思。"},{"en":"The phrase emphasises that an activity is a means to an end rather than the end itself.","zh":"這個片語強調一項活動是達成目標的方法，而不是目標本身。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"deeper thinking","meaning":"更深入的思考","examples":[{"en":"Drama can lead students towards deeper thinking.","zh":"戲劇可以帶領學生走向更深入的思考。"},{"en":"Deeper thinking means analysis that goes beyond simple facts to examine reasons, consequences, perspectives and connections.","zh":"更深入的思考是超越簡單事實，分析原因、後果、觀點和連繫。"},{"en":"Asking why a character stayed silent encourages deeper thinking.","zh":"問角色為甚麼保持沉默，可以鼓勵更深入思考。"},{"en":"Drama promotes deeper thinking when students must explain choices rather than repeat definitions.","zh":"當學生必須解釋選擇，而不是重複定義，戲劇便能促進更深入思考。"},{"en":"Deeper thinking often involves questioning first impressions and considering alternatives.","zh":"更深入思考常包括質疑第一印象和考慮其他可能。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, drama deserves a place in education.","zh":"綜合而言，戲劇應在教育中佔一席位。"},{"en":"“All things considered” means after taking the main advantages, disadvantages and evidence into account.","zh":"「all things considered」表示把主要優點、缺點和證據都考慮之後。"},{"en":"All things considered, the new timetable is better for students.","zh":"綜合而言，新時間表對學生更好。"},{"en":"After considering both benefits and risks, the writer reaches a balanced conclusion about drama.","zh":"考慮好處和風險後，作者對戲劇得出平衡結論。"},{"en":"This phrase is especially useful for introducing a final judgement.","zh":"這個片語特別適合用來帶出最終判斷。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"I would argue that","meaning":"我會主張","examples":[{"en":"I would argue that drama deserves a secure place in education.","zh":"我會主張戲劇應在教育中佔有穩固位置。"},{"en":"“I would argue that” introduces a reasoned opinion the speaker is prepared to defend.","zh":"「I would argue that」用來帶出說話者準備以理由支持的觀點。"},{"en":"I would argue that schools should teach media literacy more directly.","zh":"我會主張學校應更直接教授媒體素養。"},{"en":"This phrase sounds more analytical than simply saying “I think”.","zh":"這個片語比單純說「I think」更有分析意味。"},{"en":"An argument introduced this way should be supported by clear reasons and examples.","zh":"以這個句式提出的論點應由清楚理由和例子支持。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"deserves a secure place in","meaning":"應在……中佔有穩固位置","examples":[{"en":"Drama deserves a secure place in education.","zh":"戲劇應在教育中佔有穩固位置。"},{"en":"To deserve a secure place in something means to merit a stable and recognised role rather than being treated as optional or temporary.","zh":"「deserves a secure place in」表示值得得到穩定而獲認可的位置，而不只是可有可無或暫時存在。"},{"en":"Physical education deserves a secure place in the school timetable.","zh":"體育應在學校時間表中佔有穩固位置。"},{"en":"If drama consistently supports important learning, it should not depend on occasional teacher enthusiasm alone.","zh":"如果戲劇持續支援重要學習，就不應只依靠個別老師偶爾有興趣才使用。"},{"en":"A secure place suggests long-term recognition of value.","zh":"穩固位置代表其價值得到長期認可。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"not every lesson should","meaning":"並非每堂課都應該","examples":[{"en":"Not every lesson should become a performance.","zh":"並非每堂課都應該變成表演。"},{"en":"“Not every lesson should” means the method being supported is not suitable or necessary for all teaching situations.","zh":"「not every lesson should」表示即使支持某種方法，它也不適合或不需要用於所有課堂。"},{"en":"Not every lesson should use group work; sometimes individual practice is better.","zh":"並非每堂課都應用小組活動；有時個人練習更好。"},{"en":"Drama is valuable, but some topics are more efficiently taught through explanation or written practice.","zh":"戲劇有價值，但部分主題用講解或書面練習會更有效率。"},{"en":"Supporting a method does not mean using it without limits.","zh":"支持一種方法並不代表毫無限制地使用。"}],"source":"2012 Q3.pdf","sourcePage":12},{"front":"merely to","meaning":"只是為了","examples":[{"en":"No teacher should use drama merely to make a lesson fashionable.","zh":"老師不應只是為了令課堂看起來時髦而使用戲劇。"},{"en":"“Merely to” means only for that single limited purpose and for no deeper reason.","zh":"「merely to」表示只為那一個有限目的，而沒有更深理由。"},{"en":"Schools should not buy technology merely to look modern.","zh":"學校不應只是為了看起來現代而購買科技。"},{"en":"Drama should not be used merely to entertain or impress observers.","zh":"戲劇不應只是為了娛樂或令旁觀者留下印象。"},{"en":"A teaching method needs a genuine learning purpose beyond appearance.","zh":"教學方法需要真正學習目的，而不只是外表。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"look fashionable","meaning":"看起來時髦","examples":[{"en":"Teachers should not use drama just to make lessons look fashionable.","zh":"老師不應只為令課堂看起來時髦而使用戲劇。"},{"en":"To look fashionable means to appear modern, trendy or in line with current educational fashions.","zh":"「look fashionable」表示看起來現代、流行或符合當前教育潮流。"},{"en":"A school can look fashionable by buying new devices without using them effectively.","zh":"學校可以透過購買新裝置看起來很時髦，卻未必真正有效使用。"},{"en":"Teaching quality matters more than whether a lesson looks fashionable to visitors.","zh":"教學質素比課堂在訪客眼中是否時髦更重要。"},{"en":"New methods should be chosen because they help learning, not because they seem trendy.","zh":"新方法應因為有助學習而被選擇，而不是因為看起來流行。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"when used with purpose","meaning":"當有目的地使用時","examples":[{"en":"When used with purpose, drama makes learning memorable.","zh":"當有目的地使用時，戲劇令學習令人難忘。"},{"en":"“When used with purpose” means when the activity is chosen and designed for a clear educational reason.","zh":"「when used with purpose」表示活動因清楚教育理由而被選擇和設計。"},{"en":"Technology is useful when used with purpose rather than simply because it is available.","zh":"科技在有目的地使用時才真正有用，而不是因為有設備就使用。"},{"en":"Drama becomes stronger when each role-play connects directly with a learning objective.","zh":"每次角色扮演都直接連接學習目標時，戲劇會更有效。"},{"en":"Purposeful use separates meaningful innovation from activity for its own sake.","zh":"有目的的使用可以把有意義創新與為活動而活動分開。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"brings ideas off the page","meaning":"把書本上的概念帶進現實","examples":[{"en":"Drama brings ideas off the page.","zh":"戲劇把書本上的概念帶進現實。"},{"en":"“Brings ideas off the page” is a metaphor meaning to turn written concepts into active, visible experiences.","zh":"「brings ideas off the page」是一個比喻，表示把書面概念變成活躍、看得見的經驗。"},{"en":"A science demonstration brings textbook ideas off the page.","zh":"科學示範把課本概念帶進現實。"},{"en":"Acting a conflict lets students see how written dialogue works through voice and movement.","zh":"演出一場衝突，讓學生看見書面對白如何透過聲音和動作發揮作用。"},{"en":"Ideas become more concrete when students can experience them rather than only read them.","zh":"當學生能親身經歷，而不只是閱讀，概念會變得更具體。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"gives students room to speak","meaning":"給學生發言空間","examples":[{"en":"Drama gives students room to speak.","zh":"戲劇給學生發言空間。"},{"en":"To give students room to speak means to create time and opportunity for them to express ideas in their own voices.","zh":"給學生發言空間表示創造時間和機會，讓他們用自己的聲音表達想法。"},{"en":"Small-group discussion gives quieter students more room to speak.","zh":"小組討論給較安靜學生更多發言空間。"},{"en":"Drama can provide structured speaking opportunities for students who rarely volunteer answers.","zh":"戲劇可以為很少主動回答的學生提供有結構的說話機會。"},{"en":"Students develop confidence when the classroom gives them safe space to use their voices.","zh":"當課室給學生安全空間使用自己的聲音，自信便會發展。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"makes learning memorable","meaning":"令學習令人難忘","examples":[{"en":"Drama makes learning memorable.","zh":"戲劇令學習令人難忘。"},{"en":"To make learning memorable means to create experiences and understanding that students can recall clearly later.","zh":"令學習令人難忘表示創造學生日後能清楚回想的經歷和理解。"},{"en":"A field trip can make history memorable by connecting facts with real places.","zh":"實地考察把歷史事實與真實地方連接，可以令歷史學習更難忘。"},{"en":"Drama makes learning memorable through emotion, movement and interaction.","zh":"戲劇透過情緒、動作和互動令學習令人難忘。"},{"en":"Memorable learning is useful because students can retrieve ideas more easily when they need them later.","zh":"難忘的學習很有用，因為學生日後需要時更容易提取概念。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"silent copying","meaning":"沉默抄寫","examples":[{"en":"Silent copying rarely makes learning memorable.","zh":"沉默抄寫很少會令學習令人難忘。"},{"en":"Silent copying means quietly writing down information without discussion, explanation or active use.","zh":"沉默抄寫表示安靜地抄下資料，而沒有討論、解釋或主動使用。"},{"en":"Students spent ten minutes on silent copying from the board.","zh":"學生用了十分鐘從黑板沉默抄寫。"},{"en":"Silent copying may record information but does not necessarily help learners understand it.","zh":"沉默抄寫可以記錄資料，但不一定幫助學習者理解。"},{"en":"Writing becomes more meaningful when students process and use the ideas rather than simply copy them.","zh":"當學生處理和使用概念，而不只是抄下來，寫作才更有意義。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"drama-based tasks","meaning":"以戲劇為本的課業","examples":[{"en":"Schools should explain drama-based tasks to parents.","zh":"學校應向家長解釋以戲劇為本的課業。"},{"en":"Drama-based tasks are learning activities that use acting, role-play, performance or dramatic techniques.","zh":"以戲劇為本的課業是使用演戲、角色扮演、表演或戲劇技巧的學習活動。"},{"en":"A hot-seating exercise is a drama-based task.","zh":"熱座提問就是一項以戲劇為本的課業。"},{"en":"Explaining drama-based tasks helps parents see what skills students are practising.","zh":"解釋戲劇課業可以幫助家長看見學生正在練習甚麼技能。"},{"en":"Clear communication can prevent active learning from being mistaken for unstructured play.","zh":"清楚溝通可以避免活躍學習被誤認為沒有結構的玩樂。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"explain the purpose of","meaning":"解釋……的目的","examples":[{"en":"Schools should explain the purpose of drama-based tasks.","zh":"學校應解釋以戲劇為本課業的目的。"},{"en":"To explain the purpose of something means to make clear why it is being done and what it is intended to achieve.","zh":"解釋某事的目的表示清楚說明為甚麼要做，以及希望達成甚麼。"},{"en":"The teacher explained the purpose of the survey before students began.","zh":"學生開始前，老師解釋調查的目的。"},{"en":"Parents may support drama more readily when schools explain its learning purpose.","zh":"當學校解釋戲劇的學習目的，家長可能更容易支持。"},{"en":"Knowing the purpose helps people judge an activity by its intended outcome rather than appearance.","zh":"知道目的後，人可以按預期成果而不是表面去評價活動。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"design them carefully","meaning":"仔細設計它們","examples":[{"en":"Teachers should design drama tasks carefully.","zh":"老師應仔細設計戲劇任務。"},{"en":"To design them carefully means to plan the tasks thoughtfully, considering objectives, instructions, roles, timing and assessment.","zh":"仔細設計它們表示周詳規劃目標、指示、角色、時間和評核。"},{"en":"Teachers should design group projects carefully so every student has meaningful work.","zh":"老師應仔細設計小組專題，令每名學生都有有意義的工作。"},{"en":"Carefully designed drama tasks reduce confusion and keep creativity connected to learning.","zh":"仔細設計的戲劇任務可以減少混亂，並令創意與學習保持連結。"},{"en":"Good design helps an activity produce the result it was intended to achieve.","zh":"良好設計幫助活動達成原本預期的結果。"}],"source":"2012 Q3.pdf","sourcePage":13},{"front":"reflect on what they have learnt","meaning":"反思自己學到的東西","examples":[{"en":"Students should reflect on what they have learnt afterwards.","zh":"學生之後應反思自己學到的東西。"},{"en":"To reflect on what you have learnt means to think carefully about new understanding, skills and changes in your thinking after an activity.","zh":"反思自己學到的東西表示活動後仔細思考新的理解、技能和思維改變。"},{"en":"After the project, students reflected on what they had learnt about teamwork.","zh":"專題後，學生反思自己對團隊合作學到了甚麼。"},{"en":"Reflection helps learners notice learning that may have happened during an exciting activity.","zh":"反思幫助學習者留意在刺激活動中可能已發生的學習。"},{"en":"Thinking back turns experience into clearer knowledge that can be used later.","zh":"回望經驗可以把它轉化成日後能使用的更清楚知識。"}],"source":"2012 Q3.pdf","sourcePage":14},{"front":"from the outside","meaning":"從外面看","examples":[{"en":"Drama may look like play from the outside.","zh":"從外面看，戲劇可能像玩樂。"},{"en":"“From the outside” means according to what someone can observe without being directly involved or knowing the deeper purpose.","zh":"「from the outside」表示從沒有直接參與或不了解深層目的的人所看到的角度。"},{"en":"From the outside, the job looked easy, but the workers faced constant pressure.","zh":"從外面看，那份工作很容易，但員工其實面對持續壓力。"},{"en":"Parents watching only a few minutes may see movement and laughter without seeing the analysis behind them.","zh":"家長只看幾分鐘時，可能只看到走動和笑聲，而看不到背後的分析。"},{"en":"An outside appearance can be misleading when important thinking is not immediately visible.","zh":"當重要思考不會立即顯示，外在表象可能會誤導。"}],"source":"2012 Q3.pdf","sourcePage":14},{"front":"at its best","meaning":"在最佳情況下","examples":[{"en":"In the classroom, drama at its best is serious learning.","zh":"在課室中，戲劇在最佳情況下就是認真學習。"},{"en":"“At its best” means when something is being used or performed in its most effective and successful form.","zh":"「at its best」表示某件事以最有效、最成功的形式被使用或表現時。"},{"en":"Technology at its best makes difficult information easier to access.","zh":"科技在最佳情況下可以令困難資料更容易接觸。"},{"en":"Drama at its best combines engagement, structure and deep thinking.","zh":"戲劇在最佳情況下會把投入、結構和深入思考結合起來。"},{"en":"Judging a method fairly requires looking at how it works when used well, not only at poor examples.","zh":"公平評價一種方法，需要看它被良好使用時的效果，而不只是差劣例子。"}],"source":"2012 Q3.pdf","sourcePage":14},{"front":"serious learning wearing a human face","meaning":"有人情味的認真學習","examples":[{"en":"Drama is serious learning wearing a human face.","zh":"戲劇是有人情味的認真學習。"},{"en":"“Serious learning wearing a human face” is a metaphor meaning rigorous education presented through human emotions, relationships and lived situations.","zh":"「serious learning wearing a human face」是一個比喻，表示嚴謹教育透過人的情感、關係和真實情境呈現。"},{"en":"A lesson about justice becomes more human when students explore the feelings of people affected by unfairness.","zh":"當學生探索受不公平影響者的感受，關於公義的課堂便變得更有人情味。"},{"en":"Drama keeps serious thinking but gives ideas voices, faces and actions.","zh":"戲劇保留認真思考，同時給概念加入聲音、面孔和行動。"},{"en":"The metaphor suggests that learning can be intellectually demanding while still feeling personal, emotional and alive.","zh":"這個比喻表示學習可以在智力上有要求，同時仍然個人化、有情感而有生命力。"}],"source":"2012 Q3.pdf","sourcePage":14}],"dse/writing/part-b/2012/Q4":[{"front":"still shaking","meaning":"仍然激動；仍在發抖","examples":[{"en":"The singer is still shaking after the band’s first festival performance.","zh":"首次音樂節演出後，歌手仍然激動。"},{"en":"Still shaking means still trembling or feeling emotionally excited after something intense.","zh":"仍然激動或仍在發抖，意思是在強烈經歷後仍身體顫抖或情緒激動。"},{"en":"A student may be still shaking after giving their first speech on stage.","zh":"學生第一次上台演講後可能仍在發抖。"},{"en":"The singer is still shaking because the performance felt larger than anything before.","zh":"歌手仍然激動，因為那場演出比以往任何經歷都更盛大。"},{"en":"Sometimes we are still shaking not from fear alone, but from joy and disbelief.","zh":"有時我們仍在發抖，不只是因為害怕，而是因為喜悅和難以置信。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"first festival performance","meaning":"首次音樂節演出","examples":[{"en":"Neon Harbour gave its first festival performance at Victoria Park.","zh":"Neon Harbour 在維多利亞公園進行了首次音樂節演出。"},{"en":"A first festival performance is a band’s first time playing at a music festival.","zh":"首次音樂節演出是樂隊第一次在音樂節上表演。"},{"en":"A young band may remember its first festival performance for years.","zh":"年輕樂隊可能多年後仍記得自己的首次音樂節演出。"},{"en":"The first festival performance matters because it proves the band has reached a bigger stage.","zh":"首次音樂節演出很重要，因為它證明樂隊已走上更大的舞台。"},{"en":"For Neon Harbour, the first festival performance turns a dream into a real memory.","zh":"對 Neon Harbour 來說，首次音樂節演出把夢想變成真實回憶。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"Victoria Park","meaning":"維多利亞公園","examples":[{"en":"The band performed at a music festival in Victoria Park.","zh":"樂隊在維多利亞公園的音樂節上表演。"},{"en":"Victoria Park is a public park in Hong Kong where large events can be held.","zh":"維多利亞公園是香港一個可舉辦大型活動的公園。"},{"en":"Families, joggers, and music fans may all gather in Victoria Park on different days.","zh":"家庭、緩跑人士和樂迷可能在不同日子聚集於維多利亞公園。"},{"en":"A familiar park can feel new when it becomes a festival venue.","zh":"熟悉的公園成為音樂節場地時，也可以感覺煥然一新。"},{"en":"In the post, Victoria Park changes from an ordinary public space into a glowing music island.","zh":"在帖文中，維多利亞公園由普通公共空間變成發光的音樂小島。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"last week","meaning":"上星期","examples":[{"en":"Last week, my band performed at a music festival.","zh":"上星期，我的樂隊在音樂節上表演。"},{"en":"Last week means during the week before the present one.","zh":"上星期意思是現在這一星期之前的一星期。"},{"en":"Last week, the students finished their final rehearsal before the show.","zh":"上星期，學生們在演出前完成最後一次排練。"},{"en":"Using “last week” makes the memory feel recent and still emotional.","zh":"使用「上星期」令回憶感覺很近，情緒仍然新鮮。"},{"en":"The singer writes about last week as if the sound is still fresh.","zh":"歌手寫起上星期時，好像聲音仍在耳邊。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"my band","meaning":"我的樂隊","examples":[{"en":"My band, Neon Harbour, performed at a music festival.","zh":"我的樂隊 Neon Harbour 在音樂節上表演。"},{"en":"My band means the music group that the speaker belongs to.","zh":"我的樂隊意思是說話者所屬的音樂組合。"},{"en":"A singer may feel proud when saying “my band” before a big performance.","zh":"歌手在大型演出前說「我的樂隊」時，可能感到自豪。"},{"en":"The phrase shows personal connection, not just membership.","zh":"這個短語顯示的不只是成員身份，也有個人連繫。"},{"en":"For the writer, “my band” carries friendship, practice, and shared dreams.","zh":"對作者來說，「我的樂隊」承載友誼、練習和共同夢想。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"Neon Harbour","meaning":"Neon Harbour","examples":[{"en":"Neon Harbour performed at Victoria Park.","zh":"Neon Harbour 在維多利亞公園表演。"},{"en":"Neon Harbour is the name of the band in the post.","zh":"Neon Harbour 是帖文中樂隊的名字。"},{"en":"A band name like Neon Harbour can suggest city lights, water, and music at night.","zh":"像 Neon Harbour 這樣的樂隊名，可以令人想到城市燈光、海港和夜晚音樂。"},{"en":"When the announcer called Neon Harbour’s name, the performance became real.","zh":"當司儀叫出 Neon Harbour 的名字時，演出變得真實。"},{"en":"The name Neon Harbour becomes special because the audience shouted it back.","zh":"Neon Harbour 這個名字因觀眾大聲喊出來而變得特別。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"had been dreaming about","meaning":"一直夢想","examples":[{"en":"We did something we had been dreaming about for years.","zh":"我們做了一件多年來一直夢想的事。"},{"en":"Had been dreaming about means had wanted or imagined something for a long time.","zh":"一直夢想意思是長時間渴望或想像某事。"},{"en":"A dancer may perform on a famous stage she had been dreaming about since childhood.","zh":"舞者可能在自己從小一直夢想的著名舞台上表演。"},{"en":"Long dreaming makes the real moment feel powerful and unreal.","zh":"長久夢想會令真正發生的一刻強烈又不真實。"},{"en":"The band’s performance mattered because it was not sudden; it had lived in their dreams for years.","zh":"樂隊的演出重要，因為它不是突然出現，而是在他們夢中存在多年。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"since we first","meaning":"自從我們第一次……以來","examples":[{"en":"We had dreamed about this since we first squeezed into a rehearsal room.","zh":"自從我們第一次擠進排練室以來，我們一直夢想這一刻。"},{"en":"Since we first means from the first time something happened until now.","zh":"自從我們第一次……以來，意思是由某事第一次發生開始直到現在。"},{"en":"Since we first played together, we hoped to perform on a bigger stage.","zh":"自從我們第一次一起演奏以來，我們就希望站上更大的舞台。"},{"en":"This phrase connects the beginning of a journey with its later achievement.","zh":"這個短語把旅程的開始和後來的成就連接起來。"},{"en":"Since they first practised in a tiny room, the band had carried the same dream.","zh":"自從他們第一次在細小房間排練以來，樂隊一直懷著同一個夢。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"squeeze into","meaning":"擠進","examples":[{"en":"We first squeezed into a tiny rehearsal room in Kwun Tong.","zh":"我們第一次擠進觀塘一間細小的排練室。"},{"en":"To squeeze into a place means to fit into it even though it is small or crowded.","zh":"擠進某處意思是即使地方細小或擁擠，仍勉強進入。"},{"en":"Five musicians may squeeze into a small room with drums, guitars, and amplifiers.","zh":"五位樂手可能帶著鼓、結他和音箱擠進小房間。"},{"en":"Squeezing into a tiny space can show early struggle and strong commitment.","zh":"擠進狹小空間可以顯示早期掙扎和強烈投入。"},{"en":"The band once squeezed into a rehearsal room; now they stand before a festival crowd.","zh":"樂隊曾經擠進排練室；現在他們站在音樂節人群面前。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"tiny rehearsal room","meaning":"細小的排練室","examples":[{"en":"We first practised in a tiny rehearsal room in Kwun Tong.","zh":"我們最初在觀塘一間細小的排練室練習。"},{"en":"A tiny rehearsal room is a very small space where musicians practise.","zh":"細小的排練室是音樂人練習用的很小空間。"},{"en":"A tiny rehearsal room may be crowded with instruments, cables, and tired band members.","zh":"細小的排練室可能擠滿樂器、電線和疲倦的樂隊成員。"},{"en":"Small rehearsal rooms often hold the earliest version of big dreams.","zh":"小小排練室常承載大夢想最初的模樣。"},{"en":"The contrast between the tiny rehearsal room and the festival stage shows how far the band has come.","zh":"細小排練室和音樂節舞台之間的對比，顯示樂隊已走了多遠。"}],"source":"2012 Q4.pdf","sourcePage":1},{"front":"Kwun Tong","meaning":"觀塘","examples":[{"en":"The band first squeezed into a tiny rehearsal room in Kwun Tong.","zh":"樂隊最初擠進觀塘一間細小的排練室。"},{"en":"Kwun Tong is the district where the band’s early rehearsals took place.","zh":"觀塘是樂隊早期排練所在的地區。"},{"en":"A band may rent a small studio in Kwun Tong because practice rooms are available there.","zh":"樂隊可能在觀塘租用小型工作室，因為那裏有排練室。"},{"en":"Mentioning Kwun Tong makes the memory local and concrete.","zh":"提到觀塘令回憶更本地化和具體。"},{"en":"For Neon Harbour, Kwun Tong represents the beginning before the bigger stage.","zh":"對 Neon Harbour 來說，觀塘代表走上更大舞台前的起點。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"perform at","meaning":"在……表演","examples":[{"en":"We performed at a music festival in Victoria Park.","zh":"我們在維多利亞公園的音樂節表演。"},{"en":"To perform at an event means to sing, play, act, or present something there.","zh":"在某活動表演意思是在那裏唱歌、演奏、演戲或呈現作品。"},{"en":"A school choir may perform at a charity concert.","zh":"學校合唱團可能在慈善音樂會表演。"},{"en":"Performing at a festival can feel different from practising in a closed room.","zh":"在音樂節表演與在密閉房間練習感覺很不同。"},{"en":"The band’s dream became real when they performed at Victoria Park.","zh":"當樂隊在維多利亞公園表演時，他們的夢想變成現實。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"music festival","meaning":"音樂節","examples":[{"en":"We performed at a music festival in Victoria Park.","zh":"我們在維多利亞公園的音樂節上表演。"},{"en":"A music festival is an event where several artists or bands perform for an audience.","zh":"音樂節是多位歌手或樂隊為觀眾演出的活動。"},{"en":"A music festival may include food stalls, banners, crowds, and different stages.","zh":"音樂節可能包括小食檔、橫額、人群和不同舞台。"},{"en":"Performing at a music festival gives new bands a chance to reach strangers.","zh":"在音樂節表演給新樂隊接觸陌生觀眾的機會。"},{"en":"The festival setting makes the band’s first big performance feel lively and public.","zh":"音樂節場景令樂隊首次大型演出感覺熱鬧而公開。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"as the lead singer","meaning":"作為主音歌手","examples":[{"en":"As the lead singer, I had imagined this moment many times.","zh":"作為主音歌手，我曾多次想像這一刻。"},{"en":"As the lead singer means in the role of the main vocalist of the band.","zh":"作為主音歌手意思是以樂隊主要歌唱者的身份。"},{"en":"As the lead singer, a person must carry the melody and connect with the crowd.","zh":"作為主音歌手，一個人要唱出旋律並與觀眾連繫。"},{"en":"The lead singer may feel extra pressure because many eyes face the front of the stage.","zh":"主音歌手可能感到額外壓力，因為許多目光都望向舞台前方。"},{"en":"This phrase explains why the moment feels so personal to the writer.","zh":"這個短語解釋了為何這一刻對作者如此個人化。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"imagined this moment","meaning":"想像過這一刻","examples":[{"en":"I had imagined this moment so many times.","zh":"我已經想像過這一刻很多次。"},{"en":"To imagine this moment means to picture a future event in the mind before it happens.","zh":"想像這一刻意思是在某事發生前，在腦海中描繪未來情景。"},{"en":"A student may imagine the moment they receive exam results.","zh":"學生可能想像自己收到考試成績的那一刻。"},{"en":"Imagining a moment often cannot fully prepare us for how it really feels.","zh":"想像某一刻往往不能完全讓我們準備好真實感受。"},{"en":"The singer imagined the festival stage, but the real crowd still surprised him.","zh":"歌手想像過音樂節舞台，但真實人群仍令他驚訝。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"so many times that","meaning":"……很多次，以致","examples":[{"en":"I had imagined this moment so many times that I thought I would know how it would feel.","zh":"我想像過這一刻很多次，以致我以為自己會知道感覺是怎樣。"},{"en":"So many times that shows that something happened repeatedly and led to a result.","zh":"……很多次，以致顯示某事反覆發生，並導致一個結果。"},{"en":"She practised the speech so many times that she could say it without notes.","zh":"她練習演講很多次，以致可以不用筆記說出來。"},{"en":"The phrase links repetition with expectation.","zh":"這個短語把重複和期待連接起來。"},{"en":"The singer imagined the moment so often that he thought reality would feel familiar.","zh":"歌手太常想像這一刻，以致以為現實會感覺熟悉。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"know exactly how it would feel","meaning":"完全知道感覺會是怎樣","examples":[{"en":"I thought I would know exactly how it would feel.","zh":"我以為自己會完全知道感覺會是怎樣。"},{"en":"To know exactly how it would feel means to fully understand an experience before it happens.","zh":"完全知道感覺會是怎樣，意思是在事情發生前完全理解那種經歷。"},{"en":"A runner may think they know exactly how winning will feel, but the real moment may be different.","zh":"跑手可能以為自己完全知道勝利的感覺，但真實一刻可能不同。"},{"en":"Big experiences often surprise us even when we have imagined them many times.","zh":"重大經歷即使被想像很多次，仍常令人驚訝。"},{"en":"The singer learns that imagination cannot predict every emotion.","zh":"歌手明白想像不能預測每一種情緒。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"I was wrong","meaning":"我錯了","examples":[{"en":"I thought I knew how it would feel, but I was wrong.","zh":"我以為自己知道感覺會是怎樣，但我錯了。"},{"en":"I was wrong means my earlier belief or expectation was not correct.","zh":"我錯了意思是我早前的信念或期待不正確。"},{"en":"I thought the exam would be easy, but I was wrong.","zh":"我以為考試會很容易，但我錯了。"},{"en":"Admitting “I was wrong” makes the writing honest and human.","zh":"承認「我錯了」令文字誠實而有人情味。"},{"en":"The singer was wrong because the real performance felt far bigger than expected.","zh":"歌手錯了，因為真實演出比預期震撼得多。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"a world of difference between","meaning":"……之間有天壤之別","examples":[{"en":"There is a world of difference between singing to four walls and singing to strangers.","zh":"對著四面牆唱歌和對著陌生人唱歌之間有天壤之別。"},{"en":"A world of difference between two things means they are extremely different.","zh":"兩者之間有天壤之別意思是它們極為不同。"},{"en":"There is a world of difference between practising alone and speaking to a full hall.","zh":"獨自練習和在滿座禮堂演講之間有天壤之別。"},{"en":"The phrase stresses how a real audience changes everything.","zh":"這個短語強調真實觀眾如何改變一切。"},{"en":"For the singer, rehearsal and festival performance are not the same experience at all.","zh":"對歌手來說，排練和音樂節演出根本不是同一種經驗。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"singing to four walls","meaning":"對著四面牆唱歌","examples":[{"en":"There is a world of difference between singing to four walls and singing to a crowd.","zh":"對著四面牆唱歌和對著人群唱歌之間有天壤之別。"},{"en":"Singing to four walls means practising alone in a room without an audience.","zh":"對著四面牆唱歌意思是在沒有觀眾的房間裏獨自練習。"},{"en":"A singer may feel safe singing to four walls because no stranger is judging them.","zh":"歌手對著四面牆唱歌可能感到安全，因為沒有陌生人評價。"},{"en":"Singing to four walls helps practice, but it cannot teach the energy of a crowd.","zh":"對著四面牆唱歌有助練習，但不能教會人群帶來的能量。"},{"en":"The phrase captures the loneliness of rehearsal before public performance.","zh":"這個短語捕捉公開演出前排練的孤單感。"}],"source":"2012 Q4.pdf","sourcePage":2},{"front":"a field of strangers","meaning":"一大片陌生觀眾","examples":[{"en":"We sang to a field of strangers at Victoria Park.","zh":"我們在維多利亞公園對著一大片陌生觀眾唱歌。"},{"en":"A field of strangers means a large open crowd of people the singer does not know.","zh":"一大片陌生觀眾意思是歌手不認識的一大群開放空間中的人。"},{"en":"From the stage, the audience may look like a field of faces.","zh":"從舞台上看，觀眾可能像一片面孔。"},{"en":"Singing to strangers can feel frightening because their reaction is unknown.","zh":"對陌生人唱歌可能令人害怕，因為他們的反應未知。"},{"en":"The field of strangers becomes warmer when some people start singing along.","zh":"當有些人開始跟著唱時，那一大片陌生觀眾變得溫暖。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"faces are lit by","meaning":"面孔被……照亮","examples":[{"en":"Their faces were lit by stage lights, phone screens, and curiosity.","zh":"他們的面孔被舞台燈光、手機螢幕和好奇心照亮。"},{"en":"Faces are lit by something means light shines on people’s faces from that source.","zh":"面孔被某物照亮意思是光從該來源照到人的臉上。"},{"en":"At a concert, faces may be lit by colourful lamps and glowing phones.","zh":"在演唱會上，面孔可能被彩燈和發光手機照亮。"},{"en":"The light makes the audience visible and alive to the performer.","zh":"光線令觀眾在表演者眼中變得可見而有生命。"},{"en":"In the sentence, curiosity also seems to light the faces emotionally.","zh":"在句子中，好奇心似乎也在情感上照亮了面孔。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"stage lights","meaning":"舞台燈光","examples":[{"en":"The audience’s faces were lit by stage lights.","zh":"觀眾的面孔被舞台燈光照亮。"},{"en":"Stage lights are powerful lights used to illuminate performers and the stage.","zh":"舞台燈光是用來照亮表演者和舞台的強光。"},{"en":"Stage lights can make a small band feel as if they are in a dream.","zh":"舞台燈光可以令小樂隊感覺像置身夢中。"},{"en":"Bright stage lights may hide some faces while making the moment dramatic.","zh":"明亮舞台燈光可能遮住部分面孔，同時令場面更戲劇化。"},{"en":"For the singer, the stage lights turn the park into a performance world.","zh":"對歌手來說，舞台燈光把公園變成表演世界。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"phone screens","meaning":"手機螢幕","examples":[{"en":"The audience’s faces were lit by phone screens.","zh":"觀眾的面孔被手機螢幕照亮。"},{"en":"Phone screens are the glowing displays on mobile phones.","zh":"手機螢幕是手提電話上發光的顯示屏。"},{"en":"At concerts, phone screens often rise when people record videos or take photos.","zh":"在演唱會上，當人們錄影或拍照時，手機螢幕常會舉起。"},{"en":"Phone screens can make a crowd look like a field of small lights.","zh":"手機螢幕可以令觀眾群看起來像一片小燈光。"},{"en":"Seeing phone screens reminds performers that the moment is being remembered.","zh":"看見手機螢幕提醒表演者，這一刻正在被記住。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"this post is my attempt to","meaning":"這篇帖文是我嘗試……","examples":[{"en":"This post is my attempt to remember the night honestly.","zh":"這篇帖文是我嘗試真誠記下那一晚。"},{"en":"This post is my attempt to means the writer is trying to do something through the post.","zh":"這篇帖文是我嘗試……意思是作者透過帖文努力做某事。"},{"en":"This diary entry is my attempt to understand why the day mattered.","zh":"這篇日記是我嘗試理解那天為何重要。"},{"en":"The phrase sounds personal because it admits the writing may be imperfect.","zh":"這個短語很個人化，因為它承認文字可能並不完美。"},{"en":"The singer’s post is not just celebration; it is an attempt to record truthfully.","zh":"歌手的帖文不只是慶祝，也是在嘗試真實記錄。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"remember the night honestly","meaning":"真誠地記下那一晚","examples":[{"en":"I wanted to remember the night honestly.","zh":"我想真誠地記下那一晚。"},{"en":"To remember the night honestly means to recall both the good and imperfect parts truthfully.","zh":"真誠地記下那一晚意思是真實回想美好和不完美的部分。"},{"en":"After a competition, a student may remember the night honestly by admitting nerves and mistakes.","zh":"比賽後，學生可能透過承認緊張和錯誤來真誠地記下那一晚。"},{"en":"Honest memory is stronger than pretending everything was perfect.","zh":"真誠的記憶比假裝一切完美更有力量。"},{"en":"The singer wants to keep the joy and the lessons together.","zh":"歌手想把喜悅和教訓一起保留下來。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"the joy, the electricity, the mistakes and the lessons","meaning":"喜悅、震撼、錯誤和教訓","examples":[{"en":"The post records the joy, the electricity, the mistakes, and the lessons.","zh":"這篇帖文記錄了喜悅、震撼、錯誤和教訓。"},{"en":"This phrase lists the emotional excitement and practical learning from the night.","zh":"這個短語列出那一晚的情緒激動和實際學習。"},{"en":"A first performance can contain joy, electricity, mistakes, and lessons all at once.","zh":"第一次演出可以同時包含喜悅、震撼、錯誤和教訓。"},{"en":"Including mistakes makes the memory more honest and useful.","zh":"包括錯誤令回憶更誠實，也更有用。"},{"en":"The phrase shows that a meaningful night is not perfect, but full.","zh":"這個短語顯示有意義的一晚不一定完美，但很豐富。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"before we went on","meaning":"上台前","examples":[{"en":"Before we went on, I was anything but calm.","zh":"上台前，我一點也不冷靜。"},{"en":"Before we went on means before the band went on stage to perform.","zh":"上台前意思是樂隊走上舞台表演之前。"},{"en":"Before the students went on, they waited nervously behind the curtain.","zh":"學生上台前，在幕後緊張地等待。"},{"en":"This phrase captures the tense moment just before public performance begins.","zh":"這個短語捕捉公開演出開始前的緊張一刻。"},{"en":"The singer’s fear is strongest before the first step onto the stage.","zh":"歌手的恐懼在踏上舞台前最強烈。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"anything but calm","meaning":"一點也不冷靜","examples":[{"en":"Before we went on, I was anything but calm.","zh":"上台前，我一點也不冷靜。"},{"en":"Anything but calm means not calm at all.","zh":"一點也不冷靜意思是完全不平靜。"},{"en":"A debater waiting for results may be anything but calm.","zh":"等待結果的辯論員可能一點也不冷靜。"},{"en":"The phrase strongly denies the idea of calmness.","zh":"這個短語強烈否定冷靜的狀態。"},{"en":"The singer’s cold hands and dry throat prove he was anything but calm.","zh":"歌手冰冷的雙手和乾澀的喉嚨證明他一點也不冷靜。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"backstage","meaning":"後台","examples":[{"en":"Backstage, my hands were cold and my throat felt dry.","zh":"在後台，我雙手冰冷，喉嚨乾澀。"},{"en":"Backstage means the area behind the stage where performers wait and prepare.","zh":"後台是舞台後方讓表演者等待和準備的地方。"},{"en":"Musicians may tune instruments backstage before walking out.","zh":"音樂人可能在後台調音，然後走出去。"},{"en":"Backstage can feel crowded, noisy, and full of nervous energy.","zh":"後台可能感覺擁擠、嘈雜，並充滿緊張能量。"},{"en":"The backstage scene shows the fear hidden before the public performance.","zh":"後台場景顯示公開演出前隱藏的恐懼。"}],"source":"2012 Q4.pdf","sourcePage":3},{"front":"my throat felt dry","meaning":"喉嚨乾澀","examples":[{"en":"My throat felt dry before the performance.","zh":"演出前，我的喉嚨乾澀。"},{"en":"My throat felt dry means my throat was uncomfortable and lacked moisture.","zh":"喉嚨乾澀意思是喉嚨不舒服，像缺少水分。"},{"en":"A nervous speaker may feel a dry throat before a presentation.","zh":"緊張的演講者在匯報前可能感到喉嚨乾澀。"},{"en":"A dry throat can make a singer worry about hitting notes.","zh":"喉嚨乾澀會令歌手擔心能否唱準音。"},{"en":"The detail makes the singer’s anxiety physical and real.","zh":"這個細節令歌手的焦慮變得具體而真實。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"every small sound seemed enormous","meaning":"每個細小聲音都顯得巨大","examples":[{"en":"Every small sound seemed enormous backstage.","zh":"在後台，每個細小聲音都顯得巨大。"},{"en":"Every small sound seemed enormous means tiny noises felt very loud because of nervousness.","zh":"每個細小聲音都顯得巨大，意思是因緊張而覺得微小聲音非常大。"},{"en":"Before an exam, even a clock tick can seem enormous.","zh":"考試前，連鐘聲滴答都可能顯得巨大。"},{"en":"Anxiety can make ordinary sounds feel bigger than they are.","zh":"焦慮會令普通聲音感覺比實際更大。"},{"en":"The phrase shows how sharply the singer noticed everything before going on stage.","zh":"這個短語顯示歌手上台前對一切都異常敏感。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"the click of","meaning":"……的喀噠聲","examples":[{"en":"I heard the click of a guitar pedal.","zh":"我聽到結他效果器踏板的喀噠聲。"},{"en":"The click of something is a short sharp sound made by it.","zh":"……的喀噠聲是某物發出的短促清脆聲音。"},{"en":"The click of a camera can make a quiet room feel tense.","zh":"相機的喀噠聲可以令安靜房間變得緊張。"},{"en":"Small clicks backstage become noticeable when a performer is nervous.","zh":"當表演者緊張時，後台細小喀噠聲也會變得明顯。"},{"en":"The phrase focuses attention on one tiny sound before the show.","zh":"這個短語把注意力集中在演出前一個微小聲音上。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"guitar pedal","meaning":"結他效果器踏板","examples":[{"en":"The click of a guitar pedal sounded enormous.","zh":"結他效果器踏板的喀噠聲聽起來很巨大。"},{"en":"A guitar pedal is a device guitarists press with their foot to change the sound.","zh":"結他效果器踏板是結他手用腳按下以改變聲音的裝置。"},{"en":"A guitarist may use a pedal to add echo, distortion, or delay.","zh":"結他手可能用踏板加入回音、失真或延遲效果。"},{"en":"The pedal’s click can remind the band that the performance is about to begin.","zh":"踏板的喀噠聲可以提醒樂隊演出快要開始。"},{"en":"In the post, even a guitar pedal becomes part of the nervous atmosphere.","zh":"在帖文中，連結他效果器踏板也成為緊張氣氛的一部分。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"the crackle of","meaning":"……的沙沙聲","examples":[{"en":"I heard the crackle of a walkie-talkie.","zh":"我聽到對講機的沙沙聲。"},{"en":"The crackle of something is a rough, broken sound.","zh":"……的沙沙聲是某物發出的粗糙、斷續聲音。"},{"en":"The crackle of a radio can fill a quiet room before an announcement.","zh":"公告前，收音機的沙沙聲可以充滿安靜房間。"},{"en":"Crackling sounds can make backstage feel busy and urgent.","zh":"沙沙聲可以令後台感覺忙碌而急促。"},{"en":"The phrase adds texture to the tense moments before performance.","zh":"這個短語為演出前的緊張時刻加入質感。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"walkie-talkie","meaning":"對講機","examples":[{"en":"The crackle of a walkie-talkie made me nervous.","zh":"對講機的沙沙聲令我緊張。"},{"en":"A walkie-talkie is a small radio used for quick communication between staff.","zh":"對講機是工作人員用來快速溝通的小型無線電裝置。"},{"en":"Festival workers may use walkie-talkies to coordinate stages and schedules.","zh":"音樂節工作人員可能使用對講機協調舞台和時間表。"},{"en":"Hearing a walkie-talkie backstage can remind performers that everything is being managed quickly.","zh":"在後台聽到對講機，會提醒表演者一切正在快速安排。"},{"en":"In the singer’s nervous state, the walkie-talkie sounds louder than usual.","zh":"在歌手緊張狀態下，對講機聲比平常更響。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"tap nervous rhythms","meaning":"敲出緊張的節奏","examples":[{"en":"The drummer tapped nervous rhythms on his knees.","zh":"鼓手在膝蓋上敲出緊張的節奏。"},{"en":"To tap nervous rhythms means to make repeated beats that show anxiety or excitement.","zh":"敲出緊張的節奏意思是敲出反覆拍子，顯示焦慮或興奮。"},{"en":"A student may tap nervous rhythms on the desk before an interview.","zh":"學生面試前可能在桌上敲出緊張的節奏。"},{"en":"Tapping can release tension when words are not enough.","zh":"當言語不足以表達時，敲打可以釋放緊張。"},{"en":"The drummer’s nervous rhythms show that the whole band feels the pressure.","zh":"鼓手的緊張節奏顯示整個樂隊都感受到壓力。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"nervous rhythms","meaning":"緊張的節奏","examples":[{"en":"The drummer tapped nervous rhythms on his knees.","zh":"鼓手在膝蓋上敲出緊張的節奏。"},{"en":"Nervous rhythms are repeated beats that reveal tension or excitement.","zh":"緊張的節奏是透露緊張或興奮的反覆拍子。"},{"en":"Fingers tapping before a speech can create nervous rhythms.","zh":"演講前手指敲打桌面，可能形成緊張的節奏。"},{"en":"Such rhythms show emotion through movement rather than words.","zh":"這類節奏透過動作而非言語顯示情緒。"},{"en":"Before the show, nervous rhythms fill the silence backstage.","zh":"演出前，緊張的節奏填滿後台沉默。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"keep telling myself that","meaning":"不斷告訴自己","examples":[{"en":"I kept telling myself that nerves were simply excitement.","zh":"我不斷告訴自己，緊張只是興奮。"},{"en":"To keep telling myself that means to repeat an idea silently to calm or persuade myself.","zh":"不斷告訴自己某事，意思是反覆在心裏說一個想法，以安撫或說服自己。"},{"en":"Before a test, a student may keep telling herself that she is prepared.","zh":"考試前，學生可能不斷告訴自己已經準備好。"},{"en":"Repeating a thought can help, but it does not always remove fear.","zh":"重複一個想法可以有幫助，但不一定能消除恐懼。"},{"en":"The singer keeps telling himself a comforting idea, yet his heart still races.","zh":"歌手不斷告訴自己一個安慰想法，但心跳仍然急速。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"nerves","meaning":"緊張情緒","examples":[{"en":"Nerves were simply excitement looking for somewhere to go.","zh":"緊張情緒只是無處安放的興奮。"},{"en":"Nerves are feelings of worry, fear, or tension before something important.","zh":"緊張情緒是在重要事情前出現的擔心、害怕或繃緊感。"},{"en":"Performers often feel nerves before stepping onto a stage.","zh":"表演者踏上舞台前常會感到緊張。"},{"en":"Nerves can be uncomfortable, but they may also show that the moment matters.","zh":"緊張情緒可以不舒服，但也顯示那一刻很重要。"},{"en":"The singer tries to turn nerves into energy for the performance.","zh":"歌手嘗試把緊張情緒轉化為演出的能量。"}],"source":"2012 Q4.pdf","sourcePage":4},{"front":"excitement looking for somewhere to go","meaning":"無處安放的興奮","examples":[{"en":"Nerves were simply excitement looking for somewhere to go.","zh":"緊張情緒只是無處安放的興奮。"},{"en":"Excitement looking for somewhere to go means strong energy that has not yet found an outlet.","zh":"無處安放的興奮意思是強烈能量尚未找到出口。"},{"en":"Before a race, nervous energy can feel like excitement looking for somewhere to go.","zh":"比賽前，緊張能量可能像無處安放的興奮。"},{"en":"The phrase makes fear sound more hopeful and useful.","zh":"這個短語令恐懼聽起來更有希望，也更有用。"},{"en":"Once the music begins, that excitement finally has somewhere to go.","zh":"音樂一開始，那份興奮終於有地方可以釋放。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"stop my heart from racing","meaning":"阻止我心跳加速","examples":[{"en":"Even that did not stop my heart from racing.","zh":"即使那樣也不能阻止我心跳加速。"},{"en":"To stop my heart from racing means to calm my very fast heartbeat.","zh":"阻止我心跳加速意思是令非常快的心跳平靜下來。"},{"en":"Deep breathing may help stop a speaker’s heart from racing before a presentation.","zh":"深呼吸可能幫助演講者在匯報前阻止心跳加速。"},{"en":"The phrase shows that the singer’s body remains nervous despite his thoughts.","zh":"這個短語顯示即使歌手嘗試思考，他的身體仍然緊張。"},{"en":"His racing heart proves how much the performance means to him.","zh":"他急速的心跳證明這場演出對他多麼重要。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"heart from racing","meaning":"心跳急速","examples":[{"en":"I could not stop my heart from racing.","zh":"我無法阻止自己心跳急速。"},{"en":"Heart from racing refers to the heart beating very fast because of fear, excitement, or pressure.","zh":"心跳急速是指因害怕、興奮或壓力而心臟跳得很快。"},{"en":"A performer may feel their heart racing just before the curtain opens.","zh":"表演者可能在布幕打開前感到心跳急速。"},{"en":"A racing heart can make time feel faster and slower at the same time.","zh":"心跳急速會令人感覺時間同時變快又變慢。"},{"en":"The singer’s racing heart makes the stage entrance feel terrifying.","zh":"歌手急速的心跳令上台一刻感覺令人害怕。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"the announcer","meaning":"司儀；報幕員","examples":[{"en":"The announcer called our band’s name.","zh":"司儀叫出我們樂隊的名字。"},{"en":"The announcer is the person who introduces performers or gives public information.","zh":"司儀或報幕員是介紹表演者或發布公開資訊的人。"},{"en":"At a festival, the announcer may tell the crowd which band is next.","zh":"在音樂節上，司儀可能告訴觀眾下一隊樂隊是誰。"},{"en":"When the announcer speaks, waiting suddenly turns into action.","zh":"當司儀說話時，等待突然變成行動。"},{"en":"Hearing the announcer call Neon Harbour makes the band’s dream real.","zh":"聽到司儀叫出 Neon Harbour，令樂隊的夢想變成現實。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"called our name","meaning":"叫出我們的名字","examples":[{"en":"When the announcer called our name, I walked out.","zh":"當司儀叫出我們的名字時，我走了出去。"},{"en":"Called our name means said the band’s name aloud to the audience.","zh":"叫出我們的名字意思是向觀眾大聲說出樂隊名稱。"},{"en":"When a teacher called the team’s name, the students went on stage.","zh":"老師叫出隊伍名字時，學生們走上舞台。"},{"en":"Hearing your name publicly can make a moment feel official.","zh":"在公開場合聽到自己的名字，會令那一刻感覺正式。"},{"en":"For the band, being called by name is the signal that there is no turning back.","zh":"對樂隊來說，被叫出名字就是不能回頭的訊號。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"walked out as if","meaning":"走出去時像是","examples":[{"en":"I walked out as if I were stepping onto a moving bridge.","zh":"我走出去時像是踏上一條移動中的橋。"},{"en":"Walked out as if means moved forward while feeling or imagining a comparison.","zh":"走出去時像是意思是向前走時感覺或想像某種比喻。"},{"en":"She walked out as if the whole hall were holding its breath.","zh":"她走出去時像是整個禮堂都屏住呼吸。"},{"en":"The phrase helps readers feel the singer’s unstable nerves.","zh":"這個短語幫助讀者感受歌手不穩的緊張情緒。"},{"en":"The stage feels like a moving bridge because every step is exciting and frightening.","zh":"舞台像移動中的橋，因為每一步都既興奮又可怕。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"step onto","meaning":"踏上","examples":[{"en":"I felt as if I were stepping onto a moving bridge.","zh":"我感覺自己像踏上一條移動中的橋。"},{"en":"To step onto something means to place your foot on it and begin entering it.","zh":"踏上某物意思是把腳放到上面，開始進入它。"},{"en":"A performer steps onto the stage when the show begins.","zh":"表演開始時，表演者踏上舞台。"},{"en":"Stepping onto a big stage can feel like crossing into another world.","zh":"踏上大型舞台可能感覺像進入另一個世界。"},{"en":"The singer’s first step onto the stage carries fear and wonder.","zh":"歌手踏上舞台的第一步帶著恐懼和驚奇。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"a moving bridge","meaning":"移動中的橋","examples":[{"en":"I felt as if I were stepping onto a moving bridge.","zh":"我感覺自己像踏上一條移動中的橋。"},{"en":"A moving bridge is a metaphor for something unstable, exciting, and difficult to trust.","zh":"移動中的橋是一個比喻，指不穩、刺激而難以完全信任的東西。"},{"en":"A new challenge can feel like a moving bridge when we are unsure of our balance.","zh":"當我們不確定自己能否站穩時，新挑戰可能像移動中的橋。"},{"en":"The image shows that the stage feels alive and unsafe at the same time.","zh":"這個意象顯示舞台同時感覺有生命又不安全。"},{"en":"The singer must cross the moving bridge by beginning the performance.","zh":"歌手必須透過開始演出來走過這條移動中的橋。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"for one terrifying second","meaning":"在令人害怕的一秒間","examples":[{"en":"For one terrifying second, the crowd looked endless.","zh":"在令人害怕的一秒間，人群看似無邊無際。"},{"en":"For one terrifying second means during a very brief but frightening moment.","zh":"在令人害怕的一秒間意思是在非常短暫但可怕的一刻中。"},{"en":"For one terrifying second, a speaker may forget the first line of a speech.","zh":"在令人害怕的一秒間，演講者可能忘記第一句稿。"},{"en":"Short moments can feel long when fear is intense.","zh":"當恐懼強烈時，短短一刻也可能感覺很長。"},{"en":"The singer’s terror fades only after the crowd becomes human and encouraging.","zh":"只有當人群變得有人性並帶來鼓勵時，歌手的恐懼才減退。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"the crowd looked endless","meaning":"人群看似無邊無際","examples":[{"en":"The crowd looked endless from the stage.","zh":"從舞台上看，人群看似無邊無際。"},{"en":"The crowd looked endless means there seemed to be too many people to count.","zh":"人群看似無邊無際意思是人多得似乎數不清。"},{"en":"From a high stage, even a small audience may look endless to a nervous performer.","zh":"從高舞台上看，即使不算太大的觀眾群也可能令緊張表演者覺得無邊無際。"},{"en":"An endless-looking crowd can make a singer feel exposed and tiny.","zh":"看似無邊無際的人群會令歌手感到暴露和渺小。"},{"en":"The phrase shows how fear enlarges the audience in the singer’s mind.","zh":"這個短語顯示恐懼如何在歌手心中放大觀眾。"}],"source":"2012 Q4.pdf","sourcePage":5},{"front":"near the front","meaning":"靠近前排","examples":[{"en":"Someone near the front shouted our band name.","zh":"靠近前排的某個人大叫我們樂隊的名字。"},{"en":"Near the front means close to the front part of the crowd or stage area.","zh":"靠近前排意思是接近觀眾區或舞台區前方。"},{"en":"Fans near the front often see the performers most clearly.","zh":"靠近前排的樂迷通常能最清楚看見表演者。"},{"en":"A shout from near the front can reach the band quickly and personally.","zh":"從前排附近傳來的呼喊，可以快速而親近地傳到樂隊耳中。"},{"en":"That voice near the front helps the singer feel less alone.","zh":"前排附近的那把聲音令歌手感到不那麼孤單。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"shouted our band name","meaning":"大叫我們樂隊的名字","examples":[{"en":"Someone near the front shouted our band name.","zh":"靠近前排的某個人大叫我們樂隊的名字。"},{"en":"Shouted our band name means called the band’s name loudly with excitement.","zh":"大叫我們樂隊的名字意思是興奮地高聲叫出樂隊名稱。"},{"en":"A fan may shout a band’s name to show support before the first song.","zh":"樂迷可能在第一首歌前大叫樂隊名字以表示支持。"},{"en":"Hearing the name shouted back can turn fear into courage.","zh":"聽到名字被大聲喊回來，可以把恐懼變成勇氣。"},{"en":"The shout tells the band that at least one stranger is already on their side.","zh":"那聲呼喊告訴樂隊，至少有一位陌生人已站在他們一邊。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"loosen its grip","meaning":"鬆開束縛","examples":[{"en":"The fear loosened its grip when someone shouted our name.","zh":"當有人叫出我們名字時，恐懼鬆開了束縛。"},{"en":"To loosen its grip means to become less strong or less controlling.","zh":"鬆開束縛意思是力量或控制變弱。"},{"en":"A student’s anxiety may loosen its grip after a friend smiles from the audience.","zh":"學生看見觀眾席上的朋友微笑後，焦慮可能鬆開束縛。"},{"en":"Encouragement can loosen fear’s grip before a difficult task.","zh":"鼓勵可以在困難任務前鬆開恐懼的束縛。"},{"en":"The shout from the crowd gives the singer enough freedom to begin.","zh":"人群中的呼喊給歌手足夠自由去開始。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"beyond words","meaning":"難以用言語形容","examples":[{"en":"The atmosphere was beyond words.","zh":"那種氣氛難以用言語形容。"},{"en":"Beyond words means too powerful, beautiful, or emotional to describe fully.","zh":"難以用言語形容意思是太強烈、太美或太有情感，無法完整描述。"},{"en":"The applause after the final song was beyond words.","zh":"最後一首歌後的掌聲難以用言語形容。"},{"en":"People use this phrase when ordinary language feels too small.","zh":"當普通語言顯得太小時，人們會使用這個短語。"},{"en":"The festival atmosphere is beyond words because it combines fear, lights, music, and human warmth.","zh":"音樂節氣氛難以用言語形容，因為它結合恐懼、燈光、音樂和人的溫暖。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"a place of","meaning":"一個……的地方","examples":[{"en":"Victoria Park is usually a place of joggers and families.","zh":"維多利亞公園通常是一個緩跑人士和家庭聚集的地方。"},{"en":"A place of something means a place commonly connected with those people or activities.","zh":"一個……的地方意思是通常與那些人或活動連繫的地方。"},{"en":"A library is a place of quiet study and careful reading.","zh":"圖書館是一個安靜學習和仔細閱讀的地方。"},{"en":"Calling Victoria Park a place of joggers and families shows its ordinary daytime identity.","zh":"把維多利亞公園稱為緩跑人士和家庭的地方，顯示它平日的身份。"},{"en":"The festival transforms a familiar place of daily life into a place of music.","zh":"音樂節把熟悉的日常地方變成音樂的地方。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"joggers","meaning":"緩跑人士","examples":[{"en":"Victoria Park is usually a place of joggers, families, and football matches.","zh":"維多利亞公園通常是緩跑人士、家庭和足球賽的地方。"},{"en":"Joggers are people who run slowly or steadily for exercise.","zh":"緩跑人士是為運動而慢跑或穩定跑步的人。"},{"en":"Joggers may use Victoria Park early in the morning before work.","zh":"緩跑人士可能在上班前清晨使用維多利亞公園。"},{"en":"Mentioning joggers makes the park feel ordinary and familiar.","zh":"提到緩跑人士令公園感覺平常而熟悉。"},{"en":"On festival night, the space usually used by joggers becomes a stage for music.","zh":"在音樂節之夜，平日屬於緩跑人士的空間變成音樂舞台。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"weekend football matches","meaning":"週末足球賽","examples":[{"en":"Victoria Park is usually a place of weekend football matches.","zh":"維多利亞公園通常是週末足球賽的地方。"},{"en":"Weekend football matches are games played on Saturdays or Sundays.","zh":"週末足球賽是在星期六或星期日進行的比賽。"},{"en":"Families may watch weekend football matches in the park.","zh":"家庭可能在公園觀看週末足球賽。"},{"en":"The phrase shows the normal community life of Victoria Park.","zh":"這個短語顯示維多利亞公園平日的社區生活。"},{"en":"During the festival, music replaces the usual sound of weekend football matches.","zh":"在音樂節期間，音樂取代了週末足球賽的平常聲音。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"turn into","meaning":"變成","examples":[{"en":"Victoria Park had turned into a glowing island of music.","zh":"維多利亞公園變成了一座發光的音樂小島。"},{"en":"To turn into something means to become something different.","zh":"變成某物意思是成為不同的東西。"},{"en":"A classroom can turn into a stage during a school performance.","zh":"課室在學校表演期間可以變成舞台。"},{"en":"Lights, food stalls, and music turn the park into a festival world.","zh":"燈光、小食檔和音樂把公園變成音樂節世界。"},{"en":"The phrase shows transformation from ordinary space to magical scene.","zh":"這個短語顯示由普通空間到神奇場景的轉變。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"glowing island of music","meaning":"發光的音樂小島","examples":[{"en":"Victoria Park had turned into a glowing island of music.","zh":"維多利亞公園變成了一座發光的音樂小島。"},{"en":"A glowing island of music is a vivid image of a bright, lively place surrounded by sound.","zh":"發光的音樂小島是一個生動意象，指被聲音包圍的明亮熱鬧地方。"},{"en":"At night, a festival ground can look like a glowing island among darker streets.","zh":"夜晚的音樂節場地可以像黑暗街道中的發光小島。"},{"en":"The phrase makes the park feel separate from ordinary city life.","zh":"這個短語令公園感覺與普通城市生活分隔開來。"},{"en":"For the band, the glowing island becomes the place where their dream happens.","zh":"對樂隊來說，發光的音樂小島成為夢想發生的地方。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"food stalls","meaning":"小食檔","examples":[{"en":"Food stalls sent up the smell of grilled squid.","zh":"小食檔散發出燒魷魚的氣味。"},{"en":"Food stalls are small temporary shops selling snacks or meals.","zh":"小食檔是售賣小吃或餐食的小型臨時店舖。"},{"en":"At a festival, food stalls may sell drinks, fish balls, and grilled snacks.","zh":"在音樂節上，小食檔可能賣飲品、魚蛋和燒烤小吃。"},{"en":"Food stalls make the festival feel lively through smell and movement.","zh":"小食檔透過氣味和人流令音樂節更熱鬧。"},{"en":"The smell from food stalls becomes part of the singer’s memory of the night.","zh":"小食檔的氣味成為歌手那晚回憶的一部分。"}],"source":"2012 Q4.pdf","sourcePage":6},{"front":"sent up the smell of","meaning":"散發出……的氣味","examples":[{"en":"Food stalls sent up the smell of grilled squid and curry fish balls.","zh":"小食檔散發出燒魷魚和咖喱魚蛋的氣味。"},{"en":"Sent up the smell of something means released that smell into the air.","zh":"散發出某物的氣味意思是把那種味道釋放到空氣中。"},{"en":"The bakery sent up the smell of fresh bread in the morning.","zh":"麵包店早上散發出新鮮麵包的氣味。"},{"en":"Smells can make a scene feel warm, crowded, and real.","zh":"氣味可以令場景感覺溫暖、擁擠而真實。"},{"en":"The festival is remembered not only through sound, but also through smell.","zh":"音樂節不只透過聲音被記住，也透過氣味被記住。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"grilled squid","meaning":"燒魷魚","examples":[{"en":"The food stalls smelled of grilled squid.","zh":"小食檔有燒魷魚的氣味。"},{"en":"Grilled squid is squid cooked over heat until smoky and fragrant.","zh":"燒魷魚是以高溫烤製至帶煙香和香氣的魷魚。"},{"en":"People often buy grilled squid as a snack at outdoor events.","zh":"人們常在戶外活動買燒魷魚作小食。"},{"en":"The smell of grilled squid can make a festival feel local and lively.","zh":"燒魷魚的氣味可以令音樂節感覺本地而熱鬧。"},{"en":"This detail adds taste and smell to the memory of the performance.","zh":"這個細節為演出回憶加入味道和氣味。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"curry fish balls","meaning":"咖喱魚蛋","examples":[{"en":"The food stalls smelled of curry fish balls.","zh":"小食檔有咖喱魚蛋的氣味。"},{"en":"Curry fish balls are fish balls cooked or served in curry sauce.","zh":"咖喱魚蛋是以咖喱汁烹煮或伴食的魚蛋。"},{"en":"Curry fish balls are a familiar street snack in Hong Kong.","zh":"咖喱魚蛋是香港熟悉的街頭小食。"},{"en":"Their smell can make a festival feel cheerful and crowded.","zh":"它們的氣味可以令音樂節感覺愉快又人多。"},{"en":"Mentioning curry fish balls connects the music festival to local everyday life.","zh":"提到咖喱魚蛋，把音樂節連接到本地日常生活。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"coloured banners","meaning":"彩色橫額","examples":[{"en":"Coloured banners moved in the evening breeze.","zh":"彩色橫額在傍晚微風中飄動。"},{"en":"Coloured banners are bright pieces of fabric or signs used for decoration or information.","zh":"彩色橫額是用於裝飾或提供資訊的鮮色布條或標誌。"},{"en":"Festival banners may show band names, sponsors, or stage directions.","zh":"音樂節橫額可能顯示樂隊名稱、贊助商或舞台方向。"},{"en":"Moving banners make the scene feel alive even before the music starts.","zh":"飄動的橫額令場景在音樂開始前已感覺有生命。"},{"en":"Their colours add visual energy to the night.","zh":"它們的顏色為夜晚增添視覺能量。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"evening breeze","meaning":"傍晚微風","examples":[{"en":"Coloured banners moved in the evening breeze.","zh":"彩色橫額在傍晚微風中飄動。"},{"en":"An evening breeze is a gentle wind that blows in the evening.","zh":"傍晚微風是在晚上初段吹來的輕柔風。"},{"en":"An evening breeze can cool a crowded festival ground.","zh":"傍晚微風可以令擁擠的音樂節場地涼快一點。"},{"en":"The breeze makes the outdoor scene feel open and alive.","zh":"微風令戶外場景感覺開闊而有生命。"},{"en":"The phrase softens the energy of lights, crowds, and loud music.","zh":"這個短語柔化了燈光、人群和大聲音樂的能量。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"somewhere behind us","meaning":"在我們身後某處","examples":[{"en":"Somewhere behind us, another stage was booming with electronic beats.","zh":"在我們身後某處，另一個舞台充滿轟鳴的電子節拍。"},{"en":"Somewhere behind us means in an uncertain place behind the speaker or band.","zh":"在我們身後某處意思是在說話者或樂隊後方某個不確定位置。"},{"en":"Somewhere behind us, festival staff were preparing the next act.","zh":"在我們身後某處，音樂節工作人員正準備下一個表演。"},{"en":"The phrase creates a sense of a larger festival world beyond the band’s stage.","zh":"這個短語創造出樂隊舞台之外更大音樂節世界的感覺。"},{"en":"It reminds readers that many sounds were happening at once.","zh":"它提醒讀者，當時有很多聲音同時發生。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"boom with","meaning":"充滿轟鳴的……","examples":[{"en":"Another stage was booming with electronic beats.","zh":"另一個舞台充滿轟鳴的電子節拍。"},{"en":"To boom with something means to be filled with a loud deep sound.","zh":"充滿轟鳴的某種聲音，意思是被低沉而響亮的聲音填滿。"},{"en":"The hall boomed with applause after the final song.","zh":"最後一首歌後，禮堂充滿轟鳴的掌聲。"},{"en":"A festival stage booming with music can shake the air around it.","zh":"充滿音樂轟鳴聲的音樂節舞台，可以震動周圍空氣。"},{"en":"The booming beats make the festival feel energetic and huge.","zh":"轟鳴節拍令音樂節感覺充滿能量而巨大。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"electronic beats","meaning":"電子節拍","examples":[{"en":"Another stage was booming with electronic beats.","zh":"另一個舞台充滿轟鳴的電子節拍。"},{"en":"Electronic beats are rhythmic sounds made with digital or electronic instruments.","zh":"電子節拍是用數碼或電子樂器製造的節奏聲。"},{"en":"A DJ may build a dance track with fast electronic beats.","zh":"DJ 可能用快速電子節拍製作舞曲。"},{"en":"Electronic beats can give a festival a powerful, modern atmosphere.","zh":"電子節拍可以令音樂節帶有強烈而現代的氣氛。"},{"en":"The distant beats contrast with the band’s own live sound.","zh":"遠處節拍與樂隊自己的現場聲音形成對比。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"first chord rang out","meaning":"第一個和弦響起","examples":[{"en":"When our first chord rang out, the space felt intimate.","zh":"當我們第一個和弦響起時，眼前空間感覺親密。"},{"en":"First chord rang out means the first group of musical notes sounded clearly across the space.","zh":"第一個和弦響起，意思是第一組音符清楚地在空間中傳開。"},{"en":"When the first chord rang out, the audience turned toward the stage.","zh":"當第一個和弦響起，觀眾轉向舞台。"},{"en":"The first chord can change waiting into performance instantly.","zh":"第一個和弦可以瞬間把等待變成演出。"},{"en":"For the band, that chord begins their real conversation with the crowd.","zh":"對樂隊來說，那個和弦開始了他們與觀眾真正的對話。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"rang out","meaning":"響起","examples":[{"en":"Our first chord rang out across the festival ground.","zh":"我們第一個和弦在音樂節場地響起。"},{"en":"Rang out means sounded loudly and clearly.","zh":"響起意思是大聲而清晰地發出聲音。"},{"en":"The school bell rang out across the playground.","zh":"校鐘在操場上響起。"},{"en":"A chord that rings out can make a large place feel suddenly focused.","zh":"響起的和弦可以令大型場地突然變得集中。"},{"en":"The sound ringing out marks the start of the band’s dream performance.","zh":"那聲響起標誌著樂隊夢想演出的開始。"}],"source":"2012 Q4.pdf","sourcePage":7},{"front":"suddenly felt intimate","meaning":"突然感覺親密","examples":[{"en":"The space in front of us suddenly felt intimate.","zh":"我們面前的空間突然感覺親密。"},{"en":"Suddenly felt intimate means unexpectedly became close, warm, or personal.","zh":"突然感覺親密意思是出乎意料地變得接近、溫暖或個人化。"},{"en":"A large hall may suddenly feel intimate when the audience sings quietly together.","zh":"當觀眾一起輕聲唱歌時，大禮堂可能突然感覺親密。"},{"en":"Music can turn strangers into a shared group for a short time.","zh":"音樂可以短暫地把陌生人變成共享群體。"},{"en":"The festival space feels intimate because the crowd starts responding.","zh":"音樂節空間因觀眾開始回應而突然感覺親密。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"had never heard of us","meaning":"從未聽過我們","examples":[{"en":"People who had never heard of us began nodding along.","zh":"從未聽過我們的人開始跟著點頭。"},{"en":"Had never heard of us means did not know the band before this moment.","zh":"從未聽過我們意思是在此刻之前不知道這隊樂隊。"},{"en":"New listeners may enjoy a song even if they had never heard of the artist.","zh":"新聽眾即使從未聽過該歌手，也可能喜歡一首歌。"},{"en":"Winning over people who had never heard of the band can feel especially rewarding.","zh":"打動從未聽過樂隊的人，感覺特別有成就感。"},{"en":"Their response proves that the music can reach strangers.","zh":"他們的反應證明音樂可以觸及陌生人。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"began nodding along","meaning":"開始跟著點頭","examples":[{"en":"Some people began nodding along to our music.","zh":"有些人開始跟著我們的音樂點頭。"},{"en":"Began nodding along means started moving the head with the rhythm.","zh":"開始跟著點頭意思是開始隨節奏點頭。"},{"en":"A listener may nod along when a song has a strong beat.","zh":"當歌曲節拍強烈時，聽眾可能會跟著點頭。"},{"en":"Nodding along is a small but encouraging sign from the crowd.","zh":"跟著點頭是觀眾給出的細小但鼓舞人心的訊號。"},{"en":"The singer relaxes when strangers begin nodding along.","zh":"當陌生人開始跟著點頭時，歌手放鬆下來。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"near the barrier","meaning":"在欄杆附近","examples":[{"en":"A group of children danced near the barrier.","zh":"一群孩子在欄杆附近跳舞。"},{"en":"Near the barrier means close to the fence or rail that separates the crowd from the stage.","zh":"在欄杆附近意思是靠近分隔觀眾和舞台的圍欄或欄杆。"},{"en":"Fans near the barrier often feel close to the performers.","zh":"在欄杆附近的樂迷通常感覺很接近表演者。"},{"en":"Children dancing near the barrier make the scene feel joyful and safe.","zh":"孩子在欄杆附近跳舞，令場面感覺快樂而安全。"},{"en":"The detail shows that the music reaches even the youngest listeners.","zh":"這個細節顯示音樂甚至觸及最年幼的聽眾。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"light sticks","meaning":"螢光棒","examples":[{"en":"Two girls in raincoats waved their light sticks.","zh":"兩個穿雨衣的女孩揮動螢光棒。"},{"en":"Light sticks are glowing sticks that fans wave at concerts or festivals.","zh":"螢光棒是樂迷在演唱會或音樂節揮動的發光棒。"},{"en":"A crowd waving light sticks can look like moving stars.","zh":"揮動螢光棒的人群可以看起來像移動的星星。"},{"en":"Light sticks show excitement and help performers see audience support.","zh":"螢光棒顯示興奮，也幫助表演者看見觀眾支持。"},{"en":"For a new band, even two light sticks can feel like a dream.","zh":"對新樂隊來說，即使只有兩支螢光棒也可以像夢一樣。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"as though","meaning":"好像","examples":[{"en":"They waved their light sticks as though we were already famous.","zh":"她們揮動螢光棒，好像我們已經成名。"},{"en":"As though means as if or in a way that suggests something is true.","zh":"好像意思是彷彿某事真實。"},{"en":"The children cheered as though the small band were world-famous.","zh":"孩子們歡呼，好像這隊小樂隊世界聞名。"},{"en":"This phrase helps describe imagination and feeling rather than fact.","zh":"這個短語幫助描述想像和感覺，而不只是事實。"},{"en":"The girls’ support makes the band feel bigger than it really is.","zh":"那兩個女孩的支持令樂隊感覺比現實更盛大。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"already famous","meaning":"已經成名","examples":[{"en":"They acted as though we were already famous.","zh":"她們的舉動好像我們已經成名。"},{"en":"Already famous means well known before this moment.","zh":"已經成名意思是在這一刻之前已被很多人認識。"},{"en":"A new singer may feel already famous when strangers sing along.","zh":"當陌生人跟著唱時，新歌手可能感覺自己已經成名。"},{"en":"The band is not truly famous yet, but the crowd’s reaction lets them pretend.","zh":"樂隊其實尚未真正成名，但觀眾反應讓他們可以假裝。"},{"en":"The phrase captures the beautiful illusion of a first big show.","zh":"這個短語捕捉首次大型演出的美麗幻覺。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"for those thirty minutes","meaning":"在那三十分鐘裏","examples":[{"en":"For those thirty minutes, we were allowed to pretend.","zh":"在那三十分鐘裏，我們被允許假裝。"},{"en":"For those thirty minutes means during that half-hour period.","zh":"在那三十分鐘裏意思是在那半小時期間。"},{"en":"For those thirty minutes on stage, the band forgot the small rehearsal room.","zh":"在台上那三十分鐘裏，樂隊忘記了細小排練室。"},{"en":"A short performance can feel like a whole world when emotions are strong.","zh":"當情緒強烈時，短短演出可以像一整個世界。"},{"en":"The phrase shows how brief but precious the experience was.","zh":"這個短語顯示那段經歷短暫卻珍貴。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"be allowed to pretend","meaning":"被允許假裝","examples":[{"en":"For thirty minutes, we were allowed to pretend we were famous.","zh":"在三十分鐘裏，我們被允許假裝自己已經成名。"},{"en":"To be allowed to pretend means to have permission, even briefly, to imagine a different reality.","zh":"被允許假裝意思是被容許短暫想像另一種現實。"},{"en":"Children are allowed to pretend they are heroes during a school play.","zh":"孩子在學校話劇中被允許假裝自己是英雄。"},{"en":"The band’s pretending is joyful because the crowd joins the illusion.","zh":"樂隊的假裝令人快樂，因為觀眾一起參與了這個幻象。"},{"en":"Sometimes pretending gives people courage to become more real.","zh":"有時假裝會給人勇氣，讓人變得更真實。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"the best moment came during","meaning":"最精彩的一刻出現在","examples":[{"en":"The best moment came during our third song.","zh":"最精彩的一刻出現在我們第三首歌期間。"},{"en":"The best moment came during means the most special part happened while something was taking place.","zh":"最精彩的一刻出現在某時，意思是最特別的部分在某事進行中發生。"},{"en":"The best moment came during the final chorus when the audience stood up.","zh":"最精彩的一刻出現在最後副歌時，觀眾全都站起來。"},{"en":"This phrase prepares readers for a key memory.","zh":"這個短語讓讀者準備進入關鍵回憶。"},{"en":"The singer’s best moment comes from a mistake that becomes shared joy.","zh":"歌手最精彩的一刻來自一個變成共同喜悅的錯誤。"}],"source":"2012 Q4.pdf","sourcePage":8},{"front":"third song","meaning":"第三首歌","examples":[{"en":"The best moment came during our third song, “Harbour Lights”.","zh":"最精彩的一刻出現在我們第三首歌《Harbour Lights》期間。"},{"en":"Third song means the song performed after the first and second songs.","zh":"第三首歌意思是在第一首和第二首之後演出的歌曲。"},{"en":"By the third song, a band may begin to feel more relaxed on stage.","zh":"到第三首歌時，樂隊可能開始在台上放鬆。"},{"en":"The third song becomes memorable because the audience helps finish the lyric.","zh":"第三首歌令人難忘，因為觀眾幫忙唱完歌詞。"},{"en":"In the post, “Harbour Lights” is where mistake turns into connection.","zh":"在帖文中，《Harbour Lights》是錯誤變成連繫的地方。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"halfway through","meaning":"進行到一半時","examples":[{"en":"Halfway through the chorus, my microphone cable caught under the stand.","zh":"副歌進行到一半時，我的麥克風線卡在架子下面。"},{"en":"Halfway through means at the middle point of an action, song, or event.","zh":"進行到一半時意思是在行動、歌曲或事件的中段。"},{"en":"Halfway through the presentation, the projector stopped working.","zh":"匯報進行到一半時，投影機停止運作。"},{"en":"Problems that happen halfway through can be especially stressful because there is no time to reset.","zh":"進行到一半時出現問題特別有壓力，因為沒有時間重新開始。"},{"en":"The singer’s mistake happens halfway through, but the audience helps carry the song.","zh":"歌手的錯誤在中段發生，但觀眾幫忙承接歌曲。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"chorus","meaning":"副歌","examples":[{"en":"The audience finished the lyric halfway through the chorus.","zh":"觀眾在副歌進行到一半時替我唱完歌詞。"},{"en":"A chorus is the repeated main part of a song, often the easiest part to remember.","zh":"副歌是一首歌中反覆出現的主要部分，通常最容易記住。"},{"en":"Fans often sing loudly during the chorus of a familiar song.","zh":"樂迷常在熟悉歌曲的副歌部分大聲唱。"},{"en":"A strong chorus can help strangers join a performance quickly.","zh":"有力的副歌可以幫助陌生人快速加入演出。"},{"en":"In this show, the chorus becomes a bridge between the band and audience.","zh":"在這場演出中，副歌成為樂隊和觀眾之間的橋樑。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"microphone cable","meaning":"麥克風線","examples":[{"en":"My microphone cable caught under the stand.","zh":"我的麥克風線卡在架子下面。"},{"en":"A microphone cable is the wire that connects a microphone to sound equipment.","zh":"麥克風線是把麥克風連接到音響設備的電線。"},{"en":"A singer may trip or stop moving if a microphone cable gets caught.","zh":"如果麥克風線被卡住，歌手可能會絆倒或停下動作。"},{"en":"Cables should be checked carefully before a live performance.","zh":"現場演出前應仔細檢查電線。"},{"en":"This small cable problem creates the most memorable moment of the show.","zh":"這個小小麥克風線問題創造了演出中最難忘的一刻。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"caught under","meaning":"卡在……下面","examples":[{"en":"The microphone cable caught under the stand.","zh":"麥克風線卡在架子下面。"},{"en":"Caught under means stuck beneath something so it cannot move freely.","zh":"卡在某物下面意思是被困在下方，不能自由移動。"},{"en":"A bag strap may get caught under a chair.","zh":"書包帶可能卡在椅子下面。"},{"en":"When a cable is caught under equipment, a performer may lose timing.","zh":"當電線卡在設備下面，表演者可能失去節奏。"},{"en":"The singer misses a line because the cable is caught under the stand.","zh":"歌手因麥克風線卡在架子下面而漏唱一句。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"mic stand","meaning":"麥克風架","examples":[{"en":"The microphone cable caught under the mic stand.","zh":"麥克風線卡在麥克風架下面。"},{"en":"A mic stand is a stand that holds a microphone at the right height.","zh":"麥克風架是把麥克風固定在合適高度的架子。"},{"en":"Singers adjust a mic stand before rehearsing or performing.","zh":"歌手排練或演出前會調整麥克風架。"},{"en":"A small problem with a mic stand can affect movement on stage.","zh":"麥克風架的小問題也可能影響台上動作。"},{"en":"The mic stand becomes important because it causes a mistake in the chorus.","zh":"麥克風架變得重要，因為它導致副歌中的一個錯誤。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"missed a line","meaning":"漏唱一句","examples":[{"en":"I missed a line during the chorus.","zh":"我在副歌中漏唱了一句。"},{"en":"To miss a line means to fail to sing or say one sentence or lyric at the right time.","zh":"漏唱一句意思是沒有在正確時間唱出或說出一句歌詞或台詞。"},{"en":"An actor may miss a line if they forget their words on stage.","zh":"演員在台上忘詞時可能漏說一句。"},{"en":"Missing a line can feel frightening in a live performance.","zh":"在現場演出中漏唱一句可以令人很害怕。"},{"en":"The singer misses a line, but the audience turns the mistake into a shared moment.","zh":"歌手漏唱一句，但觀眾把錯誤變成共同時刻。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"not quite","meaning":"不完全是","examples":[{"en":"Was it a disaster? Not quite.","zh":"這是災難嗎？不完全是。"},{"en":"Not quite means not completely or not exactly.","zh":"不完全是意思是不是完全如此，或不完全準確。"},{"en":"The presentation went wrong, but not quite badly enough to fail.","zh":"匯報出了問題，但不完全壞到失敗。"},{"en":"This phrase softens a negative judgement.","zh":"這個短語能柔化負面判斷。"},{"en":"The singer admits the mistake, but not quite as a disaster.","zh":"歌手承認錯誤，但不完全把它看成災難。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"without being asked","meaning":"無需被要求","examples":[{"en":"Without being asked, the audience finished the lyric for me.","zh":"觀眾無需被要求，就替我唱完歌詞。"},{"en":"Without being asked means without anyone requesting or instructing it.","zh":"無需被要求意思是沒有人請求或指示也主動做。"},{"en":"A friend may help clean up without being asked.","zh":"朋友可能無需被要求就幫忙收拾。"},{"en":"Unasked help can feel especially generous because it is freely given.","zh":"主動幫忙特別令人感動，因為它是自願給予的。"},{"en":"The audience’s response is powerful because it happens naturally.","zh":"觀眾的回應之所以有力，是因為它自然發生。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"finished the lyric for me","meaning":"替我唱完歌詞","examples":[{"en":"The audience finished the lyric for me.","zh":"觀眾替我唱完歌詞。"},{"en":"Finished the lyric for me means sang the missing words when I could not.","zh":"替我唱完歌詞意思是在我唱不出時唱出缺少的字句。"},{"en":"Fans may finish a lyric for a singer who forgets a line.","zh":"當歌手忘記一句時，樂迷可能替他唱完歌詞。"},{"en":"This action turns an individual mistake into a shared performance.","zh":"這個行動把個人錯誤變成共同演出。"},{"en":"The singer feels supported because the audience carries the song with him.","zh":"歌手感到被支持，因為觀眾和他一起承托歌曲。"}],"source":"2012 Q4.pdf","sourcePage":9},{"front":"cannot begin to describe","meaning":"無法充分描述","examples":[{"en":"I cannot begin to describe what that sounded like from the stage.","zh":"我無法充分描述從舞台上聽到那聲音是怎樣。"},{"en":"Cannot begin to describe means the feeling is too strong to explain properly.","zh":"無法充分描述意思是感受太強烈，難以好好解釋。"},{"en":"I cannot begin to describe how the applause felt after months of practice.","zh":"我無法充分描述經過數月練習後聽到掌聲的感覺。"},{"en":"This phrase shows emotional overwhelm.","zh":"這個短語顯示情緒 overwhelming，難以承受。"},{"en":"The audience’s singing is so moving that ordinary words feel insufficient.","zh":"觀眾的歌聲太感人，令普通文字顯得不足。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"from the stage","meaning":"從舞台上聽來","examples":[{"en":"The audience sounded amazing from the stage.","zh":"從舞台上聽來，觀眾的聲音很驚人。"},{"en":"From the stage means from the performer’s position on the stage.","zh":"從舞台上聽來意思是從表演者在舞台上的位置聽到。"},{"en":"From the stage, the crowd may look like lights and moving faces.","zh":"從舞台上看，人群可能像燈光和移動的面孔。"},{"en":"The same song can feel different from the stage than from the audience area.","zh":"同一首歌從舞台上聽來，和在觀眾區聽來感覺可以不同。"},{"en":"The phrase lets readers hear the crowd through the singer’s experience.","zh":"這個短語讓讀者透過歌手的經驗聽見人群。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"perfect singing","meaning":"完美的歌聲","examples":[{"en":"It was not perfect singing.","zh":"那不是完美的歌聲。"},{"en":"Perfect singing means singing with flawless pitch, timing, and tone.","zh":"完美的歌聲意思是音準、節奏和音色都毫無瑕疵的歌唱。"},{"en":"A choir may practise for months to achieve perfect singing.","zh":"合唱團可能練習數月，以達到完美歌聲。"},{"en":"The audience’s singing was not technically perfect, but it was emotionally powerful.","zh":"觀眾的歌聲技術上並不完美，但情感上很有力量。"},{"en":"The phrase shows that human warmth can matter more than accuracy.","zh":"這個短語顯示人的溫暖可以比準確更重要。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"something better","meaning":"更好的東西","examples":[{"en":"It was not perfect singing; it was something better.","zh":"那不是完美的歌聲；那是更好的東西。"},{"en":"Something better means a thing more meaningful or valuable than what was expected.","zh":"更好的東西意思是比預期更有意義或更有價值的事物。"},{"en":"A messy group song may be something better than a perfect solo because everyone joins in.","zh":"凌亂的集體歌聲可能比完美獨唱更好，因為每個人都參與。"},{"en":"The audience’s imperfect singing becomes better because it is generous and human.","zh":"觀眾不完美的歌聲因慷慨和有人情味而變得更好。"},{"en":"The phrase helps the writer value connection over perfection.","zh":"這個短語幫助作者重視連繫多於完美。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"generous, spontaneous and human","meaning":"慷慨、自然流露而有人情味","examples":[{"en":"The audience’s singing was generous, spontaneous, and human.","zh":"觀眾的歌聲慷慨、自然流露而有人情味。"},{"en":"Generous, spontaneous and human means kind, natural, and full of real feeling.","zh":"慷慨、自然流露而有人情味意思是友善、自然，並充滿真實感情。"},{"en":"A crowd helping a nervous singer can be generous, spontaneous and human.","zh":"人群幫助緊張歌手時，可以是慷慨、自然流露而有人情味的。"},{"en":"These qualities make the mistake feel like connection rather than failure.","zh":"這些特質令錯誤感覺像連繫，而不是失敗。"},{"en":"The phrase describes warmth that no perfect recording can replace.","zh":"這個短語描述了完美錄音無法取代的溫暖。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"spontaneous","meaning":"自發的；自然流露的","examples":[{"en":"The audience’s response was spontaneous.","zh":"觀眾的反應是自發的。"},{"en":"Spontaneous means happening naturally without planning or being forced.","zh":"自發的意思是自然發生，沒有計劃或被強迫。"},{"en":"A spontaneous cheer may rise when a band starts a favourite song.","zh":"當樂隊開始唱最受歡迎的歌時，自發歡呼可能響起。"},{"en":"Spontaneous reactions feel honest because they are not arranged.","zh":"自發反應感覺誠實，因為它不是安排出來的。"},{"en":"The audience’s spontaneous singing becomes the heart of the performance.","zh":"觀眾自發的歌聲成為演出的核心。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"bandmates","meaning":"樂隊成員","examples":[{"en":"I looked at my bandmates, and all of us were grinning.","zh":"我望向我的樂隊成員，我們全都咧嘴笑。"},{"en":"Bandmates are the other members of the same band.","zh":"樂隊成員是同一隊樂隊中的其他成員。"},{"en":"Bandmates practise, argue, improve, and perform together.","zh":"樂隊成員一起練習、爭論、改進和演出。"},{"en":"A quick look between bandmates can communicate joy without words.","zh":"樂隊成員之間的一眼可以無需言語地傳達喜悅。"},{"en":"The singer’s bandmates share the mistake and the miracle with him.","zh":"歌手的樂隊成員和他一起分享錯誤與奇蹟。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"all of us were grinning","meaning":"我們全都咧嘴笑","examples":[{"en":"I looked at my bandmates, and all of us were grinning.","zh":"我望向樂隊成員，我們全都咧嘴笑。"},{"en":"All of us were grinning means everyone was smiling widely with happiness.","zh":"我們全都咧嘴笑意思是每個人都開心地露出大笑容。"},{"en":"After the audience sang along, all of us were grinning with relief.","zh":"觀眾跟著唱後，我們全都鬆一口氣地咧嘴笑。"},{"en":"A grin can show joy that is too sudden for words.","zh":"咧嘴笑可以顯示來得太突然、難以用言語表達的喜悅。"},{"en":"The band’s shared grin proves that the mistake has become a gift.","zh":"樂隊共同的笑容證明錯誤已變成禮物。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"at that point","meaning":"在那一刻","examples":[{"en":"At that point, the performance stopped being about proving ourselves.","zh":"在那一刻，演出不再是關於證明自己。"},{"en":"At that point means at that exact moment in the event or story.","zh":"在那一刻意思是在事件或故事中的那個確切時刻。"},{"en":"At that point, the nervous speaker realised the audience wanted them to succeed.","zh":"在那一刻，緊張的演講者明白觀眾希望他成功。"},{"en":"This phrase marks a turning point in the performance.","zh":"這個短語標誌演出的轉折點。"},{"en":"From that point onward, the show becomes about connection rather than fear.","zh":"從那一刻起，演出變成關於連繫，而不是恐懼。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"proving ourselves","meaning":"證明自己","examples":[{"en":"The performance stopped being about proving ourselves.","zh":"演出不再是關於證明自己。"},{"en":"Proving ourselves means showing others that we are good enough or worthy.","zh":"證明自己意思是向別人顯示自己足夠好或值得被肯定。"},{"en":"A new band may feel pressure to prove itself at its first festival.","zh":"新樂隊在首次音樂節上可能感到要證明自己的壓力。"},{"en":"The audience’s kindness removes some of the need to prove anything.","zh":"觀眾的善意減少了證明一切的需要。"},{"en":"The singer learns that music is more than proving skill.","zh":"歌手明白音樂不只是證明技巧。"}],"source":"2012 Q4.pdf","sourcePage":10},{"front":"became a conversation between","meaning":"變成……之間的對話","examples":[{"en":"The performance became a conversation between us and everyone listening.","zh":"演出變成我們和每一位聆聽者之間的對話。"},{"en":"Became a conversation between means turned into a shared exchange rather than one-way performance.","zh":"變成……之間的對話，意思是轉化為共同交流，而不是單向表演。"},{"en":"A concert becomes a conversation when the crowd sings and the band responds.","zh":"當觀眾跟唱而樂隊回應時，演唱會就變成一場對話。"},{"en":"The phrase shows that live music depends on both performers and listeners.","zh":"這個短語顯示現場音樂依賴表演者和聽眾雙方。"},{"en":"The mistake helps the show become a conversation instead of a test.","zh":"那個錯誤幫助演出變成對話，而不是測試。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"everyone listening","meaning":"每一位聆聽的人","examples":[{"en":"The performance became a conversation with everyone listening.","zh":"演出變成與每一位聆聽的人之間的對話。"},{"en":"Everyone listening means all the people who are hearing and paying attention.","zh":"每一位聆聽的人是指所有正在聽並留意的人。"},{"en":"A singer can feel connected when everyone listening joins the chorus.","zh":"當每一位聆聽的人加入副歌時，歌手會感到連繫。"},{"en":"The phrase includes friends, strangers, and accidental listeners together.","zh":"這個短語把朋友、陌生人和偶然聽眾包括在一起。"},{"en":"Live music becomes special when everyone listening helps create the moment.","zh":"當每一位聆聽的人幫忙創造那一刻時，現場音樂變得特別。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, honesty matters.","zh":"話雖如此，誠實很重要。"},{"en":"That said means despite what has just been said, another point should be considered.","zh":"話雖如此意思是儘管剛才說了某事，仍要考慮另一點。"},{"en":"The show was joyful; that said, the band still made mistakes.","zh":"演出很快樂；話雖如此，樂隊仍然犯了錯。"},{"en":"Writers use this phrase to balance celebration with reflection.","zh":"作者使用這個短語來平衡慶祝和反思。"},{"en":"It helps the singer stay honest instead of only praising the night.","zh":"它幫助歌手保持誠實，而不是只讚美那一晚。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"honesty matters","meaning":"誠實很重要","examples":[{"en":"Honesty matters when we look back on the performance.","zh":"當我們回望演出時，誠實很重要。"},{"en":"Honesty matters means truthfulness is important.","zh":"誠實很重要意思是真實表達很重要。"},{"en":"After a performance, honesty matters because mistakes can become lessons.","zh":"演出後，誠實很重要，因為錯誤可以變成教訓。"},{"en":"Honest reflection helps a band improve without losing joy.","zh":"誠實反思幫助樂隊改善，同時不失去喜悅。"},{"en":"The singer values honesty because the night was meaningful, not perfect.","zh":"歌手重視誠實，因為那一晚有意義，而不是完美。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"unforgettable","meaning":"難忘的","examples":[{"en":"Our first festival show was unforgettable.","zh":"我們首次音樂節演出是難忘的。"},{"en":"Unforgettable means so special that it cannot be easily forgotten.","zh":"難忘的意思是非常特別，難以忘記。"},{"en":"A first performance before a large crowd can be unforgettable.","zh":"第一次在大批觀眾面前表演可以是難忘的。"},{"en":"Moments become unforgettable when fear, joy, and surprise happen together.","zh":"當恐懼、喜悅和驚喜同時發生時，那些時刻會變得難忘。"},{"en":"The show is unforgettable because the audience turned a mistake into connection.","zh":"這場演出難忘，因為觀眾把錯誤變成連繫。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"room for improvement","meaning":"有改善空間","examples":[{"en":"There is certainly room for improvement.","zh":"當中當然有改善空間。"},{"en":"Room for improvement means there are still things that can be made better.","zh":"有改善空間意思是仍有事情可以變得更好。"},{"en":"A band may have room for improvement even after a successful show.","zh":"樂隊即使演出成功，仍可能有改善空間。"},{"en":"Admitting room for improvement helps artists grow.","zh":"承認有改善空間能幫助藝術家成長。"},{"en":"The phrase keeps the post humble and practical.","zh":"這個短語令帖文保持謙遜和實際。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"for one thing","meaning":"首先","examples":[{"en":"For one thing, we should have checked the sound monitors more carefully.","zh":"首先，我們本應更仔細檢查舞台監聽。"},{"en":"For one thing introduces the first reason, example, or point.","zh":"首先用來引出第一個理由、例子或觀點。"},{"en":"For one thing, the team needs to rehearse transitions more often.","zh":"首先，團隊需要更常排練銜接部分。"},{"en":"This phrase helps organise criticism clearly.","zh":"這個短語幫助清楚組織批評。"},{"en":"The singer uses it to begin a practical review of the performance.","zh":"歌手用它開始對演出的實際檢討。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"sound monitors","meaning":"舞台監聽","examples":[{"en":"We should have checked the sound monitors more carefully.","zh":"我們本應更仔細檢查舞台監聽。"},{"en":"Sound monitors are speakers or earpieces that help performers hear themselves and the band.","zh":"舞台監聽是幫助表演者聽見自己和樂隊聲音的喇叭或耳機。"},{"en":"A singer may depend on sound monitors to hear pitch and timing.","zh":"歌手可能依靠舞台監聽來聽音準和節奏。"},{"en":"Poor monitor sound can make performers sing too loudly or lose control.","zh":"監聽聲音不好，可能令表演者唱得太大力或失控。"},{"en":"Checking sound monitors carefully can prevent problems during the opening song.","zh":"仔細檢查舞台監聽可以避免開場歌曲出問題。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"more carefully","meaning":"更仔細地","examples":[{"en":"We should have checked the sound monitors more carefully.","zh":"我們本應更仔細地檢查舞台監聽。"},{"en":"More carefully means with greater attention and caution.","zh":"更仔細地意思是以更多注意和謹慎去做。"},{"en":"A guitarist should check cables more carefully before a live show.","zh":"結他手在現場演出前應更仔細地檢查電線。"},{"en":"Doing something more carefully can prevent small mistakes from becoming public problems.","zh":"更仔細地做事可以防止小錯誤變成公開問題。"},{"en":"The singer learns that excitement should not replace careful preparation.","zh":"歌手明白興奮不應取代仔細準備。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"opening song","meaning":"開場歌曲","examples":[{"en":"During the opening song, I could barely hear my own voice.","zh":"在開場歌曲期間，我幾乎聽不到自己的聲音。"},{"en":"The opening song is the first song in a performance.","zh":"開場歌曲是一場演出中的第一首歌。"},{"en":"A strong opening song can help a band capture the crowd’s attention.","zh":"有力的開場歌曲可以幫助樂隊吸引觀眾注意。"},{"en":"Problems during the opening song can shake a singer’s confidence.","zh":"開場歌曲出問題，可能動搖歌手信心。"},{"en":"The singer struggled because the monitor sound was not clear enough.","zh":"歌手感到困難，因為監聽聲音不夠清楚。"}],"source":"2012 Q4.pdf","sourcePage":11},{"front":"could barely hear","meaning":"幾乎聽不到","examples":[{"en":"I could barely hear my own voice.","zh":"我幾乎聽不到自己的聲音。"},{"en":"Could barely hear means could almost not hear something.","zh":"幾乎聽不到意思是差不多完全聽不見某物。"},{"en":"A singer may barely hear the guitar if the stage sound is too loud.","zh":"如果舞台聲音太大，歌手可能幾乎聽不到結他。"},{"en":"When performers can barely hear themselves, they may push too hard.","zh":"當表演者幾乎聽不到自己時，可能會太用力。"},{"en":"The phrase explains why the singer nearly lost control of the high notes.","zh":"這個短語解釋了為何歌手差點失去高音控制。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"pushed too hard","meaning":"太用力","examples":[{"en":"I pushed too hard and nearly lost control of the high notes.","zh":"我太用力，差點失去高音控制。"},{"en":"Pushed too hard means used too much effort or force.","zh":"太用力意思是使用過多努力或力量。"},{"en":"A singer may push too hard when they cannot hear their own voice.","zh":"當歌手聽不到自己的聲音時，可能會唱得太用力。"},{"en":"Pushing too hard can make singing sound strained and risky.","zh":"太用力會令歌聲聽起來緊繃而危險。"},{"en":"Better sound monitoring helps performers avoid pushing too hard.","zh":"更好的舞台監聽能幫助表演者避免太用力。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"nearly lost control of","meaning":"差點失控","examples":[{"en":"I nearly lost control of the high notes.","zh":"我差點失去高音控制。"},{"en":"Nearly lost control of something means almost failed to manage it properly.","zh":"差點失去某物控制，意思是幾乎無法妥善掌握它。"},{"en":"A speaker may nearly lose control of their voice when nervous.","zh":"演講者緊張時可能差點控制不了聲音。"},{"en":"Losing control on stage can frighten a performer and distract the audience.","zh":"在台上失控可能令表演者害怕，也令觀眾分心。"},{"en":"The singer learns that control depends on preparation, not emotion alone.","zh":"歌手明白控制力取決於準備，而不只是情緒。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"high notes","meaning":"高音","examples":[{"en":"I nearly lost control of the high notes.","zh":"我差點失去高音控制。"},{"en":"High notes are musical notes sung or played at a high pitch.","zh":"高音是以高音高唱出或演奏的音符。"},{"en":"Singers often need breath control to reach high notes safely.","zh":"歌手通常需要呼吸控制，才能安全唱到高音。"},{"en":"High notes can sound powerful when controlled well, but strained when forced.","zh":"高音控制得好時可以很有力量，但強迫唱出時會顯得緊繃。"},{"en":"The singer’s high notes became difficult because he could barely hear himself.","zh":"歌手的高音變得困難，因為他幾乎聽不到自己。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"for another","meaning":"其次","examples":[{"en":"For another, our transitions between songs were not smooth enough.","zh":"其次，我們歌與歌之間的銜接不夠流暢。"},{"en":"For another introduces an additional reason or example.","zh":"其次用來引出額外理由或例子。"},{"en":"For another, the band should practise stage talk before the show.","zh":"其次，樂隊應在演出前練習台上說話。"},{"en":"This phrase helps add a second point after “for one thing”.","zh":"這個短語幫助在「首先」之後加入第二點。"},{"en":"The singer uses it to continue a fair review of mistakes.","zh":"歌手用它繼續公平地檢討錯誤。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"transitions between songs","meaning":"歌與歌之間的銜接","examples":[{"en":"Our transitions between songs were not smooth enough.","zh":"我們歌與歌之間的銜接不夠流暢。"},{"en":"Transitions between songs are the moments when a band moves from one song to the next.","zh":"歌與歌之間的銜接是樂隊由一首歌轉到下一首歌的時刻。"},{"en":"Bands may use short comments or instrument changes during transitions between songs.","zh":"樂隊可能在歌曲銜接時使用簡短說話或換樂器。"},{"en":"Poor transitions can make a performance lose energy.","zh":"差劣的銜接會令演出失去能量。"},{"en":"Practising transitions helps a show feel complete, not only like separate songs.","zh":"練習銜接能令演出感覺完整，而不只是分開的歌曲。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"not smooth enough","meaning":"不夠流暢","examples":[{"en":"Our transitions between songs were not smooth enough.","zh":"我們歌與歌之間的銜接不夠流暢。"},{"en":"Not smooth enough means not flowing naturally or comfortably.","zh":"不夠流暢意思是沒有自然或舒服地連接。"},{"en":"A presentation is not smooth enough if the speaker pauses awkwardly between sections.","zh":"如果演講者在段落之間尷尬停頓，匯報就不夠流暢。"},{"en":"Unsmooth transitions can make the audience notice the gap instead of the music.","zh":"不流暢的銜接會令觀眾注意空隙，而不是音樂。"},{"en":"The band needs more rehearsal so the show moves more naturally.","zh":"樂隊需要更多排練，令演出更自然地推進。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"had practised the songs","meaning":"練習過歌曲","examples":[{"en":"We had practised the songs, but not the silence between them.","zh":"我們練習過歌曲，但沒有練習歌與歌之間的沉默。"},{"en":"Had practised the songs means had rehearsed the music before the performance.","zh":"練習過歌曲意思是在演出前排練過音樂。"},{"en":"A band may practise each song well but forget to practise what happens between songs.","zh":"樂隊可能每首歌都練得很好，卻忘記練習歌曲之間發生的事。"},{"en":"Practising songs is necessary, but a live show also needs flow.","zh":"練習歌曲是必要的，但現場演出也需要流暢感。"},{"en":"The sentence shows that preparation must include the whole performance.","zh":"這句話顯示準備必須包括整場演出。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"the silence between them","meaning":"歌與歌之間的沉默","examples":[{"en":"We had not practised the silence between songs.","zh":"我們沒有練習歌與歌之間的沉默。"},{"en":"The silence between them means the quiet pauses after one song ends and before the next begins.","zh":"歌與歌之間的沉默，是一首歌結束後、下一首歌開始前的安靜停頓。"},{"en":"Silence between songs can feel awkward if the band does not know what to say.","zh":"如果樂隊不知道說甚麼，歌曲之間的沉默可能很尷尬。"},{"en":"Practising silence may sound strange, but it helps the show flow.","zh":"練習沉默聽起來奇怪，但有助演出流暢。"},{"en":"On stage, silence feels louder than it does in rehearsal.","zh":"在台上，沉默比在排練中感覺更響亮。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"awkward seconds","meaning":"尷尬的幾秒","examples":[{"en":"Those awkward seconds felt much longer on stage.","zh":"那些尷尬的幾秒在台上感覺長得多。"},{"en":"Awkward seconds are short moments that feel uncomfortable or embarrassing.","zh":"尷尬的幾秒是感覺不自在或令人尷尬的短暫時刻。"},{"en":"A pause after a forgotten line can become awkward seconds for a speaker.","zh":"忘記台詞後的停頓，對演講者來說可能變成尷尬的幾秒。"},{"en":"Awkward seconds feel longer because everyone is watching.","zh":"尷尬的幾秒感覺更長，因為所有人都在看。"},{"en":"The band learns that even brief silence needs preparation.","zh":"樂隊學到即使短暫沉默也需要準備。"}],"source":"2012 Q4.pdf","sourcePage":12},{"front":"much longer on stage","meaning":"在台上感覺長得多","examples":[{"en":"The silence felt much longer on stage than in rehearsal.","zh":"沉默在台上比在排練中感覺長得多。"},{"en":"Much longer on stage means time seems to stretch during public performance.","zh":"在台上感覺長得多意思是公開表演時，時間好像被拉長。"},{"en":"Five seconds may feel much longer on stage when a microphone stops working.","zh":"當麥克風停止運作時，五秒鐘在台上可能感覺長得多。"},{"en":"Audience attention can make small pauses feel huge.","zh":"觀眾的注意力會令小停頓感覺巨大。"},{"en":"The phrase explains why transitions need real rehearsal, not just musical practice.","zh":"這個短語解釋了為何銜接需要真正排練，而不只是練歌曲。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"in rehearsal","meaning":"在排練中","examples":[{"en":"The pauses felt shorter in rehearsal.","zh":"停頓在排練中感覺較短。"},{"en":"In rehearsal means during practice before the real performance.","zh":"在排練中意思是在正式演出前的練習期間。"},{"en":"Mistakes feel safer in rehearsal because there is no public audience.","zh":"在排練中犯錯感覺較安全，因為沒有公開觀眾。"},{"en":"A pause that feels short in rehearsal may feel long on stage.","zh":"在排練中感覺短的停頓，在台上可能變得很長。"},{"en":"The band learns that rehearsal should imitate the real show more closely.","zh":"樂隊學到排練應更接近真實演出。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"wish I had","meaning":"希望自己當時有","examples":[{"en":"I wish I had spoken to the audience more naturally.","zh":"我希望自己當時有更自然地跟觀眾說話。"},{"en":"Wish I had means I regret not doing something in the past.","zh":"希望自己當時有做某事，意思是後悔過去沒有做那件事。"},{"en":"I wish I had checked the cables before the show.","zh":"我希望自己當時有在演出前檢查電線。"},{"en":"This phrase lets the writer admit regret without destroying the joy of the memory.","zh":"這個短語讓作者承認遺憾，同時不破壞回憶中的喜悅。"},{"en":"The singer wishes he had sounded more like himself.","zh":"歌手希望自己當時聽起來更像自己。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"speak to the audience","meaning":"跟觀眾說話","examples":[{"en":"I wish I had spoken to the audience more naturally.","zh":"我希望自己當時有更自然地跟觀眾說話。"},{"en":"To speak to the audience means to talk directly to the people watching or listening.","zh":"跟觀眾說話意思是直接向正在觀看或聆聽的人說話。"},{"en":"A singer may speak to the audience between songs to create warmth.","zh":"歌手可能在歌曲之間跟觀眾說話，以營造溫暖感。"},{"en":"Speaking naturally can make a performance feel personal.","zh":"自然說話可以令演出感覺更個人化。"},{"en":"The band should rehearse stage talk so speaking to the audience feels less forced.","zh":"樂隊應排練台上說話，讓跟觀眾說話不那麼生硬。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"more naturally","meaning":"更自然地","examples":[{"en":"I should have spoken to the audience more naturally.","zh":"我本應更自然地跟觀眾說話。"},{"en":"More naturally means in a more relaxed, honest, and unforced way.","zh":"更自然地意思是以更放鬆、真誠和不勉強的方式。"},{"en":"A speaker sounds more naturally when they use their own voice instead of copying others.","zh":"當演講者用自己的聲音而不是模仿別人時，會聽起來更自然。"},{"en":"Natural speech helps the audience trust the performer.","zh":"自然說話幫助觀眾信任表演者。"},{"en":"The singer wants to be polished less and genuine more.","zh":"歌手想少一點包裝，多一點真實。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"instead of trying to","meaning":"而不是試圖","examples":[{"en":"Instead of trying to sound like a polished superstar, I should have sounded like myself.","zh":"我本應聽起來像自己，而不是試圖聽起來像包裝成熟的巨星。"},{"en":"Instead of trying to means rather than attempting to do something.","zh":"而不是試圖意思是不是嘗試做某事，而是選擇另一方式。"},{"en":"Instead of trying to copy famous singers, a performer should develop their own style.","zh":"表演者應發展自己的風格，而不是試圖模仿名歌手。"},{"en":"This phrase contrasts false performance with honest identity.","zh":"這個短語把虛假的表演和真實身份作對比。"},{"en":"The singer learns that authenticity matters more than pretending to be perfect.","zh":"歌手學到真誠比假裝完美更重要。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"polished superstar","meaning":"包裝成熟的巨星","examples":[{"en":"I tried to sound like a polished superstar.","zh":"我試圖聽起來像一位包裝成熟的巨星。"},{"en":"A polished superstar is a famous performer who appears smooth, professional, and perfectly prepared.","zh":"包裝成熟的巨星是看起來流暢、專業和準備完美的著名表演者。"},{"en":"New singers may imitate polished superstars because they want to seem confident.","zh":"新歌手可能模仿包裝成熟的巨星，因為他們想顯得有信心。"},{"en":"Sounding polished is not wrong, but it can feel fake if it hides the real person.","zh":"聽起來成熟不一定錯，但如果遮住真實的人，就可能顯得虛假。"},{"en":"The singer later wishes he had sounded less like a superstar and more like himself.","zh":"歌手後來希望自己少一點像巨星，多一點像自己。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"sound like myself","meaning":"聽起來更像自己","examples":[{"en":"I should have sounded more like myself.","zh":"我本應聽起來更像自己。"},{"en":"To sound like myself means to speak or sing in a way that feels genuine and personal.","zh":"聽起來更像自己意思是以真實和個人化的方式說話或唱歌。"},{"en":"A student sounds like herself when she presents ideas in her own words.","zh":"學生用自己的話表達想法時，就聽起來更像自己。"},{"en":"Audiences often connect better with honesty than with imitation.","zh":"觀眾往往比起模仿，更能與真誠產生連繫。"},{"en":"The singer realises that sounding like himself is stronger than sounding perfect.","zh":"歌手意識到聽起來像自己比聽起來完美更有力量。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"would not trade that night for anything","meaning":"我不會用任何東西交換那一晚","examples":[{"en":"I would not trade that night for anything.","zh":"我不會用任何東西交換那一晚。"},{"en":"Would not trade that night for anything means the memory is so valuable that nothing could replace it.","zh":"我不會用任何東西交換那一晚，意思是那段回憶極有價值，沒有東西可以取代。"},{"en":"After a hard but joyful show, a singer may say they would not trade it for anything.","zh":"經歷一場艱難但快樂的演出後，歌手可能說自己不會用任何東西交換它。"},{"en":"This phrase shows deep gratitude despite mistakes.","zh":"這個短語顯示即使有錯誤，仍有深深感激。"},{"en":"The night matters because it gave the band both achievement and lessons.","zh":"那一晚重要，因為它給樂隊成就，也給他們教訓。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"ruin the performance","meaning":"破壞演出","examples":[{"en":"The mistakes did not ruin the performance.","zh":"那些錯誤沒有破壞演出。"},{"en":"To ruin the performance means to spoil it completely.","zh":"破壞演出意思是完全毀掉表演。"},{"en":"A missed lyric may feel serious, but it does not always ruin a show.","zh":"漏唱一句可能感覺嚴重，但不一定會破壞整場演出。"},{"en":"Mistakes can even create connection when people respond kindly.","zh":"當人們善意回應時，錯誤甚至可以創造連繫。"},{"en":"The performance survives because the audience turns imperfection into warmth.","zh":"演出能保留下來，因為觀眾把不完美變成溫暖。"}],"source":"2012 Q4.pdf","sourcePage":13},{"front":"if anything","meaning":"反而","examples":[{"en":"If anything, the mistakes made the achievement feel real.","zh":"反而，那些錯誤令成就感變得真實。"},{"en":"If anything means if we judge the situation more carefully, the opposite or an additional point is true.","zh":"反而意思是如果更仔細判斷，真正情況可能相反或多了一層意思。"},{"en":"The rain did not ruin the concert; if anything, it made the night more memorable.","zh":"雨沒有破壞演唱會；反而令那一晚更難忘。"},{"en":"This phrase helps reverse a negative assumption.","zh":"這個短語幫助扭轉負面假設。"},{"en":"The singer suggests the mistakes strengthened the memory rather than weakened it.","zh":"歌手暗示錯誤強化了回憶，而不是削弱它。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"make the achievement feel real","meaning":"令成就感變得真實","examples":[{"en":"The mistakes made the achievement feel real.","zh":"那些錯誤令成就感變得真實。"},{"en":"To make the achievement feel real means to make success feel honest, human, and believable.","zh":"令成就感變得真實意思是令成功感覺誠實、有人性和可信。"},{"en":"A perfect score may feel distant, but a hard-earned improvement can feel real.","zh":"滿分可能感覺遙遠，但辛苦得來的進步會感覺真實。"},{"en":"Mistakes remind performers that success is built by people, not machines.","zh":"錯誤提醒表演者，成功是由人而不是機器建立的。"},{"en":"The band’s imperfect show feels real because it contains effort and risk.","zh":"樂隊不完美的演出因包含努力和風險而變得真實。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"perfect show","meaning":"完美演出","examples":[{"en":"A perfect show might have been impressive.","zh":"一場完美演出可能令人印象深刻。"},{"en":"A perfect show is a performance with no obvious mistakes.","zh":"完美演出是沒有明顯錯誤的表演。"},{"en":"A perfect show may impress the audience with skill and control.","zh":"完美演出可能以技巧和控制力令觀眾留下深刻印象。"},{"en":"However, perfection is not the only way to create meaning.","zh":"然而，完美不是創造意義的唯一方式。"},{"en":"The singer values an imperfect but human show more than a flawless one.","zh":"歌手比起毫無瑕疵的演出，更重視不完美但有人情味的演出。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"imperfect one","meaning":"這場不完美的演出","examples":[{"en":"This imperfect one taught us how far we had come.","zh":"這場不完美的演出教會我們已走了多遠。"},{"en":"Imperfect one means this performance that had mistakes or flaws.","zh":"這場不完美的演出意思是這場帶有錯誤或瑕疵的表演。"},{"en":"An imperfect exam answer can still show real progress.","zh":"不完美的考試答案仍可以顯示真正進步。"},{"en":"Imperfection can teach more than perfection because it reveals what to improve.","zh":"不完美比完美更能教人，因為它揭示需要改善之處。"},{"en":"The band’s imperfect show becomes a teacher, not a failure.","zh":"樂隊的不完美演出成為老師，而不是失敗。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"how far we have come","meaning":"我們已走了多遠","examples":[{"en":"The performance taught us how far we have come.","zh":"這場演出教會我們已走了多遠。"},{"en":"How far we have come means the amount of progress we have made.","zh":"我們已走了多遠意思是我們已取得多少進步。"},{"en":"Looking back at old recordings can show a band how far it has come.","zh":"回看舊錄音可以讓樂隊看見自己已走了多遠。"},{"en":"The festival stage proves that the band has moved far beyond the rehearsal room.","zh":"音樂節舞台證明樂隊已遠遠走出排練室。"},{"en":"Remembering progress gives artists confidence to continue.","zh":"記住自己的進步能給藝術家繼續前行的信心。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"how far we still have to go","meaning":"我們仍有多遠的路要走","examples":[{"en":"It also taught us how far we still have to go.","zh":"它也教會我們仍有多遠的路要走。"},{"en":"How far we still have to go means how much more improvement or growth remains.","zh":"我們仍有多遠的路要走，意思是還有多少改善或成長尚未完成。"},{"en":"A successful performance can still show a band how far it has to go.","zh":"成功演出仍可以讓樂隊看見自己仍有多遠的路要走。"},{"en":"This phrase balances pride with humility.","zh":"這個短語平衡自豪和謙遜。"},{"en":"The band celebrates progress while admitting the journey is not finished.","zh":"樂隊慶祝進步，同時承認旅程尚未完成。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"arrive earlier","meaning":"早點到達","examples":[{"en":"Next time, we will arrive earlier.","zh":"下次，我們會早點到達。"},{"en":"Arrive earlier means reach a place before the expected or previous time.","zh":"早點到達意思是在預期或之前時間之前抵達某地。"},{"en":"A band may arrive earlier to set up instruments and solve sound problems.","zh":"樂隊可能早點到達，以安裝樂器並解決音響問題。"},{"en":"Arriving early reduces panic before a live show.","zh":"早到能減少現場演出前的驚慌。"},{"en":"The band’s lesson is that better timing creates calmer preparation.","zh":"樂隊學到，更好的時間安排能帶來更冷靜的準備。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"test every cable","meaning":"測試每條電線","examples":[{"en":"Next time, we will test every cable.","zh":"下次，我們會測試每條電線。"},{"en":"To test every cable means to check all wires to make sure they work and do not cause problems.","zh":"測試每條電線意思是檢查所有電線，確保它們能運作並不會造成問題。"},{"en":"A sound engineer may test every cable before a concert begins.","zh":"音響工程師可能在演唱會開始前測試每條電線。"},{"en":"Testing cables prevents technical mistakes during live music.","zh":"測試電線可以防止現場音樂中的技術錯誤。"},{"en":"The microphone cable problem teaches the band to check small details.","zh":"麥克風線問題教會樂隊要檢查小細節。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"rehearse our stage talk","meaning":"排練台上說話","examples":[{"en":"Next time, we will rehearse our stage talk.","zh":"下次，我們會排練台上說話。"},{"en":"To rehearse our stage talk means to practise what the band will say between songs.","zh":"排練台上說話意思是練習樂隊在歌曲之間會說的話。"},{"en":"Singers rehearse stage talk so they can sound natural under pressure.","zh":"歌手排練台上說話，讓自己在壓力下也能聽起來自然。"},{"en":"Practising speech can make transitions between songs smoother.","zh":"練習說話可以令歌與歌之間的銜接更流暢。"},{"en":"The band wants future audience interaction to feel honest, not awkward.","zh":"樂隊希望日後與觀眾互動時感覺真誠，而不尷尬。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"stage talk","meaning":"台上說話","examples":[{"en":"Our stage talk should sound natural.","zh":"我們的台上說話應該聽起來自然。"},{"en":"Stage talk is what performers say to the audience during a show.","zh":"台上說話是表演者在演出期間向觀眾說的話。"},{"en":"Stage talk may include thanking the crowd or introducing the next song.","zh":"台上說話可能包括感謝觀眾或介紹下一首歌。"},{"en":"Good stage talk helps a band connect with listeners between songs.","zh":"好的台上說話幫助樂隊在歌曲之間與聽眾連繫。"},{"en":"Stage talk should feel like real conversation, not a copied script.","zh":"台上說話應像真正對話，而不是照抄稿件。"}],"source":"2012 Q4.pdf","sourcePage":14},{"front":"leave more room for","meaning":"為……預留更多空間","examples":[{"en":"We will leave more room for the unexpected.","zh":"我們會為意料之外的事預留更多空間。"},{"en":"To leave more room for something means to allow space, time, or flexibility for it.","zh":"為某事預留更多空間，意思是為它留出空間、時間或彈性。"},{"en":"A band leaves room for the unexpected by preparing backup cables and extra time.","zh":"樂隊可以透過準備備用電線和額外時間，為意料之外的事預留空間。"},{"en":"Live shows rarely follow the plan perfectly, so flexibility matters.","zh":"現場演出很少完全按計劃進行，所以彈性很重要。"},{"en":"Leaving room for surprises helps performers stay calm when problems happen.","zh":"為驚喜預留空間，有助表演者在問題發生時保持冷靜。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"the unexpected","meaning":"意料之外的事","examples":[{"en":"Live music always leaves room for the unexpected.","zh":"現場音樂總會為意料之外的事留下空間。"},{"en":"The unexpected means events or problems that were not planned or predicted.","zh":"意料之外的事是沒有被計劃或預測到的事件或問題。"},{"en":"A broken cable, sudden rain, or audience singalong can be the unexpected.","zh":"壞掉的電線、突如其來的雨或觀眾跟唱，都可以是意料之外的事。"},{"en":"The unexpected can be frightening, but it can also create magic.","zh":"意料之外的事可以令人害怕，但也可以創造魔法。"},{"en":"The band learns to prepare well while accepting the unexpected.","zh":"樂隊學到要好好準備，同時接受意料之外的事。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"most importantly","meaning":"最重要的是","examples":[{"en":"Most importantly, we will remember what live music really means.","zh":"最重要的是，我們會記住現場音樂真正的意思。"},{"en":"Most importantly introduces the point that matters more than the others.","zh":"最重要的是用來引出比其他觀點更重要的一點。"},{"en":"Most importantly, the band learned that mistakes do not erase connection.","zh":"最重要的是，樂隊學到錯誤不會抹走連繫。"},{"en":"Writers use this phrase to guide readers toward the central lesson.","zh":"作者使用這個短語引導讀者走向核心教訓。"},{"en":"The singer’s most important lesson is about sharing, not perfection.","zh":"歌手最重要的一課是分享，而不是完美。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"live music","meaning":"現場音樂","examples":[{"en":"Live music is not just about hitting every note.","zh":"現場音樂不只是唱準每一個音。"},{"en":"Live music is music performed in front of listeners in real time.","zh":"現場音樂是在聽眾面前即時演奏或演唱的音樂。"},{"en":"A live music show can include mistakes, cheers, and unexpected audience reactions.","zh":"現場音樂演出可以包括錯誤、歡呼和意想不到的觀眾反應。"},{"en":"Live music feels special because performers and listeners share the same moment.","zh":"現場音樂特別，因為表演者和聽眾共享同一刻。"},{"en":"The band learns that live music is about connection as much as accuracy.","zh":"樂隊學到現場音樂關乎連繫，也關乎準確。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"not just about hitting every note","meaning":"不只是唱準每一個音","examples":[{"en":"Live music is not just about hitting every note.","zh":"現場音樂不只是唱準每一個音。"},{"en":"Not just about hitting every note means music is not only about technical accuracy.","zh":"不只是唱準每一個音意思是音樂不只關於技術準確。"},{"en":"A singer can hit every note but still fail to move the audience.","zh":"歌手可以唱準每一個音，卻仍未能感動觀眾。"},{"en":"Live performance also needs feeling, timing, honesty, and connection.","zh":"現場演出也需要感情、時機、真誠和連繫。"},{"en":"This phrase argues that music is human, not merely mechanical.","zh":"這個短語主張音樂是人的，而不只是機械的。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"hitting every note","meaning":"唱準每一個音","examples":[{"en":"Singers worry about hitting every note during a live show.","zh":"歌手在現場演出時會擔心能否唱準每一個音。"},{"en":"Hitting every note means singing each musical note accurately.","zh":"唱準每一個音意思是準確唱出每個音符。"},{"en":"Vocal practice helps singers hit every note with better control.","zh":"聲樂練習幫助歌手更有控制地唱準每一個音。"},{"en":"Hitting every note is important, but it is not the whole meaning of performance.","zh":"唱準每一個音很重要，但不是演出的全部意義。"},{"en":"The audience may remember sincerity more than perfect notes.","zh":"觀眾可能比起完美音準，更記得真誠。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"sharing a pulse with","meaning":"與……分享同一種脈搏","examples":[{"en":"Live music is about sharing a pulse with people who choose to listen.","zh":"現場音樂是與選擇聆聽的人分享同一種脈搏。"},{"en":"Sharing a pulse with someone means feeling the same rhythm, energy, or emotional beat together.","zh":"與某人分享同一種脈搏，意思是一起感受同一節奏、能量或情感跳動。"},{"en":"A crowd and band share a pulse when everyone claps to the same rhythm.","zh":"當觀眾和樂隊按同一節奏拍手時，他們就在分享同一種脈搏。"},{"en":"This phrase makes music feel like a shared heartbeat.","zh":"這個短語令音樂感覺像共享的心跳。"},{"en":"The singer values live music because it lets strangers share one pulse for a few minutes.","zh":"歌手重視現場音樂，因為它讓陌生人在幾分鐘內共享同一脈搏。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"a few precious minutes","meaning":"珍貴的幾分鐘","examples":[{"en":"People chose to listen for a few precious minutes.","zh":"人們選擇聆聽那珍貴的幾分鐘。"},{"en":"A few precious minutes means a short time that feels valuable and meaningful.","zh":"珍貴的幾分鐘意思是一段短暫但有價值和有意義的時間。"},{"en":"A performer may feel grateful when strangers give them a few precious minutes of attention.","zh":"當陌生人給予表演者珍貴幾分鐘的注意力時，表演者可能感到感激。"},{"en":"Attention is precious because people could easily walk away at a festival.","zh":"注意力很珍貴，因為在音樂節上人們很容易走開。"},{"en":"Those few minutes matter because they turn unknown listeners into part of the story.","zh":"那幾分鐘重要，因為它們把不認識的聽眾變成故事的一部分。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"accidental listener","meaning":"偶然聽到的觀眾","examples":[{"en":"Thank you to every friend, stranger, and accidental listener who stayed.","zh":"多謝每位朋友、陌生人和留下來的偶然聽眾。"},{"en":"An accidental listener is someone who hears the music by chance, not by plan.","zh":"偶然聽到的觀眾是碰巧聽到音樂，而不是計劃前來的人。"},{"en":"A passer-by at a festival may become an accidental listener.","zh":"音樂節上的路人可能成為偶然聽到的觀眾。"},{"en":"Accidental listeners are special because they choose to stay after hearing something unexpected.","zh":"偶然聽眾特別，因為他們聽到意外的音樂後選擇留下。"},{"en":"The band thanks them because their attention was freely given.","zh":"樂隊感謝他們，因為他們的注意力是自願給予的。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"every friend, stranger and accidental listener","meaning":"每位朋友、陌生人和偶然聽眾","examples":[{"en":"The singer thanked every friend, stranger, and accidental listener who stayed.","zh":"歌手感謝每位朋友、陌生人和留下來的偶然聽眾。"},{"en":"Every friend, stranger and accidental listener means all kinds of people who gave the band attention.","zh":"每位朋友、陌生人和偶然聽眾意思是所有給予樂隊注意力的人。"},{"en":"Friends came with support, strangers came with curiosity, and accidental listeners came by chance.","zh":"朋友帶著支持而來，陌生人帶著好奇而來，偶然聽眾則碰巧遇上。"},{"en":"The phrase makes the audience feel wide, mixed, and generous.","zh":"這個短語令觀眾感覺廣闊、多元而慷慨。"},{"en":"Thanking all three groups shows the singer’s gratitude for every listener.","zh":"感謝這三類人顯示歌手對每位聽眾的感激。"}],"source":"2012 Q4.pdf","sourcePage":15},{"front":"who stayed","meaning":"留下來的人","examples":[{"en":"The band thanked everyone who stayed to listen.","zh":"樂隊感謝每一位留下來聆聽的人。"},{"en":"Who stayed means who remained instead of leaving.","zh":"留下來的人意思是沒有離開而繼續在場的人。"},{"en":"At a festival, people who stayed gave the band their time and attention.","zh":"在音樂節上，留下來的人把時間和注意力給了樂隊。"},{"en":"Staying matters because audiences always have other stages and choices.","zh":"留下來很重要，因為觀眾總有其他舞台和選擇。"},{"en":"The phrase shows gratitude for listeners who chose connection over walking away.","zh":"這個短語顯示對選擇連繫而不是走開的聽眾的感激。"}],"source":"2012 Q4.pdf","sourcePage":16},{"front":"first festival performance is over","meaning":"首次音樂節演出已經結束","examples":[{"en":"Our first festival performance is over.","zh":"我們的首次音樂節演出已經結束。"},{"en":"First festival performance is over means the band’s first music festival show has finished.","zh":"首次音樂節演出已經結束，意思是樂隊第一次音樂節表演已完成。"},{"en":"When a big event is over, performers may feel both empty and proud.","zh":"當大型活動結束後，表演者可能同時感到空虛和自豪。"},{"en":"The end of the performance does not end the emotion it created.","zh":"演出結束並不代表它創造的情感結束。"},{"en":"The singer knows the show is over, but its echo remains inside him.","zh":"歌手知道演出已結束，但它的回響仍留在心中。"}],"source":"2012 Q4.pdf","sourcePage":16},{"front":"the echo of it","meaning":"它的回響","examples":[{"en":"The echo of the performance is still ringing in my chest.","zh":"那場演出的回響仍在我胸口迴盪。"},{"en":"The echo of it means the lasting sound, feeling, or memory of the experience.","zh":"它的回響意思是那段經歷留下的聲音、感覺或記憶。"},{"en":"After applause ends, the echo of it may stay in a performer’s mind.","zh":"掌聲結束後，它的回響可能仍留在表演者腦海中。"},{"en":"An echo can be emotional, not only physical sound.","zh":"回響可以是情感上的，不只是物理聲音。"},{"en":"The phrase shows that the night continues inside the singer after it ends.","zh":"這個短語顯示那一晚結束後仍在歌手心中延續。"}],"source":"2012 Q4.pdf","sourcePage":16},{"front":"still ringing in my chest","meaning":"仍在我胸口迴盪","examples":[{"en":"The echo of the performance is still ringing in my chest.","zh":"那場演出的回響仍在我胸口迴盪。"},{"en":"Still ringing in my chest means the memory or emotion is still felt deeply inside me.","zh":"仍在我胸口迴盪意思是那份記憶或情緒仍在內心深處被感受到。"},{"en":"After a moving concert, the music may feel as if it is still ringing in the chest.","zh":"感人的演唱會後，音樂可能像仍在胸口迴盪。"},{"en":"The phrase connects sound with heartbeat and emotion.","zh":"這個短語把聲音與心跳和情感連接起來。"},{"en":"The singer is no longer on stage, but the performance still lives inside him.","zh":"歌手已不在舞台上，但那場演出仍活在他心裏。"}],"source":"2012 Q4.pdf","sourcePage":16}],"dse/writing/part-b/2012/Q5":[{"front":"speak up","meaning":"大膽發言","examples":[{"en":"Students should learn to speak up when they have ideas.","zh":"學生應學會在有想法時大膽發言。"},{"en":"To speak up means to express your thoughts clearly, especially when you might feel nervous.","zh":"speak up 的意思是清楚表達自己的想法，尤其是在可能感到緊張時。"},{"en":"A quiet student can learn to speak up during group discussions.","zh":"安靜的學生可以在小組討論中學會大膽發言。"},{"en":"Speaking up does not mean being rude; it means sharing your view with confidence.","zh":"大膽發言不代表無禮；它是指有信心地分享自己的看法。"},{"en":"This phrase is useful when encouraging students to take part instead of staying silent.","zh":"當鼓勵學生參與而不是保持沉默時，這個短語很有用。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"think sharply","meaning":"敏銳地思考","examples":[{"en":"The debating club helps students think sharply.","zh":"辯論學會幫助學生敏銳地思考。"},{"en":"To think sharply means to think clearly, quickly, and critically.","zh":"think sharply 的意思是清晰、快速而批判地思考。"},{"en":"Debaters think sharply when they notice weak evidence in an opponent’s argument.","zh":"當辯手注意到對方論點中的薄弱證據時，就是敏銳地思考。"},{"en":"Students who think sharply can separate facts from feelings more easily.","zh":"能敏銳地思考的學生較容易分辨事實與情緒。"},{"en":"This phrase describes strong mental focus and careful judgement.","zh":"這個短語描述強烈的思考專注和細心判斷。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"stand tall","meaning":"堂堂正正地站穩","examples":[{"en":"Debating helps students stand tall when it matters.","zh":"辯論幫助學生在關鍵時刻堂堂正正地站穩。"},{"en":"To stand tall means to act with confidence, dignity, and courage.","zh":"stand tall 的意思是帶着信心、尊嚴和勇氣行事。"},{"en":"A student can stand tall when defending a fair idea in front of classmates.","zh":"學生在同學面前捍衛公平想法時，可以堂堂正正地站穩。"},{"en":"Standing tall does not mean never feeling nervous; it means not letting fear silence you.","zh":"堂堂正正地站穩不代表從不緊張；而是不讓恐懼令自己沉默。"},{"en":"This phrase shows confidence in moments that require bravery.","zh":"這個短語展示在需要勇氣的時刻中的信心。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"Principal, teachers and fellow students","meaning":"校長、老師及各位同學","examples":[{"en":"Good morning, Principal, teachers and fellow students.","zh":"校長、老師及各位同學，早晨。"},{"en":"Principal, teachers and fellow students is a formal way to address a school audience.","zh":"Principal, teachers and fellow students 是正式稱呼校園聽眾的方式。"},{"en":"A student speaker may begin a morning assembly speech by greeting the Principal, teachers and fellow students.","zh":"學生演講者可以在早會演講開始時問候校長、老師及各位同學。"},{"en":"This phrase shows respect for both authority figures and classmates.","zh":"這個短語顯示對權威人物和同學的尊重。"},{"en":"It helps a speech begin in a polite and organised way.","zh":"它幫助演講以禮貌而有條理的方式開始。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"have you ever","meaning":"你有沒有試過","examples":[{"en":"Have you ever thought of the perfect reply too late?","zh":"你有沒有試過太遲才想到最完美的回應？"},{"en":"Have you ever is used to ask whether someone has had a particular experience before.","zh":"have you ever 用來詢問某人是否曾經有過某種經歷。"},{"en":"Have you ever wanted to answer in class but lost courage at the last second?","zh":"你有沒有試過想在課堂上回答，卻在最後一秒失去勇氣？"},{"en":"Speakers use this question form to make listeners think about their own lives.","zh":"演講者使用這種問句，讓聽眾思考自己的經歷。"},{"en":"This phrase is useful for opening a speech with a relatable situation.","zh":"這個短語適合用貼近生活的情境作演講開場。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"hear a comment","meaning":"聽到一句評論","examples":[{"en":"You may hear a comment you disagree with in class.","zh":"你可能在課堂上聽到一句你不同意的評論。"},{"en":"To hear a comment means to listen to someone’s opinion, remark, or statement.","zh":"hear a comment 的意思是聽到某人的意見、說話或陳述。"},{"en":"A student may hear a comment about homework and want to respond.","zh":"學生可能聽到一句關於功課的評論，並想作出回應。"},{"en":"Hearing a comment you dislike can become a chance to practise respectful disagreement.","zh":"聽到不喜歡的評論，可以成為練習尊重地表達不同意見的機會。"},{"en":"This phrase describes the first moment before a response or debate begins.","zh":"這個短語描述回應或辯論開始前的第一刻。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"disagree with","meaning":"不同意","examples":[{"en":"Sometimes students hear comments they disagree with.","zh":"有時學生會聽到他們不同意的評論。"},{"en":"To disagree with something means to have a different opinion from it.","zh":"disagree with something 的意思是對某事持有不同意見。"},{"en":"A student may disagree with a classmate’s view on school uniforms.","zh":"學生可能不同意同學對校服的看法。"},{"en":"Disagreeing with someone does not mean disrespecting them.","zh":"不同意某人不代表不尊重他。"},{"en":"This phrase is central to debate because debate begins with different views.","zh":"這個短語是辯論的核心，因為辯論始於不同觀點。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"the perfect reply","meaning":"最完美的回應","examples":[{"en":"A student may think of the perfect reply only after the lesson has ended.","zh":"學生可能直到課堂結束後才想到最完美的回應。"},{"en":"The perfect reply is the answer or response that seems exactly right for the situation.","zh":"perfect reply 是在某情況下看似最恰當的答案或回應。"},{"en":"Many people think of the perfect reply after the chance to speak has passed.","zh":"許多人在發言機會過去後，才想到最完美的回應。"},{"en":"Debate training helps students prepare better replies under pressure.","zh":"辯論訓練幫助學生在壓力下準備更好的回應。"},{"en":"This phrase shows the frustration of knowing what to say too late.","zh":"這個短語展示太遲才知道該說甚麼的懊惱。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"only after","meaning":"直到……之後才","examples":[{"en":"The perfect reply may come only after the lesson has ended.","zh":"最完美的回應可能直到課堂結束後才出現。"},{"en":"Only after means not until a particular event has happened.","zh":"only after 的意思是直到某件事發生之後才。"},{"en":"Some students find their confidence only after practising several speeches.","zh":"有些學生直到練習幾次演講後才找到信心。"},{"en":"This phrase shows that something happens later than expected or desired.","zh":"這個短語顯示某事比預期或希望中更遲發生。"},{"en":"It is useful when describing delayed understanding or reaction.","zh":"當描述遲來的理解或反應時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"you are not alone","meaning":"你並不孤單","examples":[{"en":"If this has happened to you, you are not alone.","zh":"如果這件事曾發生在你身上，你並不孤單。"},{"en":"You are not alone means other people have experienced the same feeling or problem.","zh":"you are not alone 的意思是其他人也經歷過同樣感受或問題。"},{"en":"If you feel nervous before speaking, you are not alone.","zh":"如果你在發言前感到緊張，你並不孤單。"},{"en":"This phrase comforts listeners by showing that their struggle is shared.","zh":"這個短語透過顯示掙扎是共同的來安慰聽眾。"},{"en":"It helps create connection between the speaker and the audience.","zh":"它幫助演講者與聽眾建立連繫。"}],"source":"2012 Q5.pdf","sourcePage":1},{"front":"a world where","meaning":"一個……的世界","examples":[{"en":"We live in a world where opinions travel faster than facts.","zh":"我們生活在一個意見比事實傳播得更快的世界。"},{"en":"A world where means a situation or society in which something is true or common.","zh":"a world where 的意思是某事真實或常見的情況或社會。"},{"en":"We live in a world where students meet information every time they open their phones.","zh":"我們生活在一個學生每次打開手機都接觸資訊的世界。"},{"en":"This phrase helps speakers describe the wider environment behind a problem.","zh":"這個短語幫助演講者描述問題背後的更大環境。"},{"en":"It is useful when connecting a school activity to real life.","zh":"當把校園活動與現實生活連繫起來時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"opinions travel faster than facts","meaning":"意見比事實傳播得更快","examples":[{"en":"Opinions often travel faster than facts online.","zh":"在網上，意見往往比事實傳播得更快。"},{"en":"Opinions travel faster than facts means people’s views may spread before evidence is checked.","zh":"opinions travel faster than facts 的意思是人們的看法可能在證據被核實前已經流傳。"},{"en":"A rumour about school rules can travel faster than the official notice.","zh":"關於校規的謠言可能比正式通告傳播得更快。"},{"en":"When opinions travel faster than facts, careful thinking becomes more important.","zh":"當意見比事實傳播得更快，細心思考就變得更重要。"},{"en":"This phrase warns listeners about the speed and danger of careless information.","zh":"這個短語提醒聽眾注意粗心資訊的速度和危險。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"want to speak up","meaning":"想大膽發言","examples":[{"en":"Many students want to speak up.","zh":"許多學生想大膽發言。"},{"en":"Want to speak up means wish to express an opinion but may still feel unsure.","zh":"want to speak up 的意思是希望表達意見，但可能仍感到不確定。"},{"en":"A student may want to speak up when a group makes an unfair decision.","zh":"當小組作出不公平決定時，學生可能想大膽發言。"},{"en":"Wanting to speak up is the first step toward becoming a stronger communicator.","zh":"想大膽發言是成為更強溝通者的第一步。"},{"en":"This phrase shows desire before confidence fully develops.","zh":"這個短語展示信心完全建立前的意願。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"do not quite know how","meaning":"不太知道怎樣做","examples":[{"en":"Many students want to speak up but do not quite know how.","zh":"許多學生想大膽發言，但不太知道怎樣做。"},{"en":"Do not quite know how means are unsure about the exact way to do something.","zh":"do not quite know how 的意思是不太確定做某事的具體方法。"},{"en":"A student may have good ideas but not quite know how to present them clearly.","zh":"學生可能有好想法，但不太知道怎樣清楚表達。"},{"en":"Debate training helps students who want to speak but do not know where to start.","zh":"辯論訓練幫助想發言但不知道從何開始的學生。"},{"en":"This phrase describes uncertainty rather than inability.","zh":"這個短語描述不確定，而不是沒有能力。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"school debating club","meaning":"學校辯論學會","examples":[{"en":"Our school debating club is looking for new members.","zh":"我們的學校辯論學會正在招募新會員。"},{"en":"A school debating club is a student group that practises argument, public speaking, and critical thinking.","zh":"school debating club 是練習論證、公開演說和批判思考的學生組織。"},{"en":"The school debating club may meet after school to prepare speeches and mock debates.","zh":"學校辯論學會可能在放學後聚會，準備演辭和模擬辯論。"},{"en":"Joining a debating club can help students become clearer and braver speakers.","zh":"加入辯論學會可以幫助學生成為更清晰和更勇敢的演說者。"},{"en":"This phrase names the organisation being promoted in the speech.","zh":"這個短語點出演講中正在宣傳的組織。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"look for new members","meaning":"招募新會員","examples":[{"en":"The debating club is looking for new members.","zh":"辯論學會正在招募新會員。"},{"en":"To look for new members means to invite more people to join a group.","zh":"look for new members 的意思是邀請更多人加入一個團體。"},{"en":"A club may look for new members at the start of the school term.","zh":"學會可以在學期初招募新會員。"},{"en":"Looking for new members helps a club bring in fresh ideas and energy.","zh":"招募新會員幫助學會帶來新想法和活力。"},{"en":"This phrase is useful when announcing recruitment.","zh":"這個短語適合用於宣布招募。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"make room for","meaning":"為……騰出位置","examples":[{"en":"The club wants to make room for different kinds of students.","zh":"學會想為不同類型的學生騰出位置。"},{"en":"To make room for someone means to include them and give them space to participate.","zh":"make room for someone 的意思是包容某人並給他參與空間。"},{"en":"A debating club should make room for shy students as well as confident speakers.","zh":"辯論學會應為害羞學生和有信心的演說者都騰出位置。"},{"en":"Making room for different students makes the club more welcoming and fair.","zh":"為不同學生騰出位置，令學會更友善和公平。"},{"en":"This phrase shows inclusion rather than selection only for the strongest.","zh":"這個短語展示共融，而不是只挑選最強的人。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"curious","meaning":"好奇的","examples":[{"en":"Curious students are welcome to join the debating club.","zh":"好奇的學生歡迎加入辯論學會。"},{"en":"Curious means eager to learn, ask questions, or understand more.","zh":"curious 的意思是渴望學習、提問或了解更多。"},{"en":"A curious student may join debating because she wants to explore current affairs.","zh":"好奇的學生可能因想探索時事而加入辯論。"},{"en":"Curiosity helps debaters ask better questions and examine assumptions.","zh":"好奇心幫助辯手提出更好的問題並檢視假設。"},{"en":"This word describes a learning attitude that suits debate.","zh":"這個詞描述適合辯論的學習態度。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"nervous","meaning":"緊張的","examples":[{"en":"Nervous students can still benefit from debating.","zh":"緊張的學生仍可以從辯論中受益。"},{"en":"Nervous means worried, tense, or lacking confidence before doing something.","zh":"nervous 的意思是在做某事前擔心、緊繃或缺乏信心。"},{"en":"A nervous student may shake before her first speech but improve with practice.","zh":"緊張的學生第一次演講前可能會發抖，但可透過練習進步。"},{"en":"Debate clubs can help nervous students because they provide a safe place to practise.","zh":"辯論學會可以幫助緊張的學生，因為它提供安全的練習空間。"},{"en":"This word shows that fear does not prevent growth.","zh":"這個詞顯示恐懼不會阻止成長。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"outspoken","meaning":"直言不諱的","examples":[{"en":"Outspoken students can learn to argue more fairly.","zh":"直言不諱的學生可以學會更公平地論證。"},{"en":"Outspoken means willing to express opinions openly and directly.","zh":"outspoken 的意思是願意公開而直接地表達意見。"},{"en":"An outspoken student may speak quickly but still need to learn careful listening.","zh":"直言不諱的學生可能說話很快，但仍需要學會細心聆聽。"},{"en":"Debate can help outspoken students become fairer and more precise.","zh":"辯論可以幫助直言不諱的學生變得更公平和更精準。"},{"en":"This word describes confidence that needs guidance and discipline.","zh":"這個詞描述需要引導和紀律的信心。"}],"source":"2012 Q5.pdf","sourcePage":2},{"front":"completely new","meaning":"完全沒有經驗的","examples":[{"en":"The club welcomes students who are completely new to debating.","zh":"學會歡迎完全沒有辯論經驗的學生。"},{"en":"Completely new means having no previous experience with something.","zh":"completely new 的意思是對某事沒有任何過往經驗。"},{"en":"A student completely new to debating may begin by learning what a motion is.","zh":"完全沒有辯論經驗的學生可以先學習甚麼是辯題。"},{"en":"Being completely new is not a problem if the club provides patient training.","zh":"如果學會提供有耐性的訓練，完全沒有經驗並不是問題。"},{"en":"This phrase reassures beginners that they are welcome.","zh":"這個短語安慰初學者，讓他們知道自己受歡迎。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"think clearly","meaning":"清晰思考","examples":[{"en":"Debating helps students think clearly.","zh":"辯論幫助學生清晰思考。"},{"en":"To think clearly means to organise thoughts in a logical and understandable way.","zh":"think clearly 的意思是以有邏輯和容易理解的方式組織想法。"},{"en":"Students think clearly when they know their claim, reasons, and evidence.","zh":"當學生知道自己的主張、理由和證據時，就是清晰思考。"},{"en":"Clear thinking helps speakers avoid confusing examples and emotional exaggeration.","zh":"清晰思考幫助演說者避免混亂例子和情緒化誇張。"},{"en":"This phrase describes one of the main benefits of debate.","zh":"這個短語描述辯論的主要好處之一。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"speak confidently","meaning":"有信心地說話","examples":[{"en":"Debating trains students to speak confidently.","zh":"辯論訓練學生有信心地說話。"},{"en":"To speak confidently means to express ideas with a steady voice and belief in what you say.","zh":"speak confidently 的意思是以穩定聲線和對自己說話的信念表達想法。"},{"en":"A shy student can learn to speak confidently after repeated practice.","zh":"害羞學生可以在反覆練習後學會有信心地說話。"},{"en":"Speaking confidently does not mean speaking loudly all the time.","zh":"有信心地說話不代表一直大聲說話。"},{"en":"This phrase shows growth in public speaking.","zh":"這個短語展示公開演說方面的成長。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"listen respectfully","meaning":"尊重地聆聽","examples":[{"en":"Good debaters learn to listen respectfully.","zh":"優秀辯手學會尊重地聆聽。"},{"en":"To listen respectfully means to pay attention to others without interrupting, mocking, or dismissing them.","zh":"listen respectfully 的意思是專心聆聽別人，而不打斷、嘲笑或否定對方。"},{"en":"A debater listens respectfully when she writes down an opponent’s point before answering it.","zh":"當辯手先寫下對方論點再回應時，就是尊重地聆聽。"},{"en":"Respectful listening makes disagreement more fair and useful.","zh":"尊重地聆聽令分歧更公平和更有用。"},{"en":"This phrase reminds students that debating is not only about speaking.","zh":"這個短語提醒學生，辯論不只是說話。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"I would like to show you that","meaning":"我想向你們說明","examples":[{"en":"Today, I would like to show you that debating is for everyone.","zh":"今天，我想向你們說明辯論適合每一個人。"},{"en":"I would like to show you that means I want to explain or prove something to you.","zh":"I would like to show you that 的意思是我想向你解釋或證明某事。"},{"en":"I would like to show you that confidence can be trained, not simply born.","zh":"我想向你們說明信心可以被訓練出來，而不只是天生的。"},{"en":"Speakers use this phrase to introduce the main purpose of a speech.","zh":"演講者使用這個短語來介紹演講的主要目的。"},{"en":"It sounds polite and clear in a formal school presentation.","zh":"它在正式校園演說中聽起來禮貌而清晰。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"not just an activity for","meaning":"不只是給……的活動","examples":[{"en":"Debating is not just an activity for the loudest students.","zh":"辯論不只是給聲音最大的學生的活動。"},{"en":"Not just an activity for means not only meant for one particular kind of person.","zh":"not just an activity for 的意思是不只適合某一類人。"},{"en":"Debate is not just an activity for confident speakers; it can help nervous students too.","zh":"辯論不只是給有信心的演說者的活動；它也能幫助緊張的學生。"},{"en":"This phrase challenges a common misunderstanding about who belongs in debate.","zh":"這個短語挑戰人們對誰適合辯論的常見誤解。"},{"en":"It helps make the club sound more inclusive.","zh":"它幫助學會聽起來更共融。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"the loudest students","meaning":"聲音最大的學生","examples":[{"en":"Debating is not only for the loudest students.","zh":"辯論不只是給聲音最大的學生。"},{"en":"The loudest students are those who speak most boldly, loudly, or often.","zh":"the loudest students 是說話最大膽、最大聲或最頻繁的學生。"},{"en":"The loudest students may enjoy speaking, but they still need to learn evidence and fairness.","zh":"聲音最大的學生可能喜歡發言，但仍需要學習證據和公平。"},{"en":"Quiet students can become excellent debaters even if they are not the loudest students.","zh":"安靜學生即使不是聲音最大的學生，也可以成為出色辯手。"},{"en":"This phrase contrasts noisy confidence with real debating skill.","zh":"這個短語把吵鬧的信心與真正辯論技巧作對比。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"training for anyone who","meaning":"給任何想……的人的訓練","examples":[{"en":"Debating is training for anyone who wants to think better.","zh":"辯論是給任何想思考得更好的人提供的訓練。"},{"en":"Training for anyone who means practice that is open to all people with a certain goal.","zh":"training for anyone who 的意思是開放給有某個目標的所有人的練習。"},{"en":"The club offers training for anyone who wants to speak more clearly.","zh":"學會為任何想說得更清楚的人提供訓練。"},{"en":"This phrase shows that debating is not limited to naturally confident students.","zh":"這個短語顯示辯論不只限於天生有信心的學生。"},{"en":"It makes the activity sound accessible and purposeful.","zh":"它令活動聽起來容易參與而有目標。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"sharper, braver and fairer","meaning":"更敏銳、更勇敢、更公平","examples":[{"en":"Debating can make students sharper, braver and fairer.","zh":"辯論可以令學生更敏銳、更勇敢和更公平。"},{"en":"Sharper, braver and fairer means more thoughtful, more courageous, and more respectful of justice.","zh":"sharper, braver and fairer 的意思是更有思想、更有勇氣，也更尊重公義。"},{"en":"Students become sharper by analysing arguments, braver by speaking up, and fairer by listening to both sides.","zh":"學生透過分析論點變得更敏銳，透過大膽發言變得更勇敢，透過聆聽雙方變得更公平。"},{"en":"These qualities matter not only in competitions but also in daily life.","zh":"這些特質不只在比賽中重要，在日常生活中也重要。"},{"en":"This phrase summarises the personal growth debating can bring.","zh":"這個短語總結辯論可以帶來的個人成長。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"there is more to…than…","meaning":"……不只是……","examples":[{"en":"There is more to the debating club than standing behind a lectern.","zh":"辯論學會不只是站在講台後。"},{"en":"There is more to A than B means A includes deeper or wider things than B alone.","zh":"there is more to A than B 的意思是 A 包含比單單 B 更深或更廣的內容。"},{"en":"There is more to debating than winning trophies.","zh":"辯論不只是贏得獎盃。"},{"en":"This structure helps correct a narrow understanding of an activity.","zh":"這個結構幫助修正對某項活動的狹窄理解。"},{"en":"It is useful when explaining hidden benefits.","zh":"當解釋隱藏好處時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":3},{"front":"stand behind a lectern","meaning":"站在講台後","examples":[{"en":"Debating is not only about standing behind a lectern.","zh":"辯論不只是站在講台後。"},{"en":"To stand behind a lectern means to speak formally from a small speaking desk.","zh":"stand behind a lectern 的意思是站在小型演講桌後正式發言。"},{"en":"A student may stand behind a lectern during a competition speech.","zh":"學生可以在比賽演說時站在講台後。"},{"en":"The lectern can make speaking feel serious, but debate also requires teamwork and listening.","zh":"講台可以令發言感覺嚴肅，但辯論也需要團隊合作和聆聽。"},{"en":"This phrase describes the visible part of public speaking.","zh":"這個短語描述公開演說中可見的一部分。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"argue for","meaning":"支持……作出論證","examples":[{"en":"Debaters may argue for a motion in a competition.","zh":"辯手可能在比賽中支持一個辯題作出論證。"},{"en":"To argue for something means to give reasons supporting it.","zh":"argue for something 的意思是提出理由支持某事。"},{"en":"A team may argue for reducing homework by explaining its effect on sleep.","zh":"一隊人可以透過解釋功課對睡眠的影響，支持減少功課作出論證。"},{"en":"Good debaters argue for a point with evidence, not just strong feelings.","zh":"優秀辯手會用證據支持一個觀點，而不只是靠強烈感受。"},{"en":"This phrase describes supporting a position in debate.","zh":"這個短語描述在辯論中支持某個立場。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"practical training sessions","meaning":"實用訓練課節","examples":[{"en":"The club organises practical training sessions every week.","zh":"學會每星期舉辦實用訓練課節。"},{"en":"Practical training sessions are useful practice meetings where members learn skills by doing tasks.","zh":"practical training sessions 是會員透過完成任務學習技巧的有用練習聚會。"},{"en":"A practical training session may include speech practice, rebuttal drills, and feedback.","zh":"實用訓練課節可以包括演說練習、反駁操練和回饋。"},{"en":"These sessions help students improve because they practise real debating skills.","zh":"這些課節幫助學生進步，因為他們練習真正的辯論技巧。"},{"en":"This phrase shows that the club offers regular hands-on learning.","zh":"這個短語顯示學會提供定期實作學習。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"case-building","meaning":"建構論點","examples":[{"en":"Members learn case-building in the debating club.","zh":"會員在辯論學會學習建構論點。"},{"en":"Case-building is the process of creating a clear argument with claims, reasons, evidence, and examples.","zh":"case-building 是用主張、理由、證據和例子建立清晰論證的過程。"},{"en":"A team uses case-building to decide what its main points should be.","zh":"一隊人透過建構論點來決定主要觀點應該是甚麼。"},{"en":"Strong case-building helps debaters avoid scattered or weak speeches.","zh":"強而有力的論點建構幫助辯手避免演辭零散或薄弱。"},{"en":"This phrase describes the foundation of a debate.","zh":"這個短語描述辯論的基礎。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"rebuttal","meaning":"反駁","examples":[{"en":"Rebuttal is an important debating skill.","zh":"反駁是一項重要的辯論技巧。"},{"en":"Rebuttal means answering and weakening the other side’s argument.","zh":"rebuttal 的意思是回應並削弱對方的論點。"},{"en":"A debater gives a rebuttal when she explains why an opponent’s evidence is not enough.","zh":"當辯手解釋為何對手的證據不足夠時，就是作出反駁。"},{"en":"Good rebuttal attacks the idea, not the person.","zh":"好的反駁攻擊的是想法，而不是個人。"},{"en":"This word describes one of the most active parts of debating.","zh":"這個詞描述辯論中最活躍的部分之一。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"delivery","meaning":"演說表達","examples":[{"en":"The club trains members in delivery.","zh":"學會訓練會員的演說表達。"},{"en":"Delivery is the way a speaker presents a speech through voice, pace, tone, and body language.","zh":"delivery 是演講者透過聲音、速度、語氣和肢體語言呈現演辭的方式。"},{"en":"Clear delivery helps the audience follow complicated ideas.","zh":"清晰的演說表達幫助觀眾理解複雜想法。"},{"en":"A strong argument can sound weak if the delivery is unclear.","zh":"如果演說表達不清晰，強而有力的論點也可能聽起來薄弱。"},{"en":"This word describes how a message is spoken, not just what it says.","zh":"這個詞描述訊息如何被說出，而不只是訊息內容。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"current affairs","meaning":"時事","examples":[{"en":"The club discusses current affairs during training.","zh":"學會在訓練期間討論時事。"},{"en":"Current affairs are recent events and public issues happening in society.","zh":"current affairs 是社會中正在發生的近期事件和公共議題。"},{"en":"Students may discuss current affairs such as technology, education, health, or the environment.","zh":"學生可以討論科技、教育、健康或環境等時事。"},{"en":"Debating current affairs helps students connect school learning with real-world questions.","zh":"辯論時事幫助學生把校園學習與現實世界問題連繫起來。"},{"en":"This phrase describes topics that are timely and socially important.","zh":"這個短語描述具時代性和社會重要性的題目。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"examine whether","meaning":"探討是否","examples":[{"en":"One week, members may examine whether homework should be reduced.","zh":"某一星期，會員可能探討是否應減少功課。"},{"en":"Examine whether means look carefully at whether something is true, fair, or useful.","zh":"examine whether 的意思是仔細研究某事是否真實、公平或有用。"},{"en":"Debaters may examine whether school uniforms should be compulsory.","zh":"辯手可能探討校服是否應該是強制性的。"},{"en":"This phrase shows careful investigation instead of quick judgement.","zh":"這個短語表示仔細探究，而不是快速判斷。"},{"en":"It is useful when introducing a debate question.","zh":"當引入辯論問題時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"be reduced","meaning":"被減少","examples":[{"en":"Members may debate whether homework should be reduced.","zh":"會員可能辯論功課是否應被減少。"},{"en":"Be reduced means be made smaller in amount, size, or level.","zh":"be reduced 的意思是在數量、大小或程度上被降低。"},{"en":"Students may argue that homework should be reduced during examination periods.","zh":"學生可能主張考試期間功課應被減少。"},{"en":"Reducing homework may help sleep, but it may also affect revision if done carelessly.","zh":"減少功課可能有助睡眠，但如果做得不小心，也可能影響溫習。"},{"en":"This phrase is useful when discussing possible changes to workload.","zh":"當討論工作量可能改變時，這個短語很有用。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"artificial intelligence","meaning":"人工智能","examples":[{"en":"The club may debate artificial intelligence.","zh":"學會可能辯論人工智能。"},{"en":"Artificial intelligence is technology that allows machines to perform tasks that usually require human thinking.","zh":"artificial intelligence 是讓機器執行通常需要人類思考的任務的科技。"},{"en":"Students may debate whether artificial intelligence should be used in homework.","zh":"學生可能辯論人工智能是否應用於功課。"},{"en":"Artificial intelligence can help learning, but it also raises questions about honesty and skill.","zh":"人工智能可以幫助學習，但也帶來關於誠實和技能的問題。"},{"en":"This phrase describes a modern topic suitable for debate.","zh":"這個短語描述適合辯論的現代議題。"}],"source":"2012 Q5.pdf","sourcePage":4},{"front":"animal protection","meaning":"動物保護","examples":[{"en":"Members may discuss animal protection.","zh":"會員可能討論動物保護。"},{"en":"Animal protection means actions or laws that keep animals safe from harm, cruelty, or neglect.","zh":"animal protection 是保護動物免受傷害、殘酷對待或忽視的行動或法律。"},{"en":"Students may debate whether schools should teach more about animal protection.","zh":"學生可能辯論學校是否應更多教授動物保護。"},{"en":"Animal protection discussions can involve pets, wildlife, farming, and public responsibility.","zh":"動物保護討論可以涉及寵物、野生動物、農業和公共責任。"},{"en":"This phrase describes a moral and social issue.","zh":"這個短語描述一個道德和社會議題。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"school uniforms","meaning":"校服","examples":[{"en":"The club may debate school uniforms.","zh":"學會可能辯論校服。"},{"en":"School uniforms are standard clothes students are required to wear at school.","zh":"school uniforms 是學生在學校被要求穿着的標準服裝。"},{"en":"Debaters may argue whether school uniforms create equality or limit self-expression.","zh":"辯手可能討論校服是創造平等，還是限制自我表達。"},{"en":"School uniforms are a familiar topic because most students have direct experience with them.","zh":"校服是熟悉題目，因為大多數學生都有直接經驗。"},{"en":"This phrase describes a school issue that can lead to balanced arguments.","zh":"這個短語描述一個能引出平衡論點的校園議題。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"waste problem","meaning":"廢物問題","examples":[{"en":"Members may discuss Hong Kong’s waste problem.","zh":"會員可能討論香港的廢物問題。"},{"en":"A waste problem is a situation where too much rubbish is produced or not managed well.","zh":"waste problem 是產生太多垃圾或垃圾管理不善的情況。"},{"en":"Students may discuss the waste problem caused by disposable lunch boxes.","zh":"學生可能討論即棄飯盒造成的廢物問題。"},{"en":"Waste problems require both personal habits and public policy to change.","zh":"廢物問題需要個人習慣和公共政策同時改變。"},{"en":"This phrase describes an environmental issue that affects daily life.","zh":"這個短語描述影響日常生活的環境議題。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"brainstorming motions","meaning":"集思廣益想辯題","examples":[{"en":"Members improve through brainstorming motions.","zh":"會員透過集思廣益想辯題來進步。"},{"en":"Brainstorming motions means thinking of possible debate topics together quickly and creatively.","zh":"brainstorming motions 的意思是快速而有創意地一起想出可能的辯論題目。"},{"en":"Students may brainstorm motions about homework, technology, or school rules.","zh":"學生可以集思廣益想關於功課、科技或校規的辯題。"},{"en":"Brainstorming motions helps members see how many issues can become debates.","zh":"集思廣益想辯題幫助會員看見許多議題都可以變成辯論。"},{"en":"This phrase describes an active way to generate ideas.","zh":"這個短語描述產生想法的主動方式。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"polishing speeches","meaning":"打磨演辭","examples":[{"en":"Members practise polishing speeches before debates.","zh":"會員在辯論前練習打磨演辭。"},{"en":"Polishing speeches means improving speeches by making the language, structure, and delivery clearer.","zh":"polishing speeches 的意思是改善演辭，使語言、結構和表達更清晰。"},{"en":"A student polishes a speech by removing repeated ideas and adding stronger examples.","zh":"學生可以透過刪去重複想法和加入更有力例子來打磨演辭。"},{"en":"Polishing speeches helps arguments sound smoother and more convincing.","zh":"打磨演辭幫助論點聽起來更流暢和更有說服力。"},{"en":"This phrase shows that good speaking improves through revision.","zh":"這個短語顯示好的演說是透過修改進步的。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"mock debates","meaning":"模擬辯論","examples":[{"en":"The club uses mock debates to help members practise.","zh":"學會使用模擬辯論幫助會員練習。"},{"en":"Mock debates are practice debates that prepare students for real competitions.","zh":"mock debates 是為真實比賽作準備的練習辯論。"},{"en":"Members may hold a mock debate before facing another school.","zh":"會員可以在面對其他學校前舉行模擬辯論。"},{"en":"Mock debates help students test speeches, timing, and rebuttals in a safer setting.","zh":"模擬辯論幫助學生在較安全環境中測試演辭、時間控制和反駁。"},{"en":"This phrase describes realistic practice without the full pressure of a match.","zh":"這個短語描述接近真實但沒有完整比賽壓力的練習。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"post-match feedback","meaning":"賽後回饋","examples":[{"en":"Members receive post-match feedback after debates.","zh":"會員在辯論後收到賽後回饋。"},{"en":"Post-match feedback is advice or comments given after a competition or practice debate.","zh":"post-match feedback 是在比賽或模擬辯論後給予的建議或評論。"},{"en":"A coach may give post-match feedback on delivery, evidence, and teamwork.","zh":"教練可以就演說表達、證據和團隊合作給予賽後回饋。"},{"en":"Feedback after a match helps students understand what to improve next time.","zh":"賽後回饋幫助學生理解下次應改善甚麼。"},{"en":"This phrase shows learning after performance.","zh":"這個短語展示表現之後的學習。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"be designed to","meaning":"旨在","examples":[{"en":"Every activity is designed to help members improve.","zh":"每項活動都旨在幫助會員進步。"},{"en":"Be designed to means be created for a particular purpose.","zh":"be designed to 的意思是為某個特定目的而設計。"},{"en":"Mock debates are designed to prepare students for real competitions.","zh":"模擬辯論旨在為學生準備真實比賽。"},{"en":"Training sessions are designed to build confidence step by step.","zh":"訓練課節旨在一步一步建立信心。"},{"en":"This phrase explains the purpose behind an activity or system.","zh":"這個短語解釋活動或制度背後的目的。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"improve step by step","meaning":"一步一步進步","examples":[{"en":"The activities help members improve step by step.","zh":"這些活動幫助會員一步一步進步。"},{"en":"To improve step by step means to get better gradually through small stages.","zh":"improve step by step 的意思是透過小階段逐漸變得更好。"},{"en":"A nervous speaker can improve step by step by practising short speeches first.","zh":"緊張的演說者可以先練習短演辭，一步一步進步。"},{"en":"Step-by-step improvement feels less frightening than expecting instant success.","zh":"一步一步進步比期望立即成功較不令人害怕。"},{"en":"This phrase gives beginners hope and patience.","zh":"這個短語給初學者希望和耐性。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"impromptu challenge","meaning":"即興挑戰","examples":[{"en":"The club runs impromptu challenge afternoons.","zh":"學會舉辦即興挑戰下午。"},{"en":"An impromptu challenge is an activity where students must think and speak with little preparation.","zh":"impromptu challenge 是學生必須在很少準備下思考和發言的活動。"},{"en":"An impromptu challenge may ask members to prepare a speech in fifteen minutes.","zh":"即興挑戰可能要求會員在十五分鐘內準備演辭。"},{"en":"Such challenges train students to stay calm when ideas must be formed quickly.","zh":"這類挑戰訓練學生在需要快速形成想法時保持冷靜。"},{"en":"This phrase describes practice for quick thinking.","zh":"這個短語描述即場思考的練習。"}],"source":"2012 Q5.pdf","sourcePage":5},{"front":"be given a motion","meaning":"獲給予一個辯題","examples":[{"en":"Students are given a motion and fifteen minutes to prepare.","zh":"學生獲給予一個辯題和十五分鐘準備。"},{"en":"To be given a motion means to receive a debate topic or statement to argue about.","zh":"be given a motion 的意思是收到一個要辯論的題目或陳述。"},{"en":"In an impromptu challenge, students may be given a motion about school rules.","zh":"在即興挑戰中，學生可能獲給予一個關於校規的辯題。"},{"en":"Being given a motion tests how quickly students can understand and organise ideas.","zh":"獲給予辯題會測試學生能多快理解和組織想法。"},{"en":"This phrase describes the starting point of many debate activities.","zh":"這個短語描述許多辯論活動的起點。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"prepare","meaning":"準備","examples":[{"en":"Students have only fifteen minutes to prepare.","zh":"學生只有十五分鐘準備。"},{"en":"To prepare means to get ready before doing something.","zh":"prepare 的意思是在做某事前作好準備。"},{"en":"Debaters prepare by building arguments, choosing examples, and planning rebuttals.","zh":"辯手透過建構論點、選擇例子和計劃反駁來準備。"},{"en":"Careful preparation can reduce nervousness before a speech.","zh":"細心準備可以減少演講前的緊張。"},{"en":"This word describes the work done before performance.","zh":"這個詞描述表現前所做的工作。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"sounds terrifying","meaning":"聽起來很可怕","examples":[{"en":"The impromptu challenge sounds terrifying at first.","zh":"即興挑戰起初聽起來很可怕。"},{"en":"Sounds terrifying means seems extremely frightening when first heard.","zh":"sounds terrifying 的意思是初聽時似乎非常令人害怕。"},{"en":"Speaking with only fifteen minutes to prepare may sound terrifying to new members.","zh":"只有十五分鐘準備便要演說，對新會員來說可能聽起來很可怕。"},{"en":"Something that sounds terrifying can become enjoyable after practice and support.","zh":"聽起來很可怕的事，在練習和支持後可以變得有趣。"},{"en":"This phrase describes first fear before real experience.","zh":"這個短語描述真正經驗前的第一種恐懼。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"not quite","meaning":"並不完全是這樣","examples":[{"en":"The challenge sounds terrifying, but not quite.","zh":"這個挑戰聽起來很可怕，但並不完全是這樣。"},{"en":"Not quite means not completely or not exactly as it first seems.","zh":"not quite 的意思是不完全，或並非正如起初看來那樣。"},{"en":"The speech looks impossible, but not quite, once the team helps you plan it.","zh":"這篇演辭看似不可能完成，但當團隊幫你計劃後，並不完全是這樣。"},{"en":"This phrase softens or corrects an earlier idea.","zh":"這個短語會緩和或修正前面的想法。"},{"en":"It is useful when showing that fear is partly mistaken.","zh":"當顯示恐懼有部分是誤解時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, those sessions often become the funniest part of the term.","zh":"事實上，那些課節往往成為學期中最有趣的部分。"},{"en":"In fact introduces information that gives the real situation or strengthens a point.","zh":"in fact 用來介紹真實情況或加強某個觀點的資料。"},{"en":"Many students fear debating at first; in fact, they often enjoy the practice later.","zh":"許多學生起初害怕辯論；事實上，他們之後往往享受練習。"},{"en":"This phrase helps correct an assumption with surprising information.","zh":"這個短語幫助用令人驚訝的資料修正假設。"},{"en":"It is useful when moving from fear to reassurance.","zh":"當由恐懼轉向安慰時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"the funniest part of the term","meaning":"學期中最有趣的部分","examples":[{"en":"Impromptu challenges often become the funniest part of the term.","zh":"即興挑戰往往成為學期中最有趣的部分。"},{"en":"The funniest part of the term means the most enjoyable or amusing activity during the school term.","zh":"the funniest part of the term 是學期中最令人愉快或有趣的活動。"},{"en":"Students may laugh at strange examples and unexpected arguments during impromptu challenges.","zh":"學生可能在即興挑戰中因奇怪例子和意想不到的論點而大笑。"},{"en":"A difficult activity can become funny when members support one another.","zh":"當會員互相支持時，困難活動也可以變得有趣。"},{"en":"This phrase makes the club sound lively and welcoming.","zh":"這個短語令學會聽起來活潑而友善。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"think on their feet","meaning":"即場思考","examples":[{"en":"Members learn to think on their feet.","zh":"會員學會即場思考。"},{"en":"To think on their feet means to respond quickly and intelligently without much preparation.","zh":"think on their feet 的意思是在沒有太多準備下快速而聰明地回應。"},{"en":"Debaters think on their feet when they answer a challenge during a speech.","zh":"當辯手在演說中回答質疑時，就是即場思考。"},{"en":"This skill helps students in interviews, presentations, and unexpected questions.","zh":"這項技能幫助學生應付面試、匯報和突如其來的問題。"},{"en":"This phrase describes quick practical thinking under pressure.","zh":"這個短語描述壓力下快速而實用的思考。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"support one another","meaning":"互相支持","examples":[{"en":"Members learn to support one another.","zh":"會員學會互相支持。"},{"en":"To support one another means to help, encourage, and stand by each other.","zh":"support one another 的意思是彼此幫助、鼓勵和支持。"},{"en":"Club members support one another by sharing evidence and giving kind feedback.","zh":"學會會員透過分享證據和給予善意回饋來互相支持。"},{"en":"Support makes difficult training feel safer and more enjoyable.","zh":"支持令困難訓練感覺更安全和更愉快。"},{"en":"This phrase shows the teamwork behind debating.","zh":"這個短語展示辯論背後的團隊合作。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"laugh at mistakes","meaning":"對錯誤一笑置之","examples":[{"en":"Students learn to laugh at mistakes instead of fearing them.","zh":"學生學會對錯誤一笑置之，而不是害怕它們。"},{"en":"To laugh at mistakes means to accept errors lightly and learn from them without shame.","zh":"laugh at mistakes 的意思是輕鬆接受錯誤，並在沒有羞恥下從中學習。"},{"en":"A new debater may laugh at a forgotten line and try again.","zh":"新辯手可能對忘記一句演辭一笑置之，然後再試一次。"},{"en":"Laughing at mistakes can reduce fear and make practice more honest.","zh":"對錯誤一笑置之可以減少恐懼，令練習更真誠。"},{"en":"This phrase describes a healthy learning attitude.","zh":"這個短語描述健康的學習態度。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"instead of fearing them","meaning":"而不是害怕它們","examples":[{"en":"Members laugh at mistakes instead of fearing them.","zh":"會員對錯誤一笑置之，而不是害怕它們。"},{"en":"Instead of fearing them means choosing not to be controlled by fear of mistakes.","zh":"instead of fearing them 的意思是不選擇被對錯誤的恐懼控制。"},{"en":"Students improve faster when they discuss mistakes instead of fearing them.","zh":"當學生討論錯誤而不是害怕它們時，他們進步得更快。"},{"en":"This phrase contrasts a healthy response with an anxious one.","zh":"這個短語把健康回應與焦慮回應作對比。"},{"en":"It is useful when encouraging learners to treat errors as practice.","zh":"當鼓勵學習者把錯誤視為練習時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":6},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, the club joins inter-school competitions.","zh":"更好的是，學會參加聯校比賽。"},{"en":"Better still means even better or more importantly in addition to what was said before.","zh":"better still 的意思是在之前所說之外，更好或更重要的是。"},{"en":"The club offers training; better still, it gives students chances to compete.","zh":"學會提供訓練；更好的是，它給學生比賽機會。"},{"en":"Writers use this phrase to add a stronger advantage.","zh":"作者使用這個短語來加入更強的優點。"},{"en":"It helps make a speech more persuasive.","zh":"它幫助演講更有說服力。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"inter-school competitions","meaning":"聯校比賽","examples":[{"en":"The debating club joins inter-school competitions.","zh":"辯論學會參加聯校比賽。"},{"en":"Inter-school competitions are contests between students from different schools.","zh":"inter-school competitions 是不同學校學生之間的比賽。"},{"en":"Debaters meet stronger teams through inter-school competitions.","zh":"辯手透過聯校比賽遇到更強隊伍。"},{"en":"These competitions help members test their skills beyond their own classroom.","zh":"這些比賽幫助會員在自己課室以外測試技能。"},{"en":"This phrase describes formal opportunities for wider experience.","zh":"這個短語描述獲得更廣泛經驗的正式機會。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"friendly debates","meaning":"友誼辯論賽","examples":[{"en":"The club joins friendly debates with neighbouring schools.","zh":"學會與鄰近學校參加友誼辯論賽。"},{"en":"Friendly debates are practice or informal debates held in a cooperative spirit.","zh":"friendly debates 是以合作精神舉行的練習或非正式辯論。"},{"en":"A friendly debate lets students test arguments without the full pressure of a major competition.","zh":"友誼辯論賽讓學生在沒有大型比賽完整壓力下測試論點。"},{"en":"Friendly debates help schools learn from one another.","zh":"友誼辯論賽幫助學校互相學習。"},{"en":"This phrase describes competition that remains supportive and respectful.","zh":"這個短語描述仍然支持和尊重的競爭。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"neighbouring schools","meaning":"鄰近學校","examples":[{"en":"The club debates with neighbouring schools.","zh":"學會與鄰近學校辯論。"},{"en":"Neighbouring schools are schools located nearby or in the same area.","zh":"neighbouring schools 是位於附近或同一區域的學校。"},{"en":"Debating with neighbouring schools gives members a chance to meet students outside their own campus.","zh":"與鄰近學校辯論，給會員機會認識本校以外的學生。"},{"en":"Friendly contact with nearby schools can build confidence before larger competitions.","zh":"與附近學校友善交流，可以在大型比賽前建立信心。"},{"en":"This phrase shows connection beyond one school community.","zh":"這個短語展示超越一所學校社群的連繫。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"give members the chance to","meaning":"給會員機會去……","examples":[{"en":"Competitions give members the chance to meet different people.","zh":"比賽給會員機會去認識不同的人。"},{"en":"Give members the chance to means provide members with an opportunity to do something.","zh":"give members the chance to 的意思是給會員做某事的機會。"},{"en":"Debate training gives members the chance to practise speaking under pressure.","zh":"辯論訓練給會員機會在壓力下練習發言。"},{"en":"Competitions give members the chance to learn from different styles.","zh":"比賽給會員機會學習不同風格。"},{"en":"This phrase highlights the opportunities created by an activity.","zh":"這個短語突顯活動創造的機會。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"accents and styles","meaning":"口音和風格","examples":[{"en":"Members meet people with different ideas, accents and styles.","zh":"會員認識有不同想法、口音和風格的人。"},{"en":"Accents and styles refer to different ways of speaking, presenting, and expressing ideas.","zh":"accents and styles 是不同的說話、演說和表達想法方式。"},{"en":"In competitions, students may hear accents and styles different from those at their own school.","zh":"在比賽中，學生可能聽到與本校不同的口音和風格。"},{"en":"Meeting different speaking styles helps debaters become more adaptable listeners.","zh":"接觸不同演說風格幫助辯手成為更能適應的聆聽者。"},{"en":"This phrase shows variety in communication.","zh":"這個短語展示溝通中的多樣性。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"different from their own","meaning":"與自己的不同","examples":[{"en":"Members meet people whose styles are different from their own.","zh":"會員認識風格與自己的不同的人。"},{"en":"Different from their own means not the same as what they are used to or personally have.","zh":"different from their own 的意思是與他們習慣的或自己擁有的不同。"},{"en":"Students may learn from speakers whose pace is different from their own.","zh":"學生可以向語速與自己的不同的演說者學習。"},{"en":"Meeting people different from ourselves can widen our understanding.","zh":"認識與自己不同的人可以擴闊理解。"},{"en":"This phrase highlights learning through contrast.","zh":"這個短語突顯透過差異學習。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"the benefits of joining","meaning":"加入……的好處","examples":[{"en":"The benefits of joining the club go far beyond trophies.","zh":"加入學會的好處遠遠超出獎盃。"},{"en":"The benefits of joining means the good results or advantages of becoming a member.","zh":"benefits of joining 的意思是成為會員後得到的好結果或優點。"},{"en":"The benefits of joining may include confidence, friendship, sharper thinking, and better English.","zh":"加入的好處可以包括信心、友誼、更敏銳的思考和更好的英文。"},{"en":"This phrase helps explain why students should consider signing up.","zh":"這個短語幫助解釋為何學生應考慮報名。"},{"en":"It introduces reasons for joining beyond surface rewards.","zh":"它引入表面獎賞以外的加入理由。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"go far beyond","meaning":"遠遠超出","examples":[{"en":"The benefits of debating go far beyond trophies.","zh":"辯論的好處遠遠超出獎盃。"},{"en":"To go far beyond something means to be much greater, wider, or deeper than it.","zh":"go far beyond something 的意思是比某事大得多、廣得多或深得多。"},{"en":"The value of debating goes far beyond winning a competition.","zh":"辯論的價值遠遠超出贏得一場比賽。"},{"en":"A club’s impact goes far beyond meetings if students use the skills in daily life.","zh":"如果學生在日常生活使用技能，學會的影響就遠遠超出聚會本身。"},{"en":"This phrase emphasises that the real value is larger than expected.","zh":"這個短語強調真正價值比預期更大。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"trophies","meaning":"獎盃","examples":[{"en":"Debating brings benefits beyond trophies.","zh":"辯論帶來獎盃以外的好處。"},{"en":"Trophies are prizes, often cups or plaques, given to winners of competitions.","zh":"trophies 是頒給比賽勝出者的獎品，通常是杯或牌匾。"},{"en":"A team may win trophies, but the confidence gained through training can matter more.","zh":"一隊人可能贏得獎盃，但透過訓練得到的信心可能更重要。"},{"en":"Trophies are visible signs of success, but they are not the only reward.","zh":"獎盃是可見的成功標誌，但不是唯一獎賞。"},{"en":"This word helps contrast public achievement with personal growth.","zh":"這個詞幫助對比公開成就與個人成長。"}],"source":"2012 Q5.pdf","sourcePage":7},{"front":"strengthens English","meaning":"增強英文能力","examples":[{"en":"Debating strengthens English.","zh":"辯論增強英文能力。"},{"en":"Strengthens English means improves someone’s ability to use English clearly and effectively.","zh":"strengthens English 的意思是改善某人清晰而有效使用英文的能力。"},{"en":"Debate strengthens English because students must read, speak, listen, and respond in English.","zh":"辯論增強英文能力，因為學生必須用英文閱讀、發言、聆聽和回應。"},{"en":"Students strengthen English when they learn to choose precise words under pressure.","zh":"當學生學會在壓力下精準用字時，就是增強英文能力。"},{"en":"This phrase describes a language benefit of debating.","zh":"這個短語描述辯論在語言方面的好處。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"force someone to","meaning":"迫使某人去……","examples":[{"en":"Debating forces us to choose words precisely.","zh":"辯論迫使我們精準用字。"},{"en":"To force someone to do something means to make them do it because the situation requires it.","zh":"force someone to do something 的意思是因情況需要而令某人必須做某事。"},{"en":"Debate forces students to explain ideas clearly because vague answers are easily challenged.","zh":"辯論迫使學生清楚解釋想法，因為模糊答案很容易被質疑。"},{"en":"Pressure can force speakers to organise their thoughts more carefully.","zh":"壓力可以迫使演說者更仔細地組織想法。"},{"en":"This phrase shows how challenge can create improvement.","zh":"這個短語展示挑戰如何帶來進步。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"choose words precisely","meaning":"精準用字","examples":[{"en":"Debating trains us to choose words precisely.","zh":"辯論訓練我們精準用字。"},{"en":"To choose words precisely means to select exact words that express the intended meaning clearly.","zh":"choose words precisely 的意思是選擇準確文字，清楚表達原本想法。"},{"en":"A debater must choose words precisely when defining a motion.","zh":"辯手在定義辯題時必須精準用字。"},{"en":"Precise word choice prevents misunderstanding and strengthens arguments.","zh":"精準用字可以防止誤解並加強論點。"},{"en":"This phrase describes careful language control.","zh":"這個短語描述謹慎的語言控制。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"structure ideas logically","meaning":"有邏輯地組織想法","examples":[{"en":"Debating helps students structure ideas logically.","zh":"辯論幫助學生有邏輯地組織想法。"},{"en":"To structure ideas logically means to arrange thoughts in a clear order that makes sense.","zh":"structure ideas logically 的意思是以清楚合理的次序安排想法。"},{"en":"A debater structures ideas logically by moving from claim to reason to evidence.","zh":"辯手透過由主張到理由再到證據，有邏輯地組織想法。"},{"en":"Logical structure helps the audience follow the argument without confusion.","zh":"有邏輯的結構幫助觀眾不混亂地跟上論點。"},{"en":"This phrase describes organised thinking and writing.","zh":"這個短語描述有組織的思考和寫作。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"speak to a real audience","meaning":"對真正的觀眾說話","examples":[{"en":"Debaters learn to speak to a real audience.","zh":"辯手學會對真正的觀眾說話。"},{"en":"To speak to a real audience means to present ideas to actual listeners, not just practise alone.","zh":"speak to a real audience 的意思是向真實聽眾表達想法，而不只是獨自練習。"},{"en":"A student speaks to a real audience when she delivers a speech at assembly.","zh":"當學生在早會發表演講時，就是對真正的觀眾說話。"},{"en":"Real audiences teach speakers to notice reaction, pace, and clarity.","zh":"真正的觀眾教演說者留意反應、語速和清晰度。"},{"en":"This phrase shows the practical nature of public speaking.","zh":"這個短語展示公開演說的實用性。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"model essays","meaning":"範文","examples":[{"en":"Reading model essays is useful.","zh":"閱讀範文是有用的。"},{"en":"Model essays are sample essays that show good structure, language, and argument.","zh":"model essays 是展示良好結構、語言和論證的示範文章。"},{"en":"Students can learn useful phrases and organisation from model essays.","zh":"學生可以從範文中學習有用句式和組織方法。"},{"en":"Model essays help writing, but debating asks students to use ideas actively.","zh":"範文有助寫作，但辯論要求學生主動使用想法。"},{"en":"This phrase describes a learning resource often used in English study.","zh":"這個短語描述英文學習中常用的學習資源。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"defend your own argument","meaning":"捍衛自己的論點","examples":[{"en":"Debating requires you to defend your own argument under pressure.","zh":"辯論要求你在壓力下捍衛自己的論點。"},{"en":"To defend your own argument means to explain and protect your point against challenges.","zh":"defend your own argument 的意思是在面對質疑時解釋並保護自己的觀點。"},{"en":"A debater defends her argument by answering questions with evidence.","zh":"辯手透過用證據回答問題來捍衛自己的論點。"},{"en":"Defending an argument teaches students to understand their ideas more deeply.","zh":"捍衛論點教學生更深入理解自己的想法。"},{"en":"This phrase shows active responsibility for what you say.","zh":"這個短語展示對自己說話的主動責任。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"under pressure","meaning":"在壓力下","examples":[{"en":"Debaters must defend arguments under pressure.","zh":"辯手必須在壓力下捍衛論點。"},{"en":"Under pressure means while feeling stress, urgency, or challenge.","zh":"under pressure 的意思是在感到壓力、迫切或挑戰時。"},{"en":"Students speak under pressure when judges and opponents are listening carefully.","zh":"當評判和對手仔細聆聽時，學生就是在壓力下發言。"},{"en":"Practising under pressure helps speakers stay calm in real situations.","zh":"在壓力下練習幫助演說者在真實情況中保持冷靜。"},{"en":"This phrase describes difficulty that tests confidence.","zh":"這個短語描述考驗信心的困難。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"another matter altogether","meaning":"完全是另一回事","examples":[{"en":"Defending your own argument is another matter altogether.","zh":"捍衛自己的論點完全是另一回事。"},{"en":"Another matter altogether means a completely different and usually more difficult thing.","zh":"another matter altogether 的意思是完全不同，而且通常更困難的事。"},{"en":"Reading about debate is useful, but speaking in a competition is another matter altogether.","zh":"閱讀辯論知識有用，但在比賽中發言完全是另一回事。"},{"en":"This phrase highlights the difference between theory and real practice.","zh":"這個短語突顯理論與真實練習之間的差別。"},{"en":"It is useful when showing that one task is much harder than another.","zh":"當顯示一項任務比另一項難得多時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take a shy junior student, for example.","zh":"以一名害羞的低年級學生為例。"},{"en":"Take something for example introduces a specific case that supports a wider point.","zh":"take something for example 用來介紹支持較大觀點的具體例子。"},{"en":"Take a nervous Form One student, for example: debate can help her speak more clearly.","zh":"以一名緊張的中一學生為例：辯論可以幫助她說得更清楚。"},{"en":"This phrase helps listeners understand an idea through a concrete person or situation.","zh":"這個短語幫助聽眾透過具體人物或情況理解想法。"},{"en":"It is useful when moving from general claims to examples.","zh":"當由一般說法轉向例子時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":8},{"front":"shy junior student","meaning":"害羞的低年級學生","examples":[{"en":"A shy junior student can become more confident through debating.","zh":"害羞的低年級學生可以透過辯論變得更有信心。"},{"en":"A shy junior student is a younger student who feels nervous about speaking or joining in.","zh":"shy junior student 是在發言或參與方面感到緊張的低年級學生。"},{"en":"A shy junior student may first practise with a small group before speaking to the class.","zh":"害羞的低年級學生可以先在小組中練習，再向全班發言。"},{"en":"Debate can help shy students because it gives them structure and repeated practice.","zh":"辯論可以幫助害羞學生，因為它提供結構和反覆練習。"},{"en":"This phrase gives a concrete example of someone the club can help.","zh":"這個短語給出學會可以幫助的具體例子。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"whisper from a script","meaning":"照著稿子小聲讀","examples":[{"en":"At first, she may whisper from a script.","zh":"起初，她可能照着稿子小聲讀。"},{"en":"To whisper from a script means to read prepared words very quietly because of nervousness.","zh":"whisper from a script 的意思是因緊張而很小聲地讀準備好的文字。"},{"en":"A new speaker may whisper from a script during her first training session.","zh":"新演說者可能在第一次訓練課節中照着稿子小聲讀。"},{"en":"With practice, a student can move from whispering to speaking clearly.","zh":"透過練習，學生可以由小聲讀變成清楚發言。"},{"en":"This phrase shows the early stage of learning public speaking.","zh":"這個短語展示學習公開演說的早期階段。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"avoid eye contact","meaning":"避免眼神接觸","examples":[{"en":"She may avoid eye contact at first.","zh":"她起初可能避免眼神接觸。"},{"en":"To avoid eye contact means to avoid looking directly at people’s eyes.","zh":"avoid eye contact 的意思是避免直接看着別人的眼睛。"},{"en":"A nervous speaker may avoid eye contact by looking only at her notes.","zh":"緊張的演說者可能只看筆記來避免眼神接觸。"},{"en":"Practising eye contact can help a speaker connect with the audience.","zh":"練習眼神接觸可以幫助演說者與觀眾建立連繫。"},{"en":"This phrase describes a common sign of nervousness.","zh":"這個短語描述常見的緊張跡象。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"panic when challenged","meaning":"被質疑時慌張","examples":[{"en":"She may panic when challenged.","zh":"她被質疑時可能會慌張。"},{"en":"To panic when challenged means to become very frightened or confused when someone questions you.","zh":"panic when challenged 的意思是在有人質疑你時變得非常害怕或混亂。"},{"en":"A new debater may panic when challenged by a strong opponent.","zh":"新辯手面對強勁對手質疑時可能會慌張。"},{"en":"Training helps students stay calm when their ideas are questioned.","zh":"訓練幫助學生在想法被質疑時保持冷靜。"},{"en":"This phrase describes fear during confrontation or pressure.","zh":"這個短語描述面對衝突或壓力時的恐懼。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"little by little","meaning":"漸漸地","examples":[{"en":"Little by little, she becomes a more confident speaker.","zh":"漸漸地，她成為更有信心的演說者。"},{"en":"Little by little means gradually, through small changes over time.","zh":"little by little 的意思是隨時間透過小改變逐漸地。"},{"en":"Little by little, a nervous student learns to look up from her notes.","zh":"漸漸地，緊張的學生學會從筆記中抬頭。"},{"en":"This phrase shows patient progress rather than sudden success.","zh":"這個短語展示有耐性的進步，而不是突然成功。"},{"en":"It is useful when describing growth through repeated practice.","zh":"當描述透過反覆練習而成長時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"open with a hook","meaning":"以吸引人的開場開始","examples":[{"en":"She learns to open with a hook.","zh":"她學會以吸引人的開場開始。"},{"en":"To open with a hook means to begin a speech with something that catches the audience’s attention.","zh":"open with a hook 的意思是用吸引觀眾注意的內容開始演講。"},{"en":"A speaker may open with a hook by asking a surprising question.","zh":"演說者可以用一個令人驚訝的問題作吸引人的開場。"},{"en":"A strong hook makes listeners want to hear the rest of the speech.","zh":"有力的開場令聽眾想聽完整篇演辭。"},{"en":"This phrase describes an effective speaking technique.","zh":"這個短語描述有效的演說技巧。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"signpost her points","meaning":"清楚標示自己的論點","examples":[{"en":"She learns to signpost her points clearly.","zh":"她學會清楚標示自己的論點。"},{"en":"To signpost her points means to guide listeners by clearly marking each main idea.","zh":"signpost her points 的意思是透過清楚標記每個主要想法來引導聽眾。"},{"en":"A speaker signposts her points by saying, “First,” “Second,” and “Finally.”","zh":"演說者可以說「首先」、「第二」和「最後」來標示自己的論點。"},{"en":"Clear signposting helps the audience follow the structure of a speech.","zh":"清楚標示論點幫助觀眾跟上演辭結構。"},{"en":"This phrase describes organising ideas for listeners.","zh":"這個短語描述為聽眾組織想法。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"respond to objections","meaning":"回應反對意見","examples":[{"en":"She learns to respond to objections.","zh":"她學會回應反對意見。"},{"en":"To respond to objections means to answer doubts, criticisms, or opposing points.","zh":"respond to objections 的意思是回答疑問、批評或相反觀點。"},{"en":"A debater responds to objections by explaining why her evidence still supports her case.","zh":"辯手透過解釋為何自己的證據仍支持己方論點來回應反對意見。"},{"en":"Responding to objections makes an argument stronger and more balanced.","zh":"回應反對意見令論點更強而更平衡。"},{"en":"This phrase describes a key skill in debate and discussion.","zh":"這個短語描述辯論和討論中的關鍵技巧。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"end with impact","meaning":"以有力方式結尾","examples":[{"en":"She learns to end with impact.","zh":"她學會以有力方式結尾。"},{"en":"To end with impact means to finish a speech in a strong and memorable way.","zh":"end with impact 的意思是以強而令人難忘的方式結束演講。"},{"en":"A speaker may end with impact by returning to the opening question.","zh":"演說者可以透過回到開場問題來有力地結尾。"},{"en":"A powerful ending helps the audience remember the main message.","zh":"有力的結尾幫助觀眾記住主要訊息。"},{"en":"This phrase describes how to close a speech effectively.","zh":"這個短語描述如何有效結束演講。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"become a champion","meaning":"成為冠軍","examples":[{"en":"She may not become a champion yet.","zh":"她也許尚未成為冠軍。"},{"en":"To become a champion means to win a competition or become the best in a field.","zh":"become a champion 的意思是贏得比賽或成為某領域中最好的人。"},{"en":"A new debater may not become a champion in her first year, but she can still improve greatly.","zh":"新辯手第一年可能未能成為冠軍，但仍可以大大進步。"},{"en":"Becoming a champion is not the only sign of success.","zh":"成為冠軍不是成功的唯一標誌。"},{"en":"This phrase helps separate winning from personal growth.","zh":"這個短語幫助把勝利與個人成長分開。"}],"source":"2012 Q5.pdf","sourcePage":9},{"front":"a more confident speaker","meaning":"更有信心的演說者","examples":[{"en":"She will already be a more confident speaker.","zh":"她已經會成為更有信心的演說者。"},{"en":"A more confident speaker is someone who speaks with greater calmness and belief in their own voice.","zh":"more confident speaker 是說話時更冷靜並更相信自己聲音的人。"},{"en":"A student becomes a more confident speaker after practising introductions and rebuttals.","zh":"學生練習開場和反駁後，可以成為更有信心的演說者。"},{"en":"Confidence grows when speakers see that mistakes do not destroy them.","zh":"當演說者看見錯誤不會摧毀自己，信心就會成長。"},{"en":"This phrase describes progress even before winning any prize.","zh":"這個短語描述在贏得任何獎項前已出現的進步。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, debating makes us better teammates.","zh":"更重要的是，辯論令我們成為更好的隊友。"},{"en":"More importantly means what follows is even more significant than the previous point.","zh":"more importantly 的意思是接下來的內容比前一點更重要。"},{"en":"Debating improves English; more importantly, it teaches students to listen fairly.","zh":"辯論改善英文；更重要的是，它教學生公平地聆聽。"},{"en":"Speakers use this phrase to guide the audience toward a deeper value.","zh":"演講者使用這個短語，引導觀眾走向更深層價值。"},{"en":"It helps move from practical benefits to character development.","zh":"它幫助由實用好處轉向品格發展。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"better teammates","meaning":"更好的隊友","examples":[{"en":"Debating makes students better teammates.","zh":"辯論令學生成為更好的隊友。"},{"en":"Better teammates are people who cooperate, listen, support, and challenge others respectfully.","zh":"better teammates 是會合作、聆聽、支持並尊重地挑戰別人的人。"},{"en":"A better teammate helps revise a speech instead of laughing at mistakes.","zh":"更好的隊友會幫忙修改演辭，而不是嘲笑錯誤。"},{"en":"Debating builds better teammates because success depends on shared preparation.","zh":"辯論培養更好的隊友，因為成功取決於共同準備。"},{"en":"This phrase shows the social benefit of joining the club.","zh":"這個短語展示加入學會的社交好處。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"strong teams","meaning":"強大的團隊","examples":[{"en":"Strong teams challenge each other respectfully.","zh":"強大的團隊會尊重地互相挑戰。"},{"en":"Strong teams are groups whose members trust, support, and improve one another.","zh":"strong teams 是成員之間互相信任、支持並促進彼此進步的團隊。"},{"en":"A strong debating team gives honest feedback without humiliating anyone.","zh":"強大的辯論隊會給予誠實回饋，而不羞辱任何人。"},{"en":"Strong teams are not made of identical people, but of people who work well together.","zh":"強大的團隊不是由完全一樣的人組成，而是由能良好合作的人組成。"},{"en":"This phrase describes effective cooperation.","zh":"這個短語描述有效合作。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"challenge each other","meaning":"互相挑戰","examples":[{"en":"Members of strong teams challenge each other.","zh":"強大團隊的成員會互相挑戰。"},{"en":"To challenge each other means to question, test, and push one another to improve.","zh":"challenge each other 的意思是彼此質疑、測試並推動進步。"},{"en":"Debaters challenge each other by asking whether the evidence is strong enough.","zh":"辯手透過詢問證據是否足夠有力來互相挑戰。"},{"en":"Healthy challenge helps teammates improve without damaging friendship.","zh":"健康的挑戰幫助隊友進步，而不傷害友誼。"},{"en":"This phrase shows that support can include honest criticism.","zh":"這個短語顯示支持也可以包括誠實批評。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"without humiliating one another","meaning":"不羞辱彼此","examples":[{"en":"Good teammates challenge each other without humiliating one another.","zh":"好隊友會互相挑戰，而不羞辱彼此。"},{"en":"Without humiliating one another means without making each other feel ashamed or small.","zh":"without humiliating one another 的意思是不令彼此感到羞愧或渺小。"},{"en":"A teammate can question a weak point without humiliating the speaker.","zh":"隊友可以質疑薄弱觀點，而不羞辱演說者。"},{"en":"Debate improves when criticism is firm but respectful.","zh":"當批評堅定但尊重時，辯論會進步。"},{"en":"This phrase shows the difference between challenge and cruelty.","zh":"這個短語展示挑戰與殘酷之間的差別。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"disagreement is not disrespect","meaning":"不同意並不等於不尊重","examples":[{"en":"Debating teaches us that disagreement is not disrespect.","zh":"辯論教會我們，不同意並不等於不尊重。"},{"en":"Disagreement is not disrespect means having a different opinion does not automatically mean being rude.","zh":"disagreement is not disrespect 的意思是持有不同意見不自動代表無禮。"},{"en":"A student can disagree with a teacher’s idea while still speaking politely.","zh":"學生可以不同意老師的想法，同時仍禮貌地說話。"},{"en":"Understanding this helps debates remain serious and fair.","zh":"明白這一點有助辯論保持嚴肅和公平。"},{"en":"This phrase teaches a healthy attitude toward conflict.","zh":"這個短語教導人們健康看待衝突。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"a stronger argument","meaning":"更有力的論點","examples":[{"en":"A stronger argument often begins with better listening.","zh":"更有力的論點往往由更好的聆聽開始。"},{"en":"A stronger argument is a point supported by clearer reasons, better evidence, and fairer thinking.","zh":"stronger argument 是由更清晰理由、更好證據和更公平思考支持的觀點。"},{"en":"A debater builds a stronger argument by understanding the other side first.","zh":"辯手先理解對方，才能建立更有力的論點。"},{"en":"Stronger arguments are not always louder; they are usually better organised.","zh":"更有力的論點不一定更大聲；它們通常更有組織。"},{"en":"This phrase describes improvement in reasoning.","zh":"這個短語描述推理方面的進步。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"better listening","meaning":"更好的聆聽","examples":[{"en":"A stronger argument often begins with better listening.","zh":"更有力的論點往往由更好的聆聽開始。"},{"en":"Better listening means paying closer attention to what others actually mean.","zh":"better listening 的意思是更專注地理解別人真正的意思。"},{"en":"A debater practises better listening by noting the opponent’s reasons before replying.","zh":"辯手透過在回應前記下對手的理由來練習更好的聆聽。"},{"en":"Better listening prevents speakers from attacking points nobody made.","zh":"更好的聆聽防止演說者攻擊別人根本沒有提出的觀點。"},{"en":"This phrase shows that good speaking depends on understanding.","zh":"這個短語顯示好的演說取決於理解。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"being a good debater","meaning":"成為一名優秀辯手","examples":[{"en":"Being a good debater is important in life.","zh":"成為一名優秀辯手在生活中很重要。"},{"en":"Being a good debater means being able to think clearly, speak fairly, and listen carefully.","zh":"being a good debater 的意思是能清晰思考、公平說話和仔細聆聽。"},{"en":"A good debater can disagree without turning the discussion into a personal attack.","zh":"優秀辯手可以不同意別人，而不把討論變成人身攻擊。"},{"en":"These skills matter in school, work, friendships, and society.","zh":"這些技能在學校、工作、友誼和社會中都重要。"},{"en":"This phrase describes a role that goes beyond competitions.","zh":"這個短語描述一個超越比賽的角色。"}],"source":"2012 Q5.pdf","sourcePage":10},{"front":"life itself","meaning":"生活本身","examples":[{"en":"Life itself is full of arguments.","zh":"生活本身充滿爭論。"},{"en":"Life itself means ordinary real life, not only school or competitions.","zh":"life itself 的意思是普通真實生活，而不只是學校或比賽。"},{"en":"Life itself asks people to explain choices, solve conflicts, and judge information.","zh":"生活本身要求人們解釋選擇、解決衝突和判斷資訊。"},{"en":"Debate skills matter because they are useful outside the debate room.","zh":"辯論技巧重要，因為它們在辯論室以外也有用。"},{"en":"This phrase connects club training with wider human experience.","zh":"這個短語把學會訓練與更廣泛的人生經驗連繫起來。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"full of arguments","meaning":"充滿爭論","examples":[{"en":"Life itself is full of arguments.","zh":"生活本身充滿爭論。"},{"en":"Full of arguments means containing many disagreements, claims, or competing ideas.","zh":"full of arguments 的意思是包含許多分歧、主張或互相競爭的想法。"},{"en":"Social media is full of arguments about news, school rules, and public issues.","zh":"社交媒體充滿關於新聞、校規和公共議題的爭論。"},{"en":"A world full of arguments needs people who can think and listen carefully.","zh":"一個充滿爭論的世界需要能細心思考和聆聽的人。"},{"en":"This phrase shows why debating skills are practical.","zh":"這個短語顯示辯論技巧為何實用。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"advertisements","meaning":"廣告","examples":[{"en":"Advertisements tell us what to buy.","zh":"廣告告訴我們該買甚麼。"},{"en":"Advertisements are messages designed to persuade people to buy, support, or notice something.","zh":"advertisements 是旨在說服人們購買、支持或注意某事的訊息。"},{"en":"An advertisement may use emotion, music, or attractive images to influence customers.","zh":"廣告可以使用情緒、音樂或吸引人的圖片來影響顧客。"},{"en":"Students with debating skills can question whether an advertisement’s claim is fair.","zh":"有辯論技巧的學生可以質疑廣告說法是否公平。"},{"en":"This word connects persuasion in media with critical thinking.","zh":"這個詞把媒體中的說服與批判思考連繫起來。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"what to believe","meaning":"該相信甚麼","examples":[{"en":"Social media tells us what to believe.","zh":"社交媒體告訴我們該相信甚麼。"},{"en":"What to believe means which ideas, claims, or opinions we should accept as true.","zh":"what to believe 的意思是我們應把哪些想法、說法或意見視為真實。"},{"en":"Students should not let social media alone decide what to believe.","zh":"學生不應只讓社交媒體決定自己該相信甚麼。"},{"en":"Debating helps people examine evidence before choosing what to believe.","zh":"辯論幫助人們在決定該相信甚麼前檢視證據。"},{"en":"This phrase describes a key challenge in the information age.","zh":"這個短語描述資訊時代中的關鍵挑戰。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"future employers","meaning":"未來僱主","examples":[{"en":"Future employers will ask us to explain our thinking.","zh":"未來僱主會要求我們解釋自己的想法。"},{"en":"Future employers are people or organisations that may hire us later.","zh":"future employers 是將來可能聘請我們的人或機構。"},{"en":"Future employers may ask graduates why they made a decision or how they solved a problem.","zh":"未來僱主可能問畢業生為何作出某個決定，或如何解決問題。"},{"en":"Debate training helps students answer future employers clearly and calmly.","zh":"辯論訓練幫助學生清楚而冷靜地回答未來僱主。"},{"en":"This phrase connects school skills with workplace expectations.","zh":"這個短語把校園技能與工作場所期望連繫起來。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"in different ways","meaning":"以不同方式","examples":[{"en":"People will ask us in different ways to explain our views.","zh":"人們會以不同方式要求我們解釋自己的看法。"},{"en":"In different ways means through various methods, situations, or forms.","zh":"in different ways 的意思是透過不同方法、情況或形式。"},{"en":"Teachers, friends, employers, and voters may challenge our ideas in different ways.","zh":"老師、朋友、僱主和選民都可能以不同方式挑戰我們的想法。"},{"en":"Debate helps students respond when questions appear in different forms.","zh":"辯論幫助學生在問題以不同形式出現時作出回應。"},{"en":"This phrase shows variety in real-life communication.","zh":"這個短語展示現實溝通中的多樣性。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"explain what we think and why","meaning":"解釋我們的想法及原因","examples":[{"en":"We need to explain what we think and why.","zh":"我們需要解釋自己的想法及原因。"},{"en":"To explain what we think and why means to state our opinion and give the reasons behind it.","zh":"explain what we think and why 的意思是說明自己的意見，並給出背後理由。"},{"en":"A student explains what she thinks and why when she supports a school policy with evidence.","zh":"當學生用證據支持一項校園政策時，就是解釋自己的想法及原因。"},{"en":"This skill prevents opinions from sounding empty or careless.","zh":"這項技能防止意見聽起來空洞或草率。"},{"en":"This phrase describes the heart of clear argument.","zh":"這個短語描述清晰論證的核心。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"separate evidence from emotion","meaning":"分辨證據與情緒","examples":[{"en":"Students must learn to separate evidence from emotion.","zh":"學生必須學會分辨證據與情緒。"},{"en":"To separate evidence from emotion means to tell the difference between facts and feelings.","zh":"separate evidence from emotion 的意思是分清事實和感受之間的差別。"},{"en":"A debater separates evidence from emotion when she checks data before using an angry example.","zh":"當辯手在使用憤怒例子前先核實數據，就是分辨證據與情緒。"},{"en":"Feelings may matter, but evidence is needed to support public claims.","zh":"感受可以重要，但公共主張需要證據支持。"},{"en":"This phrase describes an important critical-thinking skill.","zh":"這個短語描述重要的批判思考技能。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"confidence from accuracy","meaning":"分辨自信與準確性","examples":[{"en":"We must separate confidence from accuracy.","zh":"我們必須分辨自信與準確性。"},{"en":"To separate confidence from accuracy means to understand that a confident statement is not always correct.","zh":"separate confidence from accuracy 的意思是明白有信心的說法不一定正確。"},{"en":"A speaker may sound confident but still use wrong information.","zh":"演說者可能聽起來有信心，但仍使用錯誤資料。"},{"en":"Debate teaches students to check whether a confident claim is also accurate.","zh":"辯論教學生檢查有信心的主張是否同時準確。"},{"en":"This phrase warns against trusting style more than truth.","zh":"這個短語提醒人們不要信任風格多於真相。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"persuasion from manipulation","meaning":"分辨說服與操控","examples":[{"en":"We must separate persuasion from manipulation.","zh":"我們必須分辨說服與操控。"},{"en":"To separate persuasion from manipulation means to tell honest influence apart from unfair control.","zh":"separate persuasion from manipulation 的意思是分清誠實影響與不公平控制。"},{"en":"Persuasion uses reasons, while manipulation may use fear, lies, or hidden pressure.","zh":"說服使用理由，而操控可能使用恐懼、謊言或隱藏壓力。"},{"en":"Debaters learn to persuade without misleading the audience.","zh":"辯手學會說服而不誤導觀眾。"},{"en":"This phrase describes ethical judgement in communication.","zh":"這個短語描述溝通中的道德判斷。"}],"source":"2012 Q5.pdf","sourcePage":11},{"front":"run the risk of","meaning":"冒着……的風險","examples":[{"en":"Without critical thinking, we run the risk of being misled.","zh":"沒有批判思考，我們會冒着被誤導的風險。"},{"en":"To run the risk of something means to face the possibility of something bad happening.","zh":"run the risk of something 的意思是面對某件壞事可能發生的風險。"},{"en":"Students run the risk of believing rumours if they never check sources.","zh":"如果學生從不核實來源，就會冒着相信謠言的風險。"},{"en":"People who follow only loud voices run the risk of making poor decisions.","zh":"只跟隨大聲音的人，會冒着作出差劣決定的風險。"},{"en":"This phrase warns about a possible danger.","zh":"這個短語提醒可能存在的危險。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"be led by","meaning":"被……帶着走","examples":[{"en":"We may be led by the loudest voice in the room.","zh":"我們可能被房間裏最大聲的聲音帶着走。"},{"en":"To be led by someone or something means to be guided or influenced by it.","zh":"be led by someone or something 的意思是被某人或某事引導或影響。"},{"en":"A group may be led by the most confident speaker even when the speaker is wrong.","zh":"一個小組可能被最有信心的演說者帶着走，即使那人是錯的。"},{"en":"Critical thinking helps students avoid being led by noise instead of evidence.","zh":"批判思考幫助學生避免被噪音而不是證據帶着走。"},{"en":"This phrase shows how influence can shape decisions.","zh":"這個短語展示影響如何塑造決定。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"the loudest voice in the room","meaning":"房間裏最大聲的聲音","examples":[{"en":"Students should not simply follow the loudest voice in the room.","zh":"學生不應只跟隨房間裏最大聲的聲音。"},{"en":"The loudest voice in the room means the most forceful or attention-grabbing person, not necessarily the wisest.","zh":"the loudest voice in the room 是最強勢或最吸引注意的人，但不一定是最有智慧的人。"},{"en":"In a group project, the loudest voice in the room may dominate the plan.","zh":"在小組項目中，房間裏最大聲的聲音可能主導計劃。"},{"en":"Debate teaches students to ask whether the loudest voice also has the strongest evidence.","zh":"辯論教學生詢問最大聲的聲音是否也有最強證據。"},{"en":"This phrase warns against confusing volume with truth.","zh":"這個短語提醒人們不要把音量與真相混淆。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"does not simply ask","meaning":"不只是問","examples":[{"en":"A good debater does not simply ask how to win.","zh":"優秀辯手不只是問如何勝出。"},{"en":"Does not simply ask means does not only focus on one narrow question.","zh":"does not simply ask 的意思是不只聚焦一個狹窄問題。"},{"en":"A good student does not simply ask how to get marks, but how to understand the issue.","zh":"好學生不只是問如何取得分數，而是問如何理解議題。"},{"en":"This phrase helps move attention from shallow success to deeper purpose.","zh":"這個短語幫助把注意力由表面成功轉向更深目標。"},{"en":"It is useful when contrasting two levels of thinking.","zh":"當對比兩個思考層次時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"rather","meaning":"反而；更準確地說","examples":[{"en":"Rather, a good debater asks what is true and fair.","zh":"反而，優秀辯手會問甚麼是真實和公平。"},{"en":"Rather means instead or more accurately.","zh":"rather 的意思是相反地，或更準確地說。"},{"en":"A good debate is not about shouting; rather, it is about testing ideas.","zh":"好辯論不是關於叫喊；更準確地說，它是關於檢驗想法。"},{"en":"This word helps correct one idea and replace it with a better one.","zh":"這個詞幫助修正一個想法，並以更好的想法取代它。"},{"en":"It is useful when making an argument more precise.","zh":"當令論點更精準時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"what have I failed to consider?","meaning":"我忽略了甚麼？","examples":[{"en":"A good debater asks, “What have I failed to consider?”","zh":"優秀辯手會問：「我忽略了甚麼？」"},{"en":"What have I failed to consider? means what important point, evidence, or view have I missed.","zh":"what have I failed to consider? 的意思是我錯過了甚麼重要觀點、證據或看法。"},{"en":"A student may ask this question before finalising an argument on school uniforms.","zh":"學生在完成關於校服的論點前，可以問這個問題。"},{"en":"This question helps debaters avoid being narrow-minded.","zh":"這個問題幫助辯手避免思想狹窄。"},{"en":"It shows humility and careful thinking.","zh":"它展示謙卑和細心思考。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"only by asking","meaning":"只有透過提出","examples":[{"en":"Only by asking these questions can we become better citizens.","zh":"只有透過提出這些問題，我們才能成為更好的公民。"},{"en":"Only by asking means success is possible only if we raise certain questions.","zh":"only by asking 的意思是只有提出某些問題，成功才可能發生。"},{"en":"Only by asking for evidence can students avoid being misled.","zh":"學生只有透過要求證據，才能避免被誤導。"},{"en":"This structure emphasises that questioning is necessary for growth.","zh":"這個結構強調提問對成長是必要的。"},{"en":"It is useful when showing that a habit is essential.","zh":"當展示某種習慣不可或缺時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"speak with courage","meaning":"勇敢地發言","examples":[{"en":"Good citizens speak with courage.","zh":"好公民會勇敢地發言。"},{"en":"To speak with courage means to express the truth or your view even when it feels difficult.","zh":"speak with courage 的意思是即使困難，也表達真相或自己的看法。"},{"en":"A student speaks with courage when she defends a classmate being treated unfairly.","zh":"當學生為受到不公平對待的同學辯護時，就是勇敢地發言。"},{"en":"Courageous speech should still be respectful and responsible.","zh":"勇敢的發言仍應尊重和負責任。"},{"en":"This phrase describes brave public communication.","zh":"這個短語描述勇敢的公共溝通。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"listen with humility","meaning":"謙卑地聆聽","examples":[{"en":"Good citizens listen with humility.","zh":"好公民會謙卑地聆聽。"},{"en":"To listen with humility means to hear others while admitting that you may not know everything.","zh":"listen with humility 的意思是在聆聽別人時承認自己未必知道一切。"},{"en":"A debater listens with humility when she allows opposing evidence to change her view.","zh":"當辯手容許相反證據改變自己的看法時，就是謙卑地聆聽。"},{"en":"Humble listening makes disagreement less aggressive and more useful.","zh":"謙卑聆聽令分歧較不具攻擊性，也更有用。"},{"en":"This phrase describes openness to learning from others.","zh":"這個短語描述向別人學習的開放態度。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"the pen may be mightier than the sword","meaning":"筆比劍更有力量","examples":[{"en":"The pen may be mightier than the sword, but a well-reasoned voice can be just as powerful.","zh":"筆也許比劍更有力量，但有充分理據的聲音也可以同樣有力。"},{"en":"The pen may be mightier than the sword means words and ideas can be more powerful than violence.","zh":"the pen may be mightier than the sword 的意思是文字和思想可以比暴力更有力量。"},{"en":"A thoughtful article can change opinions more deeply than force.","zh":"一篇有思想的文章可以比武力更深刻地改變意見。"},{"en":"In debate, reasoned speech can influence people without harming them.","zh":"在辯論中，有理據的演說可以在不傷害人的情況下影響別人。"},{"en":"This proverb praises the power of language and thought.","zh":"這句諺語讚揚語言和思想的力量。"}],"source":"2012 Q5.pdf","sourcePage":12},{"front":"a well-reasoned voice","meaning":"有充分理據的聲音","examples":[{"en":"A well-reasoned voice can be very powerful.","zh":"有充分理據的聲音可以非常有力量。"},{"en":"A well-reasoned voice is speech supported by clear logic, evidence, and fairness.","zh":"well-reasoned voice 是由清晰邏輯、證據和公平支持的發言。"},{"en":"A student with a well-reasoned voice can challenge unfair rules respectfully.","zh":"有充分理據的學生聲音可以尊重地挑戰不公平規則。"},{"en":"Such a voice is powerful because people can trust how the argument is built.","zh":"這種聲音有力量，因為人們可以信任論點如何建立。"},{"en":"This phrase describes speech that persuades through reason.","zh":"這個短語描述透過理性說服的發言。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"just as powerful","meaning":"同樣有力量","examples":[{"en":"A well-reasoned voice can be just as powerful.","zh":"有充分理據的聲音可以同樣有力量。"},{"en":"Just as powerful means equally strong or influential.","zh":"just as powerful 的意思是同樣強大或有影響力。"},{"en":"A calm argument can be just as powerful as an emotional speech if the evidence is strong.","zh":"如果證據有力，冷靜論點可以和情緒化演說同樣有力量。"},{"en":"Quiet students can be just as powerful as loud speakers when their reasoning is clear.","zh":"當推理清晰時，安靜學生可以和大聲演說者同樣有力量。"},{"en":"This phrase shows equality in strength or effect.","zh":"這個短語展示力量或效果上的相等。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"whether you dream of becoming","meaning":"無論你夢想成為","examples":[{"en":"Whether you dream of becoming a lawyer or journalist, debating can help you.","zh":"無論你夢想成為律師還是記者，辯論都可以幫助你。"},{"en":"Whether you dream of becoming means no matter what future role you hope to have.","zh":"whether you dream of becoming 的意思是不論你希望將來成為甚麼角色。"},{"en":"Whether you dream of becoming a teacher, entrepreneur, or doctor, clear speaking will help.","zh":"無論你夢想成為老師、企業家還是醫生，清晰表達都會有幫助。"},{"en":"This phrase makes the message apply to students with different ambitions.","zh":"這個短語令訊息適用於有不同志向的學生。"},{"en":"It is useful when encouraging a wide audience.","zh":"當鼓勵廣泛聽眾時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"lawyer","meaning":"律師","examples":[{"en":"A future lawyer can benefit from debating.","zh":"未來律師可以從辯論中受益。"},{"en":"A lawyer is a person trained to understand law, advise clients, and argue legal cases.","zh":"lawyer 是受過法律訓練、能給客戶建議並處理法律案件的人。"},{"en":"A student who wants to become a lawyer can practise reasoning through debate.","zh":"想成為律師的學生可以透過辯論練習推理。"},{"en":"Lawyers need clear speaking because they must explain complex ideas fairly.","zh":"律師需要清晰說話，因為他們必須公平地解釋複雜想法。"},{"en":"This word connects debating with a possible career path.","zh":"這個詞把辯論與可能的職業道路連繫起來。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"journalist","meaning":"記者","examples":[{"en":"A future journalist can benefit from debating.","zh":"未來記者可以從辯論中受益。"},{"en":"A journalist is a person who researches, writes, or reports news and public stories.","zh":"journalist 是研究、撰寫或報道新聞和公共故事的人。"},{"en":"A student who wants to be a journalist needs to ask sharp questions and check evidence.","zh":"想成為記者的學生需要提出敏銳問題並核實證據。"},{"en":"Debate helps future journalists separate strong claims from weak support.","zh":"辯論幫助未來記者分辨有力主張與薄弱支持。"},{"en":"This word connects communication skills with public information.","zh":"這個詞把溝通技巧與公共資訊連繫起來。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"entrepreneur","meaning":"企業家","examples":[{"en":"A future entrepreneur can benefit from debating.","zh":"未來企業家可以從辯論中受益。"},{"en":"An entrepreneur is a person who starts or develops a business, often by taking risks.","zh":"entrepreneur 是創立或發展企業的人，通常需要承擔風險。"},{"en":"An entrepreneur must explain ideas clearly to customers, partners, and investors.","zh":"企業家必須向顧客、伙伴和投資者清楚解釋想法。"},{"en":"Debate helps entrepreneurs persuade others without losing logic or honesty.","zh":"辯論幫助企業家說服別人，同時不失去邏輯或誠信。"},{"en":"This word connects debating skills with innovation and business.","zh":"這個詞把辯論技巧與創新和商業連繫起來。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"when it matters","meaning":"在關鍵時刻","examples":[{"en":"Debating helps students stand tall when it matters.","zh":"辯論幫助學生在關鍵時刻堂堂正正地站穩。"},{"en":"When it matters means at an important or serious moment.","zh":"when it matters 的意思是在重要或嚴肅的時刻。"},{"en":"Students need courage when it matters, such as during interviews or public discussions.","zh":"學生在關鍵時刻需要勇氣，例如面試或公共討論時。"},{"en":"Debate training prepares students to speak clearly when the situation is important.","zh":"辯論訓練幫助學生在情況重要時清楚發言。"},{"en":"This phrase highlights meaningful moments, not everyday comfort.","zh":"這個短語突顯有意義的時刻，而不是日常舒適。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"have something to offer","meaning":"能給予……一些有價值的東西","examples":[{"en":"The debating club has something to offer every student.","zh":"辯論學會能給予每位學生一些有價值的東西。"},{"en":"To have something to offer means to provide something useful or valuable.","zh":"have something to offer 的意思是提供有用或有價值的東西。"},{"en":"The club has something to offer shy students, outspoken students, and curious beginners.","zh":"學會能給予害羞學生、直言不諱的學生和好奇初學者一些有價值的東西。"},{"en":"A club offers value when it helps members grow in different ways.","zh":"當學會幫助會員以不同方式成長時，它就是提供價值。"},{"en":"This phrase invites listeners to see personal benefit.","zh":"這個短語邀請聽眾看見個人好處。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"good enough to join","meaning":"好到足以加入","examples":[{"en":"Do not wait until you are good enough to join.","zh":"不要等到你好到足以加入才行動。"},{"en":"Good enough to join means skilled or confident enough to become a member.","zh":"good enough to join 的意思是技巧或信心足夠成為會員。"},{"en":"Some students wrongly think they must be good enough to join before attending training.","zh":"有些學生錯誤地以為自己必須先好到足以加入，才可以參加訓練。"},{"en":"Clubs exist to help members improve, so beginners should not wait for perfection.","zh":"學會存在是為了幫助會員進步，所以初學者不應等待完美。"},{"en":"This phrase challenges the fear of not being ready.","zh":"這個短語挑戰未準備好的恐懼。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"join so that","meaning":"加入，好讓","examples":[{"en":"Join so that you can become good enough.","zh":"加入，好讓你能變得足夠好。"},{"en":"Join so that means become a member for the purpose of achieving something.","zh":"join so that 的意思是為了達到某個目的而加入。"},{"en":"Join the club so that you can practise speaking every week.","zh":"加入學會，好讓你每星期都能練習發言。"},{"en":"This structure shows that joining is the path to improvement, not the reward after improvement.","zh":"這個結構顯示加入是進步的道路，而不是進步後的獎賞。"},{"en":"It encourages action before confidence is fully formed.","zh":"它鼓勵人在信心完全形成前先行動。"}],"source":"2012 Q5.pdf","sourcePage":13},{"front":"sign up at our booth","meaning":"在我們的攤位報名","examples":[{"en":"Students can sign up at our booth outside the hall.","zh":"學生可以在禮堂外我們的攤位報名。"},{"en":"To sign up at our booth means to register at the club’s table or stand.","zh":"sign up at our booth 的意思是在學會的桌子或攤位登記。"},{"en":"New members can sign up at the booth by writing their name and class.","zh":"新會員可以在攤位寫下姓名和班別報名。"},{"en":"A booth makes joining easier because students know where to go.","zh":"攤位令加入更容易，因為學生知道該去哪裏。"},{"en":"This phrase gives listeners a clear next step.","zh":"這個短語給聽眾清晰的下一步。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"outside the hall","meaning":"禮堂外","examples":[{"en":"The booth is outside the hall after assembly.","zh":"攤位在早會後設於禮堂外。"},{"en":"Outside the hall means in the area near but not inside the school hall.","zh":"outside the hall 的意思是在學校禮堂附近但不在禮堂裏面的地方。"},{"en":"Students may find the debating club booth outside the hall during recess.","zh":"學生可以在小息時於禮堂外找到辯論學會攤位。"},{"en":"Giving a location outside the hall helps students know exactly where to sign up.","zh":"說明地點在禮堂外，幫助學生確切知道去哪裏報名。"},{"en":"This phrase describes a clear physical place.","zh":"這個短語描述清楚的實體地點。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"after assembly","meaning":"早會後","examples":[{"en":"Students can sign up after assembly.","zh":"學生可以在早會後報名。"},{"en":"After assembly means during the time after the school gathering has ended.","zh":"after assembly 的意思是在學校集會結束後的時間。"},{"en":"Students may speak to committee members after assembly near the hall.","zh":"學生可以在早會後於禮堂附近與委員會成員交談。"},{"en":"This phrase gives a clear time for action.","zh":"這個短語給出清晰的行動時間。"},{"en":"It helps listeners remember when they can join.","zh":"它幫助聽眾記住何時可以加入。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"committee member","meaning":"委員會成員","examples":[{"en":"Students can speak to any committee member this week.","zh":"學生本星期可以與任何委員會成員交談。"},{"en":"A committee member is a person who helps organise and run a club or group.","zh":"committee member 是幫助組織和管理學會或團體的人。"},{"en":"A debating club committee member may answer questions about training times.","zh":"辯論學會委員會成員可以回答關於訓練時間的問題。"},{"en":"Speaking to a committee member can help nervous students understand how to join.","zh":"與委員會成員交談可以幫助緊張學生了解如何加入。"},{"en":"This phrase describes a contact person for the club.","zh":"這個短語描述學會的聯絡人。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"the sooner…the better","meaning":"越早……越好","examples":[{"en":"The sooner you begin, the better.","zh":"你越早開始，越好。"},{"en":"The sooner…the better means starting earlier will bring a better result.","zh":"the sooner…the better 的意思是越早開始，結果越好。"},{"en":"The sooner students practise speaking, the better their confidence can become.","zh":"學生越早練習發言，信心就可以變得越好。"},{"en":"This structure encourages listeners not to delay action.","zh":"這個結構鼓勵聽眾不要拖延行動。"},{"en":"It is useful when stressing the value of early effort.","zh":"當強調早期努力的價值時，它很有用。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"one thing is for sure","meaning":"有一點可以肯定","examples":[{"en":"One thing is for sure: your voice is worth training.","zh":"有一點可以肯定：你的聲音值得訓練。"},{"en":"One thing is for sure means this point is certain even if other things are uncertain.","zh":"one thing is for sure 的意思是即使其他事情不確定，這一點是肯定的。"},{"en":"You may feel nervous now, but one thing is for sure: practice will help.","zh":"你現在可能感到緊張，但有一點可以肯定：練習會有幫助。"},{"en":"Speakers use this phrase to end with confidence and clarity.","zh":"演講者使用這個短語，以信心和清晰度作結。"},{"en":"It helps listeners remember the main message.","zh":"它幫助聽眾記住主要訊息。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"worth training","meaning":"值得訓練","examples":[{"en":"Your voice is worth training.","zh":"你的聲音值得訓練。"},{"en":"Worth training means valuable enough to spend time improving.","zh":"worth training 的意思是有價值到值得花時間改善。"},{"en":"A shy student’s voice is worth training even if it shakes at first.","zh":"害羞學生的聲音即使起初顫抖，也值得訓練。"},{"en":"Training a voice means developing confidence, clarity, and judgement.","zh":"訓練聲音是發展信心、清晰度和判斷力。"},{"en":"This phrase encourages students to believe their growth matters.","zh":"這個短語鼓勵學生相信自己的成長重要。"}],"source":"2012 Q5.pdf","sourcePage":14},{"front":"love to have you on the team","meaning":"很希望你加入我們的團隊","examples":[{"en":"We would love to have you on the team.","zh":"我們很希望你加入我們的團隊。"},{"en":"Would love to have you on the team means we warmly want you to join us.","zh":"would love to have you on the team 的意思是我們真誠而熱情地希望你加入。"},{"en":"A club leader may say this to make new members feel welcome.","zh":"學會領袖可以用這句話令新會員感到受歡迎。"},{"en":"This phrase sounds friendly because it invites rather than pressures.","zh":"這個短語聽起來友善，因為它是邀請，而不是施壓。"},{"en":"It is a warm closing line for a recruitment speech.","zh":"它是招募演講中溫暖的結尾句。"}],"source":"2012 Q5.pdf","sourcePage":14}],"dse/writing/part-b/2012/Q6":[{"front":"beyond the mirror","meaning":"超越鏡中的外貌","examples":[{"en":"Hong Kong must look beyond the mirror and resist beauty obsession.","zh":"香港必須超越鏡中的外貌，抵抗對美貌的沉迷。"},{"en":"Beyond the mirror means looking past outward appearance to see a person’s character, feelings, and worth.","zh":"beyond the mirror 指超越外表，去看一個人的品格、感受和價值。"},{"en":"Students look beyond the mirror when they value kindness more than perfect skin.","zh":"當學生重視善良多於完美皮膚時，就是在超越鏡中的外貌。"},{"en":"A society that looks beyond the mirror will not judge people only by faces or bodies.","zh":"一個超越鏡中外貌的社會，不會只按臉孔或身形評價人。"},{"en":"This phrase reminds readers that beauty should not decide human value.","zh":"這個短語提醒讀者，美貌不應決定人的價值。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"resist the tyranny of beauty","meaning":"抵抗美貌霸權","examples":[{"en":"Hong Kong must resist the tyranny of beauty.","zh":"香港必須抵抗美貌霸權。"},{"en":"To resist the tyranny of beauty means to refuse to let narrow beauty standards control people’s lives.","zh":"resist the tyranny of beauty 指拒絕讓狹窄的美貌標準控制人們的生活。"},{"en":"Schools resist the tyranny of beauty when they praise effort and kindness more than appearance.","zh":"當學校讚賞努力和善良多於外貌時，就是在抵抗美貌霸權。"},{"en":"Young people can resist the tyranny of beauty by questioning edited images online.","zh":"年輕人可以透過質疑網上修圖照片來抵抗美貌霸權。"},{"en":"This phrase treats beauty pressure as a form of unfair power.","zh":"這個短語把美貌壓力視為一種不公平權力。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"tyranny of beauty","meaning":"美貌霸權","examples":[{"en":"The tyranny of beauty can make people confuse appearance with worth.","zh":"美貌霸權會令人混淆外貌與價值。"},{"en":"The tyranny of beauty means the unfair power beauty standards have over people’s choices and confidence.","zh":"tyranny of beauty 指美貌標準對人們的選擇和自信產生的不公平力量。"},{"en":"The tyranny of beauty appears when teenagers feel they must fix normal faces.","zh":"當青少年覺得自己必須修正正常面貌時，美貌霸權就出現了。"},{"en":"Under the tyranny of beauty, people may spend money they cannot afford on treatments.","zh":"在美貌霸權下，人們可能把負擔不起的錢花在療程上。"},{"en":"This phrase suggests that beauty has become controlling, not simply enjoyable.","zh":"這個短語暗示美貌已變成控制，而不只是愉悅。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"Dear Editor","meaning":"尊敬的編輯","examples":[{"en":"A formal letter to a newspaper may begin with “Dear Editor”.","zh":"寫給報章的正式信件可以用「尊敬的編輯」開頭。"},{"en":"Dear Editor is a polite greeting used when writing to a newspaper or magazine editor.","zh":"Dear Editor 是寫給報紙或雜誌編輯時使用的禮貌稱呼。"},{"en":"A student may begin a letter of complaint with “Dear Editor” before giving an opinion.","zh":"學生在提出意見前，可能用「尊敬的編輯」開始一封投訴信。"},{"en":"Using “Dear Editor” shows that the writer is addressing a public issue formally.","zh":"使用 Dear Editor 顯示作者正正式地討論公共議題。"},{"en":"This phrase helps set the correct tone for a letter to the press.","zh":"這個短語幫助建立寫給媒體的正確語氣。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"express my deep concern about","meaning":"表達我對……的深切關注","examples":[{"en":"I am writing to express my deep concern about beauty obsession.","zh":"我寫信是為了表達我對美貌沉迷的深切關注。"},{"en":"To express my deep concern about something means to state serious worry about it.","zh":"express my deep concern about something 指表達對某事的嚴重擔憂。"},{"en":"Parents may express deep concern about students spending too much time online.","zh":"家長可能表達對學生花太多時間上網的深切關注。"},{"en":"A citizen can write to express deep concern about misleading advertisements.","zh":"市民可以寫信表達對誤導性廣告的深切關注。"},{"en":"This phrase is useful in formal letters about social problems.","zh":"這個短語適合用於討論社會問題的正式信件。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"growing obsession with","meaning":"對……日益沉迷","examples":[{"en":"Hong Kong has a growing obsession with physical beauty.","zh":"香港對外貌美日益沉迷。"},{"en":"A growing obsession with something means an increasing unhealthy focus on it.","zh":"growing obsession with something 指對某事越來越不健康地專注。"},{"en":"A growing obsession with grades can make students forget learning itself.","zh":"對成績日益沉迷可能令學生忘記學習本身。"},{"en":"A growing obsession with beauty may make people compare themselves every day.","zh":"對美貌日益沉迷可能令人每天比較自己。"},{"en":"This phrase shows that the problem is becoming stronger over time.","zh":"這個短語顯示問題正隨時間變得更嚴重。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"physical beauty","meaning":"外貌美","examples":[{"en":"Many people feel pressured to pursue physical beauty.","zh":"許多人感到有壓力去追求外貌美。"},{"en":"Physical beauty means attractiveness in a person’s face, body, skin, or outward appearance.","zh":"physical beauty 指一個人在臉孔、身體、皮膚或外表上的吸引力。"},{"en":"Physical beauty may attract attention, but it does not prove kindness or ability.","zh":"外貌美可能吸引注意，但不能證明善良或能力。"},{"en":"Pressure to achieve physical beauty can damage confidence.","zh":"追求外貌美的壓力可能損害自信。"},{"en":"This phrase helps discuss appearance without confusing it with personal worth.","zh":"這個短語有助討論外表，而不把它與個人價值混淆。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"the wish to look attractive","meaning":"想變得吸引人的願望","examples":[{"en":"The wish to look attractive is human and understandable.","zh":"想變得吸引人的願望是合乎人性而可以理解的。"},{"en":"The wish to look attractive means the desire to appear pleasant, confident, or appealing to others.","zh":"the wish to look attractive 指希望自己看起來討人喜歡、自信或有吸引力。"},{"en":"A teenager’s wish to look attractive before a school event is natural.","zh":"青少年在學校活動前想變得吸引人是自然的。"},{"en":"The wish to look attractive becomes harmful only when it turns into fear or obsession.","zh":"想變得吸引人的願望只有在變成恐懼或沉迷時才有害。"},{"en":"This phrase gives a balanced view before criticising beauty pressure.","zh":"這個短語在批評美貌壓力前提供平衡看法。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"of course","meaning":"當然","examples":[{"en":"The wish to look attractive is, of course, understandable.","zh":"想變得吸引人的願望當然可以理解。"},{"en":"Of course means naturally, certainly, or as expected.","zh":"of course 指自然地、當然地或如預期般。"},{"en":"Of course, students want to look neat for a graduation photo.","zh":"當然，學生想在畢業照中看起來整齊。"},{"en":"Using “of course” can show that the writer recognises a reasonable point.","zh":"使用 of course 可以顯示作者承認一個合理觀點。"},{"en":"This phrase softens the argument by admitting that caring about appearance is normal.","zh":"這個短語透過承認注重外表是正常的，令論點較溫和。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"human and understandable","meaning":"合乎人性而可以理解","examples":[{"en":"Wanting to look attractive is human and understandable.","zh":"想看起來吸引人是合乎人性而可以理解的。"},{"en":"Human and understandable means normal for people and easy to sympathise with.","zh":"human and understandable 指對人來說正常，也容易令人理解和同情。"},{"en":"Feeling nervous before speaking in public is human and understandable.","zh":"公開發言前感到緊張是合乎人性而可以理解的。"},{"en":"Wanting to look good becomes a problem only when society turns it into pressure.","zh":"想看起來好看本身不是問題；當社會把它變成壓力時才有問題。"},{"en":"This phrase shows empathy while still allowing criticism of obsession.","zh":"這個短語顯示同理心，同時仍能批評沉迷。"}],"source":"2012 Q6.pdf","sourcePage":1},{"front":"beauty filters","meaning":"美顏濾鏡","examples":[{"en":"Beauty filters can make ordinary faces seem inadequate.","zh":"美顏濾鏡可以令普通臉孔看起來不夠好。"},{"en":"Beauty filters are digital effects that change a person’s face in photos or videos.","zh":"beauty filters 指在照片或影片中改變人臉的數碼效果。"},{"en":"Beauty filters may smooth skin, enlarge eyes, or sharpen the jawline.","zh":"美顏濾鏡可能磨平皮膚、放大眼睛或令下顎線更尖。"},{"en":"If young people use beauty filters too often, they may dislike their real faces.","zh":"如果年輕人太常使用美顏濾鏡，可能會不喜歡真實面貌。"},{"en":"This phrase shows how technology can create unrealistic beauty standards.","zh":"這個短語顯示科技如何製造不切實際的美貌標準。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"celebrity culture","meaning":"名人文化","examples":[{"en":"Celebrity culture often promotes narrow beauty standards.","zh":"名人文化常推廣狹窄的美貌標準。"},{"en":"Celebrity culture means the public attention given to famous actors, singers, influencers, and their lifestyles.","zh":"celebrity culture 指公眾對著名演員、歌手、網紅及其生活方式的關注。"},{"en":"Celebrity culture can make fans copy stars’ clothes, faces, and bodies.","zh":"名人文化可以令粉絲模仿名人的衣着、臉孔和身材。"},{"en":"When celebrity culture shows only one kind of beauty, ordinary people may feel inadequate.","zh":"當名人文化只展示一種美，普通人可能覺得自己不夠好。"},{"en":"This phrase helps explain how fame shapes social expectations.","zh":"這個短語有助解釋名氣如何塑造社會期望。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"cosmetic-surgery advertisements","meaning":"整容廣告","examples":[{"en":"Cosmetic-surgery advertisements appear across Hong Kong.","zh":"整容廣告在香港到處出現。"},{"en":"Cosmetic-surgery advertisements are promotions for operations or procedures that change appearance.","zh":"cosmetic-surgery advertisements 指推廣改變外貌的手術或療程的廣告。"},{"en":"Cosmetic-surgery advertisements may promise sharper features, smoother skin, or a younger face.","zh":"整容廣告可能承諾帶來更尖的五官、更滑的皮膚或更年輕的臉。"},{"en":"Seeing cosmetic-surgery advertisements everywhere can make normal faces feel like problems.","zh":"到處看見整容廣告，可能令正常面貌看似問題。"},{"en":"This phrase shows how commercial messages turn insecurity into business.","zh":"這個短語顯示商業訊息如何把不安全感變成生意。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"appear everywhere from…to…","meaning":"從……到……隨處可見","examples":[{"en":"Beauty advertisements appear everywhere from MTR billboards to social media feeds.","zh":"美容廣告從港鐵廣告牌到社交媒體動態都隨處可見。"},{"en":"Appear everywhere from A to B means be seen in many places, including both A and B.","zh":"appear everywhere from A to B 指在許多地方都能看見，包括 A 和 B。"},{"en":"Exam notices appeared everywhere from classroom doors to school websites.","zh":"考試通知從課室門口到學校網站都隨處可見。"},{"en":"Beauty messages appear everywhere from train stations to phone screens, so they are hard to escape.","zh":"美貌訊息從車站到手機螢幕都隨處可見，因此很難避開。"},{"en":"This phrase shows how widespread a problem has become.","zh":"這個短語顯示問題已變得多麼普遍。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"MTR billboards","meaning":"港鐵廣告牌","examples":[{"en":"Cosmetic-surgery advertisements can be seen on MTR billboards.","zh":"整容廣告可以在港鐵廣告牌上看見。"},{"en":"MTR billboards are large advertising boards in Hong Kong’s railway stations or trains.","zh":"MTR billboards 指香港鐵路站或列車中的大型廣告牌。"},{"en":"People may see MTR billboards while waiting for the train.","zh":"人們等車時可能看見港鐵廣告牌。"},{"en":"If MTR billboards constantly show beauty procedures, commuters receive the message every day.","zh":"如果港鐵廣告牌不斷展示美容療程，通勤者每天都會接收這種訊息。"},{"en":"This phrase gives a concrete Hong Kong example of public beauty pressure.","zh":"這個短語提供香港公共美貌壓力的具體例子。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"social media feeds","meaning":"社交媒體動態","examples":[{"en":"Beauty images appear constantly on social media feeds.","zh":"美貌圖片不斷出現在社交媒體動態中。"},{"en":"Social media feeds are the streams of posts, videos, and advertisements users see online.","zh":"social media feeds 指用戶在網上看到的一連串帖文、影片和廣告。"},{"en":"A teenager may scroll through social media feeds before sleeping.","zh":"青少年可能睡前瀏覽社交媒體動態。"},{"en":"Social media feeds can repeat filtered faces until they seem normal.","zh":"社交媒體動態可以反覆展示濾鏡臉孔，直到它們看似正常。"},{"en":"This phrase shows how beauty pressure enters private daily life.","zh":"這個短語顯示美貌壓力如何進入私人日常生活。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"especially young people","meaning":"尤其是年輕人","examples":[{"en":"Many citizens, especially young people, feel pressure to change their appearance.","zh":"許多市民，尤其是年輕人，感到有壓力要改變外貌。"},{"en":"Especially young people means young people in particular are strongly affected.","zh":"especially young people 指年輕人尤其受到強烈影響。"},{"en":"Beauty filters may influence many users, especially young people still building confidence.","zh":"美顏濾鏡可能影響許多用戶，尤其是仍在建立自信的年輕人。"},{"en":"Young people are especially vulnerable because they compare themselves with peers online.","zh":"年輕人尤其容易受影響，因為他們會在網上與同輩比較。"},{"en":"This phrase highlights the group most at risk.","zh":"這個短語突顯最有風險的群體。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"be encouraged to","meaning":"被鼓勵去","examples":[{"en":"Young people are being encouraged to alter their faces and bodies.","zh":"年輕人正被鼓勵去改變面貌和身體。"},{"en":"Be encouraged to means be pushed, persuaded, or invited to do something.","zh":"be encouraged to 指被推動、說服或邀請去做某事。"},{"en":"Students should be encouraged to read more, not to hate their appearance.","zh":"學生應被鼓勵去多閱讀，而不是討厭自己的外貌。"},{"en":"Advertisements encourage people to change their faces by calling normal features flaws.","zh":"廣告把正常特徵稱為缺陷，鼓勵人改變臉孔。"},{"en":"This phrase shows how outside messages influence personal choices.","zh":"這個短語顯示外來訊息如何影響個人選擇。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"alter their faces and bodies","meaning":"改變面貌和身體","examples":[{"en":"Some young people feel encouraged to alter their faces and bodies.","zh":"有些年輕人覺得自己被鼓勵去改變面貌和身體。"},{"en":"Alter their faces and bodies means change their physical appearance through products, filters, or procedures.","zh":"alter their faces and bodies 指透過產品、濾鏡或療程改變外貌。"},{"en":"Teenagers may feel pressure to alter their faces after seeing edited selfies.","zh":"青少年看見修圖自拍後，可能感到壓力要改變面貌。"},{"en":"People should not feel forced to alter their bodies just to be accepted.","zh":"人們不應為了被接納而被迫改變身體。"},{"en":"This phrase shows how beauty pressure can reach both face and body.","zh":"這個短語顯示美貌壓力可以影響臉孔和身體。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"in order to","meaning":"為了","examples":[{"en":"Some people change their appearance in order to gain confidence.","zh":"有些人改變外貌，是為了獲得自信。"},{"en":"In order to means for the purpose of doing something.","zh":"in order to 指為了達到某個目的。"},{"en":"Students revise early in order to feel prepared for exams.","zh":"學生早點溫習，是為了在考試中感到有準備。"},{"en":"Some people buy beauty products in order to feel accepted by others.","zh":"有些人購買美容產品，是為了感到被別人接納。"},{"en":"This phrase clearly connects an action with its purpose.","zh":"這個短語清楚把行動和目的連接起來。"}],"source":"2012 Q6.pdf","sourcePage":2},{"front":"gain confidence, acceptance and opportunities","meaning":"獲得自信、認同和機會","examples":[{"en":"Many young people believe beauty can help them gain confidence, acceptance and opportunities.","zh":"許多年輕人相信美貌可以幫助他們獲得自信、認同和機會。"},{"en":"To gain confidence, acceptance and opportunities means to feel more self-assured, be welcomed, and receive better chances.","zh":"gain confidence, acceptance and opportunities 指變得更有自信、被接納，並得到更好機會。"},{"en":"A student should gain confidence through skills and support, not only through appearance.","zh":"學生應透過技能和支持獲得自信，而不只是靠外貌。"},{"en":"If society links beauty with opportunity, people may feel forced to change themselves.","zh":"如果社會把美貌與機會連在一起，人們可能覺得被迫改變自己。"},{"en":"This phrase shows why beauty pressure can feel powerful and personal.","zh":"這個短語顯示美貌壓力為何會強大而私人化。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, this trend is unhealthy.","zh":"就我而言，這個趨勢是不健康的。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"as far as I am concerned 指以我的看法或立場來說。"},{"en":"As far as I am concerned, schools should teach students to question advertisements.","zh":"就我而言，學校應教學生質疑廣告。"},{"en":"This phrase is useful for stating a clear personal view in formal writing.","zh":"這個短語適合在正式寫作中清楚表達個人觀點。"},{"en":"It helps the writer move from description to judgement.","zh":"它幫助作者從描述轉向判斷。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"not merely a matter of personal taste","meaning":"不只是個人品味問題","examples":[{"en":"This trend is not merely a matter of personal taste.","zh":"這個趨勢不只是個人品味問題。"},{"en":"Not merely a matter of personal taste means the issue is larger than individual preference.","zh":"not merely a matter of personal taste 指問題比個人喜好更大。"},{"en":"School uniform rules are not merely a matter of personal taste when they affect equality.","zh":"當校服規則影響平等時，它就不只是個人品味問題。"},{"en":"Beauty obsession is not merely personal because it shapes confidence, money and discrimination.","zh":"美貌沉迷不只是個人問題，因為它影響自信、金錢和歧視。"},{"en":"This phrase helps turn a private issue into a social argument.","zh":"這個短語幫助把私人問題轉化為社會論點。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"reflect a culture that","meaning":"反映一種……的文化","examples":[{"en":"The trend reflects a culture that confuses appearance with worth.","zh":"這個趨勢反映一種混淆外貌與價值的文化。"},{"en":"Reflect a culture that means show the values or habits of a society.","zh":"reflect a culture that 指顯示一個社會的價值觀或習慣。"},{"en":"Long working hours may reflect a culture that values productivity over rest.","zh":"長工時可能反映一種重視生產力多於休息的文化。"},{"en":"Beauty pressure reflects a culture that rewards people for looking perfect.","zh":"美貌壓力反映一種獎勵完美外表的文化。"},{"en":"This phrase helps connect individual behaviour to wider social values.","zh":"這個短語幫助把個人行為連到更廣泛的社會價值。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"confuse appearance with worth","meaning":"混淆外貌與價值","examples":[{"en":"Society should not confuse appearance with worth.","zh":"社會不應混淆外貌與價值。"},{"en":"Confuse appearance with worth means wrongly think a person’s looks show their value.","zh":"confuse appearance with worth 指錯誤地以為一個人的外貌代表他的價值。"},{"en":"A kind nurse should not be valued less because she does not look fashionable.","zh":"友善的護士不應因不夠時尚而被看低。"},{"en":"When people confuse appearance with worth, they may ignore character and ability.","zh":"當人們混淆外貌與價值，就可能忽略品格和能力。"},{"en":"This phrase names the central mistake behind beauty obsession.","zh":"這個短語指出美貌沉迷背後的核心錯誤。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"unless we challenge","meaning":"除非我們挑戰","examples":[{"en":"Unless we challenge this obsession, young people will suffer.","zh":"除非我們挑戰這種沉迷，否則年輕人會受苦。"},{"en":"Unless we challenge means if we do not question or resist something.","zh":"unless we challenge 指如果我們不質疑或抵抗某事。"},{"en":"Unless we challenge unfair rules, they will continue to hurt students.","zh":"除非我們挑戰不公平規則，否則它們會繼續傷害學生。"},{"en":"Unless society challenges beauty pressure, teenagers may believe they are never enough.","zh":"除非社會挑戰美貌壓力，否則青少年可能相信自己永遠不夠好。"},{"en":"This phrase warns that inaction will have consequences.","zh":"這個短語警告不行動會帶來後果。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"unhealthy obsession","meaning":"不健康的沉迷","examples":[{"en":"Hong Kong must challenge this unhealthy obsession.","zh":"香港必須挑戰這種不健康的沉迷。"},{"en":"An unhealthy obsession is an excessive focus on something that harms mental, social or physical well-being.","zh":"unhealthy obsession 指對某事過度專注，以致傷害心理、社交或身體健康。"},{"en":"An unhealthy obsession with grades can make students anxious and exhausted.","zh":"對成績不健康地沉迷，可能令學生焦慮和疲憊。"},{"en":"Beauty becomes an unhealthy obsession when it controls spending, eating and self-worth.","zh":"當美貌控制消費、飲食和自我價值，它就變成不健康的沉迷。"},{"en":"This phrase shows that the problem is not beauty itself, but extreme fixation.","zh":"這個短語顯示問題不是美本身，而是極端執着。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"raise a generation that","meaning":"培養出一代……的人","examples":[{"en":"We may raise a generation that knows how to edit selfies but not value itself.","zh":"我們可能培養出一代懂得修圖自拍，卻不懂重視自身價值的人。"},{"en":"Raise a generation that means shape young people so they grow up with certain beliefs or habits.","zh":"raise a generation that 指塑造年輕人，使他們長大後帶着某些信念或習慣。"},{"en":"Schools and families can raise a generation that questions online images wisely.","zh":"學校和家庭可以培養出一代明智質疑網上圖片的人。"},{"en":"A society obsessed with beauty may raise young people who fear their natural faces.","zh":"沉迷美貌的社會可能培養出一代害怕自然面貌的年輕人。"},{"en":"This phrase warns about long-term effects on children and teenagers.","zh":"這個短語警告對兒童和青少年的長遠影響。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"edit a selfie","meaning":"修圖自拍","examples":[{"en":"Young people may know how to edit a selfie but not how to value themselves.","zh":"年輕人可能懂得修圖自拍，卻不懂如何重視自己。"},{"en":"Edit a selfie means change a self-taken photo using filters, tools or apps.","zh":"edit a selfie 指用濾鏡、工具或應用程式修改自拍照。"},{"en":"A teenager may edit a selfie to make her skin look smoother.","zh":"青少年可能修圖自拍，讓皮膚看起來更光滑。"},{"en":"Editing a selfie becomes harmful when the real face starts to feel unacceptable.","zh":"當真實臉孔開始變得不可接受時，修圖自拍就變得有害。"},{"en":"This phrase shows the difference between digital skill and self-worth.","zh":"這個短語顯示數碼技巧和自我價值之間的分別。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"value itself","meaning":"重視自身價值","examples":[{"en":"A generation must learn how to value itself.","zh":"一代人必須學會如何重視自身價值。"},{"en":"Value itself means recognise its own worth without depending only on outside approval.","zh":"value itself 指認清自身價值，而不只依賴外界認同。"},{"en":"A student learns to value herself when she sees effort as important.","zh":"當學生明白努力很重要時，她就學會重視自己。"},{"en":"Young people who value themselves are less controlled by beauty advertisements.","zh":"重視自身價值的年輕人較不容易被美容廣告控制。"},{"en":"This phrase focuses on inner worth rather than appearance.","zh":"這個短語聚焦內在價值，而不是外貌。"}],"source":"2012 Q6.pdf","sourcePage":3},{"front":"first and foremost","meaning":"首先；最重要的是","examples":[{"en":"First and foremost, beauty worship damages self-esteem.","zh":"首先，對美貌的崇拜會損害自尊。"},{"en":"First and foremost means most importantly and before anything else.","zh":"first and foremost 指最重要的是，而且在其他事情之前。"},{"en":"First and foremost, schools should protect students’ mental health.","zh":"首先，學校應保護學生的心理健康。"},{"en":"A formal argument uses this phrase to introduce the strongest or first major point.","zh":"正式論述會用這個短語引入最有力或第一個主要觀點。"},{"en":"This phrase tells readers that self-esteem is the writer’s main concern.","zh":"這個短語告訴讀者，自尊是作者最關心的問題。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"the worship of physical beauty","meaning":"對外貌美的崇拜","examples":[{"en":"The worship of physical beauty can damage self-esteem.","zh":"對外貌美的崇拜會損害自尊。"},{"en":"The worship of physical beauty means treating outward appearance as if it is extremely important or almost sacred.","zh":"worship of physical beauty 指把外貌看得極其重要，甚至近乎神聖。"},{"en":"The worship of physical beauty may make teenagers fear normal ageing.","zh":"對外貌美的崇拜可能令青少年害怕正常老化。"},{"en":"When schools reward looks too much, they may support the worship of physical beauty.","zh":"當學校過度獎勵外表時，可能助長對外貌美的崇拜。"},{"en":"This phrase criticises society for valuing appearance too highly.","zh":"這個短語批評社會過分重視外貌。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"damage self-esteem","meaning":"損害自尊","examples":[{"en":"Beauty pressure can damage young people’s self-esteem.","zh":"美貌壓力會損害年輕人的自尊。"},{"en":"Damage self-esteem means harm a person’s belief that they are valuable and worthy.","zh":"damage self-esteem 指傷害一個人相信自己有價值、值得被尊重的感覺。"},{"en":"Constant criticism of appearance can damage a child’s self-esteem.","zh":"不斷批評外貌可能損害孩子的自尊。"},{"en":"Edited images may damage self-esteem by making real faces seem wrong.","zh":"修圖圖片可能令真實臉孔看似錯誤，從而損害自尊。"},{"en":"This phrase explains one major emotional effect of beauty obsession.","zh":"這個短語解釋美貌沉迷的一個主要情緒影響。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"turn ordinary features into supposed defects","meaning":"把普通特徵變成所謂缺陷","examples":[{"en":"Beauty standards can turn ordinary features into supposed defects.","zh":"美貌標準可以把普通特徵變成所謂缺陷。"},{"en":"To turn ordinary features into supposed defects means make normal body traits seem like problems.","zh":"turn ordinary features into supposed defects 指令正常外貌特徵看似問題。"},{"en":"Advertising can turn freckles into supposed defects by selling products to hide them.","zh":"廣告透過售賣遮蓋雀斑的產品，可以把雀斑變成所謂缺陷。"},{"en":"When normal faces are called flawed, teenagers may feel they need fixing.","zh":"當正常臉孔被稱為有瑕疵，青少年可能覺得自己需要被修正。"},{"en":"This phrase shows how beauty culture creates insecurity.","zh":"這個短語顯示美貌文化如何製造不安全感。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"ordinary features","meaning":"普通外貌特徵","examples":[{"en":"Single eyelids and freckles are ordinary features.","zh":"單眼皮和雀斑都是普通外貌特徵。"},{"en":"Ordinary features are normal parts of a person’s face or body.","zh":"ordinary features 指一個人臉孔或身體的正常部分。"},{"en":"A round face, darker skin, or small eyes can all be ordinary features.","zh":"圓臉、較深膚色或小眼睛都可以是普通外貌特徵。"},{"en":"Ordinary features should not be treated as problems just because trends change.","zh":"普通外貌特徵不應只因潮流改變就被視為問題。"},{"en":"This phrase helps remind readers that normal variety is not failure.","zh":"這個短語提醒讀者，正常差異不是失敗。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"supposed defects","meaning":"所謂缺陷","examples":[{"en":"Young people may start to see ordinary features as supposed defects.","zh":"年輕人可能開始把普通特徵視為所謂缺陷。"},{"en":"Supposed defects are things people are told are flaws, even though they may be normal.","zh":"supposed defects 指人們被告知是缺陷的東西，即使它們可能很正常。"},{"en":"A gap between teeth may be treated as a supposed defect by beauty advertising.","zh":"牙縫可能被美容廣告視為所謂缺陷。"},{"en":"Calling normal features supposed defects can make people feel ashamed.","zh":"把正常特徵稱為所謂缺陷，會令人感到羞愧。"},{"en":"This phrase questions whether the “defect” is real or socially invented.","zh":"這個短語質疑「缺陷」是真實存在，還是由社會製造。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"single eyelids","meaning":"單眼皮","examples":[{"en":"A teenager with single eyelids should not feel inferior.","zh":"有單眼皮的青少年不應感到自卑。"},{"en":"Single eyelids are eyelids without a visible crease above the eye.","zh":"single eyelids 指眼睛上方沒有明顯摺痕的眼皮。"},{"en":"Many people naturally have single eyelids, and they are not a defect.","zh":"許多人天生有單眼皮，而它不是缺陷。"},{"en":"Beauty pressure may make teenagers with single eyelids consider unnecessary surgery.","zh":"美貌壓力可能令單眼皮青少年考慮不必要的手術。"},{"en":"This phrase gives a concrete example of a normal feature being judged unfairly.","zh":"這個短語提供正常特徵被不公平評價的具體例子。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"freckles","meaning":"雀斑","examples":[{"en":"Freckles can be a harmless part of a person’s identity.","zh":"雀斑可以是一個人身分中無害的一部分。"},{"en":"Freckles are small brown spots on the skin, often caused or darkened by sunlight.","zh":"freckles 指皮膚上的細小啡色斑點，常由陽光造成或加深。"},{"en":"Some children have freckles across their noses and cheeks.","zh":"有些孩子鼻子和臉頰上有雀斑。"},{"en":"Freckles should not be treated as flaws just because advertisements sell perfect skin.","zh":"雀斑不應只因廣告推銷完美皮膚而被視為缺點。"},{"en":"This word shows how a natural feature can become unfairly criticised.","zh":"這個詞顯示自然特徵如何被不公平批評。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"a round face","meaning":"圓臉","examples":[{"en":"A round face should not be treated as a defect.","zh":"圓臉不應被視為缺陷。"},{"en":"A round face is a face with soft curves and less sharp angles.","zh":"round face 指線條柔和、角度較不尖銳的臉形。"},{"en":"A person with a round face may look friendly, youthful, or gentle.","zh":"圓臉的人可能看起來友善、年輕或溫和。"},{"en":"Beauty trends that praise only sharp jawlines can make a round face seem wrong.","zh":"只讚賞尖削下顎線的美貌潮流，可能令圓臉看似錯誤。"},{"en":"This phrase reminds readers that face shapes naturally differ.","zh":"這個短語提醒讀者，臉形本來就有自然差異。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"regard these as","meaning":"把這些視為","examples":[{"en":"A teenager may once have regarded these features as harmless.","zh":"青少年可能曾經把這些特徵視為無害。"},{"en":"Regard these as means think of these things in a particular way.","zh":"regard these as 指以某種方式看待這些事物。"},{"en":"Children may regard freckles as cute before advertisements teach them otherwise.","zh":"孩子可能把雀斑視為可愛，直到廣告教他們相反想法。"},{"en":"If people regard normal features as defects, their confidence may fall.","zh":"如果人們把正常特徵視為缺陷，自信可能下降。"},{"en":"This phrase shows how interpretation changes the emotional meaning of appearance.","zh":"這個短語顯示理解方式如何改變外貌的情感意義。"}],"source":"2012 Q6.pdf","sourcePage":4},{"front":"harmless parts of their identity","meaning":"身分中無害的一部分","examples":[{"en":"Ordinary features can be harmless parts of a teenager’s identity.","zh":"普通外貌特徵可以是青少年身分中無害的一部分。"},{"en":"Harmless parts of their identity means natural features that belong to who they are and do not need fixing.","zh":"harmless parts of their identity 指自然屬於他們自己、毋須修正的特徵。"},{"en":"A birthmark can be a harmless part of a person’s identity.","zh":"胎記可以是一個人身分中無害的一部分。"},{"en":"Treating harmless features as problems can make teenagers feel ashamed of themselves.","zh":"把無害特徵視為問題，可能令青少年對自己感到羞愧。"},{"en":"This phrase supports acceptance of natural appearance.","zh":"這個短語支持接納自然外貌。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"scroll through endless images","meaning":"不停瀏覽無窮無盡的圖片","examples":[{"en":"Teenagers scroll through endless images of perfect-looking faces.","zh":"青少年不停瀏覽無窮無盡的完美臉孔圖片。"},{"en":"Scroll through endless images means keep moving through many pictures on a phone or screen.","zh":"scroll through endless images 指在手機或螢幕上不斷滑看大量圖片。"},{"en":"A student may scroll through endless images before bed and compare herself with strangers.","zh":"學生睡前可能不停瀏覽無窮無盡的圖片，並把自己與陌生人比較。"},{"en":"Endless beauty images can make unrealistic faces feel ordinary.","zh":"無窮無盡的美貌圖片可以令不切實際的臉孔看似普通。"},{"en":"This phrase shows how repeated online viewing creates pressure.","zh":"這個短語顯示反覆網上觀看如何製造壓力。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"sharpened jawlines","meaning":"尖削下顎線","examples":[{"en":"Social media often shows images of sharpened jawlines.","zh":"社交媒體常展示尖削下顎線的圖片。"},{"en":"Sharpened jawlines are jawlines made to look clearer, narrower, or more angular.","zh":"sharpened jawlines 指被塑造成更清晰、更窄或更有角度的下顎線。"},{"en":"Photo apps can create sharpened jawlines even when a person’s real face is softer.","zh":"修圖程式可以製造尖削下顎線，即使真人臉形較柔和。"},{"en":"Constant images of sharpened jawlines may make round faces seem less acceptable.","zh":"不斷看見尖削下顎線的圖片，可能令圓臉顯得較不被接受。"},{"en":"This phrase gives an example of a beauty ideal shaped by editing.","zh":"這個短語提供由修圖塑造美貌理想的例子。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"flawless skin","meaning":"無瑕肌膚","examples":[{"en":"Advertisements often promote flawless skin.","zh":"廣告常推廣無瑕肌膚。"},{"en":"Flawless skin means skin that looks perfect, smooth, and without marks.","zh":"flawless skin 指看起來完美、平滑、沒有痕跡的皮膚。"},{"en":"Real skin may have pores, spots, wrinkles, or uneven colour.","zh":"真實皮膚可能有毛孔、暗瘡、皺紋或膚色不均。"},{"en":"When advertisements promote flawless skin, teenagers may treat normal skin as failure.","zh":"當廣告推廣無瑕肌膚，青少年可能把正常皮膚視為失敗。"},{"en":"This phrase shows how perfection can become unrealistic pressure.","zh":"這個短語顯示完美如何變成不切實際的壓力。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"impossibly slim bodies","meaning":"瘦得不切實際的身形","examples":[{"en":"Young people are shown images of impossibly slim bodies.","zh":"年輕人被展示瘦得不切實際的身形圖片。"},{"en":"Impossibly slim bodies are bodies shown as extremely thin in a way that is unrealistic for many people.","zh":"impossibly slim bodies 指被呈現得極瘦、對很多人而言不現實的身形。"},{"en":"Edited photos can create impossibly slim bodies that do not reflect real health.","zh":"修圖照片可以製造瘦得不切實際的身形，並不反映真正健康。"},{"en":"Seeing impossibly slim bodies every day can encourage dangerous dieting.","zh":"每天看見瘦得不切實際的身形，可能鼓勵危險節食。"},{"en":"This phrase criticises beauty standards that ignore natural body diversity.","zh":"這個短語批評忽視自然身體差異的美貌標準。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"start to see themselves as","meaning":"開始把自己視為","examples":[{"en":"Teenagers may start to see themselves as unfinished projects.","zh":"青少年可能開始把自己視為未完成的改造項目。"},{"en":"Start to see themselves as means begin to think of themselves in a certain way.","zh":"start to see themselves as 指開始以某種方式看待自己。"},{"en":"A child may start to see herself as weak if people always criticise her.","zh":"如果人們總是批評孩子，她可能開始把自己視為軟弱。"},{"en":"Teenagers may start to see themselves as problems after constant beauty comparison.","zh":"在不斷美貌比較後，青少年可能開始把自己視為問題。"},{"en":"This phrase shows how repeated messages change self-image.","zh":"這個短語顯示反覆訊息如何改變自我形象。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"unfinished projects","meaning":"未完成的改造項目","examples":[{"en":"Young people should not see themselves as unfinished projects.","zh":"年輕人不應把自己視為未完成的改造項目。"},{"en":"Unfinished projects means things that are incomplete and need fixing or improvement.","zh":"unfinished projects 指尚未完成、需要修正或改善的東西。"},{"en":"A person is not an unfinished project just because their skin has spots.","zh":"一個人不會只因皮膚有斑點就成為未完成的改造項目。"},{"en":"Beauty culture can make teenagers feel like unfinished projects waiting for products and procedures.","zh":"美貌文化可以令青少年覺得自己像等待產品和療程的未完成項目。"},{"en":"This phrase criticises the idea that normal bodies must be constantly improved.","zh":"這個短語批評正常身體必須不斷改善的想法。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"the more…, the less…","meaning":"越……，就越少……","examples":[{"en":"The more teenagers compare, the less they accept themselves.","zh":"青少年越比較，就越少接納自己。"},{"en":"The more A, the less B means as A increases, B decreases.","zh":"the more A, the less B 指 A 越增加，B 越減少。"},{"en":"The more students sleep late, the less energy they have in class.","zh":"學生越晚睡，上課時就越少精力。"},{"en":"The more teenagers compare with edited images, the less satisfied they may feel.","zh":"青少年越與修圖圖片比較，就越少感到滿足。"},{"en":"This structure clearly shows a negative relationship between two changes.","zh":"這個結構清楚顯示兩種變化之間的負面關係。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"the less…, the more vulnerable…","meaning":"越少……，就越容易受……影響","examples":[{"en":"The less they accept themselves, the more vulnerable they become.","zh":"他們越少接納自己，就越容易受影響。"},{"en":"The less A, the more vulnerable B becomes means lower self-acceptance increases the risk of being harmed or influenced.","zh":"the less A, the more vulnerable B becomes 指自我接納越低，受傷害或被影響的風險越高。"},{"en":"The less sleep students get, the more vulnerable they become to stress.","zh":"學生睡得越少，就越容易受壓力影響。"},{"en":"The less teenagers accept themselves, the more vulnerable they are to beauty marketing.","zh":"青少年越少接納自己，就越容易受美容營銷影響。"},{"en":"This pattern shows how insecurity opens the door to pressure.","zh":"這個句式顯示不安全感如何打開壓力的大門。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"become vulnerable to","meaning":"容易受……影響","examples":[{"en":"Insecure teenagers may become vulnerable to beauty products.","zh":"沒有安全感的青少年可能容易受美容產品影響。"},{"en":"Become vulnerable to means become more easily influenced, harmed, or controlled by something.","zh":"become vulnerable to 指變得更容易被某事影響、傷害或控制。"},{"en":"Tired students may become vulnerable to online distractions.","zh":"疲倦學生可能容易受網上干擾影響。"},{"en":"Teenagers with low self-esteem may become vulnerable to advertisements promising a better face.","zh":"自尊較低的青少年可能容易受承諾帶來「更好」臉孔的廣告影響。"},{"en":"This phrase shows how weakness or insecurity can be exploited.","zh":"這個短語顯示弱點或不安全感如何被利用。"}],"source":"2012 Q6.pdf","sourcePage":5},{"front":"products and procedures","meaning":"產品和療程","examples":[{"en":"Products and procedures often promise a better face.","zh":"產品和療程常承諾帶來一張更好的臉。"},{"en":"Products and procedures means beauty goods and treatments, including creams, devices, injections, or surgery.","zh":"products and procedures 指美容商品和治療，包括面霜、儀器、注射或手術。"},{"en":"Shops sell products, while clinics offer procedures to change appearance.","zh":"商店售賣產品，而診所提供改變外貌的療程。"},{"en":"Products and procedures can be useful, but they become harmful when sold through fear.","zh":"產品和療程可以有用，但如果透過恐懼銷售，就會變得有害。"},{"en":"This phrase covers both everyday beauty items and more serious treatments.","zh":"這個短語涵蓋日常美容用品和較嚴肅的療程。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"promise a “better” face","meaning":"承諾帶來一張「更好」的臉","examples":[{"en":"Some products promise a “better” face.","zh":"有些產品承諾帶來一張「更好」的臉。"},{"en":"Promise a “better” face means claim that a product or treatment will improve someone’s appearance.","zh":"promise a “better” face 指聲稱產品或療程會改善某人的外貌。"},{"en":"A cream may promise a “better” face by saying it can remove every mark.","zh":"面霜可能透過聲稱能去除每個痕跡，承諾帶來一張「更好」的臉。"},{"en":"Such promises can make people believe their natural face is not good enough.","zh":"這種承諾可以令人相信自己的自然臉孔不夠好。"},{"en":"The quotation marks around “better” suggest the claim should be questioned.","zh":"“better” 加上引號，暗示這種說法應被質疑。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"take…, for example","meaning":"以……為例","examples":[{"en":"Take a Secondary Four student, for example.","zh":"以一名中四學生為例。"},{"en":"Take something for example means use it as a clear case to explain a point.","zh":"take something for example 指用某事作為清楚例子來解釋觀點。"},{"en":"Take school uniforms, for example: they can reduce pressure to dress expensively.","zh":"以校服為例：它們可以減少穿昂貴衣服的壓力。"},{"en":"A writer uses this phrase to move from a general idea to a concrete situation.","zh":"作者使用這個短語，把一般想法轉向具體情境。"},{"en":"This phrase helps readers understand a social problem through one person.","zh":"這個短語幫助讀者透過一個人理解社會問題。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"receive fewer “likes”","meaning":"獲得較少「讚好」","examples":[{"en":"A student may feel upset if she receives fewer “likes”.","zh":"如果學生獲得較少「讚好」，她可能感到難過。"},{"en":"Receive fewer “likes” means get a smaller number of approval clicks on social media.","zh":"receive fewer “likes” 指在社交媒體上得到較少表示認同的點擊。"},{"en":"A teenager may feel ignored when her selfie receives fewer likes than her friend’s.","zh":"當自拍照比朋友少讚好時，青少年可能覺得被忽視。"},{"en":"Judging worth by likes can make online approval feel too important.","zh":"用讚好數判斷價值，會令網上認同變得過分重要。"},{"en":"This phrase shows how social media numbers can affect self-esteem.","zh":"這個短語顯示社交媒體數字如何影響自尊。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"use filters","meaning":"使用濾鏡","examples":[{"en":"A classmate who uses filters may receive more attention online.","zh":"使用濾鏡的同學可能在網上得到更多注意。"},{"en":"Use filters means apply digital effects to change a photo or video.","zh":"use filters 指套用數碼效果來改變照片或影片。"},{"en":"Students may use filters to make skin smoother or eyes brighter.","zh":"學生可能使用濾鏡令皮膚更平滑或眼睛更明亮。"},{"en":"If filtered photos receive more attention, teenagers may feel their real faces are not enough.","zh":"如果濾鏡照片得到更多注意，青少年可能覺得真實臉孔不夠好。"},{"en":"This phrase shows how edited images can shape online comparison.","zh":"這個短語顯示修圖圖片如何塑造網上比較。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"conclude not that…, but that…","meaning":"得出的結論不是……，而是……","examples":[{"en":"She may conclude not that the online world is artificial, but that she is inadequate.","zh":"她得出的結論可能不是網上世界是人為加工的，而是自己不夠好。"},{"en":"Conclude not that A, but that B means reach the wrong second conclusion instead of the more reasonable first one.","zh":"conclude not that A, but that B 指沒有得出較合理的第一個結論，反而得出有害的第二個結論。"},{"en":"A student may conclude not that the test was unfair, but that she is stupid.","zh":"學生得出的結論可能不是測驗不公平，而是自己愚蠢。"},{"en":"Teenagers should conclude that filtered images are artificial, not that they are inadequate.","zh":"青少年應得出濾鏡圖片是人為加工的結論，而不是自己不夠好。"},{"en":"This structure shows a harmful mistake in thinking.","zh":"這個結構顯示一種有害的思考錯誤。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"the online world is artificial","meaning":"網上世界是人為加工的","examples":[{"en":"Teenagers should understand that the online world is artificial.","zh":"青少年應明白網上世界是人為加工的。"},{"en":"The online world is artificial means much of what appears online is edited, selected, staged, or filtered.","zh":"the online world is artificial 指網上出現的很多東西都經過修圖、挑選、安排或濾鏡處理。"},{"en":"A perfect holiday photo may hide boredom, arguments, or editing.","zh":"一張完美旅行照片可能隱藏沉悶、爭吵或修圖。"},{"en":"If teenagers know the online world is artificial, they may compare themselves less harshly.","zh":"如果青少年知道網上世界是人為加工的，他們可能不會那麼嚴厲地比較自己。"},{"en":"This phrase helps separate digital appearance from real life.","zh":"這個短語幫助分開數碼外表和真實生活。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"feel inadequate","meaning":"覺得自己不夠好","examples":[{"en":"A teenager may feel inadequate after comparing herself with filtered images.","zh":"青少年與濾鏡圖片比較後，可能覺得自己不夠好。"},{"en":"Feel inadequate means feel not good enough or not worthy enough.","zh":"feel inadequate 指覺得自己不夠好或不夠有價值。"},{"en":"A student may feel inadequate if she compares her first draft with a published essay.","zh":"如果學生把自己的初稿與出版文章比較，可能覺得自己不夠好。"},{"en":"Beauty culture can make normal people feel inadequate for having ordinary features.","zh":"美貌文化可以令有普通特徵的正常人覺得自己不夠好。"},{"en":"This phrase describes the emotional damage caused by unfair comparison.","zh":"這個短語描述不公平比較造成的情緒傷害。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"such thinking","meaning":"這種想法","examples":[{"en":"Such thinking can lead to anxiety and social withdrawal.","zh":"這種想法可以導致焦慮和社交退縮。"},{"en":"Such thinking means this kind of thought or belief just mentioned.","zh":"such thinking 指剛才提到的那類想法或信念。"},{"en":"Such thinking can make students fear mistakes instead of learning from them.","zh":"這種想法可以令學生害怕犯錯，而不是從錯誤中學習。"},{"en":"If teenagers believe they are inadequate, such thinking may harm their mental health.","zh":"如果青少年相信自己不夠好，這種想法可能傷害心理健康。"},{"en":"This phrase connects harmful beliefs to harmful results.","zh":"這個短語把有害信念連到有害結果。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"lead to anxiety","meaning":"導致焦慮","examples":[{"en":"Constant comparison can lead to anxiety.","zh":"持續比較可以導致焦慮。"},{"en":"Lead to anxiety means cause worry, fear, or nervous tension.","zh":"lead to anxiety 指造成憂慮、恐懼或緊張。"},{"en":"Checking exam rankings every day can lead to anxiety.","zh":"每天查看考試排名可以導致焦慮。"},{"en":"Comparing faces online can lead to anxiety because the standard keeps changing.","zh":"在網上比較臉孔可以導致焦慮，因為標準不斷改變。"},{"en":"This phrase shows a cause-and-effect relationship in mental health.","zh":"這個短語顯示心理健康中的因果關係。"}],"source":"2012 Q6.pdf","sourcePage":6},{"front":"social withdrawal","meaning":"社交退縮","examples":[{"en":"Beauty pressure may lead to social withdrawal.","zh":"美貌壓力可能導致社交退縮。"},{"en":"Social withdrawal means avoiding people, activities, or social situations.","zh":"social withdrawal 指避開人群、活動或社交場合。"},{"en":"A student experiencing social withdrawal may stop eating lunch with friends.","zh":"經歷社交退縮的學生可能停止與朋友一起吃午飯。"},{"en":"If teenagers feel ugly, they may avoid photos, parties, and group activities.","zh":"如果青少年覺得自己醜，可能會避開拍照、派對和集體活動。"},{"en":"This phrase shows how inner insecurity can affect social life.","zh":"這個短語顯示內心不安全感如何影響社交生活。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"disordered eating","meaning":"飲食失調","examples":[{"en":"Unhealthy beauty standards may contribute to disordered eating.","zh":"不健康的美貌標準可能促成飲食失調。"},{"en":"Disordered eating means harmful or irregular eating behaviours that may damage health.","zh":"disordered eating 指可能傷害健康的有害或不正常飲食行為。"},{"en":"Skipping meals to look thinner can be a form of disordered eating.","zh":"為了看起來更瘦而不吃飯，可以是一種飲食失調。"},{"en":"Images of impossibly slim bodies may increase the risk of disordered eating.","zh":"瘦得不切實際的身形圖片可能增加飲食失調風險。"},{"en":"This phrase shows that beauty pressure can affect the body, not only mood.","zh":"這個短語顯示美貌壓力不只影響心情，也影響身體。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"a constant fear of being judged","meaning":"持續害怕被評價","examples":[{"en":"Some teenagers live with a constant fear of being judged.","zh":"有些青少年持續害怕被評價。"},{"en":"A constant fear of being judged means always worrying that others are criticising you.","zh":"constant fear of being judged 指一直擔心別人在批評自己。"},{"en":"A student may avoid speaking in class because of a constant fear of being judged.","zh":"學生可能因持續害怕被評價而避免在課堂發言。"},{"en":"Beauty pressure can create a constant fear that every photo or outfit will be criticised.","zh":"美貌壓力可以製造一種持續恐懼，令人覺得每張照片或每套衣服都會被批評。"},{"en":"This phrase shows how public judgement can become an everyday burden.","zh":"這個短語顯示公眾評價如何變成日常負擔。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"in this sense","meaning":"從這個意義上說","examples":[{"en":"In this sense, beauty is no longer a pleasure.","zh":"從這個意義上說，美不再是一種愉悅。"},{"en":"In this sense means from this particular point of view.","zh":"in this sense 指從這個特定角度來看。"},{"en":"In this sense, homework is not punishment but practice.","zh":"從這個意義上說，功課不是懲罰，而是練習。"},{"en":"In this sense, beauty becomes harmful when it turns into a test.","zh":"從這個意義上說，當美變成考驗時，它就有害。"},{"en":"This phrase explains exactly how the writer wants readers to understand the point.","zh":"這個短語解釋作者希望讀者如何理解觀點。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"no longer a pleasure","meaning":"不再是一種愉悅","examples":[{"en":"Beauty is no longer a pleasure when it becomes a test.","zh":"當美變成考驗時，它就不再是一種愉悅。"},{"en":"No longer a pleasure means something has stopped being enjoyable.","zh":"no longer a pleasure 指某事已不再令人享受。"},{"en":"Reading is no longer a pleasure if every book becomes an exam task.","zh":"如果每本書都變成考試任務，閱讀就不再是一種愉悅。"},{"en":"Beauty is no longer a pleasure when people feel they must pass impossible standards.","zh":"當人們覺得自己必須通過不可能的標準時，美就不再是愉悅。"},{"en":"This phrase shows how enjoyment changes into pressure.","zh":"這個短語顯示享受如何變成壓力。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"a test that nobody can pass for long","meaning":"沒有人能長久通過的考驗","examples":[{"en":"Beauty becomes a test that nobody can pass for long.","zh":"美變成一個沒有人能長久通過的考驗。"},{"en":"A test that nobody can pass for long means an impossible standard that people cannot keep meeting.","zh":"a test that nobody can pass for long 指人們無法一直達到的不可能標準。"},{"en":"If skin must always be flawless, beauty becomes a test nobody can pass for long.","zh":"如果皮膚必須永遠無瑕，美就變成沒有人能長久通過的考驗。"},{"en":"Ageing, tiredness and real life make permanent perfection impossible.","zh":"衰老、疲倦和真實生活令永久完美不可能。"},{"en":"This phrase criticises beauty standards for being unfair and endless.","zh":"這個短語批評美貌標準不公平，而且沒完沒了。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"examine every pore","meaning":"檢視每一個毛孔","examples":[{"en":"Society should not teach young people to examine every pore.","zh":"社會不應教年輕人檢視每一個毛孔。"},{"en":"Examine every pore means look too closely at tiny details of the skin.","zh":"examine every pore 指過分仔細查看皮膚上的細小細節。"},{"en":"A teenager may examine every pore after seeing close-up filtered faces online.","zh":"青少年看見網上濾鏡近照後，可能開始檢視每一個毛孔。"},{"en":"Examining every pore can turn normal skin texture into a source of worry.","zh":"檢視每一個毛孔可以把正常皮膚質感變成憂慮來源。"},{"en":"This phrase shows unhealthy self-scrutiny.","zh":"這個短語顯示不健康的自我審視。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"in effect","meaning":"實際上","examples":[{"en":"In effect, society teaches them to doubt themselves.","zh":"實際上，社會教他們懷疑自己。"},{"en":"In effect means in practice or as the real result.","zh":"in effect 指實際效果上或真正結果上。"},{"en":"The rule sounds fair, but in effect it punishes poorer students.","zh":"那條規則聽起來公平，但實際上懲罰較貧窮的學生。"},{"en":"Beauty culture may claim to inspire confidence; in effect, it creates insecurity.","zh":"美貌文化可能聲稱啟發自信；實際上，它製造不安全感。"},{"en":"This phrase reveals the real impact behind the surface message.","zh":"這個短語揭示表面訊息背後的真正影響。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"doubt every part of themselves","meaning":"懷疑自己的每一部分","examples":[{"en":"Young people may learn to doubt every part of themselves.","zh":"年輕人可能學會懷疑自己的每一部分。"},{"en":"Doubt every part of themselves means question the value or acceptability of their body, face, and identity.","zh":"doubt every part of themselves 指質疑自己的身體、臉孔和身份是否有價值或可被接受。"},{"en":"Constant criticism can make a child doubt every part of herself.","zh":"持續批評可以令孩子懷疑自己的每一部分。"},{"en":"Beauty pressure teaches teenagers to inspect their skin, eyes, weight, and smile with suspicion.","zh":"美貌壓力教青少年以懷疑眼光檢查皮膚、眼睛、體重和笑容。"},{"en":"This phrase shows deep damage to self-acceptance.","zh":"這個短語顯示對自我接納的深層傷害。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"equally worrying","meaning":"同樣令人憂慮的是","examples":[{"en":"Equally worrying is the way the beauty industry profits from insecurity.","zh":"同樣令人憂慮的是，美容業如何從不安全感中獲利。"},{"en":"Equally worrying means just as concerning as the previous problem.","zh":"equally worrying 指與前一個問題同樣令人擔心。"},{"en":"Bullying is harmful; equally worrying is the silence of bystanders.","zh":"欺凌是有害的；同樣令人憂慮的是旁觀者的沉默。"},{"en":"Beauty standards damage confidence, and equally worrying is how companies profit from that damage.","zh":"美貌標準損害自信，而同樣令人憂慮的是公司如何從這種傷害中獲利。"},{"en":"This phrase introduces another serious point in an argument.","zh":"這個短語在論述中引入另一個嚴重觀點。"}],"source":"2012 Q6.pdf","sourcePage":7},{"front":"profit from insecurity","meaning":"從不安全感中獲利","examples":[{"en":"The beauty industry often profits from insecurity.","zh":"美容業常從不安全感中獲利。"},{"en":"Profit from insecurity means make money by using people’s doubts about themselves.","zh":"profit from insecurity 指利用人們對自己的懷疑來賺錢。"},{"en":"A company profits from insecurity when it sells products by making normal skin seem ugly.","zh":"當公司透過令正常皮膚看似醜陋來售賣產品，就是從不安全感中獲利。"},{"en":"If people feel never good enough, they may keep buying more treatments.","zh":"如果人們覺得自己永遠不夠好，就可能不斷購買更多療程。"},{"en":"This phrase criticises business models built on self-doubt.","zh":"這個短語批評建立在自我懷疑上的商業模式。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"pretend to sell empowerment","meaning":"假裝出售自主力量","examples":[{"en":"The industry profits from insecurity while pretending to sell empowerment.","zh":"這個行業從不安全感中獲利，同時假裝出售自主力量。"},{"en":"Pretend to sell empowerment means claim to offer confidence or freedom while actually increasing dependence.","zh":"pretend to sell empowerment 指聲稱提供自信或自由，但實際上增加依賴。"},{"en":"An advertisement may pretend to sell empowerment by telling women they need surgery to feel strong.","zh":"廣告可能透過告訴女性需要手術才會強大，來假裝出售自主力量。"},{"en":"True empowerment should help people make free choices, not make them fear their faces.","zh":"真正的自主力量應幫助人自由選擇，而不是令他們害怕自己的臉。"},{"en":"This phrase exposes the gap between marketing language and real effect.","zh":"這個短語揭示營銷語言和真正效果之間的差距。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"cosmetic surgery","meaning":"整容手術","examples":[{"en":"Cosmetic surgery may be a legitimate choice for adults.","zh":"整容手術對成年人來說可能是合理選擇。"},{"en":"Cosmetic surgery is medical surgery done mainly to change or improve appearance.","zh":"cosmetic surgery 指主要為改變或改善外貌而進行的醫療手術。"},{"en":"Some adults choose cosmetic surgery after careful thought and medical advice.","zh":"有些成年人在仔細思考和聽取醫療意見後選擇整容手術。"},{"en":"Cosmetic surgery becomes concerning when people feel pressured or misled into it.","zh":"當人們感到被迫或被誤導去做整容手術時，它就令人憂慮。"},{"en":"This phrase allows a balanced discussion without attacking every individual choice.","zh":"這個短語容許平衡討論，而不是攻擊每個個人選擇。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"legitimate choice","meaning":"合理選擇","examples":[{"en":"Cosmetic surgery can be a legitimate choice for informed adults.","zh":"對知情成年人來說，整容手術可以是合理選擇。"},{"en":"A legitimate choice is a reasonable and acceptable decision.","zh":"legitimate choice 指合理而可接受的決定。"},{"en":"Changing jobs can be a legitimate choice if the old workplace is harmful.","zh":"如果舊工作場所有害，轉工可以是合理選擇。"},{"en":"Surgery may be legitimate when an adult understands the risks and chooses freely.","zh":"當成年人明白風險並自由選擇，手術可能是合理的。"},{"en":"This phrase prevents the argument from becoming unfairly judgemental.","zh":"這個短語防止論點變得過分批判。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"make informed decisions","meaning":"作出知情決定","examples":[{"en":"Adults should make informed decisions before cosmetic surgery.","zh":"成年人在整容手術前應作出知情決定。"},{"en":"Make informed decisions means choose after understanding the facts, risks, costs, and alternatives.","zh":"make informed decisions 指在了解事實、風險、成本和替代方案後作選擇。"},{"en":"Patients should make informed decisions before any medical procedure.","zh":"病人在任何醫療程序前都應作出知情決定。"},{"en":"A person cannot make an informed decision if advertising hides the risks.","zh":"如果廣告隱藏風險，人就無法作出知情決定。"},{"en":"This phrase stresses knowledge and freedom before serious choices.","zh":"這個短語強調在重大選擇前需要知識和自由。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"far be it from me to","meaning":"我絕不會……","examples":[{"en":"Far be it from me to condemn every person who chooses surgery.","zh":"我絕不會譴責每一個選擇手術的人。"},{"en":"Far be it from me to means I do not want to or have no right to do that thing.","zh":"far be it from me to 指我不想或無權做某事。"},{"en":"Far be it from me to judge someone’s private medical decision.","zh":"我絕不會評判別人的私人醫療決定。"},{"en":"The writer uses this phrase to avoid sounding extreme or unfair.","zh":"作者使用這個短語，以避免聽起來極端或不公平。"},{"en":"This phrase helps make criticism more balanced and respectful.","zh":"這個短語令批評更平衡和尊重。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"condemn every individual","meaning":"譴責每一個人","examples":[{"en":"It is unfair to condemn every individual who chooses cosmetic surgery.","zh":"譴責每一個選擇整容手術的人是不公平的。"},{"en":"Condemn every individual means strongly criticise each person as if they are wrong.","zh":"condemn every individual 指強烈批評每個人，彷彿他們都是錯的。"},{"en":"We should not condemn every individual who uses make-up to feel confident.","zh":"我們不應譴責每一個用化妝建立自信的人。"},{"en":"The issue is the pressure and advertising, not every person who makes a choice.","zh":"問題在於壓力和廣告，而不是每個作出選擇的人。"},{"en":"This phrase separates criticism of a system from judgement of individuals.","zh":"這個短語把對制度的批評與對個人的評判分開。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"the problem is that","meaning":"問題是","examples":[{"en":"The problem is that the industry often creates dissatisfaction.","zh":"問題是，這個行業常製造不滿。"},{"en":"The problem is that means the main issue is what follows.","zh":"the problem is that 指主要問題就是接下來的內容。"},{"en":"The problem is that students are comparing themselves with edited images.","zh":"問題是學生正在與修圖圖片比較自己。"},{"en":"The phrase helps focus the reader on the central concern.","zh":"這個短語幫助讀者集中在核心關注上。"},{"en":"In this essay, it points to the beauty industry’s role in creating insecurity.","zh":"在這篇文章中，它指出美容業在製造不安全感上的角色。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"create the very dissatisfaction it claims to cure","meaning":"製造它聲稱要治癒的不滿","examples":[{"en":"The industry often creates the very dissatisfaction it claims to cure.","zh":"這個行業常製造它聲稱要治癒的不滿。"},{"en":"This means the industry causes the insecurity it says it can fix.","zh":"這句指行業製造它聲稱能解決的不安全感。"},{"en":"A clinic may make people dislike their noses, then sell nose reshaping as the solution.","zh":"診所可能先令人不喜歡自己的鼻子，再把鼻形重塑作為解決方法出售。"},{"en":"If advertisements create dissatisfaction first, their promised cure becomes suspicious.","zh":"如果廣告先製造不滿，它承諾的治療就變得可疑。"},{"en":"This phrase exposes a cycle of problem-making and profit-making.","zh":"這個短語揭示製造問題和賺取利潤的循環。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"claim to cure","meaning":"聲稱能治癒","examples":[{"en":"The beauty industry claims to cure insecurity.","zh":"美容業聲稱能治癒不安全感。"},{"en":"Claim to cure means say that it can fix or remove a problem.","zh":"claim to cure 指聲稱可以修正或消除一個問題。"},{"en":"A product may claim to cure dull skin without showing real evidence.","zh":"一件產品可能聲稱能治癒暗沉皮膚，卻沒有展示真正證據。"},{"en":"Companies may claim to cure insecurity while making customers feel worse.","zh":"公司可能聲稱能治癒不安全感，同時令顧客感覺更差。"},{"en":"This phrase questions whether the promise is honest or exaggerated.","zh":"這個短語質疑承諾是否誠實或誇大。"}],"source":"2012 Q6.pdf","sourcePage":8},{"front":"advertise “small improvements”","meaning":"宣傳「小改善」","examples":[{"en":"Clinics advertise “small improvements” to natural faces.","zh":"診所宣傳對天然面貌作出「小改善」。"},{"en":"Advertise “small improvements” means promote minor changes as desirable or necessary.","zh":"advertise “small improvements” 指把細小改變推廣成值得做或有必要做。"},{"en":"A clinic may advertise small improvements to eyelids, noses, or jawlines.","zh":"診所可能宣傳對眼皮、鼻子或下顎線作「小改善」。"},{"en":"Calling changes “small improvements” can make procedures seem harmless.","zh":"把改變稱為「小改善」可以令療程看似無害。"},{"en":"This phrase shows how marketing softens serious decisions.","zh":"這個短語顯示營銷如何淡化嚴肅決定。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"as if","meaning":"彷彿","examples":[{"en":"Clinics advertise improvements as if natural faces were problems.","zh":"診所宣傳改善，彷彿天然面貌是問題。"},{"en":"As if means in a way that suggests something is true, even if it may not be.","zh":"as if 指以某種方式暗示某事是真的，即使它未必如此。"},{"en":"The advertisement speaks as if wrinkles are a personal failure.","zh":"廣告說話彷彿皺紋是個人失敗。"},{"en":"Beauty culture often treats normal skin as if it needs correction.","zh":"美貌文化常把正常皮膚視作彷彿需要修正。"},{"en":"This phrase helps expose a false assumption.","zh":"這個短語幫助揭露錯誤假設。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"natural faces","meaning":"天然面貌","examples":[{"en":"Natural faces should not be treated as problems.","zh":"天然面貌不應被視為問題。"},{"en":"Natural faces are real faces without surgical or heavy digital alteration.","zh":"natural faces 指未經手術或大量數碼修改的真實臉孔。"},{"en":"Natural faces may have pores, lines, freckles, and different shapes.","zh":"天然面貌可能有毛孔、紋路、雀斑和不同形狀。"},{"en":"Treating natural faces as problems can make people ashamed of being human.","zh":"把天然面貌視為問題，可以令人為自己作為人而感到羞愧。"},{"en":"This phrase supports acceptance of ordinary appearance.","zh":"這個短語支持接納普通外貌。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"problems waiting to be corrected","meaning":"等待被修正的問題","examples":[{"en":"Advertisements suggest that natural faces are problems waiting to be corrected.","zh":"廣告暗示天然面貌是等待被修正的問題。"},{"en":"Problems waiting to be corrected means flaws that supposedly need fixing.","zh":"problems waiting to be corrected 指所謂需要修正的缺陷。"},{"en":"A normal nose should not be treated as a problem waiting to be corrected.","zh":"正常鼻子不應被視為等待被修正的問題。"},{"en":"If people see their faces as problems, they may keep buying solutions.","zh":"如果人們把自己的臉視為問題，就可能不斷購買解決方案。"},{"en":"This phrase criticises beauty advertising for inventing defects.","zh":"這個短語批評美容廣告發明缺陷。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"influencers describe","meaning":"網紅形容","examples":[{"en":"Influencers describe cosmetic procedures very casually.","zh":"網紅非常隨便地形容整容療程。"},{"en":"Influencers describe means online personalities explain, present, or talk about something to followers.","zh":"influencers describe 指網上紅人向追蹤者解釋、展示或談論某事。"},{"en":"Influencers describe skincare routines in short videos every day.","zh":"網紅每天在短片中形容護膚程序。"},{"en":"When influencers describe surgery casually, followers may underestimate the risks.","zh":"當網紅隨便地形容手術，追蹤者可能低估風險。"},{"en":"This phrase shows how online voices can normalise serious choices.","zh":"這個短語顯示網上聲音如何令嚴肅選擇變得平常。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"injections","meaning":"注射療程","examples":[{"en":"Influencers may discuss injections as casually as lipstick.","zh":"網紅可能像談論唇膏一樣隨便地討論注射療程。"},{"en":"Injections are procedures in which substances are put into the body through a needle.","zh":"injections 指用針把物質注入身體的程序。"},{"en":"Cosmetic injections may be advertised as quick ways to change facial shape or wrinkles.","zh":"美容注射療程可能被宣傳為快速改變臉形或皺紋的方法。"},{"en":"Injections are still medical procedures and should not be treated like ordinary shopping.","zh":"注射仍是醫療程序，不應被視為普通購物。"},{"en":"This word shows how beauty culture can make medical actions seem casual.","zh":"這個詞顯示美貌文化如何令醫療行為看似隨便。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"eyelid surgery","meaning":"眼皮手術","examples":[{"en":"Eyelid surgery is often promoted as a simple beauty choice.","zh":"眼皮手術常被宣傳成簡單美容選擇。"},{"en":"Eyelid surgery is an operation that changes the shape or fold of the eyelids.","zh":"eyelid surgery 指改變眼皮形狀或摺痕的手術。"},{"en":"Some people consider eyelid surgery because they want a different eye shape.","zh":"有些人因想要不同眼形而考慮眼皮手術。"},{"en":"Advertising eyelid surgery as simple may hide pain, risk, and recovery time.","zh":"把眼皮手術宣傳成簡單，可能隱藏痛楚、風險和復原時間。"},{"en":"This phrase gives an example of surgery being normalised by beauty culture.","zh":"這個短語提供手術被美貌文化正常化的例子。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"nose reshaping","meaning":"鼻形重塑","examples":[{"en":"Nose reshaping is frequently advertised online.","zh":"鼻形重塑經常在網上被宣傳。"},{"en":"Nose reshaping means changing the shape of the nose through surgery or cosmetic procedures.","zh":"nose reshaping 指透過手術或美容療程改變鼻子的形狀。"},{"en":"A clinic may advertise nose reshaping by showing before-and-after photos.","zh":"診所可能透過展示前後對比照片來宣傳鼻形重塑。"},{"en":"Nose reshaping should not be treated as casual if it involves medical risk.","zh":"如果鼻形重塑涉及醫療風險，就不應被當作隨便選擇。"},{"en":"This phrase shows how one facial feature can become a commercial target.","zh":"這個短語顯示一個面部特徵如何成為商業目標。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"as casually as buying lipstick","meaning":"像買唇膏一樣隨便","examples":[{"en":"Some procedures are described as casually as buying lipstick.","zh":"有些療程被形容得像買唇膏一樣隨便。"},{"en":"As casually as buying lipstick means in a very relaxed way, as if the choice were simple and low-risk.","zh":"as casually as buying lipstick 指以非常輕鬆的方式談論，好像選擇簡單而低風險。"},{"en":"Surgery should not be discussed as casually as buying lipstick.","zh":"手術不應被討論得像買唇膏一樣隨便。"},{"en":"When influencers describe injections this way, viewers may forget they involve the body.","zh":"當網紅這樣形容注射，觀眾可能忘記它們涉及身體。"},{"en":"This phrase criticises the trivialising of serious cosmetic procedures.","zh":"這個短語批評把嚴肅美容療程瑣碎化。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"before long","meaning":"不久之後","examples":[{"en":"Before long, exceptional procedures begin to look normal.","zh":"不久之後，非比尋常的療程開始顯得正常。"},{"en":"Before long means after a short time.","zh":"before long 指過了不久。"},{"en":"Before long, the new school rule became part of daily routine.","zh":"不久之後，新的校規成為日常的一部分。"},{"en":"If surgery is advertised every day, before long it may seem ordinary.","zh":"如果手術每天被宣傳，不久之後它可能看似普通。"},{"en":"This phrase shows how repeated exposure changes people’s sense of normality.","zh":"這個短語顯示反覆接觸如何改變人們對正常的感覺。"}],"source":"2012 Q6.pdf","sourcePage":9},{"front":"what was once exceptional","meaning":"曾經非比尋常的事","examples":[{"en":"What was once exceptional may begin to look normal.","zh":"曾經非比尋常的事可能開始顯得正常。"},{"en":"What was once exceptional means something that used to be unusual or rare.","zh":"what was once exceptional 指過去不尋常或罕見的事。"},{"en":"What was once exceptional in technology may become common after a few years.","zh":"科技上曾經非比尋常的事，數年後可能變得普遍。"},{"en":"Cosmetic procedures once seen as extreme may look normal after repeated promotion.","zh":"曾被視為極端的整容療程，在反覆宣傳後可能看似正常。"},{"en":"This phrase shows how social standards can shift.","zh":"這個短語顯示社會標準如何轉變。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"begin to look normal","meaning":"開始顯得正常","examples":[{"en":"Cosmetic procedures may begin to look normal.","zh":"整容療程可能開始顯得正常。"},{"en":"Begin to look normal means start to seem ordinary, acceptable, or expected.","zh":"begin to look normal 指開始看似普通、可接受或被期待。"},{"en":"When every classmate uses filters, edited faces begin to look normal.","zh":"當每個同學都用濾鏡，修圖臉孔就開始顯得正常。"},{"en":"If surgery begins to look normal, natural features may seem less acceptable.","zh":"如果手術開始顯得正常，天然特徵可能顯得較不被接受。"},{"en":"This phrase warns that normality can be shaped by repetition.","zh":"這個短語提醒我們，正常感可以被重複塑造。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"what was once normal","meaning":"曾經正常的事","examples":[{"en":"What was once normal may begin to look unacceptable.","zh":"曾經正常的事可能開始顯得不可接受。"},{"en":"What was once normal means something that used to be accepted as ordinary.","zh":"what was once normal 指過去被接受為普通的事。"},{"en":"What was once normal, such as visible pores, may seem ugly after heavy filtering.","zh":"曾經正常的事，例如可見毛孔，在大量濾鏡後可能顯得醜陋。"},{"en":"Beauty culture can make natural ageing look unacceptable.","zh":"美貌文化可以令自然衰老看起來不可接受。"},{"en":"This phrase shows the dangerous reversal caused by unrealistic standards.","zh":"這個短語顯示不切實際標準造成的危險倒轉。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"begin to look unacceptable","meaning":"開始顯得不可接受","examples":[{"en":"Natural features may begin to look unacceptable.","zh":"天然特徵可能開始顯得不可接受。"},{"en":"Begin to look unacceptable means start to seem wrong, ugly, or not good enough.","zh":"begin to look unacceptable 指開始看似錯誤、醜陋或不夠好。"},{"en":"Normal skin texture may begin to look unacceptable after people see only filtered images.","zh":"人們只看濾鏡圖片後，正常皮膚質感可能開始顯得不可接受。"},{"en":"When natural features look unacceptable, people may feel pressured to change them.","zh":"當天然特徵顯得不可接受，人們可能感到壓力要改變它們。"},{"en":"This phrase shows how beauty culture can reduce self-acceptance.","zh":"這個短語顯示美貌文化如何削弱自我接納。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"for one thing","meaning":"一方面","examples":[{"en":"For one thing, beauty pressure creates financial pressure.","zh":"一方面，美貌壓力會造成經濟壓力。"},{"en":"For one thing means one reason or example is as follows.","zh":"for one thing 指其中一個理由或例子如下。"},{"en":"For one thing, online learning saves travel time.","zh":"一方面，網上學習節省交通時間。"},{"en":"A writer uses this phrase to introduce the first supporting reason.","zh":"作者用這個短語引入第一個支持理由。"},{"en":"In this essay, it begins the argument about money and beauty.","zh":"在這篇文章中，它開始關於金錢和美貌的論點。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"place financial pressure on","meaning":"對……造成經濟壓力","examples":[{"en":"Beauty standards place financial pressure on many people.","zh":"美貌標準對許多人造成經濟壓力。"},{"en":"Place financial pressure on someone means make someone feel money-related stress or burden.","zh":"place financial pressure on someone 指令某人感到金錢上的壓力或負擔。"},{"en":"Expensive uniforms can place financial pressure on low-income families.","zh":"昂貴校服可能對低收入家庭造成經濟壓力。"},{"en":"Beauty products and procedures place financial pressure on people who already struggle with rent.","zh":"美容產品和療程對已經為租金掙扎的人造成經濟壓力。"},{"en":"This phrase shows that appearance standards can create economic problems.","zh":"這個短語顯示外貌標準可以造成經濟問題。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"can barely afford","meaning":"勉強負擔得起","examples":[{"en":"Some people can barely afford tuition fees or rent.","zh":"有些人勉強負擔得起學費或租金。"},{"en":"Can barely afford means have only just enough money to pay for something.","zh":"can barely afford 指只有剛剛足夠的錢支付某物。"},{"en":"A family that can barely afford rent should not feel pressured to buy luxury skincare.","zh":"勉強負擔得起租金的家庭，不應感到壓力要買昂貴護膚品。"},{"en":"If students can barely afford transport, beauty spending becomes another burden.","zh":"如果學生勉強負擔得起交通費，美容開支就成為另一負擔。"},{"en":"This phrase shows how limited money makes extra pressure harmful.","zh":"這個短語顯示金錢有限如何令額外壓力變得有害。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"tuition fees","meaning":"學費","examples":[{"en":"Some young people already struggle with tuition fees.","zh":"有些年輕人已經為學費掙扎。"},{"en":"Tuition fees are money paid for classes, courses, school, or university education.","zh":"tuition fees 指為課程、學校或大學教育支付的費用。"},{"en":"Students may work part-time to pay tuition fees.","zh":"學生可能做兼職來支付學費。"},{"en":"Beauty expenses can become unfair when young people already face tuition fees.","zh":"當年輕人已面對學費時，美容開支可能變得不公平。"},{"en":"This phrase gives a concrete example of real financial responsibility.","zh":"這個短語提供真實財務責任的具體例子。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"rent","meaning":"租金","examples":[{"en":"Beauty expenses add pressure to people who can barely afford rent.","zh":"美容開支會增加勉強負擔租金的人的壓力。"},{"en":"Rent is money paid regularly to live in or use a place owned by someone else.","zh":"rent 指定期支付給別人以居住或使用地方的金錢。"},{"en":"Many young workers spend a large part of their salary on rent.","zh":"許多年輕員工把大部分薪金花在租金上。"},{"en":"If someone can barely afford rent, beauty procedures should not become another social demand.","zh":"如果有人勉強負擔租金，美容療程不應成為另一種社會要求。"},{"en":"This word shows that beauty pressure competes with basic living costs.","zh":"這個詞顯示美貌壓力與基本生活開支競爭。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"family expenses","meaning":"家庭開支","examples":[{"en":"Cosmetic procedures may add to family expenses.","zh":"整容療程可能增加家庭開支。"},{"en":"Family expenses are the costs a family must pay for daily life.","zh":"family expenses 指家庭為日常生活必須支付的費用。"},{"en":"Food, rent, transport, school fees, and medical bills are family expenses.","zh":"食物、租金、交通、學費和醫療費都是家庭開支。"},{"en":"Spending too much on beauty can increase family expenses and create conflict.","zh":"在美容上花太多錢可能增加家庭開支並造成衝突。"},{"en":"This phrase shows that beauty choices can affect more than one person.","zh":"這個短語顯示美容選擇可以影響不只一個人。"}],"source":"2012 Q6.pdf","sourcePage":10},{"front":"for another","meaning":"另一方面","examples":[{"en":"For another, beauty standards reinforce discrimination.","zh":"另一方面，美貌標準會加深歧視。"},{"en":"For another means another reason or point is as follows.","zh":"for another 指另一個理由或觀點如下。"},{"en":"For one thing, the plan is expensive; for another, it may not solve the problem.","zh":"一方面，這個計劃很昂貴；另一方面，它未必能解決問題。"},{"en":"This phrase helps organise several arguments clearly.","zh":"這個短語幫助清楚組織多個論點。"},{"en":"In this essay, it introduces discrimination as a second major concern.","zh":"在這篇文章中，它引入歧視作為第二個主要憂慮。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"reinforce discrimination against","meaning":"加深對……的歧視","examples":[{"en":"Narrow beauty standards reinforce discrimination against those who look different.","zh":"狹窄的美貌標準會加深對外貌不同者的歧視。"},{"en":"Reinforce discrimination against means make unfair treatment of a group stronger.","zh":"reinforce discrimination against 指令對某群體的不公平對待更嚴重。"},{"en":"Hiring only people with one body type can reinforce discrimination against larger applicants.","zh":"只聘請某一種身形的人，可能加深對較大身形求職者的歧視。"},{"en":"Beauty standards reinforce discrimination when they reward only certain faces and bodies.","zh":"當美貌標準只獎勵某些臉孔和身體，就是在加深歧視。"},{"en":"This phrase shows how appearance pressure becomes a fairness issue.","zh":"這個短語顯示外貌壓力如何變成公平問題。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"conform","meaning":"順從；迎合","examples":[{"en":"Some people cannot or do not wish to conform.","zh":"有些人不能或不想迎合。"},{"en":"Conform means behave or look like what society expects.","zh":"conform 指按照社會期望行事或呈現外貌。"},{"en":"A student should not be forced to conform to one narrow style of beauty.","zh":"學生不應被迫迎合一種狹窄的美貌風格。"},{"en":"People who do not conform may face unfair judgement.","zh":"不迎合的人可能面對不公平評價。"},{"en":"This word helps discuss pressure to fit a social standard.","zh":"這個詞有助討論配合社會標準的壓力。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"job applicants","meaning":"求職者","examples":[{"en":"Job applicants may feel pressure to look polished.","zh":"求職者可能感到壓力，要看起來外表得體。"},{"en":"Job applicants are people who apply for jobs.","zh":"job applicants 指申請工作的人。"},{"en":"Job applicants should be judged by skills, experience, and attitude.","zh":"求職者應按技能、經驗和態度被評價。"},{"en":"If job applicants are judged mainly by looks, capable people may be treated unfairly.","zh":"如果求職者主要按外貌被評價，有能力的人可能受到不公平對待。"},{"en":"This phrase connects beauty standards to employment.","zh":"這個短語把美貌標準連到就業。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"flight attendants","meaning":"空中服務員","examples":[{"en":"Flight attendants may face appearance-based expectations.","zh":"空中服務員可能面對基於外貌的期望。"},{"en":"Flight attendants are workers who help passengers on an aircraft.","zh":"flight attendants 指在飛機上協助乘客的工作人員。"},{"en":"Flight attendants should be valued for safety training, communication, and service.","zh":"空中服務員應因安全訓練、溝通和服務而被重視。"},{"en":"Appearance-based expectations can add unfair pressure to flight attendants.","zh":"基於外貌的期望可能給空中服務員增加不公平壓力。"},{"en":"This phrase gives an example of a job where looks may be overemphasised.","zh":"這個短語提供一個外貌可能被過度強調的職業例子。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"receptionists","meaning":"接待員","examples":[{"en":"Receptionists may feel judged by their appearance.","zh":"接待員可能覺得自己被外貌評價。"},{"en":"Receptionists are workers who greet visitors, answer calls, and provide information.","zh":"receptionists 指接待訪客、接聽電話和提供資訊的工作人員。"},{"en":"A receptionist’s patience and organisation matter more than perfect skin.","zh":"接待員的耐性和組織能力比完美皮膚更重要。"},{"en":"If receptionists feel judged by appearance, work can become stressful and unfair.","zh":"如果接待員覺得自己被外貌評價，工作可能變得有壓力和不公平。"},{"en":"This phrase shows how beauty pressure can enter everyday workplaces.","zh":"這個短語顯示美貌壓力如何進入日常工作場所。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"dating-app users","meaning":"交友應用程式用戶","examples":[{"en":"Dating-app users may feel that appearance matters too much.","zh":"交友應用程式用戶可能覺得外貌太重要。"},{"en":"Dating-app users are people who use apps to meet possible romantic partners.","zh":"dating-app users 指使用應用程式認識潛在戀愛對象的人。"},{"en":"Dating-app users often see photos before they learn about personality.","zh":"交友應用程式用戶常先看照片，才了解性格。"},{"en":"If dating apps reward only attractive photos, users may feel reduced to appearance.","zh":"如果交友程式只獎勵吸引人的照片，用戶可能覺得自己被簡化成外貌。"},{"en":"This phrase shows how digital platforms can intensify beauty pressure.","zh":"這個短語顯示數碼平台如何加劇美貌壓力。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"looking polished","meaning":"外表得體","examples":[{"en":"Some people believe looking polished matters more than being capable.","zh":"有些人相信外表得體比有能力更重要。"},{"en":"Looking polished means appearing neat, stylish, and well-prepared.","zh":"looking polished 指看起來整齊、時尚和準備充分。"},{"en":"A smart shirt and tidy hair can help someone look polished at an interview.","zh":"整潔恤衫和整齊頭髮可以令人在面試中外表得體。"},{"en":"Looking polished is useful, but it should not replace real ability.","zh":"外表得體有用，但不應取代真正能力。"},{"en":"This phrase helps distinguish presentation from competence.","zh":"這個短語幫助區分外在呈現和能力。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"matter more than being capable","meaning":"比有能力更重要","examples":[{"en":"Appearance should not matter more than being capable.","zh":"外貌不應比有能力更重要。"},{"en":"Matter more than being capable means be treated as more important than having real ability.","zh":"matter more than being capable 指被視為比真正能力更重要。"},{"en":"A nurse’s appearance should not matter more than being capable and caring.","zh":"護士的外貌不應比有能力和有愛心更重要。"},{"en":"If looks matter more than capability, society rewards the wrong thing.","zh":"如果外貌比能力更重要，社會就獎勵錯誤的東西。"},{"en":"This phrase directly criticises unfair priorities.","zh":"這個短語直接批評不公平的優次。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"reward surface over substance","meaning":"重外表多於內涵","examples":[{"en":"A city should not reward surface over substance.","zh":"一個城市不應重外表多於內涵。"},{"en":"Reward surface over substance means give more value to appearance than to real qualities.","zh":"reward surface over substance 指重視外表多於真正品質。"},{"en":"A school rewards surface over substance if it praises neat displays but ignores learning.","zh":"如果學校讚賞漂亮展示卻忽視學習，就是重外表多於內涵。"},{"en":"A workplace rewards surface over substance when it values looks more than skill.","zh":"當工作場所重視外貌多於技能，就是重外表多於內涵。"},{"en":"This phrase criticises shallow judgement.","zh":"這個短語批評膚淺判斷。"}],"source":"2012 Q6.pdf","sourcePage":11},{"front":"that is not progress","meaning":"那不是進步","examples":[{"en":"Rewarding appearance over ability is not progress.","zh":"重視外貌多於能力，那不是進步。"},{"en":"That is not progress means that change should not be seen as improvement.","zh":"that is not progress 指那種改變不應被視為改善。"},{"en":"Replacing kindness with popularity is not progress.","zh":"用受歡迎程度取代善良，那不是進步。"},{"en":"If society becomes more polished but less fair, that is not progress.","zh":"如果社會變得更光鮮但更不公平，那不是進步。"},{"en":"This phrase clearly rejects a false idea of advancement.","zh":"這個短語清楚否定一種假的進步觀。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"vanity dressed up as success","meaning":"披着成功外衣的虛榮","examples":[{"en":"It is simply vanity dressed up as success.","zh":"它只不過是披着成功外衣的虛榮。"},{"en":"Vanity dressed up as success means shallow pride in appearance being presented as achievement.","zh":"vanity dressed up as success 指把對外貌的膚淺自滿包裝成成就。"},{"en":"Buying expensive brands only to impress others can be vanity dressed up as success.","zh":"只為了令人羨慕而買名牌，可能是披着成功外衣的虛榮。"},{"en":"A culture that rewards flawless selfies may confuse vanity with real accomplishment.","zh":"獎勵完美自拍的文化，可能把虛榮與真正成就混淆。"},{"en":"This phrase exposes a false image of success.","zh":"這個短語揭穿一種假的成功形象。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"some may argue that","meaning":"有些人可能會認為","examples":[{"en":"Some may argue that caring about appearance is harmless.","zh":"有些人可能會認為注重外表是無害的。"},{"en":"Some may argue that means some people may hold the following opinion.","zh":"some may argue that 指有些人可能持有接下來的看法。"},{"en":"Some may argue that uniforms limit freedom, but others see them as fair.","zh":"有些人可能會認為校服限制自由，但另一些人視它為公平。"},{"en":"This phrase introduces an opposing view before the writer responds.","zh":"這個短語在作者回應前引入相反觀點。"},{"en":"It helps make an essay more balanced and persuasive.","zh":"它幫助文章更平衡和有說服力。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"caring about appearance","meaning":"注重外表","examples":[{"en":"Caring about appearance is not always harmful.","zh":"注重外表不一定有害。"},{"en":"Caring about appearance means paying attention to how one looks.","zh":"caring about appearance 指留意自己的外貌。"},{"en":"Caring about appearance may include washing, dressing neatly, and choosing suitable clothes.","zh":"注重外表可以包括清潔、穿着整齊和選擇合適衣服。"},{"en":"The problem begins when caring about appearance becomes fear or obsession.","zh":"當注重外表變成恐懼或沉迷時，問題才開始。"},{"en":"This phrase allows a fair distinction between grooming and pressure.","zh":"這個短語容許公平區分打扮和壓力。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"a smart outfit","meaning":"得體醒目的衣着","examples":[{"en":"A smart outfit can help someone make a good impression.","zh":"得體醒目的衣着可以幫助人留下好印象。"},{"en":"A smart outfit is clothing that looks neat, suitable, and well chosen.","zh":"smart outfit 指看起來整齊、合適和選擇得宜的衣着。"},{"en":"A job applicant may wear a smart outfit to an interview.","zh":"求職者可能穿得體醒目的衣着去面試。"},{"en":"A smart outfit can show respect for an occasion, but it cannot replace ability.","zh":"得體衣着可以顯示對場合的尊重，但不能取代能力。"},{"en":"This phrase gives a reasonable example of appearance mattering in a limited way.","zh":"這個短語提供外表在有限程度上有用的合理例子。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"clear skin","meaning":"乾淨透亮的皮膚","examples":[{"en":"Clear skin is often treated as part of a polished image.","zh":"乾淨透亮的皮膚常被視為精緻形象的一部分。"},{"en":"Clear skin means skin that looks clean, smooth, and without obvious spots.","zh":"clear skin 指看起來乾淨、平滑、沒有明顯斑點的皮膚。"},{"en":"Clear skin may be valued in beauty culture, but real skin naturally changes.","zh":"乾淨透亮的皮膚可能在美貌文化中被重視，但真實皮膚自然會變化。"},{"en":"A person with acne can still be confident, capable, and worthy.","zh":"有暗瘡的人仍可以自信、有能力和有價值。"},{"en":"This phrase shows how one beauty feature can be overvalued.","zh":"這個短語顯示一項美貌特徵如何被過度重視。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"a confident smile","meaning":"自信的笑容","examples":[{"en":"A confident smile can open doors.","zh":"自信的笑容可以帶來機會。"},{"en":"A confident smile is a smile that shows self-belief and ease.","zh":"confident smile 指顯示自信和自在的笑容。"},{"en":"A confident smile may help a student feel calmer before a presentation.","zh":"自信的笑容可能幫助學生在匯報前感到較平靜。"},{"en":"A confident smile can make communication easier, but it should not be the only thing valued.","zh":"自信的笑容可以令溝通更容易，但不應成為唯一被重視的東西。"},{"en":"This phrase shows the positive side of appearance without making it everything.","zh":"這個短語顯示外表的正面作用，但不把它變成全部。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"open doors","meaning":"帶來機會","examples":[{"en":"A confident appearance may open doors.","zh":"自信的外表可能帶來機會。"},{"en":"Open doors means create opportunities or make progress easier.","zh":"open doors 指創造機會或令進展更容易。"},{"en":"Good communication skills can open doors in many careers.","zh":"良好溝通技巧可以在許多職業中帶來機會。"},{"en":"Appearance may open doors sometimes, but character keeps them open.","zh":"外貌有時可以帶來機會，但品格才能長久保住機會。"},{"en":"This phrase explains opportunity through the image of an entrance.","zh":"這個短語用入口的畫面來解釋機會。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"I take that point","meaning":"我明白這一點","examples":[{"en":"I take that point, but it does not solve the deeper problem.","zh":"我明白這一點，但它不能解決更深層的問題。"},{"en":"I take that point means I understand and accept that argument to some extent.","zh":"I take that point 指我在某程度上理解並接受那個論點。"},{"en":"I take that point, but students still need protection from harmful advertising.","zh":"我明白這一點，但學生仍需要免受有害廣告影響。"},{"en":"This phrase lets a writer respond fairly instead of ignoring the opposing view.","zh":"這個短語讓作者公平回應，而不是無視相反觀點。"},{"en":"It helps make disagreement sound respectful and reasonable.","zh":"它令不同意聽起來尊重而合理。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"the deeper problem","meaning":"更深層的問題","examples":[{"en":"The deeper problem is society’s obsession with beauty.","zh":"更深層的問題是社會對美貌的沉迷。"},{"en":"The deeper problem means the more serious underlying issue beneath the surface.","zh":"deeper problem 指表面之下更嚴重的根本問題。"},{"en":"The deeper problem behind cheating may be fear of failure, not laziness.","zh":"作弊背後更深層的問題可能是害怕失敗，而不是懶惰。"},{"en":"In beauty culture, the deeper problem is not make-up but the belief that people are never enough.","zh":"在美貌文化中，更深層的問題不是化妝，而是人永遠不夠好的信念。"},{"en":"This phrase helps move from symptoms to causes.","zh":"這個短語幫助從症狀走向原因。"}],"source":"2012 Q6.pdf","sourcePage":12},{"front":"there is a difference between","meaning":"……和……之間有分別","examples":[{"en":"There is a difference between healthy grooming and obsessive self-reconstruction.","zh":"健康得體的打扮和令人着迷的自我改造之間有分別。"},{"en":"There is a difference between A and B means A and B should not be treated as the same.","zh":"there is a difference between A and B 指 A 和 B 不應被視為相同。"},{"en":"There is a difference between confidence and arrogance.","zh":"自信和自大之間有分別。"},{"en":"There is a difference between looking neat and believing your natural face is wrong.","zh":"外表整潔和相信自己的天然臉孔有問題之間有分別。"},{"en":"This phrase helps make a careful distinction.","zh":"這個短語幫助作出仔細區分。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"healthy grooming","meaning":"健康得體的打扮","examples":[{"en":"Healthy grooming helps people present themselves respectfully.","zh":"健康得體的打扮幫助人得體地展現自己。"},{"en":"Healthy grooming means clean, balanced, and reasonable care for appearance.","zh":"healthy grooming 指清潔、平衡而合理地照顧外表。"},{"en":"Washing your face, brushing your hair, and wearing clean clothes are healthy grooming.","zh":"洗臉、梳頭和穿乾淨衣服都是健康得體的打扮。"},{"en":"Healthy grooming supports dignity without making people hate themselves.","zh":"健康得體的打扮支持尊嚴，而不令人討厭自己。"},{"en":"This phrase separates ordinary self-care from harmful obsession.","zh":"這個短語把普通自我照顧與有害沉迷分開。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"obsessive self-reconstruction","meaning":"令人着迷的自我改造","examples":[{"en":"Obsessive self-reconstruction makes people feel never good enough.","zh":"令人着迷的自我改造令人覺得自己永遠不夠好。"},{"en":"Obsessive self-reconstruction means constantly trying to rebuild one’s appearance because of insecurity.","zh":"obsessive self-reconstruction 指因不安全感而不斷嘗試重塑外貌。"},{"en":"A teenager may fall into obsessive self-reconstruction if every photo becomes something to fix.","zh":"如果每張照片都變成需要修正的東西，青少年可能陷入令人着迷的自我改造。"},{"en":"This behaviour can make natural features seem unacceptable.","zh":"這種行為可能令天然特徵看似不可接受。"},{"en":"This phrase criticises beauty culture for turning people into endless projects.","zh":"這個短語批評美貌文化把人變成沒完沒了的改造項目。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"the former","meaning":"前者","examples":[{"en":"The former helps people present themselves respectfully.","zh":"前者幫助人得體地展現自己。"},{"en":"The former means the first of two things just mentioned.","zh":"the former 指剛提到的兩件事中的第一件。"},{"en":"Exercise and extreme dieting are different; the former supports health when done sensibly.","zh":"運動和極端節食不同；前者如合理進行，可以支持健康。"},{"en":"In this essay, the former refers to healthy grooming.","zh":"在這篇文章中，前者指健康得體的打扮。"},{"en":"This phrase helps avoid repeating a long noun phrase.","zh":"這個短語幫助避免重複很長的名詞片語。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"the latter","meaning":"後者","examples":[{"en":"The latter persuades people that they are never enough.","zh":"後者說服人們相信自己永遠不夠好。"},{"en":"The latter means the second of two things just mentioned.","zh":"the latter 指剛提到的兩件事中的第二件。"},{"en":"Confidence and arrogance are different; the latter can hurt relationships.","zh":"自信和自大不同；後者可能傷害人際關係。"},{"en":"In this essay, the latter refers to obsessive self-reconstruction.","zh":"在這篇文章中，後者指令人着迷的自我改造。"},{"en":"This phrase helps compare two ideas clearly.","zh":"這個短語幫助清楚比較兩個想法。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"present themselves respectfully","meaning":"得體地展現自己","examples":[{"en":"Healthy grooming helps people present themselves respectfully.","zh":"健康得體的打扮幫助人得體地展現自己。"},{"en":"Present themselves respectfully means appear in a way that shows care for oneself and the occasion.","zh":"present themselves respectfully 指以顯示自重和尊重場合的方式出現。"},{"en":"Students present themselves respectfully when they wear clean clothes to a ceremony.","zh":"學生穿乾淨衣服出席典禮，就是得體地展現自己。"},{"en":"Presenting yourself respectfully does not require changing your natural features.","zh":"得體地展現自己不需要改變天然特徵。"},{"en":"This phrase shows a healthy purpose for grooming.","zh":"這個短語顯示打扮的健康目的。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"persuade someone that","meaning":"說服某人相信","examples":[{"en":"Obsessive beauty culture persuades people that they are never enough.","zh":"令人沉迷的美貌文化說服人們相信自己永遠不夠好。"},{"en":"Persuade someone that means make someone believe a particular idea.","zh":"persuade someone that 指令某人相信某個想法。"},{"en":"Advertisements may persuade teenagers that normal skin needs fixing.","zh":"廣告可能說服青少年相信正常皮膚需要修正。"},{"en":"Good education can persuade students that edited images should be questioned.","zh":"良好教育可以說服學生相信修圖圖片應被質疑。"},{"en":"This phrase shows how messages shape belief.","zh":"這個短語顯示訊息如何塑造信念。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"never enough","meaning":"永遠不夠好","examples":[{"en":"The beauty industry can make people feel they are never enough.","zh":"美容業可以令人覺得自己永遠不夠好。"},{"en":"Never enough means always lacking something and never fully acceptable.","zh":"never enough 指總是缺少某些東西，永遠不能完全被接受。"},{"en":"A student may feel never enough if every grade below perfect is criticised.","zh":"如果每個非滿分成績都被批評，學生可能覺得自己永遠不夠好。"},{"en":"Beauty culture makes people feel never enough by constantly selling improvements.","zh":"美貌文化透過不斷售賣改善方法，令人覺得自己永遠不夠好。"},{"en":"This phrase captures the emotional trap of endless comparison.","zh":"這個短語概括無盡比較的情緒陷阱。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"just because…does not mean…","meaning":"只是因為……並不代表……","examples":[{"en":"Just because beauty brings advantages does not mean society should magnify them.","zh":"只是因為美貌帶來優勢，並不代表社會應放大那些優勢。"},{"en":"Just because A does not mean B means A may be true, but B does not automatically follow.","zh":"just because A does not mean B 指 A 可能是真的，但 B 不會自動成立。"},{"en":"Just because a video is popular does not mean it is reliable.","zh":"只是因為影片受歡迎，並不代表它可靠。"},{"en":"Just because appearance can help in some situations does not mean it should dominate society.","zh":"只是因為外貌在某些情況下有幫助，並不代表它應支配社會。"},{"en":"This structure helps challenge weak reasoning.","zh":"這個結構幫助挑戰薄弱推理。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"bring advantages","meaning":"帶來優勢","examples":[{"en":"Beauty can bring advantages in some situations.","zh":"美貌在某些情況下可以帶來優勢。"},{"en":"Bring advantages means provide benefits, opportunities, or helpful effects.","zh":"bring advantages 指提供好處、機會或有利影響。"},{"en":"Good communication skills can bring advantages in interviews.","zh":"良好溝通技巧可以在面試中帶來優勢。"},{"en":"Beauty may bring advantages, but society should not let it outweigh character.","zh":"美貌可能帶來優勢，但社會不應讓它壓過品格。"},{"en":"This phrase allows the writer to admit a limited truth.","zh":"這個短語讓作者承認有限度的事實。"}],"source":"2012 Q6.pdf","sourcePage":13},{"front":"magnify those advantages","meaning":"放大那些優勢","examples":[{"en":"Society should not magnify those advantages too much.","zh":"社會不應過度放大那些優勢。"},{"en":"Magnify those advantages means make those benefits larger, stronger, or more important than they should be.","zh":"magnify those advantages 指把那些好處變得比應有程度更大、更強或更重要。"},{"en":"Schools should not magnify the advantages of wealthy students by giving them more attention.","zh":"學校不應透過給予更多注意來放大家境富裕學生的優勢。"},{"en":"If society magnifies beauty advantages, people may believe looks matter more than ability.","zh":"如果社會放大美貌優勢，人們可能相信外貌比能力更重要。"},{"en":"This phrase criticises making an unfair benefit even bigger.","zh":"這個短語批評把不公平優勢變得更大。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"character, kindness and competence","meaning":"品格、善良和能力","examples":[{"en":"Character, kindness and competence should not be pushed aside.","zh":"品格、善良和能力不應被擠到一旁。"},{"en":"Character, kindness and competence mean moral quality, care for others, and real ability.","zh":"character, kindness and competence 指道德品質、關心他人和真正能力。"},{"en":"A good nurse needs character, kindness and competence more than a flawless image.","zh":"好護士需要品格、善良和能力，多於完美形象。"},{"en":"A society that values these qualities will judge people more fairly.","zh":"重視這些品質的社會會更公平地評價人。"},{"en":"This phrase names the deeper qualities that should matter more than appearance.","zh":"這個短語指出比外貌更應重要的深層品質。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"be pushed aside","meaning":"被擠到一旁","examples":[{"en":"Important qualities may be pushed aside by beauty obsession.","zh":"重要品質可能被美貌沉迷擠到一旁。"},{"en":"Be pushed aside means be ignored, neglected, or treated as less important.","zh":"be pushed aside 指被忽視、被忽略或被視為較不重要。"},{"en":"In a noisy discussion, quiet but useful ideas may be pushed aside.","zh":"在嘈吵討論中，安靜但有用的想法可能被擠到一旁。"},{"en":"When beauty is overvalued, kindness and competence may be pushed aside.","zh":"當美貌被過度重視，善良和能力可能被擠到一旁。"},{"en":"This phrase shows how one value can unfairly replace another.","zh":"這個短語顯示一種價值如何不公平地取代另一種。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"after all","meaning":"畢竟","examples":[{"en":"After all, a patient teacher contributes more than a flawless image.","zh":"畢竟，一位有耐性的老師比完美形象貢獻更多。"},{"en":"After all means when we remember the most important reason or truth.","zh":"after all 指當我們記起最重要的原因或真相時。"},{"en":"You should rest tonight; after all, health matters more than one extra hour of study.","zh":"你今晚應該休息；畢竟，健康比多溫習一小時更重要。"},{"en":"After all, society needs caring people more than perfect photographs.","zh":"畢竟，社會需要有愛心的人，多於完美照片。"},{"en":"This phrase introduces a final reminder or deeper truth.","zh":"這個短語引入最後提醒或更深層真相。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"a friendly nurse","meaning":"友善的護士","examples":[{"en":"A friendly nurse contributes greatly to society.","zh":"友善的護士對社會貢獻很大。"},{"en":"A friendly nurse is a healthcare worker who treats patients with warmth and care.","zh":"friendly nurse 指以溫暖和關懷對待病人的醫護人員。"},{"en":"A friendly nurse can comfort a frightened child before treatment.","zh":"友善的護士可以在治療前安慰受驚的孩子。"},{"en":"A friendly nurse’s kindness matters more than whether she fits a beauty ideal.","zh":"友善護士的善良比她是否符合美貌理想更重要。"},{"en":"This phrase gives a concrete example of valuable human qualities.","zh":"這個短語提供有價值人類品質的具體例子。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"an honest salesperson","meaning":"誠實的銷售員","examples":[{"en":"An honest salesperson is more valuable than a flawless online image.","zh":"誠實的銷售員比完美的網上形象更有價值。"},{"en":"An honest salesperson is a seller who tells customers the truth and does not mislead them.","zh":"honest salesperson 指告訴顧客真相、不誤導人的銷售員。"},{"en":"An honest salesperson may warn a customer that a product is unnecessary.","zh":"誠實的銷售員可能提醒顧客某件產品並不必要。"},{"en":"Honesty in sales protects people from wasting money.","zh":"銷售中的誠實能保護人們免於浪費金錢。"},{"en":"This phrase shows that trust matters more than perfect appearance.","zh":"這個短語顯示信任比完美外貌更重要。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"a patient teacher","meaning":"有耐性的老師","examples":[{"en":"A patient teacher contributes far more than someone who only looks perfect.","zh":"有耐性的老師比只看起來完美的人貢獻大得多。"},{"en":"A patient teacher is a teacher who remains calm and supportive while students learn slowly.","zh":"patient teacher 指在學生慢慢學習時仍保持冷靜和支持的老師。"},{"en":"A patient teacher explains the same grammar point again without humiliating students.","zh":"有耐性的老師會再次解釋同一個文法重點，而不羞辱學生。"},{"en":"Students remember patient teachers because they help confidence grow.","zh":"學生會記得有耐性的老師，因為他們幫助自信成長。"},{"en":"This phrase shows a social contribution that beauty cannot replace.","zh":"這個短語顯示美貌無法取代的社會貢獻。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"contribute far more to","meaning":"對……貢獻大得多","examples":[{"en":"Kind people contribute far more to Hong Kong than flawless images do.","zh":"善良的人對香港的貢獻比完美形象大得多。"},{"en":"Contribute far more to means give much greater help or value to something.","zh":"contribute far more to 指對某事提供更大幫助或價值。"},{"en":"Volunteers contribute far more to a community than empty slogans do.","zh":"義工對社區的貢獻比空洞口號大得多。"},{"en":"Nurses, teachers and honest workers contribute far more to society than filtered faces.","zh":"護士、老師和誠實員工對社會的貢獻比濾鏡臉孔大得多。"},{"en":"This phrase helps compare real service with shallow appearance.","zh":"這個短語幫助比較真正服務與膚淺外貌。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"only achievement","meaning":"唯一成就","examples":[{"en":"Looking flawless online should not be someone’s only achievement.","zh":"在網上看起來完美無瑕不應是某人的唯一成就。"},{"en":"Only achievement means the single thing a person is praised for or proud of.","zh":"only achievement 指一個人唯一被讚賞或引以為傲的事情。"},{"en":"A student’s only achievement should not be having the most likes on a photo.","zh":"學生的唯一成就不應是照片得到最多讚好。"},{"en":"If looking perfect becomes someone’s only achievement, deeper talents may be ignored.","zh":"如果看起來完美成為某人的唯一成就，更深層的才華可能被忽略。"},{"en":"This phrase warns against reducing life to appearance.","zh":"這個短語警告不要把人生簡化成外貌。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"looking flawless online","meaning":"在網上看起來完美無瑕","examples":[{"en":"Looking flawless online should not be valued above character.","zh":"在網上看起來完美無瑕不應比品格更受重視。"},{"en":"Looking flawless online means appearing perfect in photos or videos posted on the internet.","zh":"looking flawless online 指在發布到網上的照片或影片中看起來完美。"},{"en":"A person may look flawless online because of lighting, filters, and careful angles.","zh":"一個人可能因燈光、濾鏡和精心角度而在網上看起來完美無瑕。"},{"en":"Looking flawless online does not prove kindness, honesty, or competence.","zh":"在網上看起來完美無瑕不能證明善良、誠實或能力。"},{"en":"This phrase criticises digital perfection as a poor measure of value.","zh":"這個短語批評數碼完美不是衡量價值的好標準。"}],"source":"2012 Q6.pdf","sourcePage":14},{"front":"Handsome is as handsome does","meaning":"行為美才是真正美","examples":[{"en":"Handsome is as handsome does.","zh":"行為美才是真正美。"},{"en":"Handsome is as handsome does means real beauty is shown by good actions, not only appearance.","zh":"Handsome is as handsome does 指真正的美由好行為顯示，而不只是外表。"},{"en":"A polite student proves that handsome is as handsome does when he helps a classmate quietly.","zh":"有禮貌的學生安靜幫助同學時，就證明行為美才是真正美。"},{"en":"A person with perfect looks but cruel behaviour is not truly admirable.","zh":"外貌完美但行為殘忍的人，並不真正值得欣賞。"},{"en":"This saying supports the argument that character matters more than looks.","zh":"這句諺語支持品格比外貌更重要的論點。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"the time has come for","meaning":"是時候……","examples":[{"en":"The time has come for schools, parents, advertisers and the media to restore balance.","zh":"是時候讓學校、家長、廣告商和媒體恢復平衡。"},{"en":"The time has come for means it is now necessary or appropriate for someone to act.","zh":"the time has come for 指現在已需要或適合由某人行動。"},{"en":"The time has come for schools to teach students about edited images.","zh":"是時候讓學校教學生認識修圖圖片。"},{"en":"This phrase gives urgency to a call for change.","zh":"這個短語為改變呼籲加入迫切感。"},{"en":"In the essay, it moves from criticism to solutions.","zh":"在文章中，它把批評轉向解決方法。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"restore balance","meaning":"恢復平衡","examples":[{"en":"Society needs to restore balance in how it views beauty.","zh":"社會需要在看待美貌方面恢復平衡。"},{"en":"Restore balance means bring back a fair and healthy relationship between different values.","zh":"restore balance 指重新建立不同價值之間公平而健康的關係。"},{"en":"A school can restore balance by praising creativity as well as exam results.","zh":"學校同時讚賞創意和考試成績，就可以恢復平衡。"},{"en":"Society restores balance when it values appearance, character and ability in proper proportion.","zh":"當社會以適當比例重視外貌、品格和能力，就是恢復平衡。"},{"en":"This phrase suggests correction, not rejection of beauty entirely.","zh":"這個短語暗示修正，而不是完全拒絕美。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"media-literacy education","meaning":"媒體素養教育","examples":[{"en":"Schools should include media-literacy education.","zh":"學校應包括媒體素養教育。"},{"en":"Media-literacy education teaches students to understand, question and evaluate media messages.","zh":"media-literacy education 教學生理解、質疑和評估媒體訊息。"},{"en":"Media-literacy education can help students recognise edited photos and hidden advertising.","zh":"媒體素養教育可以幫助學生辨認修圖照片和隱藏廣告。"},{"en":"Without media literacy, teenagers may believe every beauty image they see online.","zh":"沒有媒體素養，青少年可能相信他們在網上看見的每張美貌圖片。"},{"en":"This phrase offers a practical solution to beauty pressure.","zh":"這個短語提供應對美貌壓力的實際方法。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"identify edited images","meaning":"辨認經修圖的圖片","examples":[{"en":"Students should learn to identify edited images.","zh":"學生應學會辨認經修圖的圖片。"},{"en":"Identify edited images means recognise photos that have been changed digitally.","zh":"identify edited images 指認出被數碼修改過的照片。"},{"en":"Students can identify edited images by looking for unnatural skin, strange shadows, or distorted backgrounds.","zh":"學生可以透過觀察不自然皮膚、奇怪陰影或扭曲背景，辨認經修圖的圖片。"},{"en":"Learning to identify edited images can reduce unfair comparison.","zh":"學會辨認修圖圖片可以減少不公平比較。"},{"en":"This phrase gives students a practical skill for online life.","zh":"這個短語給學生一項網上生活的實用技能。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"manipulative advertising","meaning":"具操控性的廣告","examples":[{"en":"Students should learn to recognise manipulative advertising.","zh":"學生應學會辨認具操控性的廣告。"},{"en":"Manipulative advertising is advertising that pressures or tricks people into feeling they need something.","zh":"manipulative advertising 指透過施壓或欺騙令人覺得自己需要某物的廣告。"},{"en":"An advertisement that makes normal skin seem shameful may be manipulative.","zh":"令正常皮膚看似可恥的廣告可能是具操控性的。"},{"en":"Recognising manipulative advertising helps young people protect their confidence and money.","zh":"辨認具操控性的廣告能幫助年輕人保護自信和金錢。"},{"en":"This phrase shows that some marketing is not neutral information.","zh":"這個短語顯示有些營銷並不是中立資訊。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"praise effort, courage and compassion","meaning":"讚賞努力、勇氣和同情心","examples":[{"en":"Parents should praise effort, courage and compassion more often.","zh":"家長應更常讚賞努力、勇氣和同情心。"},{"en":"Praise effort, courage and compassion means show approval for hard work, bravery and care for others.","zh":"praise effort, courage and compassion 指肯定辛勤付出、勇敢和關心他人。"},{"en":"Parents praise effort when they notice a child practising despite difficulty.","zh":"當家長注意到孩子雖然困難仍繼續練習，就是在讚賞努力。"},{"en":"Praising courage and compassion teaches children that character matters more than looks.","zh":"讚賞勇氣和同情心會教孩子品格比外貌重要。"},{"en":"This phrase gives families a positive way to resist beauty obsession.","zh":"這個短語給家庭一種抵抗美貌沉迷的正面方法。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"more often than appearance","meaning":"比外貌更常","examples":[{"en":"Parents should praise character more often than appearance.","zh":"家長應比外貌更常讚賞品格。"},{"en":"More often than appearance means more frequently than comments about looks.","zh":"more often than appearance 指比評論外貌更頻密。"},{"en":"A parent can praise kindness more often than appearance by noticing helpful actions.","zh":"家長可以透過留意孩子幫助別人的行動，比外貌更常讚賞善良。"},{"en":"If children hear praise for effort more often than appearance, they may build healthier self-worth.","zh":"如果孩子聽到努力比外貌更常被讚賞，他們可能建立更健康的自我價值。"},{"en":"This phrase suggests a simple change in everyday language.","zh":"這個短語建議日常語言中的簡單改變。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"newspapers such as","meaning":"例如……這類報章","examples":[{"en":"Newspapers such as the Hong Kong Express can help restore balance.","zh":"例如 Hong Kong Express 這類報章可以幫助恢復平衡。"},{"en":"Newspapers such as means newspapers like the example being named.","zh":"newspapers such as 指像所列例子那樣的報章。"},{"en":"Newspapers such as local community papers can report ordinary people’s stories.","zh":"例如本地社區報這類報章，可以報道普通人的故事。"},{"en":"Newspapers such as the Hong Kong Express can challenge narrow beauty ideals through better features.","zh":"例如 Hong Kong Express 這類報章，可以透過更好的專題報道挑戰狹窄美貌理想。"},{"en":"This phrase introduces a specific example of a wider group.","zh":"這個短語引入較大類別中的具體例子。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"feature people of different ages, sizes and appearances","meaning":"報道不同年齡、身形和外貌的人","examples":[{"en":"Newspapers can feature people of different ages, sizes and appearances.","zh":"報章可以報道不同年齡、身形和外貌的人。"},{"en":"Feature people of different ages, sizes and appearances means show and report on a wider range of real people.","zh":"feature people of different ages, sizes and appearances 指展示和報道更多不同類型的真人。"},{"en":"A magazine can feature older workers, larger bodies and people with natural skin.","zh":"雜誌可以報道年長工作者、較大身形的人和有天然皮膚的人。"},{"en":"Featuring diverse people helps readers see beauty and value beyond one narrow ideal.","zh":"報道多元的人能幫助讀者看見狹窄理想以外的美和價值。"},{"en":"This phrase suggests a practical role for the media.","zh":"這個短語提出媒體的實際角色。"}],"source":"2012 Q6.pdf","sourcePage":15},{"front":"fit a narrow commercial ideal","meaning":"符合狹窄的商業理想","examples":[{"en":"The media should not show only people who fit a narrow commercial ideal.","zh":"媒體不應只展示符合狹窄商業理想的人。"},{"en":"Fit a narrow commercial ideal means match a limited image that businesses find profitable.","zh":"fit a narrow commercial ideal 指符合商業上有利可圖的有限形象。"},{"en":"Models with only one body type may fit a narrow commercial ideal, but they do not represent everyone.","zh":"只有一種身形的模特兒可能符合狹窄商業理想，但不能代表所有人。"},{"en":"Showing only this ideal can make ordinary people feel invisible.","zh":"只展示這種理想可能令普通人覺得自己被隱形。"},{"en":"This phrase criticises beauty standards shaped by profit.","zh":"這個短語批評由利潤塑造的美貌標準。"}],"source":"2012 Q6.pdf","sourcePage":16},{"front":"Beauty is not the enemy; obsession is","meaning":"美不是敵人，沉迷才是","examples":[{"en":"Beauty is not the enemy; obsession is.","zh":"美不是敵人，沉迷才是。"},{"en":"Beauty is not the enemy; obsession is means beauty itself is not harmful, but extreme fixation on it is.","zh":"Beauty is not the enemy; obsession is 指美本身無害，有害的是對它的極端執着。"},{"en":"Caring about clothes is not the enemy; believing clothes decide your worth is.","zh":"注重衣着不是敵人；相信衣着決定你的價值才是。"},{"en":"This sentence separates healthy appreciation from unhealthy control.","zh":"這句話把健康欣賞與不健康控制分開。"},{"en":"It gives the essay a balanced and memorable message.","zh":"它給文章一個平衡而易記的訊息。"}],"source":"2012 Q6.pdf","sourcePage":16},{"front":"look in the mirror","meaning":"照鏡","examples":[{"en":"Young people should look in the mirror and see a person.","zh":"年輕人照鏡時應看見一個人。"},{"en":"Look in the mirror means look at one’s reflection in a mirror.","zh":"look in the mirror 指看鏡中的自己。"},{"en":"A teenager may look in the mirror before school and worry about her skin.","zh":"青少年上學前可能照鏡，並擔心自己的皮膚。"},{"en":"Looking in the mirror should not become an exercise in self-criticism.","zh":"照鏡不應變成自我批評的練習。"},{"en":"This phrase connects daily self-image with deeper self-worth.","zh":"這個短語把日常自我形象與更深層的自我價值連起來。"}],"source":"2012 Q6.pdf","sourcePage":16},{"front":"see a person, not a product","meaning":"看見一個人，而不是一件產品","examples":[{"en":"Young people should see a person, not a product.","zh":"年輕人應看見一個人，而不是一件產品。"},{"en":"See a person, not a product means recognise oneself as a human being, not something to be packaged, improved and sold.","zh":"see a person, not a product 指把自己看成一個人，而不是需要包裝、改善和出售的東西。"},{"en":"A student should see a person in the mirror, not a list of defects to fix.","zh":"學生應在鏡中看見一個人，而不是一串需要修正的缺陷。"},{"en":"Beauty advertising can make people treat themselves like products for display.","zh":"美容廣告可以令人把自己當成展示用的產品。"},{"en":"This phrase gives the essay a strong final image of dignity.","zh":"這個短語給文章一個有尊嚴的有力結尾畫面。"}],"source":"2012 Q6.pdf","sourcePage":16},{"front":"Yours faithfully","meaning":"此致敬禮","examples":[{"en":"A formal letter can end with “Yours faithfully”.","zh":"正式信件可以用「此致敬禮」作結。"},{"en":"Yours faithfully is a polite closing used in formal letters, especially when the recipient is not personally known.","zh":"Yours faithfully 是正式信件中的禮貌結尾，尤其用於不熟識收信人時。"},{"en":"A letter beginning “Dear Editor” may end with “Yours faithfully”.","zh":"以 Dear Editor 開頭的信件可以用 Yours faithfully 結尾。"},{"en":"Using “Yours faithfully” helps the writer sound respectful and formal.","zh":"使用 Yours faithfully 幫助作者顯得尊重而正式。"},{"en":"This phrase completes the structure of a formal letter to a newspaper.","zh":"這個短語完成寫給報章的正式信件結構。"}],"source":"2012 Q6.pdf","sourcePage":16}],"dse/writing/part-b/2012/Q7":[{"front":"the key that wasn’t his","meaning":"不屬於他的鑰匙","examples":[{"en":"The key in Aaron’s pocket was never his.","zh":"Aaron 口袋裏的鑰匙從來不屬於他。"},{"en":"The key that wasn’t his means an object Aaron carried but did not truly own.","zh":"The key that wasn’t his 指 Aaron 帶着但並不真正擁有的物件。"},{"en":"A borrowed key can make someone look rich, powerful or mysterious even when it is not theirs.","zh":"一條借來的鑰匙可以令人看似富有、有權力或神秘，即使它並不屬於那人。"},{"en":"In the story, the key creates misunderstanding because Mary thinks it belongs to Aaron.","zh":"在故事中，鑰匙造成誤會，因為 Mary 以為它屬於 Aaron。"},{"en":"This phrase suggests appearance can mislead people.","zh":"這個短語暗示外表可能令人誤判。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"Hardly had… when…","meaning":"剛……就……","examples":[{"en":"Hardly had the rain stopped when the Peninsula Hotel began to shine.","zh":"雨剛停，半島酒店就開始發亮。"},{"en":"Hardly had… when… means one thing happened immediately after another.","zh":"Hardly had… when… 指一件事剛發生，另一件事就立刻發生。"},{"en":"Hardly had I opened the door when the phone started ringing.","zh":"我剛打開門，電話就響起。"},{"en":"Writers use this structure to make events feel sudden and closely connected.","zh":"作者用這個結構令事件感覺突然，而且緊密相連。"},{"en":"This phrase is formal and dramatic, often used in storytelling.","zh":"這個短語較正式和戲劇化，常用於敘事。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"the rain stopped","meaning":"雨停了","examples":[{"en":"The rain had just stopped outside the hotel.","zh":"酒店外的雨剛停。"},{"en":"The rain stopped means rain was falling before, but it ended.","zh":"The rain stopped 指之前正在下雨，但現在已結束。"},{"en":"When the rain stopped, people folded their umbrellas and walked faster.","zh":"雨停後，人們收起雨傘並走得更快。"},{"en":"After rain stops, streets may shine with water and reflected lights.","zh":"雨停後，街道可能因積水和反光而發亮。"},{"en":"This phrase often sets the mood after bad weather.","zh":"這個短語常用來營造壞天氣過後的氣氛。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"the Peninsula Hotel","meaning":"半島酒店","examples":[{"en":"The Peninsula Hotel began to shine after the rain.","zh":"雨後，半島酒店開始發亮。"},{"en":"The Peninsula Hotel is a famous hotel in Tsim Sha Tsui.","zh":"The Peninsula Hotel 是尖沙咀一間著名酒店。"},{"en":"In the story, the Peninsula Hotel creates an image of wealth and elegance.","zh":"在故事中，半島酒店營造出富貴和優雅的形象。"},{"en":"A luxury hotel can make a scene feel important or mysterious.","zh":"豪華酒店可以令場景感覺重要或神秘。"},{"en":"This phrase gives the story a recognisable Hong Kong setting.","zh":"這個短語為故事提供可辨認的香港背景。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"begin to shine","meaning":"開始發亮","examples":[{"en":"The hotel began to shine after the rain stopped.","zh":"雨停後，酒店開始發亮。"},{"en":"Begin to shine means start looking bright because of light or reflection.","zh":"Begin to shine 指因光線或反射而開始變亮。"},{"en":"The wet road began to shine when the streetlights came on.","zh":"街燈亮起時，濕漉漉的馬路開始發亮。"},{"en":"A building can begin to shine after rain because water reflects the city lights.","zh":"建築物在雨後可能開始發亮，因為水面反射城市燈光。"},{"en":"This phrase creates a visual change in a scene.","zh":"這個短語在場景中製造視覺變化。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"walk by","meaning":"走過","examples":[{"en":"I was walking by the Peninsula Hotel in Tsim Sha Tsui.","zh":"我正走過尖沙咀的半島酒店。"},{"en":"Walk by means pass a place on foot without necessarily entering it.","zh":"Walk by 指步行經過某地方，不一定進入。"},{"en":"I walked by the bakery and smelled fresh bread.","zh":"我走過麵包店時聞到新鮮麵包香。"},{"en":"A person may notice something unusual while walking by a familiar place.","zh":"一個人走過熟悉地方時，可能注意到不尋常的事。"},{"en":"This phrase describes casual movement past a location.","zh":"這個短語描述隨意經過某地的動作。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"Tsim Sha Tsui","meaning":"尖沙咀","examples":[{"en":"The Peninsula Hotel is in Tsim Sha Tsui.","zh":"半島酒店位於尖沙咀。"},{"en":"Tsim Sha Tsui is a busy district in Hong Kong known for hotels, shops and harbour views.","zh":"Tsim Sha Tsui 是香港一個繁忙地區，以酒店、商店和海港景色聞名。"},{"en":"A story set in Tsim Sha Tsui may feel crowded, bright and urban.","zh":"以尖沙咀為背景的故事可能感覺擠迫、明亮而都市化。"},{"en":"Tourists often pass through Tsim Sha Tsui when visiting the harbour.","zh":"遊客參觀海港時常會經過尖沙咀。"},{"en":"This phrase gives a clear local setting.","zh":"這個短語提供清楚的本地背景。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"bag biting into my shoulder","meaning":"袋子勒得肩膀發痛","examples":[{"en":"My bag was biting into my shoulder as I walked.","zh":"我走路時，袋子勒得肩膀發痛。"},{"en":"A bag biting into my shoulder means the strap pressed painfully into my shoulder.","zh":"A bag biting into my shoulder 指袋帶壓進肩膀，令人感到疼痛。"},{"en":"A heavy school bag can bite into a student’s shoulder after a long walk.","zh":"沉重書包在長時間步行後，可以勒得學生肩膀發痛。"},{"en":"This phrase shows physical discomfort through a vivid image.","zh":"這個短語用生動畫面表現身體不適。"},{"en":"It helps readers feel the narrator’s tiredness.","zh":"它幫助讀者感受敘事者的疲累。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"smell of wet traffic","meaning":"雨後車流的氣味","examples":[{"en":"The smell of wet traffic rose from Salisbury Road.","zh":"雨後車流的氣味從梳士巴利道升起。"},{"en":"The smell of wet traffic means the damp smell of cars, road water and city air after rain.","zh":"The smell of wet traffic 指雨後汽車、路面積水和城市空氣混合的潮濕氣味。"},{"en":"After heavy rain, the smell of wet traffic filled the busy street.","zh":"大雨過後，雨後車流的氣味充滿繁忙街道。"},{"en":"This phrase mixes weather and city life into one sensory detail.","zh":"這個短語把天氣和城市生活混合成一個感官細節。"},{"en":"It helps create a realistic urban atmosphere.","zh":"它幫助營造真實的都市氣氛。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"rise from","meaning":"從……升起","examples":[{"en":"The smell of wet traffic rose from Salisbury Road.","zh":"雨後車流的氣味從梳士巴利道升起。"},{"en":"Rise from means move upward or seem to come up from a place.","zh":"Rise from 指向上移動，或像是從某地方冒出來。"},{"en":"Steam rose from the bowl of noodles.","zh":"熱氣從那碗麵升起。"},{"en":"A smell can rise from a wet street after rain.","zh":"雨後，氣味可以從濕街道升起。"},{"en":"This phrase helps describe movement from a lower place into the air.","zh":"這個短語幫助描述由較低處進入空氣中的動作。"}],"source":"2012 Q7.pdf","sourcePage":1},{"front":"Salisbury Road","meaning":"梳士巴利道","examples":[{"en":"The smell of wet traffic rose from Salisbury Road.","zh":"雨後車流的氣味從梳士巴利道升起。"},{"en":"Salisbury Road is a road in Tsim Sha Tsui used here to create a local street setting.","zh":"Salisbury Road 是尖沙咀一條道路，在這裏用來營造本地街道背景。"},{"en":"Naming Salisbury Road makes the scene feel specific rather than vague.","zh":"提到梳士巴利道令場景具體，而不是模糊。"},{"en":"A busy road after rain can carry the sounds and smells of city traffic.","zh":"雨後繁忙道路可以帶有城市車流的聲音和氣味。"},{"en":"This phrase anchors the story in Hong Kong.","zh":"這個短語把故事固定在香港背景中。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"silver sports car","meaning":"銀色跑車","examples":[{"en":"A silver sports car slid towards the hotel entrance.","zh":"一輛銀色跑車滑向酒店入口。"},{"en":"A silver sports car is a fast, stylish car with a shiny silver colour.","zh":"A silver sports car 指一輛銀色、快速而有型的跑車。"},{"en":"A silver sports car outside a luxury hotel can suggest wealth and mystery.","zh":"停在豪華酒店外的銀色跑車可以暗示財富和神秘感。"},{"en":"Mary misunderstands Aaron partly because the car looks expensive.","zh":"Mary 誤會 Aaron，部分原因是那輛車看起來很昂貴。"},{"en":"This phrase creates a strong visual impression.","zh":"這個短語製造強烈視覺印象。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"slide towards","meaning":"滑向","examples":[{"en":"The sports car slid towards the entrance.","zh":"跑車滑向入口。"},{"en":"Slide towards means move smoothly and quietly in the direction of something.","zh":"Slide towards 指平穩而安靜地朝某方向移動。"},{"en":"The taxi slid towards the kerb after the rain.","zh":"雨後，的士滑向路邊。"},{"en":"A car sliding towards a hotel entrance can look controlled and elegant.","zh":"一輛車滑向酒店入口，可以顯得受控而優雅。"},{"en":"This phrase makes movement feel smooth rather than rough.","zh":"這個短語令動作感覺順滑，而不是粗糙。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"hotel entrance","meaning":"酒店入口","examples":[{"en":"The sports car stopped near the hotel entrance.","zh":"跑車停在酒店入口附近。"},{"en":"A hotel entrance is the front area where guests arrive and leave.","zh":"Hotel entrance 指客人進出酒店的正門區域。"},{"en":"Expensive cars often stop at a hotel entrance to drop off guests.","zh":"昂貴汽車常在酒店入口停下來讓客人下車。"},{"en":"The hotel entrance becomes important because Mary first sees Aaron there.","zh":"酒店入口很重要，因為 Mary 在那裏第一次看見 Aaron。"},{"en":"This phrase identifies the doorway to a public setting.","zh":"這個短語指出公共場景的入口。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"engine purring","meaning":"引擎低聲嗚嗚作響","examples":[{"en":"The car’s engine was purring softly.","zh":"那輛車的引擎正低聲嗚嗚作響。"},{"en":"Engine purring means the engine made a low, smooth and steady sound.","zh":"Engine purring 指引擎發出低沉、順滑而穩定的聲音。"},{"en":"A luxury car may sit outside a hotel with its engine purring quietly.","zh":"豪華車可能停在酒店外，引擎安靜地嗚嗚作響。"},{"en":"This sound can make the car seem alive and powerful.","zh":"這種聲音可以令汽車像有生命和力量。"},{"en":"This phrase gives the scene sound as well as movement.","zh":"這個短語為場景加入聲音和動感。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"like an animal that knew people were watching","meaning":"像一隻知道有人注視的動物","examples":[{"en":"The engine purred like an animal that knew people were watching.","zh":"引擎低聲嗚嗚作響，像一隻知道有人注視的動物。"},{"en":"This comparison makes the car seem proud, alive and aware of attention.","zh":"這個比較令汽車顯得自豪、有生命，並意識到別人的注視。"},{"en":"A sports car outside a hotel can look like an animal waiting to be admired.","zh":"停在酒店外的跑車可以像一隻等待被欣賞的動物。"},{"en":"The image suggests glamour, but also something slightly suspicious.","zh":"這個畫面暗示光鮮，也帶一點可疑感。"},{"en":"This phrase uses metaphor to make the car feel dramatic.","zh":"這個短語用比喻令汽車更有戲劇感。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"at the wheel","meaning":"在駕駛座上","examples":[{"en":"At the wheel was my brother, Aaron.","zh":"在駕駛座上的人是我的哥哥 Aaron。"},{"en":"At the wheel means sitting in the driver’s seat and controlling the vehicle.","zh":"At the wheel 指坐在駕駛座上並控制車輛。"},{"en":"Mary was shocked because Aaron was at the wheel of an expensive car.","zh":"Mary 很震驚，因為 Aaron 坐在昂貴跑車的駕駛座上。"},{"en":"Seeing someone at the wheel tells us who is driving.","zh":"看見某人在駕駛座上，就知道誰在開車。"},{"en":"This phrase is common when describing drivers.","zh":"這個短語常用於描述司機。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"for a moment","meaning":"有一刻","examples":[{"en":"For a moment, I simply stared.","zh":"有一刻，我只是呆望着。"},{"en":"For a moment means for a short time.","zh":"For a moment 指短暫一段時間。"},{"en":"For a moment, Mary could not understand what she was seeing.","zh":"有一刻，Mary 無法理解自己看見的是甚麼。"},{"en":"A shocking sight can stop someone’s thoughts for a moment.","zh":"震驚的畫面可以令人的思緒停頓一刻。"},{"en":"This phrase helps slow down a scene briefly.","zh":"這個短語幫助短暫放慢場景。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"simply stared","meaning":"只是呆望着","examples":[{"en":"I simply stared when I saw Aaron in the sports car.","zh":"看見 Aaron 在跑車裏時，我只是呆望着。"},{"en":"Simply stared means looked silently and fixedly because of surprise or confusion.","zh":"Simply stared 指因驚訝或困惑而靜靜地盯着看。"},{"en":"The student simply stared when he saw his quiet teacher on television.","zh":"那學生看見安靜的老師出現在電視上時，只是呆望着。"},{"en":"Mary stared because Aaron’s appearance did not match what she knew about him.","zh":"Mary 呆望着，因為 Aaron 的樣子與她認識的他不相符。"},{"en":"This phrase shows shock without needing many words.","zh":"這個短語不用很多文字也能表現震驚。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"the last time we had spoken","meaning":"我們上次說話時","examples":[{"en":"The last time we had spoken, Aaron was looking for work.","zh":"我們上次說話時，Aaron 正在找工作。"},{"en":"The last time we had spoken means during our most recent conversation before this moment.","zh":"The last time we had spoken 指在這一刻之前我們最近一次交談時。"},{"en":"The last time we had spoken, he seemed tired and worried about money.","zh":"我們上次說話時，他看起來疲累，並擔心金錢。"},{"en":"This phrase helps compare the past Aaron with the Aaron Mary sees now.","zh":"這個短語幫助比較過去的 Aaron 和 Mary 現在看到的 Aaron。"},{"en":"It is useful when showing a sudden change.","zh":"它適合用來顯示突然轉變。"}],"source":"2012 Q7.pdf","sourcePage":2},{"front":"kitchen table","meaning":"廚房餐枱","examples":[{"en":"Aaron had been sitting at our kitchen table.","zh":"Aaron 當時坐在我們的廚房餐枱旁。"},{"en":"A kitchen table is a table used for meals, family talk or daily tasks at home.","zh":"Kitchen table 指家中用來吃飯、交談或處理日常事情的桌子。"},{"en":"Aaron sat at the kitchen table circling job advertisements.","zh":"Aaron 坐在廚房餐枱旁圈起招聘廣告。"},{"en":"The kitchen table makes the memory feel ordinary and family-based.","zh":"廚房餐枱令回憶感覺平凡並帶有家庭氣息。"},{"en":"This phrase contrasts home life with the luxury hotel scene.","zh":"這個短語把家中生活與豪華酒店場景作對比。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"faded T-shirt","meaning":"褪色T恤","examples":[{"en":"He had been wearing a faded T-shirt.","zh":"他當時穿着一件褪色 T 恤。"},{"en":"A faded T-shirt is a shirt whose colour has become pale from age or washing.","zh":"Faded T-shirt 指因時間或清洗而顏色變淡的 T 恤。"},{"en":"A faded T-shirt can make someone look ordinary or financially struggling.","zh":"褪色 T 恤可以令人看起來平凡或經濟拮据。"},{"en":"Aaron’s faded T-shirt contrasts with the dark suit he wears later.","zh":"Aaron 的褪色 T 恤與他後來穿的深色西裝形成對比。"},{"en":"This phrase helps show the difference between past appearance and present appearance.","zh":"這個短語幫助顯示過去外表和現在外表的差異。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"circle job advertisements","meaning":"圈起招聘廣告","examples":[{"en":"Aaron was circling job advertisements with a pencil.","zh":"Aaron 用鉛筆圈起招聘廣告。"},{"en":"Circle job advertisements means mark job notices to show interest in applying.","zh":"Circle job advertisements 指標記招聘通知，表示有興趣申請。"},{"en":"A job seeker may circle advertisements in the newspaper before making calls.","zh":"求職者可能先在報紙上圈起招聘廣告，再打電話查詢。"},{"en":"This action shows Aaron was actively looking for work.","zh":"這個動作顯示 Aaron 正積極找工作。"},{"en":"The phrase gives a concrete image of unemployment and hope.","zh":"這個短語給出失業與希望的具體畫面。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"job advertisements","meaning":"招聘廣告","examples":[{"en":"Aaron was looking through job advertisements.","zh":"Aaron 正在翻看招聘廣告。"},{"en":"Job advertisements are notices that describe available jobs and how to apply.","zh":"Job advertisements 指描述空缺職位和申請方法的通知。"},{"en":"Job advertisements may list duties, working hours and salary.","zh":"招聘廣告可能列出職責、工作時間和薪金。"},{"en":"Reading job advertisements can be stressful when a person urgently needs work.","zh":"當一個人急需工作，閱讀招聘廣告可能很有壓力。"},{"en":"This phrase is useful in work and employment contexts.","zh":"這個短語適合用於工作和就業語境。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"I’ll take anything","meaning":"甚麼工作都願意做","examples":[{"en":"Aaron said he would take any job.","zh":"Aaron 說他甚麼工作都願意做。"},{"en":"I’ll take anything means I am willing to accept almost any opportunity because I need one badly.","zh":"I’ll take anything 指因為非常需要機會，所以幾乎任何工作都願意接受。"},{"en":"A job seeker may say “I’ll take anything” after many rejections.","zh":"求職者在多次被拒後，可能會說「甚麼工作都願意做」。"},{"en":"This phrase shows desperation more than confidence.","zh":"這個短語顯示絕望多於自信。"},{"en":"It helps readers understand Aaron’s difficult situation.","zh":"它幫助讀者理解 Aaron 的困境。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"office assistant","meaning":"辦公室助理","examples":[{"en":"Aaron was willing to work as an office assistant.","zh":"Aaron 願意做辦公室助理。"},{"en":"An office assistant is a worker who helps with basic office tasks.","zh":"Office assistant 指協助處理基本辦公室工作的員工。"},{"en":"Office assistants may answer phones, file documents and support staff.","zh":"辦公室助理可能接聽電話、整理文件和支援員工。"},{"en":"Aaron mentioning this job shows he was open to ordinary work.","zh":"Aaron 提到這份工作，顯示他願意接受普通工作。"},{"en":"This phrase describes an entry-level workplace role.","zh":"這個短語描述入門級辦公室職位。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"delivery worker","meaning":"送貨員","examples":[{"en":"He was also willing to work as a delivery worker.","zh":"他也願意做送貨員。"},{"en":"A delivery worker is a person who brings goods, food or packages to people.","zh":"Delivery worker 指把貨物、食物或包裹送到別人手上的人。"},{"en":"Delivery workers often need to travel quickly and follow addresses carefully.","zh":"送貨員常需要快速行動並仔細跟從地址。"},{"en":"Aaron being willing to do delivery work shows he was not proud or picky.","zh":"Aaron 願意做送貨工作，顯示他並不驕傲或挑剔。"},{"en":"This phrase describes a practical service job.","zh":"這個短語描述實用服務工作。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"dark suit","meaning":"深色西裝","examples":[{"en":"Now he was wearing a dark suit.","zh":"現在他穿着一套深色西裝。"},{"en":"A dark suit is formal clothing, often worn for work or important occasions.","zh":"Dark suit 指正式服裝，常用於工作或重要場合。"},{"en":"Aaron’s dark suit makes him look more successful than Mary expected.","zh":"Aaron 的深色西裝令他看起來比 Mary 預期更成功。"},{"en":"Clothing can change how people judge someone before they know the truth.","zh":"衣着可以在人們知道真相前改變他們的判斷。"},{"en":"This phrase helps create the story’s misunderstanding.","zh":"這個短語幫助製造故事中的誤會。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"cost more than","meaning":"比……更貴","examples":[{"en":"The car probably cost more than our flat.","zh":"那輛車大概比我們的單位更貴。"},{"en":"Cost more than means be more expensive than something else.","zh":"Cost more than 指比另一樣東西更昂貴。"},{"en":"A luxury watch may cost more than a student’s yearly tuition.","zh":"一隻名貴手錶可能比學生一年的學費更貴。"},{"en":"Mary thinks the car cost more than their flat, so she becomes suspicious.","zh":"Mary 覺得那輛車比他們的單位更貴，所以變得懷疑。"},{"en":"This phrase compares value or price.","zh":"這個短語比較價值或價格。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"before I could","meaning":"還未及我……","examples":[{"en":"Before I could call his name, a woman stepped forward.","zh":"還未及我叫他的名字，一名女子已走上前。"},{"en":"Before I could means something happened before I had time to act.","zh":"Before I could 指在我有時間行動之前，另一件事已發生。"},{"en":"Before I could answer, the teacher asked another question.","zh":"還未及我回答，老師又問了另一個問題。"},{"en":"This phrase creates quick movement in a story.","zh":"這個短語在故事中製造快速推進。"},{"en":"It shows the narrator was interrupted by another event.","zh":"它顯示敘事者被另一事件打斷。"}],"source":"2012 Q7.pdf","sourcePage":3},{"front":"call his name","meaning":"叫他的名字","examples":[{"en":"I wanted to call Aaron’s name.","zh":"我想叫 Aaron 的名字。"},{"en":"Call his name means say someone’s name loudly enough to get their attention.","zh":"Call his name 指大聲說出某人的名字，以引起他的注意。"},{"en":"Mary wanted to call Aaron’s name when she saw him in the car.","zh":"Mary 看見 Aaron 在車裏時，想叫他的名字。"},{"en":"Calling someone’s name can start a conversation or stop them from leaving.","zh":"叫某人的名字可以開始對話，或阻止他離開。"},{"en":"This phrase describes a simple attempt to reach someone.","zh":"這個短語描述接觸某人的簡單嘗試。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"cream coat","meaning":"米色外套","examples":[{"en":"A woman in a cream coat handed Aaron an envelope.","zh":"一名穿米色外套的女子遞給 Aaron 一個信封。"},{"en":"A cream coat is a light beige or pale yellowish coat.","zh":"Cream coat 指淺米色或淡黃色的外套。"},{"en":"The cream coat makes the woman look neat and formal.","zh":"米色外套令那名女子看起來整潔而正式。"},{"en":"Clothing details help readers remember characters quickly.","zh":"服裝細節幫助讀者快速記住角色。"},{"en":"This phrase gives a soft visual detail in a tense scene.","zh":"這個短語在緊張場景中加入柔和視覺細節。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"step forward","meaning":"走上前","examples":[{"en":"The woman stepped forward and handed him an envelope.","zh":"那名女子走上前，遞給他一個信封。"},{"en":"Step forward means move closer, often to speak or give something.","zh":"Step forward 指走近一些，通常是為了說話或交出東西。"},{"en":"A volunteer stepped forward to help the lost child.","zh":"一名義工走上前幫助迷路的孩子。"},{"en":"In the story, the woman steps forward before Mary can call Aaron.","zh":"在故事中，那名女子在 Mary 叫 Aaron 前走上前。"},{"en":"This phrase shows purposeful movement.","zh":"這個短語顯示有目的的動作。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"hand someone an envelope","meaning":"遞給某人一個信封","examples":[{"en":"The woman handed Aaron a white envelope.","zh":"那名女子遞給 Aaron 一個白色信封。"},{"en":"Hand someone an envelope means give an envelope directly to that person.","zh":"Hand someone an envelope 指直接把信封交給某人。"},{"en":"A secretary may hand someone an envelope containing important forms.","zh":"秘書可能遞給某人一個裝有重要表格的信封。"},{"en":"Mary becomes suspicious because the envelope looks secretive.","zh":"Mary 變得懷疑，因為信封看起來很神秘。"},{"en":"This phrase describes a small action that can carry plot importance.","zh":"這個短語描述一個細小但可推動情節的動作。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"white envelope","meaning":"白色信封","examples":[{"en":"Aaron received a white envelope from the woman.","zh":"Aaron 從那名女子手中收到一個白色信封。"},{"en":"A white envelope is a plain paper cover used to hold letters or documents.","zh":"White envelope 指用來放信件或文件的普通白色紙封套。"},{"en":"A white envelope can look ordinary, but it may contain important papers.","zh":"白色信封看似普通，但可能裝着重要文件。"},{"en":"In the story, the envelope later turns out to contain medical consent forms.","zh":"在故事中，信封後來證實裝着醫療同意書。"},{"en":"This phrase helps create mystery before the truth is revealed.","zh":"這個短語在真相揭示前製造神秘感。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"look around quickly","meaning":"迅速四處張望","examples":[{"en":"Aaron looked around quickly before driving away.","zh":"Aaron 開車離開前迅速四處張望。"},{"en":"Look around quickly means glance in several directions in a short time.","zh":"Look around quickly 指在短時間內看向幾個方向。"},{"en":"A nervous person may look around quickly before entering a building.","zh":"緊張的人進入大樓前可能會迅速四處張望。"},{"en":"Aaron’s quick look makes Mary think he is hiding something.","zh":"Aaron 迅速張望，令 Mary 以為他在隱瞞事情。"},{"en":"This phrase suggests anxiety or caution.","zh":"這個短語暗示焦慮或小心。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"not proudly, but nervously","meaning":"不是驕傲地，而是緊張地","examples":[{"en":"Aaron looked around not proudly, but nervously.","zh":"Aaron 四處張望時不是驕傲地，而是緊張地。"},{"en":"Not proudly, but nervously corrects one possible interpretation and gives the real feeling.","zh":"Not proudly, but nervously 修正一個可能解讀，並指出真正感覺。"},{"en":"He did not smile proudly in the expensive car; he looked nervous and careful.","zh":"他在昂貴車裏不是驕傲地微笑，而是緊張而小心。"},{"en":"This structure helps show that appearances can be misleading.","zh":"這個結構幫助顯示外表可能令人誤解。"},{"en":"It contrasts confidence with fear.","zh":"它把自信和恐懼作對比。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"drive off","meaning":"開車離開","examples":[{"en":"Aaron drove off after receiving the envelope.","zh":"Aaron 收到信封後開車離開。"},{"en":"Drive off means leave a place by driving a vehicle.","zh":"Drive off 指駕車離開某地方。"},{"en":"The taxi drove off as soon as the passenger closed the door.","zh":"乘客關上車門後，的士立即開車離開。"},{"en":"Aaron’s driving off makes Mary feel she must follow him quickly.","zh":"Aaron 開車離開令 Mary 覺得自己必須馬上跟着他。"},{"en":"This phrase describes movement away from a scene.","zh":"這個短語描述離開場景的動作。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"something felt wrong","meaning":"感覺有點不對勁","examples":[{"en":"Something felt wrong when I saw Aaron drive away.","zh":"我看見 Aaron 開車離開時，感覺有點不對勁。"},{"en":"Something felt wrong means the situation seemed strange or worrying, even without proof.","zh":"Something felt wrong 指情況看似奇怪或令人擔心，即使沒有證據。"},{"en":"Mary felt something was wrong because Aaron looked nervous in an expensive car.","zh":"Mary 覺得不對勁，因為 Aaron 坐在昂貴車裏卻顯得緊張。"},{"en":"Sometimes small details create suspicion before facts are clear.","zh":"有時細小細節會在事實清楚前製造懷疑。"},{"en":"This phrase shows instinctive unease.","zh":"這個短語顯示本能上的不安。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"should have gone home","meaning":"本應回家","examples":[{"en":"I should have gone home instead of following him.","zh":"我本應回家，而不是跟着他。"},{"en":"Should have gone home means it would have been wiser or better to return home.","zh":"Should have gone home 指回家本來會更明智或更好。"},{"en":"I should have gone home, but worry made me follow the car.","zh":"我本應回家，但擔心令我跟着那輛車。"},{"en":"This phrase shows regret about a past choice.","zh":"這個短語顯示對過去選擇的後悔。"},{"en":"It helps the narrator admit she may have acted wrongly.","zh":"它幫助敘事者承認自己可能做錯了。"}],"source":"2012 Q7.pdf","sourcePage":4},{"front":"jump into the first taxi","meaning":"跳上第一輛的士","examples":[{"en":"I jumped into the first taxi I saw.","zh":"我跳上看見的第一輛的士。"},{"en":"Jump into the first taxi means quickly get into the nearest available taxi.","zh":"Jump into the first taxi 指迅速坐進最近可用的的士。"},{"en":"A worried sister might jump into the first taxi to follow her brother.","zh":"擔心的妹妹可能會跳上第一輛的士去跟蹤哥哥。"},{"en":"This action shows urgency rather than careful planning.","zh":"這個動作顯示急切，而不是仔細計劃。"},{"en":"This phrase creates fast movement in the story.","zh":"這個短語在故事中製造快速動作。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"point at","meaning":"指向","examples":[{"en":"I pointed at the sports car disappearing down the road.","zh":"我指向那輛沿路遠去的跑車。"},{"en":"Point at means direct a finger toward someone or something.","zh":"Point at 指用手指指向某人或某物。"},{"en":"Mary pointed at the car so the taxi driver would know which one to follow.","zh":"Mary 指向那輛車，好讓的士司機知道要跟哪一輛。"},{"en":"Pointing can be faster than explaining when something is moving away.","zh":"當某物正在離開時，指着它可能比解釋更快。"},{"en":"This phrase describes a direct physical signal.","zh":"這個短語描述直接的身體訊號。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"disappear down the road","meaning":"沿路遠去","examples":[{"en":"The sports car was disappearing down the road.","zh":"那輛跑車正沿路遠去。"},{"en":"Disappear down the road means move farther along the road until it is almost out of sight.","zh":"Disappear down the road 指沿着道路越走越遠，直到幾乎看不見。"},{"en":"The bus disappeared down the road before I reached the stop.","zh":"我到達車站前，巴士已沿路遠去。"},{"en":"A car disappearing down the road creates urgency for anyone trying to follow it.","zh":"如果有人想跟蹤，一輛車沿路遠去會製造急迫感。"},{"en":"This phrase shows distance increasing.","zh":"這個短語顯示距離正在增加。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"follow that car","meaning":"跟着那輛車","examples":[{"en":"I asked the taxi driver to follow that car.","zh":"我叫的士司機跟着那輛車。"},{"en":"Follow that car means drive behind a particular car and keep it in sight.","zh":"Follow that car 指駕車跟在某輛車後面，並保持看得見它。"},{"en":"The line sounds dramatic because it is often heard in detective stories.","zh":"這句話聽起來戲劇化，因為常見於偵探故事。"},{"en":"Mary says it because she urgently wants to know where Aaron is going.","zh":"Mary 這樣說，是因為她急切想知道 Aaron 去哪裏。"},{"en":"This phrase shows suspicion and action.","zh":"這個短語顯示懷疑和行動。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"glance at someone in the mirror","meaning":"從倒後鏡瞥某人","examples":[{"en":"The driver glanced at me in the mirror.","zh":"司機從倒後鏡瞥了我一眼。"},{"en":"Glance at someone in the mirror means look briefly at someone through the rear-view mirror.","zh":"Glance at someone in the mirror 指透過倒後鏡短暫看某人。"},{"en":"A taxi driver may glance at a passenger in the mirror when a request sounds strange.","zh":"當乘客要求聽起來奇怪，的士司機可能從倒後鏡瞥他一眼。"},{"en":"The driver’s glance shows he is curious or doubtful.","zh":"司機的一瞥顯示他好奇或懷疑。"},{"en":"This phrase gives a small detail of reaction.","zh":"這個短語給出反應上的小細節。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"movie scene","meaning":"電影場面","examples":[{"en":"The driver asked whether it was a movie scene.","zh":"司機問這是不是電影場面。"},{"en":"A movie scene is a part of a film, often dramatic or unrealistic.","zh":"Movie scene 指電影中的一幕，常帶戲劇性或不太現實。"},{"en":"Asking to follow a car can sound like a movie scene.","zh":"要求跟蹤一輛車聽起來可以像電影場面。"},{"en":"The driver’s comment shows how unusual Mary’s request sounds.","zh":"司機的說法顯示 Mary 的要求聽起來多麼不尋常。"},{"en":"This phrase adds humour to a tense moment.","zh":"這個短語為緊張時刻加入幽默。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"family problem","meaning":"家庭問題","examples":[{"en":"I told the driver it was a family problem.","zh":"我告訴司機這是家庭問題。"},{"en":"A family problem is a difficulty or conflict involving relatives.","zh":"Family problem 指涉及親人的困難或衝突。"},{"en":"Mary calls it a family problem because Aaron is her brother.","zh":"Mary 說這是家庭問題，因為 Aaron 是她哥哥。"},{"en":"Family problems can make people act quickly and emotionally.","zh":"家庭問題可以令人快速而情緒化地行動。"},{"en":"This phrase explains the personal reason behind Mary’s behaviour.","zh":"這個短語解釋 Mary 行為背後的個人原因。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"mutter","meaning":"低聲咕噥","examples":[{"en":"I muttered that it was a family problem.","zh":"我低聲咕噥說那是家庭問題。"},{"en":"Mutter means speak quietly and not very clearly, often because of embarrassment or worry.","zh":"Mutter 指低聲而不太清楚地說話，通常因為尷尬或擔心。"},{"en":"Mary muttered because she did not want to explain everything to the driver.","zh":"Mary 低聲咕噥，因為她不想向司機解釋所有事情。"},{"en":"People may mutter when they feel uncomfortable or ashamed.","zh":"人感到不舒服或羞愧時，可能會低聲咕噥。"},{"en":"This word shows how a line is spoken.","zh":"這個詞顯示說話方式。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"No sooner had… than…","meaning":"一……就……","examples":[{"en":"No sooner had we turned past the harbour than my mind began to betray Aaron.","zh":"我們一駛過海旁，我的思緒就開始背叛 Aaron。"},{"en":"No sooner had… than… means one thing happened immediately after another.","zh":"No sooner had… than… 指一件事剛發生，另一件事就立刻發生。"},{"en":"No sooner had I sat down than the alarm rang.","zh":"我一坐下，警鐘就響起。"},{"en":"This structure is formal and dramatic, often used to show sudden change.","zh":"這個結構正式而戲劇化，常用來顯示突然轉變。"},{"en":"In the story, it shows suspicion entering Mary’s mind quickly.","zh":"在故事中，它顯示懷疑很快進入 Mary 的腦海。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"turn past the harbour","meaning":"駛過海旁","examples":[{"en":"The taxi turned past the harbour.","zh":"的士駛過海旁。"},{"en":"Turn past the harbour means drive around or beyond the harbour area.","zh":"Turn past the harbour 指車輛轉彎並駛過海港一帶。"},{"en":"The taxi turned past the harbour while Mary kept watching the sports car.","zh":"的士駛過海旁時，Mary 一直望着那輛跑車。"},{"en":"Passing the harbour gives the chase a clear Hong Kong setting.","zh":"駛過海旁令追蹤場景有清楚的香港背景。"},{"en":"This phrase describes movement through the city.","zh":"這個短語描述在城市中移動。"}],"source":"2012 Q7.pdf","sourcePage":5},{"front":"my mind began to betray","meaning":"我的思緒開始背叛","examples":[{"en":"My mind began to betray Aaron with suspicious thoughts.","zh":"我的思緒開始以懷疑的想法背叛 Aaron。"},{"en":"My mind began to betray means my thoughts started turning against someone I cared about.","zh":"My mind began to betray 指我的想法開始轉而懷疑自己關心的人。"},{"en":"Mary loved Aaron, but worry made her imagine the worst.","zh":"Mary 愛 Aaron，但擔憂令她想像最壞情況。"},{"en":"Suspicion can feel like betrayal when it targets someone close.","zh":"當懷疑指向親近的人，它可以像一種背叛。"},{"en":"This phrase shows inner conflict.","zh":"這個短語顯示內心衝突。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"rich stranger","meaning":"有錢陌生人","examples":[{"en":"I wondered whether Aaron was working for some rich stranger.","zh":"我 wondered Aaron 是否在替某個有錢陌生人工作。"},{"en":"A rich stranger is an unknown wealthy person.","zh":"Rich stranger 指一個不認識的富有人士。"},{"en":"Mary imagines a rich stranger because the car and hotel look expensive.","zh":"Mary 想像有錢陌生人，是因為那輛車和酒店看起來昂貴。"},{"en":"In stories, rich strangers can suggest opportunity, danger or secrecy.","zh":"在故事中，有錢陌生人可以暗示機會、危險或秘密。"},{"en":"This phrase shows how Mary fills gaps with suspicion.","zh":"這個短語顯示 Mary 如何用懷疑填補未知。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"borrow money","meaning":"借錢","examples":[{"en":"I wondered whether Aaron had borrowed money.","zh":"我 wondered Aaron 是否借了錢。"},{"en":"Borrow money means take money from someone with the promise to return it later.","zh":"Borrow money 指向別人取得金錢，並承諾之後歸還。"},{"en":"A person without work may borrow money to pay rent or bills.","zh":"沒有工作的人可能借錢交租或付帳單。"},{"en":"Mary worries Aaron may have borrowed money because he looked desperate before.","zh":"Mary 擔心 Aaron 借了錢，因為他以前看起來很絕望。"},{"en":"This phrase connects financial pressure with concern.","zh":"這個短語把金錢壓力和擔憂連接起來。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"worse still","meaning":"更糟的是","examples":[{"en":"Worse still, I wondered whether he was involved in something illegal.","zh":"更糟的是，我 wondered 他是否捲入了非法事情。"},{"en":"Worse still introduces an even more worrying possibility.","zh":"Worse still 用來引出更加令人擔心的可能性。"},{"en":"He was late; worse still, nobody could reach him by phone.","zh":"他遲到了；更糟的是，沒有人能打通他的電話。"},{"en":"Writers use this phrase to move from bad to more serious.","zh":"作者用這個短語由壞情況推進到更嚴重情況。"},{"en":"This phrase shows Mary’s fear becoming darker.","zh":"這個短語顯示 Mary 的恐懼變得更陰暗。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"become involved in","meaning":"捲入","examples":[{"en":"I feared Aaron had become involved in something illegal.","zh":"我害怕 Aaron 已捲入非法事情。"},{"en":"Become involved in means start taking part in a situation or activity.","zh":"Become involved in 指開始參與某情況或活動。"},{"en":"A young person may become involved in trouble if they follow the wrong crowd.","zh":"年輕人如果跟錯人，可能會捲入麻煩。"},{"en":"Mary fears Aaron became involved in danger because his behaviour looks secretive.","zh":"Mary 害怕 Aaron 捲入危險，因為他的行為看起來神秘。"},{"en":"This phrase can describe joining something good or bad, depending on context.","zh":"這個短語可描述參與好事或壞事，視乎語境。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"something illegal","meaning":"非法事情","examples":[{"en":"I worried that Aaron had become involved in something illegal.","zh":"我擔心 Aaron 捲入了非法事情。"},{"en":"Something illegal means an action or activity that breaks the law.","zh":"Something illegal 指違反法律的行動或活動。"},{"en":"Stealing, fraud or dangerous driving can be something illegal.","zh":"偷竊、詐騙或危險駕駛都可以是非法事情。"},{"en":"Mary’s fear is unfair, but it grows because she lacks the truth.","zh":"Mary 的擔心並不公平，但因為她不知道真相，所以恐懼加深。"},{"en":"This phrase creates serious suspicion in the story.","zh":"這個短語在故事中製造嚴重懷疑。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"hate myself for thinking it","meaning":"恨自己竟然這樣想","examples":[{"en":"I hated myself for thinking badly of Aaron.","zh":"我恨自己竟然把 Aaron 想得那麼壞。"},{"en":"Hate myself for thinking it means feel guilty or ashamed for having a certain thought.","zh":"Hate myself for thinking it 指因有某種想法而感到內疚或羞愧。"},{"en":"Mary hated herself for suspecting her brother without proof.","zh":"Mary 因沒有證據就懷疑哥哥而恨自己。"},{"en":"People may feel guilty when fear makes them judge someone they love.","zh":"當恐懼令人評判自己所愛的人，人們可能會感到內疚。"},{"en":"This phrase shows emotional conflict and regret.","zh":"這個短語顯示情感衝突和後悔。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"worry has a cruel imagination","meaning":"擔憂會令人想像殘酷的可能","examples":[{"en":"Worry has a cruel imagination when we fear the worst.","zh":"當我們害怕最壞情況時，擔憂會令人想像殘酷的可能。"},{"en":"This means worry can make people imagine painful or unfair possibilities.","zh":"這句話指擔憂會令人想像痛苦或不公平的可能性。"},{"en":"When a friend does not reply, worry may imagine rejection or danger.","zh":"當朋友沒有回覆，擔憂可能會想像被拒絕或發生危險。"},{"en":"Mary’s worry invents harsh explanations before she knows the truth.","zh":"Mary 的擔憂在她知道真相前，先編造嚴 harsh 的解釋。"},{"en":"This phrase personifies worry as something unkind and creative.","zh":"這個短語把擔憂擬人化成不仁慈但有想像力的東西。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"finally stopped outside","meaning":"最後停在……外面","examples":[{"en":"The car finally stopped outside a hospital in Kowloon.","zh":"那輛車最後停在九龍一間醫院外面。"},{"en":"Finally stopped outside means at last came to a stop near the front of a place.","zh":"Finally stopped outside 指最後在某地方外面停下。"},{"en":"The taxi finally stopped outside the school after a long ride.","zh":"經過長途車程，的士最後停在學校外面。"},{"en":"In the story, the car stopping outside a hospital changes Mary’s expectations.","zh":"在故事中，車停在醫院外改變了 Mary 的預期。"},{"en":"This phrase marks the end of the chase.","zh":"這個短語標示追蹤的結束。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"hospital in Kowloon","meaning":"九龍一間醫院","examples":[{"en":"The car stopped outside a hospital in Kowloon.","zh":"那輛車停在九龍一間醫院外。"},{"en":"A hospital in Kowloon means a medical centre located on the Kowloon side of Hong Kong.","zh":"Hospital in Kowloon 指位於香港九龍區的醫療中心。"},{"en":"Seeing the car at a hospital suggests the journey may involve illness or care.","zh":"看見車停在醫院，暗示這趟旅程可能涉及疾病或照顧。"},{"en":"The hospital setting shifts the story from suspicion to compassion.","zh":"醫院場景把故事由懷疑轉向同情。"},{"en":"This phrase gives the mystery a new emotional direction.","zh":"這個短語為謎團帶來新的情感方向。"}],"source":"2012 Q7.pdf","sourcePage":6},{"front":"hurry to","meaning":"匆忙走向","examples":[{"en":"Aaron hurried to the passenger side.","zh":"Aaron 匆忙走向乘客座一邊。"},{"en":"Hurry to means move quickly toward a place or person.","zh":"Hurry to 指快速走向某地方或某人。"},{"en":"A nurse hurried to the entrance when the patient arrived.","zh":"病人到達時，護士匆忙走向入口。"},{"en":"Aaron hurries because he wants to help Chloe carefully and quickly.","zh":"Aaron 匆忙走去，是因為他想快速而細心地幫助 Chloe。"},{"en":"This phrase shows urgency and purpose.","zh":"這個短語顯示急切和目的。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"passenger side","meaning":"乘客座一邊","examples":[{"en":"Aaron hurried to the passenger side of the car.","zh":"Aaron 匆忙走向汽車乘客座一邊。"},{"en":"The passenger side is the side of a car where passengers sit, not the driver.","zh":"Passenger side 指汽車中乘客坐的位置那一邊，而不是司機那邊。"},{"en":"Aaron went to the passenger side to help the little girl into the car.","zh":"Aaron 走向乘客座一邊，是為了幫小女孩上車。"},{"en":"This detail shows he is serving someone else, not showing off.","zh":"這個細節顯示他是在服務別人，而不是炫耀。"},{"en":"This phrase gives a clear car-related position.","zh":"這個短語提供清楚的車內位置。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"step from the taxi","meaning":"從的士下車","examples":[{"en":"I stepped from the taxi outside the hospital.","zh":"我在醫院外從的士下車。"},{"en":"Step from the taxi means get out of the taxi carefully.","zh":"Step from the taxi 指小心地從的士走出來。"},{"en":"Mary stepped from the taxi ready to confront Aaron.","zh":"Mary 從的士下車，準備質問 Aaron。"},{"en":"Getting out of the taxi moves her from suspicion into direct discovery.","zh":"下車令她由懷疑地觀察轉為直接發現真相。"},{"en":"This phrase marks a change from watching to acting.","zh":"這個短語標示由觀看轉為行動。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"ready to demand an explanation","meaning":"準備要求解釋","examples":[{"en":"I was ready to demand an explanation from Aaron.","zh":"我準備向 Aaron 要求解釋。"},{"en":"Ready to demand an explanation means prepared to insist that someone tell the truth.","zh":"Ready to demand an explanation 指準備堅持要求某人說出真相。"},{"en":"Mary was angry enough to demand an explanation before she saw Chloe.","zh":"Mary 在看見 Chloe 前，生氣得準備要求解釋。"},{"en":"People demand explanations when they feel worried, betrayed or confused.","zh":"當人們感到擔心、被背叛或困惑時，會要求解釋。"},{"en":"This phrase shows emotional tension before the truth appears.","zh":"這個短語顯示真相出現前的情感張力。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"demand an explanation","meaning":"要求解釋","examples":[{"en":"Mary wanted to demand an explanation.","zh":"Mary 想要求解釋。"},{"en":"Demand an explanation means strongly ask someone to explain what happened.","zh":"Demand an explanation 指強烈要求某人解釋發生了甚麼。"},{"en":"A parent may demand an explanation if a child comes home very late.","zh":"如果孩子很晚回家，父母可能會要求解釋。"},{"en":"Demanding an explanation can sound angry because it suggests suspicion.","zh":"要求解釋聽起來可能帶怒氣，因為它暗示懷疑。"},{"en":"This phrase is stronger than simply asking a question.","zh":"這個短語比單純提問更強烈。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"only to find myself frozen","meaning":"結果卻發現自己僵住","examples":[{"en":"I stepped from the taxi, only to find myself frozen by what I saw.","zh":"我從的士下車，結果卻發現自己被眼前所見嚇得僵住。"},{"en":"Only to find myself frozen means I expected to act, but instead I stopped in shock.","zh":"Only to find myself frozen 指我本來預期行動，結果卻因震驚而停住。"},{"en":"She opened the door to complain, only to find herself frozen by the surprise party.","zh":"她打開門想投訴，結果卻發現自己被驚喜派對嚇得僵住。"},{"en":"This phrase shows an unexpected result.","zh":"這個短語顯示意想不到的結果。"},{"en":"It changes the scene from anger to shock.","zh":"它把場景由憤怒轉為震驚。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"frozen by what I saw","meaning":"被眼前所見嚇得僵住","examples":[{"en":"I was frozen by what I saw outside the hospital.","zh":"我被醫院外眼前所見嚇得僵住。"},{"en":"Frozen by what I saw means unable to move or speak because the sight was shocking.","zh":"Frozen by what I saw 指因看見震驚畫面而無法移動或說話。"},{"en":"Mary was frozen when she saw a sick child waiting for the ride.","zh":"Mary 看見一名生病孩子等待乘車時僵住了。"},{"en":"A powerful image can stop anger immediately.","zh":"有力的畫面可以立即令怒氣停下。"},{"en":"This phrase shows shock through physical stillness.","zh":"這個短語透過身體僵住表現震驚。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"little girl in a wheelchair","meaning":"坐輪椅的小女孩","examples":[{"en":"A little girl in a wheelchair was waiting under the shelter.","zh":"一名坐輪椅的小女孩正在上蓋下等候。"},{"en":"A little girl in a wheelchair is a young child who uses a wheelchair to move around.","zh":"Little girl in a wheelchair 指需要使用輪椅移動的年幼女孩。"},{"en":"The little girl in a wheelchair changes Mary’s understanding of Aaron’s actions.","zh":"坐輪椅的小女孩改變了 Mary 對 Aaron 行為的理解。"},{"en":"Seeing a child needing help makes the scene more compassionate.","zh":"看見需要幫助的孩子，令場景更有同情感。"},{"en":"This phrase introduces the person Aaron is trying to serve.","zh":"這個短語介紹 Aaron 正努力服務的人。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"under the shelter","meaning":"在上蓋下","examples":[{"en":"The girl was waiting under the shelter.","zh":"那女孩正在上蓋下等候。"},{"en":"Under the shelter means beneath a covered area that protects people from rain or sun.","zh":"Under the shelter 指在可遮雨或遮陽的有蓋地方下面。"},{"en":"Patients may wait under the shelter outside a hospital entrance.","zh":"病人可能在醫院入口外的上蓋下等候。"},{"en":"The shelter suggests care and protection in the grey afternoon.","zh":"上蓋在灰沉沉的下午暗示照顧和保護。"},{"en":"This phrase gives the scene a clear physical location.","zh":"這個短語給場景一個清楚的實際位置。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"woollen hat","meaning":"羊毛帽","examples":[{"en":"She wore a woollen hat decorated with yellow stars.","zh":"她戴着一頂以黃色星星裝飾的羊毛帽。"},{"en":"A woollen hat is a warm hat made from wool or similar soft material.","zh":"Woollen hat 指由羊毛或類似柔軟材料製成的保暖帽。"},{"en":"A woollen hat can keep a child warm during a hospital visit.","zh":"羊毛帽可以在孩子到醫院時保暖。"},{"en":"Chloe’s woollen hat adds tenderness to the scene.","zh":"Chloe 的羊毛帽為場景加入溫柔感。"},{"en":"This phrase gives a small, memorable detail about the girl.","zh":"這個短語給女孩一個細小而難忘的細節。"}],"source":"2012 Q7.pdf","sourcePage":7},{"front":"decorated with","meaning":"以……裝飾","examples":[{"en":"Her hat was decorated with yellow stars.","zh":"她的帽子以黃色星星裝飾。"},{"en":"Decorated with means made prettier or more noticeable by adding something.","zh":"Decorated with 指透過加入某物令它更美觀或更顯眼。"},{"en":"The classroom was decorated with paper flowers.","zh":"課室以紙花裝飾。"},{"en":"Chloe’s hat is decorated with stars, making it look bright and childlike.","zh":"Chloe 的帽子以星星裝飾，令它看起來明亮而有童真。"},{"en":"This phrase describes added visual detail.","zh":"這個短語描述加上的視覺細節。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"yellow stars","meaning":"黃色星星","examples":[{"en":"The woollen hat was decorated with yellow stars.","zh":"那頂羊毛帽以黃色星星裝飾。"},{"en":"Yellow stars are bright star-shaped decorations in a yellow colour.","zh":"Yellow stars 指黃色的星形裝飾。"},{"en":"Yellow stars on a child’s hat can suggest hope and imagination.","zh":"孩子帽子上的黃色星星可以暗示希望和想像。"},{"en":"The stars look brighter because Chloe herself looks pale.","zh":"因為 Chloe 本人很蒼白，星星看起來更明亮。"},{"en":"This phrase gives colour and contrast to the scene.","zh":"這個短語為場景加入色彩和對比。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"so pale that","meaning":"蒼白得……","examples":[{"en":"Her face was so pale that the hat looked brighter than the rest of her.","zh":"她的臉蒼白得令帽子比她整個人更鮮亮。"},{"en":"So pale that means extremely pale, with a result following after “that.”","zh":"So pale that 指非常蒼白，並在 that 後說明結果。"},{"en":"He was so tired that he could hardly stand.","zh":"他累得幾乎站不住。"},{"en":"Chloe’s paleness suggests illness and makes Mary’s anger weaken.","zh":"Chloe 的蒼白暗示疾病，並令 Mary 的怒氣開始減弱。"},{"en":"This structure links degree with result.","zh":"這個結構把程度和結果連接起來。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"brighter than the rest of her","meaning":"比她整個人更鮮亮","examples":[{"en":"The hat looked brighter than the rest of her.","zh":"那頂帽子看起來比她整個人更鮮亮。"},{"en":"Brighter than the rest of her means the hat appeared more colourful than the girl’s pale body or face.","zh":"Brighter than the rest of her 指帽子看起來比女孩蒼白的身體或臉更有色彩。"},{"en":"A red scarf may look brighter than a tired patient’s face.","zh":"紅色圍巾可能比疲累病人的臉更鮮亮。"},{"en":"This contrast makes Chloe seem fragile but still full of childlike hope.","zh":"這種對比令 Chloe 顯得脆弱，但仍有孩子般的希望。"},{"en":"This phrase uses colour to create emotion.","zh":"這個短語用色彩製造情感。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"stand behind","meaning":"站在……後面","examples":[{"en":"The woman in the cream coat stood behind Chloe.","zh":"穿米色外套的女子站在 Chloe 後面。"},{"en":"Stand behind means be positioned at the back of someone or something.","zh":"Stand behind 指位於某人或某物後方。"},{"en":"A mother may stand behind a child in a wheelchair to support her.","zh":"母親可能站在坐輪椅的孩子後面支持她。"},{"en":"Standing behind Chloe suggests protection and care.","zh":"站在 Chloe 後面暗示保護和照顧。"},{"en":"This phrase describes both position and emotional support.","zh":"這個短語同時描述位置和情感支持。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"clutch the folder","meaning":"緊握文件夾","examples":[{"en":"The woman stood behind Chloe, clutching the folder.","zh":"那名女子站在 Chloe 後面，緊握文件夾。"},{"en":"Clutch the folder means hold the folder tightly, often from worry or importance.","zh":"Clutch the folder 指緊緊拿着文件夾，通常因為擔心或文件重要。"},{"en":"A parent may clutch a medical folder while waiting at a hospital.","zh":"家長在醫院等候時，可能緊握醫療文件夾。"},{"en":"The action shows the woman is anxious and responsible.","zh":"這個動作顯示女子焦慮而負責任。"},{"en":"This phrase uses hand movement to show emotion.","zh":"這個短語用手部動作表現情感。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"kneel beside","meaning":"跪在……旁邊","examples":[{"en":"Aaron knelt beside the girl and smiled.","zh":"Aaron 跪在女孩旁邊並微笑。"},{"en":"Kneel beside means lower oneself onto one or both knees next to someone.","zh":"Kneel beside 指在某人旁邊單膝或雙膝跪下。"},{"en":"Aaron kneels beside Chloe so he can speak to her at her level.","zh":"Aaron 跪在 Chloe 旁邊，好讓自己以她的高度和她說話。"},{"en":"Kneeling beside a child can show gentleness and respect.","zh":"跪在孩子旁邊可以顯示溫柔和尊重。"},{"en":"This phrase reveals Aaron’s care through body language.","zh":"這個短語透過身體語言揭示 Aaron 的細心。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"your carriage awaits","meaning":"你的馬車已經準備好了","examples":[{"en":"Aaron said, “Your carriage awaits.”","zh":"Aaron 說：「你的馬車已經準備好了。」"},{"en":"Your carriage awaits is a playful formal line meaning your ride is ready.","zh":"Your carriage awaits 是帶玩味的正式說法，意思是你的車已準備好。"},{"en":"Aaron says this to make Chloe feel like a princess.","zh":"Aaron 這樣說，是為了令 Chloe 感覺像公主。"},{"en":"A driver might jokingly say “your carriage awaits” before opening the car door.","zh":"司機打開車門前，可能半開玩笑地說「你的馬車已經準備好了」。"},{"en":"This phrase turns an ordinary ride into a magical moment.","zh":"這個短語把普通車程變成魔法般的一刻。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"laugh brightly enough to","meaning":"笑得明亮得足以……","examples":[{"en":"The girl laughed brightly enough to cut through the grey afternoon.","zh":"那女孩笑得明亮得足以穿透灰沉沉的下午。"},{"en":"Laugh brightly enough to means laugh with enough joy to change the mood around her.","zh":"Laugh brightly enough to 指笑得充滿喜悅，足以改變周圍氣氛。"},{"en":"A child’s laugh can be bright enough to lift a tired room.","zh":"孩子的笑聲可以明亮得足以令疲累的房間變輕鬆。"},{"en":"Chloe’s laughter cuts through sadness because it is full of life.","zh":"Chloe 的笑聲穿透悲傷，因為它充滿生命力。"},{"en":"This phrase shows joy as something powerful.","zh":"這個短語把喜悅描寫成有力量的東西。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"cut through","meaning":"穿透","examples":[{"en":"Her laughter cut through the grey afternoon.","zh":"她的笑聲穿透灰沉沉的下午。"},{"en":"Cut through means pass strongly through something and change it.","zh":"Cut through 指有力地穿過某物並改變它。"},{"en":"A clear voice can cut through a noisy room.","zh":"清晰的聲音可以穿透嘈雜房間。"},{"en":"Chloe’s laughter cuts through the dull mood outside the hospital.","zh":"Chloe 的笑聲穿透醫院外沉悶的氣氛。"},{"en":"This phrase makes sound feel sharp and powerful.","zh":"這個短語令聲音感覺銳利而有力量。"}],"source":"2012 Q7.pdf","sourcePage":8},{"front":"grey afternoon","meaning":"灰沉沉的下午","examples":[{"en":"Her laughter cut through the grey afternoon.","zh":"她的笑聲穿透灰沉沉的下午。"},{"en":"A grey afternoon is a dull, cloudy or emotionally heavy afternoon.","zh":"Grey afternoon 指陰沉、多雲或情感上沉重的下午。"},{"en":"After rain, the city may feel like a grey afternoon.","zh":"雨後，城市可能像一個灰沉沉的下午。"},{"en":"Chloe’s laughter makes the grey afternoon feel less hopeless.","zh":"Chloe 的笑聲令灰沉沉的下午不再那麼絕望。"},{"en":"This phrase describes both weather and mood.","zh":"這個短語同時描述天氣和心情。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"only then did I notice","meaning":"直到那時我才留意到","examples":[{"en":"Only then did I notice the sticker on the car door.","zh":"直到那時，我才留意到車門上的貼紙。"},{"en":"Only then did I notice means I did not notice until that exact moment.","zh":"Only then did I notice 指直到那一刻我才注意到。"},{"en":"Only then did Mary understand that the car was part of a charity ride.","zh":"直到那時，Mary 才明白那輛車是慈善乘車活動的一部分。"},{"en":"This structure highlights a delayed realisation.","zh":"這個結構突出延遲的發現。"},{"en":"It helps reveal important information dramatically.","zh":"它幫助以戲劇化方式揭示重要資訊。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"small sticker","meaning":"小貼紙","examples":[{"en":"A small sticker was on the car door.","zh":"車門上有一張小貼紙。"},{"en":"A small sticker is a little label or picture attached to a surface.","zh":"Small sticker 指貼在表面上的小標籤或小圖案。"},{"en":"A small sticker can identify which organisation a car belongs to.","zh":"小貼紙可以標示汽車屬於哪個機構。"},{"en":"In the story, a small sticker changes Mary’s understanding of everything.","zh":"在故事中，一張小貼紙改變了 Mary 對一切的理解。"},{"en":"This phrase shows how a tiny detail can carry the truth.","zh":"這個短語顯示細小細節也可以承載真相。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"car door","meaning":"車門","examples":[{"en":"The sticker was on the car door.","zh":"貼紙在車門上。"},{"en":"A car door is the door used to enter or leave a car.","zh":"Car door 指用來進出汽車的門。"},{"en":"A logo on a car door can show the car belongs to a company or charity.","zh":"車門上的標誌可以顯示汽車屬於公司或慈善機構。"},{"en":"Mary notices the car door sticker only after seeing Chloe.","zh":"Mary 在看見 Chloe 後，才注意到車門貼紙。"},{"en":"This phrase gives the exact place of an important clue.","zh":"這個短語指出重要線索的確切位置。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"Dream Ride Foundation","meaning":"夢想乘車基金會","examples":[{"en":"The car belonged to Dream Ride Foundation.","zh":"那輛車屬於夢想乘車基金會。"},{"en":"Dream Ride Foundation is the organisation in the story that arranges special car rides for children.","zh":"Dream Ride Foundation 是故事中為孩子安排特別乘車體驗的機構。"},{"en":"The foundation uses the sports car to give Chloe a beautiful afternoon.","zh":"基金會使用那輛跑車，為 Chloe 帶來一個美好的下午。"},{"en":"The name reveals that Aaron’s work is kind, not suspicious.","zh":"這個名稱揭示 Aaron 的工作是善意的，而不是可疑的。"},{"en":"This phrase changes the meaning of the car from luxury to charity.","zh":"這個短語把汽車的意義由奢華改為慈善。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"a second later","meaning":"一秒後","examples":[{"en":"Aaron saw me a second later.","zh":"一秒後，Aaron 看見了我。"},{"en":"A second later means almost immediately after that moment.","zh":"A second later 指幾乎在那一刻之後立刻。"},{"en":"A second later, Mary realised Aaron had noticed her.","zh":"一秒後，Mary 意識到 Aaron 已經注意到她。"},{"en":"This phrase keeps the action moving quickly.","zh":"這個短語令動作快速推進。"},{"en":"It marks a sudden shift from watching to being seen.","zh":"它標示由觀察別人轉為被別人看見。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"his smile faded","meaning":"他的笑容消失","examples":[{"en":"Aaron’s smile faded when he saw Mary.","zh":"Aaron 看見 Mary 時，他的笑容消失了。"},{"en":"His smile faded means his smile slowly disappeared.","zh":"His smile faded 指他的笑容慢慢消失。"},{"en":"A person’s smile may fade when they realise someone is upset.","zh":"當一個人意識到別人生氣時，笑容可能會消失。"},{"en":"Aaron’s smile fades because he understands Mary has followed him.","zh":"Aaron 的笑容消失，因為他明白 Mary 跟着他來了。"},{"en":"This phrase shows a change in emotion through facial expression.","zh":"這個短語透過表情顯示情感變化。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"I could ask you the same thing","meaning":"我也可以問你同一個問題","examples":[{"en":"Mary said, “I could ask you the same thing.”","zh":"Mary 說：「我也可以問你同一個問題。」"},{"en":"I could ask you the same thing means your question also applies to you.","zh":"I could ask you the same thing 指你的問題也同樣適用於你。"},{"en":"If someone asks why you are here, you might reply, “I could ask you the same thing.”","zh":"如果有人問你為何在這裏，你可以回答：「我也可以問你同一個問題。」"},{"en":"Mary uses this line because Aaron also owes her an explanation.","zh":"Mary 使用這句話，因為 Aaron 也欠她一個解釋。"},{"en":"This phrase can sound defensive or challenging.","zh":"這個短語可以聽起來防衛或帶挑戰。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"my anger was already weakening","meaning":"我的怒氣已經開始減弱","examples":[{"en":"My anger was already weakening when I saw Chloe.","zh":"看見 Chloe 時，我的怒氣已經開始減弱。"},{"en":"My anger was already weakening means I was becoming less angry.","zh":"My anger was already weakening 指我變得沒有那麼生氣。"},{"en":"Mary’s anger weakens because Chloe’s situation reveals kindness behind Aaron’s actions.","zh":"Mary 的怒氣減弱，因為 Chloe 的情況揭示 Aaron 行動背後的善意。"},{"en":"Seeing someone vulnerable can soften suspicion.","zh":"看見脆弱的人可以軟化懷疑。"},{"en":"This phrase shows emotion changing before an explanation is given.","zh":"這個短語顯示在解釋出現前情緒已經改變。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"give me twenty minutes","meaning":"給我二十分鐘","examples":[{"en":"Aaron asked Mary to give him twenty minutes.","zh":"Aaron 請 Mary 給他二十分鐘。"},{"en":"Give me twenty minutes means allow me twenty minutes before asking questions or judging.","zh":"Give me twenty minutes 指在提問或判斷前，先給我二十分鐘。"},{"en":"A person may say “give me ten minutes” when they need time to finish something important.","zh":"當一個人需要時間完成重要事情時，可能會說「給我十分鐘」。"},{"en":"Aaron asks for time because Chloe’s ride matters more than the argument.","zh":"Aaron 要求時間，因為 Chloe 的乘車體驗比爭執更重要。"},{"en":"This phrase requests patience.","zh":"這個短語是在請求耐性。"}],"source":"2012 Q7.pdf","sourcePage":9},{"front":"wait by the entrance","meaning":"在入口旁等候","examples":[{"en":"I waited by the entrance while Aaron helped Chloe.","zh":"Aaron 幫助 Chloe 時，我在入口旁等候。"},{"en":"Wait by the entrance means stay near the doorway until something happens.","zh":"Wait by the entrance 指在門口附近等待事情發生。"},{"en":"Mary waited by the entrance because Aaron asked for time.","zh":"Mary 在入口旁等候，因為 Aaron 要求一些時間。"},{"en":"Waiting can give a person space to calm down and observe.","zh":"等候可以給人空間冷靜和觀察。"},{"en":"This phrase gives a clear place and pause in the action.","zh":"這個短語提供清楚位置和行動中的停頓。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"help someone into the car","meaning":"扶某人上車","examples":[{"en":"Aaron helped Chloe into the car carefully.","zh":"Aaron 小心地扶 Chloe 上車。"},{"en":"Help someone into the car means support someone while they get inside a car.","zh":"Help someone into the car 指在某人上車時扶助他。"},{"en":"A nurse may help an elderly patient into the car after a hospital visit.","zh":"醫院探訪後，護士可能扶年長病人上車。"},{"en":"Aaron helps Chloe into the car gently because she is fragile.","zh":"Aaron 溫柔地扶 Chloe 上車，因為她很脆弱。"},{"en":"This phrase shows practical care.","zh":"這個短語顯示實際照顧。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"with a care I had never seen in him before","meaning":"以一種我從未見過的細心","examples":[{"en":"Aaron helped Chloe with a care I had never seen in him before.","zh":"Aaron 以一種我從未見過的細心扶 Chloe。"},{"en":"This means Aaron acted with a level of gentleness Mary had not noticed before.","zh":"這句話指 Aaron 表現出 Mary 以前未曾留意到的溫柔程度。"},{"en":"A person may show unexpected care when helping someone vulnerable.","zh":"一個人在幫助脆弱的人時，可能會表現出意想不到的細心。"},{"en":"Mary sees a new side of Aaron through the way he treats Chloe.","zh":"Mary 透過 Aaron 對待 Chloe 的方式，看見他新的一面。"},{"en":"This phrase reveals character through action.","zh":"這個短語透過行動揭示人物性格。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"race away","meaning":"飛快駛走","examples":[{"en":"They did not race away in the sports car.","zh":"他們沒有開着跑車飛快駛走。"},{"en":"Race away means drive away very quickly.","zh":"Race away 指非常快速地開車離開。"},{"en":"A sports car can race away loudly, but Aaron drives slowly for Chloe.","zh":"跑車可以大聲地飛快駛走，但 Aaron 為了 Chloe 慢慢開。"},{"en":"The car does not race away because the ride is meant to feel special, not dangerous.","zh":"那輛車沒有飛快駛走，因為這趟車程是要特別，而不是危險。"},{"en":"This phrase contrasts expected speed with gentle care.","zh":"這個短語把預期中的速度與溫柔照顧作對比。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"almost ceremonially","meaning":"近乎莊重地","examples":[{"en":"They drove slowly, almost ceremonially, around the block.","zh":"他們慢慢地、近乎莊重地繞着街區行駛。"},{"en":"Almost ceremonially means in a slow, careful and respectful way, like a ceremony.","zh":"Almost ceremonially 指以緩慢、仔細而尊重的方式進行，像儀式一樣。"},{"en":"The students carried the trophy almost ceremonially across the hall.","zh":"學生近乎莊重地把獎盃帶過禮堂。"},{"en":"Aaron drives almost ceremonially because the ride is Chloe’s special moment.","zh":"Aaron 近乎莊重地開車，因為這趟車程是 Chloe 的特別時刻。"},{"en":"This phrase makes an ordinary action feel meaningful.","zh":"這個短語令普通行動變得有意義。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"around the block","meaning":"繞着街區","examples":[{"en":"They drove slowly around the block.","zh":"他們慢慢繞着街區行駛。"},{"en":"Around the block means around the nearby group of streets and buildings.","zh":"Around the block 指繞過附近的一組街道和建築物。"},{"en":"The driver took the child around the block so she could enjoy the ride.","zh":"司機載着孩子繞着街區，讓她享受車程。"},{"en":"Driving around the block is short, but it can still feel special.","zh":"繞着街區路程雖短，但仍可以感覺特別。"},{"en":"This phrase describes a small circular journey.","zh":"這個短語描述一段小型環形路程。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"wave at","meaning":"向……揮手","examples":[{"en":"Chloe waved at her mother from the car.","zh":"Chloe 從車裏向母親揮手。"},{"en":"Wave at means move your hand to greet or say goodbye to someone.","zh":"Wave at 指揮動手來向某人打招呼或道別。"},{"en":"A child may wave at her parents from a school bus.","zh":"孩子可能從校巴裏向父母揮手。"},{"en":"Chloe’s wave shows joy and pride in her special ride.","zh":"Chloe 的揮手顯示她在特別車程中的快樂和自豪。"},{"en":"This phrase describes a simple gesture of connection.","zh":"這個短語描述一個簡單的連結手勢。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"as if she were","meaning":"彷彿她是","examples":[{"en":"Chloe waved as if she were a princess in a parade.","zh":"Chloe 揮手時，彷彿她是巡遊中的公主。"},{"en":"As if she were means like she was, though it may not be literally true.","zh":"As if she were 指好像她是那樣，雖然未必是字面事實。"},{"en":"The child smiled as if she were already on a stage.","zh":"那孩子微笑着，彷彿她已站在舞台上。"},{"en":"Chloe is not truly a princess, but Aaron makes her feel like one.","zh":"Chloe 並不真的是公主，但 Aaron 令她感覺像公主。"},{"en":"This phrase connects reality with imagination.","zh":"這個短語把現實和想像連接起來。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"princess in a parade","meaning":"巡遊中的公主","examples":[{"en":"Chloe waved like a princess in a parade.","zh":"Chloe 像巡遊中的公主一樣揮手。"},{"en":"A princess in a parade is an image of someone proudly greeting people during a public celebration.","zh":"Princess in a parade 指在公開慶祝中自豪地向人打招呼的公主形象。"},{"en":"A child in a special car may feel like a princess in a parade.","zh":"坐在特別車裏的孩子可能感覺像巡遊中的公主。"},{"en":"This image shows Chloe’s happiness and temporary escape from illness.","zh":"這個畫面顯示 Chloe 的快樂，以及暫時逃離病痛的感覺。"},{"en":"This phrase turns a hospital ride into a fairytale moment.","zh":"這個短語把醫院車程變成童話時刻。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"loosen his tie","meaning":"鬆開領呔","examples":[{"en":"Aaron loosened his tie when he returned.","zh":"Aaron 回來時鬆開領呔。"},{"en":"Loosen his tie means make the tie less tight around the neck.","zh":"Loosen his tie 指把頸上的領呔弄鬆一點。"},{"en":"After a stressful meeting, a worker may loosen his tie.","zh":"壓力大的會議後，員工可能會鬆開領呔。"},{"en":"Aaron loosens his tie because the formal role is over and he is tired.","zh":"Aaron 鬆開領呔，因為正式角色結束了，而他很疲累。"},{"en":"This phrase shows a person relaxing after pressure.","zh":"這個短語顯示人在壓力後放鬆。"}],"source":"2012 Q7.pdf","sourcePage":10},{"front":"come over","meaning":"走過來","examples":[{"en":"Aaron came over to speak to Mary.","zh":"Aaron 走過來和 Mary 說話。"},{"en":"Come over means move toward someone’s position to talk or join them.","zh":"Come over 指走向某人的位置，通常是為了交談或加入。"},{"en":"The teacher came over when she saw the students arguing.","zh":"老師看見學生爭執時走過來。"},{"en":"Aaron comes over because he knows Mary needs an explanation.","zh":"Aaron 走過來，因為他知道 Mary 需要解釋。"},{"en":"This phrase describes friendly or direct movement toward someone.","zh":"這個短語描述友善或直接走向某人的動作。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"before I could speak","meaning":"還未等我開口","examples":[{"en":"Aaron explained before I could speak.","zh":"還未等我開口，Aaron 已開始解釋。"},{"en":"Before I could speak means before I had time to say anything.","zh":"Before I could speak 指在我有時間說話之前。"},{"en":"Before Mary could accuse him, Aaron began to explain.","zh":"還未等 Mary 指責他，Aaron 就開始解釋。"},{"en":"This phrase shows that Aaron understands the misunderstanding quickly.","zh":"這個短語顯示 Aaron 很快明白誤會。"},{"en":"It creates a quick shift into explanation.","zh":"它迅速把場景轉入解釋。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"belong to","meaning":"屬於","examples":[{"en":"The car belongs to a businessman.","zh":"那輛車屬於一位商人。"},{"en":"Belong to means be owned by someone or something.","zh":"Belong to 指由某人或某機構擁有。"},{"en":"The key belongs to the foundation, not to Aaron.","zh":"那條鑰匙屬於基金會，而不是 Aaron。"},{"en":"Knowing who something belongs to can correct a misunderstanding.","zh":"知道某物屬於誰，可以糾正誤會。"},{"en":"This phrase is useful for explaining ownership.","zh":"這個短語適合用來解釋所有權。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"businessman","meaning":"商人","examples":[{"en":"A businessman lends the car to the foundation.","zh":"一位商人把車借給基金會。"},{"en":"A businessman is a person who works in business, often owning or managing companies.","zh":"Businessman 指從事商業的人，常擁有或管理公司。"},{"en":"The businessman uses his sports car to help children through the foundation.","zh":"那位商人透過基金會用自己的跑車幫助孩子。"},{"en":"A wealthy person can support charity by lending resources, not only money.","zh":"富有人士可以透過借出資源支持慈善，而不只是捐錢。"},{"en":"This word identifies the car’s real owner.","zh":"這個詞指出汽車真正的主人。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"lend something to","meaning":"把某物借給","examples":[{"en":"The businessman lends the car to the foundation twice a month.","zh":"那位商人每月兩次把車借給基金會。"},{"en":"Lend something to someone means allow them to use it for a period of time.","zh":"Lend something to someone 指讓某人在一段時間內使用某物。"},{"en":"A teacher may lend books to students for a project.","zh":"老師可能把書借給學生做專題。"},{"en":"The businessman lends the car so sick children can enjoy special rides.","zh":"商人借出汽車，讓生病孩子享受特別車程。"},{"en":"This phrase shows temporary use, not ownership.","zh":"這個短語顯示暫時使用，而不是擁有。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"foundation","meaning":"基金會","examples":[{"en":"The car is used by the foundation for children.","zh":"那輛車由基金會用來服務孩子。"},{"en":"A foundation is an organisation that supports a cause, often through charity work.","zh":"Foundation 指支持某個目標的機構，常透過慈善工作運作。"},{"en":"The foundation arranges dream rides for children facing illness.","zh":"基金會為面對疾病的孩子安排夢想車程。"},{"en":"Foundations can connect donors, volunteers and people who need help.","zh":"基金會可以連接捐助者、義工和需要幫助的人。"},{"en":"This word explains the charity behind Aaron’s job.","zh":"這個詞解釋 Aaron 工作背後的慈善機構。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"twice a month","meaning":"每月兩次","examples":[{"en":"The businessman lends the car twice a month.","zh":"那位商人每月兩次借出汽車。"},{"en":"Twice a month means two times in each month.","zh":"Twice a month 指每個月兩次。"},{"en":"Volunteers may visit the hospital twice a month.","zh":"義工可能每月兩次到醫院探訪。"},{"en":"Lending the car twice a month makes the programme regular but special.","zh":"每月兩次借出汽車，令活動有規律但仍然特別。"},{"en":"This phrase describes frequency.","zh":"這個短語描述頻率。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"medical consent forms","meaning":"醫療同意書","examples":[{"en":"The envelope contained Chloe’s medical consent forms.","zh":"信封裏裝着 Chloe 的醫療同意書。"},{"en":"Medical consent forms are documents giving permission for medical care or related activities.","zh":"Medical consent forms 指准許醫療護理或相關活動的文件。"},{"en":"A parent may sign medical consent forms before a child receives treatment.","zh":"家長可能在孩子接受治療前簽署醫療同意書。"},{"en":"The envelope was not secret money; it held important medical documents.","zh":"信封裏不是秘密金錢，而是重要醫療文件。"},{"en":"This phrase corrects Mary’s misunderstanding about the envelope.","zh":"這個短語糾正 Mary 對信封的誤解。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"old Hong Kong movies","meaning":"香港舊電影","examples":[{"en":"Chloe loves old Hong Kong movies.","zh":"Chloe 喜歡香港舊電影。"},{"en":"Old Hong Kong movies are films from earlier periods of Hong Kong cinema.","zh":"Old Hong Kong movies 指較早期香港電影時期的作品。"},{"en":"Chloe’s love of old Hong Kong movies explains why she wants a film-star arrival.","zh":"Chloe 喜歡香港舊電影，解釋了她為何想像電影明星般到達。"},{"en":"Movies can comfort a child by giving her dreams and images of glamour.","zh":"電影可以透過夢想和光彩畫面安慰孩子。"},{"en":"This phrase connects Chloe’s wish with local culture.","zh":"這個短語把 Chloe 的願望和本地文化連接起來。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"arrive there like a film star","meaning":"像電影明星般到達那裏","examples":[{"en":"Chloe wanted to arrive at the Peninsula like a film star.","zh":"Chloe 想像電影明星般到達半島酒店。"},{"en":"Arrive there like a film star means reach a place in a glamorous, confident and special way.","zh":"Arrive there like a film star 指以光彩、自信和特別的方式到達某地。"},{"en":"A child might dream of arriving at a party like a film star in a beautiful car.","zh":"孩子可能夢想坐着漂亮汽車，像電影明星般到達派對。"},{"en":"The ride lets Chloe feel special before her treatment.","zh":"這趟車程讓 Chloe 在治療前感到特別。"},{"en":"This phrase shows the emotional purpose of the sports car.","zh":"這個短語顯示跑車的情感目的。"}],"source":"2012 Q7.pdf","sourcePage":11},{"front":"film star","meaning":"電影明星","examples":[{"en":"Chloe wanted to feel like a film star.","zh":"Chloe 想感覺像電影明星。"},{"en":"A film star is a famous actor or actress in movies.","zh":"Film star 指電影中著名的男演員或女演員。"},{"en":"A film star may arrive at a hotel in a beautiful car while people watch.","zh":"電影明星可能坐漂亮汽車到達酒店，受人注視。"},{"en":"Chloe’s dream of feeling like a film star gives her joy before treatment.","zh":"Chloe 想感覺像電影明星的夢想，在治療前給她快樂。"},{"en":"This phrase represents glamour and attention.","zh":"這個短語代表光彩和注視。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"before her treatment","meaning":"在她接受治療之前","examples":[{"en":"Chloe wanted a special ride before her treatment.","zh":"Chloe 想在接受治療之前有一次特別車程。"},{"en":"Before her treatment means before she receives medical care.","zh":"Before her treatment 指在她接受醫療護理之前。"},{"en":"A child may want one happy experience before a difficult treatment.","zh":"孩子可能在困難治療前想要一次快樂經歷。"},{"en":"The timing makes the ride feel tender and urgent.","zh":"這個時間點令車程感覺溫柔而急切。"},{"en":"This phrase explains why the afternoon matters so much.","zh":"這個短語解釋為何那個下午如此重要。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"give a tired smile","meaning":"露出疲倦的笑容","examples":[{"en":"Aaron gave a tired smile as he explained.","zh":"Aaron 解釋時露出疲倦的笑容。"},{"en":"Give a tired smile means smile weakly while feeling exhausted.","zh":"Give a tired smile 指在疲累時淡淡微笑。"},{"en":"A worker may give a tired smile after a long but meaningful day.","zh":"工作了一個漫長但有意義的日子後，員工可能露出疲倦的笑容。"},{"en":"Aaron’s tired smile shows he is not glamorous; he is simply working hard.","zh":"Aaron 疲倦的笑容顯示他並不光鮮，只是在努力工作。"},{"en":"This phrase mixes warmth with fatigue.","zh":"這個短語把溫暖和疲累混合起來。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"programme assistant","meaning":"活動助理","examples":[{"en":"Aaron worked as a driver and programme assistant.","zh":"Aaron 做司機和活動助理。"},{"en":"A programme assistant helps organise and run activities for an organisation.","zh":"Programme assistant 指協助機構組織和執行活動的人。"},{"en":"Aaron helps the foundation by driving children and supporting the ride programme.","zh":"Aaron 透過接載孩子和支援乘車計劃來幫助基金會。"},{"en":"Programme assistants often handle small tasks that make an event possible.","zh":"活動助理常處理令活動能夠進行的小任務。"},{"en":"This phrase explains Aaron’s real job.","zh":"這個短語解釋 Aaron 真正的工作。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"temporary","meaning":"臨時的","examples":[{"en":"The job was temporary and poorly paid.","zh":"那份工作是臨時的，而且薪酬低。"},{"en":"Temporary means lasting for only a limited time, not permanent.","zh":"Temporary 指只持續有限時間，並非永久。"},{"en":"A temporary job may end after a few weeks or months.","zh":"臨時工作可能在幾星期或幾個月後結束。"},{"en":"Aaron’s job is meaningful but uncertain because it is temporary.","zh":"Aaron 的工作有意義，但因為是臨時的，所以不穩定。"},{"en":"This word describes unstable work.","zh":"這個詞描述不穩定的工作。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"poorly paid","meaning":"薪酬低的","examples":[{"en":"Aaron’s job was meaningful but poorly paid.","zh":"Aaron 的工作有意義，但薪酬低。"},{"en":"Poorly paid means receiving low wages for the work done.","zh":"Poorly paid 指工作所得工資很低。"},{"en":"Some charity jobs are poorly paid but emotionally meaningful.","zh":"有些慈善工作薪酬低，但在情感上很有意義。"},{"en":"A poorly paid job can still give someone purpose and dignity.","zh":"薪酬低的工作仍可以給人目的和尊嚴。"},{"en":"This phrase separates financial reward from personal value.","zh":"這個短語把金錢回報和個人價值分開。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"definitely not glamorous","meaning":"絕不光鮮","examples":[{"en":"The job was definitely not glamorous.","zh":"那份工作絕不光鮮。"},{"en":"Definitely not glamorous means certainly not rich-looking, fashionable or exciting from the outside.","zh":"Definitely not glamorous 指肯定不是外表富貴、時尚或刺激的。"},{"en":"Cleaning equipment after an event is meaningful but definitely not glamorous.","zh":"活動後清理器材有意義，但絕不光鮮。"},{"en":"Aaron’s job involves care and paperwork, not luxury.","zh":"Aaron 的工作涉及照顧和文件，而不是奢華。"},{"en":"This phrase corrects Mary’s first impression.","zh":"這個短語糾正 Mary 的第一印象。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"make sure","meaning":"確定","examples":[{"en":"Aaron wanted to make sure he could keep the job first.","zh":"Aaron 想先確定自己能保住工作。"},{"en":"Make sure means check or become certain that something is true or possible.","zh":"Make sure 指確認或確定某事是真的或可行。"},{"en":"Aaron did not tell his parents until he could make sure the job would last.","zh":"Aaron 在確定工作能維持前，沒有告訴父母。"},{"en":"People make sure before sharing news when they fear disappointment.","zh":"當人們害怕失望，分享消息前會先確定。"},{"en":"This phrase shows caution.","zh":"這個短語顯示謹慎。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"keep the job","meaning":"保住工作","examples":[{"en":"Aaron wanted to keep the job before telling his parents.","zh":"Aaron 想在告訴父母前先保住工作。"},{"en":"Keep the job means continue having the job and not lose it.","zh":"Keep the job 指繼續擁有那份工作，而不是失去它。"},{"en":"A temporary worker may worry about whether he can keep the job.","zh":"臨時員工可能會擔心自己能否保住工作。"},{"en":"Aaron wants to keep the job because it gives him purpose after rejection.","zh":"Aaron 想保住工作，因為它在多次被拒後給他目的感。"},{"en":"This phrase describes employment security.","zh":"這個短語描述就業保障。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"after being rejected","meaning":"在被拒絕之後","examples":[{"en":"After being rejected many times, Aaron feared disappointment.","zh":"在被拒絕很多次之後，Aaron 害怕失望。"},{"en":"After being rejected means after someone or something refuses to accept you.","zh":"After being rejected 指在被某人或某機構拒絕接受之後。"},{"en":"After being rejected by several companies, he lost confidence.","zh":"被幾間公司拒絕後，他失去信心。"},{"en":"Rejection can make people afraid to share hope too early.","zh":"被拒絕可以令人害怕太早分享希望。"},{"en":"This phrase explains Aaron’s silence.","zh":"這個短語解釋 Aaron 為何保持沉默。"}],"source":"2012 Q7.pdf","sourcePage":12},{"front":"so many times","meaning":"很多次","examples":[{"en":"Aaron had been rejected so many times.","zh":"Aaron 已經被拒絕很多次。"},{"en":"So many times means on many occasions, often more than expected or bearable.","zh":"So many times 指多次，通常比預期或能承受的還多。"},{"en":"She failed the test so many times that she began to doubt herself.","zh":"她考試失敗很多次，以致開始懷疑自己。"},{"en":"Being rejected so many times can make a person protect their hopes.","zh":"被拒絕很多次可以令人保護自己的希望。"},{"en":"This phrase stresses repeated experience.","zh":"這個短語強調反覆經歷。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"couldn’t bear","meaning":"無法忍受","examples":[{"en":"Aaron could not bear another disappointed look.","zh":"Aaron 無法忍受再看見一次失望的眼神。"},{"en":"Couldn’t bear means could not emotionally tolerate something.","zh":"Couldn’t bear 指情感上無法承受某事。"},{"en":"He could not bear telling his parents another job had failed.","zh":"他無法忍受再告訴父母另一份工作失敗了。"},{"en":"People avoid sharing news when they cannot bear another painful reaction.","zh":"當人們無法忍受另一個痛苦反應，他們會避免分享消息。"},{"en":"This phrase shows emotional pressure.","zh":"這個短語顯示情感壓力。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"disappointed look","meaning":"失望的眼神","examples":[{"en":"Aaron feared seeing another disappointed look.","zh":"Aaron 害怕再看見失望的眼神。"},{"en":"A disappointed look is an expression showing sadness because someone expected better.","zh":"Disappointed look 指因期望更好而流露傷心的表情。"},{"en":"A parent’s disappointed look can hurt more than words.","zh":"父母失望的眼神可能比說話更傷人。"},{"en":"Aaron hides the job because he fears disappointing his family again.","zh":"Aaron 隱瞞工作，因為他害怕再次令家人失望。"},{"en":"This phrase shows pain through facial expression.","zh":"這個短語透過表情顯示痛苦。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"give someone a chance","meaning":"給某人機會","examples":[{"en":"The foundation gave Aaron a chance.","zh":"基金會給了 Aaron 一個機會。"},{"en":"Give someone a chance means offer someone an opportunity to try or prove themselves.","zh":"Give someone a chance 指給某人嘗試或證明自己的機會。"},{"en":"A small company may give a young worker a chance after many rejections.","zh":"小公司可能在年輕人多次被拒後給他一個機會。"},{"en":"The foundation’s chance helps Aaron feel useful again.","zh":"基金會給的機會令 Aaron 再次感到自己有用。"},{"en":"This phrase connects opportunity with hope.","zh":"這個短語把機會和希望連接起來。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"care about","meaning":"在意","examples":[{"en":"The children do not care about Aaron’s exam results.","zh":"孩子們不在意 Aaron 的考試成績。"},{"en":"Care about means think something is important or worth attention.","zh":"Care about 指認為某事重要或值得注意。"},{"en":"Children care about whether Aaron is kind, not whether he has perfect marks.","zh":"孩子們在意 Aaron 是否善良，而不是他是否有完美分數。"},{"en":"People may care less about status when they need real help.","zh":"當人們需要真正幫助時，可能較不在意地位。"},{"en":"This phrase shows what truly matters to someone.","zh":"這個短語顯示某人真正重視甚麼。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"exam results","meaning":"考試成績","examples":[{"en":"The children do not care about Aaron’s exam results.","zh":"孩子們不在意 Aaron 的考試成績。"},{"en":"Exam results are the marks or grades someone receives after examinations.","zh":"Exam results 指考試後得到的分數或等級。"},{"en":"Aaron may have felt judged by exam results in the past.","zh":"Aaron 過去可能曾感到自己被考試成績評價。"},{"en":"The children value his presence more than his academic record.","zh":"孩子們重視他的出現，多於他的學業紀錄。"},{"en":"This phrase contrasts school achievement with human kindness.","zh":"這個短語把學業成就和人的善意作對比。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"show up","meaning":"出現；守約到場","examples":[{"en":"The children care whether Aaron shows up.","zh":"孩子們在意 Aaron 是否守約到場。"},{"en":"Show up means arrive or appear when expected.","zh":"Show up 指在預期時間到達或出現。"},{"en":"A volunteer shows up when they come as promised.","zh":"義工按承諾前來，就是守約到場。"},{"en":"For the children, Aaron showing up matters because it means he keeps his word.","zh":"對孩子們來說，Aaron 出現很重要，因為這代表他守信用。"},{"en":"This phrase connects presence with reliability.","zh":"這個短語把出現和可靠連接起來。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"it dawned on me","meaning":"我突然明白","examples":[{"en":"It dawned on me that I had judged Aaron wrongly.","zh":"我突然明白自己錯誤判斷了 Aaron。"},{"en":"It dawned on me means I suddenly or gradually realised something.","zh":"It dawned on me 指我突然或逐漸明白某事。"},{"en":"It dawned on Mary that the car was not a sign of crime or wealth.","zh":"Mary 突然明白那輛車不是犯罪或財富的象徵。"},{"en":"A truth may dawn on someone after one small detail changes everything.","zh":"一個小細節改變一切後，真相可能令人突然明白。"},{"en":"This phrase describes a moment of realisation.","zh":"這個短語描述恍然大悟的一刻。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"mistake appearance for truth","meaning":"將表象誤當真相","examples":[{"en":"I had mistaken appearance for truth.","zh":"我把表象誤當成真相。"},{"en":"Mistake appearance for truth means believe what something looks like without knowing the facts.","zh":"Mistake appearance for truth 指在不知道事實前，就相信表面看見的東西。"},{"en":"Mary mistook Aaron’s suit and sports car for signs of hidden wealth.","zh":"Mary 把 Aaron 的西裝和跑車誤當成隱藏財富的證據。"},{"en":"People often mistake appearance for truth when they judge too quickly.","zh":"人們太快判斷時，常會將表象誤當真相。"},{"en":"This phrase states the main lesson of the story.","zh":"這個短語說出故事的主要教訓。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"all that glittered was not gold","meaning":"閃閃發光的不一定是金子","examples":[{"en":"All that glittered was not gold.","zh":"閃閃發光的不一定是金子。"},{"en":"All that glittered was not gold means shiny or attractive things are not always truly valuable or what they seem.","zh":"All that glittered was not gold 指閃亮或吸引的東西不一定真正有價值，或不一定如表面所見。"},{"en":"The sports car glittered, but it did not mean Aaron was rich.","zh":"跑車閃閃發光，但這不代表 Aaron 富有。"},{"en":"A beautiful appearance may hide a borrowed object or a harder truth.","zh":"美麗外表可能隱藏借來的物件或更艱難的真相。"},{"en":"This phrase warns against judging by surface glamour.","zh":"這個短語提醒人不要只憑表面光彩判斷。"}],"source":"2012 Q7.pdf","sourcePage":13},{"front":"borrowed metal","meaning":"借來的金屬","examples":[{"en":"Sometimes the glitter was only borrowed metal.","zh":"有時那光彩只是借來的金屬。"},{"en":"Borrowed metal means the shiny car or object was only borrowed, not owned.","zh":"Borrowed metal 指閃亮的車或物件只是借來的，不是擁有的。"},{"en":"Aaron’s key opened a beautiful car, but the car was borrowed metal.","zh":"Aaron 的鑰匙能打開漂亮汽車，但那車只是借來的金屬。"},{"en":"This phrase contrasts appearance of wealth with temporary use.","zh":"這個短語把富有外表和暫時使用作對比。"},{"en":"It turns the sports car into a symbol of misunderstanding.","zh":"它把跑車變成誤會的象徵。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"polished for","meaning":"為……擦亮","examples":[{"en":"The car was polished for a child who needed one beautiful afternoon.","zh":"那輛車是為一個需要美好下午的孩子而擦亮的。"},{"en":"Polished for means cleaned and made shiny for a particular person or purpose.","zh":"Polished for 指為某人或某目的而清潔並擦亮。"},{"en":"Volunteers polished the car for Chloe’s special ride.","zh":"義工為 Chloe 的特別車程擦亮汽車。"},{"en":"The car’s shine was not for Aaron’s pride, but for a child’s happiness.","zh":"汽車的光亮不是為了 Aaron 的驕傲，而是為了孩子的快樂。"},{"en":"This phrase changes the meaning of glamour into care.","zh":"這個短語把光彩的意義轉化為照顧。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"one beautiful afternoon","meaning":"一個美好的下午","examples":[{"en":"Chloe needed one beautiful afternoon before her treatment.","zh":"Chloe 在治療前需要一個美好的下午。"},{"en":"One beautiful afternoon means a short but precious period of joy and beauty.","zh":"One beautiful afternoon 指一段短暫但珍貴的快樂和美好時光。"},{"en":"For a sick child, one beautiful afternoon can become a memory of hope.","zh":"對生病孩子來說，一個美好的下午可以成為希望的回憶。"},{"en":"The foundation tries to give children beauty before difficult medical moments.","zh":"基金會嘗試在困難醫療時刻前給孩子美好經歷。"},{"en":"This phrase shows how small kindness can matter deeply.","zh":"這個短語顯示小小善意也可以有深刻意義。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"whisper","meaning":"低聲說","examples":[{"en":"Mary whispered that she was sorry.","zh":"Mary 低聲說她很抱歉。"},{"en":"Whisper means speak very quietly, often because of emotion or secrecy.","zh":"Whisper 指非常輕聲地說話，通常因為情緒或保密。"},{"en":"Mary whispered because she felt ashamed of judging Aaron wrongly.","zh":"Mary 低聲說話，因為她為錯誤判斷 Aaron 感到羞愧。"},{"en":"People whisper apologies when they feel gentle, guilty or afraid.","zh":"人們感到溫柔、內疚或害怕時，可能會低聲道歉。"},{"en":"This word shows softness in speech.","zh":"這個詞顯示說話的柔和。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"shrug","meaning":"聳肩","examples":[{"en":"Aaron shrugged after Mary apologised.","zh":"Mary 道歉後，Aaron 聳了聳肩。"},{"en":"Shrug means lift the shoulders slightly, often to show acceptance, uncertainty or forgiveness.","zh":"Shrug 指輕輕抬起肩膀，常表示接受、不確定或原諒。"},{"en":"Aaron shrugged because he did not want to make Mary feel worse.","zh":"Aaron 聳肩，因為他不想令 Mary 更難受。"},{"en":"A shrug can say “it’s okay” without many words.","zh":"聳肩可以不用很多話就表示「沒關係」。"},{"en":"This phrase shows a quiet reaction.","zh":"這個短語顯示安靜的反應。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"his eyes softened","meaning":"他的眼神變柔和","examples":[{"en":"Aaron’s eyes softened when he understood Mary’s worry.","zh":"Aaron 明白 Mary 的擔心後，他的眼神變柔和。"},{"en":"His eyes softened means his expression became gentler and less angry.","zh":"His eyes softened 指他的表情變得更溫柔，不再那麼生氣。"},{"en":"A person’s eyes may soften when they realise someone acted out of love.","zh":"當一個人明白對方是出於愛而行動，眼神可能會變柔和。"},{"en":"Aaron understands that Mary followed him because she was worried.","zh":"Aaron 明白 Mary 跟着他是因為擔心。"},{"en":"This phrase shows forgiveness through expression.","zh":"這個短語透過表情顯示原諒。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"count for something","meaning":"仍然有點意義","examples":[{"en":"Aaron said Mary’s worry counted for something.","zh":"Aaron 說 Mary 的擔心仍然有點意義。"},{"en":"Count for something means still have value or meaning.","zh":"Count for something 指仍然有價值或意義。"},{"en":"Even if Mary was wrong, her concern counted for something.","zh":"即使 Mary 錯了，她的關心仍然有點意義。"},{"en":"A small apology counts for something when it is sincere.","zh":"真誠的小小道歉仍然有點意義。"},{"en":"This phrase offers forgiveness without denying the mistake.","zh":"這個短語在不否認錯誤的同時給予原諒。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"go home together","meaning":"一起回家","examples":[{"en":"That evening, Mary and Aaron went home together.","zh":"那天晚上，Mary 和 Aaron 一起回家。"},{"en":"Go home together means return to the same home with another person.","zh":"Go home together 指與另一個人一起回到同一個家。"},{"en":"After the misunderstanding, going home together shows the siblings are close again.","zh":"誤會之後一起回家，顯示兄妹關係重新拉近。"},{"en":"A shared journey home can feel like quiet reconciliation.","zh":"一同回家的路程可以像安靜的和解。"},{"en":"This phrase marks emotional repair.","zh":"這個短語標示情感修復。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"by minibus","meaning":"乘小巴","examples":[{"en":"They went home by minibus, not sports car.","zh":"他們乘小巴回家，而不是坐跑車。"},{"en":"By minibus means using a minibus as transport.","zh":"By minibus 指以小巴作為交通工具。"},{"en":"Going home by minibus shows Aaron does not live a glamorous life.","zh":"乘小巴回家顯示 Aaron 並沒有過着光鮮生活。"},{"en":"The contrast between sports car and minibus reveals the truth about his situation.","zh":"跑車和小巴的對比揭示他的真實處境。"},{"en":"This phrase grounds the ending in ordinary life.","zh":"這個短語把結尾拉回普通生活。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"secret fortune","meaning":"秘密財富","examples":[{"en":"Aaron carried no secret fortune.","zh":"Aaron 沒有帶着任何秘密財富。"},{"en":"A secret fortune means hidden wealth that other people do not know about.","zh":"Secret fortune 指別人不知道的隱藏財富。"},{"en":"Mary imagined a secret fortune when she saw the expensive car.","zh":"Mary 看見昂貴汽車時，想像他有秘密財富。"},{"en":"Aaron has no secret fortune; he only has a meaningful but low-paid job.","zh":"Aaron 沒有秘密財富；他只有一份有意義但薪酬低的工作。"},{"en":"This phrase corrects the idea that appearance proves wealth.","zh":"這個短語糾正外表能證明財富的想法。"}],"source":"2012 Q7.pdf","sourcePage":14},{"front":"no miracle","meaning":"沒有奇蹟","examples":[{"en":"Aaron carried no miracle, only a job badge and a tired smile.","zh":"Aaron 沒有帶着奇蹟，只有工作證和疲倦的笑容。"},{"en":"No miracle means there was no sudden magical solution to his problems.","zh":"No miracle 指沒有突然出現的魔法般解決方法。"},{"en":"Aaron did not become rich overnight; there was no miracle.","zh":"Aaron 沒有一夜之間變富；沒有奇蹟。"},{"en":"His life improved through a small chance, not a perfect rescue.","zh":"他的生活是因一個小機會而改善，不是被完美拯救。"},{"en":"This phrase keeps the ending honest and realistic.","zh":"這個短語令結尾保持誠實和現實。"}],"source":"2012 Q7.pdf","sourcePage":15},{"front":"job badge","meaning":"工作證","examples":[{"en":"Aaron carried only a job badge in his pocket.","zh":"Aaron 口袋裏只帶着一張工作證。"},{"en":"A job badge is an identification card or tag showing someone’s workplace role.","zh":"Job badge 指顯示某人工作身份的識別證或名牌。"},{"en":"Aaron’s job badge proves he works for the foundation.","zh":"Aaron 的工作證證明他為基金會工作。"},{"en":"A job badge may look small, but it can represent dignity and responsibility.","zh":"工作證看似細小，但可以代表尊嚴和責任。"},{"en":"This phrase replaces the mystery of the car key with ordinary work.","zh":"這個短語以普通工作取代車匙的神秘感。"}],"source":"2012 Q7.pdf","sourcePage":15},{"front":"tired smile","meaning":"疲倦的笑容","examples":[{"en":"Aaron carried a tired smile home with him.","zh":"Aaron 帶着疲倦的笑容回家。"},{"en":"A tired smile is a weak but warm smile from someone who is exhausted.","zh":"Tired smile 指疲累的人露出的微弱但溫暖的笑容。"},{"en":"After helping Chloe, Aaron’s tired smile shows both effort and kindness.","zh":"幫助 Chloe 後，Aaron 疲倦的笑容顯示努力和善意。"},{"en":"A tired smile can be more honest than a proud smile.","zh":"疲倦的笑容可以比驕傲的笑容更真實。"},{"en":"This phrase shows quiet emotional richness.","zh":"這個短語顯示安靜的情感豐富。"}],"source":"2012 Q7.pdf","sourcePage":15},{"front":"in his pocket","meaning":"在他的口袋裏","examples":[{"en":"The key was in Aaron’s pocket.","zh":"鑰匙在 Aaron 的口袋裏。"},{"en":"In his pocket means inside the small cloth space in his clothes.","zh":"In his pocket 指在他衣服上的小布袋空間裏。"},{"en":"A key in his pocket made Mary think the car belonged to him.","zh":"口袋裏的鑰匙令 Mary 以為那輛車屬於他。"},{"en":"Small objects in a pocket can carry big meaning in a story.","zh":"故事中，口袋裏的小物件可以帶有重大意義。"},{"en":"This phrase gives a precise location for an important clue.","zh":"這個短語為重要線索提供確切位置。"}],"source":"2012 Q7.pdf","sourcePage":15},{"front":"never his","meaning":"從來不屬於他","examples":[{"en":"The key was never his.","zh":"那條鑰匙從來不屬於他。"},{"en":"Never his means it did not belong to him at any time.","zh":"Never his 指在任何時候都不屬於他。"},{"en":"The car looked connected to Aaron, but the key was never truly his.","zh":"那輛車看似與 Aaron 有關，但鑰匙從來不真正屬於他。"},{"en":"This phrase corrects the false story Mary had imagined.","zh":"這個短語糾正 Mary 想像出來的錯誤故事。"},{"en":"It shows the difference between carrying something and owning it.","zh":"它顯示帶着某物和擁有某物之間的分別。"}],"source":"2012 Q7.pdf","sourcePage":15},{"front":"in my eyes","meaning":"在我眼中","examples":[{"en":"In Mary’s eyes, Aaron had never looked richer.","zh":"在 Mary 眼中，Aaron 從未顯得如此富有。"},{"en":"In my eyes means from my point of view or in my opinion.","zh":"In my eyes 指從我的角度或在我看來。"},{"en":"In Mary’s eyes, Aaron became richer because he was kind, not because he owned a car.","zh":"在 Mary 眼中，Aaron 因善良而變得富有，不是因為擁有汽車。"},{"en":"A person can look valuable in someone’s eyes because of character rather than money.","zh":"一個人在別人眼中可以因品格而顯得有價值，而不是因金錢。"},{"en":"This phrase marks a personal judgement.","zh":"這個短語標示個人判斷。"}],"source":"2012 Q7.pdf","sourcePage":15},{"front":"had never looked richer","meaning":"從未顯得如此富有","examples":[{"en":"Although Aaron was poor, he had never looked richer.","zh":"雖然 Aaron 貧窮，但他從未顯得如此富有。"},{"en":"Had never looked richer means had never seemed more valuable, admirable or rich in character.","zh":"Had never looked richer 指從未顯得如此有價值、令人敬佩或品格富足。"},{"en":"Aaron looked richer when Mary saw how gently he treated Chloe.","zh":"當 Mary 看見 Aaron 如何溫柔地對待 Chloe，他顯得更富有。"},{"en":"True richness can come from kindness, responsibility and purpose.","zh":"真正的富足可以來自善良、責任和目的。"},{"en":"This phrase gives the story its final lesson about real worth.","zh":"這個短語帶出故事關於真正價值的最後教訓。"}],"source":"2012 Q7.pdf","sourcePage":15}],"dse/writing/part-b/2012/Q8":[{"front":"second chance","meaning":"第二次機會","examples":[{"en":"The campaign gives rehabilitated persons a second chance.","zh":"這項運動給予更生人士第二次機會。"},{"en":"A second chance means another opportunity to improve after a mistake or failure.","zh":"第二次機會是指在犯錯或失敗後，再次得到改善的機會。"},{"en":"A student who failed once may need a second chance to show that they have changed.","zh":"曾經失敗的學生可能需要第二次機會，去證明自己已經改變。"},{"en":"A second chance can help people rebuild confidence, responsibility, and trust.","zh":"第二次機會可以幫助人重建信心、責任和信任。"},{"en":"This phrase shows hope because a person’s past does not have to decide their future.","zh":"這個短語顯示希望，因為一個人的過去不必決定他的未來。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"stronger business","meaning":"更強大的企業","examples":[{"en":"Fair employment can help build a stronger business.","zh":"公平就業可以幫助建立更強大的企業。"},{"en":"A stronger business is a company that becomes more reliable, respected, and effective.","zh":"更強大的企業是指變得更可靠、更受尊重和更有效率的公司。"},{"en":"Hiring loyal workers can help a small shop become a stronger business.","zh":"聘請忠誠員工可以幫助小店成為更強大的企業。"},{"en":"A business becomes stronger when it has committed staff and public trust.","zh":"當企業擁有投入的員工和公眾信任時，就會變得更強大。"},{"en":"This phrase connects fairness with practical business success.","zh":"這個短語把公平與實際商業成功連接起來。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"business leaders","meaning":"商界領袖","examples":[{"en":"The letter is addressed to Hong Kong business leaders.","zh":"這封信是寫給香港商界領袖的。"},{"en":"Business leaders are people who guide companies, industries, or commercial decisions.","zh":"商界領袖是引導公司、行業或商業決定的人。"},{"en":"Business leaders can influence hiring practices and workplace culture.","zh":"商界領袖可以影響招聘做法和職場文化。"},{"en":"When business leaders support fair employment, other companies may follow.","zh":"當商界領袖支持公平就業時，其他公司可能會跟隨。"},{"en":"This phrase identifies the people who have power to create job opportunities.","zh":"這個短語指出有能力創造就業機會的人。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"have long been admired for","meaning":"一直因……而備受讚賞","examples":[{"en":"Hong Kong has long been admired for turning pressure into progress.","zh":"香港一直因化壓力為進步而備受讚賞。"},{"en":"Have long been admired for means have been respected for a particular quality over many years.","zh":"一直因……而備受讚賞，是指多年來因某種特質而受到尊重。"},{"en":"A school may have long been admired for helping weak students improve.","zh":"一所學校可能一直因幫助能力較弱的學生進步而備受讚賞。"},{"en":"A city is admired for resilience when it faces difficulty and still develops.","zh":"當城市面對困難仍能發展時，會因韌性而受人欣賞。"},{"en":"This phrase shows lasting respect, not sudden praise.","zh":"這個短語顯示持久的尊重，而不是突然的讚美。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"turn pressure into progress","meaning":"化壓力為進步","examples":[{"en":"Hong Kong is admired for turning pressure into progress.","zh":"香港因化壓力為進步而備受讚賞。"},{"en":"To turn pressure into progress means to use difficulty as a reason to improve.","zh":"化壓力為進步，是指把困難用作改善的原因。"},{"en":"A student turns pressure into progress when exam stress leads to better study habits.","zh":"當學生因考試壓力而建立更好的學習習慣時，就是化壓力為進步。"},{"en":"Businesses can turn pressure into progress by solving problems instead of complaining.","zh":"企業可以透過解決問題而不是抱怨，化壓力為進步。"},{"en":"This phrase shows that hardship can become a force for improvement.","zh":"這個短語顯示困難可以變成改善的力量。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"one group is still too often left outside","meaning":"有一群人仍經常被排拒於……之外","examples":[{"en":"One group is still too often left outside the workplace.","zh":"有一群人仍經常被排拒於職場之外。"},{"en":"One group is left outside means a certain group is excluded or not given fair access.","zh":"有一群人被排拒於外，是指某個群體被排除，或沒有得到公平使用機會。"},{"en":"Young workers without experience may be left outside good job opportunities.","zh":"沒有經驗的年輕工人可能被排拒於好工作機會之外。"},{"en":"When rehabilitated persons are left outside the workplace, society loses their possible contribution.","zh":"當更生人士被排拒於職場之外時，社會會失去他們可能作出的貢獻。"},{"en":"This phrase highlights unfair exclusion that happens repeatedly.","zh":"這個短語突出反覆發生的不公平排斥。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"the workplace","meaning":"職場","examples":[{"en":"Rehabilitated persons are often left outside the workplace.","zh":"更生人士經常被排拒於職場之外。"},{"en":"The workplace is the place or environment where people do their jobs.","zh":"職場是人們工作的地方或環境。"},{"en":"A workplace can be an office, restaurant, factory, shop, or school.","zh":"職場可以是辦公室、餐廳、工廠、商店或學校。"},{"en":"A fair workplace gives people clear rules, supervision, and respect.","zh":"公平的職場會給人清晰規則、監督和尊重。"},{"en":"This word focuses on employment as part of everyday social life.","zh":"這個詞著重就業作為日常社會生活的一部分。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"reformed offenders","meaning":"改過自新的違法者","examples":[{"en":"Reformed offenders deserve fair employment opportunities.","zh":"改過自新的違法者值得得到公平就業機會。"},{"en":"Reformed offenders are people who committed offences in the past but have changed their behaviour.","zh":"改過自新的違法者是過去曾犯法，但已改變行為的人。"},{"en":"A reformed offender may need a job to prove responsibility and rebuild trust.","zh":"改過自新的違法者可能需要一份工作來證明責任感並重建信任。"},{"en":"Fair hiring helps reformed offenders return to normal routines.","zh":"公平招聘幫助改過自新的違法者重返正常生活規律。"},{"en":"This phrase asks readers to judge people by change, not only by past mistakes.","zh":"這個短語要求讀者根據改變來評價人，而不只是根據過去錯誤。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"rehabilitated former drug abusers","meaning":"戒毒康復者","examples":[{"en":"Rehabilitated former drug abusers may be ready to rebuild their lives.","zh":"戒毒康復者可能已準備好重建人生。"},{"en":"Rehabilitated former drug abusers are people who previously abused drugs but have received treatment and changed.","zh":"戒毒康復者是過去曾濫用毒品，但已接受治療並改變的人。"},{"en":"A rehabilitated former drug abuser may need stable work to stay away from drugs.","zh":"戒毒康復者可能需要穩定工作來遠離毒品。"},{"en":"Employment can support rehabilitation by giving structure, income, and dignity.","zh":"就業可以透過提供規律、收入和尊嚴來支援更生。"},{"en":"This phrase highlights recovery and readiness, not only past addiction.","zh":"這個短語突出康復和準備程度，而不只是過往毒癮。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"be ready to rebuild their lives","meaning":"準備好重建人生","examples":[{"en":"Many rehabilitated persons are ready to rebuild their lives.","zh":"許多更生人士已準備好重建人生。"},{"en":"To be ready to rebuild their lives means to be prepared to create a better future after hardship or mistakes.","zh":"準備好重建人生，是指在困難或錯誤後，準備創造更好的未來。"},{"en":"A person leaving treatment may be ready to rebuild their life through work and stable routines.","zh":"離開戒毒治療的人可能準備透過工作和穩定規律重建人生。"},{"en":"People need real opportunities when they are ready to rebuild.","zh":"當人們準備好重建人生時，他們需要真正機會。"},{"en":"This phrase shows willingness, hope, and practical change.","zh":"這個短語顯示意願、希望和實際改變。"}],"source":"2012 Q8.pdf","sourcePage":1},{"front":"support their reintegration","meaning":"支援他們重新融入社會","examples":[{"en":"The campaign supports their reintegration into society.","zh":"這項運動支援他們重新融入社會。"},{"en":"To support their reintegration means to help people return to normal social, family, and working life.","zh":"支援他們重新融入社會，是指幫助人回到正常社交、家庭和工作生活。"},{"en":"Employment supports reintegration by giving people routines and responsibility.","zh":"就業透過給予生活規律和責任，支援重新融入社會。"},{"en":"Without support, reintegration may become much harder after release or treatment.","zh":"沒有支援，人在獲釋或治療後重新融入社會可能困難得多。"},{"en":"This phrase shows that returning to society requires help, not only personal effort.","zh":"這個短語顯示重返社會需要幫助，而不只是個人努力。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"reintegration","meaning":"重新融入社會","examples":[{"en":"Employment is important for successful reintegration.","zh":"就業對成功重新融入社會十分重要。"},{"en":"Reintegration means returning to society and becoming part of normal community life again.","zh":"重新融入社會是指返回社會，並再次成為正常社區生活的一部分。"},{"en":"Reintegration may include finding work, reconnecting with family, and following daily routines.","zh":"重新融入社會可能包括找工作、重新連繫家人和遵守日常規律。"},{"en":"A stable job can make reintegration more realistic and lasting.","zh":"穩定工作可以令重新融入社會更實際和持久。"},{"en":"This word focuses on rebuilding belonging after separation or difficulty.","zh":"這個詞著重人在分離或困難後重建歸屬感。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"launch a campaign","meaning":"推出一項運動","examples":[{"en":"The Government has launched a campaign called Second Chance.","zh":"政府推出了一項名為「第二次機會」的運動。"},{"en":"To launch a campaign means to start an organised effort to change behaviour or raise awareness.","zh":"推出一項運動，是指開始一個有組織的行動，以改變行為或提高意識。"},{"en":"A school may launch a campaign to reduce bullying and encourage kindness.","zh":"學校可能推出一項運動來減少欺凌並鼓勵善意。"},{"en":"Launching a campaign gives a social issue public attention and structure.","zh":"推出運動能為社會議題帶來公共關注和結構。"},{"en":"This phrase shows the beginning of an organised public action.","zh":"這個短語顯示有組織公共行動的開始。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"encourage local businesses to","meaning":"鼓勵本地企業去","examples":[{"en":"The campaign encourages local businesses to offer suitable employment.","zh":"這項運動鼓勵本地企業提供合適就業機會。"},{"en":"To encourage local businesses to do something means to invite and motivate nearby companies to take action.","zh":"鼓勵本地企業去做某事，是指邀請並推動附近公司採取行動。"},{"en":"A district campaign may encourage local businesses to hire young apprentices.","zh":"地區運動可能鼓勵本地企業聘請年輕學徒。"},{"en":"Encouraging businesses works best when support and guidance are also provided.","zh":"當同時提供支援和指引時，鼓勵企業會最有效。"},{"en":"This phrase shows cooperation between public policy and private companies.","zh":"這個短語顯示公共政策與私人企業之間的合作。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"suitable employment","meaning":"合適就業機會","examples":[{"en":"Second Chance encourages businesses to offer suitable employment.","zh":"「第二次機會」鼓勵企業提供合適就業機會。"},{"en":"Suitable employment means a job that matches a person’s skills, readiness, and situation.","zh":"合適就業機會是指符合一個人的技能、準備程度和情況的工作。"},{"en":"A simple kitchen post may be suitable employment for someone rebuilding work habits.","zh":"對正在重建工作習慣的人來說，簡單廚房職位可能是合適就業機會。"},{"en":"Suitable employment protects both the employer and employee because expectations are realistic.","zh":"合適就業能保護僱主和僱員，因為期望是實際的。"},{"en":"This phrase stresses careful matching, not careless hiring.","zh":"這個短語強調小心配對，而不是草率招聘。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"rehabilitated persons","meaning":"更生人士","examples":[{"en":"Rehabilitated persons should be judged by their present capability.","zh":"更生人士應按他們的現有能力被評估。"},{"en":"Rehabilitated persons are people who have gone through a process of correction, treatment, or recovery.","zh":"更生人士是經歷矯正、治療或康復過程的人。"},{"en":"Rehabilitated persons may need employment to rebuild routines and dignity.","zh":"更生人士可能需要就業來重建生活規律和尊嚴。"},{"en":"Judging rehabilitated persons only by their past can block real change.","zh":"只用過去評價更生人士，可能阻礙真正改變。"},{"en":"This phrase focuses on recovery, responsibility, and a new start.","zh":"這個短語著重康復、責任和重新開始。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"intern at","meaning":"在……實習","examples":[{"en":"Chris Wong writes as an intern at Hong Kong Correctional Services.","zh":"Chris Wong 以香港懲教署實習生身份寫信。"},{"en":"To intern at an organisation means to work there temporarily to learn and gain experience.","zh":"在某機構實習，是指暫時在那裡工作，以學習和累積經驗。"},{"en":"A student may intern at a social service agency during the summer.","zh":"學生可能在暑假到社會服務機構實習。"},{"en":"Interning at a public department can help young people understand community issues.","zh":"在公共部門實習可以幫助年輕人理解社區議題。"},{"en":"This phrase identifies the writer’s training position.","zh":"這個短語指出作者的培訓職位。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"Hong Kong Correctional Services","meaning":"香港懲教署","examples":[{"en":"Chris Wong is an intern at Hong Kong Correctional Services.","zh":"Chris Wong 是香港懲教署的實習生。"},{"en":"Hong Kong Correctional Services refers to the public service responsible for correctional work and rehabilitation support.","zh":"香港懲教署是負責懲教工作和更生支援的公共服務機構。"},{"en":"Staff in correctional services may help people prepare for life after custody.","zh":"懲教服務人員可能幫助人為離開羈押後的生活作準備。"},{"en":"Mentioning Hong Kong Correctional Services gives the letter an official and relevant context.","zh":"提及香港懲教署，能為這封信提供正式和相關的背景。"},{"en":"This phrase identifies the organisation connected to rehabilitation work.","zh":"這個短語指出與更生工作有關的機構。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"invite your company to join","meaning":"邀請貴公司加入","examples":[{"en":"The writer invites each company to join the scheme.","zh":"作者邀請每間公司加入這項計劃。"},{"en":"To invite your company to join means to formally ask a business to take part.","zh":"邀請貴公司加入，是指正式請求企業參與。"},{"en":"A charity may invite a company to join a youth employment programme.","zh":"慈善機構可能邀請公司加入青年就業計劃。"},{"en":"This phrase sounds polite because the company still has the choice to decide.","zh":"這個短語聽起來有禮貌，因為公司仍可自行決定。"},{"en":"It introduces the main request of the letter.","zh":"它引出信件的主要請求。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"join this scheme","meaning":"加入這項計劃","examples":[{"en":"Local businesses are invited to join this scheme.","zh":"本地企業獲邀加入這項計劃。"},{"en":"To join this scheme means to take part in an organised programme with rules and support.","zh":"加入這項計劃，是指參與一個有規則和支援的有組織項目。"},{"en":"A restaurant may join this scheme by registering suitable vacancies.","zh":"餐廳可以透過登記合適職位空缺加入這項計劃。"},{"en":"Joining the scheme can help employers hire fairly with guidance.","zh":"加入這項計劃可以幫助僱主在有指引下公平招聘。"},{"en":"This phrase shows participation in a structured campaign.","zh":"這個短語顯示參與一項有結構的運動。"}],"source":"2012 Q8.pdf","sourcePage":2},{"front":"so as to","meaning":"以便；為了","examples":[{"en":"The company can join the scheme so as to strengthen its workforce.","zh":"公司可以加入這項計劃，以便加強員工隊伍。"},{"en":"So as to means in order to or for the purpose of doing something.","zh":"以便或為了，是指帶着某個目的去做某事。"},{"en":"A company may provide training so as to help new workers adjust.","zh":"公司可能提供培訓，以便幫助新員工適應。"},{"en":"Writers use so as to when they want to explain the purpose behind an action.","zh":"作者想解釋行動背後目的時，會使用這個短語。"},{"en":"This phrase links participation with a clear benefit.","zh":"這個短語把參與和清晰好處連接起來。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"strengthen your workforce","meaning":"加強貴公司的員工隊伍","examples":[{"en":"The scheme can help companies strengthen their workforce.","zh":"這項計劃可以幫助公司加強員工隊伍。"},{"en":"To strengthen your workforce means to make your group of employees more capable, stable, or committed.","zh":"加強員工隊伍，是指令僱員群體更有能力、更穩定或更投入。"},{"en":"Hiring reliable workers can strengthen a restaurant’s workforce during busy periods.","zh":"聘請可靠員工可以在繁忙時段加強餐廳的員工隊伍。"},{"en":"Training and fair opportunities help workers become more useful to the company.","zh":"培訓和公平機會能幫助員工對公司更有用。"},{"en":"This phrase shows a practical business reason for joining the scheme.","zh":"這個短語顯示加入計劃的實際商業理由。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"enhance your reputation","meaning":"提升貴公司的聲譽","examples":[{"en":"Joining the scheme may enhance a company’s reputation.","zh":"加入這項計劃可能提升公司的聲譽。"},{"en":"To enhance your reputation means to improve how people see and respect your company.","zh":"提升貴公司的聲譽，是指改善人們如何看待和尊重貴公司。"},{"en":"A business can enhance its reputation by treating workers fairly and supporting the community.","zh":"企業可以透過公平對待員工和支援社區來提升聲譽。"},{"en":"Reputation is enhanced when actions show values clearly.","zh":"當行動清楚顯示價值時，聲譽會得到提升。"},{"en":"This phrase connects social responsibility with public respect.","zh":"這個短語把社會責任與公眾尊重連接起來。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"create a safer community","meaning":"建立更安全的社區","examples":[{"en":"The scheme can help create a safer community.","zh":"這項計劃可以幫助建立更安全的社區。"},{"en":"To create a safer community means to help make society more stable, secure, and supportive.","zh":"建立更安全的社區，是指幫助社會變得更穩定、安全和有支援。"},{"en":"Employment can create a safer community by reducing isolation and temptation.","zh":"就業可以透過減少孤立和誘惑來建立更安全的社區。"},{"en":"When people have lawful work, they are more likely to rebuild stable lives.","zh":"當人們有合法工作時，他們更可能重建穩定生活。"},{"en":"This phrase connects individual opportunity with public safety.","zh":"這個短語把個人機會與公共安全連接起來。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"fair employment","meaning":"公平就業","examples":[{"en":"Fair employment can change people’s futures.","zh":"公平就業可以改變人的未來。"},{"en":"Fair employment means giving people job opportunities based on ability, readiness, and conduct rather than prejudice.","zh":"公平就業是指根據能力、準備程度和行為給予工作機會，而不是根據偏見。"},{"en":"Fair employment allows a person with a difficult past to be judged by present effort.","zh":"公平就業讓有困難過去的人按現時努力被評價。"},{"en":"When employers practise fair employment, they widen opportunity and reduce exclusion.","zh":"當僱主實踐公平就業時，他們會擴大機會並減少排斥。"},{"en":"This phrase links justice with practical hiring.","zh":"這個短語把公義與實際招聘連接起來。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"turn past mistakes into future contributions","meaning":"把過去的錯誤轉化為未來的貢獻","examples":[{"en":"Fair employment can turn past mistakes into future contributions.","zh":"公平就業可以把過去的錯誤轉化為未來的貢獻。"},{"en":"To turn past mistakes into future contributions means to help people learn from failure and give back to society.","zh":"把過去的錯誤轉化為未來的貢獻，是指幫助人從失敗中學習並回饋社會。"},{"en":"A former offender may turn past mistakes into future contributions by mentoring at-risk youth.","zh":"前違法者可以透過輔導高危青年，把過去錯誤轉化為未來貢獻。"},{"en":"Employment gives people a way to prove change through useful work.","zh":"就業給人一條透過有用工作證明改變的路。"},{"en":"This phrase shows transformation from regret to responsibility.","zh":"這個短語顯示由後悔轉向責任的轉化。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"under Second Chance","meaning":"在「第二次機會」計劃下","examples":[{"en":"Under Second Chance, businesses may register vacancies.","zh":"在「第二次機會」計劃下，企業可以登記職位空缺。"},{"en":"Under Second Chance means within the rules or arrangements of the Second Chance campaign.","zh":"在「第二次機會」計劃下，是指在該運動的規則或安排之中。"},{"en":"Under the scheme, employers can receive guidance before hiring candidates.","zh":"在計劃下，僱主可以在招聘候選人前獲得指引。"},{"en":"This phrase tells readers that the action is part of an organised programme.","zh":"這個短語告訴讀者，該行動屬於有組織計劃的一部分。"},{"en":"It makes the process sound structured rather than casual.","zh":"它令過程聽起來有結構，而不是隨意。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"participating businesses","meaning":"參與企業","examples":[{"en":"Participating businesses may attend briefing sessions.","zh":"參與企業可以出席簡介會。"},{"en":"Participating businesses are companies that have joined or are taking part in a scheme.","zh":"參與企業是已加入或正在參與某項計劃的公司。"},{"en":"Participating businesses may register vacancies and interview recommended candidates.","zh":"參與企業可以登記職位空缺，並面見獲推薦的候選人。"},{"en":"These businesses receive information so they can hire with clearer expectations.","zh":"這些企業會收到資訊，好讓它們以更清晰期望招聘。"},{"en":"This phrase identifies companies actively involved in the campaign.","zh":"這個短語指出積極參與運動的公司。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"register vacancies","meaning":"登記職位空缺","examples":[{"en":"Businesses may register vacancies under the scheme.","zh":"企業可以在計劃下登記職位空缺。"},{"en":"To register vacancies means to officially list available job openings.","zh":"登記職位空缺是指正式列出可供申請的工作崗位。"},{"en":"A restaurant may register vacancies for kitchen helpers or cleaners.","zh":"餐廳可以登記廚房助理或清潔員的職位空缺。"},{"en":"Registering vacancies helps officers match candidates with suitable posts.","zh":"登記職位空缺有助人員把候選人與合適職位配對。"},{"en":"This phrase describes the first practical step for employers.","zh":"這個短語描述僱主的第一個實際步驟。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"attend briefing sessions","meaning":"出席簡介會","examples":[{"en":"Employers can attend briefing sessions before interviewing candidates.","zh":"僱主可以在面見候選人前出席簡介會。"},{"en":"To attend briefing sessions means to join meetings where important information and guidance are explained.","zh":"出席簡介會是指參加解釋重要資訊和指引的會議。"},{"en":"Employers may attend briefing sessions to learn about support, matching, and workplace adjustment.","zh":"僱主可能出席簡介會，了解支援、配對和適應職場安排。"},{"en":"Briefing sessions reduce uncertainty before hiring begins.","zh":"簡介會在招聘開始前減少不確定性。"},{"en":"This phrase shows that the scheme provides preparation, not just candidates.","zh":"這個短語顯示計劃提供準備，而不只是候選人。"}],"source":"2012 Q8.pdf","sourcePage":3},{"front":"interview recommended candidates","meaning":"面見獲推薦的候選人","examples":[{"en":"Businesses may interview recommended candidates.","zh":"企業可以面見獲推薦的候選人。"},{"en":"To interview recommended candidates means to meet suggested applicants and assess whether they fit the job.","zh":"面見獲推薦的候選人，是指與被建議的申請人見面，評估他們是否適合工作。"},{"en":"An employer may interview recommended candidates after reading their work history and skills.","zh":"僱主可能在閱讀工作經驗和技能後，面見獲推薦的候選人。"},{"en":"Interviews allow both sides to ask questions before making a decision.","zh":"面試讓雙方在作決定前提問。"},{"en":"This phrase shows a normal hiring step within a supported scheme.","zh":"這個短語顯示支援計劃中的正常招聘步驟。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"receive follow-up support","meaning":"獲得跟進支援","examples":[{"en":"Employers can receive follow-up support from rehabilitation officers.","zh":"僱主可以從更生輔導人員獲得跟進支援。"},{"en":"To receive follow-up support means to get continued help after the first step or decision.","zh":"獲得跟進支援，是指在第一步或決定之後繼續得到幫助。"},{"en":"A company may receive follow-up support after hiring a new worker from the scheme.","zh":"公司在透過計劃聘請新員工後，可以獲得跟進支援。"},{"en":"Follow-up support helps small problems be handled before they grow.","zh":"跟進支援幫助小問題在變大前被處理。"},{"en":"This phrase reassures employers that they will not be left alone.","zh":"這個短語讓僱主放心，知道自己不會被獨自留下。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"rehabilitation officers","meaning":"更生輔導人員","examples":[{"en":"Rehabilitation officers can support both employers and employees.","zh":"更生輔導人員可以支援僱主和僱員雙方。"},{"en":"Rehabilitation officers are trained staff who help rehabilitated persons return to society and work.","zh":"更生輔導人員是受過訓練、幫助更生人士重返社會和工作的職員。"},{"en":"They may advise employers, follow up on workplace adjustment, and support new employees.","zh":"他們可能向僱主提供建議、跟進職場適應，並支援新僱員。"},{"en":"Rehabilitation officers help make hiring clearer, safer, and more practical.","zh":"更生輔導人員幫助令招聘更清晰、安全和實際。"},{"en":"This phrase identifies the professionals who guide the process.","zh":"這個短語指出引導過程的專業人員。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"be matched according to","meaning":"根據……作配對","examples":[{"en":"Applicants will be matched according to their skills and readiness.","zh":"申請人會根據技能和準備程度作配對。"},{"en":"Be matched according to means be paired or selected based on particular qualities or information.","zh":"根據某些條件作配對，是指按特定特質或資訊配合或選擇。"},{"en":"Job applicants may be matched according to experience, work attitude, and training needs.","zh":"求職者可能根據經驗、工作態度和培訓需要作配對。"},{"en":"Matching candidates carefully reduces risk for both employers and employees.","zh":"小心配對候選人能減少僱主和僱員雙方的風險。"},{"en":"This phrase shows that placement is guided by evidence, not guesswork.","zh":"這個短語顯示安置是按證據指引，而不是猜測。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"work attitude","meaning":"工作態度","examples":[{"en":"Work attitude is considered when applicants are matched with vacancies.","zh":"申請人與職位空缺配對時，工作態度會被考慮。"},{"en":"Work attitude means how a person approaches work, including responsibility, punctuality, and willingness to learn.","zh":"工作態度是指一個人如何對待工作，包括責任感、守時和學習意願。"},{"en":"A person with a good work attitude arrives on time and follows instructions carefully.","zh":"工作態度好的人會準時到達並仔細跟從指示。"},{"en":"Skills matter, but work attitude often decides whether someone grows in a job.","zh":"技能很重要，但工作態度常決定一個人能否在工作中成長。"},{"en":"This phrase focuses on behaviour and mindset at work.","zh":"這個短語著重工作中的行為和心態。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"readiness for employment","meaning":"就業準備程度","examples":[{"en":"The scheme considers each applicant’s readiness for employment.","zh":"這項計劃會考慮每位申請人的就業準備程度。"},{"en":"Readiness for employment means how prepared someone is to start and keep a job.","zh":"就業準備程度是指某人準備開始和維持工作的程度。"},{"en":"Readiness may include punctuality, basic skills, emotional stability, and willingness to follow rules.","zh":"準備程度可能包括守時、基本技能、情緒穩定和遵守規則的意願。"},{"en":"Assessing readiness helps employers choose suitable posts and support levels.","zh":"評估準備程度有助僱主選擇合適職位和支援水平。"},{"en":"This phrase shows that hiring should match a person’s current stage.","zh":"這個短語顯示招聘應配合一個人的現階段情況。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"be left to make decisions without guidance","meaning":"被迫在沒有指引下作決定","examples":[{"en":"Employers are not left to make decisions without guidance.","zh":"僱主不會被迫在沒有指引下作決定。"},{"en":"To be left to make decisions without guidance means to have to decide alone without advice or support.","zh":"被迫在沒有指引下作決定，是指必須在沒有建議或支援下獨自決定。"},{"en":"Small businesses may feel worried if they are left to hire unfamiliar candidates without guidance.","zh":"如果小企業被迫在沒有指引下面試不熟悉的候選人，可能會感到擔心。"},{"en":"The scheme reduces this worry by offering briefings and follow-up support.","zh":"這項計劃透過簡介會和跟進支援減少這種憂慮。"},{"en":"This phrase reassures employers that help is available.","zh":"這個短語讓僱主放心，知道有幫助可用。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"from hiring to workplace adjustment","meaning":"從招聘到適應職場","examples":[{"en":"Support is provided from hiring to workplace adjustment.","zh":"支援會從招聘到適應職場整個過程提供。"},{"en":"From hiring to workplace adjustment means throughout the process from recruitment to helping the worker settle into the job.","zh":"從招聘到適應職場，是指由招聘到幫助員工安頓工作的整個過程。"},{"en":"A support officer may help from the first interview to the first weeks at work.","zh":"支援人員可能由第一次面試到上班首幾星期提供幫助。"},{"en":"This kind of support makes employment more stable after the job offer is made.","zh":"這類支援令工作聘用後更穩定。"},{"en":"This phrase shows that the scheme continues beyond recruitment.","zh":"這個短語顯示計劃不只停留在招聘階段。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"workplace adjustment","meaning":"適應職場","examples":[{"en":"Rehabilitation officers can help with workplace adjustment.","zh":"更生輔導人員可以協助適應職場。"},{"en":"Workplace adjustment means the process of getting used to job duties, rules, colleagues, and routines.","zh":"適應職場是指習慣工作職責、規則、同事和日常規律的過程。"},{"en":"A new employee may need workplace adjustment when learning shift times and workplace expectations.","zh":"新員工在學習輪班時間和職場期望時，可能需要適應職場。"},{"en":"Support during workplace adjustment can prevent misunderstandings and early resignation.","zh":"適應職場期間的支援可以防止誤解和過早辭職。"},{"en":"This phrase focuses on settling into real daily work.","zh":"這個短語著重安頓於真實日常工作之中。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"make recruitment clear, safe and practical","meaning":"令招聘清晰、安全而實際可行","examples":[{"en":"The project aims to make recruitment clear, safe and practical.","zh":"這項計劃旨在令招聘清晰、安全而實際可行。"},{"en":"To make recruitment clear, safe and practical means to make hiring understandable, low-risk, and workable.","zh":"令招聘清晰、安全而實際可行，是指令招聘易明、低風險並能實際運作。"},{"en":"Briefings and candidate matching can make recruitment clearer for employers.","zh":"簡介會和候選人配對可以令僱主更清楚招聘過程。"},{"en":"Safety and practicality matter because employers need confidence before joining.","zh":"安全和實際可行很重要，因為僱主加入前需要信心。"},{"en":"This phrase explains the scheme’s purpose from the employer’s point of view.","zh":"這個短語從僱主角度解釋計劃目的。"}],"source":"2012 Q8.pdf","sourcePage":4},{"front":"lower your standards","meaning":"降低標準","examples":[{"en":"There is no need for companies to lower their standards.","zh":"公司不需要降低標準。"},{"en":"To lower your standards means to accept weaker quality or poorer behaviour than usual.","zh":"降低標準是指接受比平常較低的質素或較差的行為。"},{"en":"A company does not lower its standards when it hires fairly and still requires punctuality.","zh":"公司公平招聘但仍要求守時，並不是降低標準。"},{"en":"Fair employment means judging properly, not accepting unsafe or unsuitable work.","zh":"公平就業是正確評估，而不是接受不安全或不合適的工作表現。"},{"en":"This phrase answers employers who fear the scheme asks too much of them.","zh":"這個短語回應擔心計劃要求過高的僱主。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"rather","meaning":"而是","examples":[{"en":"The scheme does not ask companies to lower standards; rather, it asks them to judge fairly.","zh":"這項計劃不是要求公司降低標準；而是要求它們公平評估。"},{"en":"Rather is used to correct one idea and replace it with a more accurate one.","zh":"Rather 用來修正一個想法，並用更準確的想法取代它。"},{"en":"The scheme is not about pity; rather, it is about fair assessment and support.","zh":"這項計劃不是關於憐憫；而是關於公平評估和支援。"},{"en":"Writers use rather when they want to guide readers away from a misunderstanding.","zh":"作者想引導讀者離開誤解時，會使用 rather。"},{"en":"This word sharpens the contrast between wrong and right explanations.","zh":"這個詞加強錯誤解釋與正確解釋之間的對比。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"judge candidates by","meaning":"根據……評估候選人","examples":[{"en":"Companies should judge candidates by their present capability.","zh":"公司應根據候選人的現有能力評估他們。"},{"en":"To judge candidates by something means to assess applicants according to that quality or evidence.","zh":"根據某事評估候選人，是指按那種特質或證據評估申請人。"},{"en":"Employers should judge candidates by skills, attitude, and readiness, not gossip.","zh":"僱主應根據技能、態度和準備程度評估候選人，而不是根據傳言。"},{"en":"Fair judgement helps companies find workers who may otherwise be overlooked.","zh":"公平評估幫助公司找到原本可能被忽視的員工。"},{"en":"This phrase shows the basis for responsible hiring.","zh":"這個短語顯示負責任招聘的基礎。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"present capability","meaning":"現有能力","examples":[{"en":"Employers should consider a candidate’s present capability.","zh":"僱主應考慮候選人的現有能力。"},{"en":"Present capability means what someone is able to do now.","zh":"現有能力是指某人現在能夠做到的事情。"},{"en":"A candidate’s present capability may include basic skills, punctuality, and ability to follow instructions.","zh":"候選人的現有能力可能包括基本技能、守時和跟從指示的能力。"},{"en":"Looking at present capability prevents employers from judging only by the past.","zh":"看現有能力可以防止僱主只用過去評價人。"},{"en":"This phrase focuses on current ability and readiness.","zh":"這個短語著重目前能力和準備程度。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"future potential","meaning":"未來潛力","examples":[{"en":"Employers should also consider a candidate’s future potential.","zh":"僱主也應考慮候選人的未來潛力。"},{"en":"Future potential means what someone may be able to become or achieve later.","zh":"未來潛力是指某人日後可能成為或達成的事情。"},{"en":"A quiet employee may have strong future potential if they are reliable and willing to learn.","zh":"如果一位安靜員工可靠並願意學習，他可能有很強的未來潛力。"},{"en":"Training can help future potential develop into real workplace value.","zh":"培訓可以幫助未來潛力發展成真正職場價值。"},{"en":"This phrase asks employers to see growth, not only current limits.","zh":"這個短語要求僱主看見成長，而不只是目前限制。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"bring genuine business value","meaning":"帶來真正的商業價值","examples":[{"en":"Joining Second Chance can bring genuine business value.","zh":"加入「第二次機會」可以帶來真正的商業價值。"},{"en":"To bring genuine business value means to create real benefits for a company, not just a good image.","zh":"帶來真正的商業價值，是指為公司創造實際好處，而不只是好形象。"},{"en":"Reliable workers bring business value when they reduce turnover and improve service.","zh":"可靠員工透過減少流失和改善服務帶來商業價值。"},{"en":"A fair hiring scheme can bring value by expanding the pool of committed workers.","zh":"公平招聘計劃可以透過擴大投入員工的來源帶來價值。"},{"en":"This phrase shows that social action can also make business sense.","zh":"這個短語顯示社會行動也可以符合商業利益。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"service and manual industries","meaning":"服務業和體力勞動行業","examples":[{"en":"Service and manual industries often need reliable workers.","zh":"服務業和體力勞動行業經常需要可靠員工。"},{"en":"Service and manual industries are fields involving customer service, physical work, cleaning, delivery, kitchen work, or maintenance.","zh":"服務業和體力勞動行業是涉及客戶服務、體力工作、清潔、送貨、廚房工作或維修的領域。"},{"en":"Restaurants, hotels, warehouses, and cleaning companies may belong to service or manual industries.","zh":"餐廳、酒店、貨倉和清潔公司可能屬於服務業或體力勞動行業。"},{"en":"These industries often value punctuality, effort, and practical skills.","zh":"這些行業通常重視守時、努力和實際技能。"},{"en":"This phrase identifies workplaces where suitable entry-level jobs may exist.","zh":"這個短語指出可能存在合適入門職位的職場。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"struggle to recruit","meaning":"難以招聘","examples":[{"en":"Some employers struggle to recruit reliable workers.","zh":"一些僱主難以招聘可靠員工。"},{"en":"To struggle to recruit means to find it difficult to hire enough suitable employees.","zh":"難以招聘是指很難聘請足夠合適員工。"},{"en":"A restaurant may struggle to recruit kitchen staff during busy seasons.","zh":"餐廳在旺季可能難以招聘廚房員工。"},{"en":"Employers who struggle to recruit may benefit from a wider pool of candidates.","zh":"難以招聘的僱主可能受惠於更廣闊的候選人來源。"},{"en":"This phrase explains a practical problem that the scheme can help solve.","zh":"這個短語解釋計劃可以幫助解決的實際問題。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"reliable workers","meaning":"可靠員工","examples":[{"en":"Employers often look for reliable workers.","zh":"僱主經常尋找可靠員工。"},{"en":"Reliable workers are employees who can be trusted to arrive, work carefully, and follow rules.","zh":"可靠員工是可以被信任會準時到達、細心工作並遵守規則的僱員。"},{"en":"A reliable worker arrives on time and tells the manager early if there is a problem.","zh":"可靠員工會準時到達，並在有問題時及早通知經理。"},{"en":"Reliability matters because one absent worker can affect the whole team.","zh":"可靠很重要，因為一名缺席員工可以影響整個團隊。"},{"en":"This phrase shows a basic quality many employers value.","zh":"這個短語顯示許多僱主重視的基本特質。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"be willing to start with","meaning":"願意從……開始","examples":[{"en":"Some workers are willing to start with modest duties.","zh":"一些員工願意從基本職責開始。"},{"en":"To be willing to start with something means to accept a basic beginning before growing further.","zh":"願意從某事開始，是指接受由基礎起步，再逐步成長。"},{"en":"A new employee may be willing to start with cleaning tables before learning customer service.","zh":"新員工可能願意先從清潔桌子開始，再學習客戶服務。"},{"en":"This willingness can show humility, patience, and readiness to learn.","zh":"這種意願可以顯示謙遜、耐性和學習準備。"},{"en":"This phrase highlights attitude at the beginning of a job.","zh":"這個短語突出工作初期的態度。"}],"source":"2012 Q8.pdf","sourcePage":5},{"front":"modest duties","meaning":"基本職責","examples":[{"en":"Rehabilitated persons may be willing to start with modest duties.","zh":"更生人士可能願意從基本職責開始。"},{"en":"Modest duties are simple or basic tasks that are not high-ranking but still useful.","zh":"基本職責是簡單或基礎的工作，職級不高但仍有用。"},{"en":"Washing dishes, preparing ingredients, and cleaning shelves can be modest duties.","zh":"洗碗、準備食材和清潔貨架都可以是基本職責。"},{"en":"Modest duties can help new workers build routines and trust.","zh":"基本職責可以幫助新員工建立規律和信任。"},{"en":"This phrase shows that small beginnings can lead to growth.","zh":"這個短語顯示小起點可以帶來成長。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"grow steadily","meaning":"穩步成長","examples":[{"en":"Employees can start with modest duties and grow steadily.","zh":"員工可以從基本職責開始，然後穩步成長。"},{"en":"To grow steadily means to improve gradually and consistently over time.","zh":"穩步成長是指隨時間逐漸而持續地改善。"},{"en":"A kitchen helper may grow steadily into a team leader after months of reliable work.","zh":"廚房助理可能在數月可靠工作後穩步成長為組長。"},{"en":"Steady growth needs training, patience, and clear expectations.","zh":"穩步成長需要培訓、耐心和清晰期望。"},{"en":"This phrase shows progress that is slow but dependable.","zh":"這個短語顯示緩慢但可靠的進步。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"be eager to prove themselves","meaning":"渴望證明自己","examples":[{"en":"Many rehabilitated persons are eager to prove themselves.","zh":"許多更生人士渴望證明自己。"},{"en":"To be eager to prove themselves means to strongly want to show that they are capable and trustworthy.","zh":"渴望證明自己，是指非常想顯示自己有能力並值得信任。"},{"en":"A new worker may be eager to prove themselves by arriving early and learning quickly.","zh":"新員工可能透過早到和快速學習來證明自己。"},{"en":"People who receive a rare opportunity may work especially hard to show they deserve it.","zh":"得到難得機會的人可能特別努力，以顯示自己值得這個機會。"},{"en":"This phrase describes strong motivation after being given trust.","zh":"這個短語描述在得到信任後的強烈動力。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"opportunities seldom arrive twice","meaning":"好機會很少再次出現","examples":[{"en":"They know that good opportunities seldom arrive twice.","zh":"他們知道好機會很少再次出現。"},{"en":"Opportunities seldom arrive twice means important chances may not return if they are missed.","zh":"好機會很少再次出現，是指重要機會一旦錯過，未必會再來。"},{"en":"A trainee may work hard because they know a job offer may not come again soon.","zh":"實習員可能很努力，因為他知道工作邀請未必很快再出現。"},{"en":"When people know opportunities are rare, they may value them more deeply.","zh":"當人們知道機會罕有時，可能會更深地珍惜它。"},{"en":"This phrase explains why a second chance can create strong commitment.","zh":"這個短語解釋為何第二次機會能創造強烈投入感。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"given proper training","meaning":"在獲得適當訓練下","examples":[{"en":"Given proper training, employees can grow into loyal staff members.","zh":"在獲得適當訓練下，員工可以成長為忠誠的職員。"},{"en":"Given proper training means if they receive suitable instruction and practice.","zh":"在獲得適當訓練下，是指如果他們得到合適指導和練習。"},{"en":"Given proper training, a beginner can learn kitchen safety and customer service.","zh":"在獲得適當訓練下，初學者可以學會廚房安全和客戶服務。"},{"en":"Training helps workers turn willingness into real workplace skill.","zh":"培訓幫助員工把意願轉化為真正職場技能。"},{"en":"This phrase shows that success depends partly on support.","zh":"這個短語顯示成功部分取決於支援。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"patient supervision","meaning":"耐心督導","examples":[{"en":"Patient supervision can help new employees adjust.","zh":"耐心督導可以幫助新員工適應。"},{"en":"Patient supervision means calm, steady guidance while someone learns a job.","zh":"耐心督導是在某人學習工作時提供冷靜而穩定的指導。"},{"en":"A supervisor gives patient supervision when they correct mistakes without humiliation.","zh":"當主管糾正錯誤但不羞辱人時，就是提供耐心督導。"},{"en":"Patient supervision helps workers build confidence and reduce repeated errors.","zh":"耐心督導幫助員工建立信心並減少重複錯誤。"},{"en":"This phrase shows that support requires time and understanding.","zh":"這個短語顯示支援需要時間和理解。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"disciplined and loyal","meaning":"有紀律而忠誠","examples":[{"en":"Such employees can become disciplined and loyal.","zh":"這類員工可以變得有紀律而忠誠。"},{"en":"Disciplined and loyal means having self-control and strong commitment to the organisation.","zh":"有紀律而忠誠，是指有自制力並對機構有強烈投入感。"},{"en":"A disciplined worker follows routines, while a loyal worker stays committed to the team.","zh":"有紀律的員工會遵守規律，而忠誠的員工會投入團隊。"},{"en":"Employees become disciplined and loyal when they receive trust and clear expectations.","zh":"當員工得到信任和清晰期望時，可能變得有紀律而忠誠。"},{"en":"This phrase describes the kind of staff many businesses want.","zh":"這個短語描述許多企業想要的員工類型。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"deeply appreciative","meaning":"深深感激的","examples":[{"en":"Some employees become deeply appreciative of the opportunity.","zh":"一些員工會對這個機會深深感激。"},{"en":"Deeply appreciative means very grateful and aware of the value of something received.","zh":"深深感激的是指非常感謝，並明白所得東西的價值。"},{"en":"A worker may be deeply appreciative when an employer trusts them after others refused.","zh":"當其他人拒絕後有僱主願意信任，員工可能會深深感激。"},{"en":"Deep appreciation can lead to effort, loyalty, and careful work.","zh":"深深感激可以帶來努力、忠誠和細心工作。"},{"en":"This phrase shows the emotional effect of being given a chance.","zh":"這個短語顯示得到機會後的情感影響。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"members of staff","meaning":"職員；員工","examples":[{"en":"Rehabilitated persons can become valuable members of staff.","zh":"更生人士可以成為有價值的員工。"},{"en":"Members of staff are people employed by an organisation.","zh":"員工是受僱於某機構的人。"},{"en":"A restaurant’s members of staff may include cooks, cleaners, servers, and managers.","zh":"餐廳員工可能包括廚師、清潔工、侍應和經理。"},{"en":"When staff members are trained well, they can support one another and serve customers better.","zh":"當員工受過良好訓練時，他們可以互相支援並更好服務顧客。"},{"en":"This phrase presents employees as part of a team.","zh":"這個短語把僱員呈現為團隊一部分。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"lawful livelihood","meaning":"合法生計","examples":[{"en":"A company can give someone a lawful livelihood.","zh":"公司可以給某人一份合法生計。"},{"en":"A lawful livelihood is a legal way to earn money and support oneself or one’s family.","zh":"合法生計是以合法方式賺錢並支撐自己或家庭生活。"},{"en":"A stable restaurant job can give a former offender a lawful livelihood.","zh":"一份穩定餐廳工作可以給前違法者合法生計。"},{"en":"Lawful livelihood reduces the pressure to return to harmful or illegal choices.","zh":"合法生計減少人重返有害或非法選擇的壓力。"},{"en":"This phrase connects employment with dignity and social safety.","zh":"這個短語把就業與尊嚴和社會安全連接起來。"}],"source":"2012 Q8.pdf","sourcePage":6},{"front":"fill a vacancy","meaning":"填補職位空缺","examples":[{"en":"The company does not simply fill a vacancy.","zh":"公司不只是填補職位空缺。"},{"en":"To fill a vacancy means to hire someone for an empty job position.","zh":"填補職位空缺是指聘請某人擔任空缺的工作崗位。"},{"en":"A shop fills a vacancy when it hires a new cashier after another worker leaves.","zh":"當一名員工離職後，商店聘請新收銀員就是填補職位空缺。"},{"en":"Through this scheme, filling a vacancy can also help someone rebuild their life.","zh":"透過這項計劃，填補職位空缺也可以幫助某人重建人生。"},{"en":"This phrase shows the basic business action behind a deeper social effect.","zh":"這個短語顯示更深社會影響背後的基本商業行動。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"build commitment","meaning":"建立投入感；建立忠誠","examples":[{"en":"Giving someone a chance can build commitment.","zh":"給某人機會可以建立投入感。"},{"en":"To build commitment means to develop loyalty, effort, and a serious sense of responsibility.","zh":"建立投入感是指培養忠誠、努力和認真責任感。"},{"en":"A worker may build commitment when they feel trusted by an employer.","zh":"當員工感到被僱主信任時，可能會建立投入感。"},{"en":"Commitment grows when people see that their effort is valued.","zh":"當人們看見自己的努力被重視時，投入感會增加。"},{"en":"This phrase explains how opportunity can create stronger staff loyalty.","zh":"這個短語解釋機會如何創造更強員工忠誠。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"take a small restaurant, for example","meaning":"以一間小餐廳為例","examples":[{"en":"Take a small restaurant, for example.","zh":"以一間小餐廳為例。"},{"en":"Take a small restaurant, for example means using a simple restaurant case to explain a wider point.","zh":"以一間小餐廳為例，是指用簡單餐廳個案來解釋較大的觀點。"},{"en":"Take a small restaurant, for example: a new worker may start with washing dishes and later learn cooking skills.","zh":"以一間小餐廳為例：新員工可能從洗碗開始，之後學習烹調技巧。"},{"en":"This phrase helps readers imagine how the scheme works in real life.","zh":"這個短語幫助讀者想像計劃如何在現實中運作。"},{"en":"It moves the argument from general policy to a concrete workplace.","zh":"它把論點由一般政策帶到具體職場。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"former drug addict","meaning":"前吸毒者","examples":[{"en":"A rehabilitated former drug addict may begin with basic kitchen duties.","zh":"一名已康復的前吸毒者可能從基本廚房職責開始。"},{"en":"A former drug addict is someone who used to be addicted to drugs but is no longer in that state.","zh":"前吸毒者是指過去曾有毒癮，但現在不再處於那種狀態的人。"},{"en":"A former drug addict may need steady work and support to maintain recovery.","zh":"前吸毒者可能需要穩定工作和支援來維持康復。"},{"en":"Labelling someone only as a former addict can hide their present effort and change.","zh":"只把某人標籤為前吸毒者，可能掩蓋他現在的努力和改變。"},{"en":"This phrase should be used carefully and respectfully.","zh":"這個短語應小心而尊重地使用。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"wash dishes","meaning":"洗碗","examples":[{"en":"He may begin by washing dishes.","zh":"他可能從洗碗開始。"},{"en":"To wash dishes means to clean plates, bowls, cups, and cooking tools after meals or food preparation.","zh":"洗碗是指在用餐或準備食物後清潔碟、碗、杯和煮食工具。"},{"en":"A kitchen helper may wash dishes before learning more complex kitchen duties.","zh":"廚房助理可能先洗碗，再學習更複雜的廚房職責。"},{"en":"Washing dishes is basic work, but it teaches speed, hygiene, and responsibility.","zh":"洗碗是基礎工作，但它教人速度、衛生和責任。"},{"en":"This phrase shows a modest starting point in restaurant work.","zh":"這個短語顯示餐廳工作中的基本起點。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"prepare ingredients","meaning":"準備食材","examples":[{"en":"He may begin by preparing ingredients.","zh":"他可能從準備食材開始。"},{"en":"To prepare ingredients means to wash, cut, measure, or organise food before cooking.","zh":"準備食材是指在烹調前清洗、切割、量度或整理食物。"},{"en":"A kitchen assistant may prepare vegetables, sauces, and rice before lunch service.","zh":"廚房助理可能在午餐服務前準備蔬菜、醬汁和米飯。"},{"en":"Preparing ingredients carefully helps the whole kitchen work smoothly.","zh":"細心準備食材能幫助整個廚房順利運作。"},{"en":"This phrase shows practical responsibility behind simple kitchen work.","zh":"這個短語顯示簡單廚房工作背後的實際責任。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"with punctuality, coaching and trust","meaning":"憑着守時、指導和信任","examples":[{"en":"With punctuality, coaching and trust, he may become a kitchen assistant.","zh":"憑着守時、指導和信任，他可能成為廚房助理。"},{"en":"With punctuality, coaching and trust means through arriving on time, receiving guidance, and being given confidence.","zh":"憑着守時、指導和信任，是指透過準時到達、得到引導和被給予信心。"},{"en":"A new worker can improve when punctuality, coaching, and trust are all present.","zh":"當守時、指導和信任同時存在時，新員工可以改善。"},{"en":"Punctuality shows responsibility, coaching builds skill, and trust encourages effort.","zh":"守時顯示責任，指導建立技能，而信任鼓勵努力。"},{"en":"This phrase shows the conditions that help a person grow at work.","zh":"這個短語顯示幫助人在工作中成長的條件。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"kitchen assistant","meaning":"廚房助理","examples":[{"en":"He may later become a kitchen assistant.","zh":"他日後可能成為廚房助理。"},{"en":"A kitchen assistant helps with basic food preparation, cleaning, and kitchen organisation.","zh":"廚房助理協助基本食物準備、清潔和廚房整理。"},{"en":"A kitchen assistant may wash vegetables, prepare ingredients, and keep work areas clean.","zh":"廚房助理可能清洗蔬菜、準備食材和保持工作區清潔。"},{"en":"This role can help a new worker learn discipline and teamwork.","zh":"這個職位可以幫助新員工學習紀律和團隊合作。"},{"en":"This phrase describes a realistic entry-level job in a restaurant.","zh":"這個短語描述餐廳中實際的入門職位。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"encourage newcomers to","meaning":"鼓勵新來者去","examples":[{"en":"He may encourage newcomers to stay away from drugs.","zh":"他可能鼓勵新來者遠離毒品。"},{"en":"To encourage newcomers to do something means to guide or motivate new people to make a better choice.","zh":"鼓勵新來者去做某事，是指引導或推動新人作出更好的選擇。"},{"en":"A senior worker may encourage newcomers to arrive early and ask questions.","zh":"資深員工可能鼓勵新來者早到和提問。"},{"en":"Someone who has rebuilt their life can encourage newcomers through personal example.","zh":"已重建人生的人可以透過個人例子鼓勵新來者。"},{"en":"This phrase shows how one second chance can help others too.","zh":"這個短語顯示一個人的第二次機會也可以幫助其他人。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"stay away from drugs","meaning":"遠離毒品","examples":[{"en":"He may encourage others to stay away from drugs.","zh":"他可能鼓勵其他人遠離毒品。"},{"en":"To stay away from drugs means to avoid using illegal or harmful substances.","zh":"遠離毒品是指避免使用非法或有害物質。"},{"en":"A mentor may help young people stay away from drugs by sharing real consequences.","zh":"導師可以透過分享真實後果，幫助年輕人遠離毒品。"},{"en":"Stable work and supportive friends can help someone stay away from drugs.","zh":"穩定工作和支持性的朋友可以幫助某人遠離毒品。"},{"en":"This phrase focuses on prevention, recovery, and healthier choices.","zh":"這個短語著重預防、康復和更健康的選擇。"}],"source":"2012 Q8.pdf","sourcePage":7},{"front":"the more..., the more likely...","meaning":"越……就越可能……","examples":[{"en":"The more room we give people to rebuild, the more likely they are to repay our trust.","zh":"我們越給人重建人生的空間，他們就越可能以努力回報信任。"},{"en":"The more A, the more likely B means when A increases, B becomes more probable.","zh":"「越A，就越可能B」意思是A增加時，B發生的可能性也增加。"},{"en":"The more training a new worker receives, the more likely they are to succeed.","zh":"新員工接受的培訓越多，就越可能成功。"},{"en":"This structure shows a clear link between support and result.","zh":"這個句式顯示支援與結果之間的清晰連繫。"},{"en":"It is useful for explaining how opportunity can increase positive behaviour.","zh":"它適合解釋機會如何增加正面行為。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"give people room to rebuild","meaning":"給人重建人生的空間","examples":[{"en":"Society should give people room to rebuild.","zh":"社會應給人重建人生的空間。"},{"en":"To give people room to rebuild means to give them time, trust, and opportunity to create a better life.","zh":"給人重建人生的空間，是指給他們時間、信任和機會去創造更好的生活。"},{"en":"Employers give people room to rebuild when they offer suitable jobs and patient supervision.","zh":"僱主提供合適工作和耐心督導時，就是給人重建人生的空間。"},{"en":"Without room to rebuild, change may remain only an intention.","zh":"沒有重建空間，改變可能只停留在意願。"},{"en":"This phrase presents opportunity as space for growth.","zh":"這個短語把機會呈現為成長空間。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"repay that trust with effort","meaning":"以努力回報信任","examples":[{"en":"Employees may repay that trust with effort.","zh":"員工可能以努力回報那份信任。"},{"en":"To repay that trust with effort means to respond to someone’s confidence by working hard and responsibly.","zh":"以努力回報信任，是指透過勤奮和負責任工作來回應別人的信任。"},{"en":"A worker may repay an employer’s trust by arriving on time every day.","zh":"員工可以透過每天準時到達來回報僱主的信任。"},{"en":"Effort becomes a way to show gratitude and prove reliability.","zh":"努力成為表達感激和證明可靠的方法。"},{"en":"This phrase links trust with responsible action.","zh":"這個短語把信任與負責任行動連接起來。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"strengthen corporate reputation","meaning":"加強企業聲譽","examples":[{"en":"The scheme strengthens corporate reputation in a meaningful way.","zh":"這項計劃以有意義的方式加強企業聲譽。"},{"en":"To strengthen corporate reputation means to improve how the public, customers, and partners view a company.","zh":"加強企業聲譽，是指改善公眾、顧客和合作夥伴如何看待公司。"},{"en":"A company strengthens its reputation when it supports fair employment honestly.","zh":"公司真誠支持公平就業時，就能加強聲譽。"},{"en":"Reputation grows stronger when social responsibility is shown through real action.","zh":"當社會責任透過真實行動顯示時，聲譽會變得更強。"},{"en":"This phrase connects business image with ethical practice.","zh":"這個短語把企業形象與道德實踐連接起來。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"in a meaningful way","meaning":"以有意義的方式","examples":[{"en":"The scheme improves reputation in a meaningful way.","zh":"這項計劃以有意義的方式改善聲譽。"},{"en":"In a meaningful way means in a way that has real value, purpose, or effect.","zh":"以有意義的方式，是指以有真正價值、目的或效果的方式。"},{"en":"A company helps meaningfully when it creates jobs, not only when it posts slogans.","zh":"公司創造職位時是在有意義地幫助，而不只是張貼口號。"},{"en":"Meaningful support changes people’s lives instead of only improving appearance.","zh":"有意義的支援會改變人的生活，而不只是改善外表形象。"},{"en":"This phrase separates real impact from shallow publicity.","zh":"這個短語把真正影響與表面宣傳分開。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"customers, investors and employees","meaning":"顧客、投資者和員工","examples":[{"en":"Customers, investors and employees notice social responsibility.","zh":"顧客、投資者和員工會留意社會責任。"},{"en":"Customers, investors and employees are three groups that can judge how a company behaves.","zh":"顧客、投資者和員工是三個可以評價公司行為的群體。"},{"en":"Customers may buy from a fair company, investors may trust it, and employees may feel proud of it.","zh":"顧客可能向公平公司購買，投資者可能信任它，員工可能為它感到自豪。"},{"en":"These groups increasingly care about whether business values are real.","zh":"這些群體越來越關心企業價值是否真實。"},{"en":"This phrase shows that reputation matters to many stakeholders.","zh":"這個短語顯示聲譽對許多持份者都重要。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"increasingly notice whether","meaning":"越來越留意是否","examples":[{"en":"People increasingly notice whether a business acts responsibly.","zh":"人們越來越留意企業是否負責任地行事。"},{"en":"Increasingly notice whether means more and more people pay attention to whether something is true.","zh":"越來越留意是否，是指越來越多人注意某事是否真實。"},{"en":"Customers increasingly notice whether companies treat workers fairly.","zh":"顧客越來越留意公司是否公平對待員工。"},{"en":"This phrase shows a growing public expectation over time.","zh":"這個短語顯示隨時間增長的公眾期望。"},{"en":"It helps explain why social responsibility affects reputation today.","zh":"它幫助解釋為何社會責任如今會影響聲譽。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"act with social responsibility","meaning":"以社會責任行事","examples":[{"en":"Businesses should act with social responsibility.","zh":"企業應以社會責任行事。"},{"en":"To act with social responsibility means to make decisions that consider society, not only profit.","zh":"以社會責任行事，是指作決定時考慮社會，而不只是利潤。"},{"en":"A company acts with social responsibility when it hires fairly and reduces discrimination.","zh":"公司公平招聘並減少歧視時，就是以社會責任行事。"},{"en":"Acting responsibly can strengthen trust between businesses and the community.","zh":"負責任行事可以加強企業與社區之間的信任。"},{"en":"This phrase describes ethical behaviour in daily business decisions.","zh":"這個短語描述日常商業決定中的道德行為。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"sponsor a slogan","meaning":"贊助一句口號","examples":[{"en":"Sponsoring a slogan is easier than creating real opportunities.","zh":"贊助一句口號比創造真正機會容易。"},{"en":"To sponsor a slogan means to pay for or support a public message, often for image or publicity.","zh":"贊助一句口號，是指資助或支持一個公共信息，通常為了形象或宣傳。"},{"en":"A company may sponsor a slogan about kindness but still refuse to hire fairly.","zh":"公司可能贊助關於善意的口號，但仍拒絕公平招聘。"},{"en":"Sponsoring words is less meaningful than changing real workplace practice.","zh":"贊助說話不如改變真實職場做法有意義。"},{"en":"This phrase criticises shallow support that does not create action.","zh":"這個短語批評沒有產生行動的表面支援。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"a person of determination","meaning":"有決心的人","examples":[{"en":"Creating a job for a person of determination is meaningful.","zh":"為有決心的人創造工作是有意義的。"},{"en":"A person of determination is someone who is serious about changing, improving, or succeeding despite difficulty.","zh":"有決心的人是即使面對困難，仍認真想改變、改善或成功的人。"},{"en":"A rehabilitated worker may be a person of determination because they want to rebuild trust.","zh":"更生員工可能是有決心的人，因為他們想重建信任。"},{"en":"Giving such a person a job can turn effort into contribution.","zh":"給這樣的人一份工作，可以把努力轉化為貢獻。"},{"en":"This phrase focuses on strength of character rather than past failure.","zh":"這個短語著重品格力量，而不是過去失敗。"}],"source":"2012 Q8.pdf","sourcePage":8},{"front":"believe in rehabilitation","meaning":"相信更生","examples":[{"en":"The company can show that it believes in rehabilitation.","zh":"公司可以顯示它相信更生。"},{"en":"To believe in rehabilitation means to trust that people can change and return to society responsibly.","zh":"相信更生是指相信人可以改變，並負責任地重返社會。"},{"en":"An employer shows belief in rehabilitation by judging candidates fairly after training and support.","zh":"僱主在培訓和支援後公平評估候選人，就是顯示相信更生。"},{"en":"Believing in rehabilitation does not mean ignoring risk; it means allowing evidence of change.","zh":"相信更生不代表忽視風險，而是容許改變的證據被看見。"},{"en":"This phrase connects moral belief with hiring practice.","zh":"這個短語把道德信念與招聘做法連接起來。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"inclusion","meaning":"共融","examples":[{"en":"The scheme shows a company’s belief in inclusion.","zh":"這項計劃顯示公司相信共融。"},{"en":"Inclusion means allowing different people to take part and belong fairly.","zh":"共融是指讓不同的人公平參與和有歸屬感。"},{"en":"A workplace practises inclusion when it gives suitable chances to people with difficult pasts.","zh":"職場給有困難過去的人合適機會時，就是實踐共融。"},{"en":"Inclusion makes a company stronger by widening who can contribute.","zh":"共融透過擴大能作出貢獻的人群，令公司更強。"},{"en":"This word focuses on belonging instead of exclusion.","zh":"這個詞著重歸屬，而不是排斥。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"practical compassion","meaning":"實際的關懷","examples":[{"en":"Second Chance turns compassion into practical action.","zh":"「第二次機會」把關懷轉化為實際行動。"},{"en":"Practical compassion means care that becomes useful action, not only kind feelings.","zh":"實際的關懷是指變成有用行動的關心，而不只是善意感受。"},{"en":"Hiring a rehabilitated person with support is practical compassion because it offers real help.","zh":"在有支援下聘請更生人士是實際的關懷，因為它提供真正幫助。"},{"en":"Compassion becomes practical when it creates routines, income, and dignity.","zh":"當關懷創造生活規律、收入和尊嚴時，它就變得實際。"},{"en":"This phrase shows kindness expressed through concrete choices.","zh":"這個短語顯示透過具體選擇表達善意。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"charity dressed up as business","meaning":"披上商業外衣的慈善","examples":[{"en":"This is not charity dressed up as business.","zh":"這不是披上商業外衣的慈善。"},{"en":"Charity dressed up as business means help that only pretends to be a business decision.","zh":"披上商業外衣的慈善，是指只是偽裝成商業決定的幫助。"},{"en":"Fair hiring is not charity dressed up as business if the employee can do the job well.","zh":"如果僱員能做好工作，公平招聘就不是披上商業外衣的慈善。"},{"en":"This phrase rejects the idea that giving a chance has no commercial value.","zh":"這個短語否定給予機會沒有商業價值的想法。"},{"en":"It shows that social responsibility can be practical, not merely symbolic.","zh":"它顯示社會責任可以是實際的，而不只是象徵性的。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"social responsibility translated into daily operations","meaning":"把社會責任轉化為日常營運","examples":[{"en":"The scheme is social responsibility translated into daily operations.","zh":"這項計劃是把社會責任轉化為日常營運。"},{"en":"Social responsibility translated into daily operations means values become part of everyday business practice.","zh":"把社會責任轉化為日常營運，是指價值變成日常商業做法的一部分。"},{"en":"A company translates responsibility into operations when it trains managers to hire fairly.","zh":"公司培訓經理公平招聘時，就是把責任轉化為營運。"},{"en":"This phrase shows that social responsibility should affect real decisions, not only advertisements.","zh":"這個短語顯示社會責任應影響真實決定，而不只是廣告。"},{"en":"It connects big values with daily workplace action.","zh":"它把重大價值與日常職場行動連接起來。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"in the eyes of the public","meaning":"在公眾眼中","examples":[{"en":"In the eyes of the public, fair companies earn respect.","zh":"在公眾眼中，公平的公司會贏得尊重。"},{"en":"In the eyes of the public means from the viewpoint of ordinary people in society.","zh":"在公眾眼中，是指從社會普通人的角度來看。"},{"en":"In the eyes of the public, a company that gives real opportunities may seem more trustworthy.","zh":"在公眾眼中，給予真正機會的公司可能顯得更可信。"},{"en":"Public opinion matters because businesses depend on trust and reputation.","zh":"公眾意見很重要，因為企業依賴信任和聲譽。"},{"en":"This phrase is useful when discussing image and social judgement.","zh":"這個短語適合討論形象和社會評價。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"profit-making organisation","meaning":"牟利機構","examples":[{"en":"A business is more than a profit-making organisation.","zh":"企業不只是一個牟利機構。"},{"en":"A profit-making organisation is an organisation that aims to earn money.","zh":"牟利機構是以賺取金錢為目標的組織。"},{"en":"A restaurant is a profit-making organisation, but it can still care about workers and neighbours.","zh":"餐廳是牟利機構，但仍可以關心員工和鄰里。"},{"en":"Businesses gain respect when they act as community members, not only money-makers.","zh":"當企業作為社區成員行動，而不只是賺錢者時，會獲得尊重。"},{"en":"This phrase contrasts financial purpose with wider social responsibility.","zh":"這個短語對比財務目的與更廣泛社會責任。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"responsible member of the community","meaning":"負責任的社區一分子","examples":[{"en":"A fair company is a responsible member of the community.","zh":"公平的公司是負責任的社區一分子。"},{"en":"A responsible member of the community is a person or organisation that contributes to local well-being.","zh":"負責任的社區一分子，是為本地福祉作出貢獻的人或組織。"},{"en":"A business becomes a responsible community member when it creates jobs and supports vulnerable groups.","zh":"企業創造職位並支援弱勢群體時，就成為負責任的社區成員。"},{"en":"Responsible members do not only take from the community; they also give back.","zh":"負責任的成員不只從社區取得，也會回饋社區。"},{"en":"This phrase presents business as part of society.","zh":"這個短語把企業呈現為社會的一部分。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"such goodwill","meaning":"這種善意和好感","examples":[{"en":"Such goodwill cannot be bought through advertising alone.","zh":"這種善意和好感不能單靠廣告買到。"},{"en":"Such goodwill means this kind of trust, kindness, and positive feeling from others.","zh":"這種善意和好感是指來自他人的這類信任、善意和正面感受。"},{"en":"A company earns goodwill when people see it helping the community sincerely.","zh":"當人們看見公司真誠幫助社區時，公司會贏得好感。"},{"en":"Goodwill grows through real action more than public slogans.","zh":"好感更多來自真實行動，而不是公共口號。"},{"en":"This phrase refers back to respect created by responsible behaviour.","zh":"這個短語指回負責任行為創造出的尊重。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"cannot be bought through advertising alone","meaning":"不能單靠廣告買到","examples":[{"en":"Public goodwill cannot be bought through advertising alone.","zh":"公眾好感不能單靠廣告買到。"},{"en":"Cannot be bought through advertising alone means cannot be gained only by paying for publicity.","zh":"不能單靠廣告買到，是指不能只透過付費宣傳得到。"},{"en":"A company may advertise kindness, but trust comes from how it treats people.","zh":"公司可以宣傳善意，但信任來自它如何對待人。"},{"en":"Real opportunities create deeper goodwill than polished posters.","zh":"真正機會比精美海報創造更深的好感。"},{"en":"This phrase argues that reputation must be earned through action.","zh":"這個短語主張聲譽必須透過行動贏得。"}],"source":"2012 Q8.pdf","sourcePage":9},{"front":"understandably","meaning":"可以理解地","examples":[{"en":"Understandably, some employers may worry about safety.","zh":"可以理解的是，一些僱主可能擔心安全問題。"},{"en":"Understandably means in a way that is reasonable or easy to understand.","zh":"可以理解地，是指以合理或容易明白的方式。"},{"en":"Understandably, parents worry when their children start a new job late at night.","zh":"可以理解的是，當孩子開始晚上很晚下班的新工作時，父母會擔心。"},{"en":"Writers use this word to show respect for another person’s concern.","zh":"作者使用這個詞來表示尊重別人的憂慮。"},{"en":"It helps discussion sound fair instead of dismissive.","zh":"它幫助討論聽起來公平，而不是輕視別人。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"worry about safety","meaning":"擔心安全問題","examples":[{"en":"Some employers may worry about safety and discipline.","zh":"一些僱主可能擔心安全和紀律問題。"},{"en":"To worry about safety means to feel concerned that people or property may be harmed.","zh":"擔心安全問題是指關心人或財物可能受到傷害。"},{"en":"Employers may worry about safety when hiring anyone for a job involving tools or customers.","zh":"僱主聘請任何涉及工具或顧客的工作時，都可能擔心安全。"},{"en":"Safety concerns deserve clear rules, training, and support.","zh":"安全憂慮值得以清晰規則、培訓和支援回應。"},{"en":"This phrase identifies a real concern that should be answered honestly.","zh":"這個短語指出應被坦誠回應的真實憂慮。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"public perception","meaning":"公眾觀感","examples":[{"en":"Employers may worry about public perception.","zh":"僱主可能擔心公眾觀感。"},{"en":"Public perception means how ordinary people see, judge, or feel about something.","zh":"公眾觀感是指普通人如何看待、評價或感受某事。"},{"en":"A company may worry that customers will misunderstand its decision to hire rehabilitated persons.","zh":"公司可能擔心顧客誤解它聘請更生人士的決定。"},{"en":"Clear communication can improve public perception by explaining the purpose and safeguards.","zh":"清晰溝通可以透過解釋目的和保障措施來改善公眾觀感。"},{"en":"This phrase focuses on reputation and social reaction.","zh":"這個短語著重聲譽和社會反應。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"deserve honest answers","meaning":"值得得到坦誠回應","examples":[{"en":"These concerns deserve honest answers.","zh":"這些憂慮值得得到坦誠回應。"},{"en":"Deserve honest answers means should be answered truthfully and respectfully.","zh":"值得得到坦誠回應，是指應該被真實和尊重地回答。"},{"en":"Employers’ worries about safety deserve honest answers, not slogans.","zh":"僱主對安全的憂慮值得得到坦誠回應，而不是口號。"},{"en":"Honest answers build trust because they admit risk and explain support.","zh":"坦誠回應能建立信任，因為它承認風險並解釋支援。"},{"en":"This phrase shows that serious concerns should not be ignored.","zh":"這個短語顯示嚴肅憂慮不應被忽視。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"assume that","meaning":"假設；認為","examples":[{"en":"It would be wrong to assume that a past conviction predicts failure.","zh":"假設過往定罪紀錄預示失敗是錯誤的。"},{"en":"To assume that means to believe something is true without enough proof.","zh":"假設某事，是指在沒有足夠證據下相信某事是真實的。"},{"en":"It is unfair to assume that a quiet student is lazy without understanding the reason.","zh":"在不了解原因前，就假設安靜學生懶惰是不公平的。"},{"en":"Employers should not assume failure from one past record alone.","zh":"僱主不應只根據一項過往紀錄就假設失敗。"},{"en":"This phrase warns against judgement based on incomplete information.","zh":"這個短語提醒人不要基於不完整資訊作判斷。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"past conviction","meaning":"過往定罪紀錄","examples":[{"en":"A past conviction does not automatically predict future failure.","zh":"過往定罪紀錄不會自動預示未來失敗。"},{"en":"A past conviction is a previous legal finding that someone committed an offence.","zh":"過往定罪紀錄是指過去法律上裁定某人曾犯法的紀錄。"},{"en":"A person with a past conviction may still change through rehabilitation, work, and support.","zh":"有過往定罪紀錄的人仍可能透過更生、工作和支援改變。"},{"en":"Employers should consider present conduct as well as past records.","zh":"僱主應同時考慮現時行為和過往紀錄。"},{"en":"This phrase refers to a serious past fact, but not a complete identity.","zh":"這個短語指一項嚴肅過去事實，但不是完整身份。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"addiction","meaning":"毒癮","examples":[{"en":"A past addiction should not automatically predict future failure.","zh":"過往毒癮不應自動預示未來失敗。"},{"en":"Addiction is a strong dependence on a substance or behaviour that is difficult to control.","zh":"毒癮是對某種物質或行為產生難以控制的強烈依賴。"},{"en":"Drug addiction can damage health, family life, and employment.","zh":"毒癮可以損害健康、家庭生活和就業。"},{"en":"Treatment and support can help people recover from addiction and rebuild routines.","zh":"治療和支援可以幫助人從毒癮中康復並重建生活規律。"},{"en":"This word should be used with care because it describes a serious health and social issue.","zh":"這個詞應小心使用，因為它描述嚴重的健康和社會問題。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"automatically predicts","meaning":"自動預示","examples":[{"en":"A past mistake does not automatically predict future failure.","zh":"過去的錯誤不會自動預示未來失敗。"},{"en":"Automatically predicts means directly and certainly shows what will happen later without considering change.","zh":"自動預示是指不考慮改變，就直接而確定地顯示日後會發生甚麼。"},{"en":"A poor exam result does not automatically predict a student’s future success or failure.","zh":"一次差劣考試成績不會自動預示學生未來成功或失敗。"},{"en":"Past behaviour matters, but it does not automatically predict present capability.","zh":"過去行為很重要，但不會自動預示現有能力。"},{"en":"This phrase warns against simple and unfair conclusions.","zh":"這個短語提醒人不要作簡單而不公平的結論。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"future failure","meaning":"未來失敗","examples":[{"en":"A past conviction does not automatically predict future failure.","zh":"過往定罪紀錄不會自動預示未來失敗。"},{"en":"Future failure means failing later in life, work, or responsibility.","zh":"未來失敗是指日後在人生、工作或責任上失敗。"},{"en":"Support and employment can reduce the risk of future failure.","zh":"支援和就業可以減低未來失敗的風險。"},{"en":"It is unfair to treat future failure as certain when a person is working to change.","zh":"當一個人正努力改變時，把未來失敗視為必然是不公平的。"},{"en":"This phrase is used to challenge pessimistic assumptions.","zh":"這個短語用來挑戰悲觀假設。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"the purpose of rehabilitation","meaning":"更生的目的","examples":[{"en":"The purpose of rehabilitation is to help people return to society.","zh":"更生的目的，是幫助人重返社會。"},{"en":"The purpose of rehabilitation means the main aim of helping people recover, take responsibility, and rebuild life.","zh":"更生的目的，是指幫助人康復、承擔責任和重建人生的主要目標。"},{"en":"Rehabilitation is not only punishment; its purpose is also change and reintegration.","zh":"更生不只是懲罰；其目的也包括改變和重新融入社會。"},{"en":"Employment supports the purpose of rehabilitation by giving people lawful routines.","zh":"就業透過給人合法生活規律，支援更生的目的。"},{"en":"This phrase explains why second chances matter.","zh":"這個短語解釋為何第二次機會重要。"}],"source":"2012 Q8.pdf","sourcePage":10},{"front":"accept responsibility","meaning":"承擔責任","examples":[{"en":"Rehabilitation helps people accept responsibility.","zh":"更生幫助人承擔責任。"},{"en":"To accept responsibility means to admit one’s role in past actions and take steps to do better.","zh":"承擔責任是指承認自己在過去行動中的角色，並採取步驟做得更好。"},{"en":"A person accepts responsibility when they stop blaming others and follow a recovery plan.","zh":"當一個人停止責怪別人並跟隨康復計劃時，就是承擔責任。"},{"en":"Accepting responsibility is necessary before trust can be rebuilt.","zh":"在信任能重建前，承擔責任是必要的。"},{"en":"This phrase shows moral maturity and readiness for change.","zh":"這個短語顯示道德成熟和改變準備。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"develop routines","meaning":"建立生活規律","examples":[{"en":"Rehabilitation helps people develop routines.","zh":"更生幫助人建立生活規律。"},{"en":"To develop routines means to build regular habits and patterns in daily life.","zh":"建立生活規律是指建立日常生活中的定期習慣和模式。"},{"en":"A job helps people develop routines by giving them start times, duties, and rest periods.","zh":"工作透過提供上班時間、職責和休息時間，幫助人建立生活規律。"},{"en":"Routines can reduce chaos and make recovery more stable.","zh":"生活規律可以減少混亂，令康復更穩定。"},{"en":"This phrase connects daily structure with long-term change.","zh":"這個短語把日常結構與長遠改變連接起來。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"return to society","meaning":"重返社會","examples":[{"en":"Employment helps rehabilitated persons return to society.","zh":"就業幫助更生人士重返社會。"},{"en":"To return to society means to become part of normal community life again after custody, treatment, or isolation.","zh":"重返社會是指在羈押、治療或孤立後，再次成為正常社區生活的一部分。"},{"en":"A person may return to society by working, supporting family, and following the law.","zh":"一個人可以透過工作、支援家庭和守法重返社會。"},{"en":"Returning to society is easier when people have income and daily structure.","zh":"當人有收入和日常規律時，重返社會會較容易。"},{"en":"This phrase focuses on belonging and social participation.","zh":"這個短語著重歸屬和社會參與。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"select suitable posts","meaning":"選擇合適職位","examples":[{"en":"Employers can select suitable posts under the scheme.","zh":"僱主可以在計劃下選擇合適職位。"},{"en":"To select suitable posts means to choose jobs that match the worker’s skills, readiness, and risk level.","zh":"選擇合適職位，是指選擇配合員工技能、準備程度和風險水平的工作。"},{"en":"A restaurant may select dishwashing or food preparation as suitable first posts.","zh":"餐廳可能選擇洗碗或準備食材作為合適的初始職位。"},{"en":"Choosing suitable posts helps prevent failure caused by unrealistic expectations.","zh":"選擇合適職位有助防止因不切實際期望而失敗。"},{"en":"This phrase shows careful planning before hiring.","zh":"這個短語顯示招聘前的小心規劃。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"conduct interviews","meaning":"進行面試","examples":[{"en":"Employers can conduct interviews before hiring.","zh":"僱主可以在聘請前進行面試。"},{"en":"To conduct interviews means to formally meet applicants and ask questions about their suitability.","zh":"進行面試是指正式會見申請人，並詢問其是否適合工作。"},{"en":"A manager may conduct interviews to learn about a candidate’s skills and work attitude.","zh":"經理可能進行面試，以了解候選人的技能和工作態度。"},{"en":"Interviews help employers judge whether a post fits the applicant.","zh":"面試幫助僱主判斷職位是否適合申請人。"},{"en":"This phrase describes a normal and responsible hiring step.","zh":"這個短語描述正常而負責任的招聘步驟。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"set probation periods","meaning":"設定試用期","examples":[{"en":"Companies can set probation periods for new employees.","zh":"公司可以為新員工設定試用期。"},{"en":"To set probation periods means to create trial periods during which a new worker’s performance is assessed.","zh":"設定試用期是指建立一段試行時間，用來評估新員工表現。"},{"en":"A restaurant may set a three-month probation period for a new kitchen assistant.","zh":"餐廳可能為新廚房助理設定三個月試用期。"},{"en":"Probation periods help both employer and employee see whether the job fits.","zh":"試用期幫助僱主和僱員雙方了解工作是否合適。"},{"en":"This phrase shows a practical safeguard in hiring.","zh":"這個短語顯示招聘中的實際保障措施。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"maintain normal workplace rules","meaning":"維持正常職場規則","examples":[{"en":"Employers can maintain normal workplace rules.","zh":"僱主可以維持正常職場規則。"},{"en":"To maintain normal workplace rules means to keep the usual standards for behaviour, safety, attendance, and performance.","zh":"維持正常職場規則，是指保留關於行為、安全、出勤和表現的一般標準。"},{"en":"A company may maintain rules about punctuality, hygiene, and respect for colleagues.","zh":"公司可以維持關於守時、衛生和尊重同事的規則。"},{"en":"Fair employment does not require employers to remove reasonable rules.","zh":"公平就業不要求僱主取消合理規則。"},{"en":"This phrase reassures businesses that fairness can still include discipline.","zh":"這個短語讓企業放心，知道公平仍可包括紀律。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"if necessary","meaning":"如有需要","examples":[{"en":"If necessary, support officers can offer advice.","zh":"如有需要，支援人員可以提供建議。"},{"en":"If necessary means if the situation needs it.","zh":"如有需要，是指如果情況需要。"},{"en":"If necessary, a manager can ask a support officer for help with workplace adjustment.","zh":"如有需要，經理可以請支援人員協助處理職場適應。"},{"en":"This phrase shows that extra help is available when problems arise.","zh":"這個短語顯示當問題出現時，額外幫助是可用的。"},{"en":"It makes the support sound flexible and practical.","zh":"它令支援聽起來有彈性和實際。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"support officers","meaning":"支援人員","examples":[{"en":"Support officers can help employers handle problems early.","zh":"支援人員可以幫助僱主及早處理問題。"},{"en":"Support officers are staff who provide advice, guidance, and follow-up help.","zh":"支援人員是提供建議、指引和跟進幫助的職員。"},{"en":"A support officer may speak with both employer and employee if adjustment problems appear.","zh":"如果出現適應問題，支援人員可能與僱主和僱員雙方交談。"},{"en":"Support officers make the process safer because concerns can be discussed quickly.","zh":"支援人員令過程更安全，因為憂慮可以迅速被討論。"},{"en":"This phrase identifies the people who provide practical help.","zh":"這個短語指出提供實際幫助的人。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"offer advice","meaning":"提供建議","examples":[{"en":"Support officers can offer advice to employers.","zh":"支援人員可以向僱主提供建議。"},{"en":"To offer advice means to give suggestions or guidance that may help someone decide what to do.","zh":"提供建議是指給予可能幫助某人決定如何行動的意見或指引。"},{"en":"A support officer may offer advice on training, communication, or probation arrangements.","zh":"支援人員可能就培訓、溝通或試用期安排提供建議。"},{"en":"Advice is useful when employers face a problem they have not handled before.","zh":"當僱主面對未曾處理過的問題時，建議很有用。"},{"en":"This phrase shows helpful guidance without taking control away from employers.","zh":"這個短語顯示有幫助的指引，而不奪去僱主的控制權。"}],"source":"2012 Q8.pdf","sourcePage":11},{"front":"problems are handled early","meaning":"問題及早處理","examples":[{"en":"Problems should be handled early before they grow.","zh":"問題應在變大前及早處理。"},{"en":"Problems are handled early means difficulties are dealt with soon after they appear.","zh":"問題及早處理，是指困難一出現不久就被處理。"},{"en":"A small misunderstanding at work should be handled early before it becomes conflict.","zh":"職場小誤會應及早處理，避免變成衝突。"},{"en":"Early handling protects both the employee’s confidence and the employer’s operations.","zh":"及早處理可以保護僱員信心和僱主營運。"},{"en":"This phrase shows the value of timely support.","zh":"這個短語顯示及時支援的價值。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"take blind risks","meaning":"盲目冒險","examples":[{"en":"Second Chance does not ask businesses to take blind risks.","zh":"「第二次機會」不是要求企業盲目冒險。"},{"en":"To take blind risks means to act without information, preparation, or safeguards.","zh":"盲目冒險是指在沒有資訊、準備或保障下行動。"},{"en":"Hiring without interviews, support, or rules would be taking a blind risk.","zh":"沒有面試、支援或規則就招聘，就是盲目冒險。"},{"en":"The scheme reduces blind risk by matching applicants and offering follow-up help.","zh":"這項計劃透過配對申請人和提供跟進幫助，減少盲目風險。"},{"en":"This phrase reassures employers that the process is careful.","zh":"這個短語讓僱主放心，知道過程是謹慎的。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"informed, humane and manageable steps","meaning":"有根據、人道而可管理的步驟","examples":[{"en":"The scheme helps businesses take informed, humane and manageable steps.","zh":"這項計劃幫助企業採取有根據、人道而可管理的步驟。"},{"en":"Informed, humane and manageable steps are actions based on knowledge, compassion, and realistic control.","zh":"有根據、人道而可管理的步驟，是基於知識、同情和實際控制的行動。"},{"en":"Interviewing candidates, setting probation, and receiving support are manageable steps.","zh":"面試候選人、設定試用期和獲得支援都是可管理步驟。"},{"en":"Humane action becomes safer when it is also informed and practical.","zh":"人道行動若同時有根據和實際，就會更安全。"},{"en":"This phrase presents second-chance hiring as careful, kind, and realistic.","zh":"這個短語把第二次機會招聘呈現為謹慎、善意和實際。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"without employment","meaning":"沒有就業","examples":[{"en":"Without employment, rehabilitation remains unfinished.","zh":"沒有就業，更生仍未完成。"},{"en":"Without employment means if a person has no job or lawful work.","zh":"沒有就業是指一個人沒有工作或合法職業。"},{"en":"Without employment, a person may struggle to pay rent, support family, or build routines.","zh":"沒有就業，一個人可能難以交租、支援家庭或建立生活規律。"},{"en":"Employment gives rehabilitation a practical place in daily life.","zh":"就業讓更生在日常生活中有實際位置。"},{"en":"This phrase shows why work is important after treatment or custody.","zh":"這個短語顯示治療或羈押後工作為何重要。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"remain unfinished","meaning":"仍未完成","examples":[{"en":"Without a job, rehabilitation remains unfinished.","zh":"沒有工作，更生仍未完成。"},{"en":"Remain unfinished means continue to be incomplete or not fully achieved.","zh":"仍未完成是指繼續不完整或未完全達成。"},{"en":"A recovery plan may remain unfinished if the person cannot find stable work.","zh":"如果一個人找不到穩定工作，康復計劃可能仍未完成。"},{"en":"Rehabilitation remains unfinished when society offers treatment but no path back to normal life.","zh":"當社會提供治療但沒有回到正常生活的道路時，更生仍未完成。"},{"en":"This phrase shows that a process needs a final practical step.","zh":"這個短語顯示一個過程需要最後的實際步驟。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"leave custody","meaning":"離開羈押；獲釋","examples":[{"en":"A person may leave custody with determination.","zh":"一個人可能帶着決心離開羈押。"},{"en":"To leave custody means to be released from detention, prison, or official confinement.","zh":"離開羈押是指從拘留、監禁或官方限制中獲釋。"},{"en":"Someone who leaves custody may need housing, work, and family support.","zh":"離開羈押的人可能需要住處、工作和家庭支援。"},{"en":"Leaving custody is only the beginning of rebuilding daily life.","zh":"離開羈押只是重建日常生活的開始。"},{"en":"This phrase shows a transition from confinement to society.","zh":"這個短語顯示由羈押走向社會的過渡。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"treatment","meaning":"治療；戒毒治療","examples":[{"en":"A person may leave treatment with determination.","zh":"一個人可能帶着決心離開治療。"},{"en":"Treatment means professional help for illness, addiction, or other serious problems.","zh":"治療是指為疾病、毒癮或其他嚴重問題提供的專業幫助。"},{"en":"Drug treatment may include counselling, medical care, and support groups.","zh":"戒毒治療可能包括輔導、醫療照顧和支援小組。"},{"en":"Leaving treatment does not end the need for support and stable routines.","zh":"離開治療不代表不再需要支援和穩定規律。"},{"en":"This word describes a recovery process, not a punishment.","zh":"這個詞描述康復過程，而不是懲罰。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"with determination","meaning":"帶着決心","examples":[{"en":"A person may leave custody or treatment with determination.","zh":"一個人可能帶着決心離開羈押或治療。"},{"en":"With determination means with a strong decision to keep trying and change.","zh":"帶着決心是指帶着堅定決定去繼續嘗試和改變。"},{"en":"A person with determination may continue looking for work even after rejection.","zh":"有決心的人可能即使被拒絕，仍繼續找工作。"},{"en":"Determination matters because rebuilding a life usually takes time.","zh":"決心很重要，因為重建人生通常需要時間。"},{"en":"This phrase shows inner strength at the start of a difficult journey.","zh":"這個短語顯示艱難旅程開始時的內在力量。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"dignity is hard to restore","meaning":"尊嚴難以恢復","examples":[{"en":"Without a job, dignity is hard to restore.","zh":"沒有工作，尊嚴難以恢復。"},{"en":"Dignity is hard to restore means self-respect and social respect are difficult to rebuild.","zh":"尊嚴難以恢復，是指自尊和社會尊重很難重建。"},{"en":"A stable job can help restore dignity because the person can contribute and support family.","zh":"穩定工作可以幫助恢復尊嚴，因為人可以作出貢獻和支援家庭。"},{"en":"When people are always rejected, dignity becomes harder to recover.","zh":"當人總是被拒絕時，尊嚴會更難恢復。"},{"en":"This phrase shows the emotional cost of unemployment after rehabilitation.","zh":"這個短語顯示更生後失業帶來的情感代價。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"temptation is harder to resist","meaning":"更難抵抗誘惑","examples":[{"en":"Without employment, temptation is harder to resist.","zh":"沒有就業，誘惑更難抵抗。"},{"en":"Temptation is harder to resist means it becomes more difficult to avoid harmful choices.","zh":"更難抵抗誘惑，是指更難避免有害選擇。"},{"en":"A person without stable routines may find old habits harder to resist.","zh":"沒有穩定規律的人可能覺得舊習慣更難抵抗。"},{"en":"Employment helps reduce temptation by giving structure, purpose, and income.","zh":"就業透過提供規律、目的和收入來減少誘惑。"},{"en":"This phrase explains why opportunity can support public safety.","zh":"這個短語解釋為何機會可以支援公共安全。"}],"source":"2012 Q8.pdf","sourcePage":12},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, a stable workplace gives structure and hope.","zh":"相比之下，穩定工作場所帶來規律和希望。"},{"en":"By contrast introduces a clear difference from the previous situation.","zh":"相比之下，用來引出與前一種情況明顯不同的情況。"},{"en":"Without work, life may feel empty; by contrast, a job gives routine and purpose.","zh":"沒有工作時，生活可能感覺空洞；相比之下，工作帶來規律和目的。"},{"en":"Writers use by contrast to compare two opposite conditions.","zh":"作者使用「相比之下」來比較兩種相反情況。"},{"en":"This phrase helps show the benefit of employment more clearly.","zh":"這個短語幫助更清楚顯示就業的好處。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"stable workplace","meaning":"穩定工作場所","examples":[{"en":"A stable workplace gives structure to the day.","zh":"穩定工作場所為一天帶來規律。"},{"en":"A stable workplace is a job environment with regular duties, rules, and expectations.","zh":"穩定工作場所是有固定職責、規則和期望的工作環境。"},{"en":"A stable workplace can help a new employee build punctuality and confidence.","zh":"穩定工作場所可以幫助新員工建立守時和信心。"},{"en":"Stability at work reduces confusion and makes progress easier to measure.","zh":"工作中的穩定性減少混亂，並令進步更容易衡量。"},{"en":"This phrase shows why employment can support rehabilitation.","zh":"這個短語顯示就業為何能支援更生。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"give structure to the day","meaning":"為一天帶來規律","examples":[{"en":"Employment gives structure to the day.","zh":"就業為一天帶來規律。"},{"en":"To give structure to the day means to create a clear routine with tasks, times, and responsibilities.","zh":"為一天帶來規律，是指創造有任務、時間和責任的清晰日常。"},{"en":"A morning shift gives structure to the day because the worker knows when to wake, travel, and work.","zh":"早更工作為一天帶來規律，因為員工知道何時起床、出門和工作。"},{"en":"Daily structure can help people avoid drifting back into harmful habits.","zh":"日常規律可以幫助人避免重新陷入有害習慣。"},{"en":"This phrase connects employment with stability and recovery.","zh":"這個短語把就業與穩定和康復連接起來。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"income to the family","meaning":"為家庭帶來收入","examples":[{"en":"A job gives income to the family.","zh":"工作為家庭帶來收入。"},{"en":"Income to the family means money earned that helps support household needs.","zh":"為家庭帶來收入，是指賺取金錢以支援家庭需要。"},{"en":"A stable wage gives income to the family for rent, food, transport, and school costs.","zh":"穩定工資為家庭帶來租金、食物、交通和學費方面的收入。"},{"en":"Family income can reduce stress and help rebuild trust at home.","zh":"家庭收入可以減少壓力，並幫助在家中重建信任。"},{"en":"This phrase shows the wider effect of one person’s employment.","zh":"這個短語顯示一個人就業的更廣泛影響。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"hope to the individual","meaning":"為個人帶來希望","examples":[{"en":"A stable job gives hope to the individual.","zh":"穩定工作為個人帶來希望。"},{"en":"Hope to the individual means personal belief that a better future is possible.","zh":"為個人帶來希望，是指讓個人相信更好的未來有可能出現。"},{"en":"A job gives hope when someone starts to see a path beyond past mistakes.","zh":"當一個人開始看見超越過去錯誤的道路時，工作就帶來希望。"},{"en":"Hope can grow when effort leads to income, trust, and routine.","zh":"當努力帶來收入、信任和規律時，希望會增加。"},{"en":"This phrase focuses on the inner effect of employment.","zh":"這個短語著重就業對內心的影響。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"one person’s second chance","meaning":"一個人的第二次機會","examples":[{"en":"One person’s second chance can benefit many others.","zh":"一個人的第二次機會可以惠及許多其他人。"},{"en":"One person’s second chance means one individual’s opportunity to rebuild after past mistakes.","zh":"一個人的第二次機會，是指一個人在過去錯誤後重建人生的機會。"},{"en":"A parent’s second chance at work can also give children a calmer home.","zh":"父母在工作上的第二次機會，也可以給孩子一個更安穩的家。"},{"en":"When one person rebuilds, families, teams, and communities may also benefit.","zh":"當一個人重建人生時，家庭、團隊和社區也可能受惠。"},{"en":"This phrase shows that opportunity can spread beyond the individual.","zh":"這個短語顯示機會可以擴展到個人以外。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"calmer home","meaning":"更安穩的家","examples":[{"en":"A second chance can become a child’s calmer home.","zh":"第二次機會可以成為孩子更安穩的家。"},{"en":"A calmer home is a household with less fear, stress, conflict, or instability.","zh":"更安穩的家是較少恐懼、壓力、衝突或不穩定的家庭。"},{"en":"Stable employment can help create a calmer home by reducing money pressure.","zh":"穩定就業可以透過減少金錢壓力來創造更安穩的家。"},{"en":"Children benefit when adults have routines and hope.","zh":"當成年人有規律和希望時，孩子會受惠。"},{"en":"This phrase shows how employment can affect family life.","zh":"這個短語顯示就業如何影響家庭生活。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"reliable pair of hands","meaning":"可靠幫手","examples":[{"en":"A second chance can become a team’s reliable pair of hands.","zh":"第二次機會可以成為團隊的可靠幫手。"},{"en":"A reliable pair of hands means a dependable person who can help with work.","zh":"可靠幫手是指可以依靠並能協助工作的人。"},{"en":"A kitchen team needs a reliable pair of hands during the lunch rush.","zh":"午餐繁忙時段，廚房團隊需要可靠幫手。"},{"en":"A worker becomes reliable when they arrive on time and complete tasks carefully.","zh":"當員工準時到達並細心完成任務時，就會變得可靠。"},{"en":"This phrase presents the employee as useful and trusted.","zh":"這個短語把員工呈現為有用和可信的人。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"safer future","meaning":"更安全的未來","examples":[{"en":"A second chance can become a community’s safer future.","zh":"第二次機會可以成為社區更安全的未來。"},{"en":"A safer future means a future with less harm, crime, fear, or instability.","zh":"更安全的未來是指較少傷害、罪案、恐懼或不穩定的未來。"},{"en":"Employment can support a safer future by helping people stay in lawful routines.","zh":"就業可以透過幫助人留在合法生活規律中，支援更安全的未來。"},{"en":"Communities become safer when people have reasons and resources to rebuild.","zh":"當人們有理由和資源重建人生時，社區會更安全。"},{"en":"This phrase connects individual change with public benefit.","zh":"這個短語把個人改變與公共利益連接起來。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"sincerely urge","meaning":"誠懇呼籲","examples":[{"en":"The writer sincerely urges businesses to take part.","zh":"作者誠懇呼籲企業參與。"},{"en":"To sincerely urge someone means to strongly and honestly encourage them to act.","zh":"誠懇呼籲某人，是指真誠而有力地鼓勵他們行動。"},{"en":"A teacher may sincerely urge students to ask for help before problems grow.","zh":"老師可能誠懇呼籲學生在問題變大前求助。"},{"en":"This phrase sounds serious because it combines strong appeal with genuine concern.","zh":"這個短語聽起來嚴肅，因為它結合有力呼籲和真誠關心。"},{"en":"It is useful near the end of a persuasive letter.","zh":"它適合用於說服性信件的結尾部分。"}],"source":"2012 Q8.pdf","sourcePage":13},{"front":"take part in","meaning":"參與","examples":[{"en":"Businesses are urged to take part in Second Chance.","zh":"企業被呼籲參與「第二次機會」。"},{"en":"To take part in something means to join and be involved in an activity or scheme.","zh":"參與某事是指加入並投入某項活動或計劃。"},{"en":"A company can take part in the campaign by registering vacancies.","zh":"公司可以透過登記職位空缺參與這項運動。"},{"en":"Taking part turns support from a good idea into real action.","zh":"參與把支持由好想法變成真實行動。"},{"en":"This phrase focuses on active participation.","zh":"這個短語著重積極加入。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"register your interest","meaning":"登記參與意向","examples":[{"en":"Companies can register their interest in the scheme.","zh":"公司可以登記參與這項計劃的意向。"},{"en":"To register your interest means to formally say that you may want to join or learn more.","zh":"登記參與意向，是指正式表示可能想加入或了解更多。"},{"en":"A business may register interest before deciding which vacancies are suitable.","zh":"企業可能在決定哪些職位合適前先登記意向。"},{"en":"Registering interest is a low-risk first step toward participation.","zh":"登記意向是邁向參與的低風險第一步。"},{"en":"This phrase invites action without forcing an immediate final decision.","zh":"這個短語邀請行動，但不強迫立即作最終決定。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"identify suitable vacancies","meaning":"找出合適職位空缺","examples":[{"en":"Businesses should identify suitable vacancies.","zh":"企業應找出合適職位空缺。"},{"en":"To identify suitable vacancies means to find job openings that fit the applicants’ skills and readiness.","zh":"找出合適職位空缺，是指尋找符合申請人技能和準備程度的工作崗位。"},{"en":"A hotel may identify cleaning or kitchen posts as suitable vacancies.","zh":"酒店可能把清潔或廚房職位找出來作合適空缺。"},{"en":"Careful identification helps prevent mismatches and workplace stress.","zh":"小心找出職位有助防止錯配和職場壓力。"},{"en":"This phrase shows that fair hiring requires preparation.","zh":"這個短語顯示公平招聘需要準備。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"fit your company’s needs","meaning":"配合貴公司的需要","examples":[{"en":"The scheme can be adjusted to fit a company’s needs.","zh":"這項計劃可以調整，以配合貴公司的需要。"},{"en":"To fit your company’s needs means to match what the company actually requires.","zh":"配合貴公司的需要，是指符合公司實際所需。"},{"en":"A restaurant’s needs may include weekend staff, kitchen helpers, or delivery support.","zh":"餐廳的需要可能包括週末員工、廚房助理或送貨支援。"},{"en":"A scheme fits better when vacancies, training, and support match daily operations.","zh":"當職位、培訓和支援配合日常營運時，計劃會更合適。"},{"en":"This phrase reassures employers that participation can be practical.","zh":"這個短語讓僱主放心，知道參與可以實際可行。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"truly resilient city","meaning":"真正有韌性的城市","examples":[{"en":"Hong Kong should become a truly resilient city.","zh":"香港應成為真正有韌性的城市。"},{"en":"A truly resilient city is a city that can recover from difficulty and help its people rebuild.","zh":"真正有韌性的城市，是能從困難中恢復並幫助市民重建人生的城市。"},{"en":"A resilient city does not leave people permanently outside society after mistakes.","zh":"有韌性的城市不會在人犯錯後永久把他們排除於社會之外。"},{"en":"Fair employment can make a city more resilient by turning exclusion into contribution.","zh":"公平就業可以透過把排斥轉化為貢獻，令城市更有韌性。"},{"en":"This phrase connects social recovery with the strength of the whole city.","zh":"這個短語把社會復原與整座城市的力量連接起來。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"be permanently defined by","meaning":"被……永久定義","examples":[{"en":"People should not be permanently defined by yesterday’s mistakes.","zh":"人不應被昔日的錯誤永久定義。"},{"en":"To be permanently defined by something means to be judged forever by one part of the past.","zh":"被某事永久定義，是指永遠只根據過去某一部分來評價。"},{"en":"A student should not be permanently defined by one failed exam.","zh":"學生不應被一次考試失敗永久定義。"},{"en":"Rehabilitated persons need the chance to be seen through present effort and future potential.","zh":"更生人士需要機會，讓人透過現時努力和未來潛力看待他們。"},{"en":"This phrase rejects lifelong labelling.","zh":"這個短語反對終身標籤。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"yesterday’s mistakes","meaning":"昔日的錯誤","examples":[{"en":"Hong Kong should not define people by yesterday’s mistakes.","zh":"香港不應以昔日的錯誤定義人。"},{"en":"Yesterday’s mistakes means wrong actions or failures from the past.","zh":"昔日的錯誤是指過去的錯誤行動或失敗。"},{"en":"A person can learn from yesterday’s mistakes and make different choices today.","zh":"一個人可以從昔日的錯誤中學習，並在今天作出不同選擇。"},{"en":"If society focuses only on yesterday’s mistakes, it may block tomorrow’s contribution.","zh":"如果社會只專注於昔日的錯誤，可能會阻擋明日的貢獻。"},{"en":"This phrase contrasts the past with the possibility of change.","zh":"這個短語對比過去與改變的可能。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"open doors","meaning":"打開大門；提供機會","examples":[{"en":"Society must open doors for people who want to rebuild.","zh":"社會必須為想重建人生的人打開大門。"},{"en":"To open doors means to create opportunities or access for people.","zh":"打開大門是指為人創造機會或使用途徑。"},{"en":"Employers open doors when they interview candidates who are usually ignored.","zh":"僱主面見通常被忽視的候選人時，就是打開大門。"},{"en":"Opening doors does not mean removing standards; it means allowing a fair chance.","zh":"打開大門不代表取消標準，而是給予公平機會。"},{"en":"This phrase presents opportunity as an entrance back into society.","zh":"這個短語把機會呈現為重返社會的入口。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"make way for","meaning":"為……鋪路","examples":[{"en":"Opening doors can make way for recovery and renewal.","zh":"打開大門可以為康復和更新鋪路。"},{"en":"To make way for something means to create the conditions that allow it to happen.","zh":"為某事鋪路，是指創造讓它發生的條件。"},{"en":"A stable job can make way for better routines and family trust.","zh":"穩定工作可以為更好生活規律和家庭信任鋪路。"},{"en":"Fair employment makes way for recovery by giving people a real role.","zh":"公平就業透過給人真實角色，為康復鋪路。"},{"en":"This phrase shows how one action prepares for a better result.","zh":"這個短語顯示一個行動如何為更好結果作準備。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"responsibility, recovery and renewal","meaning":"責任、更生和更新","examples":[{"en":"The campaign makes way for responsibility, recovery and renewal.","zh":"這項運動為責任、更生和更新鋪路。"},{"en":"Responsibility, recovery and renewal mean accepting duty, healing from past harm, and beginning again.","zh":"責任、更生和更新，是指承擔義務、從過去傷害中復原，並重新開始。"},{"en":"A job can support responsibility through rules, recovery through routine, and renewal through hope.","zh":"工作可以透過規則支援責任，透過規律支援更生，透過希望支援更新。"},{"en":"These three ideas describe what a second chance should create.","zh":"這三個想法描述第二次機會應創造的東西。"},{"en":"This phrase gives the campaign a clear moral purpose.","zh":"這個短語給運動清晰的道德目的。"}],"source":"2012 Q8.pdf","sourcePage":14},{"front":"join us in giving","meaning":"加入我們一起給予","examples":[{"en":"The writer asks businesses to join them in giving a second chance.","zh":"作者請求企業加入他們，一起給予第二次機會。"},{"en":"Join us in giving means take part together with us in offering something meaningful.","zh":"加入我們一起給予，是指與我們一起參與提供有意義的東西。"},{"en":"A charity may ask companies to join them in giving students work experience.","zh":"慈善機構可能請公司加入它們，一起給學生工作經驗。"},{"en":"This phrase sounds inclusive because it invites shared responsibility.","zh":"這個短語聽起來有包容性，因為它邀請共同責任。"},{"en":"It turns the request into a collective action.","zh":"它把請求變成集體行動。"}],"source":"2012 Q8.pdf","sourcePage":15},{"front":"build a stronger Hong Kong","meaning":"建設更強大的香港","examples":[{"en":"Second Chance can help build a stronger Hong Kong.","zh":"「第二次機會」可以幫助建設更強大的香港。"},{"en":"To build a stronger Hong Kong means to help the city become fairer, safer, and more resilient.","zh":"建設更強大的香港，是指幫助城市變得更公平、更安全和更有韌性。"},{"en":"A city becomes stronger when more people can work, contribute, and rebuild their lives.","zh":"當更多人能工作、貢獻和重建人生時，城市會變得更強大。"},{"en":"Giving second chances can strengthen families, businesses, and communities together.","zh":"給予第二次機會可以同時強化家庭、企業和社區。"},{"en":"This phrase connects individual employment with the city’s future.","zh":"這個短語把個人就業與城市未來連接起來。"}],"source":"2012 Q8.pdf","sourcePage":15},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully is used to close a formal invitation letter.","zh":"「謹啟」用於結束正式邀請信。"},{"en":"Yours faithfully is a formal closing used when the writer does not know the recipient personally.","zh":"「謹啟」是作者不熟悉收信人時使用的正式結語。"},{"en":"A student may end a letter to business leaders with Yours faithfully.","zh":"學生可能以「謹啟」結束寫給商界領袖的信。"},{"en":"This closing shows respect and completes the formal letter structure.","zh":"這個結語表示尊重，並完成正式信件結構。"},{"en":"It is more suitable for official letters than casual endings.","zh":"它比隨意結尾更適合正式信件。"}],"source":"2012 Q8.pdf","sourcePage":15},{"front":"intern","meaning":"實習生","examples":[{"en":"Chris Wong signs the letter as an intern.","zh":"Chris Wong 以實習生身份署名。"},{"en":"An intern is a temporary trainee who works in an organisation to learn and gain experience.","zh":"實習生是在機構中暫時受訓、學習和累積經驗的人。"},{"en":"An intern may help with research, letters, meetings, and community projects.","zh":"實習生可能協助資料搜集、寫信、會議和社區項目。"},{"en":"Signing as an intern tells readers the writer’s role and level of responsibility.","zh":"以實習生身份署名，告訴讀者作者的角色和責任層級。"},{"en":"This word describes someone learning through real workplace experience.","zh":"這個詞描述透過真實職場經驗學習的人。"}],"source":"2012 Q8.pdf","sourcePage":15}],"dse/writing/part-b/2012/Q9":[{"front":"when the smile disappears","meaning":"當笑容消失時","examples":[{"en":"The article is called “When the Smile Disappears.”","zh":"這篇文章名為《當笑容消失時》。"},{"en":"“When the smile disappears” suggests the moment when a happy-looking person begins to show hidden pain.","zh":"“when the smile disappears” 暗示一個看似快樂的人開始顯露隱藏痛苦的時刻。"},{"en":"A teacher may notice something is wrong when a cheerful student’s smile disappears.","zh":"當一位開朗學生的笑容消失時，老師可能會察覺不妥。"},{"en":"The phrase reminds us that emotional suffering can hide behind ordinary behaviour.","zh":"這個片語提醒我們，情緒痛苦可能藏在平常行為背後。"},{"en":"It creates a serious mood for an article about mental health.","zh":"它為一篇關於精神健康的文章營造嚴肅氣氛。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"school magazine","meaning":"學校雜誌","examples":[{"en":"Our school magazine decided to run a special feature.","zh":"我們的學校雜誌決定刊登一個專題。"},{"en":"A school magazine is a publication written for students, teachers, and the school community.","zh":"school magazine 是為學生、老師和學校社群而寫的刊物。"},{"en":"A school magazine may include interviews, articles, artwork, and student opinions.","zh":"學校雜誌可能包括訪問、文章、藝術作品和學生意見。"},{"en":"When a school magazine discusses mental health, it can start important conversations.","zh":"當學校雜誌討論精神健康時，它可以開始重要對話。"},{"en":"This phrase shows the article is written for a school audience.","zh":"這個片語顯示文章是寫給學校讀者的。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"run a special feature on","meaning":"刊登關於……的專題","examples":[{"en":"The school magazine decided to run a special feature on mental health.","zh":"學校雜誌決定刊登一個關於精神健康的專題。"},{"en":"To run a special feature on a topic means to publish a focused article or section about it.","zh":"run a special feature on 某題目，意思是刊登集中討論該題目的文章或欄目。"},{"en":"A newspaper may run a special feature on teenage stress before exams.","zh":"報章可能在考試前刊登關於青少年壓力的專題。"},{"en":"A school magazine can run a special feature on mental health to raise awareness.","zh":"學校雜誌可以刊登關於精神健康的專題，以提高意識。"},{"en":"This phrase suggests the topic deserves special attention.","zh":"這個片語表示該題目值得特別關注。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"mental health","meaning":"精神健康","examples":[{"en":"The special feature focuses on mental health.","zh":"這個專題集中討論精神健康。"},{"en":"Mental health means a person’s emotional and psychological wellbeing.","zh":"mental health 指一個人的情緒和心理健康。"},{"en":"Good mental health helps students handle stress, relationships, and daily challenges.","zh":"良好精神健康幫助學生處理壓力、人際關係和日常挑戰。"},{"en":"Poor mental health may affect sleep, energy, concentration, and hope.","zh":"精神健康欠佳可能影響睡眠、精力、專注力和希望。"},{"en":"This phrase is important because students’ feelings matter as much as their marks.","zh":"這個片語很重要，因為學生的感受與分數同樣重要。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"immediately thought of","meaning":"立即想起","examples":[{"en":"I immediately thought of a friend I shall call Ethan.","zh":"我立即想起一位我姑且稱為 Ethan 的朋友。"},{"en":"To immediately think of someone means that person comes to mind at once.","zh":"immediately thought of someone 意思是某人立刻浮現在腦海中。"},{"en":"When the teacher mentioned kindness, I immediately thought of my best friend.","zh":"當老師提到善良時，我立即想起我的好朋友。"},{"en":"The writer immediately thought of Ethan because his story matched the topic.","zh":"作者立即想起 Ethan，因為他的故事與主題相符。"},{"en":"This phrase shows a strong personal connection to the issue.","zh":"這個片語顯示作者與議題有強烈個人連繫。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"a friend I shall call","meaning":"一位我姑且稱為……的朋友","examples":[{"en":"The writer tells the story of a friend he shall call Ethan.","zh":"作者講述一位他姑且稱為 Ethan 的朋友的故事。"},{"en":"A friend I shall call means the writer is using a name to protect the person’s privacy.","zh":"a friend I shall call 意思是作者使用一個名字來保護該人的私隱。"},{"en":"In an article, a writer may say “a student I shall call May” instead of using the real name.","zh":"在文章中，作者可能說「一位我姑且稱為 May 的學生」，而不用真名。"},{"en":"This phrase is useful when discussing sensitive personal experiences.","zh":"這個片語適合用於討論敏感個人經歷。"},{"en":"It shows care because the person’s identity is not fully revealed.","zh":"它顯示關心，因為當事人的身份沒有完全公開。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"be trained to","meaning":"被訓練去","examples":[{"en":"Students are trained to chase marks and meet deadlines.","zh":"學生被訓練去追逐分數和趕上截止日期。"},{"en":"Be trained to means be taught or repeatedly encouraged to do something.","zh":"be trained to 意思是被教導或反覆鼓勵去做某事。"},{"en":"Students may be trained to answer exam questions quickly.","zh":"學生可能被訓練去快速回答考試問題。"},{"en":"If students are trained only to chase marks, they may ignore their own wellbeing.","zh":"如果學生只被訓練去追逐分數，可能會忽視自己的身心健康。"},{"en":"This phrase shows how habits can be shaped by school culture.","zh":"這個片語顯示習慣如何被學校文化塑造。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"chase marks","meaning":"追逐分數","examples":[{"en":"Students are trained to chase marks.","zh":"學生被訓練去追逐分數。"},{"en":"To chase marks means to focus mainly on getting higher scores.","zh":"chase marks 意思是主要專注於取得更高分數。"},{"en":"A student may chase marks by memorising answers without understanding them.","zh":"學生可能透過背誦答案而不理解內容來追逐分數。"},{"en":"Chasing marks can become harmful if students forget sleep, friendship, and health.","zh":"如果學生忘記睡眠、友誼和健康，追逐分數便可能有害。"},{"en":"This phrase criticises a narrow view of education.","zh":"這個片語批評狹隘的教育觀。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"meet deadlines","meaning":"趕上截止日期","examples":[{"en":"Students are trained to meet deadlines.","zh":"學生被訓練去趕上截止日期。"},{"en":"To meet deadlines means to finish work before the final required time.","zh":"meet deadlines 意思是在最後限期前完成工作。"},{"en":"Students meet deadlines when they hand in assignments on time.","zh":"學生準時交功課，就是趕上截止日期。"},{"en":"Meeting deadlines is important, but it should not destroy students’ wellbeing.","zh":"趕上截止日期很重要，但不應摧毀學生的身心健康。"},{"en":"This phrase shows one pressure students face in school life.","zh":"這個片語顯示學生在校園生活中面對的一種壓力。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"look fine","meaning":"看起來沒事","examples":[{"en":"Students often try to look fine even when they are not.","zh":"學生即使不是沒事，也常嘗試看起來沒事。"},{"en":"To look fine means to appear okay on the outside.","zh":"look fine 意思是外表看起來沒有問題。"},{"en":"A student may look fine in class but cry alone after school.","zh":"學生可能在課堂上看起來沒事，放學後卻獨自哭泣。"},{"en":"Looking fine does not always mean someone is emotionally healthy.","zh":"看起來沒事不一定代表一個人情緒健康。"},{"en":"This phrase reminds us not to judge only by appearance.","zh":"這個片語提醒我們不要只憑外表判斷。"}],"source":"2012 Q9.pdf","sourcePage":1},{"front":"anything but fine","meaning":"絕不是沒事","examples":[{"en":"Some students look fine even when they are anything but fine.","zh":"有些學生看起來沒事，但其實絕不是沒事。"},{"en":"Anything but fine means not fine at all, even if the person appears okay.","zh":"anything but fine 意思是完全不是沒事，即使外表看似正常。"},{"en":"A student who laughs with friends may still be anything but fine inside.","zh":"與朋友大笑的學生內心仍可能絕不是沒事。"},{"en":"This phrase shows the gap between appearance and hidden pain.","zh":"這個片語顯示外表與隱藏痛苦之間的差距。"},{"en":"It helps readers understand why noticing small changes matters.","zh":"它幫助讀者理解為何留意細微變化很重要。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"school community","meaning":"學校社群","examples":[{"en":"Ethan’s depression made the school community speak more honestly.","zh":"Ethan 的抑鬱症令學校社群更坦誠地說話。"},{"en":"A school community includes students, teachers, parents, and staff connected to a school.","zh":"school community 包括與學校有關的學生、老師、家長和職員。"},{"en":"A caring school community notices when students are struggling.","zh":"有關懷的學校社群會留意學生何時正在掙扎。"},{"en":"The school community can reduce stigma by talking openly about mental health.","zh":"學校社群可以透過公開談論精神健康來減少污名。"},{"en":"This phrase shows that depression is not only a private issue.","zh":"這個片語顯示抑鬱症不只是私人問題。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"speak more honestly about","meaning":"更坦誠地談論","examples":[{"en":"The school community needs to speak more honestly about pain.","zh":"學校社群需要更坦誠地談論痛苦。"},{"en":"To speak more honestly about something means to discuss it openly and truthfully.","zh":"speak more honestly about 某事，意思是公開而真實地討論它。"},{"en":"Students should speak more honestly about stress instead of pretending everything is fine.","zh":"學生應更坦誠地談論壓力，而不是假裝一切沒事。"},{"en":"Honest conversations can help people seek support earlier.","zh":"坦誠對話可以幫助人更早尋求支援。"},{"en":"This phrase suggests that silence can make suffering worse.","zh":"這個片語表示沉默可能令痛苦惡化。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"suffer quietly","meaning":"默默承受痛苦","examples":[{"en":"No student should have to suffer quietly.","zh":"沒有學生應該要默默承受痛苦。"},{"en":"To suffer quietly means to endure pain without telling others or receiving help.","zh":"suffer quietly 意思是在沒有告訴別人或沒有得到幫助下忍受痛苦。"},{"en":"A student may suffer quietly because he fears being judged.","zh":"學生可能因害怕被批評而默默承受痛苦。"},{"en":"Schools should create safe spaces so students do not suffer quietly.","zh":"學校應建立安全空間，讓學生不用默默承受痛苦。"},{"en":"This phrase shows why support and openness are necessary.","zh":"這個片語顯示支援和開放態度為何必要。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"behind a polite smile","meaning":"在禮貌微笑背後","examples":[{"en":"Students may suffer quietly behind a polite smile.","zh":"學生可能在禮貌微笑背後默默承受痛苦。"},{"en":"Behind a polite smile means hidden under a calm and pleasant expression.","zh":"behind a polite smile 意思是隱藏在平靜而友善的表情之下。"},{"en":"A person may say “I’m fine” behind a polite smile while feeling broken inside.","zh":"一個人可能帶著禮貌微笑說「我沒事」，但內心很痛苦。"},{"en":"This phrase shows that pain can be covered by good manners.","zh":"這個片語顯示痛苦可以被禮貌掩蓋。"},{"en":"It teaches readers to look beyond surface politeness.","zh":"它教讀者不要只看表面禮貌。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"in my view","meaning":"在我看來","examples":[{"en":"In my view, depression is anything but weakness.","zh":"在我看來，抑鬱症絕不是軟弱。"},{"en":"In my view means in my opinion, and it introduces a personal judgement.","zh":"in my view 意思是「在我看來」，用來引出個人判斷。"},{"en":"In my view, students should not be blamed for needing help.","zh":"在我看來，需要幫助的學生不應被責怪。"},{"en":"This phrase helps the writer state a clear position respectfully.","zh":"這個片語幫助作者有禮地表明清晰立場。"},{"en":"It is useful in reflective articles and speeches.","zh":"它適用於反思文章和演講。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"anything but weakness","meaning":"絕不是軟弱","examples":[{"en":"Depression is anything but weakness.","zh":"抑鬱症絕不是軟弱。"},{"en":"Anything but weakness means not weakness at all.","zh":"anything but weakness 意思是完全不是軟弱。"},{"en":"Asking for help is anything but weakness; it can be an act of courage.","zh":"求助絕不是軟弱；它可以是一種勇氣。"},{"en":"Depression is a serious health struggle, not a failure of character.","zh":"抑鬱症是嚴重的健康掙扎，不是性格失敗。"},{"en":"This phrase challenges the unfair belief that suffering means being weak.","zh":"這個片語挑戰「痛苦等於軟弱」的不公平看法。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"the real danger","meaning":"真正的危險","examples":[{"en":"Silence is the real danger.","zh":"沉默才是真正的危險。"},{"en":"The real danger means the most serious threat in the situation.","zh":"the real danger 指情況中最嚴重的威脅。"},{"en":"In mental health problems, the real danger may be suffering without anyone knowing.","zh":"在精神健康問題中，真正的危險可能是痛苦卻無人知道。"},{"en":"Silence can delay help until the pain becomes heavier.","zh":"沉默可能延誤求助，直到痛苦變得更沉重。"},{"en":"This phrase shifts attention from depression itself to the danger of hiding it.","zh":"這個片語把焦點由抑鬱本身轉向隱藏痛苦的危險。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"recovery begins with","meaning":"康復始於","examples":[{"en":"Recovery begins with noticing, listening and seeking help early.","zh":"康復始於留意、聆聽和及早求助。"},{"en":"Recovery begins with means healing starts from a first important step.","zh":"recovery begins with 意思是康復由一個重要的第一步開始。"},{"en":"Recovery may begin with telling one trusted adult the truth.","zh":"康復可能始於向一位可信任的成年人說出真相。"},{"en":"For a struggling student, recovery begins with being noticed and heard.","zh":"對正在掙扎的學生來說，康復始於被留意和被聆聽。"},{"en":"This phrase gives hope because recovery is shown as possible and gradual.","zh":"這個片語帶來希望，因為康復被呈現為可能且逐步發生。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"seeking help early","meaning":"及早求助","examples":[{"en":"Students should learn the importance of seeking help early.","zh":"學生應學習及早求助的重要性。"},{"en":"Seeking help early means asking for support before the problem becomes more serious.","zh":"seeking help early 意思是在問題變得更嚴重前尋求支援。"},{"en":"A student can seek help early by talking to a teacher, counsellor, or parent.","zh":"學生可以透過與老師、輔導員或家長交談來及早求助。"},{"en":"Early help can prevent loneliness and confusion from growing.","zh":"及早幫助可以防止孤獨和混亂加劇。"},{"en":"This phrase teaches that asking for help is responsible, not shameful.","zh":"這個片語教人求助是負責任的，不是可恥的。"}],"source":"2012 Q9.pdf","sourcePage":2},{"front":"up until","meaning":"直到……為止","examples":[{"en":"Up until Secondary Five, Ethan was cheerful and active.","zh":"直到中五為止，Ethan 都開朗而活躍。"},{"en":"Up until means continuing to a particular time and then possibly changing.","zh":"up until 意思是一直持續到某個時間，之後可能出現改變。"},{"en":"Up until last term, the student joined every activity.","zh":"直到上學期為止，那名學生參加每項活動。"},{"en":"This phrase helps show the contrast between Ethan before and after his depression.","zh":"這個片語幫助顯示 Ethan 抑鬱前後的對比。"},{"en":"It prepares readers to notice a turning point.","zh":"它讓讀者準備注意轉捩點。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"Secondary Five","meaning":"中五","examples":[{"en":"Up until Secondary Five, Ethan made everyone laugh.","zh":"直到中五為止，Ethan 都令大家發笑。"},{"en":"Secondary Five is the fifth year of secondary school in Hong Kong.","zh":"Secondary Five 指香港中學的第五年級。"},{"en":"Secondary Five students often face pressure because public exams are approaching.","zh":"中五學生常面對壓力，因為公開考試逐漸接近。"},{"en":"A cheerful Secondary Five student may still be carrying hidden stress.","zh":"開朗的中五學生仍可能承受隱藏壓力。"},{"en":"This phrase places Ethan’s story in a familiar school stage.","zh":"這個片語把 Ethan 的故事放在熟悉的校園階段。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"the kind of boy who","meaning":"那種會……的男生","examples":[{"en":"Ethan was the kind of boy who could make the whole row laugh.","zh":"Ethan 是那種會令整排人發笑的男生。"},{"en":"The kind of boy who means a boy with a particular habit, quality, or personality.","zh":"the kind of boy who 指有某種習慣、特質或性格的男生。"},{"en":"He was the kind of boy who remembered everyone’s birthday.","zh":"他是那種會記得每個人生日的男生。"},{"en":"This phrase helps describe Ethan’s character before things changed.","zh":"這個片語幫助描述 Ethan 在改變前的性格。"},{"en":"It makes the story feel personal and vivid.","zh":"它令故事感覺個人化而生動。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"make the whole row laugh","meaning":"令整排人發笑","examples":[{"en":"Ethan could make the whole row laugh before assembly.","zh":"Ethan 早會前能令整排人發笑。"},{"en":"To make the whole row laugh means to make everyone sitting nearby laugh together.","zh":"make the whole row laugh 意思是令坐在附近的一整排人一起笑。"},{"en":"A funny comment before class can make the whole row laugh.","zh":"課前一句有趣說話可以令整排人發笑。"},{"en":"This phrase shows Ethan was once socially lively and humorous.","zh":"這個片語顯示 Ethan 曾經活躍而有幽默感。"},{"en":"It makes his later silence feel more noticeable.","zh":"它令他後來的沉默更明顯。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"before assembly","meaning":"早會前","examples":[{"en":"Ethan made classmates laugh before assembly.","zh":"Ethan 在早會前令同學發笑。"},{"en":"Before assembly means during the time before the school gathering begins.","zh":"before assembly 意思是在學校集會開始之前的時間。"},{"en":"Students may chat with friends before assembly in the morning.","zh":"學生早上可能在早會前與朋友聊天。"},{"en":"This phrase places the memory in an ordinary school routine.","zh":"這個片語把回憶放在普通校園日常中。"},{"en":"It shows Ethan’s cheerfulness appeared in everyday moments.","zh":"它顯示 Ethan 的開朗出現在日常時刻。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"chaired meetings","meaning":"主持會議","examples":[{"en":"Ethan chaired English Society meetings.","zh":"Ethan 主持英文學會會議。"},{"en":"To chair meetings means to lead meetings and guide the discussion.","zh":"chair meetings 意思是主持會議並引導討論。"},{"en":"A student chairing a meeting may introduce topics and invite others to speak.","zh":"主持會議的學生可能介紹議題並邀請其他人發言。"},{"en":"Ethan’s ability to chair meetings shows he was responsible and active.","zh":"Ethan 能主持會議，顯示他曾經負責任和活躍。"},{"en":"This phrase gives evidence of his confidence before depression appeared.","zh":"這個片語提供他在抑鬱出現前有信心的證據。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"English Society","meaning":"英文學會","examples":[{"en":"Ethan chaired English Society meetings.","zh":"Ethan 主持英文學會會議。"},{"en":"An English Society is a school club for students interested in English activities.","zh":"English Society 是給對英語活動有興趣的學生參加的學校學會。"},{"en":"English Society members may organise debates, reading events, or drama performances.","zh":"英文學會成員可能舉辦辯論、閱讀活動或戲劇表演。"},{"en":"Leading the English Society can build confidence and teamwork.","zh":"帶領英文學會可以建立信心和團隊合作。"},{"en":"This phrase shows Ethan was involved in school life.","zh":"這個片語顯示 Ethan 曾參與校園生活。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"almost without warning","meaning":"幾乎毫無預兆地","examples":[{"en":"Almost without warning, the lights seemed to go out.","zh":"幾乎毫無預兆地，光像是突然熄滅了。"},{"en":"Almost without warning means with very few signs before something changed.","zh":"almost without warning 意思是在幾乎沒有跡象下發生改變。"},{"en":"A student’s mood may change almost without warning, so friends may feel confused.","zh":"學生的情緒可能幾乎毫無預兆地改變，令朋友感到困惑。"},{"en":"This phrase shows how sudden Ethan’s change seemed to others.","zh":"這個片語顯示 Ethan 的轉變在別人眼中有多突然。"},{"en":"It reminds readers that mental health struggles may not announce themselves clearly.","zh":"它提醒讀者，精神健康困擾未必會清楚預告。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"the lights seemed to go out","meaning":"光像是突然熄滅了","examples":[{"en":"After Secondary Five, the lights seemed to go out.","zh":"中五之後，光像是突然熄滅了。"},{"en":"The lights seemed to go out means someone’s energy, joy, or liveliness seemed to disappear.","zh":"the lights seemed to go out 意思是某人的精力、快樂或活力像消失了。"},{"en":"When a cheerful student becomes silent, it may feel as if the lights have gone out.","zh":"當開朗學生變得沉默時，可能感覺像光熄滅了。"},{"en":"This image describes emotional change without using medical language.","zh":"這個意象不用醫學語言也能描述情緒改變。"},{"en":"It helps readers feel the sadness of Ethan’s transformation.","zh":"它幫助讀者感受 Ethan 轉變中的悲傷。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"stopped eating with us","meaning":"不再和我們一起吃飯","examples":[{"en":"Ethan stopped eating with his friends.","zh":"Ethan 不再和朋友一起吃飯。"},{"en":"Stopped eating with us means no longer joined friends for meals.","zh":"stopped eating with us 意思是不再與朋友一起用膳。"},{"en":"A student who suddenly stops eating with friends may be withdrawing socially.","zh":"突然不再和朋友吃飯的學生，可能正在社交退縮。"},{"en":"This change can be a small but important warning sign.","zh":"這種改變可以是細小但重要的警號。"},{"en":"The phrase shows how depression can affect ordinary friendships.","zh":"這個片語顯示抑鬱如何影響平常友誼。"}],"source":"2012 Q9.pdf","sourcePage":3},{"front":"neat enough to be used as","meaning":"整齊得足以被用作","examples":[{"en":"His homework was once neat enough to be used as a model answer.","zh":"他的功課曾經整齊得足以被用作範文答案。"},{"en":"Neat enough to be used as means so tidy or good that it can serve as an example.","zh":"neat enough to be used as 意思是整齊或優秀到可以作為例子。"},{"en":"A student’s notes may be neat enough to be used as revision material for the class.","zh":"學生的筆記可能整齊得足以被全班用作溫習材料。"},{"en":"This phrase shows Ethan used to be careful and organised.","zh":"這個片語顯示 Ethan 以前細心而有條理。"},{"en":"It makes the later missing homework feel more serious.","zh":"它令後來欠交功課變得更嚴重。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"model answer","meaning":"範文；標準答案","examples":[{"en":"His homework was once good enough to be used as a model answer.","zh":"他的功課曾經好得足以被用作範文答案。"},{"en":"A model answer is an example answer that shows students what a strong response looks like.","zh":"model answer 是向學生展示優秀答案應如何寫的示範答案。"},{"en":"Teachers may share a model answer after a test.","zh":"老師可能在測驗後分享範文答案。"},{"en":"If Ethan’s work was once a model answer, his later decline was noticeable.","zh":"如果 Ethan 的作品曾是範文答案，他後來的退步便很明顯。"},{"en":"This phrase shows the high standard he once reached.","zh":"這個片語顯示他曾達到很高標準。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"became late or missing","meaning":"變成遲交或欠交","examples":[{"en":"His homework became late or missing.","zh":"他的功課變成遲交或欠交。"},{"en":"Became late or missing means assignments were handed in after the deadline or not handed in at all.","zh":"became late or missing 意思是功課在截止日期後才交，或完全沒有交。"},{"en":"A sudden pattern of late or missing homework may show a student is struggling.","zh":"功課突然經常遲交或欠交，可能顯示學生正在掙扎。"},{"en":"Teachers should ask gently why work has become late or missing.","zh":"老師應溫和地詢問為何功課變成遲交或欠交。"},{"en":"This phrase shows a change in behaviour, not simply laziness.","zh":"這個片語顯示行為轉變，而不只是懶惰。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"anything was wrong","meaning":"是否有甚麼不妥","examples":[{"en":"Teachers asked whether anything was wrong.","zh":"老師問是否有甚麼不妥。"},{"en":"Anything was wrong means there was a problem or something troubling the student.","zh":"anything was wrong 意思是有問題或有事情困擾學生。"},{"en":"A caring teacher may ask whether anything is wrong when a student becomes quiet.","zh":"當學生變得沉默，有關懷的老師可能會問是否有甚麼不妥。"},{"en":"This question opens space for students to speak if they are ready.","zh":"這個問題為學生在準備好時發聲留出空間。"},{"en":"The phrase shows concern without making an accusation.","zh":"這個片語顯示關心，而不是指責。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"just tired","meaning":"只是累了","examples":[{"en":"Ethan said he was just tired.","zh":"Ethan 說他只是累了。"},{"en":"Just tired means only feeling physically or mentally exhausted, at least on the surface.","zh":"just tired 意思是表面上只是身體或精神疲倦。"},{"en":"Students may say they are just tired when they do not know how to explain deeper pain.","zh":"學生不知道如何解釋更深痛苦時，可能說自己只是累了。"},{"en":"This phrase can hide more serious emotional struggles.","zh":"這個片語可能隱藏更嚴重的情緒掙扎。"},{"en":"It reminds friends not to ignore repeated tiredness.","zh":"它提醒朋友不要忽視反覆出現的疲倦。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, it looked like laziness.","zh":"乍看之下，這看起來像懶惰。"},{"en":"At first glance means when first seen, before looking carefully.","zh":"at first glance 意思是初次看見時，尚未仔細了解。"},{"en":"At first glance, a quiet student may seem rude, but he may be anxious.","zh":"乍看之下，沉默的學生可能像無禮，但他可能只是焦慮。"},{"en":"This phrase warns readers not to judge too quickly.","zh":"這個片語提醒讀者不要太快判斷。"},{"en":"It prepares a contrast with a deeper explanation.","zh":"它為之後更深層解釋作鋪墊。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"looked like laziness","meaning":"看起來像懶惰","examples":[{"en":"At first glance, Ethan’s behaviour looked like laziness.","zh":"乍看之下，Ethan 的行為看起來像懶惰。"},{"en":"Looked like laziness means appeared to be lack of effort or care.","zh":"looked like laziness 意思是看似缺乏努力或不在乎。"},{"en":"Missing homework may look like laziness, but it can come from exhaustion.","zh":"欠交功課可能看起來像懶惰，但也可能源自身心俱疲。"},{"en":"This phrase shows how mental health struggles can be misunderstood.","zh":"這個片語顯示精神健康掙扎如何被誤解。"},{"en":"It teaches readers to ask what is behind behaviour.","zh":"它教讀者要問行為背後有甚麼原因。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"on closer inspection","meaning":"仔細看時","examples":[{"en":"On closer inspection, it was exhaustion.","zh":"仔細看時，那是身心俱疲。"},{"en":"On closer inspection means after looking more carefully at the situation.","zh":"on closer inspection 意思是更仔細查看情況之後。"},{"en":"On closer inspection, the student’s silence was fear, not rudeness.","zh":"仔細看時，學生的沉默是恐懼，而不是無禮。"},{"en":"This phrase helps correct a surface judgement.","zh":"這個片語幫助修正表面判斷。"},{"en":"It shows that understanding requires patience.","zh":"它顯示理解需要耐性。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"exhaustion","meaning":"身心俱疲","examples":[{"en":"His behaviour was not laziness, but exhaustion.","zh":"他的行為不是懶惰，而是身心俱疲。"},{"en":"Exhaustion means extreme tiredness of the body, mind, or emotions.","zh":"exhaustion 指身體、思想或情緒上的極度疲倦。"},{"en":"A student with exhaustion may find even simple homework difficult.","zh":"身心俱疲的學生可能連簡單功課也覺得困難。"},{"en":"Long-term stress can lead to exhaustion if nobody helps.","zh":"如果沒有人幫助，長期壓力可能導致身心俱疲。"},{"en":"This word explains why ordinary tasks may suddenly feel impossible.","zh":"這個字解釋為何平常任務可能突然變得不可能。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"did not arrive with thunder","meaning":"並不是轟然降臨","examples":[{"en":"Depression did not arrive with thunder.","zh":"抑鬱症並不是轟然降臨。"},{"en":"Did not arrive with thunder means did not come in a loud, obvious, dramatic way.","zh":"did not arrive with thunder 意思是並非以巨大、明顯或戲劇性的方式到來。"},{"en":"Stress may not arrive with thunder; it may build quietly day by day.","zh":"壓力未必轟然降臨；它可能每天靜靜累積。"},{"en":"This phrase shows that depression can begin silently.","zh":"這個片語顯示抑鬱症可以靜悄悄地開始。"},{"en":"It warns readers that serious problems may start without clear drama.","zh":"它提醒讀者，嚴重問題可能在沒有明顯戲劇性的情況下開始。"}],"source":"2012 Q9.pdf","sourcePage":4},{"front":"quite the contrary","meaning":"恰恰相反","examples":[{"en":"Quite the contrary: it arrived quietly.","zh":"恰恰相反：它靜悄悄地到來。"},{"en":"Quite the contrary means the truth is the opposite of what was just suggested.","zh":"quite the contrary 意思是真相與剛才暗示的相反。"},{"en":"Some people think depression is always obvious; quite the contrary, it can be hidden.","zh":"有些人以為抑鬱症總是明顯；恰恰相反，它可以被隱藏。"},{"en":"This phrase introduces a strong contrast.","zh":"這個片語引出強烈對比。"},{"en":"It helps the writer correct a false expectation.","zh":"它幫助作者糾正錯誤期望。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"arrived quietly","meaning":"靜悄悄地到來","examples":[{"en":"Depression arrived quietly.","zh":"抑鬱症靜悄悄地到來。"},{"en":"Arrived quietly means came without making itself obvious at first.","zh":"arrived quietly 意思是一開始在不明顯的情況下出現。"},{"en":"A student’s sadness may arrive quietly through small changes in sleep and appetite.","zh":"學生的悲傷可能透過睡眠和食慾的小改變靜悄悄地到來。"},{"en":"Quiet arrival makes the problem harder for friends to notice.","zh":"靜悄悄地到來令朋友更難察覺問題。"},{"en":"This phrase shows why early signs matter.","zh":"這個片語顯示早期跡象為何重要。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"turning ordinary things into","meaning":"把平常事變成","examples":[{"en":"Depression turned ordinary things into tasks too heavy to lift.","zh":"抑鬱症把平常事變成沉重得難以承受的任務。"},{"en":"Turning ordinary things into something means changing normal activities into a different experience.","zh":"turning ordinary things into something 意思是把正常活動變成另一種經歷。"},{"en":"Anxiety can turn a simple phone call into something frightening.","zh":"焦慮可以把一通簡單電話變成可怕的事情。"},{"en":"Depression may turn getting dressed into a difficult task.","zh":"抑鬱症可能把穿衣服變成困難任務。"},{"en":"This phrase helps readers understand how illness changes daily life.","zh":"這個片語幫助讀者理解疾病如何改變日常生活。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"ordinary things","meaning":"平常事","examples":[{"en":"Depression can make ordinary things feel difficult.","zh":"抑鬱症可以令平常事感覺困難。"},{"en":"Ordinary things are normal daily actions, such as eating, replying to messages, or opening a book.","zh":"ordinary things 是正常日常行動，例如吃飯、回覆訊息或打開書本。"},{"en":"For a healthy student, ordinary things may feel easy and automatic.","zh":"對健康學生來說，平常事可能容易而自然。"},{"en":"For someone depressed, ordinary things may require huge effort.","zh":"對抑鬱的人來說，平常事可能需要巨大力氣。"},{"en":"This phrase shows how serious suffering can hide inside daily routines.","zh":"這個片語顯示嚴重痛苦如何藏在日常規律中。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"getting out of bed","meaning":"起床","examples":[{"en":"Getting out of bed became a task too heavy to lift.","zh":"起床變成沉重得難以承受的任務。"},{"en":"Getting out of bed means leaving the bed and starting the day.","zh":"getting out of bed 意思是離開床並開始一天。"},{"en":"A depressed student may find getting out of bed extremely difficult.","zh":"抑鬱學生可能覺得起床極其困難。"},{"en":"If getting out of bed feels impossible, the person may need support.","zh":"如果起床感覺不可能，那個人可能需要支援。"},{"en":"This phrase shows how depression can affect the first step of daily life.","zh":"這個片語顯示抑鬱如何影響日常生活的第一步。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"replying to messages","meaning":"回覆訊息","examples":[{"en":"Replying to messages became difficult.","zh":"回覆訊息變得困難。"},{"en":"Replying to messages means answering texts, chats, or emails.","zh":"replying to messages 意思是回覆短訊、聊天訊息或電郵。"},{"en":"A struggling student may read messages but feel unable to reply.","zh":"正在掙扎的學生可能讀了訊息，卻感到無法回覆。"},{"en":"Friends should not immediately assume silence means rudeness.","zh":"朋友不應立即假設沉默就是無禮。"},{"en":"This phrase shows how depression can weaken social connection.","zh":"這個片語顯示抑鬱如何削弱社交連繫。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"opening a textbook","meaning":"打開教科書","examples":[{"en":"Opening a textbook felt too heavy to lift.","zh":"打開教科書感覺沉重得難以承受。"},{"en":"Opening a textbook means beginning to study by turning to school materials.","zh":"opening a textbook 意思是翻開學習材料開始溫習。"},{"en":"A student under heavy emotional stress may struggle even to open a textbook.","zh":"承受沉重情緒壓力的學生，可能連打開教科書也覺得困難。"},{"en":"This difficulty may be about exhaustion, not lack of intelligence.","zh":"這種困難可能關乎身心俱疲，而不是智力不足。"},{"en":"The phrase shows how schoolwork can feel impossible during depression.","zh":"這個片語顯示抑鬱期間學業可以感覺不可能完成。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"too heavy to lift","meaning":"沉重得難以承受","examples":[{"en":"Ordinary tasks felt too heavy to lift.","zh":"平常任務感覺沉重得難以承受。"},{"en":"Too heavy to lift means emotionally or mentally too difficult to manage.","zh":"too heavy to lift 意思是在情緒或心理上難以處理。"},{"en":"A simple email may feel too heavy to lift when someone is overwhelmed.","zh":"當一個人被壓垮時，一封簡單電郵也可能沉重得難以承受。"},{"en":"This phrase is not about physical weight only; it describes emotional burden.","zh":"這個片語不只是指實際重量，也描述情緒負擔。"},{"en":"It helps readers imagine how depression makes small tasks feel huge.","zh":"它幫助讀者想像抑鬱如何令小任務變得巨大。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"not until… did…","meaning":"直到……才……","examples":[{"en":"Not until I saw him alone did it dawn on me.","zh":"直到我看見他獨自一人時，我才明白。"},{"en":"Not until… did… is used to emphasise that understanding happened only after a certain moment.","zh":"not until… did… 用來強調理解只在某一刻之後才發生。"},{"en":"Not until the student stopped speaking did the teacher realise something was wrong.","zh":"直到學生停止說話時，老師才意識到有不妥。"},{"en":"This structure makes the turning point more powerful.","zh":"這個句式令轉捩點更有力。"},{"en":"It shows that real understanding sometimes comes late.","zh":"它顯示真正理解有時來得較遲。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"sitting alone","meaning":"獨自坐着","examples":[{"en":"Ethan was sitting alone after school.","zh":"Ethan 放學後獨自坐着。"},{"en":"Sitting alone means being by oneself, without joining others.","zh":"sitting alone 意思是一個人坐着，沒有與其他人一起。"},{"en":"A student sitting alone every day may be feeling isolated.","zh":"每天獨自坐着的學生可能感到孤立。"},{"en":"Sitting alone once may be normal, but sudden isolation deserves attention.","zh":"偶然獨坐可能正常，但突然孤立自己值得留意。"},{"en":"This phrase gives a visible sign of emotional distance.","zh":"這個片語提供情感距離的可見跡象。"}],"source":"2012 Q9.pdf","sourcePage":5},{"front":"staring at","meaning":"凝望着","examples":[{"en":"Ethan was staring at a blank test paper.","zh":"Ethan 凝望着一張空白測驗卷。"},{"en":"Staring at means looking at something for a long time, often without reacting.","zh":"staring at 意思是長時間看着某物，通常沒有反應。"},{"en":"A worried student may stare at a question without knowing how to begin.","zh":"憂慮的學生可能凝望着題目，不知道如何開始。"},{"en":"Ethan staring at the paper suggests he felt stuck or overwhelmed.","zh":"Ethan 凝望着試卷，暗示他感到卡住或被壓垮。"},{"en":"This phrase shows silence and helplessness through action.","zh":"這個片語透過動作顯示沉默和無助。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"blank test paper","meaning":"空白測驗卷","examples":[{"en":"Ethan sat staring at a blank test paper.","zh":"Ethan 坐着凝望一張空白測驗卷。"},{"en":"A blank test paper is a test sheet with no answers written on it.","zh":"blank test paper 是沒有寫上答案的測驗紙。"},{"en":"A blank test paper can show that a student felt unable to start.","zh":"空白測驗卷可以顯示學生感到無法開始。"},{"en":"For Ethan, the blank paper became a sign of mental exhaustion.","zh":"對 Ethan 來說，空白測驗卷成為精神疲憊的象徵。"},{"en":"This phrase turns an ordinary school object into a symbol of struggle.","zh":"這個片語把普通校園物件變成掙扎的象徵。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"it dawned on me that","meaning":"我才明白","examples":[{"en":"It dawned on me that Ethan was trying to survive.","zh":"我才明白 Ethan 只是在努力撐過去。"},{"en":"It dawned on me that means I suddenly began to understand something.","zh":"it dawned on me that 意思是我突然開始明白某事。"},{"en":"It dawned on me that my friend was not lazy but exhausted.","zh":"我才明白我的朋友不是懶惰，而是身心俱疲。"},{"en":"This phrase describes a moment of realisation.","zh":"這個片語描述恍然大悟的一刻。"},{"en":"It helps the writer show how his understanding changed.","zh":"它幫助作者顯示自己的理解如何改變。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"avoid life","meaning":"逃避生活","examples":[{"en":"Ethan was not trying to avoid life.","zh":"Ethan 並不是在逃避生活。"},{"en":"To avoid life means to stay away from ordinary responsibilities, relationships, or experiences.","zh":"avoid life 意思是避開日常責任、人際關係或經歷。"},{"en":"People may wrongly think a depressed student is trying to avoid life.","zh":"人們可能錯誤地以為抑鬱學生是在逃避生活。"},{"en":"Sometimes the person is not avoiding life but struggling to cope with it.","zh":"有時那個人不是逃避生活，而是努力應付生活。"},{"en":"This phrase corrects a harsh misunderstanding.","zh":"這個片語糾正嚴厲誤解。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"survive it","meaning":"撐過去","examples":[{"en":"He was trying to survive it.","zh":"他只是努力撐過去。"},{"en":"To survive it means to get through a very difficult experience.","zh":"survive it 意思是熬過非常困難的經歷。"},{"en":"A student in deep distress may focus only on surviving the day.","zh":"深受困擾的學生可能只專注於撐過當天。"},{"en":"This phrase shows that Ethan’s struggle was serious and exhausting.","zh":"這個片語顯示 Ethan 的掙扎嚴重而耗力。"},{"en":"It asks readers to respond with compassion rather than blame.","zh":"它要求讀者以同理心而不是責備回應。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"what helped him","meaning":"幫助他的事","examples":[{"en":"What helped him was many small acts of courage.","zh":"幫助他的事是許多細小而勇敢的行動。"},{"en":"What helped him means the things that gave support and made recovery possible.","zh":"what helped him 指給予支援並令康復成為可能的事情。"},{"en":"What helped him was not pressure, but patient company and adult help.","zh":"幫助他的不是壓力，而是耐心陪伴和成年人協助。"},{"en":"This phrase focuses on practical support rather than blame.","zh":"這個片語聚焦於實際支援，而不是責備。"},{"en":"It prepares readers to learn what kind of help matters.","zh":"它讓讀者準備了解哪種幫助重要。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"not one dramatic rescue, but…","meaning":"不是一次戲劇性的拯救，而是……","examples":[{"en":"What helped him was not one dramatic rescue, but many small acts of courage.","zh":"幫助他的不是一次戲劇性的拯救，而是許多細小而勇敢的行動。"},{"en":"This structure contrasts one big heroic action with many smaller helpful actions.","zh":"這個句式把一次巨大英雄式行動與許多較小的幫助作對比。"},{"en":"Recovery is often not one dramatic rescue, but steady support over time.","zh":"康復往往不是一次戲劇性的拯救，而是長時間穩定支援。"},{"en":"The phrase shows that ordinary classmates can still make a difference.","zh":"這個片語顯示普通同學仍可以帶來改變。"},{"en":"It makes help feel realistic and possible.","zh":"它令幫助感覺現實而可行。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"dramatic rescue","meaning":"戲劇性的拯救","examples":[{"en":"Ethan’s recovery did not come from one dramatic rescue.","zh":"Ethan 的康復不是來自一次戲劇性的拯救。"},{"en":"A dramatic rescue is a sudden, heroic action that saves someone quickly.","zh":"dramatic rescue 指突然、英雄式地迅速拯救某人的行動。"},{"en":"In real life, mental health recovery rarely comes from one dramatic rescue.","zh":"在現實中，精神健康康復很少來自一次戲劇性的拯救。"},{"en":"Support usually comes through repeated listening, care, and professional help.","zh":"支援通常來自反覆聆聽、關心和專業幫助。"},{"en":"This phrase helps avoid an unrealistic view of recovery.","zh":"這個片語幫助避免對康復有不切實際的看法。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"small acts of courage","meaning":"細小而勇敢的行動","examples":[{"en":"Many small acts of courage helped Ethan.","zh":"許多細小而勇敢的行動幫助了 Ethan。"},{"en":"Small acts of courage are quiet brave actions that may seem simple but matter.","zh":"small acts of courage 是安靜而勇敢的行動，看似簡單卻很重要。"},{"en":"Asking “Are you okay?” can be a small act of courage.","zh":"問一句「你還好嗎？」可以是細小而勇敢的行動。"},{"en":"Telling a trusted adult when someone may be unsafe is also a small act of courage.","zh":"當某人可能不安全時告訴可信任成年人，也是一個細小而勇敢的行動。"},{"en":"This phrase shows that courage can be gentle, not loud.","zh":"這個片語顯示勇氣可以是溫和的，而不是大聲的。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"instead of saying","meaning":"而不是說","examples":[{"en":"Instead of saying “Cheer up,” I asked whether I could sit with him.","zh":"我沒有說「振作起來」，而是問我可否坐在他身旁。"},{"en":"Instead of saying means choosing not to use certain words and doing something else.","zh":"instead of saying 意思是選擇不說某些話，而做另一件事。"},{"en":"Instead of saying “Don’t worry,” a friend can ask, “Do you want company?”","zh":"朋友可以不說「不要擔心」，而問「你想有人陪嗎？」"},{"en":"This phrase contrasts an unhelpful response with a gentler one.","zh":"這個片語把沒有幫助的回應與更溫和的回應作對比。"},{"en":"It teaches that words should be chosen carefully.","zh":"它教人說話應仔細選擇。"}],"source":"2012 Q9.pdf","sourcePage":6},{"front":"cheer up","meaning":"振作起來","examples":[{"en":"The writer avoided simply saying “Cheer up.”","zh":"作者避免只是說「振作起來」。"},{"en":"Cheer up means try to become happier, but it can sound too simple for deep pain.","zh":"cheer up 意思是嘗試變得開心，但對深層痛苦而言可能聽起來過分簡單。"},{"en":"Saying “Cheer up” may make a depressed person feel misunderstood.","zh":"對抑鬱的人說「振作起來」可能令對方覺得不被理解。"},{"en":"A kinder response may be to listen quietly and ask what they need.","zh":"更友善的回應可能是安靜聆聽，並詢問對方需要甚麼。"},{"en":"This phrase shows why quick slogans may not help mental illness.","zh":"這個片語顯示快速口號為何未必能幫助精神疾病。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"would it help if","meaning":"如果……會有幫助嗎","examples":[{"en":"Would it help if I just sat here with you?","zh":"如果我只是坐在這裏陪你，會有幫助嗎？"},{"en":"Would it help if is a gentle way to offer support without forcing it.","zh":"would it help if 是溫和地提供支援而不強迫對方的說法。"},{"en":"A friend may ask, “Would it help if I walked with you to the counsellor?”","zh":"朋友可能問：「如果我陪你去見輔導員，會有幫助嗎？」"},{"en":"This phrase lets the struggling person keep some control.","zh":"這個片語讓正在掙扎的人保留一點控制感。"},{"en":"It is useful because it offers help as a question, not a command.","zh":"它有用，因為它以問題而不是命令來提供幫助。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"sit here with you","meaning":"坐在這裏陪你","examples":[{"en":"The writer offered to sit there with Ethan.","zh":"作者提出坐在那裏陪 Ethan。"},{"en":"To sit here with you means to stay beside someone quietly and keep them company.","zh":"sit here with you 意思是安靜地留在某人身旁陪伴他。"},{"en":"Sometimes sitting with a friend helps more than giving advice.","zh":"有時坐在朋友身旁比給建議更有幫助。"},{"en":"This action shows presence, patience, and care.","zh":"這個行動顯示陪伴、耐性和關心。"},{"en":"It reminds the person that they do not have to be alone.","zh":"它提醒對方不必獨自一人。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"for what felt like forever","meaning":"彷彿過了很久","examples":[{"en":"For what felt like forever, Ethan said nothing.","zh":"彷彿過了很久，Ethan 一句話也沒有說。"},{"en":"For what felt like forever means for a time that seemed extremely long.","zh":"for what felt like forever 意思是一段感覺非常漫長的時間。"},{"en":"A few quiet minutes can feel like forever when someone is waiting for a friend to speak.","zh":"等待朋友開口時，幾分鐘的沉默也可能彷彿過了很久。"},{"en":"This phrase helps readers feel the weight of silence.","zh":"這個片語幫助讀者感受沉默的重量。"},{"en":"It shows that patience is needed when someone is struggling.","zh":"它顯示面對正在掙扎的人需要耐性。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"eventually","meaning":"最後；終於","examples":[{"en":"Eventually, Ethan admitted that he had not slept properly.","zh":"最後，Ethan 承認他一直沒有睡好。"},{"en":"Eventually means after some time, especially after waiting or difficulty.","zh":"eventually 意思是在一段時間後，尤其在等待或困難之後。"},{"en":"Eventually, the quiet student told the teacher what was wrong.","zh":"最後，那位沉默學生告訴老師出了甚麼事。"},{"en":"This word shows that trust may take time before someone speaks.","zh":"這個字顯示信任可能需要時間，人才會開口。"},{"en":"It helps describe a slow movement from silence to honesty.","zh":"它幫助描述由沉默慢慢走向坦誠的過程。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"admitted that","meaning":"承認","examples":[{"en":"Ethan admitted that he had not slept properly for weeks.","zh":"Ethan 承認他好幾星期沒有睡好。"},{"en":"Admitted that means honestly said something difficult or private was true.","zh":"admitted that 意思是坦白說出某件困難或私人的事情是真的。"},{"en":"A student may admit that she feels overwhelmed by exams.","zh":"學生可能承認自己被考試壓力壓垮。"},{"en":"Admitting pain can be hard because people fear judgement.","zh":"承認痛苦可以很困難，因為人們害怕被評判。"},{"en":"This phrase shows the beginning of honest communication.","zh":"這個片語顯示坦誠溝通的開始。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"slept properly","meaning":"睡得好","examples":[{"en":"Ethan had not slept properly for weeks.","zh":"Ethan 好幾星期沒有睡好。"},{"en":"Slept properly means had enough restful and healthy sleep.","zh":"slept properly 意思是有足夠、能休息身心的健康睡眠。"},{"en":"A student who has not slept properly may find lessons hard to follow.","zh":"沒有睡好的學生可能難以跟上課堂。"},{"en":"Poor sleep can make emotional pain feel heavier.","zh":"睡眠不足會令情緒痛苦感覺更沉重。"},{"en":"This phrase shows one clear sign that Ethan was not well.","zh":"這個片語顯示 Ethan 狀態不好的清晰跡象。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"for weeks","meaning":"好幾星期","examples":[{"en":"He had not slept properly for weeks.","zh":"他好幾星期沒有睡好。"},{"en":"For weeks means for several weeks, not just one or two days.","zh":"for weeks 意思是持續數星期，而不是一兩天。"},{"en":"If sadness or tiredness lasts for weeks, adults should take it seriously.","zh":"如果悲傷或疲倦持續好幾星期，成年人應認真看待。"},{"en":"A problem lasting for weeks may need more support than a casual chat.","zh":"持續好幾星期的問題可能需要比閒聊更多的支援。"},{"en":"This phrase shows the struggle had been continuing for some time.","zh":"這個片語顯示掙扎已持續了一段時間。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"begun to believe","meaning":"開始相信","examples":[{"en":"He had begun to believe that everyone would be better off without him.","zh":"他開始相信沒有他，大家會過得更好。"},{"en":"Begun to believe means started to think something was true.","zh":"begun to believe 意思是開始認為某件事是真的。"},{"en":"A distressed student may begin to believe unfair and harmful thoughts about himself.","zh":"深受困擾的學生可能開始相信關於自己的不公平和有害想法。"},{"en":"When someone begins to believe people are better without them, adult help is urgent.","zh":"當某人開始相信別人沒有自己會更好時，應立即尋求成年人幫助。"},{"en":"This phrase signals serious emotional danger and should never be ignored.","zh":"這個片語發出嚴重情緒危險訊號，絕不應被忽視。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"be better off without","meaning":"沒有……會過得更好","examples":[{"en":"He believed that everyone would be better off without him.","zh":"他相信沒有他，大家會過得更好。"},{"en":"Be better off without someone means life would be better if that person were absent.","zh":"be better off without someone 意思是如果某人不存在，生活會更好。"},{"en":"This thought is a serious warning sign when someone says it about themselves.","zh":"當某人這樣形容自己時，這個想法是嚴重警號。"},{"en":"Friends should not handle such words alone; they should tell a trusted adult.","zh":"朋友不應獨自處理這些說話；應告訴可信任成年人。"},{"en":"This phrase shows deep hopelessness and needs careful support.","zh":"這個片語顯示深層絕望，需要謹慎支援。"}],"source":"2012 Q9.pdf","sourcePage":7},{"front":"frightened me","meaning":"令我害怕","examples":[{"en":"What Ethan said frightened the writer.","zh":"Ethan 所說的話令作者害怕。"},{"en":"Frightened me means made me feel scared or seriously worried.","zh":"frightened me 意思是令我感到害怕或非常擔心。"},{"en":"A friend’s hopeless words may frighten you because they suggest danger.","zh":"朋友絕望的說話可能令你害怕，因為它們暗示危險。"},{"en":"Feeling frightened can be a sign that adult help is needed immediately.","zh":"感到害怕可能表示需要立即尋求成年人幫助。"},{"en":"This phrase shows the writer understood the seriousness of Ethan’s words.","zh":"這個片語顯示作者明白 Ethan 說話的嚴重性。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"knew better than to","meaning":"明知不應該","examples":[{"en":"The writer knew better than to leave Ethan hanging.","zh":"作者明知不應該讓 Ethan 孤立無援。"},{"en":"Knew better than to means understood that doing something would be wrong or unsafe.","zh":"knew better than to 意思是明白做某事是錯誤或不安全的。"},{"en":"A responsible friend knows better than to keep dangerous secrets alone.","zh":"負責任的朋友明知不應該獨自保守危險秘密。"},{"en":"This phrase shows the writer made a careful and mature decision.","zh":"這個片語顯示作者作出謹慎而成熟的決定。"},{"en":"It teaches that friendship sometimes means getting help.","zh":"它教人友誼有時意味著尋求幫助。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"leave him hanging","meaning":"讓他孤立無援；不理會他","examples":[{"en":"The writer knew better than to leave Ethan hanging.","zh":"作者明知不應該讓 Ethan 孤立無援。"},{"en":"To leave him hanging means to leave him unsupported or uncertain when he needs help.","zh":"leave him hanging 意思是在他需要幫助時讓他沒有支援或沒有方向。"},{"en":"A friend should not leave someone hanging after hearing worrying words.","zh":"聽到令人擔心的說話後，朋友不應讓對方孤立無援。"},{"en":"Leaving a struggling person hanging can make them feel more alone.","zh":"讓正在掙扎的人孤立無援，可能令他更覺孤單。"},{"en":"This phrase shows why follow-up matters.","zh":"這個片語顯示跟進為何重要。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"with his knowledge","meaning":"在他知情下","examples":[{"en":"With Ethan’s knowledge, the writer spoke to the class teacher.","zh":"在 Ethan 知情下，作者與班主任交談。"},{"en":"With his knowledge means he knew about the action and was not secretly excluded.","zh":"with his knowledge 意思是他知道該行動，而不是被秘密排除在外。"},{"en":"With the student’s knowledge, a friend may ask a teacher for help.","zh":"在學生知情下，朋友可能向老師求助。"},{"en":"This phrase shows respect for the person’s dignity where possible.","zh":"這個片語顯示在可行情況下尊重當事人的尊嚴。"},{"en":"It also shows the writer did not handle the danger alone.","zh":"它也顯示作者沒有獨自處理危險。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"safety mattered more than embarrassment","meaning":"安全比尷尬更重要","examples":[{"en":"Safety mattered more than embarrassment.","zh":"安全比尷尬更重要。"},{"en":"Safety mattered more than embarrassment means protecting someone is more important than feeling awkward.","zh":"safety mattered more than embarrassment 意思是保護某人比感到尷尬更重要。"},{"en":"A student may feel embarrassed asking for help, but safety must come first.","zh":"學生求助時可能感到尷尬，但安全必須放在第一位。"},{"en":"If someone may be in danger, telling a trusted adult is the right step.","zh":"如果某人可能有危險，告訴可信任成年人是正確步驟。"},{"en":"This phrase gives a clear rule for serious mental health situations.","zh":"這個片語為嚴重精神健康情況提供清晰原則。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"class teacher","meaning":"班主任","examples":[{"en":"The writer spoke to the class teacher.","zh":"作者與班主任交談。"},{"en":"A class teacher is the teacher responsible for a particular class and its students.","zh":"class teacher 是負責某一班和該班學生的老師。"},{"en":"Students may speak to a class teacher when a classmate seems unsafe or deeply distressed.","zh":"當同學似乎不安全或深受困擾時，學生可以告訴班主任。"},{"en":"A class teacher can connect students with parents, counsellors, or social workers.","zh":"班主任可以把學生與家長、輔導員或社工連繫起來。"},{"en":"This phrase shows which trusted adult became involved.","zh":"這個片語顯示哪位可信任成年人介入。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"brought in","meaning":"請來；引入","examples":[{"en":"The class teacher brought in the school social worker.","zh":"班主任請來學校社工。"},{"en":"Brought in means asked someone else to join and help with the situation.","zh":"brought in 意思是請另一個人加入並協助處理情況。"},{"en":"A teacher may bring in a counsellor when a student needs more support.","zh":"當學生需要更多支援時，老師可能請來輔導員。"},{"en":"Bringing in the social worker shows the problem needed professional help.","zh":"請來社工顯示問題需要專業幫助。"},{"en":"This phrase describes widening support instead of handling everything alone.","zh":"這個片語描述擴大支援，而不是獨自處理一切。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"school social worker","meaning":"學校社工","examples":[{"en":"The school social worker helped Ethan.","zh":"學校社工幫助了 Ethan。"},{"en":"A school social worker is a trained professional who supports students’ emotional and family needs.","zh":"school social worker 是受過訓練、支援學生情緒和家庭需要的專業人士。"},{"en":"A school social worker may help students talk about stress, safety, or home problems.","zh":"學校社工可能幫助學生談論壓力、安全或家庭問題。"},{"en":"Social workers can connect students with counselling or other services.","zh":"社工可以把學生連繫到輔導或其他服務。"},{"en":"This phrase shows that professional support became part of Ethan’s recovery.","zh":"這個片語顯示專業支援成為 Ethan 康復的一部分。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"helped someone talk to","meaning":"幫助某人與……交談","examples":[{"en":"The school social worker helped Ethan talk to his parents.","zh":"學校社工幫助 Ethan 與父母交談。"},{"en":"To help someone talk to others means to support them in saying difficult things clearly and safely.","zh":"help someone talk to others 意思是支援某人安全而清楚地說出困難事情。"},{"en":"A counsellor may help a student talk to parents about stress.","zh":"輔導員可能幫助學生與父母談論壓力。"},{"en":"Some students need help because they fear worrying or disappointing their family.","zh":"有些學生需要幫助，因為他們害怕令家人擔心或失望。"},{"en":"This phrase shows how support can make hard conversations possible.","zh":"這個片語顯示支援如何令困難對話成為可能。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"thereafter","meaning":"其後","examples":[{"en":"Thereafter, recovery began to take shape.","zh":"其後，康復開始成形。"},{"en":"Thereafter means after that point or from then on.","zh":"thereafter 意思是在那之後或從那時起。"},{"en":"The student met the counsellor; thereafter, small changes slowly appeared.","zh":"學生見了輔導員；其後，細小改變慢慢出現。"},{"en":"This word helps show the sequence of events.","zh":"這個字幫助顯示事情次序。"},{"en":"It marks the beginning of a new stage in Ethan’s story.","zh":"它標誌 Ethan 故事中新階段的開始。"}],"source":"2012 Q9.pdf","sourcePage":8},{"front":"began to take shape","meaning":"開始成形","examples":[{"en":"Recovery began to take shape.","zh":"康復開始成形。"},{"en":"Began to take shape means started to become real, clear, or organised.","zh":"began to take shape 意思是開始變得真實、清晰或有組織。"},{"en":"A study plan begins to take shape when the student sets small daily goals.","zh":"當學生設定每日小目標時，溫習計劃便開始成形。"},{"en":"Ethan’s recovery took shape through counselling, rest, and routine.","zh":"Ethan 的康復透過輔導、休息和日常規律開始成形。"},{"en":"This phrase shows gradual progress, not instant success.","zh":"這個片語顯示逐步進展，而不是即時成功。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"counsellor","meaning":"輔導員","examples":[{"en":"Ethan met the counsellor regularly.","zh":"Ethan 定期見輔導員。"},{"en":"A counsellor is a trained person who helps people talk through emotional or personal problems.","zh":"counsellor 是受過訓練、幫助人談論情緒或個人問題的人。"},{"en":"A school counsellor may help students manage stress, sadness, or conflict.","zh":"學校輔導員可能幫助學生處理壓力、悲傷或衝突。"},{"en":"Meeting a counsellor can give students a safe space to speak.","zh":"見輔導員可以給學生一個安全發聲空間。"},{"en":"This phrase points to professional emotional support.","zh":"這個片語指出專業情緒支援。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"regularly","meaning":"定期地","examples":[{"en":"Ethan met the counsellor regularly.","zh":"Ethan 定期地見輔導員。"},{"en":"Regularly means again and again at planned or usual times.","zh":"regularly 意思是在計劃好或慣常時間反覆進行。"},{"en":"A student may meet a counsellor regularly every week.","zh":"學生可能每星期定期見輔導員。"},{"en":"Regular support can help recovery become steadier.","zh":"定期支援可以令康復更穩定。"},{"en":"This word shows that help was continuous, not a one-time event.","zh":"這個字顯示幫助是持續的，而不是一次性的。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"reduced his workload","meaning":"減輕工作量","examples":[{"en":"Ethan reduced his workload for a while.","zh":"Ethan 暫時減輕了工作量。"},{"en":"Reduced his workload means made the amount of work smaller or more manageable.","zh":"reduced his workload 意思是把工作量減少或變得較可應付。"},{"en":"A student may reduce workload by taking fewer activities during recovery.","zh":"學生在康復期間可能透過減少活動來減輕工作量。"},{"en":"Reducing workload can create space for sleep, meals, and counselling.","zh":"減輕工作量可以為睡眠、用餐和輔導留出空間。"},{"en":"This phrase shows that recovery may require practical adjustments.","zh":"這個片語顯示康復可能需要實際調整。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"for a while","meaning":"一段時間","examples":[{"en":"Ethan reduced his workload for a while.","zh":"Ethan 一段時間內減輕了工作量。"},{"en":"For a while means for a limited period of time.","zh":"for a while 意思是在有限的一段時間內。"},{"en":"A student may rest from extra activities for a while after burnout.","zh":"學生在身心耗盡後，可能一段時間內暫停課外活動。"},{"en":"Doing less for a while can help someone rebuild strength.","zh":"一段時間內少做一些事，可以幫助人重新建立力量。"},{"en":"This phrase shows the change was temporary and supportive.","zh":"這個片語顯示改變是暫時而具支援性的。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"rebuilt a routine around","meaning":"圍繞……重建日常規律","examples":[{"en":"Ethan rebuilt a routine around sleep, meals and exercise.","zh":"Ethan 圍繞睡眠、用餐和運動重建日常規律。"},{"en":"To rebuild a routine around something means to create daily habits based on important needs.","zh":"rebuild a routine around 某事，意思是根據重要需要建立日常習慣。"},{"en":"A student may rebuild a routine around regular sleep and short study sessions.","zh":"學生可能圍繞規律睡眠和短時間溫習重建日常規律。"},{"en":"Rebuilding routine helps life feel less chaotic during recovery.","zh":"重建規律幫助人在康復期間感到生活較不混亂。"},{"en":"This phrase shows how small daily structure supports mental health.","zh":"這個片語顯示細小日常結構如何支援精神健康。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"manageable revision","meaning":"可應付的溫習","examples":[{"en":"Ethan rebuilt a routine around manageable revision.","zh":"Ethan 圍繞可應付的溫習重建日常規律。"},{"en":"Manageable revision means study that is small enough to handle without being overwhelming.","zh":"manageable revision 指小到能處理、不會令人被壓垮的溫習。"},{"en":"Ten focused minutes may be manageable revision for a tired student.","zh":"對疲倦學生來說，十分鐘專注溫習可能是可應付的溫習。"},{"en":"Manageable revision helps students return to study gradually.","zh":"可應付的溫習幫助學生逐步回到學習。"},{"en":"This phrase shows that recovery and learning can move forward together.","zh":"這個片語顯示康復和學習可以一起前進。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"progress came in fits and starts","meaning":"進展斷斷續續","examples":[{"en":"Ethan’s progress came in fits and starts.","zh":"Ethan 的進展斷斷續續。"},{"en":"Progress came in fits and starts means improvement happened unevenly, with pauses and setbacks.","zh":"progress came in fits and starts 意思是進步不平均，有停頓和倒退。"},{"en":"Recovery may come in fits and starts rather than in a straight line.","zh":"康復可能斷斷續續，而不是直線前進。"},{"en":"A student may have a good week and then a difficult day again.","zh":"學生可能有一星期很好，之後又有困難的一天。"},{"en":"This phrase makes recovery sound realistic.","zh":"這個片語令康復聽起來更真實。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"two steps forward, one step back","meaning":"進兩步退一步","examples":[{"en":"Recovery felt like two steps forward, one step back.","zh":"康復感覺像進兩步退一步。"},{"en":"Two steps forward, one step back means progress happens but includes setbacks.","zh":"two steps forward, one step back 意思是有進展，但也有倒退。"},{"en":"A student may sleep better for two days, then struggle again.","zh":"學生可能兩天睡得較好，之後又再次掙扎。"},{"en":"This phrase encourages patience because setbacks do not erase progress.","zh":"這個片語鼓勵耐性，因為倒退不會抹去進步。"},{"en":"It helps readers understand that recovery is not perfectly smooth.","zh":"它幫助讀者理解康復不是完全順利的。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"little by little","meaning":"一點一點地","examples":[{"en":"Little by little, Ethan came a long way.","zh":"一點一點地，Ethan 取得了很大進展。"},{"en":"Little by little means gradually, through small steps over time.","zh":"little by little 意思是透過一段時間的小步驟逐漸地。"},{"en":"A student can rebuild confidence little by little after receiving support.","zh":"學生得到支援後，可以一點一點地重建信心。"},{"en":"Small daily improvements can become meaningful over months.","zh":"每天的小改善可在數月後變得有意義。"},{"en":"This phrase gives hope without pretending recovery is instant.","zh":"這個片語帶來希望，但沒有假裝康復是即時的。"}],"source":"2012 Q9.pdf","sourcePage":9},{"front":"came a long way","meaning":"取得很大進展","examples":[{"en":"Ethan came a long way during recovery.","zh":"Ethan 在康復期間取得很大進展。"},{"en":"Came a long way means made great progress from a difficult starting point.","zh":"came a long way 意思是從困難起點取得很大進步。"},{"en":"A student who once could not enter class may come a long way by attending regularly again.","zh":"曾經無法進課室的學生，若能再次定期上課，就是取得很大進展。"},{"en":"Coming a long way does not mean every problem has disappeared.","zh":"取得很大進展不代表所有問題都已消失。"},{"en":"This phrase recognises progress with kindness and realism.","zh":"這個片語以溫和而現實的方式肯定進步。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"for the first time in forever","meaning":"久違地","examples":[{"en":"For the first time in forever, Ethan laughed at a joke.","zh":"Ethan 久違地因一個笑話而笑了。"},{"en":"For the first time in forever means after what felt like a very long time.","zh":"for the first time in forever 意思是在感覺很漫長的一段時間後第一次。"},{"en":"A friend’s smile after weeks of silence can feel like the first time in forever.","zh":"朋友沉默數星期後的一個微笑，可能感覺像久違了。"},{"en":"This phrase shows how meaningful a small moment can become.","zh":"這個片語顯示一個小時刻可以變得很有意義。"},{"en":"It marks a gentle sign of returning life.","zh":"它標誌生命力慢慢回來的溫柔跡象。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time Speech Day arrived, Ethan was still standing.","zh":"到畢業頒獎禮來臨的時候，Ethan 仍然撐着。"},{"en":"By the time means when a later event happened.","zh":"by the time 意思是當之後某事件發生時。"},{"en":"By the time exams arrived, the student had rebuilt a small study routine.","zh":"到考試來臨的時候，學生已重建一個小小溫習規律。"},{"en":"This phrase connects a period of recovery with a later moment.","zh":"這個片語把康復過程與之後的一刻連接起來。"},{"en":"It helps show how time passed in the story.","zh":"它幫助顯示故事中的時間流逝。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"Speech Day","meaning":"畢業頒獎禮；學校頒獎日","examples":[{"en":"By the time Speech Day arrived, Ethan was still standing.","zh":"到畢業頒獎禮來臨的時候，Ethan 仍然撐着。"},{"en":"Speech Day is a school ceremony where students receive prizes or mark the end of a school year.","zh":"Speech Day 是學生領獎或標誌學年結束的學校典禮。"},{"en":"Speech Day can feel emotional because it celebrates effort and growth.","zh":"畢業頒獎禮可以很有感情，因為它肯定努力和成長。"},{"en":"For Ethan, reaching Speech Day was itself meaningful.","zh":"對 Ethan 來說，能走到畢業頒獎禮本身已有意義。"},{"en":"This phrase places recovery beside an important school milestone.","zh":"這個片語把康復與重要校園里程碑放在一起。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"still standing","meaning":"仍然撐着；仍然站着","examples":[{"en":"Ethan was quiet, but he was still standing.","zh":"Ethan 很安靜，但他仍然撐着。"},{"en":"Still standing means still continuing, surviving, or not giving up after difficulty.","zh":"still standing 意思是在困難後仍然繼續、撐過來或沒有放棄。"},{"en":"A student may be tired but still standing after a hard year.","zh":"學生經歷艱難一年後可能很疲倦，但仍然撐着。"},{"en":"This phrase recognises survival as an achievement.","zh":"這個片語承認撐下去本身就是成就。"},{"en":"It is powerful because recovery may begin simply with staying alive and present.","zh":"它很有力量，因為康復可能只是從仍然活着和仍然在場開始。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"fighting depression","meaning":"對抗抑鬱症","examples":[{"en":"There are things every student should know about fighting depression.","zh":"每位學生都應知道一些關於對抗抑鬱症的事情。"},{"en":"Fighting depression means dealing with depression through support, treatment, patience, and daily care.","zh":"fighting depression 意思是透過支援、治療、耐性和日常照顧來面對抑鬱症。"},{"en":"Fighting depression does not mean simply forcing yourself to be happy.","zh":"對抗抑鬱症不等於單純強迫自己開心。"},{"en":"Friends can help, but doctors, counsellors, and trusted adults may also be needed.","zh":"朋友可以幫忙，但醫生、輔導員和可信任成年人也可能需要介入。"},{"en":"This phrase presents recovery as serious work, not weakness.","zh":"這個片語把康復呈現為嚴肅工作，而不是軟弱。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"notice changes","meaning":"留意變化","examples":[{"en":"Students should notice changes in their friends.","zh":"學生應留意朋友身上的變化。"},{"en":"To notice changes means to pay attention when someone’s behaviour becomes different.","zh":"notice changes 意思是在某人行為變得不同時加以留心。"},{"en":"A friend may notice changes in sleep, appetite, mood, or social habits.","zh":"朋友可能留意到睡眠、食慾、情緒或社交習慣的變化。"},{"en":"Noticing changes early can help a student receive support sooner.","zh":"及早留意變化可以幫助學生更快得到支援。"},{"en":"This phrase shows the first step classmates can take.","zh":"這個片語顯示同學可以採取的第一步。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"few, if any","meaning":"即使有也很少","examples":[{"en":"Few, if any, depressed students will announce their suffering clearly.","zh":"即使有，也很少患抑鬱症的學生會清楚說出自己的痛苦。"},{"en":"Few, if any means almost none, or possibly none at all.","zh":"few, if any 意思是幾乎沒有，甚至可能完全沒有。"},{"en":"Few, if any, students will say directly, “I need help,” when they feel ashamed.","zh":"當學生感到羞愧時，即使有，也很少會直接說「我需要幫助」。"},{"en":"This phrase shows why friends must notice indirect signs.","zh":"這個片語顯示朋友為何必須留意間接跡象。"},{"en":"It warns readers not to wait for a perfect explanation.","zh":"它提醒讀者不要等待完美清楚的解釋。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"depressed students","meaning":"患抑鬱症的學生","examples":[{"en":"Depressed students may not describe their suffering clearly.","zh":"患抑鬱症的學生未必能清楚描述自己的痛苦。"},{"en":"Depressed students are students experiencing depression or serious depressive symptoms.","zh":"depressed students 指正在經歷抑鬱症或嚴重抑鬱症狀的學生。"},{"en":"Depressed students may withdraw, sleep badly, or lose interest in activities.","zh":"患抑鬱症的學生可能退縮、睡不好或失去對活動的興趣。"},{"en":"They need support, not blame or gossip.","zh":"他們需要支援，而不是責備或八卦。"},{"en":"This phrase identifies the students the article wants to protect.","zh":"這個片語指出文章想保護的學生。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"announce their suffering","meaning":"說出自己的痛苦","examples":[{"en":"Few students will announce their suffering in perfect sentences.","zh":"很少學生會用完整清楚的句子說出自己的痛苦。"},{"en":"To announce their suffering means to clearly tell others that they are in pain.","zh":"announce their suffering 意思是清楚告訴別人自己正在痛苦中。"},{"en":"Many students hide suffering instead of announcing it openly.","zh":"許多學生會隱藏痛苦，而不是公開說出來。"},{"en":"A sudden change in behaviour may announce suffering more clearly than words.","zh":"突然的行為改變可能比說話更清楚地表達痛苦。"},{"en":"This phrase shows why listening involves more than hearing direct statements.","zh":"這個片語顯示聆聽不只是聽直接陳述。"}],"source":"2012 Q9.pdf","sourcePage":10},{"front":"in perfect sentences","meaning":"用完整清楚的句子","examples":[{"en":"Suffering is rarely announced in perfect sentences.","zh":"痛苦很少會用完整清楚的句子說出來。"},{"en":"In perfect sentences means in clear, complete, and well-organised words.","zh":"in perfect sentences 意思是用清晰、完整和有條理的說話。"},{"en":"A struggling student may say only, “I’m tired,” not explain everything in perfect sentences.","zh":"正在掙扎的學生可能只說「我很累」，而不是用完整清楚的句子解釋一切。"},{"en":"Friends should not wait for perfect sentences before taking concern seriously.","zh":"朋友不應等到對方用完美句子說明才認真關注。"},{"en":"This phrase teaches patience with unclear communication.","zh":"這個片語教人要耐心面對不清晰的溝通。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"look out for","meaning":"留意","examples":[{"en":"Students should look out for sudden isolation and constant tiredness.","zh":"學生應留意突然孤立自己和長期疲倦。"},{"en":"To look out for something means to watch carefully for possible signs.","zh":"look out for 意思是仔細觀察可能的跡象。"},{"en":"Friends should look out for changes in mood, sleep, and social behaviour.","zh":"朋友應留意情緒、睡眠和社交行為的變化。"},{"en":"Looking out for signs is not spying; it is caring responsibly.","zh":"留意跡象不是監視，而是負責任地關心。"},{"en":"This phrase encourages careful attention to others.","zh":"這個片語鼓勵細心關注他人。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"sudden isolation","meaning":"突然孤立自己","examples":[{"en":"Sudden isolation can be a warning sign.","zh":"突然孤立自己可以是一個警號。"},{"en":"Sudden isolation means unexpectedly pulling away from friends or group activities.","zh":"sudden isolation 意思是突然遠離朋友或小組活動。"},{"en":"A student who stops eating with classmates may be showing sudden isolation.","zh":"不再和同學一起吃飯的學生，可能正在突然孤立自己。"},{"en":"Sudden isolation may suggest sadness, anxiety, or depression.","zh":"突然孤立自己可能暗示悲傷、焦慮或抑鬱。"},{"en":"This phrase shows one change classmates should not ignore.","zh":"這個片語顯示同學不應忽視的一種變化。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"constant tiredness","meaning":"長期疲倦","examples":[{"en":"Constant tiredness may be a sign of depression.","zh":"長期疲倦可能是抑鬱症的跡象。"},{"en":"Constant tiredness means feeling tired all the time or very often.","zh":"constant tiredness 意思是一直或經常感到疲倦。"},{"en":"A student with constant tiredness may sleep in class or stop joining activities.","zh":"長期疲倦的學生可能在課堂睡覺或停止參加活動。"},{"en":"Constant tiredness should be taken seriously if it lasts for weeks.","zh":"如果長期疲倦持續好幾星期，應認真看待。"},{"en":"This phrase points to a possible warning sign, not simple laziness.","zh":"這個片語指出可能的警號，而不是單純懶惰。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"unusual anger","meaning":"異常憤怒","examples":[{"en":"Unusual anger can signal emotional distress.","zh":"異常憤怒可以是情緒困擾的訊號。"},{"en":"Unusual anger means anger that is stronger, more frequent, or less typical than before.","zh":"unusual anger 指比以往更強烈、更頻繁或更不尋常的憤怒。"},{"en":"A normally gentle student who suddenly snaps at friends may be in distress.","zh":"平時溫和的學生突然對朋友發脾氣，可能正受困擾。"},{"en":"Anger can sometimes cover fear, sadness, or exhaustion.","zh":"憤怒有時可以掩蓋恐懼、悲傷或身心俱疲。"},{"en":"This phrase reminds readers that pain may appear as anger.","zh":"這個片語提醒讀者，痛苦可能以憤怒呈現。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"declining marks","meaning":"成績下滑","examples":[{"en":"Declining marks may show that a student is struggling.","zh":"成績下滑可能顯示學生正在掙扎。"},{"en":"Declining marks are scores that become lower over time.","zh":"declining marks 指分數隨時間下降。"},{"en":"A sudden fall in marks may reflect stress, poor sleep, or emotional pain.","zh":"分數突然下降可能反映壓力、睡眠差或情緒痛苦。"},{"en":"Teachers should ask what is happening instead of only punishing the result.","zh":"老師應詢問發生甚麼事，而不是只懲罰結果。"},{"en":"This phrase connects academic change with possible wellbeing concerns.","zh":"這個片語把學業變化與可能的身心健康問題連接起來。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"comments such as","meaning":"例如……的說話","examples":[{"en":"Students should notice comments such as “Nothing matters.”","zh":"學生應留意例如「一切都不重要」的說話。"},{"en":"Comments such as means remarks like the example given.","zh":"comments such as 意思是像所提供例子那樣的說話。"},{"en":"Comments such as “I’m useless” or “Nobody cares” should be taken seriously.","zh":"例如「我沒用」或「沒有人在乎」的說話應被認真看待。"},{"en":"This phrase introduces examples of worrying language.","zh":"這個片語引入令人擔心的語言例子。"},{"en":"It helps readers know what kind of words to listen for.","zh":"它幫助讀者知道要聆聽哪類說話。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"nothing matters","meaning":"一切都不重要","examples":[{"en":"A comment like “Nothing matters” should be taken seriously.","zh":"像「一切都不重要」這樣的說話應被認真看待。"},{"en":"Nothing matters means the person feels that nothing has value or meaning.","zh":"nothing matters 意思是那個人覺得沒有任何事有價值或意義。"},{"en":"If a student says “Nothing matters” repeatedly, friends should not laugh it off.","zh":"如果學生反覆說「一切都不重要」，朋友不應一笑置之。"},{"en":"Such words can suggest deep hopelessness and need adult support.","zh":"這些說話可能暗示深層絕望，需要成年人支援。"},{"en":"This phrase is a warning sign, not just a casual complaint.","zh":"這個片語是警號，而不只是隨口抱怨。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"speak gently and specifically","meaning":"溫和而具體地說","examples":[{"en":"Students should speak gently and specifically to a struggling friend.","zh":"學生應對正在掙扎的朋友溫和而具體地說話。"},{"en":"To speak gently and specifically means to use kind words and mention the exact change noticed.","zh":"speak gently and specifically 意思是用友善語氣，並提及你留意到的具體變化。"},{"en":"Instead of blaming a friend, say calmly what you have observed.","zh":"不要責怪朋友，而應冷靜說出你觀察到的事。"},{"en":"Specific words can sound more caring than vague advice.","zh":"具體說話可以比含糊建議更顯得關心。"},{"en":"This phrase teaches a practical way to start a hard conversation.","zh":"這個片語教人開始困難對話的實際方法。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"haven’t been yourself lately","meaning":"你最近不像平時的自己","examples":[{"en":"You can say, “I’ve noticed you haven’t been yourself lately.”","zh":"你可以說：「我留意到你最近不像平時的自己。」"},{"en":"Haven’t been yourself lately means you have seemed different from your usual self recently.","zh":"haven’t been yourself lately 意思是你最近看起來與平常的自己不同。"},{"en":"A friend may say this when someone becomes quiet, tired, or withdrawn.","zh":"當某人變得沉默、疲倦或退縮時，朋友可能這樣說。"},{"en":"This sentence is gentle because it points to change without accusation.","zh":"這句話溫和，因為它指出變化而不是指責。"},{"en":"It can help someone feel noticed rather than judged.","zh":"它可以幫助對方感到被留意，而不是被審判。"}],"source":"2012 Q9.pdf","sourcePage":11},{"front":"I’m here if you want to talk","meaning":"如果你想傾，我在這裏","examples":[{"en":"A friend can say, “I’m here if you want to talk.”","zh":"朋友可以說：「如果你想傾，我在這裏。」"},{"en":"I’m here if you want to talk means I am available to listen when you are ready.","zh":"I’m here if you want to talk 意思是當你準備好時，我願意聆聽。"},{"en":"This sentence offers support without forcing the person to speak immediately.","zh":"這句話提供支援，而不強迫對方立即開口。"},{"en":"It can make a struggling friend feel less alone.","zh":"它可以令正在掙扎的朋友感到不那麼孤單。"},{"en":"This phrase is simple, gentle, and useful in difficult moments.","zh":"這個片語簡單、溫和，適合困難時刻使用。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"that way","meaning":"這樣","examples":[{"en":"That way, you open a door without forcing them through it.","zh":"這樣，你打開一扇門，而不強迫他們走進去。"},{"en":"That way means by doing this or as a result of this method.","zh":"that way 意思是透過這樣做，或作為這種方法的結果。"},{"en":"Ask gently; that way, your friend may feel safe enough to respond.","zh":"溫和地詢問；這樣，你的朋友可能會感到安全而願意回應。"},{"en":"This phrase connects a caring action with its likely effect.","zh":"這個片語把關心行動與可能效果連接起來。"},{"en":"It helps explain why a gentle approach works.","zh":"它幫助解釋為何溫和方法有效。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"open a door","meaning":"打開一扇門；提供機會","examples":[{"en":"A gentle sentence can open a door.","zh":"一句溫和說話可以打開一扇門。"},{"en":"To open a door means to create a chance for conversation or support.","zh":"open a door 意思是創造對話或支援的機會。"},{"en":"Saying “I’m here” can open a door for a friend who is not ready to speak yet.","zh":"說「我在這裏」可以為尚未準備好說話的朋友打開一扇門。"},{"en":"Opening a door is different from forcing someone to talk.","zh":"打開一扇門不同於強迫某人說話。"},{"en":"This phrase shows how small words can create safe space.","zh":"這個片語顯示細小說話如何創造安全空間。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"without forcing them through it","meaning":"不強迫他們走進去","examples":[{"en":"You can open a door without forcing them through it.","zh":"你可以打開一扇門，而不強迫他們走進去。"},{"en":"Without forcing them through it means giving a choice without pressure.","zh":"without forcing them through it 意思是給予選擇而不施加壓力。"},{"en":"A friend can offer to listen without demanding an immediate answer.","zh":"朋友可以提出聆聽，而不要求即時回答。"},{"en":"This approach respects the person’s pace and dignity.","zh":"這種方式尊重對方的節奏和尊嚴。"},{"en":"The phrase teaches support that is gentle, not controlling.","zh":"這個片語教人提供溫和而不控制的支援。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"rushing to fix everything","meaning":"急着解決所有問題","examples":[{"en":"Listen without rushing to fix everything.","zh":"聆聽時不要急着解決所有問題。"},{"en":"Rushing to fix everything means trying too quickly to solve all problems at once.","zh":"rushing to fix everything 意思是太快嘗試一次過解決所有問題。"},{"en":"A friend may need listening before advice or solutions.","zh":"朋友可能需要先被聆聽，再需要建議或解決方案。"},{"en":"Rushing to fix everything can make the person feel unheard.","zh":"急着解決所有問題可能令對方覺得沒有被聽見。"},{"en":"This phrase reminds us that presence can be more helpful than quick answers.","zh":"這個片語提醒我們，陪伴可以比快速答案更有幫助。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"advice has its place","meaning":"建議有其作用","examples":[{"en":"Advice has its place, but listening may help more.","zh":"建議有其作用，但聆聽可能更有幫助。"},{"en":"Advice has its place means advice can be useful in the right situation.","zh":"advice has its place 意思是建議在適當情況下可以有用。"},{"en":"Advice has its place after the person feels heard and safe.","zh":"當對方感到被聆聽和安全後，建議才有其作用。"},{"en":"Giving advice too early may sound like a lecture.","zh":"太早給建議可能聽起來像訓話。"},{"en":"This phrase creates a balanced view of helping.","zh":"這個片語建立對幫助的平衡看法。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"a soft answer","meaning":"溫和的回應","examples":[{"en":"A soft answer often helps more than a clever lecture.","zh":"溫和的回應往往比聰明但說教式的訓話更有幫助。"},{"en":"A soft answer is a gentle, kind, and calm response.","zh":"soft answer 是溫柔、友善和平靜的回應。"},{"en":"A soft answer may be, “I’m sorry you’re going through this.”","zh":"溫和的回應可以是：「很抱歉你正在經歷這些。」"},{"en":"Such an answer can make a struggling person feel less judged.","zh":"這樣的回應可以令正在掙扎的人較少感到被審判。"},{"en":"This phrase values kindness over showing how clever you are.","zh":"這個片語重視善意，多於展示自己有多聰明。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"clever lecture","meaning":"聰明但說教式的訓話","examples":[{"en":"A soft answer may help more than a clever lecture.","zh":"溫和的回應可能比聰明但說教式的訓話更有幫助。"},{"en":"A clever lecture is advice that sounds intelligent but may feel cold or preachy.","zh":"clever lecture 是聽起來聰明但可能冷淡或說教的建議。"},{"en":"A friend in pain may not need a clever lecture about positive thinking.","zh":"痛苦中的朋友未必需要關於正面思考的聰明訓話。"},{"en":"Clever lectures can make people feel corrected rather than supported.","zh":"聰明但說教式的訓話可能令人覺得被糾正，而不是被支持。"},{"en":"This phrase warns against turning help into performance.","zh":"這個片語提醒人不要把幫助變成表演。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"turn depression into gossip","meaning":"把抑鬱症變成八卦","examples":[{"en":"Never turn depression into gossip.","zh":"絕不要把抑鬱症變成八卦。"},{"en":"To turn depression into gossip means to share someone’s mental health struggle as private talk for interest or entertainment.","zh":"turn depression into gossip 意思是把某人的精神健康掙扎當作私人閒話或娛樂來分享。"},{"en":"Telling classmates about a friend’s depression without care can become gossip.","zh":"不謹慎地告訴同學朋友患抑鬱症，可能變成八卦。"},{"en":"Gossip can break trust and make the person feel unsafe.","zh":"八卦會破壞信任，並令當事人感到不安全。"},{"en":"This phrase gives a clear warning about privacy and respect.","zh":"這個片語對私隱和尊重作出清晰提醒。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"trust is hard to build","meaning":"信任很難建立","examples":[{"en":"Trust is hard to build.","zh":"信任很難建立。"},{"en":"Trust is hard to build means people need time before they feel safe with someone.","zh":"trust is hard to build 意思是人們需要時間才會對某人感到安全。"},{"en":"A struggling friend may need many quiet conversations before trusting you.","zh":"正在掙扎的朋友可能需要許多安靜對話才會信任你。"},{"en":"Trust grows through patience, honesty, and respect for privacy.","zh":"信任透過耐性、誠實和尊重私隱慢慢建立。"},{"en":"This phrase explains why careless gossip is so damaging.","zh":"這個片語解釋為何粗心八卦如此有害。"}],"source":"2012 Q9.pdf","sourcePage":12},{"front":"painfully easy to break","meaning":"非常容易被破壞","examples":[{"en":"Trust is painfully easy to break.","zh":"信任非常容易被破壞。"},{"en":"Painfully easy to break means can be destroyed very quickly and hurtfully.","zh":"painfully easy to break 意思是可以非常快速且令人痛苦地被摧毀。"},{"en":"One careless message can make a friend feel betrayed.","zh":"一則粗心訊息可以令朋友感到被背叛。"},{"en":"Trust is painfully easy to break when private pain becomes public gossip.","zh":"當私人痛苦變成公開八卦時，信任非常容易被破壞。"},{"en":"This phrase stresses the need to handle sensitive information carefully.","zh":"這個片語強調謹慎處理敏感資料的需要。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, do not promise secrecy if someone may hurt himself or herself.","zh":"話雖如此，如果某人可能傷害自己，不要承諾保密。"},{"en":"That said means even though the previous point is true, another important point must be added.","zh":"that said 意思是即使前一點成立，也必須加入另一個重要重點。"},{"en":"Privacy matters; that said, safety must come first in danger.","zh":"私隱重要；話雖如此，在危險中安全必須優先。"},{"en":"This phrase helps balance confidentiality with protection.","zh":"這個片語幫助平衡保密和保護。"},{"en":"It introduces an important exception to keeping secrets.","zh":"它引入保守秘密的重要例外。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"hurt himself or herself","meaning":"傷害自己","examples":[{"en":"If someone may hurt himself or herself, seek adult help.","zh":"如果某人可能傷害自己，應尋求成年人幫助。"},{"en":"Hurt himself or herself means harm one’s own body or safety.","zh":"hurt himself or herself 意思是傷害自己的身體或安全。"},{"en":"If a friend says they may hurt themselves, do not handle it alone.","zh":"如果朋友說可能傷害自己，不要獨自處理。"},{"en":"Tell a trusted adult, counsellor, or emergency support as soon as possible.","zh":"應盡快告訴可信任成年人、輔導員或緊急支援人員。"},{"en":"This phrase signals an urgent safety concern.","zh":"這個片語表示迫切安全問題。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"promise secrecy","meaning":"承諾保密","examples":[{"en":"Do not promise secrecy if someone may be in danger.","zh":"如果某人可能有危險，不要承諾保密。"},{"en":"To promise secrecy means to say that you will not tell anyone else.","zh":"promise secrecy 意思是說自己不會告訴其他人。"},{"en":"Friends should not promise secrecy when safety is at risk.","zh":"當安全受威脅時，朋友不應承諾保密。"},{"en":"It is better to say, “I care about you too much to keep this only to myself.”","zh":"較好的說法是：「我太在乎你，所以不能只由我一個人知道。」"},{"en":"This phrase teaches that protection can be more important than secrecy.","zh":"這個片語教人保護可能比保密更重要。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"as soon as possible","meaning":"盡快","examples":[{"en":"Tell a trusted adult as soon as possible.","zh":"盡快告訴可信任成年人。"},{"en":"As soon as possible means without unnecessary delay.","zh":"as soon as possible 意思是不作不必要拖延。"},{"en":"If someone may be unsafe, speak to a teacher as soon as possible.","zh":"如果某人可能不安全，應盡快告訴老師。"},{"en":"Fast action can bring support before the situation worsens.","zh":"快速行動可以在情況惡化前帶來支援。"},{"en":"This phrase stresses urgency and responsibility.","zh":"這個片語強調迫切性和責任。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"the sooner…, the better","meaning":"越早……越好","examples":[{"en":"The sooner help arrives, the better.","zh":"幫助越早到來越好。"},{"en":"The sooner…, the better means earlier action leads to a better result.","zh":"the sooner…, the better 意思是越早行動，結果越好。"},{"en":"The sooner a student talks to a counsellor, the better the support can begin.","zh":"學生越早與輔導員交談，支援便越早開始。"},{"en":"The sooner warning signs are noticed, the better friends can respond.","zh":"警號越早被留意，朋友便越能作出回應。"},{"en":"This structure strongly encourages early action.","zh":"這個句式強烈鼓勵及早行動。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"keep inviting someone back into","meaning":"繼續邀請某人回到……","examples":[{"en":"Keep inviting the person back into ordinary life.","zh":"繼續邀請那個人回到日常生活。"},{"en":"To keep inviting someone back into something means to continue gently including them.","zh":"keep inviting someone back into something 意思是持續溫和地接納對方參與。"},{"en":"Friends can keep inviting a struggling student back into lunch, walks, and study groups.","zh":"朋友可以繼續邀請正在掙扎的學生回到午餐、散步和溫習小組中。"},{"en":"The invitation should be gentle, not pressuring or impatient.","zh":"邀請應溫和，而不是施壓或不耐煩。"},{"en":"This phrase shows that recovery may need repeated small welcome.","zh":"這個片語顯示康復可能需要反覆細小的歡迎。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"ordinary life","meaning":"日常生活","examples":[{"en":"Small invitations can bring someone back into ordinary life.","zh":"細小的邀請可以把某人帶回日常生活。"},{"en":"Ordinary life means normal daily activities such as eating, walking, studying, and talking.","zh":"ordinary life 指正常日常活動，例如吃飯、散步、學習和交談。"},{"en":"Depression can make ordinary life feel far away.","zh":"抑鬱症可以令日常生活感覺很遙遠。"},{"en":"A simple lunch can help someone reconnect with ordinary life.","zh":"一頓簡單午餐可以幫助某人重新連接日常生活。"},{"en":"This phrase shows that healing can happen through small daily moments.","zh":"這個片語顯示療癒可以透過細小日常時刻發生。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"a short walk","meaning":"一段短短的散步","examples":[{"en":"A short walk can be a small invitation back into life.","zh":"一段短短的散步可以是回到生活中的一個細小邀請。"},{"en":"A short walk means a brief, simple walk, often without heavy conversation.","zh":"a short walk 指短暫而簡單的散步，通常不需要沉重對話。"},{"en":"A friend may invite a struggling student for a short walk after school.","zh":"朋友可能放學後邀請正在掙扎的學生短短散步一會。"},{"en":"Walking together can feel easier than sitting face to face and talking.","zh":"一起走路可能比面對面坐着談話更容易。"},{"en":"This phrase gives a gentle example of companionship.","zh":"這個片語提供陪伴的溫和例子。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"library seat","meaning":"圖書館座位","examples":[{"en":"A library seat can make someone feel included.","zh":"一個圖書館座位可以令某人感到被接納。"},{"en":"A library seat means a place saved or offered for someone to sit and study.","zh":"library seat 指為某人保留或提供的讀書座位。"},{"en":"Keeping a library seat for a friend says, “You still belong with us.”","zh":"為朋友留一個圖書館座位等於說：「你仍然屬於我們。」"},{"en":"Small gestures like this can reduce isolation.","zh":"這樣的小舉動可以減少孤立感。"},{"en":"This phrase shows how inclusion can be quiet and practical.","zh":"這個片語顯示接納可以是安靜而實際的。"}],"source":"2012 Q9.pdf","sourcePage":13},{"front":"simple lunch","meaning":"簡單午餐","examples":[{"en":"A simple lunch can remind someone that they still belong.","zh":"一頓簡單午餐可以提醒某人他仍然屬於這裏。"},{"en":"A simple lunch means an ordinary meal shared without pressure.","zh":"simple lunch 指一頓沒有壓力的普通共餐。"},{"en":"Inviting a friend to a simple lunch can break a day of isolation.","zh":"邀請朋友吃一頓簡單午餐，可以打破一天的孤立。"},{"en":"The meal does not need to solve everything; it just says, “You are included.”","zh":"這頓飯不需要解決一切；它只是說：「你被包括在內。」"},{"en":"This phrase shows the emotional power of ordinary care.","zh":"這個片語顯示普通關心的情感力量。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"small invitations","meaning":"細小的邀請","examples":[{"en":"Small invitations remind people that they still belong.","zh":"細小的邀請提醒人們他們仍然屬於這裏。"},{"en":"Small invitations are gentle offers to join ordinary activities.","zh":"small invitations 是溫和邀請對方參與日常活動的舉動。"},{"en":"Asking someone to sit with you at lunch can be a small invitation.","zh":"請某人午飯時坐在你旁邊，可以是一個細小邀請。"},{"en":"Repeated small invitations may help a lonely student feel remembered.","zh":"反覆的細小邀請可能幫助孤單學生感到被記得。"},{"en":"This phrase shows that care does not always need grand gestures.","zh":"這個片語顯示關心不一定需要宏大行動。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"still belong","meaning":"仍然屬於這裏","examples":[{"en":"These invitations remind them that they still belong.","zh":"這些邀請提醒他們仍然屬於這裏。"},{"en":"Still belong means remain accepted, included, and connected to the group.","zh":"still belong 意思是仍被接納、包括和與群體相連。"},{"en":"A struggling student may need reminders that they still belong in the class.","zh":"正在掙扎的學生可能需要被提醒自己仍然屬於班級。"},{"en":"Feeling that one still belongs can reduce loneliness.","zh":"感到自己仍然屬於這裏，可以減少孤獨。"},{"en":"This phrase expresses the emotional purpose of small acts of care.","zh":"這個片語表達細小關心行動的情感目的。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"made him feel as if","meaning":"令他感覺好像","examples":[{"en":"Depression made Ethan feel as if he had nowhere to go.","zh":"抑鬱症令 Ethan 感覺好像無處可去。"},{"en":"Made him feel as if means caused him to experience something as though it were true.","zh":"made him feel as if 意思是令他感覺某事好像是真的。"},{"en":"Anxiety can make a student feel as if everyone is judging her.","zh":"焦慮可以令學生感覺好像所有人都在評判她。"},{"en":"Depression may make someone feel as if help is impossible, even when support exists.","zh":"抑鬱症可能令某人感覺好像求助不可能，即使支援其實存在。"},{"en":"This phrase shows how illness can change a person’s sense of reality.","zh":"這個片語顯示疾病如何改變一個人對現實的感覺。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"nowhere to go","meaning":"無處可去","examples":[{"en":"Ethan felt as if he had nowhere to go.","zh":"Ethan 感覺好像無處可去。"},{"en":"Nowhere to go means having no safe place, person, or option to turn to.","zh":"nowhere to go 意思是沒有安全地方、人物或選擇可以求助。"},{"en":"A student may feel nowhere to go if they fear parents, teachers, and friends will judge them.","zh":"如果學生害怕父母、老師和朋友都會批評自己，可能感到無處可去。"},{"en":"Schools should make sure students know where they can seek help.","zh":"學校應確保學生知道可以去哪裏求助。"},{"en":"This phrase expresses deep loneliness and helplessness.","zh":"這個片語表達深層孤單和無助。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"our job, as classmates","meaning":"作為同學，我們的責任","examples":[{"en":"Our job, as classmates, is to make sure no one is left alone.","zh":"作為同學，我們的責任是確保沒有人被留下獨自一人。"},{"en":"Our job, as classmates means our responsibility in the role of fellow students.","zh":"our job, as classmates 意思是我們作為同學這個角色中的責任。"},{"en":"As classmates, students can notice changes and include one another.","zh":"作為同學，學生可以留意變化並接納彼此。"},{"en":"This phrase gives ordinary students a clear role in supporting wellbeing.","zh":"這個片語給普通學生一個支援身心健康的清晰角色。"},{"en":"It does not make classmates doctors, but it reminds them to care.","zh":"它不是把同學變成醫生，而是提醒他們關心。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"make sure that","meaning":"確保","examples":[{"en":"Classmates should make sure that no one is left with nowhere to turn.","zh":"同學應確保沒有人求助無門。"},{"en":"Make sure that means take action to ensure something happens or does not happen.","zh":"make sure that 意思是採取行動確保某事發生或不發生。"},{"en":"Friends should make sure that a struggling student knows where to get help.","zh":"朋友應確保正在掙扎的學生知道哪裏可以求助。"},{"en":"Teachers make sure that support is available by giving clear contact points.","zh":"老師透過提供清晰聯絡點來確保支援可得。"},{"en":"This phrase expresses responsibility and prevention.","zh":"這個片語表達責任和預防。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"be left with nowhere to turn","meaning":"求助無門","examples":[{"en":"No student should be left with nowhere to turn.","zh":"沒有學生應該求助無門。"},{"en":"Be left with nowhere to turn means have no one or no place to ask for help.","zh":"be left with nowhere to turn 意思是沒有人或地方可以求助。"},{"en":"A student may feel left with nowhere to turn if adults dismiss their pain.","zh":"如果成年人忽視學生的痛苦，學生可能感到求助無門。"},{"en":"Schools can prevent this by making support services visible and approachable.","zh":"學校可透過令支援服務清晰可見和容易接觸來避免這情況。"},{"en":"This phrase shows the need for clear help networks.","zh":"這個片語顯示清晰求助網絡的需要。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"replace doctors or counsellors","meaning":"取代醫生或輔導員","examples":[{"en":"Classmates cannot replace doctors or counsellors.","zh":"同學不能取代醫生或輔導員。"},{"en":"To replace doctors or counsellors means to take the professional role of trained mental health support.","zh":"replace doctors or counsellors 意思是承擔受訓精神健康支援專業人士的角色。"},{"en":"Friends can listen, but they should not pretend to diagnose or treat depression.","zh":"朋友可以聆聽，但不應假裝診斷或治療抑鬱症。"},{"en":"Serious warning signs should be passed to trusted adults or professionals.","zh":"嚴重警號應交給可信任成年人或專業人士處理。"},{"en":"This phrase sets a healthy boundary for classmates.","zh":"這個片語為同學設定健康界線。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"notice, listen, include and speak up","meaning":"留意、聆聽、接納並發聲","examples":[{"en":"Students can notice, listen, include and speak up.","zh":"學生可以留意、聆聽、接納並發聲。"},{"en":"Notice, listen, include and speak up means pay attention, hear the person, welcome them, and seek help when needed.","zh":"notice, listen, include and speak up 意思是留心、聽對方說、歡迎對方加入，並在需要時求助。"},{"en":"A class can notice changes, listen kindly, include lonely students, and speak up about danger.","zh":"班級可以留意變化、善意聆聽、接納孤單學生，並在有危險時發聲。"},{"en":"These actions are simple but can make school safer.","zh":"這些行動簡單，但能令學校更安全。"},{"en":"This phrase gives students a practical four-step role.","zh":"這個片語給學生一個實際的四步角色。"}],"source":"2012 Q9.pdf","sourcePage":14},{"front":"speak up","meaning":"發聲；出聲求助","examples":[{"en":"Students should speak up when someone may be in danger.","zh":"當某人可能有危險時，學生應發聲。"},{"en":"To speak up means to say something clearly, especially when silence would be harmful.","zh":"speak up 意思是清楚說出來，尤其在沉默會造成傷害時。"},{"en":"A friend should speak up to a teacher if a classmate talks about hurting themselves.","zh":"如果同學談到傷害自己，朋友應向老師出聲求助。"},{"en":"Speaking up can feel uncomfortable, but it may protect someone’s safety.","zh":"發聲可能令人不舒服，但它可以保護某人的安全。"},{"en":"This phrase shows courage in seeking help.","zh":"這個片語顯示求助中的勇氣。"}],"source":"2012 Q9.pdf","sourcePage":15},{"front":"more than an article","meaning":"不只是一篇文章","examples":[{"en":"The mental health feature should be more than an article.","zh":"精神健康專題應不只是一篇文章。"},{"en":"More than an article means it should have a deeper purpose than just being read.","zh":"more than an article 意思是它應有比被閱讀更深的目的。"},{"en":"A school article on mental health should lead to care, discussion, and support.","zh":"一篇關於精神健康的校園文章應帶來關心、討論和支援。"},{"en":"If the feature changes how students treat one another, it becomes more than an article.","zh":"如果專題改變學生彼此對待的方式，它就不只是一篇文章。"},{"en":"This phrase calls for action beyond words.","zh":"這個片語呼籲文字以外的行動。"}],"source":"2012 Q9.pdf","sourcePage":15},{"front":"a promise","meaning":"一個承諾","examples":[{"en":"The feature should become a promise.","zh":"這個專題應成為一個承諾。"},{"en":"A promise is a serious commitment to do or protect something.","zh":"promise 是對做某事或保護某事作出的嚴肅承諾。"},{"en":"A school can make a promise that students’ pain will not be mocked.","zh":"學校可以作出一個承諾：學生的痛苦不會被嘲笑。"},{"en":"Turning an article into a promise means the message should guide behaviour.","zh":"把文章變成承諾，意思是訊息應指引行為。"},{"en":"This phrase gives the ending moral strength.","zh":"這個片語令結尾有道德力量。"}],"source":"2012 Q9.pdf","sourcePage":15},{"front":"will not be mocked, hidden or ignored","meaning":"不會被嘲笑、隱藏或忽視","examples":[{"en":"Pain will not be mocked, hidden or ignored.","zh":"痛苦不會被嘲笑、隱藏或忽視。"},{"en":"Will not be mocked, hidden or ignored means people’s suffering will be respected, spoken about, and taken seriously.","zh":"will not be mocked, hidden or ignored 意思是人們的痛苦會被尊重、被談論並被認真看待。"},{"en":"A caring school does not mock students for needing help.","zh":"有關懷的學校不會因學生需要幫助而嘲笑他們。"},{"en":"Pain should not be hidden because silence can delay support.","zh":"痛苦不應被隱藏，因為沉默可能延誤支援。"},{"en":"This phrase sets a clear standard for how the school community should respond.","zh":"這個片語為學校社群如何回應訂立清晰標準。"}],"source":"2012 Q9.pdf","sourcePage":15},{"front":"not on our watch","meaning":"在我們看顧下絕不會發生","examples":[{"en":"In this school, pain will not be ignored—not on our watch.","zh":"在這所學校，痛苦不會被忽視——在我們看顧下絕不會發生。"},{"en":"Not on our watch means we will not allow this to happen while we are responsible.","zh":"not on our watch 意思是當我們有責任時，我們不會容許這事發生。"},{"en":"A class may say, “No one will be left alone, not on our watch.”","zh":"一個班可以說：「沒有人會被留下獨自一人，在我們看顧下絕不會發生。」"},{"en":"This phrase expresses shared responsibility and protection.","zh":"這個片語表達共同責任和保護。"},{"en":"It gives the article a strong final call to care for one another.","zh":"它為文章帶來強而有力的最後呼籲，提醒大家彼此照顧。"}],"source":"2012 Q9.pdf","sourcePage":15}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2012_SEED);
